pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves further waste; penalize leftover proportionally
            let next_left = post_residual - next_item_size;
            score += next_left as f64 * 0.5;
            // small bonus that next item fits at all
            score -= 20.0;
        } else {
            // next item won't fit here; penalize small dead space more
            score += 30.0;
        }
    }

    // Penalize creating dead space below the minimum item size (assume >=1, use 10 as conservative)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin when it wastes residual elsewhere
    if bin_residual == bin_capacity {
        // base cost of new bin; lower if few bins open or stream near end
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 - 50.0 * (1.0 - progress) - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can host next item too, mild bonus
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are "dead" — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 25.0; // awkward narrow gap
    } else if post_residual > 60 {
        score -= 15.0; // large residual stays flexible
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual tightly matches the item (best-fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new one is cheaper.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / (1.0 + total_items as f64));
    score += pressure * 1.5;

    // Prefer bins below mean residual when many bins are open (balance load),
    // prefer high-residual bins when few bins are open.
    if open_bins_count > 4 {
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 10.0; // next item can't use this bin's remainder
        }
    }

    // New-bin candidate: only attractive when item is large relative to
    // capacity or current bins are all fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let base = bin_capacity as f64 - item_size as f64;
        if fragmentation < 0.35 || item_size > 70 {
            score -= 20.0;
        } else {
            score += base * 0.3 + 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect (tight) fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post residuals non-linearly.
        let pr = post_residual as f64;
        score -= 60.0 * (1.0 - pr / bin_capacity as f64).powi(3);

        // 2-step lookahead: if next item exactly fills the leftover, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Next item fits in the leftover: mild reward scaled by how well it fills.
            let fill = next_item_size as f64 / pr;
            score -= 150.0 * fill * fill;
        } else if next_item_size > 0 {
            // Next item would NOT fit in the leftover: penalize wasted space.
            score += 40.0 * (next_item_size as f64 - pr);
        }
    }

    // Reward when this bin is the last chance (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize bins whose residual deviates favorably from the mean (keep diverse residuals).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive if the item is large relative to capacity
    // (poor fit anywhere else) and many bins are already open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 350.0 - 300.0 * tightness * tightness;
        // More open bins -> slightly cheaper to open another.
        new_bin_score -= 5.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating.
        new_bin_score += 50.0 * (step_index as f64 / total_items.max(1) as f64);
        // If next item is huge, a fresh bin may serve it better.
        if next_item_size > 60 {
            new_bin_score -= 60.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly: post residual matches next item tightly
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
            if post_residual == next_item_size {
                score -= 40.0; // exact chain
            }
        } else {
            // dead space penalty scaled by how far next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.8;
        }
    }

    // Compare residual against mean residual: prefer using bins with below-average residual
    // (tighter bins) to keep loose bins flexible.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor if this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize creating small unusable gaps (< 10) unless exact fit
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Early in stream: be more conservative, prefer opening bins to build diversity
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive when few bins or late stream with poor fits
        let new_bin_bias = 30.0 - progress * 40.0 - (open_bins_count as f64) * 2.0;
        score += new_bin_bias;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can also chain
        }
    }

    // Slight preference for fuller bins as stream progresses
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64; // tiny gap = heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill, strongly reward
    }

    // Reward good fits: item occupying most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = post_residual - next_item_size;
        if lookahead_gap < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // Penalize if next item cannot use post_residual (dead space ahead)
    if next_item_size > post_residual && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, consolidate; when few, allow spreading
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residuals close to the mean (keeps residual distribution balanced)
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * mean_gap;

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized slightly by default; becomes attractive
        // only if it enables a near-perfect future pairing with next_item_size.
        let mut new_bin_score = 15.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && bin_capacity - next_item_size < 10 {
            new_bin_score -= 25.0;
        }
        if fill_ratio < 0.5 && fitting_bins_count > 0 {
            new_bin_score -= 10.0; // poor fits elsewhere -> new bin ok
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to how far off.
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins: slight penalty to encourage spreading / keeping good bins.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state coupling: prefer filling bins when mean residual is low (consolidation phase).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Time horizon: early in stream, slightly discourage opening new bins (keep bins tight);
    // late in stream, allow more freedom.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // New bin candidate: base cost plus scaling; cheaper to open early when few bins,
        // expensive late when many bins could still absorb the item.
        score = 30.0 + 20.0 * progress - 2.0 * open_bins_count as f64;
        // If item is large, new bin is more attractive since it leaves usable space.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        // If no lookahead fits anywhere meaningful, opening is fine.
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Mild preference for bins with larger residual when item is small (save tight bins).
    if item_size <= 30 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harshly (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: penalize leaving a gap that barely misses the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins tighter than average (good fits).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.3;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless -> heavy penalty.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 25.0; // only fits very small items
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Reward using bins with small residual relative to mean (consolidation).
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual is a dead sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 10 || post_residual == 0 {
            score -= 45.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Baseline: opening a new bin is moderately costly.
        score = 55.0 + open_bins_count as f64 * 0.5;
        // If the only alternative creates dead space, new bin becomes better.
        if fitting_bins_count <= 1 && post_residual <= 10 && item_size < bin_capacity {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1, but practically gaps < ~10 are near-dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward filling bins that are already fairly full (tight packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize creating a gap that just barely fails to fit the known next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, mild penalty
    // for leaving large residuals in mostly-empty bins (favor new-bin when fresh).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (1.0 - fill_ratio);
    score -= 10.0 * progress * fill_ratio;

    // Coupling with mean residual: if this bin's residual is far below the mean,
    // it is a good consolidation target.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // New-bin candidate baseline: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its residual equals capacity; make it
        // competitive but not dominant unless open bins would waste space badly.
        score = 55.0 + 0.5 * open_bins_count as f64 - 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can follow here. Reward tightness of the two-item chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 - chain_waste.min(50.0);
        } else {
            // Bad: dead space that next item cannot use
            let dead = (post_residual as f64) - (next_item_size as f64).min(post_residual as f64);
            score += dead * 0.5 + 20.0;
        }
    }

    // Relative to mean residual: prefer filling bins with above-average residual
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins early in the stream / when few bins open
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * -5.0;
    }

    // Progression: later in stream, be more aggressive about tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost useless.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Unusable sliver: heavy penalty scaled by how close to zero.
            score += (10.0 - gap) * 8.0;
        } else if gap <= 20.0 {
            // Small gap: hard to fill with future items (sizes >= 10).
            score += (20.0 - gap) * 2.0;
        }
    } else {
        // Perfect closure: strong reward.
        score -= 40.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids wasting residual elsewhere).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few -> allow.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 1.5;

    // Prefer bins below mean residual (consolidate emptiness into few bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly into post_residual, big reward;
    // if it can't fit at all, mild penalty (dead space relative to lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt as u32 == post_residual {
            score -= 50.0;
        } else if nxt <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate: only attractive when residuals of open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open/late stream.
        score += 30.0 - pressure * 0.5;
        // Attractive if this item is large relative to capacity (hard to place later).
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 20 && post_residual > 9 {
