    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a new bin is more attractive when few bins are open.
        score -= 1.2 * open_bins_count as f64;
        // If the item would leave a large awkward gap in existing bins, new bin looks better.
        if post_residual >= 30 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }

    // Slight preference for tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Early stream: be a bit more willing to open bins (exploration), later: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strongly reward.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Dead-space avoidance: residuals below the smallest plausible item (1..20)
        // are nearly unusable, so penalize them disproportionately.
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * 8.0; // steep penalty for tiny dead gaps
        } else if pr < 35.0 {
            score += (35.0 - pr) * 2.0; // moderate penalty for small gaps
        }
        // Reward residuals that can still host a typical future item.
        if pr >= next_item_size as f64 && next_item_size > 0 {
