    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new space.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use leftover; penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (consolidating fullness) when many bins are open.
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0);
    }

    // New-bin candidate: only attractive when open bins are nearly exhausted
    // or current residual is a poor fit for the item.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let scarcity = (open_bins_count as f64) / (1.0 + fitting_bins_count as f64);
        score = 70.0 + poor_fit * 0.1 - 20.0 * scarcity;
        if fitting_bins_count == 0 {
            score = -100.0; // no open bin fits: must open new bin
        }
    }

    // Slight late-stream conservatism: tighten packing as stream progresses.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
