    // Late-stream tightening: as the stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual anchoring: prefer bins whose residual is below average
    // (fills the fullest bins first, keeping large gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

