}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 12.0 * pr_norm * pr_norm * (1.0 + progress)
        - 8.0 * pr_norm * progress * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 10.0 * (nx - pr) * (0.5 + progress);
        } else {
            score -= 4.0 * (pr - nx).min(30.0) as f64 / 30.0;
