    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild preference for bins tighter than the mean residual
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: keep neutral-ish baseline, slightly discourage early on
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 5.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
