    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the incoming item.
        score += 10.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open; prefer new bin when few.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: baseline score so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.3;
