    // Prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // Global pressure: as mean residual shrinks, waste matters more.
    score += (cap - mean_residual) / cap * 5.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score = cap + 12.0;
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is the only option.
            score -= 200.0;
        } else {
            // Only open a new bin if the next item is large relative to
            // typical residuals and we're late in the stream.
            if next_item_size as f64 > mean_residual {
                score -= 15.0 * (0.5 + progress);
            }
            // Early in the stream, exploring a fresh bin is cheaper.
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

