    }

    // Open-bins pressure: discourage spreading across many bins unless fit is tight.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += 6.0 * open_pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is attractive only if the current
    // fit is bad (large dead space) or no open bin fits well.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual <= 10 { 60.0 * (11.0 - post_residual as f64) } else { 0.0 };
        if dead_space_penalty >= 40.0 || fitting_bins_count == 0 {
            score -= 55.0; // open a new bin rather than create dead space
        } else {
