        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many bins are open already, discourage spreading further
        score += 1.5 * open_bins_count as f64;
    }

    // Mild preference for bins whose residual deviates favorably from mean
    // (filling below-average-residual bins keeps a spread of large gaps).
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            // dead space that even the next item can't use
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is only attractive when no
    // existing bin fits well, or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win by default.
        score += 45.0;
        // Large items: opening a fresh bin is cheap and useful.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If this bin is the last chance, opening a new bin is safe.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Many open bins with large mean residual: avoid spreading.
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 25.0;
        }
    } else {
        // Pressure from number of open bins: prefer consolidating into
        // existing bins rather than proliferating.
        score += open_bins_count as f64 * 0.5;
        // Last-chance bin: strongly favor using it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Reward tight fits relative to the mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: strongly reward exact / near-exact
    // matches between post_residual and next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: big reward.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Smooth decay: closeness of post_residual to next item is rewarded.
            score -= 40.0 * (-diff / 20.0).exp();
        }
        // If next item cannot fit anywhere after this placement (post_residual
        // too small but nonzero), penalize creating tiny dead space.
        if post_residual > 0 && (post_residual as i64 - next_item_size as i64) < 0 {
            score += 15.0;
        }
    }

    // Penalize residual far below the mean residual of open bins
    // (creating disproportionately small leftover space).
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score += 0.6 * (mean_residual - resid_f);
    } else {
        score -= 0.2 * (resid_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in stream: encourage tighter packing to build good bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate should only win when it is genuinely attractive:
    // penalize opening a new bin slightly, more when many bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, tighten packing more aggressively.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small residuals, but only if they're big enough to be useful later
    // (or the stream is nearly done, where dead space costs little).
    let tiny_threshold = 10u32;
    if post_residual > 0 && post_residual < tiny_threshold {
        // Dead space penalty, softened near the end of the stream.
        score += (tiny_threshold as f64 - post_residual as f64) * (3.0 - 1.5 * progress);
    }

    // Lookahead coupling: a residual that exactly fits the next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Reward leaving room for the next item, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting the lookahead option.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Fragmentation guard: penalize bins whose post-residual is awkwardly mid-range
    // (too big to ignore, too small to fit typical items) more as stream progresses.
    let mid_lo = 20.0f64;
    let mid_hi = 45.0f64;
    let pr = post_residual as f64;
    if pr > mid_lo && pr < mid_hi {
        let depth = 1.0 - ((pr - (mid_lo + mid_hi) / 2.0).abs() / ((mid_hi - mid_lo) / 2.0));
        score += 35.0 * depth * (0.5 + progress);
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base score is post_residual = capacity; add pressure
        // that grows with open bins count and their average slack.
        score += open_bins_count as f64 * 15.0 + mean_residual * 0.8;
        // Early in the stream a fresh bin is cheap; later it's expensive.
        score += 50.0 * progress;
    } else {
        // Existing bin: reward choosing it when the fleet is crowded.
        score -= (open_bins_count as f64).ln().max(0.0) * 10.0;
        // Slight preference for bins below mean residual (balancing slack).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = post * (1.0 + 1.5 * pr * pr);

    // Smooth stream-progress coupling: later in stream, penalize large residuals more
    score += 20.0 * progress * pr * pr * cap * 0.1;

    // Penalize near-empty fills that waste a mostly full bin (dead space coupling)
    score += 8.0 * (pr - 0.5) * (pr - 0.5) * (1.0 - progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    let next = next_item_size as f64;
    if next > 0.0 {
        let fits_next = if post >= next { 1.0 } else { 0.0 };
        let gap = (post - next).abs() / cap;
        score -= 10.0 * fits_next * (1.0 - gap) * (1.0 - gap);
        score += 6.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    score += 2.0 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "unusable" residue classes (too small to ever host a typical item).
    let pr = post_residual;
    let small_dead = if pr > 0 && pr < 10 { 1.0 } else { 0.0 };
    score += small_dead * 60.0;

    // Integer-division thresholds: residual in [10, 30] can host small items,
    // residual in [31, 50] hosts mid items; reward accordingly.
    if pr >= 10 && pr <= 30 {
        score -= 15.0;
    } else if pr > 30 && pr <= 50 {
        score -= 8.0;
    } else if pr > 50 {
        score -= 4.0;
    }

    // Modulo arithmetic on capacity fractions: post_residual congruent to
    // small residues mod 10 suggests awkward fragmentation.
    let m = (pr % 10) as f64;
    score += m * 0.8;

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 20.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 {
        // next item cannot fit here; mild penalty scaled by how close we are.
        score += (next_item_size as f64 - pr as f64) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity equal to
    // the residual of all open bins; penalize proportionally to open bins count
    // and mean residual, so we prefer reusing when reasonable.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.2;
        // But early in the stream, opening bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 30.0;
    }

    // Tightness bonus: prefer bins that will be filled tightly relative to capacity.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Mean residual deviation: prefer bins close to the mean residual to keep
    // the bin population homogeneous.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual gaps that no future item (min size 1..~15) can use
    // are pure waste. Penalize small-but-nonzero post_residuals harshly.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 6.0;
    }
    // Mid-range gaps (15..40) are partially usable; mild penalty.
    if post_residual >= 15 && post_residual < 40 {
        score += (40 - post_residual) as f64 * 0.35;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // disfavor spreading. Also makes new bins less attractive.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: baseline cost plus pressure; only attractive when
    // existing fits are terrible (large dead space) or no bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly into this bin's post_residual,
    // reward placing current item here (creates a perfect slot).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is just below the next item (unusable for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Tightness bonus: reward small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 - tightness.min(1.0)) * 10.0;

    // Late in stream: waste matters more, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as f64 - nx).abs();
        // Perfect 2-step fit: post_residual == next_item_size -> strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize mismatch, scaled by how far off the pairing is.
            score += 0.35 * diff;
            // If next item cannot fit in the leftover, this is a dead pairing.
            if post_residual < next_item_size {
                score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
            }
        }
        // If next item fits exactly in current residual (item then next fills bin fully):
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.5 * post_residual as f64;
    }

    // Dead space penalty: small post_residual that is nonzero (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.30 * (mean_residual - post_residual as f64);

    // Mild penalty when many bins are open (consolidation pressure).
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: penalize unless current bin is a poor fit
    // (i.e., opening fresh is better than wasting a nearly-full bin).
    if bin_residual == bin_capacity {
        // Baseline new-bin score ~ capacity; good fits elsewhere will beat it.
        score = bin_capacity as f64 + 5.0;
        // Allow new bin early in stream or when no bin fits well.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if progress < 0.15 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on small residuals (wasted capacity).
        let pr = post_residual as f64;
        score += (bin_capacity as f64 / pr).max(0.0) * 0.5;
        if pr <= 10.0 {
            score -= 50.0; // tiny residual is nearly a perfect fit
        }
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack_fit = post_residual - next_item_size;
        score -= slack_fit as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Penalize creating a residual too small for the known next item.
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Time horizon: early in the stream, be more conservative (favor tight packing);
    // late in the stream, just use open bins to avoid new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Global state: many open bins -> discourage new bins implicitly via mean residual alignment.
    if bin_residual as f64 >= mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or no good fit exists; penalize moderately so open bins win on decent fits.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post_residual warped by stream progress
    let warp = 1.0 + 0.8 * t * (1.0 - t) * 4.0; // peaks mid-stream
    score *= warp;

    // Polynomial interaction between normalized post_residual and progress
    score += 12.0 * norm_pr * norm_pr * (1.0 + t) - 6.0 * norm_pr * t;

    // Penalize dead space relative to mean residual (smooth cubic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * dev / cap;

    // Lookahead: reward post_residual that still fits next item (smooth)
    if next_item_size > 0 {
        let fits = (next_item_size as f64 - pr).max(0.0);
        score += 0.3 * fits;
        let exact = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= 10.0 * exact.max(0.0) * exact * t;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: prefer it only when existing fit is terrible
    if bin_residual == bin_capacity {
        score -= 8.0;
        score += 20.0 * (1.0 - norm_pr.min(1.0)); // empty bin has max residual; neutralize warp
        score += 15.0 * (item_size as f64 / cap);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0 * (1.0 - (next_item_size as f64 / cap));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // sizes (or small residues) are "usable" dead space; mid-range residues
    // are dead weight and must be penalized.
    let pr = post_residual;
    let harmonic_usable = (pr <= 8)
        || (pr % 10 == 0)
        || (pr % 20 == 0)
        || (pr % 25 == 0)
        || (pr % 50 == 0);
    if harmonic_usable {
        score -= 12.0;
    } else {
        score += 10.0 + 0.25 * (pr as f64);
    }

    // Perfect fit: extremely rewarded.
    if pr == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // Harmonic class of the slack after the lookahead item.
            if slack <= 8 || slack % 10 == 0 || slack % 25 == 0 {
                score -= 25.0;
            } else {
                score += 0.3 * (slack as f64);
            }
        } else {
            // Next item cannot follow here; slight penalty for wasting the
            // residual on a non-chainable placement.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize moderately so it only wins when all
    // open bins fit badly; but reward it when item is large (large items
    // belong in fresh bins).
    if bin_residual == bin_capacity {
        score += 55.0 - 0.5 * (item_size as f64);
    }

    // Many open bins with large mean residual: discourage spreading, prefer
    // tight fills (low post_residual already does this, add coupling).
    if open_bins_count > 4 && (post_residual as f64) > mean_residual {
        score += 8.0;
    }

    // Early in the stream, allow more bin creation freedom.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // Integer-division threshold: post_residual in (0,10) is near-perfect.
    if pr > 0 && pr / 10 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item can use are heavily penalized.
    // Minimum plausible item size is 1, but small gaps (< ~30) are statistically hard to fill.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 2.5; // steep penalty for near-dead gaps
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward gaps that exactly or nearly fit the known next item (lookahead coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0; // next item fills this bin exactly: excellent chaining
        } else if slack < 20 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for the next item: dead space risk
        score += 12.0;
    }

    // Tightness of current fit: prefer bins where the item fills a large fraction of the residual
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor consolidation into existing bins
    let open_pressure = open_bins_count as f64 * 0.6;
    // New-bin candidate: residual == capacity. Allow opening a new bin only when the item is large
    // relative to mean residual or when this bin is the last chance but fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bins mildly, more so when many bins are open and mean residual is large
        score += 8.0 + open_pressure + (mean_residual / bin_capacity as f64) * 6.0;
        // But if the item is big and would leave a large post_residual in existing bins anyway,
        // opening fresh can be fine: soften penalty for large items
        if item_size >= 60 {
            score -= 6.0;
        }
        // If no other bin fits well (last chance), opening is acceptable
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward when it is the last fitting bin (avoid opening new bins)
        if fitting_bins_count == 1 {
            score -= 7.0;
        }
        // Mild consolidation reward scaled by open bins
        score -= open_pressure * 0.25;
    }

    // Late in the stream, waste matters more (less time to fill leftover gaps)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item fits exactly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(30.0) as f64;
        // Perfect 2-item fill: bin becomes exactly full after next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize small dead space more than large.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // tiny unusable fragment
        }
    }

    // Penalize creating residual far below the mean residual (fragmenting a healthy bin).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.1 * dev; // slight reward for keeping residual above mean
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists; penalize opening early.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * mean_residual;
        if fitting_bins_count > 0 {
            score += 30.0; // discourage new bin when alternatives exist
        }
    }

    // Late in stream: prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;

    let mut score = post;

    // Reward tight fits: bigger items in this bin => lower score.
    score -= (item / cap) * 25.0;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post > 0.0 && post < 10.0 {
        score += 18.0;
    }
    // Also penalize large leftover that nothing typical will use later.
    if post > 0.0 && post < item * 0.25 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 14.0 * (nxt / cap);
        } else {
            // waste proportional to how much the next item overshoots
            score += ((nxt - post) / cap).min(0.5) * 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to discriminate among many candidates via post residual
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // Global pressure: as mean residual shrinks, waste matters more.
    score += (cap - mean_residual) / cap * 5.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score = cap + 12.0;
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is the only option.
            score -= 200.0;
        } else {
            // Only open a new bin if the next item is large relative to
            // typical residuals and we're late in the stream.
            if next_item_size as f64 > mean_residual {
                score -= 15.0 * (0.5 + progress);
            }
            // Early in the stream, exploring a fresh bin is cheaper.
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 1.0 + 0.6 * t - 1.2 * t * t + 0.8 * t * t * t;
    score += 0.35 * pr * poly;

    // Tight fit reward: quadratic in post_residual normalized by capacity.
    let pr_norm = pr / cap;
    score -= 18.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (item_size as f64 / cap);

    // Penalize dead space relative to next item: smooth mismatch term.
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = (pr - ni).abs();
        score += 0.12 * gap * (1.0 + t);
        if pr >= ni {
            score -= 6.0 * (ni / cap);
        }
    }

    // Last-chance bonus: smooth sigmoid-like on fitting_bins_count.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - t * 0.5);
    }

    // Mild penalty when bin deviates from mean residual (fragmentation spread).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Prefer consolidating into fewer bins early; smooth in open_bins_count.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals that are multiples of small
    // divisors of capacity are more reusable by future items.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        0.0
    } else if pr % 50 == 0 {
        6.0
    } else if pr % 25 == 0 {
        4.0
    } else if pr % 20 == 0 {
        3.5
    } else if pr % 10 == 0 {
        3.0
    } else if pr % 5 == 0 {
        1.5
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize small dead space: residuals in (0, 10) are nearly unusable
    // for typical items; make them very unattractive.
    if pr > 0 && pr < 10 {
        score += 40.0 + (10 - pr) as f64 * 2.0;
    } else if pr > 0 && pr < 20 {
        score += 10.0;
    }

    // Coupling with lookahead: reward leaving a residual that the next item
    // exactly fits; penalize leaving residual just below next item size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr as f64 - ni).abs() < 0.5 {
            score -= 60.0;
        } else if (pr as u32) >= next_item_size {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual at all
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when the fit into
    // an existing bin is poor. Penalize the fresh empty bin mildly, more so
    // when many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let consolidation = (open_bins_count as f64).ln().max(1.0);
        score += 30.0 + 8.0 * consolidation + 20.0 * progress;
        // But if item is large and would leave tiny residual in any bin,
        // a new bin is fine; reduce penalty for big items.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 25.0;
        }
    }

    // Prefer bins below mean residual (keeps residuals balanced).
    let prf = post_residual as f64;
    if prf > mean_residual {
        score += (prf - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - prf) * 0.2;
    }

    // Mild reward for high fill ratio.
    score -= (item_size as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as u32 >= next_item_size {
            // next item fits perfectly after this placement
            if diff < 1.0 {
                score -= 500.0;
            } else {
                score -= 200.0 * (1.0 - diff / 100.0);
            }
        } else {
            // next item won't fit: penalize wasted capacity unless post_residual tiny
            score += 0.5 * diff;
            if post_residual < 10 {
                score -= 50.0; // near-full bin is fine anyway
            }
        }
    }

    // Relative to mean residual: prefer bins more filled than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 50.0;
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 100.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward placements whose leftover exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // leftover can host next item: mild reward scaled by snugness
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space relative to its size
            score += 0.5 * post_residual as f64 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Penalize small-but-nonzero dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // (poor fit elsewhere) or late in stream; otherwise push it up.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 90.0 * fill;
        score += 30.0 * t;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // stacking large items together in a fresh bin is fine
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Mild pressure toward consolidating into bins with lower residual when many bins open.
    score -= 0.05 * mean_residual * (1.0 - t);

    // Prefer bins with tighter current fit.
    score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post_residual), with polynomial shaping
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress));

    // Non-linear penalty for dead space that is too small to be useful later:
    // penalize residuals in a "wasted" band via smooth bump: norm_pr^2 * (1-norm_pr)^2 style
    let bump = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * 4.0;
    score += 12.0 * bump * (1.0 + progress);

    // Reward filling bins deeply (quadratic in item_size fraction)
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * fill * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Encourage spreading when many bins are open; encourage consolidation when few
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;
    score -= 0.2 * (mean_residual / cap - norm_pr).abs();

    // Lookahead coupling: reward residual that can still fit the next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits = (norm_pr * cap >= n) as i32 as f64;
        let margin = (pr - n).max(0.0) / cap;
        score -= 5.0 * fits * (0.5 + margin) * (1.0 - progress);
        // penalize leaving residual just barely below next item (dead space)
        let miss = (n - pr).max(0.0) / cap;
        score += 8.0 * miss * (1.0 - miss) * 4.0 * (1.0 - progress);
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress - 0.5 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 5 harmonic bands.
    let band = (post_residual * 5) / bin_capacity; // 0..=4
    let band_bonus = [30.0, 22.0, 12.0, 4.0, 0.0][band as usize];
    score -= band_bonus;

    // Modulo-10 residue classes: tiny residues (<10) are dead space; reward exact small classes.
    let r = post_residual % 10;
    if r == 0 {
        score -= 25.0; // perfectly divisible residual, likely reusable
    } else if r >= 5 {
        score -= 6.0;
    } else {
        score += 8.0; // residues 1..4 are near-dead space
    }

    // Integer-division thresholds on post_residual: can it host next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            // harmonic pairing: post_residual % next_item_size small => chained fit
            let chain = post_residual % next_item_size;
            score -= (10 - (chain as f64 / 10.0).max(0.0)).max(0.0);
        } else {
            score += 15.0; // next item cannot chain here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize wasting a nearly-full bin's residual on tiny fill.
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        score += 12.0 + mean_residual * 0.15 + crowd * 0.8 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open new bin
        }
    }

    // Mild pressure to close bins: prefer bins with residual below mean.
    score += (mean_residual - bin_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps are unusable.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly favored
    }

    // Reward tight fits (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements into crowded sets of open bins
    // unless the fit is good; encourage consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Lookahead: if next item would fit exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 5.0; // next item can't use this gap: mild penalty
        }
    }

    // New-bin candidate handling: empty bin gets a moderate default score;
    // only beat it when existing-bin fits are genuinely good.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward if the NEXT item can fit into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain placement possible: reward proportionally to tightness of chain.
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 50.0 - chain_tightness.min(50.0);
        } else {
            // Dead space relative to next item: penalize unusable leftover.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize leaving residuals below the minimum item size (unusable forever).
    if post_residual > 0 && post_residual < 1 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins that are tighter than average
    // (large residuals are better used by big future items).
    if (post_residual as f64) > mean_residual {
        score += 0.3 * ((post_residual as f64) - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: make it unattractive unless it enables a perfect
    // two-item chain (item + next item fill it exactly).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 300.0; // opening a fresh bin for an exact 2-item chain is great
        } else {
            score += 25.0;
        }
    }

    // Mild preference for using existing bins when many are open (avoid bin sprawl).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio * fit_ratio);

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size + item_size {
            // keeping this bin for the next item may be better; slight penalty
            score += 4.0;
        }
    }

    // Global state: when many bins are open, prefer consolidating into existing bins.
    let open_f = open_bins_count as f64;
    score += open_f * 0.6 * fit_ratio;

    // Mean residual coupling: if this bin's residual is far below mean, it is an outlier;
    // filling outliers reduces fragmentation.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res_f - mean_residual) / mean_residual;
        if dev < 0.0 {
            score -= 8.0 * (-dev).min(2.0);
        } else {
            score += 3.0 * dev.min(2.0);
        }
    }

    // Time horizon: early in the stream, be pickier (penalize mediocre fits);
    // late in the stream, just fill anything available.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * fit_ratio;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { fit_ratio };
        score += 18.0 * desperation + open_f * 0.3;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin is good if a big item follows
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild penalty on residual; late stream: stronger preference
    // for tight fits (small post_residual), so polynomial term grows with progress.
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * norm_post * norm_post * (3.0 * progress);
    score += poly * cap;

    // Reward filling bins well: subtract a smooth function of item_size and progress.
    let fill = (item_size as f64 / cap) * (1.0 + progress);
    score -= fill * 20.0;

    // Last-chance bin: strong reward, smoothly scaled by progress.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize if next item fits poorly in post residual (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // good lookahead fit: reward when pr - nxt is small
            let look_gap = (pr - nxt) / cap;
            score -= (1.0 - look_gap) * (5.0 + 5.0 * progress);
        } else {
            // next item won't fit: penalize large post residual
            score += (nxt - pr) / cap * (8.0 + 8.0 * progress);
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    // with a smooth quadratic interaction term.
    let diff = mean_residual - pr;
    score += 0.1 * diff * diff * (0.5 + progress) - 0.2 * diff * (1.0 + progress);

    // Slight penalty for opening new bins early, relaxing over the stream.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins partitioned into capacity-fraction classes.
    let q = bin_capacity / 4; // 25
    let half = bin_capacity / 2;

    // Penalize dead space by harmonic class: residual < q is nearly unusable.
    if post_residual > 0 && post_residual < q {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure is ideal
    }

    // Reward residuals in the "sweet spot" classes: multiples of half / quarter bands.
    if post_residual == half {
        score -= 10.0;
    } else if post_residual % q == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: how many next-size items could still fit?
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        let k = (post_residual / next_item_size.max(1)) as f64;
        if fits_next {
            score -= 4.0 + 2.0 * k.min(3.0);
        } else {
            // next item cannot use this residual: penalize proportionally to wasted class
            let wasted_frac = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * wasted_frac;
        }
        // Modulo coupling: if next item exactly fills post_residual, strong reward
        if next_item_size == post_residual && post_residual > 0 {
            score -= 25.0;
        }
        // Harmonic pair: post_residual and next_item_size share a common divisor class
        if post_residual > 0 && next_item_size > 0
            && (post_residual % next_item_size == 0 || next_item_size % post_residual.min(next_item_size) == 0) {
            score -= 3.0;
        }
    } else {
        // Last item: strongly prefer closing bins exactly
        score -= 40.0 * (post_residual == 0) as u8 as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual / bin_capacity as f64;
        // Open a new bin when open bins are fragmented and item is large.
        if item_size > half && tight < 0.35 {
            score -= 20.0 * (1.0 - progress);
        } else {
            score += 12.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual that cannot hold even the smallest plausible item (<= ~10) is "dead".
    if post_residual < 10 {
        score += 60.0; // dead space penalty on top of the already-small post_residual
    } else if post_residual <= 20 {
        // Gap too small for most items: quasi-dead space, graded penalty
        score += (20 - post_residual) as f64 * 2.5;
    } else if post_residual >= 50 {
        // Large leftover keeps flexibility; reward proportional to usable space
        score -= 8.0 + (post_residual - 50) as f64 * 0.3;
    }

    // Reward tight fits: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain fit
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0; // next item nearly fills the gap
        } else if next_item_size > post_residual {
            // Next item won't fit here; this bin becomes dead after placement
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading out; penalize candidates that look like a new-bin temptation.
    let open_pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0) / 50.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded or fit is bad.
        // Base penalty makes opening a new bin the last resort.
        score += 30.0 + open_pressure * 4.0;
        // If no existing bin fits (this is the only candidate), the penalty above is
        // shared by all-new-bin comparisons; soften when stream is early.
        if step_index == 0 {
            score -= 30.0;
        }
        // If next item is large and current item is small, opening a fresh bin may be wise.
        if next_item_size > 60 && item_size < 30 {
            score -= 18.0;
        }
    } else {
        // Existing bin: mild reward for keeping bin count low
        score -= open_pressure * 0.5;
        // Prefer bins whose residual is close to the mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Progress coupling: late in the stream, be more conservative about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += progress * 20.0; // dead space hurts more when few placements remain to fix it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: strongly reward bins where the next item fits exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 10.0 * (overshoot / (bin_capacity as f64));
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean (consolidating space).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * tightness;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 45.0 - 45.0 * desperation;
        // Slightly cheaper to open new bin late in the stream if item is large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: heavily favor small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Exact / near-exact fits are gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 5 {
        score -= 40.0;
    } else if post_residual < 15 {
        score -= 12.0;
    }

    // Penalize dead space that nothing useful can fill (dead zone below min item 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits into this bin's post-residual, reward;
    // if next item would fit better elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0 + 0.5 * (next_item_size as f64);
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 4.0; // near-miss creates awkward pairing
        }
        // If next item exactly consumes post-residual, big reward.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins unless the fit there is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large relative to mean residual, opening fresh is fine.
        if item_size as f64 > mean_residual + 10.0 {
            score -= 22.0;
        }
        // Late in the stream, opening new bins is less costly than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If many bins are open and none fit well, new bin is attractive.
        if open_bins_count > 8 {
            score -= 5.0;
        }
    }

    // Prefer filling bins that are already relatively full (residual below mean).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild congestion penalty: too many open bins -> favor consolidation.
    if open_bins_count > 10 {
        score += 0.3 * (open_bins_count as f64 - 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual
    let x = pr / cap;

    // Smooth polynomial in progress: t^2 - t is minimal at t=0.5, peaks at edges
    let t = progress;
    let poly = 4.0 * t * t - 4.0 * t + 1.0; // in [0,1], min at mid-stream

    // Base: prefer tight fits (low post_residual), more so early and late in stream
    let mut score = pr * (1.0 + 0.8 * poly);

    // Non-linear coupling: residual^2 scaled by progress encourages tight packing as stream matures
    score += 0.6 * x * x * cap * t;

    // Penalize dead space relative to next item: wasted residual that next item could use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // residual could fit next item -> mild reward for leaving useful space
            score -= 0.35 * nx * (1.0 - t);
        } else {
            // dead space unusable by next item -> penalize, stronger late in stream
            score += 0.5 * (nx - pr) * (0.5 + 0.5 * t);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score += 12.0 + 3.0 * crowd * (1.0 - poly);
    }

    // Reward filling bins near capacity (smooth saturating term)
    score -= 10.0 * (1.0 - (-4.0 * (1.0 - x)).exp());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as u32; // 0..3 harmonic classes of wasted space
    score += class as f64 * 6.0;

    // Perfect / near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Harmonic pairing: if next item fits exactly (or near) into post_residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // dead space that next item cannot use: penalize by leftover gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Integer-division threshold: post_residual that is a multiple of common small sizes is reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * (step_index as f64 / (total_items.max(1) as f64));
        if item_size > 60 {
            score -= 25.0; // big items better in fresh bins
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never accommodate
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 5.0;
    }

    // If lookahead item fits into the post residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Penalize leaving a gap just below the next item size (near-miss dead space).
    if next_item_size > 0 && post_residual >= 1 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open bins pressure: with many open bins, prefer packing into existing ones.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: if this bin is much tighter than average, it is
    // a good filler; if it leaves more than the mean, penalize mildly.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate: neutral-ish baseline, but discouraged when decent
    // fits exist (fitting_bins_count > 1) or when open bins are few.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: opening a new bin is fine
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // big item coming, fresh bin useful
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward near matches: small gap between post_residual and next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + gap);
    }

    // Penalize creating small dead space (< next item) that likely becomes waste.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Penalize very small unusable residuals harder as stream progresses.
    if post_residual > 0 && post_residual < 10 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 50.0 + 100.0 * progress;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current bin would leave large waste
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 150.0 };
        score += 50.0 + waste_penalty;
        if fitting_bins_count > 1 {
            score += 100.0;
        }
    }

    // Slight preference for fuller bins overall.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Dead space the next item cannot use — penalize proportionally.
            let unusable = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.25 * unusable;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Progress-scaled exploration: early on, be greedy on tight fits;
    // later, prefer filling bins with large residuals to close them out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_gain = (item_size as f64) / (bin_capacity as f64);
    score -= progress * 3.0 * fill_gain;

    // Prefer bins deviating from mean residual (diversify residual sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        let scarcity = if next_item_size > 0 && next_item_size >= bin_capacity { 0.0 } else { 1.0 };
        score += 8.0 * scarcity + 0.6 * open_bins_count as f64;
        // But allow a new bin if this item would leave bad dead space everywhere.
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // Small bonus for exact or near-exact fills.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate larger residuals (open bins freely).
    // Later: penalize residual quadratically to force tight packing.
    let pr_norm = pr / cap;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 30.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 12.0 * pr_norm * (1.0 - progress) * (1.0 - progress);

    // Reward filling bins nearly exactly (post_residual near zero), stronger late in stream.
    let tight = 1.0 - pr_norm;
    score -= 15.0 * tight * tight * tight * (0.3 + prog2);

    // Dead-space penalty: residuals too small for the smallest plausible next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            // residual unusable by lookahead -> penalty scaled by how close we were to fitting
            score += 8.0 * (1.0 - pr / ni) * (0.4 + progress);
        } else {
            // residual can host lookahead: reward proportional to snugness
            let snug = 1.0 - (pr - ni) / cap;
            score -= 6.0 * snug * snug * (0.5 + prog2);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly early, more strongly late (prefer reusing bins),
    // but allow opening when all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 10.0 * (0.3 + prog2) - 15.0 * crowd * crowd;
    }

    // Mean-residual divergence: prefer bins whose post-residual moves toward the mean
    // (keeps residual distribution balanced, smooth quadratic coupling).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild reward for placing larger items into emptier bins (first-fit-like guidance).
    let fill = item_size as f64 / cap;
    score -= 5.0 * fill * fill * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Class A: residual is a large multiple of common item sizes (highly reusable)
    // Class B: mid-range awkward residual
    // Class C: tiny residual (near-full bin, excellent packing)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Class C: near-perfect fill gets strong reward
    if post_residual < 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Modulo arithmetic: post_residual divisible by small common sizes is good
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 8.0;
            break;
        }
    }
    // Awkward primes / odd residuals are dead space
    if post_residual % 10 != 0 {
        score += 4.0;
    }

    // Lookahead: can next item fit into the post_residual? Reward that heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: harmonic coupling reward scaled by snugness
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 + 20.0 * snug;
        } else {
            // next item won't fit here: penalize proportional to wasted potential
            score += 6.0 + 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: using it avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 * 0.5)).abs();
        score += 30.0 + 10.0 * fragmentation / bin_capacity as f64;
        // early in stream, opening bins is cheaper
        score -= 20.0 * (1.0 - progress);
    } else {
        // prefer bins tighter than the mean residual (best-fit-like bias)
        score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);
        // prefer using bins when many are open (consolidation)
        score -= (open_bins_count as f64).min(10.0);
    }

    // Integer-division threshold on post_residual: halves of capacity
    if post_residual > bin_capacity / 2 {
        score += 5.0; // half-empty bin left behind is wasteful unless needed
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "unusable" dead space: gaps too small for typical items (1..100 range).
    // A post_residual in [1, 15] is nearly dead space -> strong penalty.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 4.0;
    }
    // Perfect fit bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 8.0;
        } else if post_residual > 0 {
            // residual exists but can't fit next item: mild penalty scaled by gap size
            score += (next_item_size as f64 - post_residual as f64).min(15.0) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones, penalize new bins.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (open_bins_count as f64 * 3.0 + 10.0);

    // Slight preference for bins with lower residual (tighter bins first).
    score += (mean_residual - post_residual as f64) * 0.2;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * 5.0 * (1.0 - new_bin);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good.
    score -= 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // 2-step lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            // Reward if the two-step leftover is small (near-perfect chain).
            score -= 10.0 * (1.0 - rem2 as f64 / bin_capacity as f64).powi(4);
        } else {
            // Penalize post_residuals that are slightly larger than next_item_size (dead space).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 9.0 {
                score += 6.0 * (1.0 - gap / 9.0);
            }
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If next item is large and no chain is possible, opening fresh is less bad.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 4.0;
        }
    }

    // Early in the stream: be slightly more willing to open bins (build a good spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to item size.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + fit_ratio);

    // Penalize dead space: residual that cannot hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: bin remains usable for the lookahead item; reward proportionally.
            score -= 0.5 * (next_item_size as f64) * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty: unusable leftover.
            score += 0.8 * post_residual as f64;
        }
    } else {
        // Last item: strongly prefer filling existing bins as tightly as possible.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 30.0;
        // More open bins => prefer reusing them; increase reluctance.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is small, open bins are nearly full;
        // a new bin becomes more attractive.
        score -= 0.4 * mean_residual;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    } else {
        // Reusing an open bin: mildly prefer bins with residual close to the mean
        // (keeps the bin pool balanced), but reward below-mean residuals (tighter bins).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
        // Prefer using bins with more residual when many bins are open (consolidation).
        score += 0.1 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    // Nonlinear coupling: penalize medium post-residuals that are awkward
    // (too large to ignore, too small for typical items 10..80 range).
    let awkward = (post_residual as f64).ln_1p();
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 / awkward.max(0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 0.35 * cap * progress * norm_pr * norm_pr;

    // Reward tight fits via smooth cubic term on normalized post_residual.
    score += 2.0 * norm_pr * norm_pr * norm_pr * cap;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: penalize if post_residual can't fit the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 8.0 * (1.0 - pr / ni);
        } else {
            score -= 5.0 * (ni / cap);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.5 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity/8 fractions
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth.max(1);
    score -= (7 - class) as f64 * 2.0; // reward small residuals (tight fits)

    // Modulo-5 dead space penalty: residuals not expressible as common item sums
    let dead = post_residual % 5;
    if dead > 0 && post_residual > 0 {
        score += dead as f64 * 1.5;
    }

    // Perfect-fill harmonic classes: post_residual in {0, 10, 20, 50, 100}-style divisibility
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 5.0;
    } else if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // penalize leaving residual in awkward modulo class relative to next item
        if post_residual % next_item_size.max(1) != 0 {
            score += 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // residual unusable by next item: dead space unless residual very small
        if post_residual > bin_capacity / 4 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        if fitting_bins_count == 0 || crowded {
            score -= 18.0 + 10.0 * (1.0 - progress);
        } else {
            score += 15.0 + mean_residual * 0.2;
        }
    }

    // Slight preference for bins with residual close to mean (balance load)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Integer-division threshold on post_residual vs capacity quarters
    let quarter = bin_capacity / 4;
    if post_residual > 0 && post_residual < quarter {
        score -= 3.0; // small leftover is fine
    } else if post_residual > 3 * quarter {
        score += 4.0; // leaving huge residual = poor packing
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual that cannot hold even the smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Gaps too small for the lookahead item are likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 20.0;
    }
    // Reward residuals that exactly fit the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    // Mean residual coupling: bins far below mean residual are already loose;
    // prefer placing into tighter bins.
    score += 0.10 * (mean_residual - post_residual as f64);

    // New-bin candidate: mildly penalize opening a new bin early in the stream,
    // but allow it when open bins are numerous (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 - 8.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), relative to mean residual landscape.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // 2-step lookahead: reward if next item fits perfectly in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Perfect chain match: strong reward, scaled by exactness.
        score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        if slack_after_next == 0 {
            score -= 20.0; // perfect 2-item fill
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: penalize leaving stranded dead space.
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += 0.6 * dead * (dead / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Avoid opening new bins unnecessarily when open bins have ample mean residual.
    if bin_residual == bin_capacity {
        // New-bin candidate: mild penalty unless it would enable a perfect pair.
        let pair_bonus = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            (bin_capacity - item_size - next_item_size) as f64
        } else {
            0.0
        };
        score += 8.0 - 0.3 * pair_bonus;
        // Penalize new bins more when many open bins already have room.
        score += 0.5 * open_bins_count as f64;
    }

    // Late-stream tightening: waste matters more as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: if the next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mildly penalize unless it's a near-perfect fit.
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage filling existing bins rather than spreading.
    if open_bins_count > 3 {
        score -= 0.5 * (open_bins_count.min(20) as f64);
    }

    // Time horizon: early in stream, be more exploratory (slightly favor new bins
    // for large items to build structure); late in stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 1.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already "specialized"; keep using it. If far above mean, it's roomy.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let no_good_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual < 10);
        if large_item > 0.6 || no_good_fit {
            score -= 20.0; // open a fresh bin
        } else {
            score += 25.0; // prefer existing bins for small/medium items
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with a non-linear penalty
    // on medium dead space (wasted capacity that is hard to reuse).
    let mut score = pr + 60.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, keep residuals flexible (reward larger post_residual
    // slightly); late in the stream, prioritize tight packing harder.
    let coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 25.0 * coupling * (1.0 - norm_pr);
    score += 15.0 * (1.0 - coupling) * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * coupling + 20.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score -= 30.0 * (-diff / 25.0) * (1.0 - coupling);
        // penalize leaving residual just below next item size (dead space)
        if pr < nx {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    if open_bins_count > 0 {
        score += 0.5 * (mean_residual - pr).abs() / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band it falls into
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead space bands: residuals just below common item sizes are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if pr < quarter {
        // residual in (0,25): usable only by small items
        score += 12.0;
    } else if pr < quarter * 2.0 {
        score += 4.0;
    }

    // Integer-division thresholds: how many "typical" items of next size fit in post residual
    if next_item_size > 0 {
        let fits_next = if next_item_size > 0 && post_residual >= next_item_size { 1 } else { 0 };
        if fits_next == 1 {
            score -= 15.0; // lookahead item fits: good packing chain
        } else if next_item_size > 0 {
            // next item cannot follow here; penalize more when residual is tiny
            score += 8.0 * (1.0 - pr / cap);
        }
        // modulo coupling: post_residual mod next_item_size measures leftover after chaining
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual % next_item_size;
            score += leftover as f64 * 0.6;
        }
    } else {
        // last item: prefer tightest fit, ignore future
        score *= 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline so it is chosen
    // only when open bins would create bad residuals
    if bin_residual == bin_capacity {
        score = cap * 0.35 + 10.0;
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good alternative: open new bin
        }
        if pr == cap {
            // perfect-fit potential unknown; slight nudge by stream position
            score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Mean-residual coupling: if this bin's residual deviates strongly from mean,
    // prefer consolidating into low-residual bins
    score += (pr - mean_residual) * 0.25;

    // Harmonic capacity-fraction bonus: post_residual near exact fractions of capacity
    let frac = pr / cap;
    for k in 1..4 {
        let target = 1.0 / (k as f64 + 1.0);
        let d = (frac - target).abs();
        if d < 0.05 {
            score -= 10.0 * (1.0 - d / 0.05);
        }
    }

    // Eighth-level modulo penalty: residuals awkwardly between eighths are dead-ish
    let band = (pr / eighth).floor();
    let in_band = pr / eighth - band;
    if in_band > 0.7 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Favor bins whose residual was already tight (good fit quality).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bonus: only fitting bin, avoid opening new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.8 * (0.5 + progress);

    // Deviation from mean residual: prefer bins below-average residual (tighter).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: neutral-ish baseline with slight penalty so only
    // genuinely poor fits trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the leftover,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // Next item fits inside the leftover: partial lookahead bonus.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * tightness;
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * waste;
        }
    }

    // Penalize small unusable residuals (dead space) more than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare residual against mean residual across open bins:
    // placing into a bin whose residual is below mean (tighter bin) is preferred
    // when the fit is good, but avoid leaving tiny crumbs.
    if post_residual > 0 {
        let rel = post_residual as f64 - mean_residual;
        if rel < 0.0 {
            score += 0.3 * rel; // tighter-than-average bin: mild reward
        } else {
            score += 0.2 * rel; // looser-than-average: mild penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual would be tiny).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual >= 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // New empty bin candidate: penalize opening a new bin, but discount the
    // penalty as the stream matures and open-bin count grows.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 70.0 - 30.0 * progress;
        // If no open bin fits well (this is the only candidate), reduce penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mild preference to fill fuller bins first (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    // Early stream: slightly favor consolidating into fewer bins.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: small but nonzero post residual is wasted
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post residual fits the next item exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0);
        } else {
            // next item won't fit here; mild penalty for fragmenting
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless fits are bad
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced
        } else {
            // open new bin only if existing fits are loose
            score += 30.0 + 0.5 * mean_residual;
            // more willing to open new bins late in stream? actually less: keep bins tight
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 15.0 * (1.0 - progress);
        }
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Prefer bins with residual close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
