pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: which capacity fraction band does post_residual fall in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;

    // Reward tight fits strongly (post_residual small => low score already, add extra class bonus).
    if post_residual == 0 {
        score -= 60.0; // perfect fill: ideal
    } else if post_residual < quarter {
        score -= 15.0; // small dead space, good
    } else if post_residual < half {
        score += 5.0; // medium dead space, mild penalty
    } else if post_residual < three_quarter {
        score += 18.0; // large dead space
    } else {
        score += 30.0; // huge leftover: wasteful
    }

    // Modulo arithmetic on post_residual: residuals congruent to small classes
    // (e.g. post_residual % 10 <= 2) are "harmonic" — likely filled by future small items.
    let class = (post_residual % 10) as f64;
    score -= 3.0 * (2.0 - class).max(0.0);   // reward class 0,1,2
    score += 1.5 * (class - 7.0).max(0.0);   // penalize awkward classes 8,9

    // Integer-division thresholds: how many items of next_item_size could still fit?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits = post_residual / next_item_size;
        score -= 4.0 * fits as f64; // bin remains reusable by the lookahead item
        // Harmonic coupling: next item exactly matches a capacity fraction of residual
        if post_residual % next_item_size == 0 {
            score -= 6.0; // perfect harmonic division, no dead space after next placement
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize proportionally
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if only one bin fits, strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0); // many alternatives: less urgency
    }

    // New-bin candidate (empty bin): make it attractive only when current open bins are crowded
    // or the fit here would be very poor.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (1.0 - mean_residual / cap);
        let poor_fit = (item_size as f64 / cap) < 0.35;
        if crowded > 2.0 || poor_fit {
            score -= 20.0; // open a fresh bin
        } else {
            score += 40.0; // discourage spawning bins when good fits exist
        }
    }

    // Progress coupling: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residual gaps (< 10, min item size) are unusable.
    if post_residual < 10 {
        score -= 25.0; // filling a bin completely is excellent
    } else if post_residual <= 20 {
        // Small gap: only good if the lookahead item can use it, otherwise dead space.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 12.0; // penalize creating likely-dead small gap
        }
    }

    // Reward tight fits (low waste relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    // New-bin candidate has bin_residual == bin_capacity; add pressure there.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.5 * open_bins_count as f64;
        // But if no open bin fits well, opening is fine: new bin has perfect fit potential
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Lookahead synergy: if next item fits exactly into the resulting gap, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // Mild stream-progress term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-match: next item fits with small slack
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit this residual: penalize leaving awkward space
    if next_item_size > 0 && next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        score += 0.3 * miss.min(30.0);
    }

    // Penalize dead space (small unusable residual) nonlinearly
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Prefer tight fits relative to mean residual across open bins
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor and stream is early
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.6;
        if poor_fit {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

