    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward; if post residual is just barely too small for next item,
    // penalize the wasted chunk.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Prefer filling already-open bins when many are open (avoid bin sprawl).
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Global residual pressure: if mean residual is small, conserve space
    // in this bin less aggressively; if large, prefer using fullest bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be more exploratory (favor new bins
    // slightly when fit is poor); late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    // New-bin candidate calibration: an empty bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * (1.0 - tightness);
    }

    score
}

