        score += 30.0 + 2.0 * pressure;
        // If every fitting bin would leave a tiny dead gap, opening fresh is attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 150.0;
        }
    } else {
        // Slight preference for bins that deviate from the mean residual (tighter than average).
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete; prefer the tightest anyway.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if the next item fits the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.5 * next_item_size as f64;
        } else {
            // Post-residual cannot host next item: penalize proportionally to waste.
            score += 0.3 * post_residual as f64;
        }
    }

    // Global state: many open bins -> consolidate; few open bins -> spreading is cheap.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to spread into fresh bins;
    // late in the stream, pack tightly to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (bin_residual == bin_capacity) as i32 as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual anchor: bins far below mean residual are underused; prefer filling them.
    let diff = mean_residual - bin_residual as f64;
    score += 0.2 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with progress
    let coupling = (norm_pr * norm_pr) * (1.0 - progress) * cap;
    score += 0.8 * coupling;

    // Penalize residual that is too small to be useful later (dead space), smoothly
    let dead = (1.0 - norm_pr).powi(3) * cap;
    score += 0.5 * dead * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * (1.0 + progress) * 10.0;

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item smoothly
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = pr - next;
        if gap >= 0.0 {
            score -= 0.3 * (gap / cap).sqrt() * cap * 0.1;
        } else {
            score += 0.2 * (-gap);
        }
    }

    // Mild pressure to reuse bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * norm_pr;

    // Keep new-bin candidate from winning too easily: add penalty on fresh bins
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect-fit class (post_residual == 0) is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: residuals that cannot fit typical small items are bad.
        // Class A: post_residual in (0,10) -> unusable sliver.
        if post_residual < 10 {
            score += 60.0;
        }
        // Class B: post_residual mod 10 == small remainder wastes divisible structure.
        let m10 = post_residual % 10;
        score += (m10 as f64) * 1.5;

        // Harmonic quarter classes: which "harmonic" of capacity the residual lies in.
        let quarter = (post_residual * 4) / bin_capacity; // 0..3
        score += match quarter {
            0 => 25.0,  // nearly full bin: excellent
            1 => 8.0,   // 25-50% left
            2 => 0.0,   // 50-75% left
            _ => -6.0,  // mostly empty: prefer filling new-ish bins? neutral
        };
    }

    // Lookahead harmony: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chain compatibility, more for tight chains.
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 + (chain_waste as f64).min(20.0) * 0.5;
        } else {
            // Next item won't fit here after placement: penalize proportionally.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin gets base residual = capacity.
    // Penalize opening a new bin unless current bin is a bad host.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins are cheaper early (more future to fill them), costlier late.
        score += 30.0 + 40.0 * progress;
        // If item is large relative to capacity, opening fresh is more acceptable.
        score -= (item_size as f64 / cap_f) * 15.0;
    } else {
        // Slight preference for bins tighter than the mean residual (good packing).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Item-size harmonic class: reward placing awkward (prime-ish, odd mod 10) items
    // into bins that absorb them well.
    let item_class = item_size % 10;
    if item_class >= 5 && post_residual < 15 {
        score -= 8.0; // awkward item finishing a bin is great
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals that are too small to hold even the
    // smallest future item are wasted space — penalize heavily.
    let dead_threshold = 12u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 2.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if no existing bin fits well, opening may be fine — soften.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins with residuals below the mean (tighter bins fill first),
    // scaled by stream progression.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual - bin_residual as f64) * 0.3 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score -= 0.6 * (bin_capacity as f64 - post_residual as f64);

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        score += 10.0;
    }

    // Penalize creating tiny unusable slivers (below min item size 1..small).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discourage opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.3;
    }

    // Mild preference to fill bins with larger residuals relative to mean (balance).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward strongly
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let chain_fit = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 35.0 * chain_fit;
        } else {
            // next item won't chain here; penalize large wasted residuals slightly
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Prefer tighter bins among many candidates
        let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
        score -= 20.0 * tightness;
    }

    // Global state coupling: penalize spreading across many open bins
    let open_pressure = open_bins_count as f64 / (mean_residual + 1.0);
    score += 0.02 * open_pressure;

    // Time horizon: early in stream, be conservative (favor new bins for bad fits);
    // late in stream, squeeze into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate
        let base = 15.0 + 30.0 * (1.0 - progress);
        // Open a new bin if current fit is poor (large post_residual) or no good option
        score = base + 0.3 * post_residual as f64 * (1.0 - progress)
              - 0.15 * post_residual as f64 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // reserving fresh space for a chain of big items is attractive early
            score -= 10.0 * (1.0 - progress);
        }
    } else {
        // Existing bin: late-stream urgency to fill
        score -= 15.0 * progress;
        // Prefer bins below mean residual (filling emptier bins evens load)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling of post residual with stream progress:
    // later in the stream, tighter packing matters more; dead space penalized superlinearly
    let coupling = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score -= 8.0 * coupling * progress;
    score += 12.0 * x * x * progress;

    // Penalize waste relative to mean residual across open bins (smooth divergence)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Reward near-full bins smoothly (quadratic in fill ratio)
    let fill = (cap - pr) / cap;
    score -= 10.0 * fill * fill;

    // Last-chance bonus: strongly favor the only fitting bin, scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits smoothly into post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 5.0 * (1.0 - slack / cap) * (1.0 - slack / cap);
    }

    // Mild preference for consolidating into fewer bins as stream progresses
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (values >= 10 can host future items; tiny residuals 1..9 are dead space).
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity class of the post residual.
    let frac = pr / cap_f;

    // Dead space penalty: residuals below the minimum item size are worthless.
    if post_residual < 10 {
        score += 40.0; // punish unusable slivers hard
    } else {
        // Harmonic tiering on integer division of post_residual into 10-wide classes
        let class = post_residual / 10;
        // Favor classes that match common item sizes: 10,20,30,40,50,60,70,80
        let harmonic_bonus = match class {
            1 => 14.0, // residual 10..19: perfect for a 10-item
            2 => 12.0, // residual 20..29
            3 => 10.0,
            4 => 8.0,
            5 => 6.0,
            6 => 4.0,
            7 => 2.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;

        // Exact-fit class: residual divisible into capacity fractions
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
        if post_residual % 20 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward exact or near-exact chaining
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 25.0;
        } else if slack < 10.0 {
            score -= 15.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize unless residual is tiny anyway
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: it must lose against good fits but beat bad ones.
        score += 15.0;
        // Late in the stream, prefer compacting into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // Many open bins with slack: discourage a new bin.
        if mean_residual > 30.0 {
            score += 12.0;
        }
        // Small item into a fresh bin wastes capacity: penalize.
        if item_size <= 30 {
            score += 20.0;
        }
    }

    // Prefer filling fuller bins overall (deviation from mean residual).
    score += 0.15 * (pr - mean_residual).max(0.0);

    // Mild pressure to keep the number of open bins down.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
