    }
    // Penalize leaving a gap that is too small for the known next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when current bins are badly fragmented
    // or nothing fits well; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
