        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins already below mean residual (consolidating emptier space usage).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;

