    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 500.0; // chain: this placement sets up a perfect fit next step
        } else if (post_residual as u32) > next_item_size {
            // next item still fits: mildly good, reward tightness of the chain
            score -= 120.0 * (1.0 - diff / bin_capacity as f64);
        } else {
