        }
    }

    // Penalize tiny unusable residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a needless new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: neutral-ish score; only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 30.0 + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 500.0; // forced new bin
        }
    }

    // Late in the stream, consolidate to reduce wasted capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 25.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
