        } else {
            score += 4.0;
        }
    }

    // New empty bin candidate: only attractive when current item is large
    // or no open bin is a decent fit (high post_residual waste otherwise).
    if bin_residual == bin_capacity {
        let waste_elsewhere = (bin_residual - item_size) as f64;
        score = 60.0 + waste_elsewhere * 0.3;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 35.0; // nothing decent fits anywhere: open a new bin
        }
        if item_size >= 50 {
            score -= 12.0; // big items are fine starting fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = pr / cap;

    // Base: post residual, smoothly modulated by stream progress
    let mut score = pr * (1.0 + 0.6 * progress);

    // Non-linear penalty for dead space: post_residual squared, weighted by progress
    score += 0.9 * post_frac * post_frac * cap * (0.4 + 0.8 * progress);

    // Reward tight fits (small post_residual) via smooth cubic term
    score -= 12.0 * (1.0 - post_frac).powi(3) * fit_frac;

    // Coupling with mean residual: penalize if this bin is far from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space for next item, penalize otherwise
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 8.0 * (1.0 - (ns / (pr + 1.0))) * (0.5 + progress);
        } else {
            score += 10.0 * (0.5 + progress);
        }
    }

    // Mild penalty for too many open bins
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Smooth new-bin preference: prefer new empty bin when item is large and progress is early
    let is_new = (bin_residual as u32 == bin_capacity) && post_residual == bin_residual - item_size;
    if is_new {
        score += 3.0 - 4.0 * fit_frac - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.6 * (waste / 100.0) * (waste / 100.0) * 100.0;

    // Perfect-fit harmonic class: post_residual divisible by common size classes (10/20/25/50).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 25 == 0 {
        score -= 5.0;
    } else if post_residual % 20 == 0 {
        score -= 4.0;
    } else {
        // Fragmented residual: penalize unusable slivers (below min item size 1..100 unknown, use 10).
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Integer-division threshold classes on residual capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor(); // quarters of capacity
    score -= match class as i64 {
        0 => 6.0,        // near-full bin, good use
        1 => 3.0,
        2 => 0.0,
        _ => -2.0,       // mostly empty bin: neutral-slight reward
    };

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bonus: only fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when existing bins are very full or fragmented.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 {
            score -= 10.0; // open bins nearly full -> new bin fine
        } else {
            score += 20.0 + 30.0 * pressure; // discourage wasting fresh bins
        }
    }

    // Stream progression: late in stream, consolidate harder (prefer fuller bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Coupling with mean residual: prefer bins below mean residual (fuller than average).
    score += (mean_residual - post_residual as f64) * 0.1;

    // Open bins count pressure: many open bins -> favor filling existing ones.
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.3 * frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1, but
    // practically gaps below a usable threshold are waste). Penalize gaps that
    // fall in the "unusable" band [0, DEAD_MAX] very hard.
    let dead_max = 20.0f64;
    let pr = post_residual as f64;
    if pr < dead_max {
        score += (dead_max - pr) * 3.0;
    }

    // Reward tight fits (near-perfect packing).
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5.0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    // existing bins; few open bins -> new bins are cheaper.
    let bin_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure so that with many open
        // bins we prefer reusing them unless the fit is poor.
        score += bin_pressure;
        // If no existing bin fits well (this call is the new bin and fitting
        // count includes it), opening is fine.
        if fitting_bins_count <= 1 {
            score -= bin_pressure;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this
    // placement (creates a perfect slot for the next item).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Slight preference for bins with lower residual among equals (denser bins).
    score += (bin_residual as f64 - pr) * 0.1;

    // Progress coupling: later in the stream, be more conservative about
    // opening bins (waste matters more as the stream ends).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Penalize leaving residual too small for the next item (dead space risk)
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Reward small post_residual relative to mean residual (tight packing)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance: this is the only bin that fits -> strong bonus to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting space in a fresh bin unless item is large
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    // Late in stream: prefer tighter fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, especially exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Penalize dead space relative to what a new bin would leave (100 - item_size).
    let new_bin_waste = (bin_capacity - item_size) as f64;
    if post_residual as f64 > new_bin_waste * 0.6 {
        score += (post_residual as f64 - new_bin_waste * 0.6) * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else if next_item_size > bin_residual {
            // Next item won't fit here anyway; waste here is less costly.
            score -= 10.0;
        }
        // Penalize leaving a residual that just barely fails to fit the next item.
        if post_residual < next_item_size && next_item_size <= bin_residual {
            score += 20.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= pressure * 8.0;
    } else {
        // New-bin candidate: penalize opening bins when pressure is high, reward when low.
        score += pressure * 5.0 - 20.0;
    }

    // Time horizon: early in the stream, be more conservative (favor new bins / flexibility);
    // late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= progress * 30.0;
    } else {
        score += progress * 30.0;
    }

    // Mild penalty when bin residual is much larger than item (poor utilization of large residual).
    if bin_residual < bin_capacity && item_size * 2 < bin_residual {
        score += 0.3 * (bin_residual - 2 * item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post / cap; // normalized post residual

    // Base: penalize residual, smoothed non-linearly
    let mut score = post * (1.0 + 0.5 * pr * (1.0 - pr));

    // Non-linear coupling with stream progress: later in stream, prefer tighter fits more strongly
    score += (post * post / cap) * progress * 0.8;

    // Reward near-perfect fits with smooth bell around small post_residual
    score -= 30.0 * (-(pr * pr) / 0.02).exp() * (1.0 + progress);

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((post - nxt).abs()) / cap;
        score += 20.0 * (unusable * unusable) * (1.0 - progress * 0.5);
        // Reward leaving room exactly for the next item
        score -= 15.0 * (-(post - nxt).powi(2) / 50.0).exp();
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Slight pressure toward consolidating into fewer bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);

    // Compare against mean residual: bins far from mean residual get smooth penalty
    score += 3.0 * ((post - mean_residual) / cap).abs() * (1.0 + progress);

    // New-bin candidate: make empty bins moderately attractive only when current bin fit is poor
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit base: tight fits are good; dead space is penalized super-linearly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = 1.0 - (post / cap); // 1.0 = perfect fit

    // Harmonic class of the post-residual: classify leftover space by
    // integer division thresholds (dead-space classes).
    let post_class = post_residual / 10; // classes 0..10
    let class_penalty: f64 = match post_class {
        0 => -6.0,             // perfect fit: strongly reward
        1 => -4.0,             // 1-10 leftover: near-perfect
        2 => -2.5,
        3 => -1.0,
        4 => 0.5,
        5 => 1.5,              // ~50 leftover: awkward mid class
        6 => 1.0,
        7 => 0.0,
        8 => -0.5,
        9 => -1.5,             // large leftover: still reusable
        _ => -2.0,
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residues that pair well with
    // common small items (multiples of 10) are favored.
    let residue_mod = post_residual % 10;
    if residue_mod == 0 {
        score -= 1.5; // divisible by 10: likely reusable by typical items
    } else if residue_mod >= 7 {
        score += 0.8; // awkward residue: wastes space
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 3.0; // chain leaves near-perfect state again
            } else {
                score -= (10.0 - (next_post % 10) as f64) * 0.05;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty if we
            // are wasting a bin that could serve the next item better.
            score += 0.5;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 3.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral base, slightly high so it's used when fits are poor.
        score = 55.0 + item_size as f64 * 0.2;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can serve a follow-up too
        }
        return score;
    }

    // Fragmentation pressure: when many bins are open with high mean residual,
    // prefer filling existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > post + 20.0 {
        score += 0.5; // this bin is worse than average; deprioritize slightly
    } else {
        score -= 0.5 * (1.0 - progress); // early on, consolidate into tighter bins
    }

    // Reward using bins whose residual is close to exhausted regardless of class.
    score -= fit_ratio * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any item (min size 1, but
    // practically small gaps < 10 are pure waste) get a strong penalty.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize residuals that can't fit the lookahead item (creates stranded space
    // for the known next item).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward residuals that can fit the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than opening new ones.
    score += (open_bins_count as f64).ln() * 6.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    // (would leave big dead space in any existing bin) or nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 40.0;
        }
    }

    // Mild mean-residual coupling: prefer bins whose residual is close to the
    // mean (keeps bin states homogeneous, easier future packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already in score).

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post_residual, i.e. a perfect 2-item chain.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nis = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: this bin will be exactly filled
        } else if post_residual > next_item_size {
            // next item fits but leaves a second residual: penalize leftover
            let second_leftover = pr - nis;
            score -= 12.0;
            score += 0.15 * second_leftover;
            // small leftover after next item is great (double tight fit)
            if second_leftover <= 10.0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use the residual: dead-space risk
            score += 0.25 * nis.min(pr);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving more than average waste is penalized, less is rewarded.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = pr - mean_residual;
        score += 0.10 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large relative to residual of typical open bins, otherwise keep
    // existing bins preferred.
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size >= 60 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (1.0 - progress) * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space that can't fit typical future items.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.05;
    }

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 15.0; // chain of perfect fits
        }
    } else if next_item_size > 0 {
        // Leftover too small for next item: penalize proportional to wasted potential.
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 2.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is low, conserve space in roomy bins.
    if mean_residual < item_size as f64 && post_residual < mean_residual {
        score -= 5.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 15.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias; // early: new bins are cheaper; late: penalized
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can always take the next item
        }
    }

    // Mild preference for bins whose residual is "odd-sized" relative to capacity,
    // encouraging consolidation of fragmented bins.
    let frag = ((bin_residual % 10) as f64) / 10.0;
    score += 3.0 * frag * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: normalized post residual
    let mut score = post / cap;

    // Smooth non-linear coupling: residual squared scaled by progress
    let post_norm = post / cap;
    score += 0.8 * post_norm * post_norm * (0.5 + progress);

    // Cubic interaction with stream progress (early: tolerate leftovers; late: punish)
    score += 0.6 * post_norm.powi(3) * (1.0 - progress) * progress * 4.0;

    // Reward tight fits smoothly (low post residual relative to bin)
    score -= 0.5 * (1.0 - post_norm).powi(2);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.5 * progress;
    }

    // Penalize bins far from mean residual (fragmentation pressure)
    let deviation = (bin_residual as f64 - mean_residual) / cap;
    score += 0.15 * deviation * deviation;

    // Lookahead: smooth reward if next item fits into post residual
    if next_item_size > 0 {
        let next_fit = (next_item_size as f64) / cap;
        let slack = (post - next_item_size as f64) / cap;
        if slack >= 0.0 {
            score -= 0.4 * next_fit * (1.0 - slack);
        } else {
            score += 0.2 * (-slack);
        }
    }

    // Mild penalty for opening new bins when many are open and progress is late
    if bin_residual == bin_capacity {
        score += 0.3 + 0.4 * progress + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover mod 10 buckets.
    let cls = post_residual % 10;
    // Leftovers near "nice" packing residues (0, 10, 20, 30, 40, 50) are more reusable.
    let nice = [0u32, 10, 20, 30, 40, 50];
    if nice.contains(&post_residual) {
        score -= 6.0;
    }
    // Penalize tiny dead space (cls 1..3): nearly unusable slivers.
    if cls >= 1 && cls <= 3 && post_residual > 0 {
        score += (4 - cls) as f64 * 3.0;
    }
    // Reward leftover classes that pair well with common item remainders (item % 10).
    let item_cls = item_size % 10;
    let next_cls = next_item_size % 10;
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect harmonic match: leftover class == next item class.
        if cls == next_cls {
            score -= 8.0;
        } else if post_residual - next_item_size <= 5 {
            score -= 5.0;
        }
    }
    // Integer-division thresholds on post_residual: big chunks are valuable.
    let chunk = post_residual / 25; // 0..4 quarters
    score -= chunk as f64 * 2.5;

    // Capacity fraction coupling: item as fraction of capacity.
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        // Large items: prefer tightest fit, mild extra pressure on post_residual.
        score += 1.0;
    }

    // Last-chance bonus: only one fitting bin left, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // New-bin candidate: only attractive when current bin would be badly fragmented
    // or when the next item would not fit here anyway.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && next_item_size > post_residual;
        if post_residual >= 40 || bad_fit {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        } else {
            score += 15.0;
        }
    }

    // Mean residual coupling: when open bins are generally full, conserve space.
    if mean_residual < 15.0 && bin_residual < 30 {
        score -= 3.0;
    }

    // Progress-based tie-breaking: later in stream, slightly prefer filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gaps 1..9 heavily penalized
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 8.0; // moderately awkward zone
    }

    // Tight fit reward: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Open-bin pressure: discourage spreading across many bins when few remain useful.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (1.0 - progress) * 3.0;

    // Prefer bins whose residual is close to item (minimizes waste relative to alternatives).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64).abs() * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size {
            score += 6.0; // blocks the next item in this bin
        }
    }

    // New-bin candidate: only attractive when open bins have poor fits or big residuals mismatch.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).abs();
        let poor_open = mean_gap > 20.0 || fitting_bins_count == 0;
        if poor_open {
            score -= 10.0 + 5.0 * (mean_gap / 100.0);
        } else {
            score += 30.0; // keep using existing bins when they fit reasonably
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining bonus: next item exactly consumes remaining space
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 + (slack_after_next as f64).min(10.0) * 0.5;
            if slack_after_next == 0 {
                score -= 20.0; // perfect two-item fill
            }
        } else {
            // Next item won't chain; penalize dead space relative to smallest item
            score += (post_residual as f64) * 0.15;
        }
    }

    // Compare against mean residual: prefer bins whose residual deviates usefully
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = residual_f - mean_residual;
        score += dev * 0.08; // prefer tighter (below-mean) bins
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) > bin_capacity / 3;
        if poor_fit && next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0; // open fresh bin rather than waste space
        } else {
            score += 8.0; // keep using open bins when fit is decent
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Prefer high fill ratio
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> exploratory (favor new bins / spread), late -> consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space quadratically, scaled by how "unusable" it is.
        let dead = post_residual as f64;
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            score += dead * dead * 0.02 * (1.0 - 0.5 * t);
        } else {
            // Lookahead synergy: reward residuals that exactly fit the next item.
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 25.0;
            } else if next_item_size > 0 {
                let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
                score += gap * 0.3;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 * (1.0 + t);
    }

    // Tightness coupling: prefer bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Global state: if mean residual is large, prefer filling existing bins harder.
    score -= mean_residual * 0.15 * (1.0 - t);

    // Many open bins -> consolidation pressure; few open bins -> allow spreading early.
    let spread = open_bins_count as f64;
    score += spread * 1.2 * (1.0 - t) - spread * 0.5 * t;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible,
    // but relax late in the stream when consolidation dominates anyway.
    if bin_residual == bin_capacity {
        score += 45.0 - 20.0 * t;
        // If item is large relative to capacity, new bin is more attractive.
        score -= item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a mild non-linear
    // penalty that grows super-linearly for large leftover space.
    let mut score = post + 0.9 * (post * post) / cap;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, waste is more costly, so amplify the polynomial term.
    let coupling = progress * progress * (post / cap) * (1.0 - post / cap);
    score += 18.0 * coupling * progress;

    // Mean-residual interaction: penalize bins far from the mean residual
    // (smooth quadratic divergence), scaled by progress.
    let dev = post - mean_residual;
    score += (1.5 + 4.0 * progress) * (dev * dev) / cap;

    // Lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fit_gap = (post - nx) / cap;
            score -= 6.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 4.0 * (nx - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly weighted by progress).
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Slight preference for consolidating into fewer bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make the empty bin mildly attractive only when the
    // item leaves a very large residual elsewhere (poor fits), via smooth term.
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.25 * progress) + 0.6 * post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space below smallest item (1..10) is nearly unusable.
    let small = post_residual < 10;
    if small {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Modulo-class logic on capacity fractions: residuals near C/2, C/4, C/3 are valuable
    // because many common item sizes land there.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    let harmonic_bonus = |r: u32| -> f64 {
        let f = r as f64 / 100.0;
        let mut b = 0.0;
        for target in [0.5f64, 0.25, 0.75, 1.0/3.0, 2.0/3.0, 0.2, 0.4] {
            let d = (f - target).abs();
            b += 40.0 * (-d * 25.0).exp();
        }
        b
    };
    score -= harmonic_bonus(post_residual);

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0 + 0.3 * next_item_size as f64;
        // Even better if next item then leaves a harmonic-class residual.
        score -= harmonic_bonus(post_residual - next_item_size);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize leaving stranded space.
        score += 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened when many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 25.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        if item_size > 70 {
            score -= 20.0; // huge items: fresh bin is fine
        }
        if fitting_bins_count > 0 && post_residual >= 10 {
            score += 30.0; // an open bin could still take it decently
        }
    }

    // Mild pressure to prefer fuller bins among many open bins.
    score += 0.05 * open_bins_count as f64;
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A post_residual that cannot hold even the smallest plausible item (1..=10)
    // is pure waste; penalize it steeply.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else {
        // Larger gaps are progressively less wasteful.
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward gaps that exactly or nearly fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer tight fits.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // New-bin candidate: only attractive when current bins fit poorly
    // (large post_residual relative to capacity or many open bins with high mean residual).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) * 55.0
            + (mean_residual / bin_capacity as f64) * 20.0;
        score += 70.0 - poor_fit;
        // Late in the stream, opening new bins is less costly than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild alignment with mean residual: prefer bins whose residual is near the mean
    // to keep bin states homogeneous.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strong bonus (subtract)
        if diff < 0.5 {
            score -= 40.0 + 20.0 * (1.0 - progress);
        } else {
            score += diff * 0.6;
        }
        // If next item cannot fit in post-residual, penalize proportionally to how much space is wasted
        if post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    } else {
        // Last item: prefer tightest fit only
        score += 5.0;
    }

    // Penalize dead space relative to mean residual: creating a residual much below
    // mean_residual means this bin becomes unusually unusable
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.3;
    } else {
        score -= (pr - mean_residual) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer opening a new bin if the resulting post_residual is large and
    // unusable elsewhere; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin (scaled by how many bins already open)
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If post_residual exactly matches next item, opening a fresh bin is attractive
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0;
        }
        // Late in the stream, avoid opening new bins even more
        score += 15.0 * progress;
    }

    // Small general reward for tight fits (low post_residual)
    score -= (bin_capacity as f64 - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, prefer tight fits less aggressively
    // (keep flexibility); late, squeeze hard into existing bins.
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Dead-space penalty: post_residual that is too small to hold any plausible
    // future item (min size 1..) is fine, but mid-range dead space is bad.
    let dead = if post_residual > 0 && post_residual < 10 {
        15.0 // tiny unusable sliver — actually good (near-perfect fit), reward instead
    } else {
        0.0
    };
    score -= dead; // near-perfect fits are excellent

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        let next_fits = post_residual as i64 - next_item_size as i64;
        if next_fits == 0 {
            score -= 25.0; // perfect chain
        } else if next_fits > 0 && (next_fits as u32) < 10 {
            score -= 12.0; // near-perfect chain
        } else if next_fits < 0 {
            // next item won't fit here; penalize slightly if it creates awkward split
            score += 3.0 * (progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it to
    // avoid opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 15.0 * progress;
    }

    // Relative fit quality: how well item fills this bin vs. average open bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Prefer bins with residual below the mean (consolidate fuller bins),
    // penalize dumping into already-large-residual bins.
    let rel = bin_residual as f64 - mean_residual;
    score += 0.15 * rel * (1.0 - progress);

    // Global pressure: many open bins -> consolidate; few open bins -> new bin ok.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer it when the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin unless item is big or late with many bins open.
        score += 30.0 - 40.0 * large_item - 10.0 * progress * pressure;
        // If next item is also large, a fresh bin gives room — soften penalty.
        if next_item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 12.0;
        }
    }

    // Mild non-linear term: reward post_residuals that are multiples of common
    // small sizes (10/20/25), making future packing easier.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: post residual (tighter fit preferred)
    let mut score = pr;

    // Smooth polynomial coupling: penalize large residuals more as stream progresses
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) * cap;
    score += poly;

    // Smooth reward for near-perfect fits (post residual close to 0), stronger late in stream
    let tight = (1.0 - norm_pr).powi(6);
    score -= tight * (20.0 + 40.0 * progress);

    // Lookahead coupling: reward residual that could hold next item, smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (norm_pr - nxt / cap).max(0.0);
        score -= 15.0 * (fits_next / (1.0 + fits_next));
    }

    // Last-chance bonus: smooth escalation when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 10.0 * scarcity * (1.0 + progress);

    // Mean residual coupling: prefer bins near the mean (smooth gaussian-like)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions) ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap; // 0..1

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class-based dead-space penalty: residuals that cannot host common
        // item sizes (1..100) are heavily penalized.
        // Next item must fit for the residual to be worth keeping.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // dead space relative to lookahead
                score += (next_item_size - post_residual) as f64 * 1.5;
            } else {
                // reward residual that exactly harmonically matches next item
                let diff = post_residual - next_item_size;
                if diff == 0 {
                    score -= 200.0; // lookahead perfect fit
                } else {
                    score -= 20.0; // usable residual bonus
                }
            }
        }

        // Integer-division thresholds: classify residual into harmonic bands
        let band = post_residual / (bin_capacity / 4); // quarter bands
        match band {
            0 => score += 60.0,           // <25% residual: nearly dead
            1 => score += 25.0,           // 25-50%
            2 => score -= 5.0,            // 50-75%
            _ => score -= 10.0,           // >=75%: roomy bin
        }

        // Modulo-class coupling: residuals that are multiples of 10 or 25
        // tend to align with typical item sizes.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }
        // Odd tiny residuals are prime dead space
        if post_residual < 10 {
            score += 80.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that can fit the item; avoid opening a new bin.
        score -= 150.0;
    }

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Baseline cost of opening a new bin: its full empty residual.
        // Prefer new bin only when no open bin offers a good fit.
        // If some open bin gives near-perfect fit, new bin loses.
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        } else if post_frac < 0.35 {
            // existing bins are tight; new bin attractive
            score -= 100.0;
        }
        // Late in the stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 {
            score += 50.0 * progress;
        }
        // Many open bins: discourage opening more
        score += open_bins_count as f64 * 3.0;
    } else {
        // Favor bins whose residual is close to the item (tight packing)
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += tightness * 10.0;

        // Prefer bins below mean residual (filling emptier bins first keeps
        // tight bins available for small items)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (items >= 1, but practically small gaps < 12 are wasteful)
    // get a heavy nonlinear penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 * (12.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward a residual that can still host the lookahead item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for the next item: it is dead space
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: penalize it by open-bin pressure
        // and by how "loose" the fit would be (large post_residual already does
        // much of this), so it only wins when all existing fits are terrible.
        score += pressure + 10.0;
    } else {
        // Existing bin: mild reward for being scarce (last chance bin).
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Slight reward for tighter-than-average fill.
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Exact match: next item fills this bin perfectly afterwards.
        if diff < 0.5 {
            score -= 45.0 + nxt; // big bonus for a two-item perfect fill
        } else {
            // Penalize post-residuals that neither fit next item well nor stay useful.
            score += 0.35 * diff;
            // If next item cannot fit in post residual, dead space risk.
            if pr < nxt {
                score += 0.6 * (nxt - pr);
            }
        }
        // Slightly favor leaving room >= next item even if not exact.
        if pr >= nxt && diff >= 0.5 {
            score -= 0.15 * (pr - nxt);
        }
    }

    // Compare post residual against mean residual of open bins:
    // leaving less than mean wastes capacity relative to fleet average.
    let pr = post_residual as f64;
    score += 0.25 * (pr - mean_residual).max(0.0);
    score -= 0.10 * (mean_residual - pr).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current
    // residuals are nearly exhausted or no good fit exists.
    if bin_residual == bin_capacity {
        let avg_use = mean_residual;
        let pressure = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = pr; // = capacity, useless metric; base penalty on fleet state
        score += 55.0
            - 0.5 * avg_use
            - 20.0 * pressure
            - if next_item_size > 0 && next_item_size as f64 > avg_use { 25.0 } else { 0.0 };
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        let _ = waste;
    }

    // Mild tightening: prefer placements into already-open bins as stream progresses.
    if bin_residual < bin_capacity {
        score -= 2.0 + 0.02 * open_bins_count as f64;
    }

    // Small tie-break: prefer bins whose residual is close to item size before placement.
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // ---- New empty bin candidate ----
    if bin_residual == bin_capacity {
        // Base handicap: prefer reusing an existing bin unless fits are bad.
        score += 45.0 + 25.0 * progress;
        if fitting_bins_count == 0 {
            // No open bin can fit: opening a new bin is mandatory.
            score -= 80.0;
        } else {
            // If existing fits leave dead space unusable for the next item,
            // a fresh bin (which can host item + next item) becomes attractive.
            let dead_elsewhere = (next > 0.0) && (post_residual >= next_item_size);
            if dead_elsewhere {
                score -= 35.0;
            }
            if next > 0.0 && next <= bin_capacity as f64 {
                // Fresh bin can fit item + next item comfortably.
                if item_size as f64 + next <= bin_capacity as f64 {
                    score -= 12.0;
                }
            }
            // Late in the stream, avoid proliferating bins.
            score += 20.0 * progress;
        }
        return score;
    }

    // ---- Existing bin candidate ----
    // Reward tight packing (small post_residual) non-linearly.
    score -= 20.0 * (1.0 - post / bin_capacity as f64) * (1.0 - post / bin_capacity as f64);

    // Dead-space penalty: residual too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.9;
    }
    // Reward if the next item can still co-fit in this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Perfect closure: bin becomes exactly full.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: this is the only bin that can take the item.
    if fitting_bins_count == 1 {
        score -= 28.0;
    }

    // Mild pressure toward bins with below-average residual (consolidation),
    // modulated by stream progress.
    score += 0.06 * (mean_residual - post) * (1.0 + progress);

    // Early stream: be slightly pickier about tight fits; late stream: pack fast.
    score *= 1.0 - 0.10 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Smooth interaction: residual squared times normalized item size (favor tight fits of large items)
    score -= 3.0 * norm_pr * norm_pr * norm_item * cap;

    // Cubic coupling of residual with progress: late in stream, waste is more costly
    score += norm_pr.powi(3) * (0.5 + 4.0 * progress) * cap;

    // Reward near-perfect fits smoothly (residual close to 0)
    score -= (1.0 - norm_pr).powi(6) * 2.0 * norm_item * cap;

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).max(0.0) / cap;
        score += fit_gap * fit_gap * cap * (0.5 + progress);
        score -= 1.5 * (1.0 - fit_gap) * (nx / cap) * (1.0 - (pr - nx).abs() / cap).max(0.0);
    } else {
        // Last item: strongly prefer zero residual
        score += norm_pr * cap;
    }

    // Scarcity bonus: if this is the only fitting bin, penalize opening a new bin instead
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.0 + 3.0 * progress;
    }

    // New-bin candidate handling: neutral-ish baseline, penalized mildly unless current bin waste is huge
    if bin_residual == bin_capacity {
        let waste_pressure = (norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap) - 2.0 * progress;
        score = 2.0 + progress + waste_pressure.max(0.0) * 0.5;
    }

    // Mild penalty for too many open bins relative to mean residual spread
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap - norm_pr).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes
    let pr = post_residual;
    let class = pr % 10; // decile class of leftover
    // Small leftovers (< 10) are dead space: penalize by class
    if pr < 10 {
        score += 12.0 + (10 - pr) as f64 * 2.0;
    } else if pr >= 10 && pr <= 20 {
        // sweet spot: leftover can still hold smallest items
        score -= 8.0 - (pr as f64 - 10.0) * 0.3;
    }

    // Integer-division thresholds: how many smallest items fit post-placement
    let fits_small = pr / 10;
    score -= fits_small as f64 * 3.0;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next fits: reward, especially tight fits (harmonic match)
            let tightness = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 10.0 + tightness * 8.0;
        } else {
            // next item won't fit: penalize proportionally to wasted potential
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize so it's only chosen when open bins are hopeless
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 1.5;
    } else {
        // reward filling existing bins deeply (capacity fraction)
        let fill_frac = (bin_residual as f64) / cap;
        score -= fill_frac * 6.0;
    }

    // Mean-residual harmonic: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Late-stream consolidation: as stream progresses, avoid spreading
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    // Modulo penalty: leftovers in awkward classes (e.g. 21..29, 41..49) less reusable
    let m = pr % 20;
    if m > 10 && m < 20 {
        score += (m - 10) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= ~10) are "dead" — penalize heavily.
    if post_residual == 0 {
        // Perfect fill: reward strongly.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: harsh penalty.
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else {
        // Usable leftover: mild penalty proportional to waste, but
        // reward keeping leftover compatible with the lookahead item.
        score += 0.15 * post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // leftover can host the next item
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
            score += 15.0; // leftover likely wasted
        }
    }

    // Tight-fit reward: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage opening new bins when several are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow, but relax
        // pressure late in the stream when consolidation matters less.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = 8.0 + 6.0 * (open_bins_count as f64).sqrt() * (1.0 - 0.5 * progress);
        score += pressure;

        // If this is the last chance among fitting bins, opening a new bin
        // is fine (avoid forcing a terrible fit).
        if fitting_bins_count == 1 && bin_residual - item_size < item_size {
            score -= 30.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 2.0 * (open_bins_count as f64).min(10.0);
    }

    // Scarcity: if only this bin fits, favor it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in the stream, be more flexible; late, tighten.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect lookahead match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        // Dead space relative to lookahead: penalize gaps the next item can't use.
        let waste = post_residual as f64 - next_item_size as f64;
        if waste < 0.0 {
            score += 0.6 * (-waste) * (0.5 + progress);
        } else {
            // Leftover that next item fits into with slack: mild reward for tightness.
            score -= 0.15 * waste;
        }
    }

    // Compare against mean residual: prefer bins that become closer to average fill
    // (balanced packing) but reward below-average residual (well-filled bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.1 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin when other bins can fit,
    // unless the item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        let base_penalty = if fitting_bins_count > 0 { 18.0 } else { 0.0 };
        score += base_penalty;
        // If residuals are large on average (lots of room), discourage new bins more.
        score += 0.2 * mean_residual;
        // Late in the stream, opening new bins is more wasteful.
        score += 8.0 * progress;
    }

    // Slight preference for tighter fits overall (small post_residual already in base).
    score += 0.05 * (post_residual as f64).powf(1.3) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize fill ratio of this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill * fill;

    // Penalize leaving awkward dead space (small, hard-to-use residuals).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual <= 20 { 0.55 } else { 0.0 };
        score += 14.0 * dead;
    }

    // Lookahead: if the next item fits exactly or well into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * next_fit;
        } else {
            // Next item won't fit here; mildly penalize wasting a good residual now.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits even more.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // all open residuals are poor for this item or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        // Cost of new bin grows with stream progress and number of open bins.
        score += 25.0 + 20.0 * progress + 6.0 * open_pressure;
        // But if the item is large and mean residual is low, new bin becomes better.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 35.0 * large_item * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Global state: if mean residual across open bins is high, favor using existing space.
    score -= 4.0 * (mean_residual / bin_capacity as f64);

    // Slight time-decay preference for consolidation late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate waste less strongly
    // since future items are fewer.
    let pr_norm = pr / cap;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 20.0 * pr_norm * (1.0 - progress) * (1.0 + prog2);
    score -= 15.0 * pr_norm * prog3;

    // Reward near-perfect fits with a smooth quadratic trough at pr = 0..small
    let fit_quality = 1.0 - (pr / cap);
    score -= 10.0 * fit_quality * fit_quality * (1.0 - progress);

    // Lookahead: if next item fits into the post_residual, reward this placement smoothly
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let smooth = 1.0 - (gap / cap) * (gap / cap);
            score -= 8.0 * smooth * (1.0 - progress);
        } else {
            let miss = (-gap / cap).min(1.0);
            score += 6.0 * miss * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: penalize opening new bins when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate: make empty bins mildly unattractive unless residuals are all large
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 5.0 + 10.0 * pressure * (1.0 - progress) - 6.0 * progress;
    }

    // Fragmentation penalty: small post_residual relative to typical item sizes is good;
    // mid-range residuals are dead space
    let mid = (pr - cap * 0.4).abs();
    score += 4.0 * (mid / cap) * (1.0 - progress);

    // Open-bin pressure: many open bins -> favor consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: coarse integer-division thresholds.
    // Small post_residual classes are rewarded (tight packing), large ones penalized.
    let class = post_residual / 10;
    score += match class {
        0 => -35.0, // nearly exact fit
        1 => -18.0,
        2 => -8.0,
        3 => 0.0,
        4 => 6.0,
        5 => 10.0,
        6 => 14.0,
        7 => 18.0,
        8 => 22.0,
        _ => 26.0,
    };

    // Exact fill is the ideal harmonic state.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo-10 harmony: residuals that are round multiples of 10 pair well
    // with typical item sizes; reward them.
    if post_residual % 10 == 0 {
        score -= 7.0;
    }

    // Lookahead coupling: if the next item can fit into the post_residual,
    // this bin remains productive; otherwise it risks becoming dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
        } else if post_residual > 0 && post_residual < 10 {
            score -= 4.0; // tiny residual, effectively sealed but harmless
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): normally penalized so we reuse open bins,
    // but a large item into a fresh bin is efficient and rewarded.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 60 {
            score -= 35.0;
        } else if item_size >= 40 {
            score -= 15.0;
        }
    }

    // Slight drift toward consolidating among many open bins: with many open
    // bins, favor tighter fills even more (mean residual context).
    if open_bins_count > 4 {
        score += (post_residual as f64 - mean_residual) * 0.08;
    }

    // Progress-aware tightening: late in the stream, prioritize closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A post_residual below the minimum item size (1..100 interface => min ~10 typical, use 10)
    // is pure dead space; below ~20 it is unlikely to be reusable.
    if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 12.0;
    } else if post_residual < 35 {
        score += (35.0 - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead space is worse when few bins are open (less chance to absorb waste elsewhere).
    let pressure = 1.0 + (open_bins_count as f64).ln().max(0.0) * 0.15;
    if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 8.0 / pressure;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Prefer filling existing bins unless the existing fit leaves a large dead gap.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins early; grows weaker as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress * 0.5);
        // But if existing bins would leave tiny dead space, new bin becomes attractive
        // (handled implicitly since those bins get the dead-space penalty above).
    }

    // Lookahead: if next item would fit in the post residual, reward leaving that gap.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item is slightly larger than what we'd leave (near-miss gap).
    if next_item_size > post_residual && (next_item_size as i64 - post_residual as i64) <= 10 {
        score += 8.0;
    }

    // Mild preference for bins with residuals below mean (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact / tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space non-linearly; small residuals are very bad
        let pr = post_residual as f64;
        score += 200.0 / pr.sqrt();
    }

    // 2-step lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 50.0 + (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: mild penalty for wasting lookahead potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 60.0 - (item_size as f64 * 0.5);
        if item_size >= 60 {
            score -= 40.0; // large items are fine in fresh bins
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared residual punishes wasted space super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize residual that is too small to ever be useful again.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // many bins are open or the item fits reasonably elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin is good for a large next item
        }
        // Early stream: opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate waste).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer fuller bins (smaller residual before placement).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear penalty on large-but-unusable residual, modulated by stream progress.
    let dead = x * x * (1.0 - x);
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - x) * (1.0 - x) * 8.0 * (0.5 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let compat = (x - nx).abs();
        score -= 6.0 * (1.0 - compat).max(0.0) * (0.4 + 0.6 * progress);
        score += 4.0 * (x * x) * (1.0 - progress);
    }

    // Mild penalty for scattering across many open bins when mean residual is low.
    let scatter = (open_bins_count as f64).ln().max(0.0);
    score += 0.6 * scatter * (mean_residual / cap) * (1.0 - progress);

    // Smooth new-bin preference: empty bin gets a small baseline nudge toward opening
    // when current fit is poor, discouraged when fit is good.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score += 3.0 - 10.0 * (1.0 - x) * (1.0 - x) + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "dead" (too small
    // to hold anything) should be heavily penalized; residues that pair well
    // with common small items should be rewarded.
    let dead_threshold: u32 = 10; // smallest plausible item
    if post_residual == 0 {
        // Perfect fit: best possible outcome.
        score -= 60.0;
    } else if post_residual < dead_threshold {
        // Unusable dead space.
        score += 40.0;
    } else {
        // Harmonic classes: post_residual divisible by common item sizes
        // (10, 20, 25, 50) is more reusable.
        let mut harmony = 0.0;
        if post_residual % 10 == 0 { harmony += 6.0; }
        if post_residual % 20 == 0 { harmony += 4.0; }
        if post_residual % 25 == 0 { harmony += 4.0; }
        if post_residual % 50 == 0 { harmony += 5.0; }
        score -= harmony;

        // Fraction-of-capacity classes: quarter/half residuals are attractive.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if post_residual == half { score -= 8.0; }
        else if post_residual == quarter || post_residual == 3 * quarter { score -= 4.0; }

        // Lookahead coupling: reward residuals that exactly fit the next item,
        // penalize residuals just barely too small for it.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 12.0;
            } else if post_residual >= next_item_size {
                score -= 3.0;
            } else if post_residual + dead_threshold > next_item_size {
                // Teasing: almost fits next item -> dead space likely.
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins that are already relatively full (low residual),
    // scaled by stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0 * (0.5 + progress);

    // Discourage spreading across many open bins when mean residual is high.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    // New-bin candidate: only attractive when nothing fits well — make the
    // empty bin's baseline moderately high so open bins with decent fits win,
    // but low enough when the empty bin gives a perfect harmonic start for a
    // large item.
    if bin_residual == bin_capacity {
        // A fresh bin always "fits" perfectly; make it neutral-ish but biased
        // by how much of it the item consumes.
        score = (bin_capacity - item_size) as f64 * 0.8;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for the smallest plausible item are pure waste.
    // Penalize them super-linearly so tight fits win decisively.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when the leftover gap exactly accommodates the lookahead item (k=2).
    if next_item_size > 0 {
        let gap_diff = post_residual as i64 - next_item_size as i64;
        if gap_diff == 0 {
            score -= 30.0; // next item will seal this bin perfectly
        } else if gap_diff > 0 && gap_diff < 10 {
            score += 8.0; // near-miss creates a small dead gap after next item
        }
    }

    // --- Tightness reward: fraction of the bin consumed by this placement ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // --- Open bins pressure ---
    // When many bins are open, prefer consolidating into existing ones;
    // when few are open, opening a new bin is cheaper.
    let open_pressure = (open_bins_count as f64).ln() * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; discount if the item
        // is large (better to give big items fresh space) or few bins open.
        let mut new_bin_score = 20.0 + open_pressure;
        new_bin_score -= fill_ratio * 15.0;
        if fitting_bins_count <= 1 {
            new_bin_score += 15.0; // last-chance bins are precious, prefer new bin
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        return new_bin_score;
    }

    // Last-chance bonus: this is the only bin that fits; avoid forcing a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be picky, penalize mediocre fits.
        if post_residual as f64 > mean_residual {
            score += 6.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (nearly-full bins),
    // which consolidates waste into few bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 20.0;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect lookahead match: strongly favor
        } else if post_residual >= next_item_size {
            // next item fits after this one: mild reward scaled by closeness
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item would not fit here: penalize wasted space
            score += 8.0 + diff * 0.15;
        }

        // Coupling with mean residual: if this bin's post-residual is far
        // below mean residual, it's a distinctive good fit.
        let post_f = post_residual as f64;
        if post_f < mean_residual {
            score -= (mean_residual - post_f) * 0.3;
        } else {
            score += (post_f - mean_residual) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin
    // offers a decent fit (post_residual would be large and next item
    // doesn't chain well).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin, reduced when the item is large
        // (big items fragment capacity) and few bins are open.
        let size_frac = (item_size as f64) / (bin_capacity as f64);
        score += 55.0 - 30.0 * size_frac;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference to fill older/more crowded bin sets: keep bin count low.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * chain_quality;
    } else if next_item_size > 0 {
        // Penalize leaving residual that no plausible next item can use (dead space).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (post_residual as f64 / bin_capacity as f64) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global fragmentation pressure: when many open bins exist, prefer
    // consolidating into bins below the mean residual (reduces spread).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 15.0 * dev;
    }

    // New-bin candidate handling: empty bin should only win when the fit
    // into existing bins is bad. Give it a neutral-ish base with a mild
    // penalty that shrinks late in the stream (less risk early).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 30.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
        // If next item is large and would pair well with this item in a fresh bin,
        // make the new bin slightly more attractive.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Non-linear waste penalty: quadratic in post_residual, damped by stream progress
    score += 0.035 * post * post / cap * (1.0 - 0.5 * progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tightness = (cap - post) / cap;
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: penalize post_residual that cannot host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = post - nx;
        if gap < 0.0 {
            score += 6.0 + (-gap) * 0.25;
        } else {
            // smooth reward for residual that still fits the next item
            score -= 5.0 * (gap / cap).min(1.0);
        }
    }

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Penalize scattering residual across many open bins (encourage consolidation)
    score += (open_bins_count as f64).ln() * 0.6 * (post / cap);

    // Discourage drifting far above mean residual (keeps bins balanced)
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate: mildly penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 4.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers that are multiples of
    // common item sizes (10..=20 bands) are more reusable, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = match pr % 10 {
            0 => 12.0,
            5 => 6.0,
            _ => 0.0,
        };
        // Exact-match harmonic: leftover equal to a plausible next item size
        if pr >= 10 && pr <= 80 {
            score -= class_bonus;
        }
        // Perfect fill is ideal
        if pr == 0 {
            score -= 50.0;
        }
        // Dead space penalty: small unusable leftovers (1..9)
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }
    }

    // Coupling with lookahead: if next item exactly fits the post residual,
    // strongly favor this bin (harmonic resonance).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if pr >= next_item_size && next_item_size > 0 {
            score -= 8.0;
        } else if pr > 0 && pr < next_item_size {
            // leftover too small for the next item -> penalize proportionally
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 15.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin
    // resonates well (high mean residual spread / item is large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 3.0;
        // New bins are cheap early, expensive late
        score += pressure - progress * 10.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        // If mean residual across open bins is large, opening new bin is wasteful
        score += mean_residual * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead". Penalize them extra hard.
    let dead_threshold = 10.0_f64.min(cap * 0.1);
    if post > 0.0 && post <= dead_threshold {
        score += (dead_threshold - post) * 8.0 + 20.0;
    }

    // Reward tight fits (small but usable post residual).
    if post > 0.0 {
        score -= (1.0 - post / cap).powf(6.0) * 15.0;
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0;
    }
    // If next item almost fits (small miss), mild penalty for stranding space.
    if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post && (next_item_size as f64) - post <= 10.0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64) * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += pressure * 3.0 + 5.0;
    } else {
        // Existing bin: mild reward scaled by open-bin pressure.
        score -= pressure.min(10.0);
    }

    // Prefer bins whose residual is below the mean (filling the emptiest-tight bins
    // keeps mean residual low and concentrates space).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong preference for near-perfect fits: reward small post_residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 50.0; // perfect chain: this placement enables a perfect next fit
        } else if gap <= 5.0 {
            score -= 25.0;
        } else if gap <= 15.0 {
            score -= 10.0;
        } else {
            // next item cannot use the leftover well: mild penalty
            score += gap * 0.15;
        }
        // If next item is large and this bin would be nearly full, chain is fine.
        if next_item_size >= 60 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: only exactness matters.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // filling them is more valuable than filling loose bins.
    let res = post_residual as f64;
    score += (res - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize the new-bin candidate unless current open bins fit badly.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin still supports lookahead
        }
        // Late in the stream, opening a new bin is cheap; slightly reduce penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // Many open bins with slack: discourage yet another bin.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild penalty for leaving awkward dead space (residual in (10, 25) is hard to reuse
    // given items are >= 1 but commonly mid-sized).
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - res) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual relative to capacity).
    score -= 0.5 * (1.0 - post_residual as f64 / cap) * cap;

    // Penalize large dead space: residual too small for any future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Perfect pairing: post_residual exactly matches next item.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // New bin baseline: its raw residual is cap, so it starts high;
        // add extra penalty that fades late in the stream when consolidation matters less.
        score += 15.0 * pressure * (1.0 - 0.3 * progress);
        // But if the item is huge relative to mean residual, opening fresh may be wise.
        let mean_fit = mean_residual - item_size as f64;
        if mean_fit < 0.0 {
            score -= 18.0;
        }
    }

    // Mild preference for bins already below mean residual (balancing load).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.1 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: minimize post residual (best fit), normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // later, strongly penalize wasted space.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress) + pr_norm * progress * progress;
    score += poly * 20.0;

    // Reward tight fits: item filling most of the bin
    let fill = it / r.max(1.0);
    score -= fill * fill * 5.0;

    // Penalize creating residual that no small future item can use well
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            // next item won't fit here; residual is dead space for lookahead
            score += 3.0 + 2.0 * (1.0 - progress);
        } else {
            // lookahead fits exactly-ish: reward
            let diff = (pr - nx) / cap;
            score -= 2.0 * (1.0 - diff);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Many open bins: encourage consolidation onto existing bins
    let ob = open_bins_count as f64;
    score += (ob / (ob + 5.0)) * (pr / cap) * 4.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (pr - mean_residual) / cap * 3.0;

    // New-bin candidate: keep neutral baseline, slightly penalized unless
    // current fit is terrible (large post residual) or stream is early
    if bin_residual == bin_capacity {
        score = 0.5 + 0.5 * (1.0 - progress) + pr_norm * 2.0;
        if fitting_bins_count == 1 {
            score += 20.0; // never open new bin when a unique fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // --- Harmonic classes of post_residual (dead-space taxonomy) ---
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else {
        // Quarter-class of residual relative to capacity.
        let quarter = (pr * 4) / bin_capacity;
        score += match quarter {
            0 => 35.0, // tiny sliver: nearly dead space
            1 => 12.0, // small but reusable
            2 => 4.0,
            _ => 0.0,  // large residual: flexible
        };
        // Hard-dead class: residual smaller than the minimum item size.
        if pr < 10 {
            score += 45.0;
        }
        // Modulo arithmetic: residuals that are exact multiples of common
        // item-size steps (10) pair well with future items.
        if pr % 10 == 0 {
            score -= 10.0;
        }
        // Integer-division thresholds: residual divisible into halves/quarters
        // of capacity is structurally reusable.
        if pr != 0 && (bin_capacity % pr == 0 || bin_capacity % (pr / 2.max(1)) == 0) {
            score -= 6.0;
        }
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0; // next item perfectly consumes this bin
        } else if next_item_size <= pr {
            score -= 22.0; // next item still fits after placement
        } else if next_item_size > pr && next_item_size <= bin_residual {
            score += 6.0; // next item would break this bin's pairing
        }
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 {
        score -= 30.0; // only this bin can take the item
    } else if fitting_bins_count > 1 {
        score += 3.0 * ((fitting_bins_count as f64 - 1.0).min(5.0));
    }

    // --- Prefer filling already-open bins deeply ---
    score -= (bin_capacity - bin_residual) as f64 * 0.12;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            // No real alternative: opening a new bin is fine.
            score -= 20.0;
        } else {
            // Other bins fit: only open new bin if all alternatives leave
            // terrible residuals (proxy: mean residual already high means
            // open bins are loose, so spreading is acceptable).
            score += 55.0 - (mean_residual * 0.15).min(40.0);
        }
        // Late in the stream, avoid bin proliferation.
        if total_items > 0 {
            let t = step_index as f64 / total_items as f64;
            score += 25.0 * t;
        }
    }

    // --- Stream progression: tighten packing as we advance ---
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score += pr as f64 * 0.08 * t;
    }

    // Mild open-bin pressure: with many open bins, favor consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1, but
    // practically small gaps < ~20 are hard to reuse) are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 - 3.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits: post_residual small relative to item.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: mild penalty if we leave a large gap.
            score += 0.05 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 15.0 + 10.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base score plus pressure; only attractive when
        // the item fits perfectly (post_residual == 0 gives reward elsewhere)
        // or existing fits are terrible.
        score += new_bin_penalty;
        if item_size == bin_capacity {
            score -= 100.0; // full-capacity item must go in a new bin
        }
    } else {
        // Slight reward for using existing bins, scaled by how average the
        // bin's residual is (prefer bins near the mean to consolidate gaps).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // good: next item fits, reward proportional to tightness of the chain
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 - 0.5 * chain_waste;
        } else {
            // next item won't fit here: penalize dead space that can't be used
            score += 20.0;
        }
    } else {
        // last item: prefer minimal post_residual
        score += 0.1 * post_residual as f64;
    }

    // Relative to mean residual: bins below mean residual are tighter -> prefer them
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if no open bin can fit at all, opening is fine
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference for filling older bins when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness coupling: penalize leftover space proportionally to how "full" the placement was.
    let fill_ratio = item_size as f64 / cap;
    score += fill_ratio * (post_residual as f64 / cap) * 12.0;

    // Lookahead: reward bins whose post-residual can host the next item (chain packing).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 15.0;
    }
    // Dead-space penalty: post-residual too small for the next item is likely wasted.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += post_residual as f64 * (0.15 + 0.25 * progress);
    }

    // Last-chance bonus: only one bin fits; strongly prefer avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless the item is large (opening bins for big items is fine)
    // or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 - fill_ratio * 25.0;
        score += base_penalty + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Prefer bins that are tighter than the fleet mean (consolidate waste).
    score += (mean_residual - bin_residual as f64) * 0.08;

    // Late in the stream, be greedier about exact fills.
    if post_residual == 0 {
        score -= 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling: waste penalty grows super-linearly
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score += 40.0 * pr_norm * pr_norm * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * tightness;

    // Lookahead: penalize post_residual that can't host the next item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 18.0 * fits_next * (1.0 - 0.5 * progress);
        // Smooth partial credit: how much of next item fits
        let frac = (post_residual as f64 / next_item_size as f64).min(1.0);
        score -= 10.0 * frac * frac;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // Penalize bins whose residual deviates far from the mean (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 12.0 * dev * dev;

    // New-bin candidate: encourage opening fresh bins early, discourage late
    if bin_residual == bin_capacity {
        score += 8.0 + 45.0 * progress * progress;
    }

    // Mild load-balancing: fewer open bins is better
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // fraction of capacity left

    // Penalize "dead" residuals that are too small to be useful (below min item size 1..100 -> small class).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score += 80.0; // tiny unusable sliver -> heavy penalty
    }

    // Modulo-style harmonic classes on post_residual
    let m = post_residual % 25;
    score += match m {
        0 => -25.0,        // residual in 25/50/75 classes: highly reusable
        1..=5 => 15.0,
        6..=12 => 5.0,
        13..=18 => -5.0,
        _ => 0.0,
    };

    // Integer division thresholds: residual in [50,100] is "half-bin class", good.
    let half_class = post_residual / 25; // 0..=4
    score -= (half_class as f64) * 6.0;

    // Lookahead coupling: reward residuals that can host the next item exactly / well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 45.0; // next item fills this bin exactly
            } else if slack < 10 {
                score += 20.0; // next item leaves sliver
            } else {
                score -= 12.0;
            }
        } else {
            // next item cannot fit here; residual should be as small as possible
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fractional-capacity penalty: residual between 10% and 25% of capacity is awkward.
    if frac > 0.10 && frac < 0.25 {
        score += 18.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - post_f) * 0.5;

    // Slight preference to keep bin count low late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // New-bin candidate: only attractive when nothing decent fits.
    if bin_residual == bin_capacity {
        score = 140.0 - (fitting_bins_count as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (next_item_size as f64) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // by typical future items are heavily penalized.
    let r = post_residual as f64;
    if r > 0.0 && r < 10.0 {
        // Unusable sliver: worst possible dead space.
        score += 60.0 + (10.0 - r) * 4.0;
    } else if r < 20.0 {
        // Likely unusable for mid-size items.
        score += 25.0;
    } else if r < 35.0 {
        // Marginal zone.
        score += 8.0;
    } else {
        // Large residual is valuable; reward keeping it.
        score -= (r - 35.0) * 0.15;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Fit quality: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Open-bins pressure: discourage spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 35.0 + mean_residual * 0.5 + pressure;
        score += new_bin_penalty;
        // If nothing else fits well, new bin becomes attractive:
        if post_residual == bin_capacity - item_size {
            // residual after placing in fresh bin
        }
    }

    // Lookahead: if the next item fits into post_residual, this placement
    // chains nicely; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        // Dead space that the next item cannot use.
        score += 5.0;
    }

    // Deviation from mean residual: prefer bins close to mean to keep balance.
    score += (r - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 900.0;
    }

    // If post residual can still host the next item, mild reward scaled
    // by how much slack remains (prefer tight chained fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: post residual too small for next item — penalize
        // proportionally to wasted fraction of capacity.
        score += 30.0 + 0.4 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than the current mean residual (good fits),
    // penalize bins looser than mean (they remain useful for future items).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when existing bins are poor fits,
    // i.e. its raw post_residual stands on its own; add a mild penalty so that
    // any decent existing fit beats opening a new bin.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
    }

    // Slight preference to fill bins with larger residual when many bins open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual), especially exact/near-exact.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual < 10 {
        score -= 8.0; // actually near-perfect fit, keep reward
    } else if post_residual < 20 {
        score += 6.0; // awkward sliver
    }

    // Lookahead: reward if next item fits in the post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize mildly, more if waste is large.
            score += 2.0 + 3.0 * ((post_residual as f64) / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer zero-waste placement.
        score -= 15.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: penalize opening a new bin when good alternatives exist,
    // but allow it when current bins are crowded / residuals are low.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        let pressure = 1.0 - avg_fit; // high when open bins are mostly full
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - pressure);
        score += 6.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);
        // If next item is large and current bins are tight, opening fresh is fine.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0 * pressure;
        }
    }

    // Prefer spreading across many open bins when residuals are high (balance load).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild time-horizon modulation: early on, be conservative with new bins;
    // later, prioritize tight fits even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let isz = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: penalize residuals that are hard to fill later.
    let pr_norm = pr / cap;
    score += 30.0 * pr_norm * pr_norm * (1.0 - pr_norm);

    // Tight fits are strongly rewarded (smooth quadratic in fill ratio).
    let fill = isz / br;
    score -= 12.0 * fill * fill;

    // Stream progress: late in the stream, prefer tighter packing more aggressively.
    score -= 10.0 * progress * fill;

    // Dead space relative to mean residual across open bins (smooth interaction).
    score += 4.0 * (pr - mean_residual) / cap * (1.0 + progress);

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            // Smooth penalty proportional to how badly next item misses.
            score += 5.0 * ((-gap) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: empty bin should only win when no good fit exists.
    if br >= cap - 0.5 {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    // Mild regularization against too many open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which eighth of the capacity does the
    // leftover space fall into? Dead space in the lowest classes (tiny leftovers)
    // is nearly unusable, so penalize it super-linearly.
    let eighth = (bin_capacity / 8).max(1) as f64;
    let class = (post_residual as f64 / eighth).floor().min(7.0);
    let class_weight = match class as u32 {
        0 => 3.0,               // post_residual < C/8 : dead space
        1 => 1.5,
        2 => 0.5,
        3 => -0.5,              // ~C/2 : classic "fits many things" sweet spot
        4 => -1.0,
        5 => -0.5,
        6 => 0.25,
        _ => 0.0,
    };
    score += class_weight * eighth;

    // Integer-division thresholds: does the leftover exactly admit a "nice" fraction?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 12.0; // perfect fill
    } else if post_residual <= quarter / 2 {
        score += 6.0; // sliver leftover
    } else if post_residual == half {
        score -= 5.0; // exactly half-full: maximally reusable
    } else if post_residual % quarter == 0 {
        score -= 3.0; // harmonic alignment
    }

    // Lookahead coupling: reward leftovers that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 + 2.0 * (slack / bin_capacity as f64);
        } else {
            // leftover too small for the next item: penalize proportionally
            score += 2.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins would
    // leave tiny dead space; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        score += 10.0
            + open_bins_count as f64
            + 0.5 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // a fresh bin always hosts the next item
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
    }

    // Mild waste aversion relative to mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Late in the stream, tighten packing (favor fuller bins) slightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure loss.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // impossible gap (shouldn't occur, but guard)
    }

    // Non-linear dead-space penalty: small gaps (< 10) are highly unusable.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 12.0;
        } else if pr < 20.0 {
            score += (20.0 - pr) * 3.0;
        }
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Reward if the next item can fit into the post_residual (lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward for a near-perfect two-item pairing.
        let pair_slack = post_residual - next_item_size;
        if pair_slack < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how close we are.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and penalize creating more bins / leaving many loose residuals.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 1.5;

    // Mean residual coupling: if open bins already have lots of slack,
    // penalize adding another slack residual; encourage consolidation.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;
    if mean_residual > 40.0 {
        score += 8.0; // bins are loose already, discourage spreading
    }

    // New-bin candidate (empty bin): only attractive when no good existing fit.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0 + open_pressure * 2.0;
        // But if existing bins would leave a tiny dead gap, opening fresh is better.
        if post_residual < 10 {
            score -= 60.0;
        }
        // Late in the stream, consolidating is more important.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual consumed relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-match_gap / 10.0).exp(); // strong bonus for exact match
        // Penalize leaving residual that is too small for next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward leaving residual exactly usable by next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: minimize waste only
        score += 0.0;
    }

    // Compare post_residual against mean residual: keep bins balanced
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0;
        // Opening a new bin is fine if next item is large and nothing matches
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild preference to consolidate into fewer bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (open_bins_count as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strong discount when item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty scaled by how much of post_residual is wasted.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving small unusable slivers (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Global state: when many bins are open with high mean residual,
    // encourage consolidation into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * (mean_residual / bin_capacity as f64) * (0.5 + progress);
    }

    // New empty bin candidate: normally costly, but attractive when this
    // item is large and would leave a bad sliver, or no bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 70 {
            score -= 35.0; // large items justify fresh bins
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        score += 10.0 * (open_bins_count as f64).sqrt();
    }

    // Mild time-horizon modulation: early on, be frugal with new bins;
    // late, prefer exact packing regardless of bin count.
    score -= 6.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // base: penalize post residual, with non-linear shaping
    let mut score = pr as f64;
    score += 20.0 * x * (1.0 - x) * (1.0 + t);

    // waste coupling: small post-residual relative to item size is good
    score -= (item_size as f64) * (1.0 - x).powi(2);

    // lookahead: reward bins leaving room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 15.0 * (-gap / 25.0).exp();
        score += 5.0 * (pr / (pr + nxt)).exp() * t;
    }

    // last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * t;
    }

    // many fitting bins: mild penalty for wasting a scarce-large bin
    if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // mean residual interaction: prefer bins near mean residual early, diverge late
    score += (pr - mean_residual).abs() * (0.3 + 0.7 * t);

    // stream progress: tighten packing later
    score *= 1.0 + 0.5 * t * t;

    // new-bin candidate: penalize opening new bins unless residual is unusable
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - t) + 0.15 * open_bins_count as f64;
        if post_residual > 0 && (item_size as f64) / cap < 0.5 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by 10 are prime targets for future items (sizes 1..100,
    // but common sizes cluster on multiples of 5/10 in typical streams).
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -8.0,           // perfectly harmonic leftover
        5 => -4.0,           // half-harmonic leftover
        _ => (class as f64) * 0.6, // ragged leftover penalty grows with distance
    };
    score += class_penalty;

    // Integer-division thresholds: small post_residual is dead space.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual < eighth {
        score += 25.0; // nearly-full bin: great, but only if it was a real fit
    } else if post_residual <= quarter {
        score -= 5.0;  // tight fit is good
    } else if post_residual > bin_capacity / 2 {
        score += 6.0;  // leaving more than half empty wastes the bin
    }

    // Perfect fit detection: post_residual can absorb a harmonic fraction.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual <= quarter {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it
    // only when no open bin offers a good (harmonic) fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and
        // how many bins are already open.
        score = 45.0 + 0.15 * (open_bins_count as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score *= 1.0 - 0.2 * progress;
        // If next item is small, a fresh bin with large residual is attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
        // If the current item leaves a harmonic residual in an existing bin,
        // opening a new bin is unattractive (raise its score).
        if post_residual % 10 == 0 {
            score += 15.0;
        }
    }

    // Lookahead coupling: if the next item exactly matches post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
            // harmonic match on modulo class
            if (next_item_size % 10) == class {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; slight penalty for tight residual
            score += 2.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (filling the emptiest bins first keeps many usable bins open).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Early-stream tiebreak: keep scores slightly varied for stable selection.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost useless.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Unusable sliver: heavy penalty scaled by how close to zero.
            score += (10.0 - gap) * 8.0;
        } else if gap <= 20.0 {
            // Small gap: hard to fill with future items (sizes >= 10).
            score += (20.0 - gap) * 2.0;
        }
    } else {
        // Perfect closure: strong reward.
        score -= 40.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids wasting residual elsewhere).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few -> allow.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 1.5;

    // Prefer bins below mean residual (consolidate emptiness into few bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly into post_residual, big reward;
    // if it can't fit at all, mild penalty (dead space relative to lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt as u32 == post_residual {
            score -= 50.0;
        } else if nxt <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate: only attractive when residuals of open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open/late stream.
        score += 30.0 - pressure * 0.5;
        // Attractive if this item is large relative to capacity (hard to place later).
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward exact fit for next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Penalize leaving a gap that cannot hold the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Reward tight fits relative to bin capacity.
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    // Compare against mean residual: prefer bins that get closer to zero residual.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_gap * (post_residual as f64 / mean_residual.max(1.0));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            (fitting_bins_count as f64).recip()
        };
        let tightness = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for large items or when alternatives are bad.
        score = 40.0 - 30.0 * tightness - 25.0 * pressure
            - 20.0 * (post_residual as f64 / bin_capacity as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin keeps room for the next item too.
            score -= 15.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Mild time decay: prefer consolidating early, be freer later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (dead-space avoidance).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    } else {
        // Penalize small unusable leftovers quadratically.
        let r = post_residual as f64;
        score += (r * r) / cap;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: opening a bin is expensive unless the item is large
    // (leaving little residual) or many open bins are already fragmented.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        let fragmentation = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins; the penalty shrinks for large items and fragmented states.
        let penalty = 80.0 * (1.0 - fill_ratio) * (1.0 - 0.5 * fragmentation) * (1.0 - 0.3 * progress);
        score += penalty;
        // Discourage opening new bins when a decent fit already exists.
        if fitting_bins_count > 0 {
            score += 40.0 / fitting_bins_count as f64;
        }
    } else {
        // Prefer tighter bins: reward small bin_residual relative to capacity.
        score -= (cap - bin_residual as f64) * 0.1;
    }

    // Mild preference to balance: avoid dumping into bins with tiny residual when
    // mean residual is large (keep big holes for big future items).
    if (bin_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;

    // Base: prefer tight fits (small post_residual), with progress-dependent shaping.
    let mut score = post * (0.6 + 0.8 * prog2);

    // Dead-space penalty: residuals too small for typical future items are waste.
    let dead = ((24.0 - post).max(0.0)) / cap;
    score += dead * dead * 30.0 * (1.0 - 0.3 * progress);

    // Reward near-perfect packing.
    if post < 4.0 {
        score -= 20.0 * (1.0 - post / 4.0);
    }

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among several candidates, prefer the fullest (smallest post already does this),
        // but add mild penalty for spreading across bins.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead coupling: reward if next item fits in the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (nxt / cap) * (1.0 - 0.5 * progress);
            // extra reward for exact chain fit
            let slack = post - nxt;
            if slack <= 5.0 {
                score -= 6.0;
            }
        } else {
            // penalize leaving residual that can't host the next item
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // Mean-residual context: if open bins are mostly full, slightly favor reusing them.
    score -= (mean_residual / cap) * 4.0;

    // New-bin candidate handling: opening a new bin wastes all existing residual space.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Base cost of a new bin: grows as existing bins become unusable.
        score += 40.0;
        // If no open bin truly fits, opening is fine (relief).
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 15.0 * progress;
        // Large items justify a fresh bin more than small ones.
        score -= (item / cap) * 20.0;
    }

    // Mild smooth coupling of item size with progress (favor big items early).
    score -= (item / cap) * (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "useful"
    // classes (small leftovers), penalize mid-range dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 25.0;
    } else if pr <= 30 {
        score -= 5.0;
    } else if pr <= 50 {
        // dead zone: residual too big to waste, too small to be valuable
        score += 15.0;
    }

    // Modulo-10 harmonic class: residuals divisible into coarse classes pair
    // well with items in the 10..80 range (multiples of 10 common).
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: can a future item of typical size fit?
    // Reward if post_residual can hold next_item_size (chaining lookahead).
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 20.0;
            // exact modular match: next item leaves another harmonic residual
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            if next_post == 0 {
                score -= 40.0;
            }
        } else {
            score += 8.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if many bins are open with low mean residual, prefer consolidation
        score += (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can serve the next item too
        }
    }

    // Late in the stream: prefer tighter packing, discourage sprawl.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Mild pull toward bins whose residual is close to item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += snug * 0.1;

    // Penalize bins far below mean residual (fragmentation risk).
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are "dead" — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 25.0; // awkward narrow gap
    } else if post_residual > 60 {
        score -= 15.0; // large residual stays flexible
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual tightly matches the item (best-fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new one is cheaper.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / (1.0 + total_items as f64));
    score += pressure * 1.5;

    // Prefer bins below mean residual when many bins are open (balance load),
    // prefer high-residual bins when few bins are open.
    if open_bins_count > 4 {
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 10.0; // next item can't use this bin's remainder
        }
    }

    // New-bin candidate: only attractive when item is large relative to
    // capacity or current bins are all fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let base = bin_capacity as f64 - item_size as f64;
        if fragmentation < 0.35 || item_size > 70 {
            score -= 20.0;
        } else {
            score += base * 0.3 + 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot use the residual: penalize dead space
            score += 10.0 + 0.3 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Compare post_residual relative to mean residual of open bins
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev; // leaving more than average waste is bad
    } else {
        score += 0.05 * dev; // slight reward for below-average waste
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin if current bin would leave tiny awkward residual
        if post_residual > 0 && post_residual < 10 {
            score -= 50.0;
        }
    }

    // Early in stream: be more open to new bins; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress; // late-stage: prefer filling existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty so small leftovers dominate.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // If next item would NOT fit but nearly does, mild penalty for wasting pairing potential.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins exist with decent residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        let mut new_bin_score = 30.0 + crowding * 2.0;
        // Late in the stream, prefer consolidation into open bins.
        new_bin_score += 40.0 * progress;
        // If no open bin fits well (post_residual tiny relative to item), opening is fine.
        score += new_bin_score;
        // But if this is the very first bin, it's mandatory.
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Global balance: prefer bins whose residual deviates favorably from the mean.
    let diff = bin_residual as f64 - mean_residual;
    score -= 0.3 * diff;

    // Mild preference to fill bins that are already quite full.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Dead-space guard: leftover too small for the minimum item size (1..100 range => >=1).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by a smooth non-linear progress coupling
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty for awkward residual sizes (dead space):
    // penalize residuals that are small-but-not-tiny via a smooth bump
    let bump = (norm_pr * std::f64::consts::PI).sin();
    score += 6.0 * bump * bump * (0.5 + 0.5 * progress);

    // Reward tight fits (small post residual) with smooth decay
    score -= 12.0 * (-norm_pr * 6.0).exp();

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 8.0 * g * (1.0 - g) * 4.0; // smooth concave reward
        } else {
            score += (-gap) * 0.3; // penalize blocking the next item
        }
    }

    // Last-chance bin: strongly favor using it when it fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * (open_bins_count as f64).ln() * (0.3 + 0.7 * progress);

    // Prefer bins with residuals near the mean (smooth regularity term)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make empty bins mildly unattractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Perfect fits (post_residual == 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Small post_residuals are only useful if next_item_size can use them.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Lookahead fits exactly into the leftover: strong reward.
                if next_item_size == post_residual {
                    score -= 120.0;
                } else {
                    score -= 8.0 + (post_residual as f64).ln() * 4.0;
                }
            } else {
                // Leftover dead space relative to the lookahead item.
                let gap = (next_item_size - post_residual) as f64;
                score += gap * gap * 0.02;
            }
        }

        // Modulo-class penalty: residuals that are awkward fractions of capacity
        // (not multiples of 10/25) tend to be dead space.
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        // Integer-division thresholds: classify leftover size.
        let cls = pr / 10; // 0..=9
        score += match cls {
            0 => 30.0,          // 1..9: nearly dead
            1 => 12.0,          // 10..19
            2 => 2.0,           // 20..29
            3 => -2.0,          // 30..39
            _ => 0.0,
        };

        // Penalize tiny residuals more when many bins are open (fragmentation).
        if pr < 20 && open_bins_count > 3 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual < bin_residual {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when current fit is very poor
    // (item barely fits or leaves a huge, awkward residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline mild preference against opening new bins.
        score += 25.0;
        // But if the item leaves a large residual in an existing bin that is
        // still unlikely to be used (high mean residual), opening fresh is fine.
        if bin_residual - item_size <= 5 {
            score -= 60.0; // item ~ fills a fresh bin: excellent
        }
        if mean_residual < 15.0 && open_bins_count > 0 && post_residual > 40 {
            score -= 20.0;
        }
    } else {
        // Reward tighter fits in existing bins.
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= tightness * 10.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual), but strongly punish
    // small *unusable* dead space (1..=9) since nothing (min size 1... but
    // practically small items) can reclaim it reliably.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 50.0; // perfect fill: heavily reward
    } else if post_residual <= 9 {
        score += 60.0; // dead space penalty: gap too small to be useful
    } else {
        score += pr; // larger gaps are reusable, mild penalty
    }

    // Reward filling bins that are relatively emptier-than-average poorly:
    // prefer placing into bins whose residual is close to item_size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Open-bin pressure: when many bins are open, favor consolidation
    // (placing into existing bins) over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    // (i.e., current bin's post_residual is dead space or next item won't fit).
    if bin_residual == bin_capacity {
        let next_fits_current = next_item_size > 0 && post_residual >= next_item_size;
        if post_residual <= 9 || !next_fits_current {
            score -= 15.0; // opening fresh bin is fine when fit is bad
        } else {
            score += 80.0; // discourage abandoning a usable gap
        }
        // Early in stream, new bins are cheap; later, consolidation matters.
        score += 20.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 9 {
        score += 25.0; // would leave dead space for the next item
    }

    // Mild tie-break toward bins below mean residual (balance load).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead-space penalty: leftover too small for the next item (or any plausible item).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable sliver
    }

    // Compare against mean residual: placing into a bin with residual far below mean
    // (a tight bin) is efficient; a very roomy bin can stay for bigger items.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 8.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 6.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it would host a large item well
    // and existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let mut penalty = 12.0 + 3.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is reasonable.
        penalty -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If some open bin would end with a near-perfect next-item fit, discourage new bin.
        if next_item_size > 0 && post_residual == next_item_size {
            penalty += 100.0;
        }
        score += penalty;
    }

    // Late in the stream: consolidate harder, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if the next item fits into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 20.0 * chain_tightness;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize proportionally
        // to how "dead" the leftover space is (below half the next item).
        let dead = (next_item_size - post_residual) as f64;
        if post_residual * 2 < next_item_size {
            score += 0.5 * dead;
        }
    }

    // Last-chance bin: if this is the only bin that fits, reward heavily
    // to avoid opening a new bin for a placeable item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses
        // (late in the stream, leftover bins are less costly to open).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - 0.5 * progress);
        // If many open bins have large mean residual, opening new bins is wasteful.
        score += 0.3 * mean_residual;
        // Few fitting bins -> new bin more acceptable.
        score -= 2.0 * fitting_bins_count as f64;
    } else {
        // Reward using bins whose residual is above the mean (drain large holes).
        score -= 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 0.5 * open_bins_count as f64;

    // Small progress-adaptive tie-breaker toward tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * progress * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.3 + progress);

    // Lookahead coupling: favor bins whose post-residual matches next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (pr - norm_next * cap).abs();
        score -= 15.0 * (1.0 - diff / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 8.0 * progress * (norm_next - norm_pr).abs();
    }

    // Penalize waste relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many are open late in stream
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * open_bins_count as f64 * (0.2 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual ----
    // Residuals are grouped into "harmonic classes" via integer division on
    // fixed fractions of capacity. Tiny residuals (class 0) are ideal.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let class = pr / 10; // 10-wide harmonic bands: 0..=10

    match class {
        0 => score -= 40.0,                 // near-perfect fit (0..10)
        1 => score -= 25.0,                 // excellent (10..20)
        2 => score -= 12.0,                 // good (20..30)
        3 => score -= 5.0,                  // acceptable (30..40)
        4 => score += 3.0,                  // marginal (40..50)
        5 => score += 10.0,                 // half-empty bin (50..60)
        _ => score += 18.0 + (class as f64),// wasteful dead space
    }

    // Exact-fit bonus: filling the bin completely is always optimal.
    if pr == 0 {
        score -= 100.0;
    }

    // ---- Modulo-arithmetic lookahead coupling ----
    // If the next item lands exactly in the post residual's harmonic band,
    // reward chains where post_residual % 10 aligns with next_item_size % 10.
    if next_item_size > 0 {
        let nmod = next_item_size % 10;
        let pmod = pr % 10;
        if next_item_size <= pr {
            // Next item fits in this bin's future residual: strong chain reward.
            score -= 15.0;
            if nmod == pmod {
                score -= 8.0; // harmonic alignment: clean modular stacking
            }
            // Reward when next item's class matches residual class exactly
            if next_item_size / 10 == pr / 10 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual; penalize locking bad space.
            score += 6.0 + (pr as f64) * 0.05;
            if pmod > nmod && pmod < 10 {
                score += 4.0; // misaligned modulo: dead space is sticky
            }
        }
    }

    // ---- Last-chance dynamics ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; avoid opening a new bin unless
        // the fit would be catastrophically wasteful.
        if pr <= 30 {
            score -= 30.0;
        } else {
            score += (pr as f64 - 30.0) * 0.4;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh bin: base attractiveness depends on stream progress and
        // congestion of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55; // neutral base
        score -= progress * 20.0;              // later: reuse bins more
        score -= (open_bins_count as f64) * 2.0; // many open bins: consolidate
        // Open a new bin when no existing bin fits well (all residuals small).
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // If the mean residual is large, prefer existing bins over a new one.
        score += mean_residual * 0.6;
        // Harmonic tie-break: opening a bin whose capacity is a "clean"
        // multiple band of typical item sizes (10s and 20s) is fine.
        if item_size % 20 == 0 {
            score -= 3.0;
        }
    }

    // ---- Mild global regularization ----
    score += (mean_residual - post_residual as f64) * 0.1;
    // Slight preference to pack into fewer bins as stream progresses.
    score += (open_bins_count as f64) * 0.5;
    score -= progress_proxy(step_index, total_items) * 2.0;

    score
}

#[inline]
fn progress_proxy(step_index: usize, total_items: usize) -> f64 {
    if total_items == 0 { 0.0 } else { step_index as f64 / total_items as f64 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap of 1 => +56, gap of 9 => +24
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fits (large fill ratio) are favored.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; tolerate opening new bins when few are open.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * snug;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is the only option.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0 + bin_pressure * 3.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            score += base_penalty;
        }
    }

    // Late in the stream, consolidation matters slightly more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild preference toward bins near the mean residual state.
    score -= 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item's size (perfect chaining), scaled by lookahead size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Exact match gets a big discount; near matches get proportional discount.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        }
        // Penalize leaving residual too small for next item (dead space).
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - post_residual as f64 / next);
        }
    }

    // Relative-to-mean coupling: bins with residual well below mean are
    // already well-utilized; finishing them off is good.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Opening a new bin has an inherent cost.
        score += 20.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins are open and fragmented, a new bin is less harmful.
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Late-stream pressure: consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect chained fit
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins -> prefer consolidation into existing bins.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual != bin_capacity {
        score -= 3.0 * pressure * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when existing fits are poor or stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (100.0 - fill_ratio * 100.0) / 100.0;
        score += 18.0 * (1.0 - poor_fit); // base cost of opening a bin
        score -= 10.0 * (1.0 - progress); // cheaper to open early when plenty of stream remains
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0; // room for a chained pair
        }
        if open_bins_count > 0 && fill_ratio > 0.9 {
            score += 30.0; // never open when an excellent fit exists
        }
    }

    // Mild time-horizon coupling: late in stream, waste hurts more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Non-linear reward for tight fits: cubic coupling of fill with post residual
    score -= fill * fill * fill * (bin_capacity as f64) * 0.8;

    // Penalize large post-residuals quadratically (dead space), smoothed by progress
    score += post_frac * post_frac * (bin_capacity as f64) * (0.3 + 0.5 * progress);

    // Reward bins whose residual is close to mean (balance), non-linear coupling
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev.abs() * (1.0 + progress) * 2.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            let gap = (post_residual as f64 - nx) / bin_capacity as f64;
            score -= (1.0 - gap) * 5.0 * (1.0 - progress);
        } else {
            // post residual can't host next item: penalize proportionally
            score += (nx - post_residual as f64) / bin_capacity as f64 * 2.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // mild penalty proportional to competition to prefer best fit among many
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // New-bin candidate: discourage opening new bins early, allow late in stream
    // or when open bins are nearly full (mean residual low)
    if bin_residual == bin_capacity {
        let mean_pressure = 1.0 - (mean_residual / bin_capacity as f64);
        let openness = (progress * 0.6 + mean_pressure * 0.4).clamp(0.0, 1.0);
        score += 10.0 * (1.0 - openness) - openness * 2.0;
    }

    // Many open bins: favor consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * post_frac * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

