    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Compare against mean residual: bins below mean are "drier", prefer them
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let huge = item_size as f64 > 0.75 * bin_capacity as f64;
        let poor_options = fitting_bins_count == 0 || (fitting_bins_count == 1 && bin_residual - item_size > 40);
        if huge || poor_options {
            score -= 20.0;
        } else {
            score += 15.0; // discourage wasting fresh bins on easy fits
        }
    }

    // Modulo coupling between item size and capacity: items in harmonic
    // resonance with capacity (dividing it evenly) pack predictably.
    if bin_capacity % item_size == 0 && post_residual % item_size == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Slight penalty per open bin to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item (or the
    // minimum possible item) are nearly unusable -> heavy penalty.
    let min_item = 1u32;
    let dead_threshold = next_item_size.max(min_item);
    if post_residual < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual) as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 2 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: bins far below the mean residual are looser;
    // filling them wastes less elsewhere.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0 * (mean_residual - post_residual as f64) / (bin_capacity as f64);
    }

    // Lookahead: if next item exactly matches post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item cannot be packed well
    // anywhere (large item, tight current bin) or late in the stream with few bins.
    if bin_residual == bin_capacity {
        let late = step_index as f64 / (total_items.max(1) as f64);
        let tight = (item_size as f64 / bin_capacity as f64) > 0.8;
        if tight || fitting_bins_count == 0 {
            score -= 12.0 + 10.0 * late;
        } else {
            score += 15.0 + 10.0 * (1.0 - late);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // next item can follow in this bin: reward tight chain
            score -= 60.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize by gap size
            score += 0.5 * match_gap;
        }
        // Bonus if post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 120.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when a decent fit exists in open bins
    if bin_residual == bin_capacity {
        score += 150.0;
        // new bin is attractive if no open bin fits well (post_residual large waste)
        if post_residual as f64 > mean_residual + 10.0 {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate, avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // Prefer filling bins when many open bins exist
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements leaving little residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward for near-exact chaining (item + next fills bin).
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else if next_item_size > post_residual + item_size {
            // Next item is large and won't fit here anyway; slight penalty
            // for squandering space a big item might need elsewhere.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable residuals (dead space) relative to
    // typical item sizes: residual below ~10 is hard to reuse.
    if post_residual < 10 {
        score -= 4.0; // perfect fill is great
    } else if post_residual < 20 {
        score += 3.0; // awkward sliver
    }

    // Global state coupling: prefer filling bins when many bins are open
    // (consolidation) to avoid bin proliferation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (1.5 + 3.0 * progress);

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (keeps pool homogeneous) unless it's a very tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tightness);

    // New-bin candidate: penalize opening a new bin unless existing fits are
    // terrible (large post_residual) or few bins are open.
    if bin_residual == bin_capacity {
        let escape = if post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 { 20.0 } else { 0.0 };
        score += 18.0 - escape - 4.0 * (1.0 - progress) - (fitting_bins_count as f64).min(4.0) * 2.0;
    }

    // Slight preference early in stream for keeping residuals flexible.
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = post / cap * (1.0 + t * (post / cap) * (1.0 - t) * 2.0);
    score = score * 0.5 + poly * 0.5;

    // Penalize large dead space more aggressively late in the stream.
    let dead = (post / cap).powi(3);
    score += dead * (0.5 + t);

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * tightness * 0.8;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0 + t;
    }

    // Lookahead: bonus if next item fits the projected residual well.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score += (gap / cap) * 0.6;
        if next_item_size as f64 <= post {
            score -= 0.4 * (1.0 - t);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * (post / cap) * 0.15;

    // Deviation from mean residual: prefer bins near the mean to keep balance.
    score += ((post - mean_residual) / cap).abs() * 0.2;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = post / cap + 0.3 - 1.5 * (1.0 - (fitting_bins_count as f64).min(1.0));
        score += 0.5 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot sizes" remain usable.
    // Items 1..100, capacity 100. Classify post_residual into harmonic bands.
    let cap = bin_capacity as f64;

    // Base: prefer tight fits — small post_residual is good.
    score = post_residual as f64;

    // Dead-space penalty: post_residual too small to hold typical items (harmonic class 0).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Harmonic class thresholds on post_residual via integer division by 10.
    let class = post_residual / 10; // 0..=10
    // Reward residuals that form nice harmonic fractions of capacity.
    match class {
        0 => { score += 5.0; }              // 0-9: nearly full, great if exact
        1 => { score -= 8.0; }              // 10-19: fits small items
        2 => { score -= 12.0; }             // 20-29: good mid slot
        3 => { score -= 10.0; }
        4 => { score -= 6.0; }
        5 => { score -= 14.0; }             // 50: half capacity, most flexible
        6 => { score -= 4.0; }
        7 => { score += 6.0; }
        8 => { score += 10.0; }
        9 => { score += 14.0; }
        10 => { score += 25.0; }            // untouched bin wasted on small item
        _ => {}
    }

    // Lookahead: does post_residual exactly accommodate next_item_size?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 15.0; // next item nearly fills remainder
            } else {
                score -= (slack.min(30)) as f64 * 0.3;
            }
        } else {
            // next item cannot fit here; penalize leaving residual in that class gap
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current bin
    // would leave a bad harmonic class or bin is fresh.
    if bin_residual == bin_capacity {
        // This is the brand-new bin candidate.
        if item_size >= 50 {
            score -= 20.0; // big items fine in fresh bins
        } else {
            score += 20.0; // prefer packing small items into open bins
        }
    }

    // Many open bins with high mean residual: encourage consolidation into open bins.
    if open_bins_count > 2 && mean_residual > (cap * 0.3) {
        score -= 6.0;
    }

    // Progress modulation: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that cannot fit even the smallest plausible item (or the next item)
    // is pure waste; the smaller the gap, the harsher the penalty.
    let min_useful = if next_item_size > 0 && next_item_size <= bin_capacity {
        next_item_size.min(10)
    } else {
        10
    };
    if post_residual < min_useful && post_residual > 0 {
        // Dead space: gap too small to ever be filled -> strong penalty.
        score += (bin_capacity as f64 - post_residual as f64) * 2.5;
    }

    // Nonlinear dead-space curve: tiny residuals are quadratic bad.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * (20.0 - pr) * 0.15;
    }

    // Reward tight fits (low post_residual) especially when many bins are open.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * 12.0;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + progress * 0.6);
    score += pressure * (pr / bin_capacity as f64);

    // Mean residual coupling: if this bin is far below mean residual, it is
    // already "wasted" relative to the fleet; using it consolidates waste.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= dev * 0.5;
    } else {
        score += (-dev) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin gives a good
    // fit. A fresh bin has post_residual == bin_capacity - item_size, which is
    // large, so the tightness term already penalizes it; add a mild penalty
    // that scales with how many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * fitting_bins_count as f64;
        // But if the item is large, a new bin yields a clean large residual
        // that is still useful — soften the penalty.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact-ish fits (low post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 60.0; // perfect chaining: item + next item fill bin
        } else if (next_item_size as u32) <= post_residual {
            score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow into this residual: penalize dead space
            score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins with residual near the mean (balanced packing),
    // but heavily prefer tighter-than-mean bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bins should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0; // default penalty so open bins are preferred...
        if fitting_bins_count == 0 {
            score -= 100.0; // ...but must open a new bin if nothing fits
        }
        // Late in the stream, opening a fresh bin is less costly (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Lookahead coupling: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap that no single small item likely fills.
            score += 8.0;
        }
    } else {
        // Last item: waste matters maximally.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when existing
    // residuals are large (poor fits available) or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_gap = mean_residual / bin_capacity as f64;
        // Penalize new bins early and when open bins are already tight.
        score += 20.0 + 30.0 * (1.0 - progress) + 40.0 * (1.0 - avg_gap);
        // Slight relief when bin count explodes (encourage consolidation checks).
        score -= (open_bins_count.min(20) as f64) * 0.5;
    } else {
        // Reward placing into bins whose residual is close to the item (best-fit flavor).
        let snugness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= snugness * 10.0;
        // Mild reward for draining fuller bins first (keeps count of half-empty bins low).
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post residual (tight fit), non-linearly.
    let mut score = post;

    // Smooth polynomial coupling of tightness with stream progress:
    // later in the stream, waste is penalized more aggressively.
    let tightness = 1.0 - norm_post; // 1 = perfect fit
    score -= tightness * tightness * (10.0 + 40.0 * progress) * cap * 0.05;

    // Penalize dead space that no plausible future item can use:
    // unusable if post_residual < next item (or below min size 1).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0);
        score += gap * gap * 0.05 * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 50.0 * progress;
    }

    // New-bin candidate: neutral-ish base, penalize opening bins when
    // decent fits exist, more so late in the stream.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.6 * progress) + 0.5 * open_bins_count as f64;
        // If current fit would leave large waste, allow opening a new bin.
        let waste_ratio = post / cap;
        score -= waste_ratio * cap * 1.2 * (0.3 + progress);
    }

    // Mild coupling with mean residual: prefer bins whose residual is close to
    // what we consume (balance across bins).
    let mean_gap = (mean_residual - bin_residual as f64).abs();
    score += mean_gap * 0.1 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (1..100 unknown distribution, so treat < 20 as
    // near-dead) are heavily penalized.
    if post_residual < 20 {
        score += 60.0;
    } else if post_residual < 35 {
        score += 25.0;
    }

    // Reward very tight fits (post_residual close to zero but not dead).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Perfect-fit reward: item exactly fills bin.
    if post_residual == 0 && bin_residual == item_size {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post_residual,
    // reward leaving that exact gap; otherwise penalize a gap the next
    // item almost fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — favor filling it further.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.25;
    } else {
        score += (bin_res_f - mean_residual) * 0.10;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Only
    // make it attractive when the fit in existing bins is poor (large
    // post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // == 1 - item/C
        let mut nb = 30.0 + 45.0 * (1.0 - poor_fit); // tight fits -> new bin unattractive
        if fitting_bins_count <= 1 {
            nb += 80.0; // almost forced to open new bin
        }
        if open_bins_count > 6 {
            nb += 15.0; // avoid bin proliferation
        }
        // Early in stream, allow opening bins more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb -= 20.0 * (1.0 - progress);
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact match of leftover space with the next item's size (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Reward near-match: leftover space that can still usefully host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // Penalize dead space relative to the upcoming item.
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Penalize large post residuals relative to mean residual (wasted space vs fleet average).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit, unless the new bin
    // enables a good lookahead pairing.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 30.0
            + 0.3 * open_bins_count as f64
            + (post_residual as f64 - next_item_size as f64).abs() * 0.4;
        score += new_bin_penalty;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 45.0; // fresh bin pairs perfectly with next item
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small penalty for leaving very thin slivers (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a superlinear term.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness * tightness;

    // Penalize large dead space that nothing small can use later.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // awkward gap zone
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack * 0.15);
        } else {
            score += 4.0; // next item won't fit here after placement
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: many open bins with high mean residual -> discourage opening new bins,
    // encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread = mean_residual - post_residual as f64;
    score += 0.05 * open_bins_count as f64;
    score -= 0.10 * mean_residual * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 { (post_residual as f64) / (bin_capacity as f64) } else { 0.0 };
        let open_pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64);
        score += 30.0 - 20.0 * poor_fit - 15.0 * open_pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild time-decay preference for compact placements later in the stream.
    score *= 1.0 - 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress) + (x * x) * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post residual), stronger later in the stream
    score -= 40.0 * (1.0 - x).powi(3) * (1.0 + progress);

    // Penalize dead space that likely becomes unusable (relative to typical item scale)
    let dead = if pr > 0.0 && pr < 10.0 { 0.0 } else { pr * pr / cap };
    score += 0.3 * dead;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // New empty bin candidate: penalize mildly, less so when no good fit exists
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 15.0 + 5.0 * openness - 10.0 * progress;
    }

    // Lookahead: prefer bins whose residual can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 0.2 * (next_item_size as f64 - pr).max(0.0);
    }

    // Slight penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual
    match post_residual {
        0 => score -= 30.0,
        1..=5 => score -= 12.0,
        6..=10 => score -= 6.0,
        _ => {}
    }

    // Modulo-class penalty: residuals that are awkward fractions of capacity
    let r = post_residual % 25;
    if r != 0 && r < 8 {
        score += (8 - r) as f64 * 1.5;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else if post_residual > 0 && post_residual < 10 {
            // small unusable sliver for next item
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.4 {
            score += 25.0; // prefer reusing fragmented bins
        } else {
            score += 8.0; // mild default penalty for opening new bin
        }
    }

    // Progress-based scaling: be more conservative late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space archetype)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that could fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Mild preference for tighter bins among fits
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.5;
    }
    // Next item does NOT fit after this placement: residual becomes dead space
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.6;
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize residuals far below mean residual (creating unusable small holes)
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 30.0 - (item_size as f64) * 0.2;
    }

    // Late-stream pressure: prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 + open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Tightness reward: strong bonus for near-perfect fits
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Exact-fit jackpot
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // Penalize leftovers that are large but too small for the next item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }
    // Many alternatives: mild penalty for wasting a scarce-fit bin
    if fitting_bins_count > 2 {
        score += 3.0;
    }

    // New-bin candidate: penalize opening new bins, less when current fits are bad
    if is_new_bin {
        let mut penalty = 35.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins
        penalty += 20.0 * progress;
        // If the best alternative residual is bad (high mean residual mismatch), ease penalty
        if mean_residual > (bin_capacity as f64 - item_size as f64) * 0.5 {
            penalty -= 12.0;
        }
        // If next item fits a fresh bin's residual well, ease slightly
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            penalty -= 5.0;
        }
        score += penalty;
    } else {
        // Mild preference for bins with residual close to item (minimize fragmentation)
        let spread = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * spread;
        // Prefer bins whose residual is below mean (fill tighter bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Time-horizon coupling: early stream, be greedy about tight fits; late, conservative
    score -= 10.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic + cubic) shaping of post-residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr) + 20.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in the stream, penalize slack more strongly.
    let progress_coupling = 1.0 + 0.9 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Reward bins whose residual aligns with the mean residual (harmonious bin states).
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // Lookahead coupling: if next item fits in post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let nx_norm = nx / cap;
        let fit_margin = (pr - nx) / cap;
        if fit_margin >= 0.0 {
            score -= 15.0 * fit_margin * (1.0 - nx_norm);
        } else {
            score += 6.0 * (-fit_margin) * nx_norm;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of open bins exist, smoothly in count.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64).sqrt() + 10.0 * (1.0 - progress);
    }

    // Mild penalty for very large current item in a nearly full bin (waste avoidance).
    let item_norm = item_size as f64 / cap;
    score += 4.0 * item_norm * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact-fill classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill, always reward massively
    } else {
        // Modulo-10 harmonic class: residuals divisible by 10 are more reusable.
        let class = pr % 10;
        score -= (10 - class) as f64 * 0.7;

        // Small residuals are dead space: penalize quadratically in the low range.
        if pr < 10 {
            score += (10 - pr) as f64 * (10 - pr) as f64 * 1.5;
        }

        // Integer-division thresholds: residuals in [10, 30] are "half-class" traps
        // unless a small item can consume them.
        if pr >= 10 && pr <= 30 {
            // Reward if the lookahead item fits the residual exactly or nearly.
            if next_item_size > 0 && next_item_size <= pr {
                let waste = pr - next_item_size;
                score -= waste as f64 * 2.0;
                if waste == 0 {
                    score -= 50.0; // lookahead exact fit: chain bonus
                }
            } else {
                score += 12.0; // dead zone with no usable lookahead
            }
        }
    }

    // Capacity-fraction coupling: favor bins whose fill lands on nice fractions.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if (fill_frac * 4.0).round() / 4.0 == fill_frac {
        score -= 8.0; // quarter-capacity harmonic fill
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item leaves a large
    // unharmonious residual in every open bin, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 60.0
            + (next_item_size as f64) * 0.3
            + (1.0 - progress) * 20.0
            - (open_bins_count as f64) * 2.0;
        score -= new_bin_bonus;
        // Penalize opening a new bin if an open bin would fit tightly.
        if post_residual < 20 && bin_residual == bin_capacity {
            score += 40.0;
        }
    }

    // Mean residual alignment: prefer bins below mean residual (tighter packs).
    score += (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals large enough to host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Creating a gap that fails the lookahead item is mildly bad.
        score += 8.0;
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 10.0 * (fill_ratio - 0.7);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // favor consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: penalize mildly so it is chosen only when
    // existing bins score poorly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 35.0 + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits exactly here: strong reward for tight match.
            score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
            if gap == 0.0 {
                score -= 15.0; // perfect 2-chain: place item then next item exactly
            }
        } else {
            // Next item cannot follow: penalize leftover dead space relative to mean residual.
            score += 0.35 * gap;
        }
    }

    // Tightness reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Penalize bins deviating from mean residual (avoid fragmenting many half-full bins).
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit would leave bad dead space
    // or no open bin fits well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 60.0 + waste;
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 55.0; // no alternative: opening new bin is fine
        }
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits (low post residual), especially exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 80.0;
    }

    // Lookahead: reward bins whose post residual can still host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Extra reward if next item then fits almost exactly.
        let next_left = post_residual - next_item_size;
        if next_left <= 5 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        score += (post_residual as f64) * 0.5;
    }

    // Penalize new bins, more so early on and when other bins fit fine.
    if is_new_bin {
        let mut penalty = 100.0;
        if fitting_bins_count > 0 {
            penalty += 50.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Late in the stream, opening a new bin is more acceptable.
        penalty -= 60.0 * progress;
        score += penalty.max(0.0);
    }

    // Prefer filling bins below the mean residual (balance toward consolidation).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Slight preference for bins with less residual overall as stream progresses.
    score += (post_residual as f64) * (0.3 + 0.4 * progress);

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (prn * prn) * (1.0 - progress) + (prn * prn * prn) * progress;
    score += 8.0 * poly;

    // Reward tight fits, scaled smoothly by progress
    score -= 6.0 * (1.0 - prn) * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits = (pr >= next_item_size as f64) as f64;
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 5.0 * fits * (1.0 - gap);
        score += 2.0 * gap * (1.0 - fits);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Penalize divergence from mean residual
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (or small classes) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        // class via integer division thresholds
        let class = pr / 10; // harmonic decade class
        score += class as f64 * 1.5;

        // modulo arithmetic: residual sharing divisors with item sizes
        let mut div_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                div_bonus += 8.0;
            }
        }
        score -= div_bonus;

        // coupling with lookahead item: residual that exactly fits next item is gold
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 50.0;
            } else if next_item_size < pr {
                let slack = pr - next_item_size;
                if slack <= 10 {
                    score -= 20.0;
                } else {
                    score += slack as f64 * 0.3;
                }
            } else {
                // next item cannot use this residual at all: penalize
                score += 10.0;
            }
        }
    }

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // penalize opening new bins when many bins already open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0;
        }
    }

    // spread against mean residual: bins far below mean residual are worse targets
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // mild pressure to pack tightly early in the stream
    score += (item_size as f64 / bin_capacity as f64) * 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical
    // future items (1..100, mean ~50) are nearly unusable -> harsh penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 45 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // Bonus for exact or near-exact fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual < 10 {
            score += 55.0; // undo if it creates dead space anyway
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.0 + progress) * 0.5;

    // New-bin candidate (empty bin): make it attractive only when the item
    // fits poorly everywhere else. An empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9 + (open_bins_count as f64) * 2.0;
        // If the item would leave a good residual (large item, tight fit),
        // a fresh bin is fine.
        if post_residual < 20 {
            score -= 45.0;
        }
        // Late in the stream, opening new bins is riskier.
        score += progress * 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }

    // Mean-residual alignment: prefer bins whose post residual stays near
    // the open-bin average to keep future flexibility balanced.
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as u32 <= post_residual {
            // Next item fits perfectly after this placement: strong reward.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 50.0; // perfect 2-item packing
            }
        } else {
            // Next item won't fit: penalize leaving a residual that is useless for it.
            score += 0.35 * gap;
        }
    } else {
        // Last item: minimize residual as much as possible.
        score += 10.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Relative to mean residual: prefer bins whose post residual is near/above the mean
    // (keeps residuals balanced), penalize creating small scattered residuals.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins overall (tight fit reward).
    score -= 0.2 * item_size as f64;

    // Penalize opening a new bin slightly when good existing fits exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // But allow new bin if no open bin fits well (post_residual tiny in others is handled by them).
    }

    // Early in stream: be more liberal with opening bins to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post residual (tight packing).
    let mut score = post;

    // Dead-space penalty: residuals too small for any plausible future item are worthless.
    // Normalize post residual and apply a convex penalty for "awkward" leftovers.
    let post_frac = post / cap;
    if post > 0.0 {
        // Penalize residuals that cannot accommodate even a small item (size 1..10 worst).
        if post < 10.0 {
            score += 40.0 * (10.0 - post);
        }
        // Mild convex penalty encouraging either near-full or comfortably usable residuals.
        score += 8.0 * post_frac * (1.0 - post_frac);
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next > 0.0 && post >= next {
        let snug = 1.0 - (post - next) / cap; // 1.0 when next item fills bin almost exactly
        score -= 25.0 * snug;
    } else if next > 0.0 && post > 0.0 && post < next {
        // Leftover blocks the next item; small penalty scaled by how close it was.
        score += 6.0 * (1.0 - post / next.max(1.0));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a tight fit. Penalize the fresh bin in proportion to how well the item
    // would fit elsewhere (approximated via mean_residual).
    if bin_residual == bin_capacity {
        let mean_fit_tightness = (mean_residual - item).abs() / cap;
        // If mean residual is close to item size, an existing bin likely fits well -> penalize new bin.
        score += 30.0 + 45.0 * (1.0 - mean_fit_tightness.min(1.0));
        // Fewer open bins -> keep consolidation, penalize opening more.
        score += 5.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, opening new bins wastes capacity permanently.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Reward using existing bins, scaled by how much they consolidate the pool.
        score -= 4.0 / (open_bins_count.max(1) as f64);
    }

    // Time-horizon modulation: early on, be more tolerant of imperfect fits
    // (future items can fill gaps); late, prioritize tight fits aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_frac * 30.0 * progress;

    // Global state: if mean residual across open bins is large, prefer bins below
    // mean (use up the "worst" bins first, balancing residuals).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr + 0.008 * pr * pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, dead space is more costly
    let progress_coupling = (pr / cap) * (pr / cap) * (progress - 0.5) * 60.0;
    score += progress_coupling;

    // Cubic residual penalty grows smoothly over the stream
    score += (pr / cap).powi(3) * (20.0 + 40.0 * progress);

    // Reward fitting into an existing bin (penalize opening new bins)
    if bin_residual != bin_capacity {
        score -= 4.0 + 6.0 * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: reward leaving residual that can still fit the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 3.0 + 2.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 2.0 * (n - pr) / cap * (1.0 + progress);
        }
    }

    // Penalize bins whose residual deviates from mean residual (balance open bins)
    score += 0.05 * (pr as f64 - mean_residual).abs() * (0.5 + progress);

    // Mild penalty for many open bins relative to progress
    score += open_bins_count as f64 * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "perfect fits"
    // (0) or highly reusable (small multiples) should be rewarded.
    let r = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit: huge reward.
    if r == 0 {
        score -= 1000.0;
    } else {
        // Modulo arithmetic on capacity fractions: post_residual equal to
        // small "harmonic" denominators (10,20,25,50) are classic reusable
        // slot sizes for integer item streams.
        let harmonic_bonus: f64 = match r {
            10 | 20 | 25 | 50 => 40.0,
            5 | 15 | 30 | 40 => 20.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;

        // Dead-space penalty: residual too small for the minimum item (1)
        // is fine, but residual that no plausible item (<= next_item_size
        // or typical sizes) can use is waste.
        if next_item_size > 0 {
            if r > 0 && r < next_item_size {
                // residual can't hold the lookahead item -> dead space
                score += (next_item_size - r) as f64 * 1.5;
            } else if r == next_item_size {
                // lookahead exactly fills this bin afterwards: excellent
                score -= 60.0;
            }
        }

        // Integer-division thresholds: reward post_residual in the "large
        // reusable half" of the capacity, penalize the awkward middle band.
        let half = (r * 2) as f64 / cap;
        if half > 0.6 {
            score -= 10.0 * half;
        } else if half < 0.2 && r > 0 {
            score += 8.0 * (0.2 - half);
        }

        // Harmonic class via division: classify residual by r / 10 tier.
        let tier = r / 10;
        score -= tier as f64 * 2.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item would leave a very tight fit here or open bins are congested.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, scaled by stream progression
        // (later in the stream, waste matters more per bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 45.0 * progress;

        // If this bin would be nearly full after placement, opening a new
        // bin is fine (small penalty removed).
        let fill = item_size as f64 / cap;
        if fill > 0.9 {
            score -= 70.0;
        }
        // If many bins are open with high mean residual, prefer packing.
        if open_bins_count > 2 && mean_residual > item_size as f64 * 2.0 {
            score += 30.0;
        }
    }

    // Slight preference for bins tighter than the mean (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable
    // for typical future items, so punish them hard (worse than medium gaps).
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Reward leaving a gap that can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize a gap that almost-but-not-quite fits the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins
    // are already open; encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is already below the mean (tighter bins
    // get filled first, keeping looser bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild early-stream bias toward opening new bins (structure building),
    // later stream bias toward filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Make the fresh bin lose against any reasonable existing fit.
            score += 25.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size,
    // penalize post_residuals that leave awkward gaps relative to the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack * 0.1);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
        // Exact two-item fill: item + next item fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 250.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Penalize wasting a large residual on a small item (dead space creation).
    let waste = (bin_residual as f64 - item_size as f64) - post_residual as f64;
    score += waste * 0.05;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Mild preference for keeping number of open bins low early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow late when open bins are fragmented.
        score += 150.0 - 100.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space: residuals too small for any future item (min size 1, but small residuals are wasteful)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: leftover is dead unless small
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: just minimize waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when existing bins fit poorly (large mean residual spread / poor tightness)
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let mut new_score = 35.0; // base cost of opening a bin
        // If item would leave a big awkward gap in existing bins, new bin is fine
        if post_residual as f64 > mean_residual {
            new_score -= 10.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_score += progress * 15.0;
        // Many open bins: discourage opening more
        new_score += open_bins_count as f64 * 2.0;
        // Perfect fit into new bin (item is large) is acceptable
        new_score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        score = new_score;
    } else {
        // Existing bin: reward when its residual deviates favorably from mean (consolidation)
        let dev = bin_residual as f64 - mean_residual;
        score -= dev * 0.15;
        // Prefer bins with less residual overall (fill fuller bins first)
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Mild time-dependent exploration: early stream, slightly favor tight fits more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * (1.0 - tightness) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: residual waste weighted by stream progress
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Dead-space penalty: post-residual that cannot fit the next item
    if next_item_size > 0 {
        let unusable = if pr < next_item_size as f64 { (next_item_size as f64 - pr) / cap } else { 0.0 };
        score += 20.0 * unusable * unusable * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening new bins unless residual is very large
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * (1.0 - progress);
    }

    // Mild penalty for bins far from mean residual (fragmentation avoidance)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // Favor larger items filling bins (less leftover per unit packed)
    score -= 10.0 * norm_item * norm_item;

    // Slight preference for bins with less residual overall early on
    score += 8.0 * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let class = post_residual % (bin_capacity / 4).max(1);
    score += 0.35 * (class as f64);

    // Reward near-perfect fits strongly (non-linear).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize dead space: residual too small for typical future items.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here; mildly penalize leaving mid-range gaps
            score += 0.15 * post;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if current fit is poor and mean residual low.
    if bin_residual == bin_capacity {
        let poor_fit = post > 0.5 * cap;
        if poor_fit && fitting_bins_count >= 1 {
            score -= 10.0 + 0.1 * mean_residual;
        } else {
            score += 25.0;
        }
    }

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post / cap);

    // Mild penalty for spreading across many open bins with large residuals.
    if open_bins_count > 3 && post_residual > bin_capacity / 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are pure waste; residuals in the "unusable gap" band (1..=9) are heavily
    // penalized since no future item can reliably fit there.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10 - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 200.0;
    }

    // Reward tight fits relative to current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize creating a gap that is just barely too small for the next item
    // (dead space with knowledge of lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter ones (post_residual already does).
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.15 * pressure;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well.
        // Base cost of a new bin grows with the number of open bins.
        let mut new_bin_cost = 120.0 + 3.0 * open_bins_count as f64;
        // If the item leaves a large usable gap in the new bin and next item
        // is large, opening fresh can be reasonable: soften cost.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_cost -= 30.0;
        }
        // If this is the ONLY fitting option, new bin is mandatory fallback.
        if fitting_bins_count == 0 {
            new_bin_cost = 0.0;
        }
        score += new_bin_cost;
    }

    // Mild preference for bins whose residual is already below average
    // (consolidate near-full bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits into post_residual with small slack -> graded reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the shortfall.
        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.5 * shortfall;
    }

    // Penalize residual far below mean (creating unusable dead space vs. fleet average).
    let res = post_residual as f64;
    if res < mean_residual {
        score += 0.4 * (mean_residual - res);
    } else {
        score -= 0.1 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when no good fit exists
    // (i.e., current bin would leave a small awkward residual).
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 10;
        if awkward || (next_item_size > 0 && post_residual < next_item_size && post_residual > 0) {
            score -= 40.0; // opening fresh bin beats fragmenting
        } else {
            score += 50.0; // prefer reusing open bins with decent fits
        }
    }

    // Mild stream-progress tilt: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate logic: only open a new bin when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so existing bins are preferred when fit is decent.
        score += 35.0;
        // If this is the only fitting bin (last chance), keep it attractive
        // relative to a new bin only if the fit is bad.
        if fitting_bins_count == 1 && fill_ratio < 0.35 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += 20.0 * progress;
        // Many open bins with large mean residual: discourage new bins.
        score += 0.5 * open_bins_count as f64;
        score += (mean_residual / 20.0).min(15.0);
    } else {
        // Last-chance bin bonus: if this is the only bin that can fit, use it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Prefer bins with residual below the mean (consolidate emptier space).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Mild preference for using more-filled bins overall.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, with non-linear polynomial shaping.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = post * (1.0 + 0.8 * x * x) + 12.0 * x * x * x * cap;

    // Smooth coupling with stream progress: waste penalized more later in the stream.
    score *= 1.0 + 0.6 * progress * progress;

    // Reward tight fits: subtract a smooth function of item fill ratio.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: if next item fits into post residual, reward this bin smoothly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo = (item_size as f64 + next_item_size as f64) / cap;
        score -= 25.0 * combo * (1.0 - combo);
    } else if next_item_size > 0 {
        // Next item cannot use leftover: penalize proportionally to leftover size.
        score += 0.25 * post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins; smooth in open count.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose residual is typical (avoid fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: keep it slightly unattractive unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-capacity-fraction residuals are valuable.
    let post = post_residual as u32;
    let frac = post as f64 / cap; // residual as capacity fraction
    // Reward residuals that are "nice" fractions: 0, 1/4, 1/2, 3/4 handled via modular check
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post == 0 {
        score -= 60.0; // perfect fill
    } else if post <= quarter / 2 {
        score -= 25.0; // near-perfect fill, tiny dead space
    } else if post == quarter || post == half || post == 3 * quarter {
        score -= 15.0; // harmonic class residual, easy to refill later
    } else {
        // penalize awkward residuals via modulo classes
        let m = post % 10;
        let penalty = match m {
            0 => 0.0,
            1 | 9 => 6.0,
            2 | 8 => 4.0,
            3 | 7 => 2.5,
            _ => 1.0,
        };
        score += penalty;
    }

    // Integer-division threshold on post_residual vs next_item_size (lookahead coupling)
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits here: strong reward, scaled by tightness
            let tight = (post - next_item_size) as f64;
            score -= 20.0 + 10.0 * (1.0 - tight / cap);
        } else {
            // dead space relative to lookahead: penalize proportionally
            score += 5.0 + 0.15 * (next_item_size - post) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a bin unless residual of this bin is badly fragmented
    if bin_residual == bin_capacity {
        score += 45.0;
        // but allow opening when open bins are nearly full on average
        score -= (mean_residual / cap) * 30.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer denser packing when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - frac) * 2.0;

    // Mild stream-progression pressure to consolidate early mess
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post as f64 / cap) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let obc = open_bins_count as f64;

    // Perfect fit: strong reward for completely filling a bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling (k=2):
    // - Reward gaps that the next item can fill, best when post_residual == next_item_size.
    // - Penalize gaps too small for the lookahead item: strict dead-space avoidance.
    if next_item_size > 0 {
        if pr >= nis {
            let closeness = 1.0 + (pr - nis).abs();
            score -= nis / closeness;
        } else {
            score += (nis - pr) * 0.9;
        }
    }

    // Tiny nonzero leftovers are statistically likely to be wasted forever.
    // Penalize them increasingly hard as more bins are open (open_bins_count pressure):
    // with many bins open, spreading dead space around is costlier.
    if pr > 0.0 && pr < 6.0 {
        score += (6.0 - pr) * 4.0 * (1.0 + obc * 0.03);
    }

    // Last-chance bonus: if this is the only open bin that fits the item,
    // strongly prefer using it over opening a brand-new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (bin_residual == bin_capacity):
    // penalize proportional to the number of already open bins, so a fresh bin
    // is chosen only when every existing fit is poor (large dead space).
    if bin_residual == bin_capacity {
        score += 8.0 + obc * 2.5;
    }

    // Mild consolidation: favor bins whose residual is below the current mean
    // residual (i.e., fuller bins), keeping the fleet of open bins tight.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Small dead space is bad: penalize residuals that are too small to be useful.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 30.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: the next item also lands here -> excellent packing.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 80.0 - 0.4 * chain_waste;
        } else {
            // Next item won't fit: penalize proportionally to how close we are to a miss.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * gap;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average space means this bin is more "used up" -> good.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.6 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., current item would leave a very tight residual everywhere else).
    if bin_residual == bin_capacity {
        let fresh_penalty = 120.0;
        let tightness = if next_item_size > 0 {
            (post_residual as f64 / bin_capacity as f64) * 40.0
        } else {
            40.0
        };
        score += fresh_penalty - tightness;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 50.0 * (1.0 - progress);
        // Many open bins already: discourage opening more.
        score += 5.0 * open_bins_count as f64;
    }

    // Mild preference for bins with less residual overall (fill fullest bins first).
    score += 0.2 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Items are 1..100, so post_residual >= 100 is impossible; small residuals
    // (< ~10) are nearly unusable "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // heavily reward this placement (perfect 2-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // Next item won't fit here; penalize proportionally to leftover size.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when existing bins fit badly (large post_residual relative to
    // mean residual) or when few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) - mean_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln().max(1.0);
        // Penalize new bins generally, more so when open bins are plentiful.
        score += 25.0 + 3.0 * openness;
        // But forgive the penalty when the alternative fit is poor.
        score -= bad_fit.max(0.0) * 0.6;
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - progress);
    }

    // Slight penalty for placing into a bin whose residual is much larger than
    // the item (wasteful spread of large items across many bins).
    if bin_residual != bin_capacity {
        let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 8.0 * waste * waste;
    }

    // Mild time-horizon modulation: as the stream nears its end, prioritize
    // closing bins tightly (reduce post_residual even harder).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Small structural term: discourage fragmenting when many bins are open.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over progress
    let poly = 1.0 + 0.8 * progress - 0.5 * progress * progress;
    let mut score = pr * poly;

    // Smooth interaction: dead-space penalty grows with progress (waste matters more late)
    let dead = (norm_pr * norm_pr) * (1.0 + 2.0 * progress);
    score += 40.0 * dead;

    // Tight fit reward (post_residual small relative to item size)
    let tight = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 30.0 * tight * tight;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
    }

    // Prefer bins with residual below mean (consolidate space)
    score += 5.0 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize mildly early, more when open bins exist with room
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual % (bin_capacity / 4).max(1); // quarter-capacity harmonic class
    score -= (bin_capacity as f64 - class as f64) * 0.05; // reward residuals near class boundaries

    // Integer-division thresholds on post_residual
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual < 10 {
        score -= 10.0; // near-perfect, unusable dead space anyway
    } else if post_residual <= bin_capacity / 5 {
        score += 5.0; // small residual, mildly penalize
    }

    // Reward tight fills relative to capacity fraction
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * fill * 20.0;

    // Coupling with next item lookahead: harmonic class of next item vs post residual
    if next_item_size > 0 {
        let nk = next_item_size % (bin_capacity / 2).max(1);
        if nk as f64 <= pr {
            score -= 8.0; // next item's harmonic class fits residual
        } else {
            score += (nk as f64 - pr) * 0.1;
        }
        // next item exactly fills post residual -> strong reward
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(3.0);
        }
        // early stream: prefer reusing bins while few open
        if open_bins_count > 2 {
            score += 5.0;
        } else {
            score -= 10.0;
        }
    }

    // Stream progression: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr) * 0.05;

    // Penalize deviation from mean residual (prefer balanced bins)
    score += (pr - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    if post > 0.0 && post < 10.0 {
        score += 60.0 * (10.0 - post) / 10.0; // tiny gap => heavy penalty
    } else if post == 0.0 {
        score -= 25.0; // perfect fill reward
    }

    // Reward tight fit relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; prefer new bin when few open.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 15.0 + 30.0 * open_pressure;
        // But if no existing bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: reward when many bins open (consolidation pressure).
        score -= 10.0 * open_pressure;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as f64 - post).abs() < 1.0 && post > 0.0 {
            score -= 35.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 12.0; // next item can still use the leftover
        } else {
            // leftover too small for next item: penalize proportionally
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight stream-progression nudge toward tighter packing later on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead core ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match: item + next item exactly fill the bin.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: reward proportionally.
            let leftover_after_pair = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * leftover_after_pair;
        } else {
            // Dead space: next item cannot use the residual.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        }
    } else {
        // Last item: just minimize post_residual (already the base score).
    }

    // ---- Tightness reward relative to bin capacity ----
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // ---- Compare against mean residual of open bins ----
    // Prefer bins whose post-residual is close to (or below) the mean residual,
    // i.e. bins that are already relatively full.
    let mean_post = mean_residual - item_size as f64;
    if (post_residual as f64) < mean_post {
        score -= 6.0;
    } else {
        score += 0.15 * (post_residual as f64 - mean_post).max(0.0);
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // If this is the only open bin that fits, avoid opening a new bin
        // unless the fit is truly terrible (large dead space).
        if post_residual <= 20 {
            score -= 30.0;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin should only win when the stream is early
        // or the item is large relative to capacity (poor fit elsewhere likely).
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 25.0 * large_item - 20.0 * (1.0 - progress);
        // A fresh bin is more attractive when many open bins are already cluttered.
        score -= 1.5 * open_bins_count as f64;
        // But if the next item is small, keeping residual space elsewhere is fine;
        // penalize opening a new bin for small items.
        if next_item_size > 0 && next_item_size < 30 {
            score += 10.0;
        }
    }

    // ---- Late-stream consolidation ----
    // As the stream nears its end, prefer filling existing bins tightly
    // rather than leaving many partially-filled bins.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // Reward bins that can also host the lookahead item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize leaving residual too small for the next item (dead space risk),
            // scaled by how close post_residual is to next_item_size.
            let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.6 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current open bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        let poor_fit = (item_size as f64 / bin_capacity as f64) * 55.0;
        let congestion = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * 25.0;
        score = 60.0 + poor_fit - 20.0 / scarcity - congestion * (1.0 - fit_ratio);
        // Early in stream, slightly prefer opening bins to build diversity.
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - t);
    }

    // Prefer bins whose residual deviates below mean (consolidate emptier space usage).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Slight penalty for very large leftovers that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Mild regularization by stream progress: later on, tighter packing matters more.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Smooth non-linear coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let base = pr_norm * pr_norm * (1.0 + 2.0 * progress);

    // Penalize residuals that are dead space relative to typical item sizes.
    let dead = (pr / (item_size.max(1) as f64)).ln().abs();
    let dead_term = 0.5 * dead * dead * (1.0 - fit_ratio);

    // Reward tight fits (small post_residual) more strongly later in the stream.
    let tight_reward = -(1.0 - pr_norm).powi(3) * (1.0 + 3.0 * progress) * 2.0;

    // Last-chance bonus: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -3.0 * (1.0 + progress) } else { 0.0 };

    // Lookahead: penalize if post_residual can't fit next item but almost could.
    let look = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        if gap < 0.0 { 0.6 * gap.abs() * (1.0 + progress) } else { -0.3 * gap * (1.0 - progress) }
    } else { 0.0 };

    // Mild pressure to consolidate when many bins are open.
    let spread = 0.2 * ((mean_residual - pr) / cap).abs() * (open_bins_count as f64).ln().max(1.0);

    base + dead_term + tight_reward + last_chance + look + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but avoid dead space.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    // Residuals that are "harmonically useful" (multiples of common item sizes) get rewarded.
    let useful: u32 = if post_residual == 0 { 10 }
        else if post_residual % 10 == 0 { 6 }
        else if post_residual % 20 == 0 { 5 }
        else if post_residual >= 10 && post_residual % 5 == 0 { 3 }
        else if post_residual < 10 { 4 }  // small dead space is nearly harmless
        else { 0 };
    score -= 8.0 * useful as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Next-item lookahead: does post_residual accommodate next item harmonically?
    if next_item_size > 0 && post_residual >= next_item_size {
        // post_residual divisible-ish relative to next item size => chain fit
        if post_residual % next_item_size.max(1) == 0 {
            score -= 12.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted potential.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap;
        // If next item is large, leaving big residual is extra wasteful.
        if next_item_size > 50 {
            score += 0.2 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Competition: slight penalty to keep spread across bins small.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let open_fits_poorly = if next_item_size > 0 {
            mean_residual < item_size as f64 * 0.6
        } else {
            mean_residual < item_size as f64 * 0.5
        };
        if open_fits_poorly {
            score -= 15.0;
        } else {
            score += 30.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if open bins are already loose, prefer tighter placements.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use are heavily penalized.
    let min_item = 1u32;
    let dead = if post_residual > 0 && post_residual < min_item.max(next_item_size.min(80)) {
        1.0
    } else {
        0.0
    };
    // treat any post_residual smaller than next item as dead if it can't fit lookahead
    let dead2 = if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        1.0
    } else {
        0.0
    };
    score += 25.0 * dead + 12.0 * dead2;

    // Reward tight fits (small post_residual relative to capacity) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    } else {
        score -= 1.0 * open_bins_count as f64 * 0.1;
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead coupling: if next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in post-residual and post-residual is small, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact/predictive match enabling next item to fill bin
        score -= 12.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(0.0);
        // Extra bonus for perfect chain (post_residual == next_item_size)
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving residual slightly larger than next item (wasted dead space)
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 8.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Penalize deviation from mean residual (prefer balancing or extreme fills)
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_gap;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist, unless residual is very small
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current item is large relative to capacity
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 10.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain with next item
        }
    }

    // Reward high fill ratio of the bin
    let used = (bin_capacity - bin_residual + item_size) as f64;
    score -= 8.0 * (used / bin_capacity as f64);

    // Progression-aware: late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating small unusable dead space (< 10 units) unless perfectly full.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item fills the bin almost perfectly after placement.
            let post2 = post_residual - next_item_size;
            if post2 <= 5 {
                score -= 10.0;
            }
        } else if next_item_size <= post_residual + 10 {
            // Near-miss lookahead: mild penalty for blocking a plausible follow-up.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is penalized unless the
    // current bin would leave a lot of dead space relative to capacity.
    if bin_residual == bin_capacity {
        // New bin has full residual 100; make it attractive only when the item is large
        // (big items fragment bins badly) or many bins are already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = if item_size >= 60 { 20.0 } else { 0.0 };
        let crowding = (open_bins_count as f64).sqrt() * 3.0;
        // Base penalty keeps new bins usually worse than a decent existing fit.
        score += 55.0 - large_item_bonus - crowding - 15.0 * progress;
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (consolidate waste into fuller bins), above-mean residual penalized.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (resid_f - mean_residual);
    }

    // Mild reward for using very full bins to encourage consolidation.
    if bin_residual <= 20 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize large post residual, with non-linear (quadratic/cubic) shaping
    let mut score = x * 40.0 - 12.0 * x * x - 6.0 * x * x * x;

    // Smooth coupling with stream progress: later in stream, tolerate less dead space
    let prog_coupling = 1.0 + 0.8 * progress * (1.0 - x);
    score *= prog_coupling;

    // Reward tight fits smoothly (small post residual gets extra bonus)
    score -= 10.0 * (1.0 - x) * (1.0 - x) * (1.0 - progress);

    // Lookahead: if next item can use the post residual, reward; smooth sigmoid-like term
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let fit_quality = 1.0 - (pr as f64 - nx) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            score += 4.0 * (nx / cap);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize bins whose residual deviates far from mean residual (fragmentation)
    score += 0.15 * ((pr - mean_residual) / cap).abs() * cap;

    // Mild pressure against accumulating too many open bins early
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue classes" are more likely reusable by future items.
    let cap = bin_capacity as f64;

    // Reward tight fits (small post_residual).
    if post_residual <= bin_capacity / 20 {
        score -= 30.0;
    } else if post_residual <= bin_capacity / 8 {
        score -= 15.0;
    }

    // Modulo-10 harmonic class: residues divisible by 10 are classic
    // "friendly" leftovers (items often come in multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Penalize awkward dead space: residues in (0,10) modulo 10 are hard to fill.
    let dead = post_residual % 10;
    if dead > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Penalize post_residual that cannot fit the next item when next item is known.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the lookahead item: strong reward,
            // scaled by how well the lookahead fits afterward.
            let post2 = post_residual - next_item_size;
            score -= 20.0 + (post2 as f64).min(10.0);
            if post2 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0; // leaves next item needing another bin anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.1 * (item_size as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // early in the stream or when all existing fits are bad.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New empty bin: baseline cost of consuming fresh capacity.
        score += 40.0;
        // Slightly cheaper to open bins early when few exist.
        score -= 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big lookahead item pairs well with fresh bin
        }
    }

    // Prefer filling bins whose residual is below mean (consolidate fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Mild penalty for many open bins already: encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Integer-division threshold: post_residual in upper quartile wastes a bin.
    if post_residual > (3 * bin_capacity) / 4 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small but potentially usable gaps: moderate penalty scaled by tightness.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Perfect / near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (penalize alternatives implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, favor consolidating into
    // existing bins; with few open bins, new-bin candidates are cheaper.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted early in stream.
        score += 15.0 + pressure * (1.0 - 0.5 * (step_index as f64 / (total_items.max(1) as f64)));
    } else {
        score -= pressure * 0.3;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the known next item: slight penalty.
        score += 5.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping looser bins available for future large items.
    score += (mean_residual - bin_residual as f64).max(-50.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits, reward closeness of fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space relative to next item.
        let dead = (post_residual as f64).min(next_item_size as f64);
        score += 0.5 * dead;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable slivers (post_residual below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: bins tighter than average are better to fill.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Discourage opening a new bin early in the stream unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        // But if no open bin fits, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Perfect lookahead on fresh bin: post_residual = capacity - item == next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.55;
    } else {
        score -= 12.0; // perfect fit bonus
    }

    // Reward filling bins deeply relative to capacity.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 6.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; if it would
    // leave this bin's residual stranded, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            // dead space relative to next item
            score += (post_residual as f64) * 0.35;
            // but if next item could fit elsewhere, soften
            if fitting_bins_count > 1 {
                score -= 2.0;
            }
        }
    }

    // Time horizon: early in stream, tolerate opening new bins (explore);
    // late in stream, prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate
        let new_bin_penalty = 8.0 + 22.0 * progress + 0.9 * open_bins_count as f64;
        score += new_bin_penalty;
        // allow new bin early when item is large and would fragment an existing bin
        if item_size as f64 > 0.7 * bin_capacity as f64 && progress < 0.4 {
            score -= 10.0;
        }
    } else {
        // existing bin: mild reward scaled by progress
        score -= 3.0 * progress;
    }

    // Global residual pressure: if mean residual is high, prefer bins above mean
    // residual (consolidate slack); if low, just minimize waste.
    if mean_residual > 0.0 {
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.12 * diff;
    }

    // Penalize leaving residuals in the awkward 1..=9 range (unusable dead space).
    if post_residual >= 1 && post_residual <= 9 {
        score += 14.0;
    }

    // Small bonus for using bins with many fitting alternatives less eagerly,
    // saving flexible bins for harder items.
    if fitting_bins_count > 2 && bin_residual != bin_capacity {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Smooth non-linear coupling: penalize large post_residual quadratically,
    // weighted by stream progress (tighten packing as stream advances).
    let norm_post = post / cap;
    score += 18.0 * norm_post * norm_post * (0.4 + 0.6 * progress) * cap * 0.1;

    // Reward tight fits (small post_residual) with cubic discount.
    score -= 12.0 * (1.0 - norm_post).powi(3);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 9.0 * (1.0 - post / nxt.max(1.0)) * (0.5 + 0.5 * progress);
        } else {
            score -= 4.0 * (post - nxt) / cap;
        }
    } else {
        // Last item: strongly prefer consuming residual fully.
        score -= 15.0 * (1.0 - norm_post);
    }

    // Last-chance bin bonus: smooth reward when few fitting bins remain.
    if fitting_bins_count <= 1 {
        score -= 10.0;
    } else {
        score -= 3.0 / fitting_bins_count as f64;
    }

    // Discourage scattering across many open bins; slight preference for
    // bins whose residual is near the mean (smooth deviation penalty).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for opening new bins when many bins already exist.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt() + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions and modulo structure.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class bands: leftover in (0,10] is near-dead space -> penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 10.0;
    } else if post_residual <= 50 {
        score -= 8.0;
    } else {
        score -= 3.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of
    // common small item sizes (10, 20, 25, 50) are "harmonic" and reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        // Prime / awkward leftovers are dead space.
        if post_residual % 10 != 0 && post_residual < 15 {
            score += 12.0;
        }
    }

    // Lookahead: if next item exactly fits the leftover, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // leftover divisible by next item -> chain of future fits
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - slack / cap)).max(0.0);
        } else {
            // next item cannot use this bin's leftover; leftover value drops
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded
    // (low mean residual) or this item would create tiny dead space.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 0.25 * cap;
        let poor_fit = post_residual > 0 && post_residual <= 10;
        if crowded || poor_fit {
            score -= 12.0;
        } else {
            score += 30.0;
        }
    }

    // Slight preference for bins tighter than the fleet average.
    score -= (mean_residual - pr) * 0.15;

    // Mild late-stream tightening: prefer filling bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are nearly unusable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space below the minimum item size
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    }

    // Reward placements whose leftover can host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // leftover blocks the known next item
    }

    // Pressure from too many open bins: favor filling existing bins.
    let open_pressure = open_bins_count as f64;
    score -= 1.5 * open_pressure;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: bins far below mean residual are good sinks.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_penalty = 20.0 + 2.0 * open_pressure;
        let scarcity_bonus = if fitting_bins_count <= 1 { 0.0 } else { 25.0 };
        score += open_penalty + scarcity_bonus;
    }

    // Late in the stream, tighten up: waste less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize wasted space (dead space), strongly non-linear.
    let mut score = (post_residual as f64).powf(1.7);

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual < 20 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 350.0; // perfect chain: this bin will be closed by next item
        } else if next_item_size as u32 <= post_residual {
            // next item fits here: reward proportional closeness
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item will NOT fit here: penalize leaving space smaller than next item (dead space)
            score += 60.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Relative to mean residual: bins tighter than average are good targets.
    score -= 15.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly prefer using the only bin that fits (avoids opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Penalize opening a new bin more when many bins are already open (encourage consolidation),
    // and slightly more early in the stream.
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64 + 30.0 * (1.0 - progress);
    }

    // Mild preference for tighter bins overall.
    score += 0.5 * (bin_capacity as f64 - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly favor tight fits: reward small post_residual non-linearly.
    // Squared term punishes leaving large gaps (dead space).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Penalize "awkward" residuals that few future items can use.
    // Residuals just below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this is a great chain placement -> reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another gap: mild reward proportional to fill
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this bin's remaining space: slight penalty
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
        if post_residual <= 15 {
            score -= 30.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: an empty bin is a fallback.
    // Prefer it only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream
        // when hoarding open bins is less useful.
        let base_cost = 120.0 - 40.0 * progress;
        // If item is large relative to capacity, opening fresh space is fine.
        let size_relief = 20.0 * (item_size as f64 / bin_capacity as f64);
        score = base_cost - size_relief + post_residual as f64;
        // If many bins are open with high mean residual, reusing them is cheap;
        // make new bins even less attractive.
        score += open_bins_count as f64 * 2.0 + mean_residual * 0.5;
    }

    // Crowding control: with many open bins, prefer consolidating into
    // already-low-residual bins to close them out.
    score += open_bins_count as f64 * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins whose residual is below mean (tighter than average)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 60.0 * norm_pr * norm_pr + 40.0 * norm_pr * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, residual waste becomes more costly
    let coupling = 0.5 + 2.0 * progress * progress;
    score *= coupling;

    // Tight fits reward: subtract a smooth function of (residual - item)
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bin bonus (smoothly scaled by how many alternatives exist)
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_ratio = next_item_size as f64 / cap;
        score -= 20.0 * fit_ratio * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty proportional to leftover
        score += 5.0 * norm_pr;
    }

    // Mean residual context: prefer bins whose residual deviates beneficially
    score += 0.3 * (pr - mean_residual);

    // Many open bins: gently discourage fragmenting capacity further
    score += 0.5 * (open_bins_count as f64).sqrt();

    // New-bin candidate: make empty-bin choice costly unless it's early or item is large
    if bin_residual == bin_capacity {
        let early_discount = 1.0 - progress;
        let largeness = item_size as f64 / cap;
        score += 30.0 - 25.0 * early_discount - 20.0 * largeness * largeness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items sizes 1..100, capacity 100.
    // Classify leftover space by its "usefulness class" via integer division.
    let post = post_residual;
    let next = next_item_size;

    // Dead-space penalty: residual that no plausible item (>=1) can use well.
    // Small nonzero post_residuals are the worst outcome.
    if post > 0 && post < 10 {
        score += 25.0 * (10 - post) as f64;
    }

    // Harmonic buckets of post_residual: 0 (perfect), small, mid, large.
    let bucket = post / 25; // 0..=4 harmonic class
    match bucket {
        0 => score -= 8.0,          // near-perfect fill
        1 => score += 2.0,          // awkward 25-49 leftover
        2 => score -= 1.0,          // decent 50-74 leftover
        _ => score -= 0.5,          // large leftover, flexible
    }

    // Modulo coupling: does next_item_size fit exactly into post_residual?
    if next > 0 && next <= post {
        // Reward exact fit (post % next == 0) strongly.
        if post % next == 0 {
            score -= 12.0;
        } else {
            // Reward when the remainder after next item is again usable (>10)
            let r2 = post % next;
            if r2 >= 10 {
                score -= 4.0;
            } else if r2 > 0 {
                score += 3.0; // creates small dead space
            }
        }
    } else if next > 0 {
        // Next item cannot follow into this bin: penalize proportionally.
        score += 6.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score unless
    // open bins are scarce or item is large.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 || item_size >= 60 {
            score -= 15.0;
        }
        if next > 0 && next >= 50 {
            score -= 5.0; // save space for big next item
        }
    }

    // Stream progression: late in stream, prefer tighter packing (lower post).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post as f64) * 0.3;

    // Mean residual context: if open bins are already slack, penalize adding slack.
    if (post as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Open bin count pressure: many open bins -> favor filling existing ones.
    score -= (open_bins_count.min(20) as f64) * 0.4 * (1.0 - post as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            (10 - post_residual) as f64 * 8.0
        } else if post_residual < item_size {
            15.0 // gap smaller than smallest possible item is semi-dead
        } else {
            0.0
        };
        score += dead;
    }

    // Prefer bins whose residual tightly matches the item (tight fit reward).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 50.0 + 10.0 * open_bins_count as f64;
        // But allow a new bin if the item would leave a huge unusable gap elsewhere.
        if post_residual > 0 && post_residual < 10 && fitting_bins_count <= 2 {
            score -= 120.0;
        }
    } else {
        score -= 10.0; // mild bonus for reusing an existing bin
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // dead space for the known next item
    }

    // Slight early-stream willingness to open bins (build a good pool).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Align with mean residual: prefer bins below mean (tighter bins get used first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect chain: subtract big bonus
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: bonus proportional to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * tightness;
        } else {
            // next item won't fit: penalize dead space relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than mean
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Slight preference for filling bins early in stream (keep many bins open)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the current fit is bad
    // (large post_residual waste relative to capacity or item barely fits).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        // Opening a new bin is good if this bin would keep a big usable chunk
        // AND the item fits poorly elsewhere. Base penalty to prefer existing bins.
        score += 12.0;
        // Reward opening a new bin when the item is large and leaves a clean residual.
        if item_size >= 60 {
            score -= 10.0 * (1.0 - waste);
        }
        // If many bins are open with large mean residual, opening new bin is wasteful.
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // Late in the stream, prefer consolidation into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Lookahead: if the next item could exactly fill the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * next_fit;
        } else {
            // Next item cannot use this bin's leftover: mild penalty for large leftovers.
            score += 0.05 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Global balance: prefer bins whose residual is below mean (consolidate fuller bins).
    score += 0.1 * (post_residual as f64 - mean_residual);

    // Mild preference for fewer open bins overall when placing into existing bins.
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    score += 15.0 * norm_pr * norm_pr * norm_pr;
    score -= 20.0 * (1.0 - progress) * norm_pr * (pr / cap.max(1.0));

    // Dead-space penalty: small residuals late in stream are bad
    let dead = 1.0 - (pr / 50.0).min(1.0);
    score += 25.0 * dead * dead * (0.3 + progress);

    // Reward tight fits
    score -= 10.0 * (item_size as f64 / cap) * (1.0 - norm_pr);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: prefer bins whose post_residual still fits next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Penalize many open bins mildly to encourage consolidation
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common small sizes) are rewarded.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -60.0 // perfect fit: best possible outcome
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        -2.0
    } else {
        4.0 // odd residuals tend to be dead space
    };
    score += class_penalty;

    // Dead-space threshold: residuals too small for the smallest plausible
    // future item are heavily penalized (quadratic in unusability).
    if pr < 10 && pr > 0 {
        score += 30.0 + (10 - pr) as f64 * 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, mild penalty scaled by waste.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 - slack * 0.15;
        } else {
            score += ((next_item_size - pr) as f64) * 0.2;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer keeping existing bins unless the item
    // fits very poorly everywhere. Penalize fresh bins mildly, less so early
    // in the stream or when mean residual across bins is already tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual / bin_capacity as f64;
        score += 10.0 - 20.0 * progress - 10.0 * (1.0 - tight);
    }

    // Fragmentation guard: prefer bins whose residual is close to the item
    // (tight fit) using a normalized tightness term.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Many open bins: slight pressure to consolidate into existing bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual is "dead" if it is smaller than the smallest plausible item (1..100 unknown,
    // so treat anything below ~15 as hard-to-fill) and scale the penalty sharply.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Perfect fit reward: strongly favor bins that are exactly filled.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Penalize leaving a gap that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over spreading items; when few bins are open, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 8.0 * pressure;
    } else {
        score += 10.0 + 4.0 * pressure;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight progression bias: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size exactly (perfect chain).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect match -> strong reward
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits: mild reward proportional to closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover: penalize dead space
            score += 15.0 * (diff / bin_capacity as f64);
        }
        // If post_residual would be too small for anything useful (min size 1..~10),
        // treat it as wasted capacity.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Prefer tight fits overall: reward small post_residual relative to mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and would leave a well-shaped residual for the future.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a fresh bin is attractive for big items (keeps small residual space
        // in existing bins available for small future items).
        if item_size >= 50 {
            score -= 45.0;
        }
        // Less attractive late in the stream when many bins are already open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty per open bin to encourage consolidation when ties occur.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0.0 -> 1.0)
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Fractional fill of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits strongly (non-linearly): waste near zero is best
    let waste = post_residual as f64;
    score -= (bin_capacity as f64) * (fill * fill) * 0.5;
    score -= 30.0 * (-waste / 15.0).exp(); // sharp bonus for small post_residual

    // Penalize dead space: residuals too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: slight penalty proportional to leftover
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // When many bins are open, encourage consolidation into existing bins
    score += (open_bins_count as f64).ln() * 2.0;

    // Prefer bins with residual below the mean (fill the emptier-toward-full ones less)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted early in the stream
        let open_cost = 35.0 - 15.0 * progress;
        score += open_cost;
        // if the item is large and current bins are mostly full, new bin is fine
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild time-horizon shaping: later in stream, be greedier about tight fits
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: polynomial coupling of post_residual with stream progress.
    // Early on, small post_residuals are cheap; late, dead space matters more.
    let mut score = pr * (1.0 + 0.9 * progress * progress + 0.6 * progress * (pr / cap));

    // Non-linear fill-ratio reward: reward bins whose post fill ratio is high,
    // smoothly via a quadratic in (1 - pr/cap).
    let fill = 1.0 - pr / cap;
    score -= 8.0 * fill * fill * (1.0 + progress);

    // Lookahead: reward if the next item fits the post-residual (smooth term).
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        let tight_next = 1.0 - (next_item_size as f64 / cap);
        score -= 6.0 * fits_next * tight_next * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, penalize opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty so best-fit among many wins.
        score += 0.4 * (fitting_bins_count as f64).ln();
    }

    // Mean residual coupling: penalize bins far from the mean residual (smooth).
    score += 0.05 * (pr - mean_residual).abs();

    // Slight preference for keeping few open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: empty bin gets moderate baseline so it's chosen only
    // when open bins have large dead space or none fit.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post residual: bins whose leftover falls into "usable"
    // residue classes (divisible into common small-item chunks) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // residuals divisible by 10 are highly reusable
        if class == 0 {
            score -= 6.0;
        } else if class == 5 {
            score -= 3.0;
        } else if class >= 7 {
            score += (class - 6) as f64;
        }
        // dead-space penalty for tiny unusable slivers
        if pr < 10 {
            score += (10 - pr) as f64 * 0.8;
        }
    }

    // Exact fit is golden
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic fraction of capacity used
    let fill = (bin_residual as f64) / cap;
    let used_frac = (item_size as f64) / cap;
    // favor bins where item occupies a clean fraction (1/2, 1/4, 3/4 style)
    let harmon = (used_frac * 4.0).round() / 4.0;
    let align_bonus = 1.0 - (used_frac - harmon).abs() * 4.0;
    score -= align_bonus * 4.0 * fill;

    // Next-item lookahead: integer-division thresholds on next_item_size
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= post_residual {
            // next item also fits here: strong reward, scaled by how snugly
            let snug = (post_residual - n) as f64;
            score -= 8.0 - snug * 0.1;
            // harmonic pair: item + next fills bin to a multiple of 25
            let total = item_size + n;
            if total % 25 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit: penalize, worse if post_residual is dead space
            score += (post_residual as f64) * 0.05 + 2.0;
        }
        // if next item is huge, prefer consolidating now
        if n >= 50 && post_residual < n {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let crowded = mean_residual < item_size as f64 * 1.5;
        if crowded && pressure > 2.0 {
            score -= 4.0;
        } else {
            score += 20.0 + pressure * 0.5;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // mild preference for tighter bins overall
    score -= (cap - bin_residual as f64) * 0.02;

    // tie-break toward bins below mean residual (consolidate small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else if post_residual < 20 { 1.5 } else { 0.0 };
        score += dead * (post_residual as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 200.0;
    }

    // Reward tight fills relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item cannot fit the post-residual but could fit a fresh bin, penalize
    // leaving a dead gap that strands the next item.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when few bins are open
    // or the item is large; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect chain: post_residual exactly matches next item size -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        // Slight bonus if next item fits exactly (diff == 0)
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Penalize dead space relative to mean residual (wasted capacity)
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.5 * dead;
    } else {
        score += 0.2 * dead; // reward below-average leftover mildly
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Tight fits rewarded (small post_residual relative to capacity)
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Prefer filling already-open bins over opening new ones early in stream
    if bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Penalize very small unusable remnants (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalty (quadratic in post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * (bin_capacity as f64) * 0.6;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward space.
            score += 3.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are quite full
    // or the current item is small relative to mean residual (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_rel = mean_residual / bin_capacity as f64;
        // Opening a new bin is penalized early and when mean residual is large.
        score += 10.0 + 30.0 * mean_rel + 20.0 * (1.0 - progress);
        // But if item is large and mean residual is small, new bin becomes viable:
        score -= 12.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - mean_rel);
        // Late in the stream, discourage opening bins that will be nearly empty.
        if progress > 0.9 && item_size < 30 {
            score += 15.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> encourage consolidating into fuller bins (low residual).
    let spread = mean_residual - post_residual as f64;
    score += 0.05 * spread;

    // Mild time-horizon scaling: early items tolerate slack, late items should pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Prefer bins that are already heavily loaded (low residual) to reduce bin count.
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * (bin_capacity as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fits (minimize post_residual aggressively);
    // later, tolerate larger residuals slightly (bins will close anyway).
    let mut score = pr * (1.0 + 0.6 * progress * (1.0 - progress) * 4.0);

    // Smooth polynomial penalty on residual fraction: dead space matters more
    // when it is "awkwardly small" (hard to reuse). Use a cubic in norm_pr.
    let awkward = norm_pr * (1.0 - norm_pr) * (2.0 - norm_pr);
    score += 30.0 * awkward * (1.0 - progress);

    // Reward scarce fitting options (last-chance bin) with smooth coupling.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 12.0 * scarcity * (1.0 + progress);

    // Penalize deviating from mean residual (keeps bin pool homogeneous),
    // with quadratic coupling scaled by number of open bins.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).sqrt();

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    }

    // New-bin candidate: smooth penalty unless residuals across pool are low
    // (i.e., open bins are nearly full) — then opening is comparatively fine.
    let pool_fullness = 1.0 - mean_residual / cap;
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - pool_fullness) * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space relative to capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 20.0;

    // Harmonic class of post_residual: residuals divisible by small moduli are
    // more likely to be exactly filled by future items -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Small unusable residuals are dead space: penalize heavily.
        if pr < 10 {
            score += 15.0 + (10 - pr) as f64 * 2.0;
        }
    } else {
        // Perfect fill is ideal
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= 4.0 + (pr - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot use this residual at all: residual likely wasted
            score += 3.0;
        }
        // Harmonic pairing: next_item_size and post_residual sharing a common
        // divisor of capacity suggests complementary sizes
        if pr % 25 == next_item_size % 25 && pr > next_item_size {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: opening a new bin is only attractive when all open
    // bins would leave very poor fits (large post_residual) or many bins open.
    if bin_residual == bin_capacity {
        // Empty bin baseline: keep it slightly worse than a good fit,
        // better than a terrible fit.
        score = 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 3.0; // late in stream, slightly prefer consolidation
    }

    // Crowding: many open bins with high mean residual -> encourage filling
    // existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 2.0;
    }

    // Mild penalty for near-half residuals (hardest to fill later)
    if pr >= 40 && pr <= 60 && pr % 10 != 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - pr) * 18.0; // gap of 1 => +216, gap of 12 => +18
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is best possible outcome
    } else {
        // Larger leftovers are less harmful if they remain usable (>12),
        // mildly reward leaving room that can still fit mid-size items.
        if post_residual >= 30 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here; penalize leaving a gap it nearly fits.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap <= 10.0 {
                score += gap * 6.0;
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residual is wasteful.
    let ob = open_bins_count as f64;
    score += ob * 3.0;

    // Mean-residual coupling: prefer bins whose residual is below mean when the fit is loose,
    // above mean when the fit is tight (keeps large residuals available).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count == 0 { 0.0 } else {
            // compare with what open bins would leave behind
            (bin_residual - item_size) as f64
        };
        // Base cost of opening a new bin grows with number of open bins.
        score = 100.0 + ob * 6.0 + bad_fit * 0.5;
        if fitting_bins_count <= 1 {
            score -= 70.0; // opening a bin is fine when alternatives are scarce
        }
        if post_residual <= 12 {
            score += 40.0; // fresh bin with tiny item => future dead space risk is fine actually
        }
    }

    // Stream progression: later in the stream, prefer closing bins out (tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space, amplified for small residuals (dead space).
    let pr = post_residual as f64;
    if post_residual > 0 {
        score += 40.0 / pr.sqrt();
    } else {
        score -= 30.0; // perfect fit reward
    }

    // Aggressive 2-step lookahead: reward if next item exactly fits the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 45.0; // chain match: perfect follow-up
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to tightness of the chain
            let slack = pr - nxt;
            score -= 25.0 - 0.5 * slack;
        } else {
            // next item won't fit here: penalize more if we created awkward leftover
            let gap = nxt - pr;
            score += 8.0 + 0.4 * gap;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are more "spent";
    // filling them is good, opening fresh space when mean residual is high is bad.
    score += 0.35 * (mean_residual - pr);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when it offers
    // better lookahead structure than existing bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity / 2 {
            score += 12.0; // discourage opening new bin when lookahead fits elsewhere
        }
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here destroys room for the next item -> mild penalty
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: prefer bins with less residual waste elsewhere
        score += 2.0;
    }

    // Global state: many open bins with large mean residual -> discourage opening new bins,
    // encourage packing into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are open or late in stream
        score += 6.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) + 8.0 * progress;
        if mean_residual > item_size as f64 {
            score += 6.0; // existing bins have room; don't open a new one
        }
    } else {
        // reward using open bins when mean residual is high
        score -= 3.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Time horizon: early in the stream, keep bins flexible (avoid very small residuals);
    // late in the stream, prioritize filling bins tightly.
    if progress < 0.5 {
        if post_residual > 0 && post_residual < 20 {
            score += 8.0;
        }
    } else {
        score -= 5.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * prn * prn);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, dead space is more costly
    let progress_coupling = pr * (0.5 + 2.0 * progress * progress);
    score += progress_coupling * prn;

    // Penalize residuals that can't fit the lookahead item (smooth quadratic gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let fit_penalty = gap * gap / cap;
        score += fit_penalty * (0.5 + progress);
        // Reward if next item fits exactly-ish
        if pr >= next_item_size as f64 {
            score -= 4.0 * (1.0 - (pr - next_item_size as f64) / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        // slight congestion penalty for spreading across many bins
        score += (open_bins_count as f64).ln() * 0.5;
    }

    // Prefer bins deviating from mean residual (balance extremes) — smooth term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 2.0 * dev * dev;

    // Mild reward for tight fits (item fills most of the bin)
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item
    // size classes (10, 20, 25, 50) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward residuals that lie in "harmonic" residue classes of capacity.
    let harmonic = if pr == 0 { 1.0 }
        else if cap % pr as f64 == 0.0 { 1.0 }
        else if pr % 10 == 0 { 0.6 }
        else if pr % 25 == 0 { 0.5 }
        else { 0.0 };
    score -= 8.0 * harmonic;

    // Penalize dead space: residuals too small for the smallest item (1..10)
    // are wasted; residuals < 10 are pure loss.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Integer-division threshold: post_residual must be able to host the
    // lookahead item; reward if it can, penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward if post_residual is an exact harmonic multiple
            // of next_item_size (perfect lookahead fit later).
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current bin fits are tight or the fit is very poor.
    if bin_residual == bin_capacity {
        let tightness = open_bins_count as f64 / (1.0 + mean_residual / cap);
        // Prefer new bin early in stream or when few fitting bins exist.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap - 10.0 - 15.0 * (1.0 - progress) - 8.0 * (fitting_bins_count as f64).min(3.0) / 3.0
            + 5.0 * (1.0 - tightness / (open_bins_count.max(1) as f64));
        // If item fits an open bin with decent post-residual, discourage new bin.
        if fitting_bins_count > 0 && post_residual >= 0 {
            score += 3.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (small residual = tight packing).
    score += 0.05 * (mean_residual - bin_residual as f64).abs()
        * if (bin_residual as f64) < mean_residual { -1.0 } else { 1.0 };

    // Modulo threshold on item class: large items (>= 50) prefer near-full bins.
    if item_size >= 50 && post_residual < 20 {
        score -= 7.0;
    }
    if item_size < 30 && post_residual > 70 {
        score += 5.0; // small item into a nearly-empty bin wastes it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Post-residual that cannot fit the lookahead item is a partial dead zone
    // for the k=2 horizon; penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose current residual is tight relative to the item
    // (best-fit flavor): reward small bin_residual.
    score += 0.25 * bin_residual as f64;

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and the item fits an existing one.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good existing option
        // (few fitting bins) or residuals are badly fragmented.
        score += 30.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open anyway
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 25.0;
    }

    // Slight penalty if this bin's residual is far above the mean residual
    // (keeping large residuals for larger future items).
    if bin_residual as f64 > mean_residual + 20.0 && post_residual > 0 {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            // Perfect chain: next item fits exactly into post residual.
            let gap = (post_residual as f64 - next).abs();
            score -= 18.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item would NOT fit: penalize wasted residual relative to next size.
            score += 6.0 * ((post_residual as f64) / next);
        }
        // Strong exact-chain bonus: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score -= 4.0 * (1.0 - pr / mean_residual);
    }

    // Penalize large dead space (unusable slivers) with a non-linear term.
    if pr > 0.0 && pr < 10.0 {
        score += 5.0 * (1.0 - pr / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // no open bin offers a good fit (post_residual would be small but next item huge).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64);
        if poor_fit_elsewhere {
            score -= 8.0 * (1.0 - progress);
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 20.0 + 10.0 * progress;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never be used again: post_residual below
    // the smallest possible item (1) is pure waste; below ~20 is hard to fill.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item would fit this bin but not the remainder, penalize
    // wasting the bin on the current item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        }
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 6.0;
        }
        // If next item is huge, prefer a bin whose remainder still complements it.
        if next_item_size >= 50 && (post_residual as i64 - next_item_size as i64).abs() <= 10 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: opening a bin is penalized mildly, but
    // becomes attractive when open bins have poor fits or many open bins
    // already fragment the space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 30.0
            + 20.0 * (open_bins_count as f64 / 20.0).min(1.0)
            - 15.0 * (1.0 - (item_size as f64 / 100.0));
        // Late in the stream, prefer consolidating into open bins.
        score += new_bin_penalty * (0.5 + 0.5 * progress);
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // bins with larger-than-mean residual can absorb big items; bins with
    // smaller residual are closer to closure.
    let dev = bin_residual as f64 - mean_residual;
    if item_size as f64 > mean_residual * 0.7 {
        score -= 4.0 * dev / (bin_capacity as f64);
    } else {
        score += 2.0 * dev / (bin_capacity as f64);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64;

    // Small time-based jitter-free exploration term: favor closing bins
    // early, favor tight packing later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (small post_residual), with non-linear sharpening
    let mut score = pr as f64;

    // Polynomial coupling with stream progress: early on, tolerate slack;
    // later, penalize dead space more aggressively.
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep in [0,1]
    score += (poly - 0.5) * 20.0 * (0.5 + progress);

    // Reward bins whose residual closely matches the next item (lookahead chaining)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let match_term = 1.0 - (x - nx).abs() * 2.0; // 1 when perfect match
        score -= match_term * 8.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize when this bin's residual is far below the mean (fragmented bin)
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += dev * dev * 10.0;

    // Slight preference for consolidating into fewer bins as stream progresses
    score -= (open_bins_count as f64).ln() * progress * 2.0;

    // New-bin candidate: smooth neutral-ish score so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress - (fitting_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class penalty: residual in awkward modulo classes is dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo-10 harmonic class: residuals divisible by 10 are "clean" slots.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => -18.0,
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        3 | 7 => 1.0,
        4 | 6 => -1.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division thresholds: how many "typical" item halves fit in post_residual.
    let half_slots = post_residual / 25;
    score -= 4.0 * half_slots as f64;

    // Capacity fraction coupling: penalize residuals in the awkward (0.05..0.20) band.
    let frac = pr / cap;
    if frac > 0.0 && frac < 0.20 {
        score += 22.0 * (0.20 - frac);
    } else if frac >= 0.20 && frac <= 0.50 {
        score -= 8.0 * frac;
    }

    // Lookahead coupling: reward if next item exactly fills post_residual or a divisor class of it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 12.0;
            }
            score += gap as f64 * 0.15;
        } else {
            // next item cannot fit here; slight penalty proportional to overshoot class
            let over = next_item_size - post_residual;
            score += (over % 10) as f64 * 0.8;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / cap);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        // default new-bin score: slightly worse than a perfect fit, better than awful fits
        score = cap * 0.55 - 20.0 * mean_tightness - 10.0 * progress + 5.0 * open_pressure;
        // if item is large, new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mild preference for bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual >= 1 && post_residual <= 9 {
        score += 45.0 - 4.0 * post_residual as f64;
    }
    // Medium gaps (10..=19): moderately bad unless next item can use them.
    else if post_residual >= 10 && post_residual <= 19 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // lookahead item fits the gap: good
        } else {
            score += 12.0;
        }
    }
    // Larger gaps: mildly favor if the next item fits exactly-ish.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= (20.0 - slack as f64).max(0.0) * 0.4;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; keep it competitive with bad fits.
        score = 55.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits anyway, new bin is necessary
        }
        if fitting_bins_count == 1 {
            score += 20.0; // an existing last-chance bin exists; prefer it
        }
    }

    // Progress-based mild bias: early on, allow more consolidation flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect chain: post_residual exactly matches next item -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the leftover space (loose chain) -> reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize more the bigger the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.8 * gap;
    }

    // Compare post_residual against mean residual: leaving more than average waste is bad.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless it enables a perfect lookahead chain
    // or current bins are too fragmented / few fitting options.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 70.0; // pack pair into fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good alternative exists
        }
    }

    // Late in the stream, consolidate: favor tighter fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with more open competition (spread load).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (low post residual), more aggressively later in the stream.
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + progress);

    // Penalize small dead space that is hard to fill: post_residual in low band is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - progress);
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving awkward leftovers.
        score += 2.0;
    }

    // Prefer filling bins with below-average residual (reduce fragmentation).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Many open bins: encourage closing them out (prefer bins with small residual).
    if open_bins_count > 3 {
        score += (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64 - 3.0) * 0.5;
    }

    // New-bin candidate: only attractive early, or when this bin would be a terrible fit.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.6;
        if progress < 0.15 || (poor_fit && fitting_bins_count <= 2) {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), smoothed polynomial
    let mut score = 2.0 * x * x - 2.0 * x + 1.0; // parabola minimized at x=0

    // Non-linear coupling with stream progress: late in stream, tolerate larger
    // post residuals less (waste matters more); early, allow spreading.
    let progress_coupling = (1.0 - progress) * (x * (1.0 - x)) * 4.0;
    score += 0.8 * progress_coupling;

    // Lookahead: if next item fits into post residual, reward strongly (smoothly).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = ((x - nx).max(0.0)) / (x.max(1e-9) + nx).max(1e-9);
        score -= 1.5 * (1.0 - fit) * nx * (1.0 + progress);
    } else {
        // last item: only tightness matters
        score -= 0.5 * (1.0 - x);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - x * x);
    }

    // Mild penalty when bin residual deviates from mean residual (keep balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Slight preference for using existing bins over opening new ones
    score -= 0.1 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "resonant" size classes (multiples of capacity fractions) are more
    // likely to be filled by future items, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Resonance classes: post_residual divisible by 25, 20, 10, 5 are
    // "harmonic" leftovers (likely to pair with common item sizes).
    if post_residual > 0 {
        if post_residual % 25 == 0 {
            score -= 8.0;
        } else if post_residual % 20 == 0 {
            score -= 6.0;
        } else if post_residual % 10 == 0 {
            score -= 4.0;
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        } else {
            // Non-harmonic dead space: penalize proportionally to how
            // "off-grid" it is (distance to nearest multiple of 5).
            let off = (post_residual % 5) as f64;
            score += off * 1.5;
        }
        // Very small unusable leftover is dead space: penalize.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 1.2;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 20.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item
    // in a harmonic class? If next_item_size divides post_residual well,
    // reward this bin (it will be usable again immediately).
    if next_item_size > 0 && post_residual >= next_item_size {
        let n = next_item_size as f64;
        let ratio = pr / n;
        if ratio.fract() < 0.05 {
            score -= 5.0; // next item fills this bin almost exactly
        } else {
            score -= 2.0; // next item still fits
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: mild penalty scaled by tightness.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: opening a new bin should only win when the
    // current bin would be left with bad dead space. Penalize the empty
    // bin candidate moderately, scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 6.0 * (1.0 - progress);
        // But if the current placement would waste > 40% of capacity,
        // opening a fresh bin becomes attractive: reduce the penalty.
        if pr > 0.4 * cap {
            score -= 14.0;
        }
    }

    // Prefer bins that are already tight (low residual) to compact load:
    // tie-break with fill fraction.
    let fill = (cap - pr) / cap;
    score -= fill * 3.0;

    // Mild preference to keep the number of open bins from exploding
    // early in the stream.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 40.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Residual that exactly serves the next item is valuable.
        score -= 8.0;
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins: reward small post_residual relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // a new bin is cheaper.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open and mean
        // residual suggests existing bins could absorb the item.
        score += 25.0 + pressure * 3.0 + mean_residual * 0.3;
        // But if item is large and mean residual is small, opening new bin is fine.
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 30.0;
        }
        // Never open a new bin when this would waste a nearly-full existing bin's slot.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score += 10.0;
        }
    }

    // Mild bonus for bins tighter than the average residual (good consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportional to leftover waste after both placements
            let waste2 = post_residual - next_item_size;
            score += waste2 as f64 * 0.5;
        } else {
            // next item does not fit: penalize dead space that likely strands this bin
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current open bins are nearly full / poor fits
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // open new bin only if existing residuals are small (items barely fit)
        score += 300.0 - avg_open * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // keep new bin clean for future items
            score += (bin_capacity - next_item_size) as f64 * 0.2;
        }
    }

    // Late-stream tightening: waste matters more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Reward filling bins exactly / near-exactly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead space penalty: post_residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
            // If next item would need a fresh bin anyway, mild reward for tight fill.
            if post_residual < next_item_size && post_residual < 20 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread = (mean_residual - post_residual as f64).abs();
        score += 25.0 - spread * 0.3 - open_bins_count as f64 * 0.5 - progress * 10.0;
        // Discourage new bins when current item leaves a nicely reusable residual.
        if post_residual >= item_size {
            score += 20.0;
        }
    }

    // Prefer bins below mean residual (consolidate space) slightly.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Late in stream, be greedier: favor tightest fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post-residual, with non-linear penalty on dead space
    let mut score = post * (1.0 + 0.8 * (post / cap).powi(2));

    // Reward tight fits (smooth coupling, no hard cutoffs)
    score -= 30.0 * fit_ratio.powi(3);

    // Lookahead: penalize leaving residuals that cannot host the next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += 20.0 * gap * gap;
        // Reward residuals that exactly serve the next item
        let match_q = (post - next_item_size as f64) / cap;
        score -= 10.0 * (-match_q * match_q * 40.0).exp();
    }

    // Last fitting bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Stream progress: as stream advances, consolidate more aggressively
    score -= 12.0 * progress * (post / cap);

    // Penalize scattering when many bins are open relative to mean residual
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * ((post - mean_residual).abs() / cap);

    // New-bin candidate: make empty bin mildly attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score = 0.5 * cap - 25.0 * item_frac * item_frac + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition dead space into residue classes mod 10.
    // Residuals that are small-but-not-zero (1..=9) are nearly unusable dead space; penalize.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }
    // Perfect fit is the ideal outcome.
    if pr == 0 {
        score -= 25.0;
    }

    // Harmonic pairing: does next_item_size exactly fill the new post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect two-item chain
        } else if next_item_size < pr {
            let rem = pr - next_item_size;
            if rem < 10 {
                score += rem as f64 * 1.5; // would leave small dead space
            } else {
                score -= (rem.min(bin_capacity / 2)) as f64 * 0.3;
            }
        } else {
            // next item cannot follow here; the bin is terminal after this placement.
            score += 5.0 + (pr as f64) * 0.5;
        }
    } else {
        // Last item: prefer exact closure.
        if pr == 0 {
            score -= 10.0;
        }
    }

    // Integer-division threshold on fill fraction (capacity quarters).
    let used = bin_capacity - pr;
    let quarter = bin_capacity / 4;
    if used >= 3 * quarter {
        score -= 8.0;
    } else if used >= 2 * quarter {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (mean_residual - item_size as f64).abs() < 1e9 && mean_residual >= item_size as f64 * 0.9;
        if good_fit_exists {
            score += 15.0; // prefer existing bins when they fit reasonably
        } else {
            score -= 5.0; // opening a fresh bin is fine
        }
    }

    // Prefer tighter bins overall (residual close to item size means snug fit).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += snug * 0.25;

    // Late in the stream, be greedier about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * (0.1 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (12.0 - post_residual as f64) * 4.0; // up to +44 for gap of 1
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Reward near-perfect fits that still leave a usable gap (>= 10).
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Prefer bins whose residual tightly matches the item (small relative slack).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly penalize placements into bins when many bins are open,
    // encouraging consolidation; but for the new-bin candidate (residual == capacity),
    // add a penalty so a new bin is only opened when fits are genuinely bad.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current fits would create dead space.
        score += 20.0 + open_bins_count as f64 * 0.5;
        if post_residual == 0 {
            score -= 0.0; // irrelevant for empty bin
        }
        // If the next item could use the fresh bin well, slightly soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    } else {
        score += open_bins_count as f64 * 0.3;
    }

    // Lookahead: if the post-residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If post-residual cannot host next item but bin_residual could have, penalize slightly.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Stream progression: later in stream, be more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that the item fills exactly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Slack proportional to how loosely the next item fits.
            score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot follow here: penalize wasted potential.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are worth using.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when existing bins can absorb the item reasonably.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.2 * open_bins_count as f64;
        // But allow a new bin if current item + next item pair would leave bad fragments elsewhere.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 40.0;
        }
    }

    // Dead-space penalty: small unusable leftovers are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Late-stream tightening: prefer compact packing as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a nonlinear term.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space: residuals too small to fit even the smallest item (1).
    if post_residual > 0 {
        score += (post_residual as f64) * (post_residual as f64) / 200.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the current bin would leave a very
    // unusable remainder, or when the item plus lookahead pair fits perfectly in a fresh bin.
    if bin_residual == bin_capacity {
        let fresh_penalty = 40.0 + 3.0 * (open_bins_count as f64).sqrt();
        score += fresh_penalty;
        if next_item_size > 0 && next_item_size <= post_residual {
            // Fresh bin can host both current and next item: strong bonus.
            let pair_left = post_residual - next_item_size;
            score -= 20.0 + (pair_left as f64).min(10.0);
        }
        // Late in the stream, opening a fresh bin is riskier (wasted capacity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead synergy: reward leaving a residual that exactly hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / 50.0).max(0.0);
        } else {
            // Next item cannot follow here; slight penalty proportional to gap.
            score += 2.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Global state coupling: prefer spreading load when mean residual is high,
    // prefer consolidating when open bins are few.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * spread;

    // Mild consolidation preference early, exploration later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, small residuals are tolerated; late, tight fits matter more.
    let w = 0.5 + 0.5 * progress;
    let tightness = (pr / cap).powi(2) * (1.0 + 2.0 * progress);

    let mut score = pr * w + tightness * cap;

    // Penalize residuals that are awkwardly sized relative to mean residual
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space exactly matching the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0);
        // Penalize dead space smaller than next item
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 0.3 * pr;
        }
    }

    // Mild preference for compacting into fewer bins
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        let crowd = fitting_bins_count as f64;
        score = cap * (1.0 + progress) - 10.0 / (1.0 + crowd);
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residuals are "dead space"
    let tiny = post_residual < 10;
    let small = post_residual < 25;
    if tiny {
        score -= 40.0; // near-perfect fill, reward strongly
    } else if small {
        score += 12.0; // awkward leftover, penalize
    }

    // Modulo classes: residuals that are multiples of common item sizes (10/20/25/50)
    // are reusable by future items -> reward them.
    let reusable = post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual == 50;
    if reusable && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division threshold: post_residual bucketed by fifths of capacity
    let fifth = (post_residual * 5) / bin_capacity;
    score += fifth as f64 * 2.5;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // harmonic match: post_residual mod next_item_size small
            let m = post_residual % next_item_size;
            if m < 10 {
                score -= 15.0 - m as f64;
            } else {
                score += m as f64 * 0.3;
            }
        } else {
            // next item won't fit here anyway; slight penalty for wasting lookahead
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin when stream is early (amortization) or few bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // if next item is huge, a fresh bin is attractive
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins far from the mean when mean is high (consolidation)
    let diff = (bin_residual as f64 - mean_residual).abs();
    if mean_residual > bin_capacity as f64 * 0.5 {
        score += diff * 0.2;
    } else {
        score -= diff * 0.1;
    }

    // Prefer tighter fits overall: reward small post_residual relative to item
    if item_size > 0 {
        score += (post_residual as f64 / item_size as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward using a bin whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Open bins pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: make an empty bin mildly attractive only when
    // existing bins would leave bad dead space or few bins fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if post_residual < 10 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Slight mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: minimize post_residual (tight fit), but with diminishing returns
    // so tiny residuals aren't over-favored vs. leaving room for the next item.
    score = (post_residual as f64).powf(0.85);

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    // (chained placements), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus: scaled by how snugly the next item lands too.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 20.0 * chain_tightness;
        } else {
            // Next item won't chain here; penalize leftover dead space that
            // is too small to be useful for typical items.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 8.0 * (10.0 - dead);
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates from the mean
    // in a productive direction (larger residual absorbs large items, small residual
    // is only good if we close it out now).
    let rel = bin_residual as f64 - mean_residual;
    score -= 0.05 * rel;

    // Last-chance logic: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one where the item is proportionally largest.
        score += 0.3 * (bin_residual as f64 - item_size as f64);
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer it
    // when no open bin offers a decent fit — i.e., penalize opening a new bin
    // unless the current item is large and would leave a very tight residual elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins early in the stream is fine (long horizon to fill them),
        // later it wastes capacity.
        score += 15.0 + 20.0 * progress;
        // But if the item is huge relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 18.0;
        }
        // If the next item is also huge, a fresh bin gives the best chain.
        if next_item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic bonus for small leftover space.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 60.0 * (1.0 - tightness);

    // Perfect fit: overwhelming preference.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 120.0; // dead space too small for any item is fine
    }

    // Lookahead coupling: reward residuals that the next item can exactly or nearly fill.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 80.0 * (1.0 - slack / 10.0);
            }
        } else {
            // next item cannot use this residual at all: mild penalty scaled by waste
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Penalize bins whose residual deviates from the mean (keep residuals homogeneous
    // so future items have consistent targets), unless it's an empty new bin.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.25 * dev;
    }

    // New-bin candidate: default cost of opening a bin; make it cheaper late in the
    // stream or when open bins are numerous and fragmented.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut new_bin_cost = 40.0;
    new_bin_cost -= 25.0 * progress;
    new_bin_cost += 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_cost;
        // If no open bin fits well, opening a bin is fine; if this is a last-chance
        // situation elsewhere we already rewarded that bin.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with upcoming large items
        }
    }

    // Mild global pressure: when many bins are open, prefer consolidation.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let quad = norm_pr * norm_pr;
    let cubic = quad * norm_pr;
    score += 24.0 * quad * (0.5 + progress);
    score -= 18.0 * cubic * (1.0 - progress);

    // Tight fits are valuable; reward small normalized post-residual smoothly.
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Penalize residuals that cannot fit the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).max(0.0) / cap;
        let gap2 = gap * gap;
        score += 20.0 * gap2 * (0.5 + 0.5 * progress);
        // Reward exact next-item fit.
        let fit_err = (pr - nxt).abs() / cap;
        score -= 14.0 * (1.0 - fit_err).powi(4);
    } else {
        score += 10.0 * norm_pr * norm_pr;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual slightly (balance load smoothly).
    score += 6.0 * ((bin_residual as f64 - mean_residual) / cap) * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize mildly early, more when open bins fit well.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 12.0 * (1.0 - progress) - 8.0 * scarcity * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: quantize post_residual into
    // capacity-fraction buckets and reward "reusable" gap classes.
    let post_class = (post_residual * 4) / bin_capacity; // 0..=3
    match post_class {
        0 => score -= 6.0,              // tiny gap: near-perfect fill
        1 => score -= 1.5,              // quarter-class gap: quite usable
        2 => score += 1.0,              // half gap: mediocre
        _ => score += 3.0,              // large gap: wasteful placement
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this gap: penalize small residual traps
            score += 4.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a mild default score;
    // prefer it only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits, must open
        }
    }

    // Prefer filling bins with small residuals relative to the fleet mean.
    score -= 0.8 * (mean_residual - bin_residual as f64);

    // Late-stream pressure: consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a small unusable gap is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if next item could use this bin's post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // New empty bin candidate: penalize unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + 1.5 * open_bins_count as f64;
    }

    // Mean residual coupling: if this bin is far below mean residual, it is a good aggregator.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact matches with the next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Penalize residuals far below the mean (fragmentation relative to fleet).
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bins
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bins are crowded.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * mean_residual.min(100.0);
    }

    // Slight preference for using fuller bins (smaller residual) as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but nonzero-ish.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += dead * (1.0 + 20.0 / (dead + 5.0)) * 0.3;
    } else {
        score -= 25.0; // perfect closure
    }

    // Lookahead: if next item fits in the post-residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.3 * next_item_size as f64;
        } else {
            // wasted capacity for the lookahead item
            score += 3.0 + 0.1 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more when open bins exist and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 15.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if the item is large relative to capacity and mean residual is low, opening is fine.
        let large_item = (item_size as f64) / bin_capacity as f64;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0 * large_item;
        }
    }

    // Mild preference for bins tighter than the mean residual (compact packing).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: prefer bins that can absorb more as stream ends.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * (bin_residual as f64 - item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (low post_residual), softened by a smooth power
    let mut score = (pr / cap).powf(0.6) * cap;

    // Non-linear coupling with stream progress: later in the stream,
    // small dead space matters more (penalty grows smoothly).
    let tightness = 1.0 - (pr / cap).powf(2.0);
    score += progress * (1.0 - tightness) * 20.0;

    // Reward bins whose residual matches the next item's size (smooth Gaussian-like coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = ((pr - nx) / cap).powf(2.0);
        score -= 15.0 * (-4.0 * match_term).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far from the mean residual (keep residual distribution tight),
    // smoothly weighted by open bin count.
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * (open_bins_count as f64).ln_1p().min(4.0) * 5.0;

    // Mild preference for using existing bins over opening new ones,
    // decaying as the stream progresses (early on, new bins are cheaper).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 10.0 * (1.0 - progress) + pr * 0.05;
    }

    // Slight reward for large items filling bins well (smooth in item size)
    score -= (it / cap).powf(2.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows superlinearly for tiny unusable leftovers
        if pr < 10 {
            score += 30.0 * (10.0 - pr as f64);
        } else {
            // harmonic reward: leftover divisible by common item granularities
            let mut harmon = 0.0;
            for &d in &[10u32, 20, 25, 50] {
                if pr % d == 0 {
                    harmon += 6.0;
                }
            }
            // integer-division threshold: leftover >= 50 keeps half-bin utility
            if pr >= 50 {
                harmon += 8.0;
            } else if pr >= 25 {
                harmon += 3.0;
            }
            score -= harmon;
        }
    } else {
        // perfect fill: strong reward
        score -= 25.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact match is gold
            if post_residual == next_item_size {
                score -= 20.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 10.0 * (slack / cap).min(1.0);
                // penalize if leftover leaves a bad class after next item
                let after = post_residual - next_item_size;
                if after < 10 && after > 0 {
                    score += 8.0;
                }
            }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin for a small item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_residual as f64) / cap;
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0) / 20.0);
    score += 10.0 * fill_frac * pressure.min(3.0);

    // New-bin candidate: only attractive when current item is large relative
    // to capacity or open bins are all poor fits.
    if bin_residual == bin_capacity {
        let big = (item_size as f64) / cap;
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score = 40.0 - 25.0 * big - 20.0 * mean_gap.min(1.0) + 5.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

