    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual).abs() * 0.4;
    } else {
        // New-bin candidate: penalize mildly so it only wins when fits are terrible;
        // escalate penalty as more bins are already open.
        score += 10.0 + open_bins_count as f64 * 2.0;
        // Allow new bin when item fits very poorly in existing residual patterns.
        if fit_ratio < 0.35 {
