    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Discard wasting a large bin on a tiny item when many bins are open
    let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += waste * 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: prefer opening fresh bin only if current fit is terrible
    if bin_residual == bin_capacity {
        score += 60.0 + post_residual as f64 * 0.5;
    }

    // Late in stream: be more conservative, keep residuals tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
