    // New-bin candidate handling: penalize opening a new bin unless current residuals are all poor.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_waste = mean_residual;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 45.0 + 2.0 * open_pressure + 0.5 * mean_waste;
        // Late in the stream, opening new bins is less costly (fewer future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
