    // Mild preference for bins whose residual deviates from mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight global pressure: many open bins -> prefer existing bins.
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core tightness: normalized post-residual, polynomially coupled with stream progress.
    let x = post / cap;
    let mut score = post * (1.0 + 0.5 * x * x);

    // Late in the stream, waste becomes more costly (fewer chances to fill it).
    score += 30.0 * progress * x * x * cap;

    // Reward near-perfect fits with a smooth quadratic bonus.
    score -= 60.0 * (1.0 - x) * (1.0 - x) * (item_size as f64 / cap);

    // Penalize bins whose residual deviates from the fleet mean (fragmentation).
    score += 0.3 * (post - mean_residual).abs();

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // New-bin candidate: discourage unless this bin would be badly fragmented
    // or the item fits almost perfectly into a fresh bin.
    if bin_residual == bin_capacity {
        let base = cap * 0.55 + 25.0 * progress;
        let escape = if post < next_item_size as f64 && next_item_size > 0 { 0.0 } else { 60.0 };
        score = score.max(base + escape);
    }

    // Lookahead: bonus if the next item fits into the post-residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in
    // "reusable" classes (multiples of small divisors) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        // reward residuals divisible by small harmonics (likely reusable)
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 2 == 0 { score -= 1.0; }
        // penalize dead space: very small unusable leftovers
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 8.0; }
    } else {
        // perfect fit
        score -= 40.0;
    }

    // Fraction-of-capacity classes for the item itself
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        // large items: prefer tight bins, discourage wasting big bins
        score += 4.0 * (bin_residual as f64 / bin_capacity as f64);
    } else if frac < 0.25 {
        // tiny items: fine almost anywhere, mild preference for fuller bins
        score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic check on leftover after the lookahead item
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
            if pr2 == 0 { score -= 15.0; }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 0.05 * pr as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer reusing
    // existing bins when their residual is well-matched.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // late in the stream, opening new bins is fine since bins won't fill again
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 { score -= 10.0; }
    }

    // Slight pull toward bins below mean residual (balancing)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit even the smallest
    // plausible item are wasted forever -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2) when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that fails the lookahead: mild extra penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it strongly
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening a new one;
    // the empty-bin candidate gets a rising penalty.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, consolidating is even more important.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Mild reward for using existing bins as open-bin count grows.
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fit of the next item into the post-residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as u32 >= next_item_size {
            // Next item fits: reward closeness of match
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize large leftover dead space
            score += 0.3 * post_residual as f64;
        }
        // Bonus if post_residual exactly equals next item size (perfect 2-chain)
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tight bins)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize wasting a nearly-full bin on a small item
    if item_size < bin_residual / 2 {
        score += 5.0;
    }

    // Mild penalty for opening a new bin when few bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness).powi(3);

    // Penalize dead space that becomes unusable: post_residual below smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item won't chain here: penalize leaving awkward small residuals.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when global
    // residuals are fragmented (mean residual low relative to item) or late stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let pressure = (open_bins_count as f64) / (1.0 + progress * 10.0);
        // Base cost of a new bin, discounted when open bins are mostly full.
        score += 30.0 - 15.0 * fragmentation - 5.0 * pressure.min(1.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin reserves room for a follow-up large item
        }
    }

    // Prefer bins with residual near mean (balanced packing) mildly.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    // Time horizon: early on, be conservative with tight fits (keep flexibility);
    // late, exploit them harder.
    score -= (1.0 - progress) * 6.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 0.35 * norm_pr * (p2 + 0.5 * p3);

    // Penalize large dead space more aggressively as stream progresses
    score += 0.2 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (small post_residual) with smooth decay
    score -= 0.5 * (-norm_pr * 6.0).exp();

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let slack = (pr - n).max(0.0) / cap;
        score -= 0.3 * slack / (1.0 + slack);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it competitive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 0.15 + 0.3 * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class penalty: dead space in awkward residue classes is worse.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual by modulo classes (harmonic bins of size 10).
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0,           // perfectly reusable class
        1..=3 => 4.0,        // nearly useless slivers
        4..=6 => 0.0,
        7..=9 => -2.0,       // still usable for mid-size items
        _ => 0.0,
    };
    score += class_penalty;

    // Small post-residual = tight fit: reward strongly (less fragmentation).
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here; slight penalty for wasting tight space
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with residual far below mean (consolidate fragmentation).
    score -= 0.3 * (mean_residual - pr);

    // Fraction-of-capacity fill ratio reward.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 10.0 * fill * fill;

    // New-bin candidate: penalize opening a new bin unless current bin is very full
    // or the item barely fits anywhere. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 8.0 + 10.0 * (1.0 - progress);
        // If item is large and would leave awkward residue in a fresh bin, discourage more.
        let fresh_residue = bin_capacity - item_size;
        if fresh_residue < 20 {
            score += base + 6.0;
        } else {
            score += base;
        }
        // Early in the stream, opening new bins is cheaper (keeps options open).
        if progress < 0.25 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 25.0 * (20.0 - post_residual as f64) / 10.0;
        } else {
            // Larger leftovers are partially reusable; mild reward scaled by reusability.
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless fit is tight.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += 6.0 * open_pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is attractive only if the current
    // fit is bad (large dead space) or no open bin fits well.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual <= 10 { 60.0 * (11.0 - post_residual as f64) } else { 0.0 };
        if dead_space_penalty >= 40.0 || fitting_bins_count == 0 {
            score -= 55.0; // open a new bin rather than create dead space
        } else {
            score += 35.0; // keep using existing bins for decent fits
        }
    }

    // Mild tie-break: prefer bins whose residual deviates from mean (consolidation).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Late-stream tightening: as the stream progresses, prefer tighter fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by item size
    // so large items get stronger packing pressure.
    let item_f = item_size as f64;
    score += 0.35 * (bin_capacity as f64 - item_f) * (post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual,
    // penalize if post_residual is a dead zone relative to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            // Perfect 2-step match: strong reward
            score -= 45.0 + 0.5 * item_f;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: reward proportional to closeness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize
            score += 0.6 * (post_residual as f64).min(nxt - post_residual as f64);
        }

        // Two-step chain: would item + next both fit residual?
        let two = item_f + nxt;
        if bin_residual as f64 >= two {
            score -= 8.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious
    // tight fits; keep them for good use.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild preference for reusing bins over opening new ones as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly over time and with many open bins.
        score += 12.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fills
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Penalize unusable dead space: residual too small for the smallest plausible item
    if post_residual < 10 {
        score -= 15.0; // a perfectly closed bin is great
    } else if post_residual < item_size {
        score += 8.0; // dead space smaller than any incoming item
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: bonus if next item fits in the post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - progress * 0.5);
    }
    // Penalize if post-residual is "almost" fitting the next item (wasted opportunity)
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
    }

    // Global state: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 25.0 + pressure * 4.0;
        // Late in the stream, filling existing bins matters more
        score += progress * 20.0;
        // But if no existing bin fits well (large residual mismatch), allow new bin
        if mean_residual < item_size as f64 * 1.1 {
            score -= 35.0;
        }
    }

    // Prefer bins below mean residual (consolidate fragmented space)
    score += (mean_residual - post_residual as f64) * 0.15;

    // Mild reward for placing into well-used bins early (first-fit-like behavior)
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: early on, tolerate slack;
    // later, penalize residual dead space more aggressively.
    score += 3.0 * norm_pr * progress * (1.0 - progress) * (norm_pr - fit);

    // Reward filling a bin nearly completely, stronger as stream advances.
    score -= (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= snug * (0.3 + 0.7 * progress);
        } else {
            score += 0.2 * progress;
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.01 * norm_pr;

    // Deviation from mean residual: prefer bins whose residual differs favorably.
    score += 0.05 * (pr - mean_residual).abs() / cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of small
    // denominators (10, 20, 25, 50) is more reusable; other values are penalized.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward post-residuals that divide the capacity harmonically (reuse potential)
    if post_residual > 0 {
        if bin_capacity % post_residual == 0 {
            score -= 6.0;
        } else if post_residual % 10 == 0 {
            score -= 3.0;
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        } else {
            // irregular dead space
            score += 2.0;
        }
    }

    // Integer-division thresholds: small post_residual => near-full bin, good.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter / 2 {
        score -= 5.0;
    } else if post_residual <= quarter {
        score -= 2.0;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual,
    // strongly favor this bin (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly, but allow it when mean residual is low
    // (existing bins are fragmented) or the item is large.
    if bin_residual == bin_capacity {
        score += 4.0
            - 6.0 * (mean_residual / cap_f)
            - 0.04 * item_size as f64;
    }

    // Prefer filling bins that are already relatively full (tight packing).
    let fill_frac = 1.0 - (bin_residual as f64) / cap_f;
    score -= 3.0 * fill_frac;

    // Slight preference for keeping the number of open bins bounded.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that cannot fit even the smallest plausible item (or the
    // known next item) is wasted capacity.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size) {
        score += 60.0; // dead space below next item's needs
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // cannot host the lookahead item
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Reward bins that can still host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when this bin is the last
        // chance or fits are terrible.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        } else {
            score += 45.0 + pressure;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strongly prefer using this bin over opening a new one.
        score -= 35.0;
    }

    // Slight preference toward bins tighter than average (better fits).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild progress scaling of dead-space penalty: late in the stream,
    // wasted space is costlier.
    score += post_residual as f64 * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits comfortably in the post residual (near-perfect chain).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0);
    }
    // Next item cannot fit: dead space created, penalize proportionally.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = next_item_size.min(post_residual) as f64 / post_residual as f64;
        score += 20.0 * (1.0 - waste);
    }

    // Penalize residuals that become too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins whose residual is already below average (tighter bins first),
    // keeping larger residual bins flexible for future large items.
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f).min(25.0);
    } else {
        score += (residual_f - mean_residual).min(25.0) * 0.5;
    }

    // Mild bias toward consolidating into fewer bins when many are open.
    score -= (open_bins_count as f64).min(20.0) * 0.3;

    // Early in stream: be slightly conservative, keep bins open for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Brand-new empty bin candidate: only attractive if item is large and
    // open bins are mostly full.
    if bin_residual == bin_capacity {
        score += 35.0 - item_size as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight * tight;

    // Penalize dead space that no future item (size >= 1) could pair with well:
    // residuals that are small but nonzero are risky.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot follow here; slight penalty for wasting the lookahead.
        score += 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when current fit is bad
    // or the stream is early and many more items are expected.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score -= pressure * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mild preference for bins below mean residual (balancing residuals).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.02 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 + progress);

    // Reward tight fits: subtract a smooth function of small post_residual
    let tight_bonus = -2.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Penalize dead space that next item cannot use
    let next_fit = if next_item_size > 0 && (next_item_size as f64) <= pr {
        0.0
    } else {
        norm_pr * (1.0 + progress)
    };

    // Last-chance bonus when this is the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -1.5 * (1.0 + progress) } else { 0.0 };

    // Slight pull toward bins near mean residual to keep balance
    let balance = 0.3 * (pr - mean_residual) / cap;

    let mut score = poly + tight_bonus + next_fit + last_chance + balance;
    score += pr * 0.01;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity fractions
    // are more reusable. Quantize post_residual into classes of 5.
    let class = post_residual / 5;
    let harmonic_bonus = match class {
        0 => 60.0,                 // near-perfect fit, dead space minimal
        1..=2 => 40.0,             // small gap, still very usable
        3..=5 => 25.0,             // mid-small gap
        6..=9 => 10.0,             // medium gap
        10..=14 => 0.0,            // large gap, neutral
        _ => -5.0,                 // near-empty bin residual
    };
    score -= harmonic_bonus;

    // Modulo-class coupling: if next item fits exactly into post_residual,
    // strongly reward (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item fills the gap.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
            // Penalize awkward leftover classes after the lookahead placement.
            let chain_left = post_residual - next_item_size;
            if chain_left > 0 && chain_left < 10 {
                score += 8.0 * (1.0 - chain_left as f64 / 10.0);
            }
        } else {
            // Next item cannot use this bin's gap: mild penalty scaled by gap size.
            score += 3.0;
        }
    } else {
        // Last item: prefer tightest possible fit, no lookahead concerns.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large (creates a well-packed fresh bin) or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size >= bin_capacity / 2;
        let poor_alternatives = mean_residual < item_size as f64 * 0.75;
        if large_item || poor_alternatives || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            // Early stream: discourage bin proliferation.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 25.0 * (1.0 - progress) + open_bins_count as f64;
        }
    }

    // Penalize bins whose residual deviates strongly from the mean (imbalance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Integer-division threshold: bins whose residual is in a "harmonically
    // awkward" zone (just below half capacity) create dead space.
    if post_residual > bin_capacity / 4 && post_residual < bin_capacity / 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 20 && post_residual > 9 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Open-bins pressure: prefer filling existing bins over opening new ones.
    score += 0.9 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that can fit the item, favor it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a new bin is more attractive when few bins are open.
        score -= 1.2 * open_bins_count as f64;
        // If the item would leave a large awkward gap in existing bins, new bin looks better.
        if post_residual >= 30 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }

    // Slight preference for tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Early stream: be a bit more willing to open bins (exploration), later: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // 2-step lookahead: reward if next item fits into post_residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use.
        score += 10.0 + 0.3 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Penalize creating unusable dead space (below min item size 1 => any leftover is usable,
    // but very small leftovers are still wasteful).
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Penalize deviation from mean residual: prefer bins near the average residual
    // (keeps bin population balanced), unless it is the last fitting bin.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item fits poorly
    // everywhere else or open bins are crowded; make empty-bin mildly costly by default.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if many open bins and item is large, new bin is fine.
        if item_size >= 60 {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 4.0; // room to pair items in the fresh bin
        }
    }

    // Late in the stream, prefer consolidation of open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that can't hold typical small items (<=10).
    if post_residual < 10 {
        score += 0.0; // perfect fill, nothing wasted
    } else {
        score += 2.5 * (10.0 - (post_residual as f64).min(10.0)).abs().max(0.0);
        score += 6.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Lookahead: if next item fits into post_residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // chain fit quality
        let chain = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 15.0 * chain;
    } else if next_item_size > 0 {
        // next item won't fit here after placement; mild penalty scaled by gap
        score += 4.0 * ((next_item_size - post_residual) as f64).min(30.0) / 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // mild dispersion penalty when many bins compete
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: prefer filling bins when mean residual is low (consolidation phase).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (1.0 - progress) * (mean_residual / (bin_capacity as f64)).max(0.0).min(1.0);

    // Penalize opening new bins early when decent open bins exist;
    // late in the stream, allow new bins more freely.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).sqrt();
        score += 12.0 * pressure * (1.2 - progress).max(0.2);
        // but if item is large and mean residual is tight, new bin is fine
        score -= 10.0 * (item_size as f64 / 100.0) * (1.0 - mean_residual / (bin_capacity as f64)).max(0.0);
    }

    // Waste-ratio coupling: penalize bins whose residual is far from mean (outliers).
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += 1.2 * dev / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Base: reward tight fits (low post residual), scaled non-linearly
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (pr / cap) * (pr / cap) * (0.5 + 0.5 * progress) * (1.0 - progress);
    score += 20.0 * coupling;

    // Dead-space penalty: residuals too small for typical items
    let dead = if pr > 0.0 {
        let t = (pr / cap).clamp(0.0, 1.0);
        (1.0 - t) * t * t * 4.0
    } else { 0.0 };
    score += dead * cap;

    // Lookahead: bonus if next item fits in post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 8.0 * (1.0 - pr / cap) * (1.0 - ns / cap);
        } else {
            score += 4.0 * (1.0 - progress) * (ns - pr) / cap;
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Prefer filling bins when many bins are open
    let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).clamp(0.0, 1.0);
    score -= 6.0 * open_norm * (1.0 - pr / cap);

    // Align with mean residual: penalize outliers far from mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate handling: neutral baseline, slightly discouraged early
    if bin_residual == bin_capacity {
        score += 2.0 + 10.0 * (1.0 - progress) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: modulo arithmetic on capacity ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Residual classes: residues mod 10 and mod 20 create "harmonic" dead-space bands.
    let res10 = post_residual % 10;
    let res20 = post_residual % 20;
    // Small non-zero residues are dead space; reward exact-zero residuals strongly.
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else {
        // Penalize awkward small residues (1..9) proportionally.
        score += (10 - res10 as i64) as f64 * 0.8;
        // Even residue classes are friendlier (many items are multiples of 10).
        if res20 == 0 && post_residual != 0 {
            score -= 6.0;
        } else if res10 == 0 {
            score -= 3.0;
        }
    }

    // --- Capacity fraction thresholds on post_residual ---
    let frac = pr / cap; // fraction of bin still free
    if frac > 0.5 {
        score += 4.0; // leaving more than half is wasteful for a used bin
    } else if frac < 0.1 && frac > 0.0 {
        score -= 5.0; // near-closed bin is good
    }

    // --- Integer division threshold coupling with next item ---
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= post_residual {
            // Next item fits here: strong lookahead reward, scaled by how snugly.
            let slack = (post_residual - n) as f64;
            score -= 12.0 - slack * 0.15;
            // Harmonic bonus: next item exactly divides the residual.
            if post_residual % n == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this residual: penalize residuals that are
            // "just barely" too small (worst dead space).
            let miss = (n - post_residual) as f64;
            if miss <= 10.0 {
                score += miss * 0.9;
            }
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // only bin that fits: strongly prefer it over opening new
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // New bin baseline: score = capacity. Make it attractive only when
        // existing bins would leave large dead space.
        let dead_if_here = pr;
        if dead_if_here > 0.0 && dead_if_here < 20.0 {
            score -= 10.0; // keep new bin unattractive when fit is decent
        } else if dead_if_here >= 40.0 {
            score += 15.0; // push toward opening a fresh bin on bad fits
        }
        // Early stream: prefer opening bins to keep flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 {
            score -= 8.0 * (1.0 - progress);
        }
        // Many open bins with low mean residual: avoid spreading thin.
        if open_bins_count > 4 && mean_residual < 25.0 {
            score += 10.0;
        }
    }

    // Mild tie-break toward filling fuller bins first.
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(80)) {
        score += 60.0;
    }
    // Gap too small for the lookahead item => likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward tight fits proportionally.
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new empty bin candidate gets penalized when many bins are open).
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if existing fits are terrible, new bin is attractive:
        if post_residual == bin_capacity - item_size && (bin_capacity - item_size) > 0 {
            score -= 10.0;
        }
    } else {
        // Mild penalty for spreading across too many bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins with residual close to the mean (balanced packing) slightly.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // Late-stream tightening: near the end, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin residual exactly absorbs next item too
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item fits in post residual: strong reward scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 300.0 - tight * 2.0;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize small unusable leftovers
        let waste = post_residual as f64;
        if waste < 10.0 {
            score += (10.0 - waste) * 20.0;
        }
    }

    // Penalize post_residual relative to mean residual (dead space vs fleet)
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let poor_fleet = (mean_residual - post_residual as f64).max(0.0);
        score += 400.0 - poor_fleet * 3.0 - crowd * 5.0;
        // Early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 100.0;
    }

    // Slight preference for tighter fits overall
    score -= (item_size as f64 / bin_capacity as f64) * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else {
        // Penalize large dead space quadratically
        score += 0.08 * (post_residual as f64).powi(2);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or when open bins are all congested.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let congestion = if mean_residual > 0.0 {
            (mean_residual / bin_capacity as f64).powf(2.0)
        } else {
            0.0
        };
        // Opening a new bin costs more as the stream progresses (fewer future
        // items to amortize the bin), but congestion of open bins favors it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let amortization = 1.0 - progress;
        score += 20.0 + 40.0 * amortization - 35.0 * congestion - 20.0 * fill_ratio;
        // If no open bin fits well, new bin becomes relatively attractive
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bins: reward those whose residual pairs well with the lookahead item
        if next_item_size > 0 {
            let pair_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 0.15 * pair_gap;
            // Perfect lookahead pairing bonus
            if post_residual == next_item_size {
                score -= 20.0;
            }
        }
        // Slightly prefer bins whose residual is below mean (compact them),
        // keeping high-residual bins available for big future items.
        let dev = post_residual as f64 - mean_residual;
        score += 0.10 * dev.max(0.0);
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing ones
    score -= (open_bins_count as f64).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize residual, weighted by a smooth polynomial in progress
    let mut score = pr * (0.9 + 0.4 * progress * progress);

    // Non-linear coupling: residual squared term, amplified late in the stream
    score += pr_norm * pr_norm * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 8.0 * (0.3 + progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Penalize scattering across many open bins when mean residual is high
    score += (open_bins_count as f64).ln() * mean_residual * 0.05 * (1.0 + progress);

    // New-bin candidate: mild bias toward keeping it attractive early, costly late
    if bin_residual == bin_capacity {
        score += 4.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it falls in.
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of capacity left

    // Integer-division thresholds: post_residual in quarters of capacity.
    let quarter = post_residual / (bin_capacity / 4);
    match quarter {
        0 => score -= 12.0,                       // near-perfect fill: reward heavily
        1 => score -= 5.0,                        // still a good chunk used
        2 => score += 3.0,                        // half bin left: mediocre
        _ => score += 8.0,                        // barely touched bin: penalize
    }

    // Modulo-10 class: small residues (dead space) are worthless if < typical min item.
    let dead = post_residual % 10;
    if dead > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    } else if dead <= 2 {
        score += dead as f64 * 0.5;
    }

    // Coupling with lookahead item: harmonic match via modulo classes.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits exactly-ish: reward when post_residual % next_item_size is small
            let m = post_residual % next_item_size;
            score -= (10 - m.min(10)) as f64 * 0.8;
            // class match: both in same decile band
            if (post_residual / 10) == (next_item_size / 10) {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; leftover must be usable for something
            score += 2.0 + frac * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: neutral baseline, slightly worse than good fits.
    if bin_residual == bin_capacity {
        score = cap * 0.55 - (open_bins_count as f64).min(10.0) * 0.5;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits: must open
        }
        // open a fresh bin early in the stream when mean residual is high (fragmented)
        if mean_residual > cap * 0.45 && open_bins_count > 2 {
            score -= 6.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 - progress * 3.0;

    // Prefer bins below mean residual (tighter bins fill first).
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold typical
    // future items (assume min item ~10, but unknown distribution -> guard low)
    let min_item = 1u32;
    let dead_threshold = (min_item + 8).max(6); // ~9: gaps below this are near-dead
    if post_residual < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, avoid creating new dead
    // space; when few are open, opening a new bin is less costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits the post_residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap unusable by next item -> penalize proportionally
        score += 8.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
    }

    // Mean-residual coupling: placing into a bin with residual far below mean
    // (already tight) is good; leaving gaps in loose bins wastes them.
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // New-bin candidate: empty bin has large post_residual; make it a
    // fallback only when the resulting placement would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual < dead_threshold {
            score -= 60.0; // new bin still avoids dead space better
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect match: next item exactly fills the bin afterwards.
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits: reward tightness of that follow-up fit.
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64)) * (nxt / (post_residual as f64));
        } else {
            // Next item won't fit in leftover: penalize proportionally to wasted space.
            score += 8.0 * gap / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Penalize small unusable dead space (fragmentation), scaled by stream position.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + 10.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if it enables a great future fit,
    // otherwise push it above typical open-bin scores.
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.5 * open_bins_count as f64 + 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 <= item_size as f64 {
            score = base - 10.0; // fresh bin can host next item too
        } else {
            score = base;
        }
    }

    // Mild preference for tighter existing fits among many options.
    score += 0.3 * (bin_residual - post_residual as u32) as f64 * 0.0
           + 0.15 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size <= bin_residual {
            // next item fits this bin now but not after: mild penalty for consuming space
            score += 3.0;
        }
        // Exact pairing bonus
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Compare against mean residual: prefer bins with below-mean residual (tighter bins)
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // Discourage spreading across many open bins when few items remain
    if progress > 0.9 && bin_residual == bin_capacity {
        score += 15.0; // avoid opening new bins late
    }

    // Mild penalty for opening a new bin early when plenty of open bins exist
    if bin_residual == bin_capacity {
        score += 2.0 + 0.02 * open_bins_count as f64 * (1.0 - progress);
    }

    // Slight preference for filling larger-residual bins when item is large
    if item_size > bin_capacity / 2 {
        score -= 0.03 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: post residual, mildly discounted early, weighted more late
    let mut score = pr * (0.8 + 0.4 * progress);

    // Non-linear penalty on dead space: small residuals are hard to fill
    let dead = (1.0 - pr_norm).powi(3) - 1.0;
    score += 20.0 * dead * (0.5 + progress);

    // Reward tight fits (quadratic coupling of fit ratio and residual)
    score -= 15.0 * fit * fit * (1.0 - pr_norm);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 12.0 * (1.0 - (ns / cap)) * (1.0 - pr_norm);
        } else {
            score += 8.0 * ((ns - pr) / cap);
        }
    }

    // Mean residual coupling: prefer bins near the mean (keeps residuals uniform)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // Many open bins: slight preference for filling existing ones
    score += 2.0 * (open_bins_count as f64).sqrt() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space
    let pr = post_residual;
    let pr_mod = (pr % 10) as f64;
    let pr_div = (pr / 10) as f64;

    // Reward small post_residual (tight fits), scaled by fullness class
    let fullness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * fullness * fullness;

    // Harmonic dead-space penalty: leftover in 1..9 is awkward
    if pr > 0 && pr < 10 {
        score += 14.0 - pr as f64; // small dead space is worse than none
    }
    // Leftover in 10..19 only good if a small item could use it
    if pr >= 10 && pr < 20 && next_item_size > 0 && next_item_size <= pr {
        score -= 8.0;
    } else if pr >= 10 && pr < 20 {
        score += 4.0;
    }

    // Modulo coupling: does post_residual pair with next item size?
    if next_item_size > 0 {
        let gap = pr as i64 - next_item_size as i64;
        if gap >= 0 && gap < 10 {
            score -= 10.0 - gap as f64; // next item fits almost exactly
        } else if gap < 0 {
            score += (gap.abs() as f64).min(12.0); // next item cannot follow
        }
        // harmonic residue match: pr and next size share a coarse class
        if (pr / 10) == (next_item_size / 10) && pr >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        score = cap - 4.0 * pressure;
        if pr >= 20 && next_item_size > 0 && next_item_size <= 20 {
            score += 6.0; // new bin fine if old bins hold small items
        }
        if fitting_bins_count <= 1 {
            score -= 15.0; // nothing else fits: open new bin
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fullness;

    // Mild preference for bins below mean residual (balance spreading)
    score += 0.05 * (post_residual as f64 - mean_residual);

    // pr_div-based class tilt: prefer leaving multiples of 10
    score += 0.8 * pr_mod;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny (unusable for the
    // typical item range 10..80) are heavily penalized; zero residual is perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // 59..1 penalty, worst at residual=1
    }

    // Reward near-perfect fits superlinearly.
    if post_residual <= 5 {
        score -= 25.0 * (1.0 - post_residual as f64 / 5.0);
    }

    // Reward filling the majority of the bin's used space.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; opening a new bin is penalized
    // proportionally to how many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But if this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 15.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post-residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here: penalize leaving a mid-range gap
            // that neither closes the bin nor hosts the next item.
            if post_residual >= 10 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., closer to being full) when the mean is high.
    if mean_residual > 0.0 {
        score += 0.25 * (mean_residual - post_residual as f64);
    }

    // Mild progression term: late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a quadratic penalty
    // on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        let ad = diff.unsigned_abs() as f64;
        // Perfect match: post_residual == next_item_size -> strong reward.
        if diff == 0 {
            score -= 60.0;
        } else {
            // Penalize mismatch, but asymmetrically: leaving slightly more than
            // the next item is fine (it still fits), leaving less wastes the bin.
            if diff > 0 {
                score += 0.3 * ad; // next item still fits
            } else {
                score += 0.8 * ad; // next item won't fit here
            }
            // Soft reward for near-matches.
            score -= 25.0 * (-ad / 12.0).exp();
        }
    }

    // Compare post_residual against mean residual: leaving below-average residual
    // concentrates slack, which is good; above-average residual spreads slack badly.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the current
    // fit is terrible or the next item matches the fresh residual perfectly.
    if bin_residual == bin_capacity {
        // Fresh bin residual after placement = capacity - item_size.
        let fresh = post_residual as f64;
        // Reward if the fresh bin's residual exactly fits the next item.
        if next_item_size > 0 && (fresh - next_item_size as f64).abs() < 1.0 {
            score -= 30.0;
        }
        // Discourage new bins when decent fits exist elsewhere.
        if fitting_bins_count > 1 {
            score += 55.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Slight preference to keep few open bins (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small for any plausible item (1..=100).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 80.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasting this bin's space
            score += 15.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Prefer fuller bins relative to the fleet average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild penalty for opening new bins when many are already open and slack exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let slack = mean_residual - item_size as f64;
        score += 40.0 + 30.0 * (open_bins_count as f64).ln().max(0.0) + 25.0 * slack.max(0.0) / bin_capacity as f64 - 20.0 * progress;
    }

    // Prefer bins with residual close to item size (tight fit) over huge residuals.
    score += 0.3 * ((bin_residual - item_size) as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * (1.0 - norm_pr) * (1.0 - progress);
    let poly = 4.0 * coupling * cap;

    // Penalize waste scaled by remaining stream length
    let waste_penalty = (1.0 - progress) * (pr * pr) / cap;

    // Last-chance bonus: strongly favor the only fitting bin
    let mut score = base + poly + waste_penalty;
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer tight fits: reward small post_residual relative to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for filling bins when many are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Align with mean residual: penalize outliers above mean
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: only attractive when residuals are large
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - norm_pr) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "reusable"
    // classes (multiples of common item sizes) are more valuable to preserve.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity used by this placement
    let fill_frac = (bin_residual - post_residual) as f64 / cap;
    score -= 60.0 * fill_frac;

    // Modulo-10 harmonic class: residuals divisible by 10 align with typical
    // item sizes -> reward them; odd/prime-ish residuals are dead space.
    let class = post_residual % 10;
    if class == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 3.0;
    } else {
        score += 4.0 + 0.5 * class as f64;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 6.0 * (1.0 - rem2 as f64 / cap);
            if rem2 % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot follow here; penalize small unusable leftovers
            if post_residual < 10 {
                score += 12.0;
            }
            score += 3.0;
        }
    }

    // Integer-division thresholds on post_residual: classify leftover size
    let tier = post_residual / 20; // 0..5
    score -= match tier {
        0 => 10.0, // tiny leftover = near-perfect fit
        1 => 4.0,
        2 => 0.0,
        3 => -3.0,
        _ => -6.0, // large leftover still flexible
    };

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when the current
    // bin would leave badly fragmented space, or when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post).abs();
        // base penalty so fresh bins lose to decent fits
        score += 45.0;
        // but if placing here would waste > half the residual space, new bin wins
        if post_residual < item_size / 2 {
            score -= 70.0;
        }
        // crowded state: many bins, low mean residual -> prefer consolidation
        if open_bins_count > 3 && mean_residual < 35.0 {
            score -= 20.0;
        }
        let _ = fragmentation;
        let _ = progress;
    }

    // Waste penalty: leftover smaller than the minimum item size is dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild bonus for bins already below mean residual (balancing residuals)
    if (post as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps that nothing can use are heavily penalized.
    let min_item = 1u32;
    let usable_threshold = if next_item_size > 0 { next_item_size } else { min_item };
    if post_residual < usable_threshold && post_residual > 0 {
        // Unusable sliver: penalize proportionally to how "wasted" it is.
        score += 40.0 + 0.5 * (usable_threshold - post_residual) as f64;
    }
    // Absolute tiny gaps are dead space regardless of lookahead.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit bonus: reward tight packing.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead synergy: reward if next item fits exactly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - tightness / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: this gap is likely dead space for the near future.
        score += 8.0;
    }

    // Open-bins pressure: prefer placing into existing bins when many are open,
    // to avoid bin proliferation.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: a fresh empty bin has post_residual = C - item.
    // Make it attractive only when the item is large (little waste potential) or
    // when no good fits exist. Penalize opening new bins slightly by default.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items leave little residual -> new bin is fine; small items -> wasteful.
        score += 10.0 * (1.0 - fill_ratio);
        // If many bins already fit the item, opening a new one is clearly worse.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference for filling the emptiest bins to consolidate residuals.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can follow here. Reward tightness of the two-item chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 - chain_waste.min(50.0);
        } else {
            // Bad: dead space that next item cannot use
            let dead = (post_residual as f64) - (next_item_size as f64).min(post_residual as f64);
            score += dead * 0.5 + 20.0;
        }
    }

    // Relative to mean residual: prefer filling bins with above-average residual
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins early in the stream / when few bins open
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * -5.0;
    }

    // Progression: later in stream, be more aggressive about tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tighter fits (small post_residual) matter more.
    let tight = (pr / cap).powf(2.0 + 3.0 * progress);
    score += 40.0 * tight * (0.5 + progress);

    // Reward filling bins almost exactly, more strongly as stream progresses.
    let fill = 1.0 - pr / cap;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Penalize large dead space relative to mean residual of open bins.
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / cap;
        score += 15.0 * dev * dev * dev.abs();
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits into post_residual (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 20.0 * snug * snug * (1.0 + progress);
        } else {
            score += 10.0 * (1.0 - pr / nxt);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (pr / cap);

    // Slight preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (integer division thresholds) ---
    // Class 0: perfect fit (post_residual == 0) -> strongest reward.
    // Class 1: tiny dead space (1..=5) -> strongly penalized, hard to fill.
    // Class 2: medium gap (6..=20) -> mild penalty.
    // Class 3: large gap (>20) -> still reusable, mild reward.
    let cls = if post_residual == 0 { 0 }
              else if post_residual <= 5 { 1 }
              else if post_residual <= 20 { 2 }
              else { 3 };

    match cls {
        0 => score -= 60.0,
        1 => score += 25.0 + (5 - post_residual) as f64 * 3.0,
        2 => score += 6.0,
        _ => score -= 4.0,
    }

    // --- Modulo-arithmetic compatibility: does the next item exactly fill the gap? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Next item seals this bin perfectly: huge reward.
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Next item leaves a new gap; penalize by how awkward the new gap is.
            let new_gap = post_residual - next_item_size;
            if new_gap <= 5 {
                score += 10.0 + new_gap as f64 * 2.0;
            } else if new_gap <= 20 {
                score += 3.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this gap at all: dead space locked in.
            score += 8.0;
        }
    }

    // --- Harmonic capacity fractions: prefer bins whose residual is a "nice" fraction ---
    // (quarter / half / three-quarter boundaries of capacity are easier to combine with)
    let frac = (bin_residual * 4) / bin_capacity; // 0..4 integer division
    match frac {
        0 => score -= 5.0,  // nearly empty
        1 => score += 2.0,  // ~quarter full residual
        2 => score -= 1.0,  // ~half
        3 => score += 3.0,  // ~three-quarters residual, tight
        _ => score -= 3.0,  // full bin residual
    }

    // --- Last-chance bin: avoid opening a new bin when this is the only fitting one ---
    if fitting_bins_count == 1 && post_residual + item_size <= bin_capacity {
        score -= 20.0;
    }

    // --- Prefer filling bins that are already small-residual relative to fleet mean ---
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // --- Late in the stream, consolidate aggressively into few bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 5.0 * progress;
    }

    // --- Slight penalty for spreading across too many open bins ---
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold any item
    // (min item size 1, but small gaps below a practical threshold) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Pressure from many open bins: discourage spreading across bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 45.0; // next item fits snugly -> great placement
        } else {
            score -= 10.0;
        }
    }
    // Penalize if next item cannot fit in the leftover but could fit a fresh bin.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // and mean residual is large (existing bins are fragmented).
        score = 70.0 + 3.0 * open_bins_count as f64 - 0.3 * mean_residual;
        // Late in the stream, keep consolidating instead of opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If next item is huge, a fresh bin may be valuable.
        if next_item_size > 60 {
            score -= 30.0;
        }
    }

    // Mild adjustment by mean residual: bins deviating far from the mean
    // (outliers in fragmentation) are slightly penalized.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // 2-step lookahead: perfect next-item match on post_residual is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; dead-space penalty grows with leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * gap / bin_capacity as f64 * 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residuals near/below mean (avoid
    // spreading waste across many half-empty bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin early in the stream when open bins could absorb the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - progress);
        // New bin is acceptable if the current bin would leave a big awkward gap.
        if post_residual > 0 && post_residual < 10 {
            score -= 18.0;
        }
    }

    // Slight preference to fill bins that are already mostly used.
    score += (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that leave little dead space.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only option.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize bins whose post-residual cannot host the next item,
    // reward bins that can host it snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 10.0;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing
    // bins); late in the stream, packing quality matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0;

    // Global state coupling: if mean residual is high, bins are loose — prefer
    // consolidating into tight residual bins; if mean residual is low, opening
    // a fresh bin is less costly.
    let residual_gap = (bin_residual as f64 - mean_residual);
    score += 0.15 * residual_gap;

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else or open bins are numerous and fragmented.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) > 0.5 * (bin_capacity as f64);
        if poor_fit_elsewhere {
            score -= 18.0;
        } else {
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Fragmentation penalty: large post-residuals that are unusable (below the
    // typical minimum item size) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = pr as f64;

    // Quadratic penalty on dead space: residuals that are too small to fit
    // typical items (norm_pr small) are wasteful; smooth quadratic coupling.
    score += 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Smooth interaction: as the stream progresses, tighter packing matters
    // more; penalize large residuals less early, more late.
    let coupling = progress * norm_pr * (norm_pr - 1.0);
    score += 30.0 * coupling;

    // Lookahead: reward leaving room for the next item (smooth Gaussian-like).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / cap;
        score -= 25.0 * (-diff * diff * 40.0).exp();
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer filling existing ones (mild smooth pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean residual alignment: prefer bins near the mean (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize mildly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "usable bands" via integer division thresholds on capacity fractions.
    let post = post_residual;
    let class = post / 10; // 0..=10 harmonic band
    // Dead-space penalty: leftover in (0,10) is nearly unusable for items >=10.
    if post > 0 && post < 10 {
        score += 25.0;
    }
    // Reward leftovers that are "perfect slots" for common small classes.
    match class {
        0 => score -= 8.0,           // exact fill
        1 => score -= 6.0,           // 10..19: fits small items
        2 => score -= 5.0,
        3 => score -= 3.0,
        4 => score -= 1.0,
        5 => score += 0.5,           // half-full: mediocre
        6 => score += 1.5,
        7 => score += 2.5,
        8 => score += 3.5,
        9 => score += 4.5,
        _ => score += 6.0,           // nearly empty bin used
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 20.0; // perfect chain
        } else if post >= next_item_size {
            let slack = post - next_item_size;
            if slack < 10 { score -= 10.0; } else { score -= 3.0; }
        } else {
            // next item cannot use leftover: mod-based dead class
            let gap = next_item_size - post;
            score += (gap as f64) * 0.15;
            if gap < 10 { score += 8.0; }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by how many bins already fit.
        if fitting_bins_count > 0 {
            score += 40.0 + 5.0 * (fitting_bins_count as f64);
        } else {
            score += 5.0; // forced open, mild base
        }
        // Early in stream, keep bins open to build tight packing later.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild preference to fill high-occupancy bins first (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Medium gaps: moderate penalty scaled by gap smallness.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Coupling with lookahead: if the next item fits exactly into the post residual,
    // reward this bin strongly (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 40.0;
        if slack < 10 {
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual cannot host next item: penalize more if gap is tiny.
        score += 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open bins pressure: when many bins are open, discourage spreading to new bins
    // and favor consolidation into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it, more so with higher open-bin pressure.
        score += 25.0 + 10.0 * pressure;
        // But if current bin would leave a bad small gap and new bin keeps
        // large residual for the future, soften the penalty.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward slightly as open-bin pressure grows (consolidation).
        score -= 2.0 * pressure;
        // Prefer bins tighter than the mean residual (better fits).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item exactly fills the residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: next item seals this bin
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // tighter chain is better; discount by slack
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to wasted gap
            let gap = next_item_size - post_residual;
            score += 8.0 * (gap as f64 / 100.0);
        }
    }

    // Penalize residual far above the mean residual of open bins (dead space outlier)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer placing into tight bins (small residual) - already implicit, but amplify
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight penalty for opening a new bin when other bins fit, scaled by stream progress
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fits_elsewhere = fitting_bins_count > 0;
        if fits_elsewhere {
            score += 30.0 + 20.0 * (1.0 - progress);
        } else {
            score -= 10.0; // no alternative, new bin is fine
        }
    }

    // Reward very tight fits of the current item
    if post_residual <= 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // Penalize bins whose residual becomes a "dead zone" that can't fit
    // the lookahead item or typical small items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Bonus if the lookahead item fits perfectly in the resulting residual.
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with larger residuals among fitting bins (best-fit tiebreak
    // inverted: leave small residuals for small future items is handled by
    // post_residual term; here discourage wasting a big residual on a small item).
    let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += waste * 15.0;

    // Global state coupling: when many bins are open, encourage consolidation
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    score -= open_pressure * 3.0 * (0.5 + progress);

    // Mean residual coupling: if this bin's residual deviates favorably from
    // the mean (larger than mean), placing here evens out residuals.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.25;

    // New-bin candidate handling: a fresh empty bin should only win when
    // nothing fits well. Make it attractive only late or when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0; // item always fits empty bin
        let _ = poor_fit;
        score = (bin_capacity - item_size) as f64 * 0.6
            + 30.0
            - progress * 20.0
            - if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 8.0 } else { 0.0 };
        // If any other bin fits, discourage new bin moderately.
        if fitting_bins_count > 1 {
            score += 18.0;
        }
    }

    // Small bonus for exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nx = next_item_size as f64;

    // Base: reward tight fits via convex penalty on post_residual (quadratic + cubic coupling)
    let mut score = pr + 0.012 * pr * pr / cap;

    // Smooth non-linear interaction: post_residual vs stream progress (later items -> punish waste more)
    let t = progress;
    score += 0.9 * pr * (t * t) / cap;

    // Reward filling bins well: subtract term coupled with item_size fraction and progress
    score -= 0.55 * (it / cap) * (1.0 + t);

    // Lookahead coupling: if next item fits into post_residual, reward this bin smoothly
    if nx > 0.0 {
        let fits = (pr - nx).max(0.0) / cap;
        score -= 2.2 * (1.0 - fits).min(1.0) * (0.5 + 0.5 * t);
        // penalize leaving exactly awkward gap for next item
        let gap = (pr - nx).abs();
        score += 0.4 * (gap / cap) * (gap / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * t;
    }

    // Mean-residual deviation: prefer bins near mean to preserve flexibility (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 0.35 * dev * dev;

    // Many open bins: slightly prefer using existing ones over opening new
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it unattractive unless current bin would be badly wasted
    if bin_residual == bin_capacity {
        let waste = pr / cap;
        score += 2.5 + 4.0 * t - 3.0 * waste * waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "clean"
    // (more likely to be exactly filled by future items).
    let clean = post_residual % 10 == 0;
    if clean {
        score -= 6.0;
    }
    // Penalize awkward residual classes (odd or non-multiples of 5).
    if post_residual % 5 != 0 {
        score += 4.0;
    }
    // Integer division thresholds: small leftovers are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Harmonic coupling: next item also lands on a clean class
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; residual becomes pure waste.
        score += (post_residual as f64) * 0.3;
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64 * 0.5;
        if tight && open_bins_count > 0 {
            score -= 8.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Prefer tighter existing bins: deviation from mean residual.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Slight preference for bins with less residual overall (best-fit bias).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps below the minimum item size are worthless.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: strong penalty proportional to how wasted the gap is.
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: big reward.
        score -= 80.0;
    }

    // Reward fits that leave room for the lookahead item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Lookahead won't fit in the leftover: mild penalty scaled by gap size.
            score += 8.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new/partial bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / (total_items.max(1) as f64)).max(1.0);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Brand-new empty bin candidate: only attractive when current bin would leave a big
    // unusable gap or when open bins are already tight/numerous.
    if bin_residual == bin_capacity {
        let would_waste = post_residual > 0 && post_residual < 10;
        if would_waste {
            score -= 30.0; // prefer fresh bin over creating a dead gap
        } else {
            score += 25.0 + 0.5 * open_bins_count as f64; // discourage needless new bins
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight nudge toward bins whose residual is close to the mean (keeps bin profile uniform).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item => strong reward.
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 40.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // Next item fits afterwards; reward proportionally to tightness.
            let tight = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 12.0 * tight;
        } else {
            // Next item will NOT fit in residual: penalize wasted lookahead space.
            score += 6.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose post-residual stays near the fleet mean (balanced packing),
    // penalize creating much larger residuals than average (hoarding) and
    // much smaller ones (fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // --- Last-chance bonus: only fitting bin => use it or lose it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // --- Dead-space penalty: small unusable residuals (below min item size) ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in the stream or when
        // current item is large (poor fit anywhere) or no open bins exist.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        let openness = open_bins_count as f64;
        score += 20.0 + 15.0 * progress + 10.0 * openness - 25.0 * large_item;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            // New bin leaves room for the big next item: make it attractive.
            score -= 30.0;
        }
    } else {
        // Slight preference for tighter existing bins (smaller residual before).
        score += 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // bin stays usable for the lookahead item
        } else if post_residual > 0 {
            // Dead space smaller than next item: penalize proportionally.
            score += 0.35 * (post_residual as f64) * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer filling existing ones over opening more.
    let pressure = (open_bins_count as f64) / (1.0 + step_index as f64);
    if bin_residual < bin_capacity {
        score -= 4.0 * pressure.min(3.0);
    }

    // Compare residual against global mean residual: bins below mean are
    // "emptier" — using them is fine; bins above mean are nearly full,
    // using them wastes little future capacity.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 3.0 * dev; // prefer fuller bins (higher residual than mean)
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If this is the last item, opening a bin is cheap (no future waste).
        if step_index + 1 >= total_items {
            score -= 30.0;
        }
        // If the next item is large and this item nearly fills a bin alone,
        // a fresh bin is attractive.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
        // When few bins fit the item elsewhere, new bin is more acceptable.
        score -= 6.0 * (fitting_bins_count as f64).recip().min(1.0);
    }

    // Mild time-horizon modulation: early in the stream, be more willing
    // to open bins (future is long); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress; // late stream: penalize new bins more
    } else {
        score -= 3.0 * progress;  // late stream: prefer existing bins even more
    }

    // Small tie-breaker: prefer bins with residual close to item size.
    score += 0.01 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = norm_pr;

    // Non-linear polynomial coupling of post-residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (0.35 - 0.25 * progress) * norm_pr * norm_pr;
    score += (0.15 * p2 - 0.1 * p3) * norm_pr * norm_pr * norm_pr;

    // Penalize residual that cannot fit the next item (lookahead)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr) / cap;
            score += (0.4 + 0.3 * progress) * gap;
        } else {
            let slack = (pr - ni) / cap;
            score -= 0.15 * slack * (1.0 - slack);
        }
    } else {
        // Last item: reward filling bins as tightly as possible
        score -= 0.5 * (1.0 - norm_pr);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 0.8;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: avoid placing into bins far from mean state
    let dev = (mean_residual - pr) / cap;
    score += 0.08 * dev * dev;

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 0.25 + 0.5 * progress + 0.2 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by integer division.
    // Classes: 0 (perfect fit), small (1..=10), medium (11..=30), large (>30).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, strongly favored
    } else if pr <= 10 {
        score -= 45.0; // near-perfect: dead space almost unusable anyway
    } else if pr <= 30 {
        score -= 12.0; // usable for small items
    } else {
        // large residual: quantify its usability for the known next item
        if next_item_size > 0 && next_item_size <= pr {
            score -= 18.0; // can host the lookahead item
        } else if next_item_size > 0 {
            score += 8.0; // lookahead won't fit here; dead-space risk
        }
    }

    // Fractional coupling: how well the item fills this bin relative to capacity.
    let fill_ratio = item_size as f64 / cap;
    let res_ratio = post_residual as f64 / cap;
    score -= 25.0 * fill_ratio * (1.0 - res_ratio); // reward dense packing

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large and current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count > 0 {
            mean_residual / cap
        } else {
            1.0
        };
        // If open bins are mostly empty (high mean residual), strongly discourage new bin.
        score += 40.0 * crowd;
        // Large items near stream start or with no fitting bins justify a new bin.
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mean-residual harmonization: prefer bins whose residual is close to the mean
    // (balanced depletion) but avoid dumping into already-degraded bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Lookahead modulo coupling: if next item divides cleanly into post_residual class
    // (post_residual % next_item_size small), this bin chains well.
    if next_item_size > 0 && pr > 0 {
        let m = pr % next_item_size;
        if next_item_size <= pr {
            score -= 10.0 * (1.0 - m as f64 / next_item_size as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0; // small gap, only usable by tiny items
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual tightly matches the item (tight fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual - next_item_size < 10 {
            score -= 10.0; // perfect chain finish
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0; // next item can't use leftover -> dead space likely
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate logic: an empty bin is only attractive when no open bin
    // offers a decent fit (post_residual large waste) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        let poor_alternatives = post_residual as f64 / bin_capacity as f64;
        let _ = poor_alternatives;
        // Penalize new bin when current best open bins are actually tight.
        // We approximate: if mean_residual is small, open bins are nearly full,
        // so a new bin is reasonable -> discount its score.
        score = waste * (0.55 + 0.35 * (1.0 - progress));
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative at all
        }
        if waste < 20.0 {
            score -= 50.0; // item nearly fills a fresh bin anyway
        }
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fills post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect 2-step match
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how much it fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill * fill;
        } else {
            // next item won't fit here: penalize leftover dead space,
            // worse if the leftover is small (unusable).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 30.0; // tiny unusable sliver
            } else if dead > next_item_size as f64 {
                score += 10.0 * (1.0 - dead / (bin_capacity as f64));
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins that are
    // already more filled than average (avoid spreading across bins).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            score += 15.0 * (1.0 - rel); // bin is emptier than average -> penalize
        } else {
            score -= 8.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if next item is large and current post_residual is tiny, new bin is fine
        if next_item_size > 0 && post_residual < 10 && next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Late in the stream: be more conservative, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted residual, weighted by tightness of fit.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += (1.0 - fit_ratio) * 20.0;

    // Reward near-perfect fills strongly.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item nests.
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 40.0 * nest;
        } else {
            // Next item cannot use leftover: penalize large dead space creation.
            let dead = post_residual as f64;
            let next_too_big = (next_item_size - post_residual) as f64;
            score += 0.3 * dead + 0.1 * next_too_big;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
        // Extra reward if the residual after placement still accommodates the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Global pressure: many open bins with low mean residual -> avoid fragmenting;
    // prefer bins whose residual is close to the mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.4 * dev;

    if open_bins_count > 4 && mean_residual < 25.0 {
        // Fragmented state: discourage placements leaving awkward small residuals.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // Time horizon: late in the stream, avoid opening/keeping barely-used bins;
    // early on, be more tolerant to build complementary bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let late = progress > 0.6;
    if late {
        // Late: prefer tight fits even more, penalize large residuals left.
        score += 0.25 * post_residual as f64;
        if post_residual == 0 {
            score -= 40.0;
        }
    } else {
        // Early: slight bonus for leaving residuals that match common item sizes.
        let r = post_residual;
        if r >= 10 && r <= 40 {
            score -= 8.0;
        }
    }

    // New-bin candidate logic: empty bin should only win when no open bin fits
    // well (this call has bin_residual == bin_capacity and item fits).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by state.
        let mut new_bin_cost = 70.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            new_bin_cost = 5.0; // no alternative, must open
        }
        // Late in stream, opening new bins is cheap since leftovers get stranded anyway.
        new_bin_cost -= 30.0 * progress;
        // If next item is huge and residual here would be small, opening is fine.
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            new_bin_cost -= 20.0;
        }
        score = new_bin_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth coupling: residual quality interacts with stream progress.
    // Early on, prefer tight fits less strongly; late, pack tightly.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Dead-space penalty: very small post-residuals are wasted capacity.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.4;
    }

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-diff * diff / 300.0);
    }

    // Prefer filling bins with smaller mean residual (older/partially full bins).
    score += 0.15 * (mean_residual - pr);

    // Slight pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item granularities) are favored.
    let post = post_residual;
    let class_bonus: f64 = if post == 0 {
        -60.0 // perfect fit: best possible outcome
    } else if post % 10 == 0 {
        -18.0
    } else if post % 5 == 0 {
        -9.0
    } else if post % 4 == 0 {
        -5.0
    } else if post % 3 == 0 {
        -2.0
    } else {
        8.0 // prime-ish leftover: likely dead space
    };
    score += class_bonus;

    // Small-but-nonzero leftovers are the worst (unusable dead space).
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 2.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it cannot fit in post but could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 55.0;
        } else if next_item_size <= post {
            score -= (post - next_item_size) as f64 * 0.4;
        } else {
            // next item won't fit here regardless of choice; slight normalization
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post < bin_capacity {
        score -= 22.0;
    }

    // Prefer filling bins that are already relatively full (low residual),
    // best-fit flavored: reward closeness of item to residual.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 25.0;

    // When many bins are open, consolidate; when few, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Compare against mean residual: choosing a bin far below mean residual
    // (i.e. fuller than average) is good.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate handling: an empty bin gets a baseline that is beaten
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.3;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0; // big item coming: fresh capacity is valuable
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // few alternatives: new bin is attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable gaps (dead space that few future items can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new space.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use leftover; penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (consolidating fullness) when many bins are open.
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0);
    }

    // New-bin candidate: only attractive when open bins are nearly exhausted
    // or current residual is a poor fit for the item.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let scarcity = (open_bins_count as f64) / (1.0 + fitting_bins_count as f64);
        score = 70.0 + poor_fit * 0.1 - 20.0 * scarcity;
        if fitting_bins_count == 0 {
            score = -100.0; // no open bin fits: must open new bin
        }
    }

    // Slight late-stream conservatism: tighten packing as stream progresses.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base pressure: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if nr <= pr {
            // next item fits perfectly -> huge reward
            let match_quality = 1.0 - ((pr - nr) / pr);
            score -= 25.0 * match_quality * match_quality;
        } else {
            // next item cannot use leftover -> penalize wasted space
            score += 8.0 * ((nr - pr) / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual of open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 - mean_residual;
        score += rel * 0.15;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + 10.0 * open_pressure * (1.0 - 0.3 * progress);
    }

    // Slight preference for balancing residual spread across bins
    score -= (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space relative to capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // Perfect or near-perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // penalize leaving dead space the next item cannot use
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer open bins generally, but allow
    // opening when existing residuals are large and fragmented
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 18.0;
        if open_bins_count > 0 {
            // discourage new bin if mean residual is small (good packing so far)
            score += 0.6 * mean_residual;
            // encourage new bin late in the stream when open bins are crowded
            let progress = step_index as f64 / total_items.max(1) as f64;
            if mean_residual > 30.0 && post_residual as f64 > 55.0 {
                score -= 10.0 * progress;
            }
        }
    } else {
        // mild preference for emptier open bins early, tighter bins late
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    }

    // Reward consolidating many open bins
    score -= 0.3 * open_bins_count as f64 * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Perfect fit: strongly reward closing a bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Non-linear waste penalty: small residuals are disproportionately bad.
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // 0..1
    score += 12.0 * (1.0 - norm_pr).powi(3) * norm_pr.powi(2) * 10.0;

    // Lookahead coupling: reward if next item fits into the post residual.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            // Smooth reward peaking when next item nearly fills the remainder.
            let tightness = 1.0 - (gap / cap);
            score -= 30.0 * tightness * tightness;
        } else {
            // Dead space relative to the next item: penalize smoothly.
            score += 0.25 * (-gap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for tighter bins among many candidates.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Stream-progress coupling: later in the stream, prefer filling existing
    // bins more aggressively (open bins become costly to leave behind).
    let late_bonus = 20.0 * progress * progress;
    score -= late_bonus * (1.0 - norm_pr);

    // Penalize bins whose residual deviates strongly from the mean residual
    // (smooth quadratic coupling), keeping a balanced pool of open bins.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // New-bin candidate: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        score = cap + 60.0 - 40.0 * progress;
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= cap {
            // Opening a fresh bin lets a large pair pack together.
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strongly penalize unless the current fit is poor
    // (large post_residual) or this is the only fitting bin.
    if bin_residual == bin_capacity {
        let tight_fit_bonus = if post_residual <= 10 { 60.0 } else { 0.0 };
        let last_chance = if fitting_bins_count == 1 { 80.0 } else { 0.0 };
        score -= tight_fit_bonus + last_chance;
        // Base cost of opening a new bin
        score += 40.0;
        return score;
    }

    // Harmonic class of post_residual: bins whose residual falls into
    // "small prime-sized" classes are nearly dead space; penalize them.
    let pr = post_residual;
    let class_mod = pr % 30;
    if pr > 0 {
        if class_mod < 5 {
            score += 25.0; // tiny unusable sliver
        } else if class_mod < 10 {
            score += 12.0;
        } else if class_mod < 20 {
            score -= 6.0; // mid-range, still usable
        } else {
            score -= 10.0; // large residual, flexible bin
        }
    }

    // Reward near-perfect fits using integer division thresholds.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item can exactly fill the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 20.0;
            } else {
                // harmonic class of the leftover gap
                score -= match gap % 25 {
                    0..=5 => 8.0,
                    6..=15 => 4.0,
                    _ => 0.0,
                };
            }
        } else {
            // next item cannot fit here; slight penalty for wasting the fit
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Stream progression: early on, prefer tighter packing; later, tolerate
    // spreading across bins since remaining items are fewer.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.3;

    // Penalize bins that are outliers vs mean residual (fragmentation).
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Mild penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (1..100)
    // can use are pure waste. Penalize tiny unusable gaps super-linearly.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // gap smaller than any item: total dead space
        } else {
            // Penalize residuals that few item sizes can still use.
            let usable = (post_residual as f64).ln().max(1.0);
            score += (100.0 - post_residual as f64) * 0.5 / usable;
        }
    }

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let next_gap = post_residual - next_item_size;
            if next_gap < 10 {
                score += 25.0; // would create a fresh dead gap
            } else {
                score -= 15.0;
            }
        } else {
            score += 10.0; // next item won't fit here at all
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; make new bins less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open or
        // mean residual across bins is very low (all bins nearly full).
        score += 40.0 + pressure;
        if mean_residual < 10.0 && fitting_bins_count > 0 {
            score -= 30.0; // existing bins are nearly full; new bin OK
        }
    } else {
        // Reward using existing bins, more so under pressure.
        score -= pressure * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mild preference for bins whose residual is above the mean
    // (keeps tighter bins free for smaller items).
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if post_residual exactly matches the next item,
    // this bin becomes perfectly reusable -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // residual can still host next item: mild reward proportional to fit quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // residual too small for next item: penalize dead space,
            // worse the closer it is to (but below) next_item_size
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (1.0 - gap / 80.0);
        }
    }

    // Compare residual against mean residual across open bins:
    // leaving residual near the mean keeps flexibility.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins would be badly fragmented
    // (large post_residual waste) or when the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = post_residual as f64;
        score = 60.0 + waste * 0.5 - 15.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize large wasted residuals (dead space) super-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.08;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive if any open bin fits.
        if fitting_bins_count > 0 {
            score += 55.0 + 3.0 * open_bins_count as f64;
        }
        // Early in the stream, opening bins is cheaper (build capacity for future items).
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 25.0 * (1.0 - progress);
        // If next item is large and current bin residual is small, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward using bins whose residual is below mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Lookahead: if post-residual cannot fit next item but another bin might,
        // slightly penalize leaving awkward gaps.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0;
        } else if next_item_size > 0 {
            score -= 5.0;
        }
    }

    // Mild pressure to reduce open-bin count late in the stream.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    // As stream progresses, dead space becomes more costly -> amplify larger residuals
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) + norm_pr * t * t * 0.5;
    score += poly * cap * 0.35;

    // Smooth penalty for residual mismatch with mean residual across open bins
    let diff = pr - mean_residual;
    score += 0.08 * diff * diff / cap;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * t;
    }

    // Lookahead coupling: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = (pr - nxt).abs();
        score += 0.06 * compat * (1.0 - t * 0.5);
        // Perfect lookahead fit reward (smooth, non-piecewise)
        let fit_quality = 1.0 - compat / cap;
        score -= 6.0 * fit_quality.max(0.0) * fit_quality.max(0.0);
    }

    // Mild penalty for spreading across many open bins early (encourage consolidation)
    score += 0.02 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate: opening a fresh bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * t + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Harmonic classes: post_residual buckets via integer division thresholds.
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score -= 40.0,                 // 1..9 dead space: nearly perfect
        1 => score -= 10.0,                 // 10..19: still usable by small items
        2 | 3 => score += 5.0,              // 20..39: mediocre
        4 | 5 => score += 20.0,             // 40..59: half-empty, risky
        6 | 7 => score += 45.0,             // 60..79: large dead space
        _ => score += 70.0,                 // 80..99: terrible unless new bin
    }

    // New-bin candidate handling: an empty bin has huge residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well,
        // or if the post-fit residual here pairs perfectly with the next item.
        let pressure = if fitting_bins_count == 0 { -80.0 } else { 60.0 };
        score += pressure;
        // Harmonic check: does post_residual (== capacity - item) land in a
        // "good" class for the next item?
        if next_item_size > 0 {
            if next_item_size <= post_residual && post_residual % 10 < 2 {
                score -= 90.0; // next item can finish this bin almost exactly
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Lookahead coupling: penalize placements that leave residual the next
    // item can't use well; reward residuals that the next item fills.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 200.0; // perfect chain: this item then next item fill bin
        } else if leftover <= 10 {
            score -= 60.0;
        } else {
            score += (leftover as f64) * 0.4;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space the (larger) next item cannot use.
        score += 15.0;
    }

    // Stream progression: later in the stream, be more conservative about
    // opening new bins and more aggressive about tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Mean-residual coupling: when open bins are on average roomy, mildly
    // prefer filling them rather than spreading.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Modulo-based tie-breakers on post_residual (harmonic classes).
    match post_residual % 7 {
        0 => score -= 3.0,
        1 => score += 1.5,
        3 => score -= 1.0,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space (below minimum item size) — worst outcome.
            score += 40.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Gap too small for the lookahead item: potential dead space.
            score += 18.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Usable gap: mild penalty proportional to wasted fraction.
            score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (favor bins with small residuals); when few bins are open, be pickier.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;
    score -= pressure * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Prefer bins whose residual is close to the mean residual (balance load).
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead synergy: reward leaving a gap that exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when the current bin would leave near-dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = 45.0 + 30.0 * progress;
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // opening fresh avoids creating dead space
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
