pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if leftover exactly fits the next item (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space that next item cannot use: mild penalty scaled by progress.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 10.0 * (post_residual as f64 / bin_capacity as f64) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize bins that are already very full (leave big bins for big items).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += 8.0 * fill_ratio * fill_ratio;

    // Global state coupling: when many bins are open with high mean residual,
    // encourage consolidating into existing bins rather than opening new ones.
    if open_bins_count > 0 {
        let consolidation = mean_residual / bin_capacity as f64;
        if bin_residual < bin_capacity {
            score -= 12.0 * consolidation;
        }
    }

    // New-bin candidate handling: opening a new bin is discouraged unless
    // existing residuals are all poor fits for the item.
    if bin_residual == bin_capacity {
        let waste_if_new = (bin_capacity - item_size) as f64;
        let mut penalty = 25.0 + 0.4 * waste_if_new;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty *= 1.5 - progress;
        // If many bins fit the item, opening a new one is clearly wasteful.
        if fitting_bins_count > 1 {
            penalty += 30.0 * (fitting_bins_count as f64);
        }
        // If only this bin fits and mean residual is low, allow opening.
        if fitting_bins_count <= 1 && mean_residual < item_size as f64 {
            penalty *= 0.4;
        }
        score += penalty;
    }

    // Mild entropy term: diversify tie-breaking with bin residual structure.
    score += 0.05 * ((bin_residual as f64 * 0.37).sin());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, quadratically so small dead space matters more
    let mut score = norm_pr * norm_pr * cap;

    // Smooth non-linear coupling with stream progress:
    // late in the stream, tightening fits matters more; reward low post residual
    let tight = (1.0 - norm_pr).powi(3);
    score -= tight * cap * (0.5 + progress);

    // Dead-space penalty: residual too small for typical future items
    let dead = (-norm_pr * 8.0).exp(); // high when post_residual near 0
    score += dead * (0.25 * cap) * (1.0 - progress * 0.5);

    // Lookahead coupling: reward residual that can hold next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n) / cap;
        score -= (-diff * diff * 40.0).exp() * (0.35 * cap) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 0.6 * cap * (1.0 + progress);
    }

    // Many open bins: mild preference to consolidate into fuller bins
    let ob = open_bins_count as f64;
    score += (ob / (ob + 4.0)) * norm_pr * cap * 0.5;

    // Mean residual coupling: prefer bins below mean residual (fuller bins)
    let mr = mean_residual / cap;
    score += (norm_pr - mr) * cap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
