    // Reward tight fits: post_residual near zero is good.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class: post_residual mod 10 — small residue classes are more
    // reusable since item sizes are integers in 1..=100.
    let class = post_residual % 10;
    score -= (10 - class) as f64 * 1.5; // lower class value -> bigger bonus

    // Dead-space penalty: residual too small for the minimum item (size 1..10 band).
    // With unknown distribution, treat residuals < 10 as near-dead.
    if post_residual < 10 {
        score += 8.0; // slightly worse than leaving a reusable 10+ gap
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= (gap <= 10) as i32 as f64 * 15.0;
            score += gap as f64 * 0.3;
        } else {
            // next item cannot follow here; mild penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced when many items remain
        // (amortization) or when open bins are already crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 45.0 - 20.0 * progress;
        if mean_residual < item_size as f64 {
            new_bin_cost -= 10.0; // open bins are full-ish anyway
        }
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // must open
        }
        // A fresh bin has full capacity; reflect its flexibility.
        score = score - score + bin_capacity as f64 * 0.5 + new_bin_cost;
    }

    // Slight preference to fill bins with larger current residuals (consolidation),
    // scaled by how many bins compete.
    if bin_residual != bin_capacity {
        score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;
        score += open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin completely.
        score -= 120.0;
    }

    // Non-linear waste term: quadratic growth of unusable gap pressure
    // relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward tight fits: the less leftover relative to the item, the better.
    if item_size > 0 {
        score -= 25.0 * (item_size as f64 / (bin_residual as f64).max(1.0));
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 3.0;

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., nearly full bins) when the mean residual is large.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Lookahead (k=2): if the next item fits into the post-residual,
    // this placement sets up a good follow-up; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item almost fits (within small gap), slight penalty for
    // creating a near-miss dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // New-bin candidate handling: a brand-new empty bin is only attractive
    // when no open bin offers a reasonable fit. Penalize the empty-bin
    // candidate proportionally to how many bins could already fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 50.0 + 10.0 * (fitting_bins_count as f64);
        } else {
            score -= 30.0;
        }
    }

    // Slight time-decay pressure: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual proportionally to how much slack remains.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use this leftover space: mild penalty scaled by leftover.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: late in the stream, consolidation matters more; early on,
    // be more willing to spread out (explore).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    // Global state: many open bins -> encourage filling existing ones (consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (post_residual as f64) / 100.0;

    // Mean residual coupling: if this bin's residual is far below the mean, it is a
    // "cramped" bin; filling it is good. If far above mean, it is roomy; using it
    // for small items wastes its potential.
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += 0.1 * residual_gap * (item_size as f64) / (bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when no open bin is a
    // good home (poor fits / many bins / large item relative to residuals).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit_pressure = if post_residual > 0 && post_residual < item_size / 2 { 1.0 } else { 0.0 };
        score = (bin_capacity as f64) * 0.6
            - 20.0 * desperation
            + 15.0 * poor_fit_pressure
            - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual in [0,1]
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: dead space penalized super-linearly,
    // and penalty grows with stream progress (late stream => waste matters more).
    let dead_space = pr_norm * pr_norm * (1.0 + 3.0 * progress) * bin_capacity as f64;
    score += dead_space;

    // Reward tight fits (small post_residual) with a smooth quartic term
    score -= 8.0 * (1.0 - pr_norm).powi(4);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits smoothly in post_residual, reward
    if next_item_size > 0 {
        let next_fits = next_item_size as f64;
        if next_fits <= post_residual as f64 {
            let slack = (post_residual as f64 - next_fits) / bin_capacity as f64;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Penalize creating residuals that are just barely too small for next item
            let gap = (next_fits - post_residual as f64) / bin_capacity as f64;
            score += 10.0 * (1.0 - gap.min(1.0));
        }
    }

    // Mild preference for balancing residuals early: avoid extreme bins
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev * dev * (1.0 - progress);

    // Slight penalty for proliferating bins early
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: prefer minimal post-residual
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Harmonic classes: classify post_residual into capacity fraction classes
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post_class = post_residual / quarter;      // integer division class 0..4
    let next_class = if next_item_size > 0 { next_item_size / quarter } else { 0 };

    // Reward when next item's class matches post-residual class (likely future fit)
    if next_item_size > 0 && next_item_size <= post_residual {
        let mismatch = (post_class as i32 - next_class as i32).abs();
        score -= 40.0 - 8.0 * mismatch as f64;
        // exact harmonic match bonus
        if post_residual % next_item_size == 0 {
            score -= 25.0;
        }
        if post_residual % 10 == 0 && next_item_size % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this residual: penalize wasted dead space
        score += 30.0 + 0.5 * post_residual as f64;
    }

    // Modulo thresholds on post_residual: small odd residuals are dead space
    if post_residual < 10 {
        score += 45.0;
    } else if post_residual % 2 == 1 && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 200.0 - 150.0 * crowding;
        if open_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 20.0; // new bin preserves space for bigger next item
        }
    }

    // Progress-based mild preference to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins near the mean (balance)
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<=10) are pure waste; punish hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // Small gap: usable only by tiny items; moderate penalty scaled
        // by how much of the stream remains (future value of space).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 * (1.0 - progress) + (20 - post_residual) as f64 * 1.2;
    }

    // Reward near-perfect fits (post_residual close to 0 but not 0 handled above).
    if post_residual == 0 {
        score -= 25.0; // perfect packing: bin closed, ideal outcome
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward if the leftover exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover cannot host the next item: mild penalty proportional
        // to the wasted potential.
        let waste = (next_item_size - post_residual) as f64;
        score += (waste * 0.15).min(15.0);
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using
    // it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheaper.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline attractiveness, penalized when the
        // open-bin count is already high or mean residual is large.
        score = 50.0 + ob * 6.0 + mean_residual * 0.5;
        // Opening a new bin is more forgivable late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // If nothing else fits (this call is the only fitting candidate),
        // opening a new bin is mandatory; make it very attractive.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // Existing bins get a mild open-count penalty so that with many
        // open bins, only genuinely good fits beat the new-bin baseline.
        score += ob * 0.8;
        // Slightly favor bins with below-average residual (tighter bins
        // should absorb items first, keeping large gaps consolidated).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose leftover exactly matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 45.0;
        } else if diff <= 10.0 {
            score -= 20.0 * (1.0 - diff / 10.0);
        }
        // Penalize leftovers that are too small for any plausible next item (dead space)
        if post_residual > 0 && (post_residual as f64) < 10.0 {
            score += 15.0;
        }
    }

    // Compare post_residual against mean residual: prefer placements that
    // reduce residual variance / consolidate space.
    let pr = post_residual as f64;
    let deviation = (pr - mean_residual).abs();
    score += 0.15 * deviation;

    // Prefer tighter fits relative to bin capacity.
    score += 0.1 * (pr / cap) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64) > 60.0
            && next_item_size > 0
            && (bin_residual as f64 - item_size as f64 - next_item_size as f64) < 0.0;
        // Default penalty keeps new bins closed; reward when a big item would
        // strand space in every existing bin.
        if poor_fit || fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 40.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Early stream: slightly prefer filling existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let progress_weight = 0.6 * t * t - 0.3 * t + 0.2;
    score += progress_weight * (norm_pr * norm_pr) * cap;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = next_frac - norm_pr;
        if gap > 0.0 {
            score += 2.5 * gap * gap * cap;
        } else {
            // reward residual that still accommodates the next item
            score -= 1.2 * norm_pr * (1.0 - t);
        }
    }

    // Last-chance bonus: smooth in fitting_bins_count
    if fitting_bins_count == 1 {
        score -= 3.0 + 4.0 * item_frac;
    }

    // Tight fit reward: quadratic in (post_residual / capacity)
    score -= 1.5 * (1.0 - norm_pr) * (1.0 - norm_pr) * item_frac * cap;

    // Mild penalty for spreading across many open bins, smooth in open_bins_count
    let ob = open_bins_count as f64;
    score += 0.05 * (ob * ob) / (1.0 + ob);

    // Deviation from mean residual, smooth quadratic coupling
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by 10 are "harmonic" (easier future fits); penalize others.
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= harmonic * 6.0;

    // Dead-space penalty: tiny residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Exact match of next item to post residual -> strong reward.
            if next_item_size == post_residual {
                score -= 12.0;
            }
        } else {
            score += 5.0;
        }
        // Harmonic class match between next item and post residual (same mod-10 class).
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / 10.0;
        // Penalize opening new bins unless residual fit is bad.
        score += 20.0 + crowded * 2.0 - progress * 5.0;
        if item_size > 50 {
            score -= 10.0; // big items are fine in fresh bins
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // toward fullness (lower residual than mean is good).
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= (dev * 0.05).min(8.0);
    } else {
        score += (-dev * 0.05).min(8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (small gaps below the minimum realistic item footprint) are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 25.0;
    }
    // Dead space relative to capacity: tiny leftover slivers are worse than moderate gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Tight fit reward: nearly-full bins are excellent placements.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    // so we avoid leaving many partially filled bins around.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement
    // (chaining placements); if next item would be stranded by this placement, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate: an empty bin should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and crowding.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.9 + 15.0 * progress + (open_bins_count as f64) * 0.5;
        // If nothing else fits, opening a new bin is inevitable and fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: when average residual across open bins is small,
    // bins are nearly closed; prefer placements that close bins out.
    if mean_residual < 15.0 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // next item fits exactly-ish: strong reward proportional to closeness
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would NOT fit: penalize proportionally to wasted potential
            score += 50.0 + diff * 0.5;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer fuller bins early; late in stream be less picky
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.5 * (bin_capacity - bin_residual) as f64 * (1.0 - progress);

    // Penalize opening new bins when decent alternatives exist
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 80.0;
        } else {
            score -= 10.0;
        }
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: strongly favor small post_residual.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot fit the post residual
    // (dead space created), reward if it fits nicely.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if next_item_size == post_residual {
            score -= 35.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Larger items favor opening fresh bins; late in stream slightly discourage.
        score += 12.0 + item_size as f64 * 0.35 - progress * 15.0;
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // If mean residual across open bins is large, prefer reusing them.
        score += mean_residual * 0.5;
    }

    // Penalize bins whose residual is far from the mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear penalty on residual, modulated by stream progress.
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 60.0 * poly * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 25.0 * (1.0 - pr_norm).powi(3) * (0.4 + 0.6 * progress);

    // Penalize creating residual that cannot fit the lookahead item.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let gap = (pr - next_item_size as f64) / cap;
        let usable = 1.0 / (1.0 + (-8.0 * gap).exp());
        score -= 18.0 * usable * next_norm;
        score += 10.0 * (pr_norm - next_norm).max(0.0) * (1.0 - usable) * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (0.5 + progress);
    }

    // New-bin candidate: mild penalty early, larger later (prefer consolidation late).
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    } else {
        // Reward reusing bins relative to how full the fleet is.
        let mean_norm = mean_residual / cap;
        score -= 8.0 * (1.0 - mean_norm) * progress;
    }

    // Interaction: penalize leaving medium residuals mid-stream.
    score += 15.0 * (pr_norm * (1.0 - pr_norm)).powi(2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual divisible by common item sizes
    // is more reusable. Reward residuals that are "friendly" (multiples of 10/25/50).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 3.0; }
    }

    // Dead-space penalty: small unusable residuals
    if pr > 0 && pr < 10 {
        score += 12.0;
    } else if pr < 20 {
        score += 4.0;
    }

    // Integer-division threshold classes on post_residual (harmonic bands)
    let band = pr / 25; // 0..4
    score -= match band {
        0 => 2.0,          // tiny leftover, mostly bad but sometimes exact
        1 => 1.0,
        2 => 3.0,          // mid residual fits mid items well
        3 => 2.0,
        _ => 0.0,
    };

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: strong reward, scaled by how snugly
            let snug = (pr - next_item_size) as f64;
            score -= 10.0 - (snug / cap) * 10.0;
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64 / cap) * 8.0;
        }
    } else {
        // last item: prefer fullest packing
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // all existing residuals are poor fits and item is large.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // open fewer bins late in the stream
        score += progress * 10.0;
        // large items justify a new bin
        score -= (item_size as f64 / cap) * 20.0;
        // if current bin's residual can't hold next item either, new bin more attractive
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Crowd control: many open bins -> prefer consolidating into existing ones
    score += (open_bins_count as f64) * 0.3;

    // Mean-residual alignment: prefer bins whose residual is near the mean (keeps balance)
    let dev = ((post_residual as f64) - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals too small for the smallest possible
    // item (size 1..=min item) are pure waste. Penalize sharply when
    // post_residual falls into an "unusable gap" band.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        // tiny unusable sliver: heavy penalty proportional to wasted fraction
        score += 40.0 * (1.0 - gap / 10.0) + 15.0;
    } else if gap >= 10.0 && gap < 20.0 {
        // moderate risk gap: mildly penalize, may still fit small items
        score += 8.0 * (1.0 - gap / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open with
    // fragmented residuals; encourage consolidation when many bins are open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 0.35 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit in post residual but this bin could hold it, mild penalty.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0;
        } else if (next_item_size as u32) <= bin_residual {
            score += 3.0;
        }
    }

    // New-bin candidate: default moderate score; only chosen when no open bin
    // scores better (poor fits / last-chance logic above will usually win).
    if bin_residual == bin_capacity {
        // slight early-stream tolerance for opening bins, later discourage
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.6 + 20.0 * progress;
        // but if no open bin fits at all, opening is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item chain
        } else if next_item_size <= post_residual {
            score -= 25.0 - gap * 0.35; // next item still fits here
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15; // next item won't fit
        }
    } else {
        // Last item: prefer tightest fill.
        score += 5.0;
    }

    // Compare against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Penalize leaving small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mild preference for compacting into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Avoid opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + (fitting_bins_count as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Strong reward when item fills the bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fill, dead space minimal
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving residual that is too small for the next item (dead space).
            score += 0.25 * post_residual as f64 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Compare against mean residual: bins with residual below mean are scarcer; using them well is valuable.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        if res_f < mean_residual {
            score -= 8.0 * (1.0 - res_f / mean_residual);
        } else {
            score += 4.0 * (res_f / mean_residual - 1.0).min(2.0);
        }
    }

    // Time horizon: early in the stream, be conservative (favor spreading); late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer consolidating into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New-bin candidate: penalize slightly more when many bins already fit the item.
        if fitting_bins_count > 0 {
            score += 10.0 + 3.0 * fitting_bins_count as f64;
        }
    }

    // Prefer bins whose residual is close to item size (minimal waste ratio).
    if item_size > 0 {
        let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
        score += 10.0 * waste_ratio * waste_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let p1 = progress;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base fit-quality term: reward small residuals, weighted more as stream progresses
    score -= (1.0 - prn) * (1.0 - prn) * 30.0 * (0.4 + 0.6 * p1);

    // Perfect/near-perfect fit bonus, smoothly amplified over the stream
    let tightness = 1.0 - prn;
    score -= tightness.powi(4) * 40.0 * (0.5 + 0.5 * p3 + p2 * 0.5);

    // Penalize residuals that are too small to ever be useful (dead space),
    // but only when not a perfect fit — smooth quadratic in prn near zero
    let dead = if post_residual > 0 { (10.0 - prn * 100.0).powi(2) } else { 0.0 };
    score += dead * 0.15 * p1;

    // Lookahead: reward residuals that still fit the next item (smooth coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity as f64) * 12.0 * (1.0 - p2 * 0.5);
    } else if next_item_size > 0 {
        score += 8.0 * (0.5 + 0.5 * p1);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 - prn * 0.5);
    }

    // New-bin candidate: penalize opening a new bin when open bins fit,
    // penalty decays smoothly with stream progress and mean residual pressure
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let fit_factor = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 45.0 * fit_factor * (1.0 - 0.3 * p1) - pressure * 10.0;
        // Late in stream, new bins slightly more acceptable to consolidate
        score -= p3 * 15.0;
    }

    // Mild preference for bins below mean residual (balancing across bins)
    score += ((pr - mean_residual) / bin_capacity as f64) * 5.0;

    // Small crowd penalty: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * p2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: divide capacity into 5 bands.
    let band = post_residual * 5 / bin_capacity; // 0..4
    match band {
        0 => score -= 30.0,                 // near-perfect fit
        1 => score -= 12.0,                 // good
        2 => { /* neutral */ }
        3 => score += 8.0,                  // poor
        _ => score += 18.0,                 // large dead space
    }

    // Harmonic coupling: post_residual divisible by common item classes (10/20/25/50)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 8.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual % next_item_size.max(1) == 0 {
            score -= 10.0; // perfect future partition
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize proportionally to wasted residual
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral for small items early, penalize later / big items
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 40.0 * progress + 0.3 * item_size as f64;
        // but if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer filling bins when many are open (consolidation pressure)
    score += (open_bins_count as f64) * (post_residual as f64) * 0.02;

    // Deviation from mean residual: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    // Zero residual is perfect packing; reward strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves further residual: mild reward scaled by fit tightness.
        let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 * tight;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual unusable for the next item: penalize proportionally to gap size.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate relatively more as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Prefer bins whose residual is close to the mean (balanced filling),
    // penalize outliers creating fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in the stream, tighten packing (less tolerance for residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this bin is an ideal two-item match.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward matches where next item leaves little dead space too.
            if slack <= 10.0 {
                score -= 150.0 - slack * 5.0;
            } else {
                score += slack * 0.5;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportional
            // to wasted residual relative to mean residual.
            score += (post_residual as f64 - mean_residual).abs() * 0.3 + 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Prefer tighter bins (small residual before placement) when many bins fit.
    if fitting_bins_count > 1 {
        score += (bin_residual as f64) * 0.15;
    }

    // Penalize creating large unusable dead space (> 10) that typical items
    // (>= 10) can never fill exactly, scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (10.0 + 20.0 * progress);
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins are badly fragmented relative to the mean residual.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.4 {
            score -= 80.0 * (fragmentation - 0.4);
        } else {
            score += 150.0;
        }
    }

    // Mild preference to spread load when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty scaled by capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item exactly fills the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item still fits here mildly rewards keeping residual usable.
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use leftover: penalize large dead space.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Global state: many open bins -> discourage spreading; few bins -> consolidation fine.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
    score += pressure * 0.5;

    // Mean residual coupling: bins far below mean residual are better fill targets.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Early phase: be conservative, prefer keeping bins balanced; late phase: pack greedily.
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score = 75.0 + progress * 20.0 - scarcity;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for upcoming larger item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, punish residual waste quadratically.
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward using a nearly-full bin (small residual) with a smooth damping term
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - pr / cap);
    }

    // Prefer filling bins with larger residuals relative to mean (balance avoidance)
    if bin_residual != bin_capacity {
        score -= 5.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    // Penalize opening new bins when many bins are open and progress is high
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead" classes (tiny slivers) should be penalized heavily.
    let pr = post_residual;
    if pr > 0 {
        // Class by integer division thresholds (harmonic bands of capacity)
        let class = match pr {
            0 => 0,
            1..=5 => 1,       // unusable sliver -> worst
            6..=15 => 2,      // poor
            16..=33 => 3,     // medium
            34..=50 => 4,     // good (fits mid items)
            _ => 5,           // large residual, fine
        };
        let class_penalty = match class {
            1 => 40.0,
            2 => 18.0,
            3 => 7.0,
            4 => -6.0,
            _ => 0.0,
        };
        score += class_penalty;

        // Modulo coupling: residual divisible into next item's size hints
        // at future perfect packing; reward multiples.
        if next_item_size > 0 && pr >= next_item_size {
            let k = pr / next_item_size;
            if k >= 2 {
                score -= 4.0 * (k.min(4) as f64);
            } else {
                score -= 3.0;
            }
        }
        // Penalize residual that no plausible item (>=1) can use well if tiny
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
    }

    // Exact fit is gold
    if pr == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad
    // placement unless the fit is decent; reward it when fit is tight.
    if fitting_bins_count == 1 {
        if pr <= 10 {
            score -= 12.0; // tight fit in sole bin -> take it
        } else {
            score += 8.0;  // wasteful sole-bin placement -> prefer new bin
        }
    }

    // New-bin candidate handling: opening a bin is reasonable when the item
    // is large relative to capacity or existing residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = (item_size as f64) / cap;
        // Bias toward new bin when item is big and open bins are scattered,
        // but keep a base cost so it's not chosen reflexively.
        score = 30.0 + 25.0 * fragmentation - 30.0 * large_item - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // pairing large items together in a fresh bin
        }
    }

    // Mild tie-break: prefer bins with residual close to item (min waste ratio)
    if bin_residual > 0 {
        let tightness = 1.0 - (item_size as f64) / (bin_residual as f64);
        score += tightness * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        }
    }
    // Penalize if post_residual is smaller than next item (dead space for lookahead).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // encourage filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit && fitting_bins_count <= 2 {
            score -= 40.0; // open a fresh bin rather than create dead space
        } else {
            score += 15.0; // otherwise prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward when next item fits into the post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    }
    // Penalize leftovers that are too small for the next item (dead space risk).
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits (small post residual) but keep it usable.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize bins far below the mean residual (wasteful use of a large bin).
    score += ((bin_residual as f64 - mean_residual) * 0.15).max(-10.0).min(10.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (poor fit = large post residual relative to next item) or late in stream with many bins.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 10.0 };
        let last_chance_bonus = if fitting_bins_count == 1 { 45.0 } else { 0.0 };
        score += 30.0 + poor_fit_penalty + last_chance_bonus
            - (open_bins_count as f64 * 0.5)
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual that can't hold typical items.
    if post_residual < 10 {
        score -= 8.0; // nearly full bin is great — finish it off
    } else {
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in post_residual, reward.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize blocking next item slightly.
        score += 4.0 * (next_item_size as f64 / 100.0);
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be more conservative with tight fits
    // (keep flexibility); late, close bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to current mean residual or no good fits exist.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > mean_residual;
        score += 15.0;
        if large_item && fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big items coming, fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: penalize leftover space, with non-linear (quadratic) growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, dead space hurts more.
    let coupling = norm_pr * norm_pr * (0.5 + progress) + norm_pr * (1.0 - progress) * 0.3;
    score += 30.0 * coupling * cap;

    // Reward filling the bin nearly completely (small post residual)
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * cap * (0.4 + 0.6 * progress);

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 + 10.0 * (1.0 - pr / (next_item_size as f64 + 1.0));
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty scaled by how much it misses
        score += 6.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mean residual context: placing into a bin with residual far from mean
    // keeps diversity of residual sizes, which is good; penalize conformity.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score -= 8.0 * dev * (0.5 + progress);

    // Many open bins: discourage spreading, favor filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Brand-new bin candidate: neutral-ish baseline with progress-dependent cost
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.1 - 0.35 * progress) + 10.0;
        // opening a new bin is fine if no bin fits well
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: prefer tight fits (low post_residual already does this).

    // Harmonic class of post_residual: dead-space classes via integer division.
    // Residuals < 10 are essentially dead space (min item size 1..100, but small
    // residuals rarely reusable) -> penalize mildly; large residuals fine.
    let dead_class = post_residual / 10; // 0..=10 harmonic band
    if dead_class == 0 {
        score += 8.0; // tiny unusable sliver
    } else if dead_class <= 2 {
        score += 3.0; // hard-to-fill band
    }

    // Reward near-perfect fills: post_residual in the last 10% of capacity.
    if post_residual * 10 <= bin_capacity {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let post2 = post_residual - next_item_size;
            // harmonic class of the double-fill leftover
            if post2 / 10 == 0 {
                score += 5.0; // chain would create dead sliver
            } else {
                score -= 4.0 * (1.0 - (post2 as f64 / post_residual as f64));
            }
        } else {
            // next item cannot follow here; leftover must stand alone
            score += 2.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish score so it wins only over bad fits.
    if bin_residual == bin_capacity {
        score = 45.0
            - 10.0 * (step_index as f64 / (total_items as f64).max(1.0))
            + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference for bins below mean residual (consolidate fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (small post_residual relative to residual).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot fit here but a fresh bin would serve it, mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items into
    // new bins; a new empty bin candidate gets penalized.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * pressure;
    } else {
        score -= 8.0 * pressure;
    }

    // Prefer bins with below-mean residual (consolidate emptier bins' waste).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as the stream progresses, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
