pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * p2 + 3.0 * p3) * 40.0;
    score += coupling;

    // Penalize large dead space more as stream progresses (smooth quartic-ish term)
    score += norm_pr * norm_pr * cap * (0.5 + 1.5 * p2);

    // Reward tight fits (small post_residual) with smooth exponential-like falloff
    let tight = (-norm_pr * 8.0).exp() - 1.0; // negative for small pr
    score += tight * (30.0 - 15.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_bonus = (-diff / 20.0).exp();
        score -= 25.0 * fit_bonus * (1.0 + progress);
        // Penalize if post residual too small for next item (dead space)
        if pr < next_item_size as f64 {
            score += 10.0 * (1.0 - pr / cap) * (1.0 + p2);
        }
    }

    // Mild pressure to consolidate when many bins are open
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= bin_pressure * (1.0 - norm_pr) * 5.0;

    // Deviation from mean residual: prefer bins near the mean (smooth balance)
    score += (pr - mean_residual).abs() * (0.3 + 0.4 * progress);

    // New-bin candidate: make empty bin moderately attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        score = pr + 20.0 - 30.0 * (item_size as f64 / cap) * (1.0 + progress) - 40.0 * (fitting_bins_count == 1) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residual mod capacity fractions ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual into harmonic bands: e.g. residual in [0,10), [10,25), [25,50), [50,100)
    // Dead space below 10 is nearly unusable for items >= 10; heavily penalize leaving it.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space, bin effectively sealed with waste
    } else if post_residual < 25 {
        score += 8.0;
    } else if post_residual < 50 {
        score -= 4.0; // decent leftover, still useful
    } else {
        score -= 8.0; // large leftover: good bin choice
    }

    // Harmonic class via integer division: post_residual / 10 (decile class)
    let decile = (post_residual / 10) as f64;
    score += 0.5 * decile; // prefer bins leaving residuals in higher deciles

    // --- Lookahead coupling: does the next item fit into the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly it fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.1 * snug; // tighter fit for next item => bigger reward
        } else {
            // next item does not fit here: penalize creating residual just below next size
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 0.6 * gap; // "just missed" trap residual
            }
        }
    }

    // --- Last-chance logic: only this bin fits the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0; // strongly prefer using the sole fitting bin over opening a new bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus penalty if any open bin could fit
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Late in the stream, prefer consolidation into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If next item is huge, a fresh bin with full residual is attractive
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Reward filling bins that are already fairly full (waste minimization)
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 10.0 * fill * fill; // quadratic preference for full bins
    }

    // --- Mean residual coupling: prefer bins deviating positively from the mean ---
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // --- Modulo arithmetic on post_residual: residuals congruent to small remainders mod 10
    //     align with the minimum item size, making leftovers reusable ---
    let rem10 = (post_residual % 10) as f64;
    if post_residual > 0 {
        score += 0.2 * (10.0 - rem10); // residual near a multiple of 10 is more reusable
    }

    // --- Open bins pressure: many open bins -> consolidate harder ---
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count.min(20) as f64 - 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver -> dead space
    }
    // If the leftover gap cannot hold the lookahead item, it is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 18.0 + 0.5 * (next_item_size as f64 - post_residual);
    }
    // Reward tight fits strongly (near-perfect packing).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 12.0;

    // Open-bin pressure: when many bins are open, favor reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * 0.6 * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make the empty bin attractive only when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 6.0; // fresh bin keeps room for the lookahead item
        }
    }

    // Mild preference for bins whose residual is already below average
    // (consolidate into fuller bins, keep roomier bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after both placements
            let post2 = post_residual - next_item_size;
            score += post2 as f64 * 0.5;
        } else {
            // next item cannot use the leftover: dead-space penalty
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative residual coupling vs mean residual of open bins
    let residual_gap = post_residual as f64 - mean_residual;
    score += residual_gap * 0.4;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity {
        score += 120.0;
        // but allow new bin early in stream or when many bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 60.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for large leftover relative to capacity (dead space)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 50.0;

    // Slight preference to fill fuller bins first
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items (below min item size 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill, strongly reward
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // awkward small gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // More competing bins -> mild penalty for spreading items thin.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting large residuals.
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state coupling: when many bins are open, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64).ln() * (0.5 + progress);
    }

    // Compare against mean residual: bins with residual far from mean are less flexible.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how desperate the situation is.
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            let best_possible_waste = post_residual as f64;
            best_possible_waste
        };
        score = bin_capacity as f64
            - 20.0 * progress
            - (open_bins_count as f64) * 0.5
            + desperation * 0.8;
        if fitting_bins_count <= 1 {
            score -= 60.0; // no real alternative, new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps chain future large items
        }
    }

    // Late-stream consolidation: near the end, squeeze items into existing bins harder.
    if progress > 0.8 {
        score += 15.0 * (progress - 0.8) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Tight-fit reward: quadratic decay of residual (favor small post_residual)
    score -= (1.0 - pr / cap).powi(2) * 18.0;

    // Penalize residual that is dead space (too small for any typical item)
    let dead = (12.0 - pr).max(0.0) / 12.0;
    score += dead * dead * 25.0;

    // Non-linear coupling with stream progress: early on, tolerate loose bins;
    // later, prefer consolidating into tight fits.
    let prog_coupling = progress * progress;
    score += pr * prog_coupling * 0.35;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= (1.0 - gap / cap).powi(3) * 14.0;
        } else {
            // penalize if post_residual is just barely too small for next item
            let over = (nx - pr) / cap;
            score += over * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: only attractive when existing bins are quite full
    // or when the fit into this new empty bin is the only viable option.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened when many bins already open
        score += 22.0 - (open_bins_count as f64).ln().max(0.0) * 1.5;
        // if existing bins are nearly full, new bin is fine
        score -= (mean_residual / cap) * 12.0;
    } else {
        // prefer filling existing bins relative to mean residual
        score += (pr - mean_residual) * 0.25;
    }

    // Smooth non-linear interaction: residual^2 normalized by capacity
    score += (pr * pr) / (cap * 8.0) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic classes: post_residual in "useful" classes (multiples of common
    // item sizes 10..80 region) are more likely to be filled later.
    let pr = post_residual;
    let harmonic_bonus = if pr >= 10 && pr <= 80 {
        // residual itself could host a typical item
        if pr % 10 == 0 { 6.0 } else if pr % 5 == 0 { 3.0 } else { 0.0 }
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: residuals too small for any item (pr < 10) are waste,
    // but if we already placed, pr is fixed; penalize creating sub-10 gaps hard.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after next is what matters
            let pr2 = pr - next_item_size;
            score -= 10.0 - (pr2 as f64).min(10.0) * 0.5;
        } else {
            // next item won't fit here: mild penalty unless post_residual tiny
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when current open bins are fragmented
        // (mean residual high relative to capacity) or many bins already open.
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 5.0 + fragmentation * 20.0 + (open_bins_count as f64) * 0.5;
        // But if the item is large (hard to place later), opening fresh is fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Avoid opening new bins early in the stream when few bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 5.0;
    } else {
        // Existing bin: prefer fuller bins (smaller residual before placement).
        score += (bin_residual as f64) * 0.05;
    }

    // Coupling: penalize leaving residual that neither matches next item nor
    // harmonic class, scaled by stream progress (late waste is costlier).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if next_item_size > 0 && next_item_size != pr && next_item_size > pr && pr > 0 && pr < 10 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // plausible item are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize residuals too small for the known next item (would strand space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residual that exactly accommodates the next item.
    else if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Reward tight fits (item nearly fills the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // encourage filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open / late in stream.
        score += 20.0 + 3.0 * open_bins_count as f64 + 30.0 * progress;
        // But allow a new bin if mean residual is very low (all bins nearly full).
        if mean_residual < 15.0 {
            score -= 40.0;
        }
    } else {
        // Slight reward for using existing bins when open count is high.
        score -= 0.5 * open_bins_count as f64;
    }

    // Mild attraction toward bins with residuals close to the item (good fit).
    let slack_gap = (bin_residual - item_size) as f64;
    score += 0.1 * (slack_gap - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly fits the next item (2-step lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Also reward when next item fits with small slack.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0 - slack * 1.5;
        } else {
            score -= (10.0 / slack).min(5.0);
        }
    }
    // Penalize leaving dead space that cannot fit the next item.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size as f64 - post_residual as f64;
        score += dead * 0.5;
    }

    // Prefer bins with residuals below the mean (tighter packing).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight penalty for very small post residuals that create unusable slivers,
    // unless they exactly match the next item.
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && post_residual == next_item_size) {
        score += 8.0;
    }

    // Mild preference for opening new bins early in the stream when few bins exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract proportionally to how full the bin becomes
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item exactly fits the post-residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space: post-residual too small for the next item
            score += 6.0 + 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize leaving residuals in the "unusable zone" (small gaps that rarely fill)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Global state coupling: prefer bins below mean residual when many bins are open
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap * (open_bins_count as f64).sqrt();

    // Time horizon: early in the stream, be more conservative (favor tight fits less,
    // keep flexibility); late in the stream, pack aggressively.
    score *= 0.8 + 0.4 * progress;

    // New-bin candidate: make it unattractive unless it is genuinely competitive.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, softened when many bins are open
        // (spreading load can be fine) and when the item is large.
        let new_bin_penalty = 15.0
            - 0.3 * (open_bins_count as f64)
            + 20.0 * (item_size as f64 / bin_capacity as f64);
        score += new_bin_penalty.max(2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear shaping
    let mut score = pr;
    score += cap * norm_pr * norm_pr * (1.0 + progress);

    // Coupling with mean residual: penalize bins deviating from fleet state
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * cap;

    // Lookahead: reward leaving space the next item can use
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 6.0 * (1.0 - slack * slack) * ns / cap * cap * 0.1;
        } else {
            // next item cannot fit here: penalize tight fills
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when open bins exist
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Tight fit reward: smooth function of fill ratio
    let fill = (cap - pr) / cap;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it fall in?
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals in "dead zones": too small to fit typical items (1..100 range)
    // Items are 1..100, so any residual < min plausible item is dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score -= 40.0; // near-perfect, unusable remainder is fine
    } else {
        // Dead-space penalty grows as residual shrinks into unusable band
        let dead = (10.0 - frac * 100.0).max(0.0);
        score += dead * 1.5;
    }

    // Harmonic classes via integer division thresholds on post_residual
    let class = post_residual / 25; // classes 0..4
    match class {
        0 => score += 8.0,   // residual 0..24: small leftover, awkward
        1 => score += 2.0,   // 25..49: can host medium items
        2 => score -= 3.0,   // 50..74: good host for medium/large
        3 => score -= 5.0,   // 75..99: spacious
        _ => score -= 10.0,  // full empty bin (100)
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how snugly next item fits
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 12.0 * snug;
        } else {
            score += 6.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins when many are open; early stream be slightly greedy-tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Alignment with mean residual: avoid bins far below mean (fragmented)
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += pressure * (10.0 + open_bins_count as f64 * 2.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin helps sequence large items
        }
    }

    // Modulo harmonic: reward residuals that are multiples of common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in 1..10 is a dead gap (min item = 1 here).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual < 20 {
        score += 10.0; // hard-to-reuse gap
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // chain fit
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item can't use this gap
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 3.0 * open_bins_count as f64;
        // New bin is attractive only if current item is large and would leave a
        // bad gap in any existing bin; otherwise the +pressure keeps it last.
        if item_size >= 70 {
            score -= 20.0;
        }
        // Early stream: allow more bins since future items unknown.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.25 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are "loose" — prefer them.
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // slack after pairing both items
            let slack2 = post_residual - next_item_size;
            score -= 2.0 * next_item_size as f64;
            score -= 0.5 * slack2 as f64;
            if slack2 == 0 {
                score -= 500.0;
            }
        } else {
            // dead space that next item cannot use
            score += 0.8 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Prefer bins whose residual deviates from the mean (tight packing)
    score -= 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64).sqrt() * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0; // new bin can still host the next item
        }
    }

    // Late in the stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (post_residual close to 0 or small)
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // penalize dead space that is too small to hold typical items
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 1.5; // tiny slivers are wasted
        } else {
            score -= 5.0 / (post_residual as f64).sqrt();
        }
    }

    // Tightness of fit: fraction of bin consumed by this item
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Lookahead: if the next item fits into the post-residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // good chain: next item can also go here
            let chain_waste = post_residual - next_item_size;
            score -= 12.0 - (chain_waste as f64).min(12.0) * 0.4;
        } else {
            // next item won't fit here; penalize more if the leftover is useless
            let leftover = post_residual as f64;
            if leftover < next_item_size as f64 {
                score += (next_item_size as f64 - leftover) * 0.3;
            }
        }
    } else {
        // last item: strongly prefer zero residual
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        // opening a new bin is penalized mildly; worse late in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 18.0 + progress * 10.0;
        // but if open bins are all nearly full (small mean residual), new bin is fine
        score -= (mean_residual / 10.0).min(15.0);
        // if many bins are open, prefer reusing them
        score += (open_bins_count as f64).min(10.0) * 1.2;
    } else {
        // reusing an existing bin: reward slightly, more when many bins open
        score -= (open_bins_count as f64).min(15.0) * 0.5;
    }

    // Compare residual to mean residual across open bins: prefer bins with residual close to item
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.2;

    // Prefer bins whose residual is small relative to the mean (they're nearly full, use them up)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, leave room (post residual less penalized); late, prefer tight fits.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = post * progress_weight;

    // Non-linear waste penalty: dead space below the smallest possible item is useless.
    let dead = if post_residual > 0 && post_residual < 10 { (10.0 - post) * 3.0 } else { 0.0 };
    score += dead;

    // Smooth fill-ratio reward: bins that are nearly full get extra attraction.
    let fill = 1.0 - post / cap;
    score -= fill * fill * item * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * fill;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * nxt;
        } else {
            // penalize leaving residuals that waste space relative to next item
            score += 0.05 * (nxt - post).max(0.0);
        }
    }

    // New-bin candidate handling: empty bin should lose unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) * 0.4 + mean_residual * 0.05;
        // New bin is attractive early (plenty of stream left) but costly late.
        score += 30.0 + crowding - 25.0 * progress;
    } else {
        // Mild preference for reusing bins with larger residuals among open bins.
        score += 0.02 * (mean_residual - bin_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact halves/quarters are valuable
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 40.0;
    } else {
        // reward post_residuals that are harmonic fractions of capacity
        let frac = pr as f64 / cap;
        if (frac - 0.5).abs() < 0.01 {
            score -= 25.0;
        } else if (frac - 0.25).abs() < 0.01 || (frac - 0.75).abs() < 0.01 {
            score -= 15.0;
        }
        // dead space penalty: leftovers that few item sizes can use
        if pr < 10 {
            score += 30.0;
        } else if pr < 20 {
            score += 12.0;
        }
        // modulo classes: leftovers divisible by common item granularities are reusable
        if pr % 10 == 0 {
            score -= 10.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        } else {
            score += 4.0;
        }
    }

    // Lookahead: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // harmonic coupling: exact match for next item is gold
            if post_residual == next_item_size {
                score -= 35.0;
            } else if post_residual - next_item_size <= 5 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            score += 10.0; // leaves next item needing another bin
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = mean_residual / cap;
        score = cap - 20.0 * congestion - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild pressure to prefer tighter bins as stream progresses
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum item (1)
    // are pure waste; the worst is a gap of exactly 1..=min_item. Penalize sharply.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32 as f64) * 25.0; // small unusable gap => big penalty
    }
    // Perfect fit is heavenly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting the next item too (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item can't use this gap: dead space for lookahead
    }

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins => prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        // Existing bin: mild reward scaling with open bins to consolidate load.
        score -= 0.5 * open_bins_count as f64;
        // Prefer bins tighter than average (good fits concentrate).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (dead space near zero)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize unusable dead space relative to smallest possible item (1)
        score += (post_residual as f64).powf(1.4) * 0.6;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let slack = post - next;
            if slack == 0.0 {
                score -= 800.0; // next item fills bin perfectly
            } else {
                score -= (post - slack).max(0.0) * 0.0;
                score += slack * 1.5; // penalize leftover after next placement
            }
        } else {
            // next item won't fit here; mild penalty proportional to overflow gap
            score += (next - post) * 0.4;
        }
    }

    // Compare post residual against mean residual: prefer bins whose residual
    // was already tight (packing into crowded bins preserves spread-out space)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no good fit exists (large post_residual on empty bin = wasted space)
    if bin_residual == bin_capacity {
        let base_penalty = 120.0;
        let waste = (bin_capacity - item_size) as f64;
        score = base_penalty + waste * 1.2 + post_residual as f64 * 0.5;
        // Late in stream, opening new bins is more acceptable
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 40.0;
        // If many bins fit, definitely don't open new one
        if fitting_bins_count > 2 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item can use:
    // dead space is post_residual smaller than the minimum item size (1),
    // but practically penalize very small leftovers relative to typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Global state: when many bins are open with slack, prefer consolidating
    // into bins with above-average residual (fill the fullest-fitting bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread load); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that grows with progress
        // and with number of open bins, so late stream favors existing bins.
        score += 8.0 + 20.0 * progress + 0.8 * open_bins_count as f64;
        // But if the item is large and no open bin fits well (many fitting bins
        // means plenty of alternatives), still allow new bin early.
        if progress < 0.3 && item_size > 60 {
            score -= 10.0;
        }
        // If next item is huge, keep a fresh bin attractive to host it.
        if next_item_size > 70 {
            score -= 12.0;
        }
    } else {
        // Existing bin: mild reward for using already-open bins, stronger late.
        score -= 3.0 + 5.0 * progress;
    }

    // Avoid scattering: penalize placements that leave post_residual near the
    // mean residual (creates many similar half-empty bins) late in stream.
    if progress > 0.6 && post_residual as f64 > mean_residual {
        score += 0.1 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial decay
    let mut score = pr_norm * (1.0 + 0.8 * pr_norm);

    // Non-linear coupling: waste hurts more as the stream progresses
    score += 2.5 * pr_norm * pr_norm * progress;

    // Perfect fit reward (smooth, avoids hard cutoff)
    let perfect = 1.0 - pr_norm;
    score -= 6.0 * perfect * perfect * perfect;

    // Lookahead: penalize leaving a residual that would strand the next item,
    // reward residuals that can host it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as u64) >= (next_item_size as u64) {
            score -= 2.0 * (nxt / cap) * (1.0 - progress);
        } else {
            // residual too small for next item: dead-space penalty, smoother for tiny gaps
            let gap = nxt - pr as f64;
            score += 1.5 * (gap / cap) * (1.0 - (pr_norm / (nxt / cap + 1e-9)).abs());
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0 + 3.0 * (1.0 - pr_norm);
    }

    // New-bin candidate handling: make empty bins unattractive unless open bins are very full
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 8.0 - 10.0 * mean_fullness * mean_fullness - 2.0 * scarcity;
        // late in the stream, consolidate harder
        score += 3.0 * progress;
    }

    // Mild pressure to fill bins when many are open
    score += 0.3 * (open_bins_count as f64).ln() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Dead-space class penalties: residuals that are hard to fill (small odd leftovers)
    // get extra penalty; "nice" residuals (0, or multiples of common item sizes) get rewards.
    let nice = |r: u32| -> f64 {
        if r == 0 { return 0.0; }
        for m in [50u32, 40, 30, 25, 20, 10].iter() {
            if r % *m == 0 { return -6.0; }
        }
        for m in [5u32, 15, 45, 60, 75].iter() {
            if r % *m == 0 { return -3.0; }
        }
        // small unusable leftovers are dead space
        if r < 10 { return 14.0; }
        if r < 20 { return 7.0; }
        0.0
    };
    score += nice(post_residual);

    // Fractional capacity coupling: reward tight fits (small frac), punish mid-range waste
    if frac > 0.0 && frac < 0.1 {
        score -= 8.0; // very tight fit
    } else if frac >= 0.5 {
        score += 4.0 * frac; // half-empty or worse is wasteful unless bin is fresh
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
            // harmonic class match: next item leaves another nice residual
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 3.0 * (next_item_size as f64 - post) / cap;
        }
    } else {
        // last item: prefer zero residual strongly
        score -= 10.0 * (1.0 - frac);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin starts at full residual; make it attractive
    // only when no open bin offers a good fit (post_residual small) — otherwise it
    // should lose to reusing bins.
    if bin_residual == bin_capacity {
        score += 25.0; // default: prefer reusing open bins
        if fitting_bins_count == 0 || (post_residual as f64) > 0.5 * cap {
            score -= 30.0; // opening fresh is fine when fits are poor
        }
        // early stream: opening bins is cheap since many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from the mean in a useful (smaller) direction
    score -= 0.5 * (mean_residual - post);

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64 * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: hard penalty for unusable small gaps.
    // A residual below the minimum plausible item size (1) is impossible,
    // but residuals that are very small relative to typical items are
    // effectively dead space. Penalize gaps < 10 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Soft dead-space penalty: non-linear cost for small residuals that
    // are unlikely to absorb future items.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 40.0 {
        score += 0.6 * (40.0 - pr) / 40.0 * (40.0 - pr) / 40.0 * 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward tight fits (small post residual) proportionally.
    score -= 0.15 * (bin_capacity as f64 - pr) / bin_capacity as f64;

    // Open bins pressure: penalize using an open bin when many are open,
    // encouraging consolidation rather than spreading items thinly.
    score += 0.05 * open_bins_count as f64;

    // Last-chance bonus: if this is the ONLY bin that fits the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when
    // no open bin offers a good fit. Make the empty-bin baseline costly
    // so consolidation is preferred unless fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Extra penalty if existing bins can already fit the item.
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if the next item could use the post residual,
    // reward leaving that much space; penalize if next item is large
    // while we leave a tiny gap.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 3.0 * (1.0 - (pr - ni) / bin_capacity as f64);
        } else {
            score += 0.05 * (ni - pr);
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins) to keep large residuals available for large items.
    if pr < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Stream progression: early on, be more willing to open bins; late in
    // the stream, consolidate aggressively to avoid leftover partial bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item exactly
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 400.0; // next item fills this bin perfectly
        } else if pr > nxt {
            score -= 150.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // next item cannot fit; penalize dead space relative to mean residual
            score += 0.6 * (nxt - pr).min(80.0);
        }
    }

    // Prefer tight fits relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin bonus: avoid wasting scarce fitting capacity
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a new bin early unless existing residuals are very tight
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 - 40.0 * progress;
        if mean_residual > item_size as f64 * 1.5 {
            score += 80.0; // existing bins still roomy; don't open new one
        }
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 50.0; // new bin can also host next item
        }
    }

    // Mild preference for keeping many open bins consolidated
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (next_item_size as f64).min(post_residual as f64)
        } else {
            0.0
        };
        let waste = post_residual as f64 - dead;
        score += 0.35 * waste;
    }

    // Lookahead: bonus if next item exactly fills the new residual.
    if next_item_size > 0 && (next_item_size as f64 - post_residual as f64).abs() < 1e-9 {
        score -= 8.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item can't use this residual: mild penalty, worse late in stream
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 3.0 * (0.5 + 0.5 * t);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let crowding = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.02 * crowding;

    // Divergence from mean residual: prefer bins with smaller residual (fuller bins).
    score += 0.10 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate handling: make empty bin mildly attractive only when
    // no good fit exists (post_residual large relative to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) / cap; // = 1 - item/cap for empty bin
        let open_bonus = if open_bins_count == 0 {
            -50.0
        } else if poor_fit > 0.75 || (fitting_bins_count <= 1 && poor_fit > 0.5) {
            -6.0
        } else {
            10.0 + 8.0 * t
        };
        score += open_bonus;
    }

    // Small dynamic horizon term: later in stream, be greedier about tight fits.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * tightness * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap; // 0..1 normalized post residual
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    // Early in stream: penalize mid-range residual (wasted space); later: reward tight fits.
    score += poly * (40.0 * (1.0 - progress) - 20.0 * progress);

    // Smooth tight-fit reward: cubic falloff around small post_residual.
    let tight = (1.0 - pr_norm).powi(3);
    score -= 12.0 * tight * (0.5 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a bin when others fit, scaled by stream progress.
    if bin_residual == bin_capacity {
        let openness = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        score += 8.0 + 12.0 * progress + 0.5 * openness;
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let diff = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - diff * diff);
        } else {
            let miss = (nxt - pr) / cap;
            score += 5.0 * miss * miss;
        }
    }

    // Mean residual alignment: prefer bins near the mean (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "perfect fits"
    // for common item classes (multiples of 10, 20, 25, 50) are more usable.
    let r = post_residual;
    let mut class_bonus = 0.0;
    if r == 0 {
        class_bonus -= 60.0; // perfect closure
    } else {
        if r % 10 == 0 { class_bonus -= 12.0; }
        if r % 20 == 0 { class_bonus -= 6.0; }
        if r % 25 == 0 { class_bonus -= 6.0; }
        if r % 50 == 0 { class_bonus -= 8.0; }
        // Integer-division dead-space thresholds: tiny unusable slivers are bad.
        if r < 10 { class_bonus += 25.0; }
        else if r < 20 { class_bonus += 10.0; }
        // Large residual classes are valuable space; keep them but not too open.
        let q = r / 25; // coarse harmonic band 0..4
        class_bonus -= 3.0 * (q as f64);
    }
    score += class_bonus;

    // Best-fit coupling: reward tight fits relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= r {
        let exact = (next_item_size == r) as f64;
        let near = (r as i64 - next_item_size as i64) <= 10;
        score -= 30.0 * exact;
        if near { score -= 10.0; }
    } else if next_item_size > r {
        // next item won't fit here; penalize leaving residual that wastes capacity
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large or open bins are congested with small residuals.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64) / bin_capacity as f64;
        // Penalty for opening new bins by default; reduced when item is big,
        // congestion is low (residuals small), or stream is early.
        score += 45.0 - 30.0 * big_item - 10.0 * congestion - 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items into fresh bins is fine
        }
    }

    // Slight preference to fill more-open bins when many are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: make it unattractive unless nothing sensible fits.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        if post_residual >= 20 && fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits -> must open
        }
    }

    // Lookahead: if next item fits the post residual, bonus.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 12.0;
    }

    // Pressure from many open bins: prefer filling existing ones.
    score += 1.5 * open_bins_count as f64;

    // Slight progression term to stabilize behavior over the stream.
    if total_items > 0 {
        score += 5.0 * (step_index as f64 / total_items as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 150.0 - 0.8 * slack;
        if slack == 0.0 {
            score -= 300.0; // chain of two perfect fits
        }
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use, scaled by how dead it is.
        let unusable = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
        score += 0.5 * (post_residual as f64).min(next_item_size as f64);
        let _ = unusable;
    }

    // Prefer bins tighter than the mean residual (best-fit orientation).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Mild preference to fill existing bins when many are open (avoid bin sprawl).
    score += 0.05 * open_bins_count as f64;

    // Early in stream: slightly favor compacting into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * progress;

    // New-bin candidate: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins with reasonable fits win.
        score += 60.0 + 0.3 * mean_residual;
        if next_item_size > 0 && item_size >= 50 {
            score -= 40.0; // big items may justify a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (non-linear coupling on residual waste).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 30.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate; relax the penalty when open bins
    // are crowded (mean residual low) or late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 18.0 * crowding - 6.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize dead space proportional to it.
        score += 4.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Mild preference for tighter bins when many bins are open (consolidation).
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Tie-breaker favoring fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    let coupling = poly * (0.5 + progress);

    // Next-item lookahead: penalize residuals too small for the next item
    let next_fit = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -1.0
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -8.0
    } else {
        0.0
    };

    // Mild penalty for opening new bins late in the stream
    let open_bias = if bin_residual == bin_capacity {
        2.0 + 3.0 * progress + 0.01 * open_bins_count as f64
    } else {
        0.0
    };

    // Deviation from mean residual: prefer bins near mean to balance load
    let dev = (pr - mean_residual).abs() / cap;

    let mut score = pr - 6.0 * coupling + 1.5 * dev + next_fit * 2.0 * (1.0 - progress) + last_chance + open_bias;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Tightness reward: quadratic bonus for small leftover space ---
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1
    score -= 18.0 * fit_ratio * fit_ratio;

    // --- Perfect / near-perfect fit classes (harmonic residue classes) ---
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // exact fill
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // --- Dead-space penalty: leftover space too small for typical items ---
    // Items 1..100 unknown distribution; treat residual < 10 as near-dead.
    if pr > 0 && pr < 10 {
        score += 30.0 * (10 - pr) as f64 / 10.0;
    }

    // --- Harmonic class coupling: post_residual residue modulo 10 ---
    // Residuals that are multiples of 10 pair well with common item sizes.
    let pr_mod = (pr % 10) as f64;
    score += 0.8 * pr_mod; // prefer residuals aligned to decade grid

    // --- Lookahead: does the next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain placement possible: reward proportionally to how well it chains
            let chain_waste = (pr - next_item_size) as f64;
            score -= 12.0 - 0.15 * chain_waste;
            // Harmonic bonus: next item exactly consumes a decade chunk
            if (next_item_size % 10 == 0 && pr % 10 == 0) || pr == next_item_size {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: leftover becomes dead space for it
            score += 0.25 * next_item_size as f64;
            if pr > 0 && pr < next_item_size {
                score += 6.0;
            }
        }
    }

    // --- Last-chance bin: only bin that can fit the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0; // strongly prefer using it over opening a new bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin
        score += 15.0;
        // But if the item is large and would leave a big residual in any bin,
        // a fresh bin is attractive (item fills it cleanly).
        if item_size >= 70 {
            score -= 10.0;
        }
        // If many bins are open and mean residual is large, spreading load is fine
        if mean_residual > 40.0 && open_bins_count > 3 {
            score -= 5.0;
        }
        // Late in the stream, avoid proliferation of slightly-used bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // --- Mild preference for filling bins that are already below mean residual ---
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.05 * dev; // emptier-than-average bins get slight priority
    } else {
        score += 0.03 * (-dev);
    }

    // --- Open-bin count pressure: with many open bins, consolidate ---
    if open_bins_count > 8 {
        score += 0.5 * ((open_bins_count - 8) as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Tight-fit reward: the smaller the gap relative to bin capacity, the better.
    score -= 45.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize leaving a gap just barely too small for the next item (creates dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins are reasonably empty.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 25.0 + 8.0 * open_bins_count as f64;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 20.0; // an open bin can hold it reasonably well; avoid new bin
        }
    } else {
        // Mild reward for keeping bins consolidated.
        score -= 2.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Prefer placing into bins whose residual is below the mean (fill emptier-topped bins last).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, tighten packing (less tolerance for loose fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but scale by capacity context.
    let cap = bin_capacity as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);

    // Lookahead term: how well does the next item fit the post-residual space?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Next item fits perfectly -> strong reward (2-step chain).
            let slack = post - nxt;
            score -= 18.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 25.0; // perfect 2-chain bonus
            }
        } else {
            // Next item won't fit: post_residual is dead space for the horizon.
            // Penalize proportionally to how unusable the leftover is.
            let unusable = post / cap;
            score += 10.0 * unusable;
            // If next item is small and many bins exist, waste matters less early.
            score -= 6.0 * (1.0 - progress) * unusable;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Compare against mean residual of open bins: prefer leaving residuals
    // below the mean (tighter than average) and avoid fragmenting large residuals.
    if mean_residual > 0.0 {
        let dev = (post_residual as f64 - mean_residual) / cap;
        if dev > 0.0 {
            score += 8.0 * dev; // above-average leftover -> penalty
        } else {
            score -= 4.0 * (-dev); // below-average leftover -> reward
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        // But if post_residual becomes tiny/unusable, soften the bonus.
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when no good fit exists; make empty bin moderately costly
    // so it wins only when open bins would create large dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening new bins is cheaper (fewer leftover items).
        score -= 15.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
