pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, prefer tight fits (wasted space weighted), later allow looser packing.
    let tightness = x * x * (1.0 + 2.0 * progress) - x * progress * progress;
    score += 8.0 * tightness * cap * 0.01;

    // Reward near-perfect fits smoothly (quadratic valley around small residual).
    let perfect = 1.0 - x;
    score -= 6.0 * perfect * perfect * perfect * cap * 0.01;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in post residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let waste_after_next = pr - nx;
            score -= 10.0 * (1.0 - waste_after_next / cap);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // Discard new-bin candidate unless open bins are fragmented or item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 12.0 + 10.0 * (1.0 - fragmentation);
        if fitting_bins_count > 0 {
            score += 5.0 * (fitting_bins_count as f64).sqrt();
        }
    }

    // Mild preference for bins with residual close to mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Harmonic class of post_residual: dead space in awkward small classes is costly.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals below 10 are nearly dead space (min item size ~ small); penalize.
        if pr < 10 {
            score += 18.0;
        } else if class <= 2 {
            score += 6.0; // awkward sliver class
        } else if (10..=20).contains(&pr) {
            score += 4.0; // only fits tiny items
        }
    }

    // Lookahead synergy: if the next item fits exactly into the post-residual class, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0; // perfect chain
        } else if gap <= 5 {
            score -= 12.0;
        } else if gap <= 15 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual cannot host next item: mild penalty scaled by how far off.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.10 * miss;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer open bins unless the new bin gives a notably
    // better residual profile than the mean of open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if open bins are crowded (mean residual low relative to item), opening
        // a fresh bin is reasonable; discount the cost.
        let crowd = mean_residual / (bin_capacity as f64);
        if crowd < (item_size as f64) / (bin_capacity as f64) {
            score -= 35.0;
        }
        // Late in the stream, consolidation matters more: raise new-bin cost.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        score += 8.0 * (fitting_bins_count as f64);
    }

    // Mild preference to fill bins that are already mostly full (harmonic of residual).
    if bin_residual > 0 && bin_residual < bin_capacity {
        score -= 6.0 / ((bin_residual as f64).sqrt());
    }

    // Small penalty scaled by number of open bins to discourage bin sprawl.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (size 1) are less harmful than mid-range gaps, but
    // gaps that are small relative to the next item are dangerous.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Dead space that cannot serve the lookahead item: penalize
            // proportionally to how close the gap is to being useful.
            let waste_ratio = (next_item_size - post_residual) as f64 / next_item_size as f64;
            score += 12.0 * waste_ratio * waste_ratio;
        }
        // Non-linear penalty on mid-range unusable gaps (0 < r < ~20).
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 0.8;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading
    // (favor filling existing bins), unless the new-bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    } else {
        // New-bin candidate: penalize more when many bins are open and
        // mean residual across open bins is still large (they can absorb).
        score += 6.0 + 0.1 * open_bins_count as f64 + 0.05 * mean_residual;
        // But if the item is large and no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below
    // average (i.e., filling the emptier-feeling bins less; prefer bins
    // closer to full than the fleet average).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.08 * diff;
    }

    // Lookahead synergy: if the next item exactly fits the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
