pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit component: exact fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small post residuals nonlinearly (dead space avoidance).
        let pr = post_residual as f64;
        if pr <= 10.0 {
            score += 30.0 * (1.0 - pr / 10.0);
        }
    }

    // Tightness: prefer bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead coupling: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Next item fits here: reward proportional to how snugly.
            score -= 25.0 * (nxt / post);
        } else if nxt <= post + 20.0 {
            // Next item almost fits: slight penalty for wasting space.
            score += 8.0 * (1.0 - (post - nxt).abs() / 20.0);
        }
        // If next item is huge, prefer conserving large-residual bins for it.
        if nxt > post {
            let waste_potential = (post - nxt).abs();
            score += 0.05 * waste_potential;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // More open bins -> discourage spreading items across many bins.
        score += 5.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * (1.0 - progress);
        // If mean residual across open bins is large, prefer reusing existing bins.
        score += 0.5 * mean_residual;
        // If other bins fit, penalize new bin more when the fit elsewhere would be decent.
        if fitting_bins_count > 0 && post_residual < 15 {
            score -= 30.0;
        }
    } else {
        // Slight preference for reusing existing bins as the stream progresses.
        score -= 10.0;
    }

    // Global pressure: many open bins with high mean residual -> favor filling existing bins harder.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 0.3 * mean_residual;
    }

    // Mild noise-free tie-breaker using bin residual identity.
    score += 0.01 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;

    // Base: post-residual (waste), scaled non-linearly by stream progress.
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Tight-fit reward: strong polynomial coupling of fill ratio with progress.
    let fill = it / cap;
    let tight = (fill * fill) * (1.0 + 2.0 * progress);
    score -= 12.0 * tight;

    // Penalize residuals that are unlikely to fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (pr - nx).min(30.0) / cap;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - progress);
    }

    // Fragmentation penalty: small post residual relative to mean residual is dead space.
    let frag = (pr / cap) * (1.0 - (pr / mean_residual.max(1.0)).min(1.0));
    score += 6.0 * frag;

    // Mild penalty for spreading across too many open bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate shaping: empty bin gets neutral-ish score unless fits are poor.
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) - 2.0 * progress;
    }

    // Smooth non-linear coupling of residual with progress.
    score += 0.5 * ((r / cap) * (r / cap)) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Class bins by capacity fraction: post_residual bucket via integer division.
        let class = pr / 10; // 0..=10 harmonic class
        // Dead space penalty grows superlinearly for small unusable residuals.
        if pr < 10 {
            score += (10 - pr) as f64 * 4.0; // tiny dead space is nearly worthless
        } else if pr >= 50 {
            score -= 6.0; // large residual keeps bin reusable
        } else {
            // mid-range: mild reward for larger residuals
            score -= class as f64 * 0.5;
        }

        // Modulo-10 alignment: residuals that are multiples of 10 pair well with
        // typical item sizes; reward exact decade alignment.
        if pr % 10 == 0 {
            score -= 3.0;
        } else {
            score += (10 - (pr % 10)) as f64 * 0.3;
        }

        // Lookahead coupling: can next item exactly fill the leftover?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 500.0; // perfect chained fit
            } else if next_item_size < pr {
                let npr = pr - next_item_size;
                // harmonic class of the double-post residual
                if npr % 10 == 0 {
                    score -= 8.0;
                }
                if npr < 10 {
                    score += npr as f64 * 2.0; // would create tiny dead space
                }
            } else {
                score += 5.0; // next item cannot use this bin's leftover anyway
            }
        }

        // Last-chance bonus: only this bin fits; strongly prefer using it.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 120.0;
        }

        // New-bin candidate: penalize opening a new bin when open bins exist,
        // unless residual would be large and reusable.
        if bin_residual == bin_capacity {
            score += 40.0 + open_bins_count as f64 * 0.5;
            if next_item_size > 0 && next_item_size >= 50 {
                score -= 30.0; // big next item may warrant fresh bin
            }
        }

        // Early stream: be greedy on fills; late stream: keep bins balanced.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.2;

        // Prefer bins below mean residual (tighter bins) slightly.
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
