    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    }
    // Penalize if next item would be blocked by the post-residual gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Many alternatives: slight penalty to prefer best fit among several.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // New-bin candidate handling: make it attractive only when open bins are crowded
    // or the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for opening a new bin.
        score += 20.0;
        // If mean residual is high (bins have room), penalize new bins more.
        score += 30.0 * crowding;
        // Early in stream, new bins are cheap; late, prefer consolidating.
        score += 25.0 * (1.0 - progress);
        // If no existing bin fits well (post_residual here = cap - item_size is small
        // only for huge items), large items justify a fresh bin.
        if item_size > 60 {
            score -= 15.0;
        }
        // If the only alternative bins are poor fits, allow opening.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Existing bin: mild reward relative to how full the bin already is.
        let used = (bin_capacity - bin_residual) as f64 / cap;
        score -= 8.0 * used;
    }

    // Global balance: if mean residual is low overall, prefer placements that
    // keep residuals usable (not tiny).
    if (post_residual as f64) < mean_residual * 0.25 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post-residual (tight fit).
    let mut score = pr;

    // Normalized tightness term with polynomial coupling to stream progress.
    let tightness = 1.0 - pr / cap;
    let progress_coupling = (1.0 - progress) * (1.0 - progress);
    score -= 30.0 * tightness * tightness * (1.0 + 1.5 * progress_coupling);

    // Reward near-perfect fills nonlinearly.
    if post_residual <= 3 {
        score -= 40.0;
    }

    // Penalize creating dead space: residual too small for typical future items.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * (10.0 - pr) } else { 0.0 };
    score += 0.5 * dead;

    // Lookahead: bonus if next item exactly fits post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score -= 25.0 * (1.0 - diff / cap).max(0.0);
        // Penalize leaving residual slightly larger than next item (wasted gap).
        if pr > nx && pr - nx < 10.0 {
            score += 0.8 * (pr - nx);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are large.
    if bin_residual == bin_capacity {
        let avg_open = mean_residual;
        let waste_pressure = (avg_open / cap).powf(2.0);
        score += 60.0 * (1.0 - 0.6 * waste_pressure) - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild penalty for scattering across many bins with large mean residual.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by small
    // "denominators" are more reusable by future items.
    let pr = post_residual;
    let mut class_bonus = 0.0f64;
    if pr == 0 {
        class_bonus -= 60.0; // perfect closure
    } else {
        if pr % 10 == 0 { class_bonus -= 8.0; }
        if pr % 20 == 0 { class_bonus -= 5.0; }
        if pr % 25 == 0 { class_bonus -= 4.0; }
        if pr % 50 == 0 { class_bonus -= 6.0; }
        // dead space: tiny unusable leftovers (items >= 1 but typical >= 10)
        if pr < 10 { class_bonus += 12.0 * (10 - pr) as f64; }
        // harmonic bucket: mid-range residuals split into fine classes
        let bucket = pr / 10;
        class_bonus -= 2.0 * ((bucket % 3) as f64); // mild diversity reward
    }
    score += class_bonus;

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 15.0;
        // extra reward if next item closes the bin exactly
        if pr == next_item_size { score -= 20.0; }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot use this residual: penalize proportionally
        score += 3.0 * (next_item_size - pr).min(40) as f64 * 0.25;
    }

    // Tight fit reward: waste ratio (post_residual / capacity) nonlinear penalty
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only good when existing fits are poor.
        // Penalize new bins when many bins fit or fit is decent.
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * (fitting_bins_count.min(10) as f64);
        }
        // Slightly favor new bins late in the stream (less future uncertainty)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
        // If next item is large, a fresh bin is valuable
        if next_item_size >= 60 { score -= 10.0; }
    }

    // Prefer filling bins that are already below mean residual (balance + closure)
    score += 0.5 * ((mean_residual - bin_residual as f64).abs());

    // Many open bins: encourage consolidation into existing bins
    score += 0.3 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A residual is "dead" if it's smaller than the smallest plausible item (1..100 interface).
        // Treat residuals < 10 as fully dead, and 10..30 as partially dead.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 30 {
            score += (30 - post_residual) as f64 * 0.8;
        }
        // Perfect fit bonus: strongly reward zero waste.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Coupling: dead space is worse when the next item could have used it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward when post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual < bin_capacity {
        score -= open_pressure;
    } else {
        // New-bin candidate: apply pressure to discourage opening new bins
        // unless the fit into existing bins is genuinely poor.
        score += open_pressure * 0.5;
    }

    // Mild preference for balancing residual toward the mean when many bins are open.
    if bin_residual < bin_capacity {
        score += ((post_residual as f64 - mean_residual).abs()) * 0.1;
    }

    // Stream progression: early on, be more willing to open new bins (explore);
    // late, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    } else {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect match: next item exactly fills the remaining space -> huge reward.
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Next item also fits here afterwards -> chain placement reward,
        // stronger the tighter the double fit.
        else if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_waste * 0.5;
        }
        // Next item does NOT fit: remaining space becomes dead space for the
        // lookahead horizon -> penalize proportionally to how close we came.
        else {
            let miss_gap = (next_item_size - post_residual) as f64;
            score += miss_gap * 1.5;
        }
    } else {
        // Last item in stream: minimize residual as tightly as possible.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins that are already fuller than
    // average (small residual relative to mean) to consolidate filling.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // perfect two-item packing (perfect lookahead match from full capacity).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 150.0;
        } else {
            score += 80.0;
        }
    }

    // Slight stream-progression pressure: as the stream advances, tighten
    // selection to reduce fragmentation.
    if total_items > 0 {
        score += (step_index as f64 / total_items as f64) * post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize dead space: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 25.0;
            // exact-ish chain fit
            if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            let overshoot = next_item_size as f64 - post_residual as f64;
            score += 5.0 * (overshoot / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));

    // Time horizon: early in stream, be more willing to open new bins / spread;
    // late in stream, pack tightly into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fill_ratio;
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global residual state: if mean residual is high, prefer using this bin to absorb slack
    if mean_residual > post_residual as f64 {
        score -= 3.0 * (mean_residual - post_residual as f64).min(50.0) / 10.0;
    } else {
        score += 2.0 * (post_residual as f64 - mean_residual).min(50.0) / 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score = 35.0 + 40.0 * desperation
            + 20.0 * (1.0 - progress)
            - (if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 20.0 });
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit = item_size as f64 / cap;
    let next_fit = next_item_size as f64 / cap;

    // Base: post residual, with non-linear dead-space penalty
    let mut score = pr + 0.35 * (pr / cap) * pr;

    // Perfect-fit reward (smooth, non-linear)
    score -= 18.0 * (1.0 - (pr / cap).powi(2)) * (1.0 - fit).powi(3);

    // Tight-fit bonus scaled by stream progress (tighten later)
    let tightness = 1.0 - (pr / cap);
    score -= (4.0 + 10.0 * progress) * tightness.powf(1.5);

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let gap = (pr - next_fit * cap) / cap;
        score -= 6.0 * (-gap.abs().powf(2.0)).exp() * (0.5 + 0.5 * progress);
    }

    // Last-chance bin pressure: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many open bins
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * (open_bins_count as f64).powf(0.75) + 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins near the mean (keeps balance)
    score += 0.08 * (pr - mean_residual).abs();

    // Late-stream penalty on large residuals (waste accumulates)
    score += 6.0 * progress * (pr / cap).powf(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic class of dead space

    // Penalize dead space superlinearly, but only for truly small leftovers.
    if post_residual < 10 {
        score -= 50.0; // near-perfect fit, huge reward
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual > 60 {
        score += 10.0; // wasteful large hole
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual < 15 {
        // unusable sliver that blocks the next item: penalize
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless current bin is empty-ish
    // and open bins are numerous (fragmentation risk).
    if bin_residual == bin_capacity {
        // brand-new bin: base cost of a fresh bin
        score += 60.0;
        if open_bins_count == 0 {
            score -= 70.0; // nothing open, must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing large items together in a fresh bin can be good
            score -= 20.0;
        }
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Modulo harmonic bonus: residuals that are multiples of common item classes are reusable.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    }

    // Late in stream, consolidate: favor existing bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can fill are heavily penalized.
    // A residual gap is "unusable" if it's smaller than the smallest item (1) -> never, but
    // practically, gaps below a critical threshold are hard to fill.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // penalize small nonzero gaps quadratically (dead space)
        score += 12.0 * (1.0 / gap.max(1.0)) * 10.0;
        // hard penalty if gap is in the awkward small range (1..=5) that rarely gets filled
        if post_residual <= 5 {
            score += 60.0;
        }
        // reward perfect fit
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty for leaving a gap that blocks lookahead
            score += 5.0;
        }
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins;
    // encourage consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 6.0 * bin_pressure * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins would leave large dead space
        // or no bins exist. Penalize mildly so tight fits in open bins win.
        score += 25.0 + bin_pressure * 8.0;
        // If item is large relative to capacity, new bin is fine (less penalty)
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * frac;
        // If mean residual of open bins is large, open bins can absorb items -> penalize new bin more
        score += (mean_residual / bin_capacity as f64).max(0.0) * 30.0;
    }

    // Mean-residual alignment: prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next item size (perfect two-item packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Strong reward: next item fills the bin completely.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that is too small for the next item
        // (dead space likely).
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: pure waste minimization.
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (best-fit flavor), penalize dumping into loose bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when item is large relative to mean residual or many bins are open.
    if bin_residual == bin_capacity {
        let tight_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual > item_size as f64 * 1.4;
        if tight_fit_exists {
            score += 80.0; // discourage opening new bin when decent fits exist
        } else {
            score -= 5.0; // slight encouragement to spread load
        }
    }

    // Mild pressure to prefer filling nearly-full bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small unusable dead space: post_residual below the minimum item size is wasted.
    let dead = post_residual < item_size.min(20).max(1);
    if dead && post_residual > 0 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty if we leave a very small residual.
            if post_residual < next_item_size && post_residual > 0 {
                score += 5.0;
            }
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit is decent,
    // unless current open bins are all nearly full (mean_residual low).
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count > 0 && mean_residual > (item_size as f64) {
            score += 10.0 * (mean_residual / bin_capacity as f64);
        }
        // Late in the stream, opening fresh bins is less costly (no need to consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    } else {
        // Reward using bins whose residual is close to the item (good fill ratio).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins harder.
    if open_bins_count > 2 {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }

    // Slight bonus for perfectly filling the bin.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let fit_ratio = 1.0 - pr / cap; // how full the bin becomes
    let norm_item = item_size as f64 / cap;
    let norm_next = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    // Reward tight fits with a smooth cubic bonus in fill ratio, modulated by stream progress.
    let fill_bonus = fit_ratio.powi(3) * (18.0 + 10.0 * progress);
    score -= fill_bonus;

    // Penalize dead space quadratically; dead space matters more later in the stream.
    let dead = pr / cap;
    score += dead * dead * (12.0 + 14.0 * progress) * cap;

    // Exact-fit coupling: near-zero residual strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < item_size {
        // residual smaller than the current item is mildly reusable for small items
        score -= 4.0 * (1.0 - pr / (item_size as f64));
    }

    // Lookahead: if the next item fits the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (nxt / cap) * (1.0 + progress);
        } else {
            score += 5.0 * (1.0 - pr / nxt) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: neutral early, penalized when many bins are open
    // and mean residual is high (prefer filling existing bins).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score += 8.0 + 22.0 * crowding * (0.3 + 0.7 * (mean_residual / cap).min(1.0));
        // But if item is huge and nothing fits well, opening a new bin is fine.
        score -= 12.0 * norm_item * norm_item * (1.0 - progress);
    }

    // Smooth non-linear coupling of residual with mean residual across open bins:
    // prefer bins whose residual is close to the mean (keeps bin portfolio balanced).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer-division thresholds (capacity / k)
    let pr = post_residual as u32;
    let class = if pr == 0 { 0 }
        else if pr <= bin_capacity / 8 { 1 }
        else if pr <= bin_capacity / 4 { 2 }
        else if pr <= bin_capacity / 2 { 3 }
        else { 4 };
    // Deeper class (smaller residual) is better: subtract reward
    score -= (4 - class) as f64 * 6.0;

    // Modulo arithmetic on residual: residuals near multiples of 10 are reusable
    let mod10 = pr % 10;
    if pr > 0 {
        score -= 4.0 - (mod10 as f64 - 5.0).abs() * 0.6;
    }

    // Lookahead coupling: does post_residual fit next item exactly / well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_fit = pr - next_item_size;
            // exact fit for next item is gold
            if next_fit == 0 { score -= 15.0; }
            else if next_fit <= bin_capacity / 8 { score -= 8.0; }
            else { score -= 2.0; }
        } else {
            // next item cannot use this residual: penalize dead space proportionally
            score += (next_item_size as f64 - pr as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer filling already-open bins when many are open (avoid bin proliferation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // New-bin candidate: empty bin gets a mild penalty so we reuse when fit is decent,
    // but bonus if item is large (harmonic class 4 item wastes little)
    if bin_residual == bin_capacity {
        score += 10.0 - (item_size as f64 / cap) * 8.0;
    }

    // Tightness reward: fraction of bin consumed by this placement
    score -= (item_size as f64 / cap) * 5.0;

    // Slight pull toward mean residual to keep balance across bins
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the minimum
    // item (<= 1) are pure waste; penalize small unusable gaps super-linearly.
    if post_residual > 0 {
        // tightness reward: exact or near-exact fills
        if post_residual == 0 {
            score -= 50.0;
        } else {
            // penalize gaps that are too small to be useful later
            if post_residual < 10 {
                score += (10 - post_residual) as f64 * 3.0;
            }
            // reward leaving gaps that exactly fit a plausible next item
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 25.0;
            } else if next_item_size > 0 && post_residual >= next_item_size {
                score -= 5.0;
            }
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New-bin candidate handling: empty bin should only win when the fit into
    // existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, modulated by how scattered
        // current residuals are (mean_residual far from item => poor fits exist)
        score += 20.0 + mean_residual * 0.1;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin leaves room for large follow-up items
        }
    } else {
        // prefer bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.3;
        // reward bins with residual near mean (keeps residual distribution balanced)
        score += (mean_residual - bin_residual as f64).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact or near-exact fit reward: squashed post-residual.
    score -= 12.0 * (-post_residual as f64 / 6.0).exp();

    // 2-step lookahead: reward bins where the next item could also fit the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement, scaled by how snugly the next item fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * snug;
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins whose residual is already far below the mean (well-filled bins
    // are precious; prefer dumping items into high-residual bins).
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (mean_residual - resid).max(0.0);
    }

    // Prefer keeping the number of open bins low when many are already open.
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 * 0.9;
        if decent_fit_exists || fitting_bins_count > 0 {
            score += 10.0; // discourage opening new bin when fits exist
        } else {
            score -= 5.0; // encourage new bin when nothing fits well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small waste) with a non-linear discount.
    if post_residual <= 5 {
        score -= 25.0 * (6.0 - post_residual as f64);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    }

    // Lookahead: penalize leaving a residual that the next item would
    // almost but not quite fill, reward residuals the next item fits.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            // next item can still go here: residual is valuable
            score -= 8.0 * (1.0 - nx / (pr + 1.0));
        } else {
            // dead space relative to lookahead: penalize proportionally
            score += 4.0 * (nx - pr).min(30.0) / 30.0 * (pr / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // mild preference against opening bins early when mean residual is large
        score += 10.0 + mean_residual * 0.15 - 5.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    let pressure = mean_residual / bin_capacity as f64;
    score -= 6.0 * pressure * (open_bins_count as f64).ln().max(1.0);

    // Small tie-breaker toward tighter residual relative to capacity.
    score += 0.05 * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: dead space becomes more costly as stream progresses
    let dead_space_penalty = pr * pr * (0.5 + 2.5 * progress) * bin_capacity as f64;
    score += dead_space_penalty;

    // Cubic term: strongly penalize mid-range wasted space late in the stream
    score += pr * pr * pr * (1.0 + 3.0 * progress) * bin_capacity as f64 * 0.5;

    // Reward tight fits (small post_residual) with a smooth exponential bonus
    let tightness = (-pr * 6.0).exp();
    score -= tightness * (2.0 + 3.0 * progress);

    // Lookahead: reward bins whose post residual accommodates the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= (1.0 - gap) * (1.0 + progress) * 3.0;
    } else if next_item_size > 0 {
        // Penalize leaving a residual too small for the next item (dead space)
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more strongly early and when open bins exist
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln_1p();
        score += 12.0 + 8.0 * (1.0 - progress) + open_pressure;
    } else {
        // Slight preference for bins with residuals near the item (best-fit style)
        let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += fit_gap * 2.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (consolidating small residuals)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * (1.0 + progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic dead-space classes: residuals that can never fit another
    // minimum item are wasted; classify by integer division thresholds.
    let dead = post_residual < 10; // assuming min item ~10, but sizes may go to 1
    if dead {
        score += 60.0;
    }

    // Modulo arithmetic on post_residual: residuals in classes matching
    // common item sizes (multiples of 5 / 10) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else {
            score += 8.0;
        }
        // Odd small residuals are the worst dead space.
        if pr < 20 && pr % 2 == 1 {
            score += 15.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 20.0;
        if next_item_size == pr {
            score -= 80.0;
        }
        // Harmonic class match: next item aligns with residual class.
        if pr % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin: mild penalty for wasting the slot.
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate calibration: opening a new bin is a fallback —
    // it should lose to good fits but beat poor fits with dead space.
    if is_new_bin {
        score = 55.0
            + 0.3 * (open_bins_count as f64)
            - 0.2 * mean_residual
            + 0.1 * (item_size as f64);
        // Late in the stream, consolidate more aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin still useful for lookahead
        }
    }

    // Prefer filling fuller bins overall (residual tightness).
    score += 0.15 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Slight preference for bins whose residual is near the mean
    // (keeps the pool homogeneous for future items).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps are nearly unusable (items >= 10 normally).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits strongly.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill * fill;

    // If the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the gap -> mild penalty for leaving large-ish gap
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward closing the bin completely.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the residual left behind exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // leftover after the next placement would be post_residual - next_item_size
            let after_next = (post_residual - next_item_size) as f64;
            score += after_next * 0.35;
            if after_next < 10.0 {
                score -= 25.0; // near-perfect two-item chain
            }
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Dead-space penalty for very small unusable residuals relative to item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate calibration: an empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin gives more room
        }
    }

    // Slight preference for bins with less residual among comparable options.
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets an extra bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that cannot fit the smallest plausible item (<= residual)
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny useless sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // New-bin candidate handling: prefer open bins unless residuals are large
    if bin_residual == bin_capacity {
        // New bin: attractive if open bins are fragmented, less so early on
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 35.0 - 20.0 * fragmentation - 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
    } else {
        // Favor bins whose residual is close to the item (best-fit character)
        let gap = (bin_residual - item_size) as f64;
        score += 0.05 * gap;
        // Favor bins below mean residual (consolidate fullness)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Mild pressure to close bins as stream matures
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: strongly prefer tight fits (amplify residual differences).
    // Late in the stream: moderate, since fewer placements remain to exploit tightness.
    let tightness = (pr / cap).powf(2.0);
    let progress_weight = 1.0 + 2.0 * (1.0 - t) * t; // peaks mid-stream
    score += 8.0 * tightness * progress_weight;

    // Reward filling a bin nearly completely, more so early on.
    let fill = 1.0 - pr / cap;
    score -= 6.0 * fill * fill * (1.0 - t);

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize crowding relative to mean residual (avoid dumping into already-full bins).
    score += 0.3 * (pr - mean_residual);

    // Lookahead coupling: penalize if post_residual cannot fit the next item
    // (wasted residual), reward if it exactly accommodates it.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 4.0 * (1.0 - ((pr - n) / cap).powf(2.0));
        } else {
            score += 5.0 * (1.0 - pr / n);
        }
    }

    // New-bin candidate: penalize opening a new bin unless residuals are large.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item sizes are more reusable; odd "dead" residues are penalized.
    let post = post_residual;
    let class_penalty = match post {
        0 => -30.0,                                // perfect fit: best outcome
        1..=9 => 25.0,                             // unusable sliver
        _ => 0.0,
    };
    score += class_penalty;

    // Modulo-based reusability: residual divisible by 10 or 25 is attractive.
    if post > 0 && (post % 10 == 0 || post % 25 == 0) {
        score -= 6.0;
    }
    // Residuals in awkward mid-band (11..19) tend to be dead space.
    if post >= 11 && post <= 19 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly or well into post_residual,
    // reward; if next item almost fits (miss by <=5), penalize strongly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) <= post {
            let slack = (post as f64 - n) / cap;
            score -= 10.0 * (1.0 - slack);         // perfect chaining bonus
        } else if next_item_size as u32 - post <= 5 {
            score += 12.0;                          // near-miss: wasted slot
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when all open
    // fits are bad. Penalize the fresh bin, scaled by how many bins fit.
    if bin_residual == bin_capacity {
        let base = 20.0;
        let crowd = (open_bins_count.max(1) as f64).ln() * 3.0;
        score += base + crowd;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Prefer filling bins below mean residual (balancing keeps large gaps
    // consolidated in fewer bins).
    score += 0.15 * ((post as f64) - mean_residual);

    // Slight preference early in the stream to consolidate into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=12) are nearly unusable
    // for future items (sizes >= 1 but typically chunky), so penalize hard.
    if post_residual >= 1 && post_residual <= 12 {
        score += 45.0 - 3.0 * post_residual as f64;
    } else if post_residual >= 13 && post_residual <= 20 {
        score += 8.0; // marginal dead space
    }

    // Perfect fit: strongly reward leaving exactly zero residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual is "well matched" to the item (low waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> favor compacting into existing bins
    // to avoid fragmentation; few open bins -> new bins are cheap.
    let pressure = (open_bins_count as f64).ln() * 6.0;
    score -= pressure * (1.0 - waste_frac);

    // Lookahead: if the next item fits into the post-residual, reward this placement
    // (creates a useful chain); otherwise mild penalty for blocking the next item.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
        } else if post_residual > 0 && (post_residual as i64) < (next_item_size as i64) {
            score += 5.0;
        }
    }

    // Stream progression: early on, be more willing to open new bins (future unknown);
    // later, pack tighter into what exists.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // Mean-residual coupling: if the average residual across open bins is high,
    // there is slack elsewhere; be pickier about this bin's fit.
    score += 0.15 * mean_residual * waste_frac;

    // New-bin candidate: only attractive when the item would leave large dead space
    // in every existing bin, or few bins are open.
    if bin_residual == bin_capacity {
        let dead_elsewhere = if fitting_bins_count > 0 { waste_frac } else { 1.0 };
        score = 55.0 - 40.0 * dead_elsewhere - 15.0 * (1.0 - progress)
            - (open_bins_count as f64).ln().max(0.0) * 2.0;
        // never allow new bin to win on a perfect fit elsewhere
        if post_residual == 0 { score += 1000.0; } // unreachable for new bin; guard
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // exact match bonus
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // closer post_residual to next item => better; scale by next size
            let next = next_item_size as f64;
            score -= (next / diff) * 8.0;
            // if next item cannot fit here, mild penalty relative to next size
            if post_residual < next_item_size {
                score += 6.0 + next * 0.05;
            }
        }
    } else {
        // last item: reward small post_residual more aggressively
        score -= (bin_capacity as f64 - post_residual as f64) * 0.15;
    }

    // Favor bins whose residual is below mean (tight bins) for big items
    let m = mean_residual;
    if (post_residual as f64) < m {
        score -= 3.0;
    } else {
        score += 0.05 * (post_residual as f64 - m);
    }

    // Last-chance bin: strong preference to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins generally, but less when
    // no good fit exists (post_residual would be tiny dead space in this bin)
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        // penalize new bin, but relax penalty if this bin would leave unusable space
        score += 30.0 - (dead / bin_capacity as f64) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin accommodates lookahead well
        }
    }

    // Early in stream: allow more bins (exploration); late: pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Non-linear penalty on large unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // tiny leftover is fine (dead space minimal)
    } else if post_residual >= 10 {
        score += 0.08 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Prefer filling bins that are already relatively full (below mean residual).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Penalize spreading across too many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * progress;

    // Early in the stream, opening new bins is cheap; late, avoid it.
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, with non-linear shrink of large residuals
    let mut score = pr - 18.0 * (norm_pr * (1.0 - norm_pr)) * (1.0 + progress);

    // Polynomial coupling: penalize residual that is small but not zero (dead space),
    // reward near-zero residuals more as stream progresses
    let dead = (norm_pr * (1.0 - norm_pr)).powi(2);
    score += 25.0 * dead * (0.5 + progress);

    // Lookahead coupling: reward if next item fits post residual (smooth)
    if next_item_size > 0 {
        let fits = ((pr - norm_next * cap).abs() / cap).min(1.0);
        let next_fit_bonus = (1.0 - fits).powi(3);
        score -= 12.0 * next_fit_bonus * (1.0 - progress);
        // penalize wasting space if next item is large and this bin was its only chance
        if norm_next > norm_pr {
            score += 8.0 * (norm_next - norm_pr) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // Prefer bins with residual below mean (tighter bins first)
    score += (mean_residual - pr) * 0.15;

    // Mild pressure to open new bins early (keep open bins tight), less late
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 3.0;

    // New-bin candidate handling: make it attractive only when item is large
    if bin_residual == bin_capacity {
        score -= 30.0 * norm_item * (1.0 - progress);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: bucket post_residual by divisibility relative to capacity
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Dead-space penalty for large residuals that are hard to fill
    if post_residual > 0 {
        // penalize residuals in awkward harmonic classes
        if post_residual % 10 == 0 {
            score -= 5.0; // round residuals pair well with round item sizes
        }
        if post_residual < 10 {
            score -= 30.0; // nearly-full bin: good
        } else if frac > 0.5 {
            score += 10.0 * frac; // large leftover space: mild penalty
        }
    }

    // Lookahead: strongly reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // penalty scaled by how much the next item would waste
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(cap * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 60.0 + 0.3 * open_bins_count as f64;
        // but if next item is large, a fresh bin is attractive
        if next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (tiny gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    } else {
        // Larger usable gaps get a mild reward scaled by usefulness.
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits: item filling most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // If several bins fit, prefer ones whose post_residual can host the
    // lookahead item (k=2 lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 40.0 * progress);
    score += 6.0 * pressure * (mean_residual / bin_capacity as f64);

    // New empty bin candidate: neutral base plus pressure cost; only chosen
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 8.0 * pressure;
        // If it's the last chance anyway, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item fits into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Penalize dead space: post_residual too small for typical items (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual across open bins: prefer bins whose post residual
    // is below the mean (tight packing), reward relative tightness
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive only
    // when no open bin offers a good fit (post residual close to next item size)
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            // perfect chain start for the new bin
            score -= 500.0;
        } else {
            // discourage opening new bins when existing bins fit reasonably
            score += 150.0;
        }
    }

    // Mild preference for filling high-residual bins early in the stream
    let progress = step_index as f64 / total_items as f64;
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0 * (1.0 - progress);

    // Prefer bins with larger residuals relative to item size (safe fit)
    score -= (bin_residual as f64 - item_size as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for any plausible future item (min size 1..~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 14.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual unusable for the next item: mild penalty scaled by progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (0.5 + progress);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean_residual elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 40.0;
        // Cheaper to open a new bin when open bins are already tight (low mean residual)
        // or when few bins can fit the item.
        let avg_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 45.0 * avg_tight;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            score += 8.0; // prefer using the single fitting bin
        }
        // Late in the stream, consolidating is cheaper than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins with slack: opening new bins is wasteful.
        if open_bins_count > 4 && mean_residual > item_size as f64 * 2.0 {
            score += 15.0;
        }
    } else {
        // Mild preference for bins with residual close to item (best-fit flavor),
        // modulated by global mean residual.
        let over = (bin_residual as f64 - item_size as f64).abs();
        score += 0.08 * over;
        // Prefer filling bins whose residual deviates most from the mean (balance residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 20.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual too small for typical future items
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Smooth coupling with stream progress: early on, prefer filling open bins;
    // late, tolerate slightly looser fits to avoid opening bins
    let progress_coupling = (0.5 * (1.0 - (std::f64::consts::PI * progress).cos())) * 18.0;
    score -= progress_coupling * (1.0 - norm_pr);

    // Penalize opening new bins when open bins have slack
    if bin_residual == bin_capacity {
        let slack = (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 + 25.0 * slack + 10.0 * (1.0 - progress);
        if next_item_size as f64 > item + pr + 1.0 {
            score -= 5.0;
        }
    }

    // Slight preference for bins below mean residual (balance spreading)
    score += 4.0 * ((pr - mean_residual) / cap).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10 and mod 25.
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;

    // Dead-space penalty: tiny residuals (< 10, min item size) are unusable.
    if post_residual < 10 {
        score += 40.0;
    } else {
        // Reward residuals that are "harmonically aligned" (divisible by common item sizes).
        if mod10 == 0 { score -= 8.0; }
        if mod25 == 0 { score -= 12.0; }
        if post_residual % 20 == 0 { score -= 5.0; }
        if post_residual % 50 == 0 { score -= 10.0; }
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 10; // 0..10 classes
    score += match class {
        0 => 30.0,
        1 => 15.0,
        2 => 5.0,
        3 => 0.0,
        4 => -3.0,
        5 => -5.0,
        _ => -6.0,
    };

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // Reward proportionally: small leftover after next item too.
            let post2 = post_residual - next_item_size;
            score -= (post2 as f64) * 0.3;
            if post2 < 10 { score += 20.0; } // would create dead space
        } else {
            // Next item won't fit here; penalize slightly to prefer bins where chain continues.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly; escalate if open bins are already fragmented.
        score += 20.0 + 15.0 * (1.0 - progress);
        if mean_residual > (item_size as f64) + 5.0 {
            score += 25.0; // existing bins have room; avoid opening new
        }
        if post_residual == 0 { score -= 5.0; }
    }

    // Congestion: many open bins -> prefer tightening existing ones.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item are pure waste. Penalize them quadratically.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        let gap = (dead_threshold - post_residual) as f64;
        score += 60.0 + gap * gap * 2.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item if it fits after placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (next_item_size as f64) * 0.15;
        } else {
            // If next item cannot fit anywhere else, prefer keeping this bin usable.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into bins with large residuals; prefer filling tighter ones.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += (post_residual as f64 - mean_residual) * 0.05 * pressure;

    // New-bin candidate: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let best_alternative = mean_residual;
        // Opening is penalized mildly; becomes attractive only if open bins
        // would leave large dead space relative to item size.
        let waste_if_forced = (bin_capacity.min(100) as f64) - (item_size as f64);
        let dead_elsewhere = (best_alternative - item_size as f64).max(0.0);
        score += 35.0 + pressure * 4.0 - dead_elsewhere * 0.8 + waste_if_forced * 0.1;
    }

    // Late-stream tightening: as the stream progresses, be greedier about
    // avoiding residual waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain completion
        } else if next_item_size < post_residual {
            // next item fits, but penalize leftover dead space after the chain
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
            if after_next == 0 { score -= 100.0; }
        } else {
            // next item cannot use the residual: dead space penalty
            score += (post_residual as f64) * 0.5;
        }
    }

    // Small unusable residuals (< min plausible item) are dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Reward packing into bins tighter than the current mean residual
    // (i.e. bins that are relatively full already).
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        score -= (mean_post - post_residual as f64) * 0.4;
    }

    // New-bin candidate handling: only attractive when existing bins would leave
    // large dead space, or when many bins are open and residual is tiny.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, scaled by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 80.0 * progress;
        // opening a new bin is better if the item would leave a small residual
        // in an existing bin (post_residual small => new bin relatively good)
        score -= (post_residual as f64) * 1.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0; // new bin leaves room for lookahead item
        }
    }

    // Slight preference to fill bins with larger items first when residuals equal.
    score -= (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small residual is wasted space unless it matches small future items
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 15.0; // dead space relative to lookahead
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer filling fuller bins (tight fit) — penalize loose fits
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Penalize opening a new bin early in the stream, allow it later
    if bin_residual == bin_capacity {
        score += 40.0 - 30.0 * t;
        // If open bins are mostly empty, new bin is fine
        if mean_residual > 60.0 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Slight preference for bins with below-average residual (keep spread)
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Late in stream: consolidate aggressively
    if t > 0.8 {
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, larger residuals are tolerable; late in the stream, dead space is costly.
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // peaks at mid residuals
    score += poly * cap * (0.5 + progress) * 0.8;

    // Reward filling a bin nearly completely, more so as stream progresses.
    let fill = (item_size as f64) / cap;
    score -= fill * fill * (1.0 + progress) * 6.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    } else {
        // Small penalty spread when many bins fit (favor concentration).
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // Lookahead: reward residual that can still fit the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            let fit_quality = 1.0 - (gap / cap);
            score -= fit_quality * fit_quality * 3.0 * (1.0 - progress);
        } else {
            // Residual cannot fit next item: penalize proportionally to wasted potential.
            score += (n - pr) / cap * 2.0 * (1.0 - progress);
        }
    }

    // Penalize opening new bins when open bins have plenty of room, smoothly.
    let mean_gap = mean_residual - pr;
    if mean_gap > 0.0 {
        score += (mean_gap / cap) * (open_bins_count as f64).sqrt() * 1.5;
    }

    // Smooth progress-driven tightness pressure: later items should pack tighter.
    score += prn * progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (e.g. multiples of 10, 25, 50) remain usable; odd/prime-ish residues are dead space.
    let pr = post_residual;
    let mut dead_penalty = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { dead_penalty -= 6.0; }
        if pr % 25 == 0 { dead_penalty -= 4.0; }
        if pr % 50 == 0 { dead_penalty -= 3.0; }
        if pr < 10 { dead_penalty += 12.0; } // unusable sliver
        else if pr < 20 { dead_penalty += 4.0; }
        if pr % 2 == 1 { dead_penalty += 1.5; } // odd residue less reusable
    }
    score += dead_penalty;

    // Lookahead coupling: does next item fit into post_residual exactly / at all?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // chains perfectly
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            if leftover % 10 == 0 || leftover == 0 {
                score -= 20.0;
            }
            score += (leftover as f64) * 0.3;
        } else {
            score += 8.0; // next item won't fit here; mild penalty for wasting the slot
        }
    }

    // Tightness reward: reward filling a large fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad
    // and there are many open bins already.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        let bad_fit = if post_residual < 10 { 20.0 } else { 0.0 };
        score += 30.0 - pressure - bad_fit;
    }

    // Prefer bins below mean residual (fill emptier bins less, keep tight bins tight? inverse):
    // favor bins with residual close to item (good fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.1;

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A post_residual below the smallest plausible item (<= 10) is pure dead space.
    if post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 45.0;
    } else if post_residual < 30 {
        score += 12.0;
    } else {
        // Larger usable gaps are mildly rewarded relative to baseline.
        score -= 4.0;
    }

    // Perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact match with the lookahead item: reserve this gap for it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // Dead-space coupling: small gap that cannot host the next item is doubly bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoids opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has high residual; keep it attractive
    // only when the current bin fit is poor (large post_residual).
    if bin_residual == bin_capacity {
        // Baseline competitiveness: prefer a new bin over leaving >40 dead space.
        score = 55.0 - pressure * 3.0;
        // If the item fits almost perfectly elsewhere, opening a new bin is wasteful.
        if post_residual == 0 { /* not applicable for empty bin, but keep symmetry */ }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is a good home for a large upcoming item.
            score -= 5.0;
        }
    }

    // Late-stream tightening: as the stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual anchoring: prefer bins whose residual is below average
    // (fills the fullest bins first, keeping large gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual as u32 > next_item_size {
            // next item fits: better if the leftover after next is small
            let after_next = post_residual as f64 - nxt;
            score -= 30.0 * (1.0 - after_next / bin_capacity as f64);
            // penalize leaving a sliver after next item (dead space)
            if after_next < 10.0 {
                score += 12.0 * (10.0 - after_next);
            }
        } else {
            // next item will NOT fit here: penalize proportionally to the shortfall
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins whose post_residual sits near mean_residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize large post_residual (wasteful fit) especially when many bins are open
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste * waste * (1.0 + open_bins_count as f64 / 10.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let tight_fit_exists = fitting_bins_count > 0 && (post_residual as f64) < mean_residual;
        if tight_fit_exists {
            score += 35.0; // keep using existing bins
        } else {
            score -= 8.0; // opening a fresh bin is reasonable
        }
        // early stream: opening bins is cheap
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Tight fit reward: small post_residual overall
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
