pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Core: post-residual with non-linear shaping (favor small post residuals strongly)
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Coupling: post-residual vs next item lookahead — reward residuals that can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 12.0 * snug * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize residuals that waste space relative to lookahead
        score += 4.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Stream-progress coupling: later in stream, be stricter about dead space
    score += 10.0 * progress * norm_pr * (1.0 - norm_pr);

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Many open bins: mild penalty to avoid bin proliferation
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Mean-residual coupling: prefer bins deviating below mean residual (tighter packs)
    score += 2.0 * (pr - mean_residual) / cap;

    // New-bin candidate: neutral-ish baseline, penalized when decent fits exist
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Residuals in "useful" classes (small, or
    // large enough to hold typical future items) are rewarded.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes 0..=10
    let class_reward: f64 = match class {
        0 => 18.0,                 // near-perfect fit
        1 => 12.0,
        2 => 6.0,
        3 => 1.0,
        4 => -2.0,                 // awkward mid-range dead space
        5 => -4.0,
        6 => -3.0,
        7 => 2.0,                  // big enough for many item sizes
        8 => 4.0,
        9 => 5.0,
        _ => 6.0,                  // nearly empty bin, still flexible
    };
    score -= class_reward;

    // Modulo coupling: residuals that are multiples of common item sizes
    // (10/20/25/50) tend to be fillable later.
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 2.0; }
    }

    // Lookahead: strongly reward if the next item fits the post-residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n as u32) <= pr {
            score -= 10.0 + 0.3 * (pr as f64 - n);
        } else {
            // penalize leaving a residual the next item cannot use
            score += 4.0 + 0.1 * (n - pr as f64);
        }
        // perfect pairing: post_residual exactly equals next item
        if next_item_size == pr { score -= 8.0; }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening fresh bins is expensive early,
    // cheaper late in the stream or when many bins are open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let slack = mean_residual / cap;
        let pressure = open_bins_count as f64;
        score += 20.0 - 12.0 * progress - 8.0 * slack.min(1.0) - 0.4 * pressure.min(20.0);
    } else {
        // prefer tighter (fuller) bins among open ones
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 6.0 * tightness;
        // mild preference to keep open-bin count low
        score += 0.05 * open_bins_count as f64;
    }

    // Mean-residual coupling: if open bins are generally tight, favor using
    // this bin more aggressively (subtract more).
    score -= 0.05 * (cap - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Reward bins whose residual was already small (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.7 * progress);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would be blocked by a small dead gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate baseline: opening a new bin is a fallback unless
    // existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 1.5;
        // If nothing else fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here: moderately good
            score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize dead space creation
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 + 100.0 * (1.0 - progress);
    }

    // Prefer consolidating into fewer open bins
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post-residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item still fits here: mild reward proportional to how well it packs.
            let second_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * (1.0 - second_tight);
        } else {
            // Next item would not fit here: penalize bins whose residual is small but unusable.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += dead * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large and no
    // open bin offers a decent fit. Compare against mean residual of open bins.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // Opening new bins early is costly; later in the stream it matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 70.0 + open_pressure * 3.0;
        // If open bins are generally too full (small mean residual), new bin is more acceptable.
        let relief = (mean_residual / bin_capacity as f64) * 40.0;
        score += base_penalty - relief - mean_gap * 0.2 - progress * 15.0;
    } else {
        // Favor bins with residual close to item size (best-fit style).
        let gap = (bin_residual as f64 - item_size as f64).max(0.0);
        score += gap * 0.25;
        // Mildly prefer using bins that are already quite full (low residual).
        score += (bin_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Time-horizon coupling: late in the stream, minimize spread of residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread = (mean_residual - post_residual as f64).abs();
    score += spread * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    // Smooth polynomial coupling: tight fits are rewarded more as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);
    // Penalize large dead space non-linearly, stronger late in stream
    score += 6.0 * norm_post * norm_post * (0.5 + 0.5 * progress);
    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }
    // Lookahead: reward if next item can fit into post-residual
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 4.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 2.0 * progress * (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
    }
    // Mild preference to fill bins with small residuals relative to mean
    score += 1.5 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    // New-bin candidate: penalize opening a new bin unless existing bins are very full
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (1.0 + progress * 10.0);
        score += 5.0 + openness;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead" (too small
    // for typical items) are heavily penalized. Class by modulo 10 bands.
    let r = post_residual as f64;
    let m10 = (post_residual % 10) as f64;
    let q10 = (post_residual / 10) as f64;

    // Dead-space penalty: residual below 10 is pure waste.
    if post_residual < 10 {
        score += 40.0 + (10.0 - r) * 3.0;
    } else if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Reward post_residuals that sit in reusable harmonic classes
        // (multiples of 10 and 5 are friendlier for integer item sizes).
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 5 == 0 { score -= 5.0; }
        // Odd, prime-ish residues are harder to fill later.
        if post_residual % 2 == 1 { score += 3.0 + m10 * 0.2; }
        // Small-but-usable residual sweet spot: 10..=20
        if post_residual <= 20 { score -= 8.0; }
        // Large residual left behind means we wasted a big bin region.
        score += q10 * q10 * 0.15;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            score -= 15.0 - (chain_left as f64) * 0.3;
            if chain_left == 0 { score -= 20.0; }
            if chain_left < 10 { score += 10.0; } // creates new dead space
        } else {
            // next item cannot use the residual at all
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are mostly full or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_open = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // Penalize new bins generally; relax when mean residual is low.
        score += 30.0 + tight_open * 5.0 - progress * 10.0;
        if item_size >= 50 { score -= 15.0; }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 > bin_capacity as f64 {
            score -= 10.0; // big pair: fresh bin is fine
        }
    }

    // Prefer filling bins below the mean residual (consolidate waste).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Mild preference for keeping few open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100 unknown,
    // but typical small) can efficiently use are heavily penalized.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Tiny unusable gap: dead space. Penalize hard (worse than a mid-size gap).
        score += 60.0;
    } else if post_residual <= 20 {
        // Moderately awkward gap.
        score += 15.0;
    } else if post_residual <= 50 {
        // Usable gap for typical items.
        score -= 10.0;
    } else {
        // Large residual: very flexible, reward.
        score -= 25.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or the current fit would create dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Pressure from many open bins makes a fresh bin less attractive.
        score += 4.0 * open_bins_count as f64;
        // If this placement would leave a bad gap, opening a new bin is preferred.
        if post_residual < 10 && bin_residual != bin_capacity {
            score -= 100.0;
        }
        // Lookahead: if next item is large and current fit is poor, new bin helps.
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins when open-bin count is low (amortization).
        score -= 2.0 * open_bins_count as f64;
        // Lookahead synergy: if next item fits exactly into post_residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Stream progression: later in the stream, be more conservative about
    // opening new bins (less future to amortize) -> favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 15.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score -= 0.5 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: the less dead space left, the better.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: strongly reward when the next item
    // exactly fills the post residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well the next item fits the leftover.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * fill_ratio;
            // Extra bonus if the chain leaves a tiny residual again.
            let second_left = post_residual as i64 - next_item_size as i64;
            if second_left >= 0 && second_left <= 5 {
                score -= 150.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers
            // relative to the lookahead, scaled by how tight the fit was.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.5 * waste.min(50.0);
        }
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins that are already below-average full (larger residual),
    // keeping tight bins for future tight fits... but if this bin is much
    // looser than average, prefer consolidating here.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.15 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no open
    // bin offers a good fit, i.e., when the item is large relative to
    // typical residuals or many bins are open and fragmented.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Default: slightly unattractive so existing bins are preferred.
        let mut new_bin_score = 60.0 + 0.5 * open_pressure;
        // If the item barely fits anywhere (post_residual small on empty bin
        // means a huge item), a fresh bin is often best.
        if item_size >= 60 {
            new_bin_score -= 70.0;
        }
        // If mean residual is small (bins are nearly full), opening fresh
        // space is valuable.
        if mean_residual < item_size as f64 {
            new_bin_score -= 80.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += 40.0 * progress;
        score = new_bin_score;
    }

    // Mild preference to keep the number of open bins bounded.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: tiny leftover that likely can't host future items (items >= 10 typically, but be safe for 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.10 * next_item_size as f64;
        } else {
            score += 6.0 + 0.05 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Tightness reward: larger item fill fraction lowers score (better packing).
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Prefer bins whose residual deviates favorably from the mean: bins tighter
    // than average get a small nudge to be filled first.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: add a barrier so existing bins are preferred unless
    // all fits are poor. Barrier shrinks late in the stream (consolidation phase).
    if is_new_bin {
        score += 45.0 - 12.0 * progress;
        // Opening a bin for a large item is fine; small items into new bins are wasteful.
        score += (80 - item_size.min(80)) as f64 * 0.15;
    }

    // Mild penalty for having many open bins already: encourage closing bins out.
    if !is_new_bin {
        score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize post residual and stream progress
    let pr = post_residual as f64 / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear penalty on residual: small residuals are valuable (tight fits)
    score -= (1.0 - pr) * (1.0 - pr) * 8.0;

    // Smooth interaction: tight fits matter more later in the stream
    score -= progress * (1.0 - pr) * 6.0;

    // Penalize medium "dead zone" residuals via smooth bump (quartic around 0.5)
    let bump = 16.0 * pr * (1.0 - pr);
    score += bump * bump * 4.0;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, less when current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = pr; // pr == 1.0 for empty bin, use item-based measure instead
        let fill = item_size as f64 / cap;
        let _ = poor_fit;
        // Reward opening a new bin only if the item is large (would leave big dead space elsewhere)
        score += 10.0 - fill * 12.0;
        // Lookahead: if next item fits the leftover of a normal placement, discourage new bin
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let left_after = (bin_residual - item_size) as f64;
            if left_after >= nxt {
                score += 6.0;
            } else {
                score -= 4.0;
            }
        }
    } else if next_item_size > 0 {
        // Lookahead synergy: if next item exactly fills this bin's post residual
        let nxt = next_item_size as f64;
        let left = post_residual as f64;
        if nxt <= left {
            let synergy = 1.0 - (left - nxt).abs() / cap;
            score -= synergy * synergy * 10.0;
        } else {
            // next item won't fit here: slight penalty proportional to waste
            score += (nxt - left) / cap * 3.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter)
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += dev * 5.0;

    // Slight preference for fewer open bins when fits are plentiful
    if fitting_bins_count > 3 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residuals that are "usable" residue classes
    // (multiples of common item-size granularities 10/20/25/50 leave reusable space).
    let pr = post_residual as u32;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly favored
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: tiny unusable leftovers (below smallest plausible item).
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits but imperfectly: mild reward scaled by fit tightness
            score -= 8.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here: penalize small residuals slightly
            score += 3.0 * (1.0 - pr as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins give bad fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // cheaper to open a new bin early in the stream or when bins are congested
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // if item is large relative to capacity, a fresh bin is attractive
        score -= 10.0 * (item_size as f64 / cap);
        // if next item is large and current bins are tight, favor new bin
        if next_item_size > 60 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // if this is the only fitting option at all, new bin is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Prefer bins whose residual is closest to the item (tight fit) beyond raw post_residual:
        // amplify discrimination among candidates with similar post_residuals.
        score += 0.5 * (bin_residual as f64 / cap);
        // Penalize spreading across too many bins when mean residual is already low.
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small leftover gaps are nearly unusable
    // (items >= 10 in the classic case, but sizes unknown => treat gaps
    // below a soft threshold as wasted). Penalize super-linearly.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits generally: residual close to item usage.
    score -= (bin_residual as f64 - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer reusing open bins while they have room;
    // only open a new bin when open bins are very full (mean residual low)
    // or many bins are open (pressure to consolidate is wrong way — instead
    // penalize new bins when few bins open).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 60.0;
        // If mean residual across open bins is small, open bins are nearly
        // full, so a new bin becomes attractive.
        score -= mean_residual * 0.8;
        // If the next item would fit in the post-residual of this fresh bin,
        // a new bin gives flexibility.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    } else {
        // Reward placing into bins whose residual is close to item size
        // (best-fit reinforcement), scaled by how many alternatives exist.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 10.0;
        // If next item fits exactly in the post residual, strong bonus.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // next item can't use the leftover: leftover likely dead space
            score += (post_residual as f64) * 0.3;
        }
    }

    // Mild open-bins pressure: with many open bins, favor consolidation
    // into existing bins (penalize new bins implicitly done above); also
    // slightly favor bins with below-average residual (fuller bins).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    if bin_residual != bin_capacity {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item can fit into post_residual,
    // this bin is doubly valuable — reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 90.0 + (next_item_size as f64) * 0.5;
        }
        // Penalize leaving residual that is *almost* but not quite big
        // enough for the next item (dead space trap).
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && gap > -10.0 {
            score += 40.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit behavior), penalize dipping into the emptiest bins.
    if (bin_residual as f64) > mean_residual + 30.0 {
        score += 25.0;
    } else if (bin_residual as f64) < mean_residual - 10.0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins fit decently well,
    // unless the item is large and residual everywhere is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64) / bin_capacity as f64;
        let scarcity = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // New bin is attractive only when scarcity is low (no room anywhere)
        // or item is huge and would leave tiny residual elsewhere.
        let new_bin_bonus = 60.0 * (1.0 - scarcity) + 40.0 * pressure * (1.0 - progress);
        score -= new_bin_bonus;
        // But discourage hoarding empty bins when a good fit exists.
        if fitting_bins_count > 0 && post_residual as f64 > 0.0 && (item_size as f64) < 0.5 * bin_capacity as f64 {
            score += 30.0;
        }
    }

    // Mild penalty for very large leftover residuals that are hard to fill
    // (dead space in the 20-40 range is the classic waste zone for C=100).
    if post_residual > 20 && post_residual < 40 {
        score += 15.0;
    }

    // Slight preference for keeping more compact bins as stream progresses.
    score += 0.05 * (bin_residual as f64 - post_residual as f64).max(0.0) * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty for wasting the gap
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Time horizon: early in the stream, be more conservative about opening bins;
    // late in the stream, packing density matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate handling: make empty bin attractive only when
    // no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.5);
        // Slightly discourage new bins early; allow them when open bins are crowded.
        score = bin_capacity as f64 - 15.0 * pressure + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: post_residual weighted by progress polynomial
    let poly = 0.5 + 1.5 * progress * progress;
    score *= poly;

    // Reward tight fits more as stream progresses
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * (1.0 + progress) * 10.0;

    // Penalize dead space below next item size
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual as f64) * (1.0 + progress);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: prefer it only when existing bins are very full on average
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 5.0 - avg_fill * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // item-class sizes (e.g. multiples of 25/50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus -= 18.0; }
        else if pr % 25 == 0 { bonus -= 10.0; }
        else if pr % 10 == 0 { bonus -= 5.0; }
        // Harmonic "waste" penalty: distance to nearest reusable class
        let r = pr % 25;
        let dist = r.min(25 - r) as f64;
        score += dist * 0.6;
        score += bonus;
    } else {
        // Perfect fit is always excellent
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score += slack * 0.15;
            if pr % next_item_size == 0 { score -= 6.0; }
        } else {
            // next item won't fit here: slight penalty for leaving big gap
            score += 0.05 * (pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let tight = (post_residual as f64) / cap; // = 1.0 for empty-bin call
        let mean_frac = mean_residual / cap;
        // open new bin only if existing bins are already fairly full on average
        score += 25.0 - 20.0 * mean_frac;
        if open_bins_count == 0 { score -= 50.0; }
        let _ = tight;
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += 45.0 - 2.5 * pr; // tiny gap => big penalty
    } else if post_residual > 12 && post_residual < 20 {
        score += 8.0; // awkward mid-range gap
    }

    // Reward very tight fits (post_residual near zero handled above; reward exactness).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Waste term: fraction of bin left idle, mildly convex.
    let frac = pr / bin_capacity as f64;
    score += 20.0 * frac * frac;

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item could fill this bin's post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 15.0;
    }
    // If next item cannot fit in the leftover, leftover is likelier dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins
    // (applied uniformly, but new-bin candidate pays it implicitly via larger waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate handling: empty bin residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing an existing bin unless its residual is badly fragmented.
        // Penalize the new bin more when mean residual across open bins is still usable.
        let usable = mean_residual >= item_size as f64;
        if usable {
            score += 18.0 + 0.5 * mean_residual;
        } else {
            score -= 10.0; // open bins are all tight; fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space: post-residual too small for the smallest plausible follow-up item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (next_item_size as f64) * 0.2;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new empty bin unless the item is large relative to capacity
    // and fits are scarce.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        let scarcity = (fitting_bins_count as f64).recip() * 10.0;
        score += 60.0 - large_item_bonus - scarcity;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Prefer bins below mean residual (balanced packing) mildly.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Slight preference for fewer open bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual

    let mut score = r;

    // Smooth non-linear coupling: quadratic/cubic penalty on wasted space,
    // modulated by stream progress (later => tighter packing matters more).
    let waste = (rn * rn) * cap * (0.35 + 0.65 * progress);
    let waste3 = (rn * rn * rn) * cap * 0.5 * progress;
    score += waste + waste3;

    // Reward near-perfect fits smoothly (small post residual gets extra discount).
    let perfect = (-rn * 12.0).exp();
    score -= 18.0 * perfect * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else; make empty-bin score track mean residual of open bins.
    if bin_residual == bin_capacity {
        let poor_fit = (rn - 1.0).abs(); // = 1.0 for empty bin
        let _ = poor_fit;
        // Penalize opening new bins when open bins have healthy residuals,
        // but relax as progress advances (consolidate late).
        score += 30.0 * (1.0 - progress) + 0.15 * mean_residual;
        // If lookahead item could use the fresh bin's large residual, soften penalty.
        let lookahead_fit = (bin_capacity as f64 - next_item_size as f64) / cap;
        score -= 10.0 * lookahead_fit * (1.0 - progress);
        // Many open bins => opening another is fine (spread load).
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Lookahead synergy: reward bins whose post residual matches next item size.
    if next_item_size > 0 {
        let gap = (r - next_item_size as f64).abs();
        let synergy = (-gap / 20.0).exp();
        score -= 12.0 * synergy * (0.4 + 0.6 * progress);
    }

    // Mild preference for filling already-open bins when many are open.
    score += 0.02 * open_bins_count as f64 * rn * cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual modulo capacity quarters.
    let quarter = bin_capacity / 4;
    let class = (post_residual / quarter) as f64;

    // Reward (subtract) for very tight fits: post_residual in lowest class.
    score -= (quarter as f64 - class * quarter as f64) * 0.6;

    // Penalize residuals that are "dead": too small to hold a mid-size item
    // (items 1..100 unknown distribution, so anything below ~quarter is dead space).
    if post_residual < quarter {
        score += (quarter - post_residual) as f64 * 0.9;
    }

    // Integer-division harmonic: reward residuals that can exactly host
    // a divisor-harmonic chunk of the capacity (50, 25, 20, 10).
    let harmonics: [u32; 5] = [50, 25, 20, 10, 5];
    for h in harmonics.iter() {
        if *h == post_residual {
            score -= 12.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect 2-chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large unusable remainder.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave big dead space and mean residual is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 - 15.0 * fragmentation - 10.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins overall (residual close to mean).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Small tie-break toward packing into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.02 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (tiny gaps) are heavily penalized, scaled by how small the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0; // unusable sliver: strong penalty
    }
    // Penalize "awkward" mid-range gaps that most items overshoot.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer tightening existing bins
    // over spreading; penalize placements that leave large residual.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // next item won't fit here: penalize large wasted residuals.
            score += (post_residual as f64 - (post_residual as f64 % 10.0)) * 0.15;
        }
    }

    // New-bin candidate: make empty bin attractive only when existing bins
    // would create bad dead space or no good fit exists.
    if bin_residual == bin_capacity {
        // Base neutral score slightly above a good fit, below a bad fit.
        score = 45.0;
        // Early in stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
        // If many bins are open and mean residual is small, avoid new bins.
        score += open_bins_count as f64 * 1.5;
        if mean_residual >= item_size as f64 {
            score += 10.0; // existing bins likely have room; discourage new bin
        }
        // If the next item is large, having a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if diff > 0.0 {
            // leftover after next item fits: penalize proportionally
            score += diff * 0.8;
        } else {
            // next item cannot fit in the leftover: penalize the mismatch
            score += (-diff) * 1.2;
        }
    }

    // Penalize small unusable dead space (nonzero but < typical min item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to bin capacity
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Relative to mean residual of open bins: prefer bins with less residual than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= fill * progress * 20.0;

    // New empty bin: mildly discouraged unless existing fits are poor
    if bin_residual == bin_capacity && item_size <= bin_capacity {
        score += 30.0;
    }

    // Prefer fewer open bins (encourage reuse rather than spreading)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 3.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets neutral baseline but
    // should be preferred when open bins would leave large dead space,
    // and avoided when a good fit exists among open bins.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, decaying as stream progresses
        // (late in the stream, fewer future items to fill it with)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 30.0 * progress;

        // If many bins are open with plenty of slack, discourage opening another.
        score += 1.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64).max(0.0);
    } else {
        // Reward using existing bins, more so when open-bin count is high
        // (consolidation pressure).
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

        // Prefer bins with residuals below the mean (tighter bins first),
        // classic best-fit-like behavior with adaptive threshold.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // Time-horizon modulation: early in the stream, be greedy with tight fits;
    // late in the stream, prioritize closing out bins (smaller residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Reward tight fits: subtract a non-linear function of post_residual.
    // The smaller the post_residual relative to capacity, the bigger the reward,
    // amplified by a smooth polynomial in stream progress.
    let tight = (1.0 - post_frac).powi(3);
    score -= 18.0 * tight * (0.5 + 0.5 * progress);

    // Perfect fit gets a strong extra reward (smooth spike via quadratic in post_frac).
    score -= 25.0 * (1.0 - post_frac * post_frac) * (1.0 - post_frac);

    // Penalize dead space: post_residual that is too small to matter is fine,
    // but mid-range residuals are wasteful. Penalize post_residual in the
    // "awkward" band using a smooth bump around mean_residual.
    let awkward = post_frac * (1.0 - post_frac);
    score += 6.0 * awkward * (1.0 + 2.0 * progress);

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 {
        let next_frac = next_item_size as f64 / cap;
        if next_item_size <= post_residual {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 10.0 * snug * (1.0 - progress * 0.5);
        } else {
            // Next item won't fit here; penalize slightly if post_residual is large
            // enough that leaving it stranded is costly.
            score += 4.0 * post_frac * next_frac;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open: favor bins with
    // residual close to (or below) the mean residual.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev * (0.5 + open_bins_count as f64 / 20.0).min(2.0);
    }

    // New-bin candidate: make empty bins less attractive early (fill existing bins),
    // but allow opening new bins late in the stream or when post_residual of the
    // new bin (== capacity - item) is small.
    if bin_residual == bin_capacity {
        let new_post_frac = (bin_capacity - item_size) as f64 / cap;
        score += 8.0 * (1.0 - progress) + 6.0 * new_post_frac * (1.0 - new_post_frac);
        if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fill: huge reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small residue class" (0..=10) are preferred — dead space minimization.
    let pr_class = post_residual / 10; // integer division class 0..=10
    score -= match pr_class {
        0 => 25.0,           // leftover < 10: nearly perfect
        1 => 12.0,           // 10..19
        2 => 5.0,            // 20..29
        3 => 0.0,
        4 => -2.0,           // 40..59: medium leftover, mildly acceptable
        5 => -4.0,
        _ => -6.0,           // large leftover: bin still reusable
    };

    // Fine residue modulo 10: reward residuals close to a multiple of 10
    let m = post_residual % 10;
    score -= (10 - m as i32 as f64).abs() * 0.3;

    // Lookahead coupling: if next item fits into this bin's post_residual,
    // reward; otherwise penalize proportionally to its size class.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nk = next_item_size / 10;
            score -= 4.0 + nk as f64 * 1.5;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate detection: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when open bins exist and mean residual
        // suggests existing space could absorb the item.
        let open_pressure = open_bins_count as f64 * 2.0;
        let mean_pressure = mean_residual * 0.3;
        score += 15.0 + open_pressure + mean_pressure * (1.0 - progress);
        // But if item is large (would leave big post_residual), opening a
        // fresh bin is less bad.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter fits overall, scaled by stream progress.
    score += (bin_residual - item_size) as f64 * 0.05 * progress;

    // Tie-break: prefer bins with residual above mean (keep small bins tight).
    if (bin_residual as f64) > mean_residual {
        score += 1.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..12)
    // are poisoned — nothing in [1,100] typically pairs with them later.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Reward exact match with lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 12 {
        score -= 15.0; // residual that exactly hosts the next item
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to the known next item
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean in the "tight" direction:
    // filling below-mean-residual bins concentrates waste.
    if post_residual > 0 {
        let dev = mean_residual - post_residual as f64;
        score -= 0.5 * dev;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is truly awful).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw score is high (post_residual == capacity), but add pressure so that
    // opening new bins is discouraged unless all fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * (1.0 - progress);
        // Allow opening a new bin when the item would leave a large awkward gap
        // in every existing bin (post_residual small & unusable already penalized).
        if post_residual as f64 > mean_residual {
            score -= 10.0; // fresh bin keeps mean residual high/usable
        }
    }

    // Mild late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (aggressively close the bin).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            score -= 0.8 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize proportional leftover gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening new bins when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But allow new bin if the item would leave a large dead space nowhere else.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream: consolidate harder, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    // Mild preference to fill bins with less residual among many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep as fallback unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0
            + 2.0 * open_bins_count as f64
            - 0.5 * mean_residual
            - 10.0 * (fitting_bins_count as f64).min(3.0);
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 8.0; // lookahead may use open-bin residuals; delay new bin
        }
        return score;
    }

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use (min item 1, but
    // typical items are larger; use a soft threshold around 15).
    if post_residual > 0 && post_residual < 15 {
        score += 6.0; // tiny sliver is nearly dead space
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer the one leaving the largest residual
        // that still matches the next item (best-fit with lookahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 + 0.1 * post_residual as f64;
        } else if next_item_size > 0 {
            score += 4.0; // residual unusable by next item
        }
    }

    // Reward residuals that exactly (or nearly) match the lookahead item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 8.0 / (1.0 + gap);
    }

    // Late in the stream, consolidate: prefer filling existing bins over
    // spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * progress;
    score -= 4.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Slight preference to keep mean residual high (balanced bins).
    if post_residual as f64 > mean_residual {
        score += 1.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = progress.clamp(0.0, 1.0);

    let mut score = post;

    // Non-linear waste penalty: quadratic coupling of post_residual with stream progress.
    // Early on, leftover space is valuable (future items may fill it); late, tightness wins.
    let norm_post = post / capacity;
    score += (norm_post * norm_post) * capacity * (0.5 + 0.5 * t);

    // Reward tight fits: subtract a smooth function of item fill ratio.
    let fill = item_size as f64 / capacity;
    score -= fill * fill * capacity * (0.6 - 0.3 * t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - t);
    }

    // Lookahead coupling: if the next item fits the post residual, reward leaving it open.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = (post - nx) / capacity;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // Next item won't fit here; penalize residuals that are awkwardly small.
            let unusable = (nx - post) / capacity;
            score += 8.0 * (1.0 - unusable) * (1.0 - unusable) * (0.4 + 0.6 * t);
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean (tighter bins),
    // with a smooth saturating term.
    let diff = (mean_residual - post) / capacity;
    score -= 10.0 * diff / (1.0 + diff.abs());

    // Mild pressure to consolidate into fewer bins when many are open.
    let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 3.0;
    score += open_pressure * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity-fraction buckets
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap;

    // Reward tight fits: perfect/quarter/half classes
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0; // harmonic decile class
    } else if frac < 0.1 {
        score -= 20.0;
    }

    // Penalize dead space in awkward middle zone (0.1..0.3 of capacity)
    if frac > 0.1 && frac < 0.3 {
        score += 10.0 * (0.3 - frac);
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // harmonic bonus scaled by how well next item uses the leftover
        let leftover_after = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - leftover_after / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover likely wasted
        score += 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin only when open bins have poor fits or it's early
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 35.0 + 20.0 * progress;
        }
        // new bin attractive if mean residual of open bins is small (all nearly full)
        if mean_residual < 0.15 * cap {
            score -= 30.0;
        }
    }

    // Mild penalty for leaving residual far from any harmonic class (multiples of 5)
    if post_residual % 5 != 0 {
        score += 3.0;
    }

    // Consolidation pressure: many open bins -> prefer filling existing ones
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * (1.0 - fit_ratio);

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 18.0 * (1.0 - gap as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize blocking good residual space.
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // But if no open bin fits tightly, allow new bin sometimes.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing potential in fresh bin
        }
    }

    // Mild alignment with mean residual: prefer bins below mean (filler bins).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when next item exactly fills the post-residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            score -= 500.0;
        } else if post_residual as f64 >= next {
            // next item fits after this placement: mild reward proportional to tightness
            score -= 80.0 * (1.0 - ((post_residual as f64 - next) / bin_capacity as f64));
        } else {
            // next item will not fit here: penalize wasted residual that can't serve lookahead
            score += 60.0 * (next - post_residual as f64) / 100.0;
        }
    }

    // Penalize large dead space relative to mean residual
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.5 * dead;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 150.0;
        // reduce penalty if item is large relative to capacity (good to start fresh)
        score -= 1.2 * item_size as f64;
        // if next item is small, existing bins with residual can serve it; discourage new bin
        if next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score += 50.0;
        }
        // late in the stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Slight preference for tighter existing bins
    score += 0.3 * (bin_residual as f64 - post_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual in (0, 10) is nearly unusable; larger residual is more reusable).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 18.0 * (1.0 - pr / 10.0);
        } else {
            score -= 2.0 * (pr / cap).ln().max(0.0);
        }
    }

    // Lookahead: if the next item fits into the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt as u32) <= post_residual {
            let slack = post_residual as f64 - nxt;
            score -= 8.0 * (1.0 - slack / cap);
        } else if post_residual > 0 && nxt > post_residual as f64 {
            // Next item cannot use leftover: mild penalty proportional to wasted potential.
            score += 3.0 * (1.0 - (post_residual as f64) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin for this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into bins below mean residual (fill the "dirtiest" bins).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64) - mean_residual;
        score += 0.05 * dev;
        // Extra consolidation pressure as open bin count grows.
        score += 0.3 * (open_bins_count as f64).ln();
    } else if open_bins_count == 0 {
        // No open bins: opening a bin is mandatory; neutralize new-bin penalty.
        score -= 100.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins fit poorly. Penalize opening a new bin, scaled by stream progress.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = 1.0 - (item_size as f64) / cap; // small items waste more of a fresh bin
        score += 6.0 + 8.0 * fit_quality + 4.0 * (1.0 - progress);
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // Time horizon: late in the stream, be more conservative about leaving
    // awkward residuals (fewer chances to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 * progress;
    }

    // Slight preference for bins whose residual is close to item_size (perfect fill).
    let exact = ((bin_residual as f64) - (item_size as f64)).abs();
    score += 0.02 * exact;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr_norm * (1.0 + 0.8 * progress * progress);

    // Reward tight fits via smooth polynomial of post_residual
    score -= (1.0 - pr_norm).powi(3) * (1.0 + fit_ratio);

    // Penalize dead space that is too small for typical future items
    let dead = (pr_norm * (1.0 - pr_norm) * 4.0).powi(2);
    score += dead * (1.0 - progress) * 2.0;

    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 1.5 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.5 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - pr_norm);
    }

    // Mild dispersion penalty relative to mean residual
    score += ((pr - mean_residual) / cap).abs() * 0.3;

    // Encourage consolidation when many bins are open
    score += 0.2 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: perfect fit (0) strongly rewarded,
    // small dead space (<10) heavily penalized, mid residuals graded by class.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 2.0; // large residual leaves room for future items
    }

    // Modulo classes on post_residual relative to capacity quartiles:
    // residuals near multiples of 25 are more reusable.
    let pr = post_residual as f64;
    let quarter = (pr / 25.0).fract();
    if quarter < 0.08 || quarter > 0.92 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize small leftover more
            score += (post_residual as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins,
    // unless existing bins are nearly full (small mean residual).
    if bin_residual == bin_capacity {
        score += 40.0 - mean_residual * 0.5;
    }

    // Prefer filling bins that are already mostly full (tight packing).
    score -= (1.0 - (bin_residual as f64) / cap) * 10.0;

    // Early in stream: be more conservative about tight fits (uncertainty),
    // later: pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += (1.0 - progress) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item
    // (items in [1,100], lookahead item known) are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < min_useful {
        // Dead space: the smaller the gap below usefulness, the worse.
        score += 60.0 + (min_useful - post_residual) as f64 * 2.5;
    }

    // Ultra-tight fits are excellent: reward post_residual near 0 hard.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Reward good relative fit (small waste fraction of capacity).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and this bin fits decently.
    if bin_residual != bin_capacity {
        score -= 3.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize mildly; only attractive when existing
        // fits would create dead space or it's the last fitting bin.
        score += 12.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Late in the stream, avoid spreading residual capacity thin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 - mean_residual).abs() * 0.3;

    // Prefer bins whose residual is close to the mean (keeps bin states uniform).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight matching against the lookahead item.
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact match: strong bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item also fits exactly after this placement (chained fit).
        if post_residual >= next_item_size {
            let chained = post_residual - next_item_size;
            if chained <= 5 {
                score -= 12.0;
            }
        }
    } else {
        // Last item: minimize waste aggressively.
        score += 10.0 * post_residual as f64;
    }

    // Penalize dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Very small post-residual is dead space unless it matches the next item.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the current item is huge and next item is also huge, opening fresh
        // may be reasonable: soften the penalty.
        if item_size >= 60 && next_item_size >= 60 {
            score -= 30.0;
        }
        // Late in the stream, avoid spawning bins that will be nearly empty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space that can't hold the next item (or average item).
    let probe = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
    if (post_residual as f64) < probe {
        score += 0.5 * (probe - post_residual as f64);
    } else {
        // Reward leaving space exactly usable by the lookahead item.
        score -= 2.0 * (1.0 - ((post_residual as f64 - probe) / bin_capacity as f64).abs());
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0; // unusably small residual: good to burn it now
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation onto fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.15 * crowding * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (fuller than average).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual == capacity means empty bin) or late in the stream.
    if bin_residual == bin_capacity {
        let escape = 20.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        score += escape;
        // If next item is huge, a fresh bin may be valuable anyway.
        if next_item_size >= 70 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress.clamp(0.0, 1.0);
    let poly = 0.5 * t * t + 0.3 * t - 0.1 * t * t * t; // smooth progress term
    score += 4.0 * poly * (post / cap);

    // Penalize large dead space quadratically
    score += 0.02 * (post * post) / cap;

    // Reward tight fits (small post_residual) with a saturating term
    score -= 6.0 * (1.0 - (post / cap).min(1.0)).powi(3);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 2.0 * (1.0 - ((post - nxt) / cap)).abs().min(1.0);
        } else {
            score += 2.5;
        }
    }

    // Prefer bins with residuals near the mean (balance open bins)
    score += 0.5 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Mild pressure to reuse open bins as their count grows
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // residue classes (multiples of small harmonics) are less penalized.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        if pr % 10 == 0 { harmony -= 6.0; }
        if pr % 20 == 0 { harmony -= 4.0; }
        if pr % 25 == 0 { harmony -= 3.0; }
        if pr % 50 == 0 { harmony -= 3.0; }
        // Dead-space class: residuals in (0,10) are nearly unusable.
        if pr < 10 { harmony += 18.0 * (1.0 - pr as f64 / 10.0); }
        // Mid-band residuals 30..50 are prime targets for typical item sizes.
        if pr >= 30 && pr < 50 { harmony -= 5.0; }
        score += harmony;
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Lookahead coupling: reward when next item fits the post residual exactly
    // or into a harmonic class of it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let ni = next_item_size;
        let mut lookahead_bonus = -8.0;
        if pr % ni == 0 { lookahead_bonus -= 6.0; }
        if ni % 10 == 0 && pr % 10 == 0 { lookahead_bonus -= 3.0; }
        // If next item leaves its own tiny dead space, dampen the bonus.
        let next_post = pr - ni;
        if next_post < 10 && next_post > 0 { lookahead_bonus += 6.0; }
        score += lookahead_bonus;
    } else if next_item_size > post_residual {
        // Next item won't fit here: slight penalty for hoarding residual.
        score += 2.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if pr > 0 && pr < 10 { score += 10.0; }
    }

    // New-bin candidate handling: opening a new bin wastes all open residuals.
    // Prefer it only when open bins are crowded and mean residual is small,
    // or when placing here would strand a tiny dead zone.
    if bin_residual == bin_capacity {
        // Base reluctance grows with number of open bins.
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But if all open residuals are small (mean residual low), new bin is fine.
        let mean_frac = mean_residual / cap;
        if mean_frac < 0.15 {
            score -= 10.0 + 10.0 * (0.15 - mean_frac);
        }
        // Late in the stream, closing out cleanly matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * progress;
        // Large items (>= half capacity) start fresh bins more readily.
        if item_size * 2 >= bin_capacity { score -= 6.0; }
    }

    // Waste-rate term: quadratic penalty on wasted residual relative to capacity.
    let waste_frac = post / cap;
    score += 4.0 * waste_frac * waste_frac * cap * 0.1;

    // Small tie-breaker toward fuller bins overall.
    score -= 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let next = next_item_size.min(bin_capacity) as f64;
    let mean = mean_residual.max(0.0).min(capacity);
    let inv_capacity = if capacity > 0.0 { 1.0 / capacity } else { 0.0 };
    let next_ratio = next * inv_capacity;
    let mean_ratio = mean * inv_capacity;

    // Estimate how likely a gap below `next_item_size` will really force another bin.
    let crowding = 1.0 / (1.0 + 0.12 * open);
    let next_risk_raw = if next <= 0.0 {
        0.0
    } else {
        let deficit = ((next - mean) / next).clamp(0.0, 1.0);
        if deficit <= 0.0 {
            0.04 + 0.06 * crowding
        } else {
            (0.30 + 0.70 * deficit) * (0.55 + 0.45 * crowding)
        }
    };

    // If this is the only fitting bin and the next item is at least as large as
    // the current one, bins that cannot fit the current item also cannot fit the next.
    let forced_single_fit = fitting_bins_count == 1 && next_item_size >= item_size;
    let next_risk = if forced_single_fit {
        next_risk_raw.max(0.92)
    } else {
        next_risk_raw
    };

    if next > 0.0 {
        if post_residual == 0 {
            // Perfect closure is excellent, even if the next item needs another bin.
            score -= 20.0 + 6.0 * progress;
            score += next_risk * (10.0 + 0.25 * (capacity - next));
        } else if post < next {
            // Strict dead-space penalty: positive gap too small for the lookahead item.
            let short = next - post;
            let severity = (short / next).clamp(0.0, 1.0);
            let dead = 0.85 * short + 12.0 * severity + 5.0 * severity * severity;

            score += dead * (0.35 + 0.85 * next_risk);
            score += (8.0 / (post + 1.0)).min(5.0) * (0.35 + 0.65 * next_risk);
            score += next_risk * (14.0 + 0.30 * (capacity - next));
        } else {
            // This bin can also absorb the lookahead item, avoiding a future split.
            let host_bonus = (5.0 + 9.0 * next_ratio) * (0.35 + 0.85 * next_risk)
                + 2.0 * (1.0 - open / (open + 5.0));
            score -= next + host_bonus;
        }
    } else if post_residual == 0 {
        score -= 18.0 + 5.0 * progress;
    }

    if is_new_bin {
        let mut pressure = 20.0
            + 0.45 * open
            + 0.20 * fitting
            + 0.045 * mean
            + 6.0 * progress
            + 3.0 / (1.0 + remaining);

        if fitting_bins_count == 1 {
            pressure += 8.0;
        }
        if fitting_bins_count == 0 {
            pressure -= 40.0;
        }

        pressure += 3.0 * mean_ratio * (1.0 + open / 20.0);
        score += pressure;
    } else {
        if fitting_bins_count == 1 {
            score -= 9.0 + 5.0 * (1.0 - progress);
        }
        score -= 0.08 * open.min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically (small leftovers are hard to reuse).
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // 2-step lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < f64::EPSILON {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 25.0; // next item fits after this placement
            // favor larger leftover slack for the next item
            score -= 0.1 * (post_residual as f64 - next);
        } else {
            // next item cannot follow: penalize more if we waste a lot of space
            score += 0.3 * (next - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 40.0 * fit_ratio;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit style),
    // but discourage dumping into already-crowded bins when many bins are open.
    let mean = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (bin_residual as f64) < mean {
        score -= 0.5 * (mean - bin_residual as f64);
    } else {
        score += 0.2 * (bin_residual as f64 - mean);
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the item is large relative to capacity or few bins fit the item.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // opening new bins early or for big items is fine; otherwise discourage
        score += 15.0 * (1.0 - size_ratio) * (1.0 - progress);
        if fitting_bins_count > 2 {
            score += 20.0; // plenty of alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    let residual_frac = post_residual as f64 / bin_capacity as f64;

    // Strongly reward tight fits (non-linear).
    score -= 30.0 * fill * fill;

    // Penalize dead space: residuals too small for typical future items are worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // nearly-full bin: fine, small bonus actually
            score -= 20.0;
        } else if post_residual < 20 {
            score += 12.0; // awkward dead zone
        }
    }

    // Time horizon: early in the stream, prefer keeping bins flexible (large residuals);
    // late in the stream, pack tightly and close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += residual_frac * (1.0 - progress) * 15.0;
    score -= residual_frac * progress * 10.0;

    // Lookahead coupling: if the next item can use the post-residual exactly, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 2.0 * residual_frac;

    // Global mean residual: if this bin is tighter than average, favor it.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let bad_lookahead = if next_item_size > 0 && next_item_size > post_residual { 10.0 } else { 0.0 };
        score += 45.0 - desperation - bad_lookahead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Progress-coupled penalty: dead space becomes more costly later in the stream
    let dead_penalty = norm_pr * norm_pr * (1.0 - norm_pr) * (2.0 + 6.0 * progress * progress);
    score += dead_penalty * cap * 0.5;

    // Smooth interaction: post_residual vs mean residual (avoid outliers vs pool)
    score += 0.35 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin, scaled by progress
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - exact / cap) * (1.0 - progress * 0.5);
    } else if next_item_size > post_residual {
        score += 4.0 * progress;
    }

    // Slight preference for consolidating into fewer bins as stream nears its end
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "dead space" classes are penalized, large usable leftovers rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo-class coupling: leftover divisible by common item sizes (5/10/20)
    // is more reusable — reward it.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item exactly fits the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a new leftover: mild reward scaled by
            // how "clean" the resulting second leftover is.
            let second = post_residual - next_item_size;
            if second % 10 == 0 { score -= 10.0; }
            if second < 10 && second > 0 { score += 15.0; }
        } else {
            // Next item won't fit here: penalize slightly, more when this bin
            // was a last-chance bin.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 10.0; // still worth consuming the dead space
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins are open, prefer using them.
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins with below-mean residual (tighter packing candidates).
    score += 0.3 * (mean_residual - pr).max(-50.0).min(50.0);

    // Mild tie-break toward fuller bins early on.
    let fill = 1.0 - pr / cap;
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps hard.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 * (1.0 - post_residual as f64 / min_useful as f64);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // dead space relative to next item
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Tight-fit preference: favor bins where item occupies a large fraction.
    score -= 20.0 * (item_size as f64 / bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full or poor fits.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 + 40.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score += (post_residual as f64) * 0.05;

    // 2-step lookahead: reward when the next item also fits after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here too -> chain placement, reward strongly.
            let slack_after_next = post_residual - next_item_size;
            score -= 20.0 + slack_after_next as f64 * 0.3;
        } else {
            // Next item won't fit: penalize proportionally to how much it misses,
            // but less if post_residual is tiny (good fit now is still fine).
            let miss = (next_item_size as f64) - (post_residual as f64);
            score += miss * 0.6;
        }
    }

    // Relative to mean residual: prefer bins whose residual is above/below mean
    // in a useful way. Filling a high-residual bin is good.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.4; // tighter than average -> good
    } else {
        score += (res - mean_residual) * 0.2; // looser than average -> mild penalty
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins with good fits, but not absurdly high.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening a new bin is attractive when few bins fit and lookahead fails.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Late in the stream: consolidate more aggressively, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    // Penalize dead space: residual that is too small for the smallest item (1..100 unknown,
    // use conservative threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fits are excellent: reward small post-residuals super-linearly.
    let tightness = 1.0 - (post / cap);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that nothing can ever use (smallest item is 1).
    if post > 0.0 && post < 1.0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let next_waste = post - nxt;
            score -= 30.0 * (1.0 - next_waste / cap);
        } else {
            // Next item won't fit here: mild penalty proportional to gap.
            score += 0.15 * (nxt - post).min(cap);
        }
    } else {
        // Last item: absolutely minimize waste.
        score += 10.0 * post / cap;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it to avoid
    // opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current residuals are large (bad fits everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        let mean_r = if mean_residual.is_finite() { mean_residual } else { cap };
        let pressure = (mean_r / cap).clamp(0.0, 1.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin, discounted by residual pressure in open bins.
        score += 45.0 - 55.0 * pressure - 10.0 * (1.0 - progress);
        // Early stream: opening bins is cheap-ish to build a portfolio.
        if open_bins_count < 3 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin: reward keeping the number of open bins low.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly stabilizing fragmentation across bins.
    if bin_residual != bin_capacity {
        let dev = ((bin_residual as f64) - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild time-horizon scaling: later in the stream, waste matters more
    // since fewer chances remain to reuse residual space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but weighted non-linearly by stream progress.
    // Late in the stream, tight fits (small post_residual) matter more,
    // so amplify the quadratic term of post_residual with progress.
    let mut score = pr * (1.0 + 1.5 * progress * progress) + 40.0 * progress * norm_pr * norm_pr;

    // Smooth coupling: reward small post_residual when the next item can use it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        let gap_norm = gap / cap;
        score -= 30.0 * (1.0 - progress) * (-gap_norm * gap_norm * 20.0).exp();
        // Penalize post_residual that is slightly larger than next item (unusable sliver)
        score += 20.0 * progress * (-(norm_pr * 6.0)).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, favor using it strongly.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty when many bins are open and residual is far above mean (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + progress);

    // Smooth new-bin consideration: empty bin gets a moderate default score,
    // lowered only early in stream or when current bin would leave large dead space.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.3 * progress) + 20.0 * norm_pr;
        // Opening a new bin is attractive if placing elsewhere creates a tiny useless residual
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward post_residual that is itself a likely packable class
    // (multiples of 10 are highly reusable given typical item granularity)
    let pr = post_residual as u32;
    if pr > 0 {
        let mod10 = pr % 10;
        // Dead space penalty: residuals not expressible as sums of typical items
        score += mod10 as f64 * 2.5;
        if pr < 10 {
            score += 40.0; // unusable sliver
        }
        // Harmonic class match: post_residual exactly equals a plausible item size class
        if pr >= 10 && pr <= 80 {
            score -= 8.0;
        }
        // post_residual divisible by next item's class
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr >= next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64; // == post_residual for empty bin
        let waste = (bin_capacity - item_size) as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // open new bin only if item is small relative to capacity (leaves reusable space)
        score += 120.0 - (100.0 - waste) * 0.5;
        score -= progress * 20.0; // late in stream, prefer consolidation
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
        if tightness >= next_item_size as f64 && next_item_size > 0 {
            score -= 10.0; // new bin can host next item too
        }
    }

    // Prefer bins whose residual is close to item (tight fit) via fractional measure
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 30.0;

    // Coupling with mean residual: prefer bins below mean residual (more filled)
    if (bin_residual as f64) < mean_residual {
        score -= 12.0;
    } else {
        score += 6.0;
    }

    // Next-item lookahead: penalize leaving residual just barely too small for next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that can still fit typical small items.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the incoming item.
        score += 10.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open; prefer new bin when few.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: baseline score so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.3;
        if fitting_bins_count == 1 {
            score += 25.0; // discourage opening new bin when an existing bin is a last chance
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 3.0;
        }
    }

    // Slight preference for tighter bins overall.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild non-linear penalty
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Lookahead: reward bins whose post_residual can host the next item (k=2 chain)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
        // Perfect chain: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead demand
        score += 0.25 * (next_item_size as f64 - pr);
    }

    // Compare post_residual against mean residual: leaving more than average is wasteful
    score += 0.30 * (pr - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are quite full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - (mean_residual / cap);
        score += 25.0 * avg_fullness + 5.0 * (1.0 - progress);
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 8.0; // fresh bin guarantees lookahead fit
        }
    }

    // Slight preference for filling fuller bins first
    score -= 0.10 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a nonlinear bonus.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always great
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_ratio * fit_ratio;
        // Penalize dead space that can't hold a typical future item.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let expected_item = 45.0 * (1.0 - 0.4 * t); // later in stream, prefer tighter packing
        if (post_residual as f64) < expected_item {
            score += 0.15 * (expected_item - post_residual as f64);
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            // post_residual below next item size is likely wasted; penalize mildly.
            score += 0.08 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins among open bins (relative to mean residual).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Penalize spreading across too many open bins slightly, encouraging consolidation.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let best_open_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        // Opening a new bin costs ~a full bin; only prefer it if existing bins fit poorly.
        score += 20.0 - 25.0 * best_open_pressure;
        // Late in the stream, opening new bins is less useful; discourage.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * t;
        // If item is small, opening a new bin wastes capacity; discourage.
        score += 0.3 * (bin_capacity as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual (tight fit).
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // dead space becomes more costly as the stream advances.
    let dead_penalty = (post / cap).powi(3) * (60.0 + 80.0 * progress * progress);
    score += dead_penalty;

    // Reward near-perfect fits (post_residual close to 0), smoothly.
    let tightness = (1.0 - post / cap).powi(2);
    score -= 45.0 * tightness * (0.5 + 0.5 * progress);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Lookahead: favor leaving space that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = post >= nxt;
        let slack = (post - nxt).max(0.0);
        let fit_quality = 1.0 - (slack / cap).powi(2);
        if usable {
            score -= 35.0 * fit_quality * (1.0 - progress);
        } else {
            // Penalize residuals too small for the next item (dead space).
            score += 25.0 * (1.0 - post / cap) * (1.0 - progress);
        }
    }

    // Mild preference for reusing bins when many are open; encourage new bins
    // when few are open (spreading load early).
    let spread_bias = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).ln().max(0.0);
    score += 4.0 * spread_bias;

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_waste = (post / cap) - (mean_residual / cap);
        score += 70.0 * (1.0 - tightness) + 30.0 * avg_waste;
        // Late in the stream, closing out bins matters more; discourage new bins.
        score += 50.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Harmonic class of the leftover space: residual classes divisible by common
    // item sizes (10/20/25/50) are more reusable than "odd" leftovers.
    let reusable = |r: u32| -> f64 {
        if r == 0 { 0.0 }
        else if r % 50 == 0 { 0.0 }
        else if r % 25 == 0 { 2.0 }
        else if r % 20 == 0 { 3.0 }
        else if r % 10 == 0 { 5.0 }
        else { 8.0 } // awkward dead space
    };
    score += reusable(post_residual);

    // Penalize leaving a residual smaller than the smallest plausible item (1..100
    // unknown dist, but tiny slivers < 10 are near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item won't fit here; mildly penalize wasting capacity
            score += 5.0;
        }
        // Harmonic divisibility of next item into post_residual class
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate handling: empty bins should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Prefer deferring new bins early (amortization), allow later when stream is dense.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Congestion: many open bins -> favor consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Nudge toward bins whose residual is close to the fleet mean (keeps spread tight).
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual < item_size {
            // Gap too small for any plausible future item of this size class.
            score += 12.0;
        }
    }

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 30.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins would leave bad dead space.
        if post_residual as f64 > mean_residual * 0.6 {
            score -= 15.0 + 5.0 * (1.0 - progress);
        } else {
            score += 25.0 + 10.0 * bin_pressure;
        }
    } else {
        // Favor bins below mean residual (more free space than average) slightly.
        score += 0.05 * (mean_residual - bin_residual as f64);
        score += 0.3 * bin_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: aggressive 2-step lookahead — reward bins whose post-residual
    // exactly matches the next item size (perfect chain fill).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus: subtract up to ~40 when gap is small.
        let match_bonus = 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        score -= match_bonus;

        // Extra strong reward for exact match (zero-gap chain).
        if gap == 0.0 {
            score -= 25.0;
        }
    }

    // Penalize large dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.35 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Penalize unusable dead space: post_residual too small for the smallest
    // plausible next item (items >= 1, but typical >= 10). Threshold at 12.
    if pr > 0.0 && pr < 12.0 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin when it would
    // waste capacity the lookahead could use in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score += 55.0;
        // If next item fits nicely into this fresh bin anyway, soften slightly.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let gap_new = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() as f64;
            if gap_new < 8.0 {
                score -= 30.0;
            }
        }
        // Late in the stream, avoid spawning bins with tiny future demand.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for tighter (fuller) bins generally.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    // Small penalty for proliferating open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use (items >= 1, so residual 0 is perfect)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 2.0;
        }
        // Bonus if post-residual matches next item exactly
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: minimize residual waste directly
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream, opening bins is cheaper; later, prefer consolidation
        let open_penalty = 20.0 * (1.0 - 0.5 * t) + 2.0 * open_bins_count as f64;
        score += open_penalty;
        // Allow new bin if no open bin fits well
        if fit_ratio < 0.5 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global residual balance: prefer bins below mean residual (filler bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for keeping many options open: penalize using large-residual bins on small items
    if (item_size as f64) < 0.4 * bin_residual as f64 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = pr;

    // Non-linear coupling: penalize residual quadratically, more as stream progresses.
    score += (pr * pr / cap) * (0.5 + progress);

    // Cubic dead-space term: large residuals are exponentially bad late in stream.
    score += (fit_ratio * fit_ratio * fit_ratio) * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post residual relative to item) with smooth interaction.
    let item_f = item_size as f64;
    score -= (item_f * item_f) / (cap + item_f) * (1.0 - fit_ratio);

    // Lookahead: penalize if next item cannot use the leftover space smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).abs();
        score += (gap / cap) * (nx + pr) * 0.25 * (1.0 - progress);
        // Reward when next item fits exactly-ish into post residual
        let smooth_fit = 1.0 / (1.0 + (nx - pr) * (nx - pr) / 50.0);
        score -= 10.0 * smooth_fit;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).ln();
    }

    // Mean residual context: penalize bins far from the fleet mean residual.
    score += (pr - mean_residual).abs() * 0.15;

    // New-bin candidate shaping: empty bin gets mild penalty that grows with open bins
    // and shrinks as stream progresses (allowing consolidation early, fresh bins late).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).ln() - 6.0 * progress;
    }

    // Mild penalty for bin proliferation.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover matches a common
    // item-size class (multiples of 10) are more reusable.
    let class = post_residual / 10;
    score -= (class as f64) * 3.0;

    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no plausible item can use: post_residual < 10
    // is unusable (min item size 1..100, but small slivers are waste).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward if next item fits exactly into post_residual (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Modulo coupling: post_residual divisible by next_item_size classes.
    if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: neutral baseline; only attractive when open bins are
    // badly fragmented (high mean residual variance proxy via mean_residual).
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.3;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin if an open bin is last chance
        }
    }

    // Slight late-stream conservatism: consolidate more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 10.0; // smallest item is <= 10 in classic streams
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 12.0;
    }

    // Reward tight fits (small post_residual) mildly beyond raw value.
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fit_ratio * 15.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate handling: only attractive if the fit here would be poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let would_be_waste = (bin_capacity - item_size) as f64;
        if would_be_waste > 40.0 {
            score -= 10.0; // poor fits elsewhere -> fresh bin is fine
        } else {
            score += 30.0; // decent fit possible -> keep filling existing bins
        }
    }

    // Lookahead: if the next item fits perfectly into the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this gap: slightly penalize leaving medium gaps.
        if post_residual >= 10 && post_residual < next_item_size {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Prefer bins whose residual is below average (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-match: next item fits with small slack left.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize proportionally to waste.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize unusable dead space (below minimum plausible item size).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Reward using bins that are tighter than average (good fill).
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.2;

    // Last-chance bin: strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin leaves a very poor fit
    // for the lookahead item.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && next_item_size <= post_residual {
            (post_residual - next_item_size) as f64
        } else {
            0.0
        };
        score += 50.0 - bad_fit * 0.4;
    }

    // Late in the stream, prefer tighter packing even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += diff * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: the fuller we make the bin, the better (scaled by item size).
    score -= 0.6 * (item / cap) * (cap - post);

    // Dead-space penalty: residual too small to hold anything useful (min plausible size).
    let min_useful = if next_item_size > 0 {
        (next_item_size.min(item_size)) as f64
    } else {
        item
    };
    if post < min_useful {
        score += 2.5 * (min_useful - post);
    }

    // Lookahead: strongly favor bins whose post-residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
        // Extra reward for a snug two-item chain (post exactly near next size).
        score -= 0.5 * (1.0 - ((post - next_item_size as f64) / cap).abs());
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: fresh bins are costly, especially late in the stream
    // or when many bins are already open; but attractive if they leave flexible space.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 0.4 * open_bins_count as f64 + 4.0 * t;
        if post >= min_useful {
            score -= 2.0; // fresh bin leaves a usable, flexible remainder
        }
        // Opening a new bin is fine when the item is huge relative to capacity.
        score -= 2.0 * (item / cap);
    }

    // Balance coupling: penalize bins that deviate strongly from the mean residual,
    // encouraging even fill across open bins.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Mild late-stream pressure to consolidate into existing bins.
    let t2 = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * t2 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let poly = prn * prn * (1.0 + progress) - 2.0 * prn * progress * progress;
    score += 10.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= (1.0 + 3.0 * progress) * tightness * tightness * item_size as f64 / 10.0;

    // Penalize dead space (small unusable residuals) with smooth cubic term
    if post_residual > 0 && post_residual < item_size.max(next_item_size).max(1) {
        score += 5.0 + 15.0 * progress * (1.0 - prn).powi(3);
    }

    // Last-chance bin bonus, scaled by progress
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (0.5 + progress);
    }

    // Lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 2.0 * progress;
    } else if next_item_size > 0 {
        score += 2.0 * prn * (1.0 - progress);
    }

    // Prefer filling bins with larger mean residual (consolidate waste)
    score -= 0.3 * mean_residual * (0.5 + 0.5 * progress);

    // New-bin candidate: mild penalty so open bins are preferred unless fit is poor
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress * (prn * prn);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity left

    // Penalize residuals that fall into "dead" classes: small, unusable slivers
    if pr == 0 {
        score -= 30.0; // perfect fit is excellent
    } else if pr < 10 {
        score += 25.0; // tiny sliver = wasted capacity
    } else {
        // Modulo-10 class: residuals divisible by 10 pair well with typical item sizes
        let class = post_residual % 10;
        if class == 0 {
            score -= 6.0;
        } else if class >= 7 {
            score += 4.0;
        }
        // Harmonic thresholds: residual that still admits half-capacity is valuable
        if pr >= bin_capacity / 2 {
            score -= 8.0;
        } else if pr >= bin_capacity / 4 {
            score -= 3.0;
        } else {
            score += 5.0 * (1.0 - frac * 4.0); // penalize shrinking residuals super-linearly
        }
    }

    // Super-linear penalty on waste, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr * pr) as f64 / (c * c) * 20.0 * (0.5 + progress);

    // Lookahead: reward leaving room for the next item exactly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / c);
            if post_residual == next_item_size {
                score -= 15.0; // chain of perfect fits
            }
        } else {
            score += 12.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: make it moderately unattractive unless open bins are all bad fits
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if the item is large and would leave a bad class, opening fresh is fine
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins when many bins are open
    score -= (bin_residual - post_residual) as f64 * 0.05;

    // Coupling with mean residual: prefer bins below mean (consolidating emptier space usage)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste — penalize them heavily.
    if post_residual < 10 {
        score -= 60.0; // perfect closure is great
    } else if post_residual < 20 {
        score += 25.0; // likely dead space
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Open-bin pressure: discourage proliferating bins; favor filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well
    // or residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let next_fits_open = next_item_size > 0 && mean_residual >= next_item_size as f64;
        if fitting_bins_count > 1 && !next_fits_open {
            score += 80.0; // keep using existing bins
        } else if fragmentation > 40.0 {
            score -= 20.0; // fragmentation high, fresh bin is fine
        } else {
            score += 15.0; // mild default penalty
        }
    }

    // Lookahead: favor leaving a gap that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 15 {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // gap useless for the next item
    }

    // Slight preference for bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize wasted potential
            score += 25.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit style).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.5;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly,
    // but allow it when post_residual of new bin (100 - item) is large and current fits are bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If lookahead shows next item also large, fresh bin is attractive.
        if next_item_size > 50 {
            score -= 80.0;
        }
    }

    // Slight preference to consolidate fewer bins early in the stream.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving space exactly useful for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // Last item: waste nothing, prefer fullest packing.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0));
        score += 15.0 + 20.0 * pressure + 10.0 * (1.0 - progress);
    }

    // Mildly prefer bins below mean residual (balance residual distribution).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time-horizon modulation: early in stream, be more conservative with new bins;
    // late in stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * 0.5;
    score += 40.0 * poly;

    // Reward tight fits increasingly over time
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize dead space relative to mean residual (wasted capacity)
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.2 * gap * (1.0 - progress);
    }

    // Mild penalty for too many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item-size classes are more reusable. Reward low modulo values.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Modulo-based reusability bonus: residual divisible by 10 (common size
    // quantum) is highly reusable.
    let mod10 = pr % 10;
    score -= 8.0 * (1.0 - mod10 as f64 / 10.0) * (prf / cap);

    // Integer-division thresholds: classify residual into harmonic bands.
    let band = pr / 25; // 0..4 bands of 25
    match band {
        0 => score += 6.0,          // dead space (<25): hard to reuse
        1 => score += 1.0,          // small
        2 => score -= 2.0,          // medium: good
        _ => score -= 4.0,          // large residual: flexible
    }

    // Fraction-of-capacity coupling: exact capacity fractions are harmonic
    // sweet spots (residuals of 50, 25, 20, 10).
    let frac = prf / cap;
    for target in [0.5f64, 0.25, 0.2, 0.1] {
        let d = (frac - target).abs();
        if d < 0.03 {
            score -= 5.0 * (1.0 - d / 0.03);
        }
    }

    // Lookahead harmony: does post_residual exactly fit next_item_size?
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 12.0; // perfect chain: fill completely next step
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            if slack < 10.0 {
                score -= 6.0 * (1.0 - slack / 10.0);
            }
            // next item's own modulo harmony with residual
            let m = pr % next_item_size.max(1);
            score -= 3.0 * (1.0 - m as f64 / next_item_size.max(1) as f64);
        } else {
            // next item cannot use this residual at all
            score += 4.0;
        }
    } else {
        // last item: prefer fullest packing
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 9.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Progress-aware tightening: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Mean-residual context: if this bin's residual is far below mean, it's
    // nearly full -> good to fill it now.
    let dev = mean_residual - prf;
    if dev > 0.0 {
        score -= 2.0 * dev / cap;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / cap;
        score = cap as f64 - 15.0 * pressure - 10.0 * big_item * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0; // fresh bin can host future items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post > 0.0 && post < 10.0 {
        score += 60.0 * (10.0 - post) / 10.0;
    }
    // Medium dead space (unlikely to host future items) gets a milder penalty.
    if post >= 10.0 && post < 30.0 {
        score += 8.0 * (30.0 - post) / 20.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // tolerate opening a new bin for a perfect fit.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).ln().max(1.0);
    score += 0.35 * pressure;

    // New-bin candidate: only attractive for perfect or near-perfect fit,
    // and more so early in the stream / when mean residual is fragmented.
    if bin_residual == bin_capacity {
        let perfection = 1.0 - (item_size as f64 / cap - 1.0).abs();
        score = cap - 40.0 * perfection.powf(4.0)
            - 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if item_size as f64 / cap > 0.85 {
            score -= 15.0; // big item: fresh bin is ideal
        }
        if mean_residual < 15.0 && open_bins_count > 3 {
            score -= 8.0; // existing bins are fragmented; new bin may consolidate
        }
    }

    // Lookahead: if next item would fit the post-residual exactly, reward.
    if next_item_size > 0 && (post_residual as u64) == next_item_size as u64 {
        score -= 20.0;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 6.0; // next item can't use this gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as i64) - (next_item_size as i64) == 0 {
            score -= 60.0; // perfect chained fit
        } else if post_residual >= next_item_size {
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_slack / (bin_capacity as f64));
        } else {
            // next item cannot follow here: penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    } else {
        // Last item: prefer filling bins as much as possible.
        score -= 10.0 * tightness;
    }

    // Prefer bins that are already relatively empty vs mean residual (consolidate waste elsewhere)?
    // Instead: prefer bins with residual ABOVE mean (keep mean low bins for small items).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a poorly-fitting item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable dead space (below typical minimum item size).
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is bad;
    // scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Late-stream consolidation: as stream progresses, prefer denser packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits, penalize dead space nonlinearly
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 60.0;

        // Penalize residuals too small for the smallest plausible future item (1..100 interface)
        if post_residual < 10 {
            score += 80.0;
        }
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else; make fresh bin mildly unattractive
    if bin_residual == bin_capacity {
        score += 50.0;
        // But if many open bins have large mean residual (fragmented state), new bin is fine
        if mean_residual > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
        // Early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Prefer filling bins with small residual relative to fleet mean
    score -= (mean_residual - bin_residual as f64).max(-100.0).min(100.0) * 0.3;

    // Slight preference for bins with more residual when few bins open
    if open_bins_count <= 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = x * x * (1.0 + progress) + x * 0.5;

    // Smooth coupling: tight fits (small post_residual) get exponentially rewarded.
    score -= (-x * 8.0).exp() * (1.5 - progress);

    // Penalize bins whose residual deviates from the mean residual (fragmentation control).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 2.0;

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 1.0 * (1.0 - (nx / cap));
        } else {
            score += (nx - pr) / cap * 2.0;
        }
    }

    // Mild pressure against accumulating too many open bins early.
    score += (open_bins_count as f64) * 0.02 * progress;

    // New-bin candidate: neutral baseline with slight adaptive bias.
    if bin_residual == bin_capacity {
        score += 0.8 - 0.6 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that the lookahead item can fill.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.1;
    }

    // Penalize wasting a large residual on a small item (poor utilization).
    let waste_ratio = (item_size as f64) / (bin_residual as f64);
    if waste_ratio < 0.4 {
        score += (0.4 - waste_ratio) * 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and avoid opening new bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild progress scaling: early in stream, be slightly more conservative
    // about tight fits since more items are coming.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * progress;

    // New-bin candidate: neutral baseline with slight pressure so it is
    // chosen only when existing bins score poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits in the leftover space.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Reward tight fits, decay as slack grows.
        score -= 40.0 * (-slack / 15.0).exp();
    }
    // Next item does NOT fit in the leftover: leftover is dead space for lookahead.
    else if next_item_size > 0 && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        score += 12.0 * (1.0 - (-miss / 20.0).exp());
    }

    // Penalize leaving tiny unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect filling of the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Compare post_residual against mean residual: prefer bins whose leftover
    // ends up below average (compact usage) when fitting options are scarce.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Early in stream: be more willing to open new bins (keep bins clean),
    // late in stream: consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when many bins open or early stream,
        // less attractive late when consolidation matters.
        score -= 10.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Using an existing bin gets progressively more attractive.
        score -= 5.0 * progress;
    }

    // Slight preference for filling fuller bins first (larger item_size consumed).
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post residual as a penalty for wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Lookahead: if the next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover space: mild penalty for dead space.
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open = mean_residual;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 12.0 + 0.15 * avg_open + 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from the mean in a "fill this one" way.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // Mild preference to fill bins with small residuals first (compact them out).
    score += 0.02 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * progress * progress);

    // Penalize awkward residual sizes (dead space) via smooth bump around mid-range
    let bump = (norm_post - 0.3) * (norm_post - 0.3) - 0.09;
    score += 40.0 * bump.max(0.0) * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 30.0 * progress);

    // Lookahead: favor bins whose residual also accommodates next item
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - (post / (next_item_size as f64)).min(1.0));
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0) * (1.0 - progress);

    // New-bin candidate: keep it competitive only when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are hard to fill later; penalize dead space.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // capacity fraction remaining

    // Dead-space penalty grows super-linearly for tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Modulo-10 harmonic class: leftovers near multiples of 10 are reusable
    // since items are often near-decade sizes; reward them.
    let r = (post_residual % 10) as f64;
    score -= 6.0 * (1.0 - (r / 5.0 - 1.0).abs()); // reward r near 0 or 10

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does this bin remain useful for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // keep room for the known next item -> strong reward
            score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
            // exact two-item packing is ideal
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // bin becomes useless for the next item; penalize proportionally
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: opening fresh bins should only win early in the
    // stream or when mean residual across open bins is very tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * progress;
        if mean_residual > 0.0 && mean_residual < 0.35 * cap {
            score -= 25.0; // open bins are nearly full -> new bin attractive
        }
    }

    // Mild preference for tighter (fuller) bins overall.
    score -= 0.1 * (1.0 - frac);

    // Late-stream consolidation: prefer filling existing bins harder.
    score += 10.0 * (step_index as f64 / total_items.max(1) as f64) * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // small awkward gaps: partial penalty proportional to awkwardness
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space is worse late in the stream when fewer correction opportunities remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.4;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (i.e., make the empty-bin candidate less attractive).
    let empty_bin = bin_residual == bin_capacity;
    if empty_bin {
        score += 20.0 + open_bins_count as f64 * 3.0;
        // Opening a new bin is acceptable when current item barely fits nowhere well
        if post_residual == bin_capacity - item_size && item_size > 60 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid opening a bin.
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is already below average (tighter bins first).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly: post residual matches next item tightly
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
            if post_residual == next_item_size {
                score -= 40.0; // exact chain
            }
        } else {
            // dead space penalty scaled by how far next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.8;
        }
    }

    // Compare residual against mean residual: prefer using bins with below-average residual
    // (tighter bins) to keep loose bins flexible.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor if this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize creating small unusable gaps (< 10) unless exact fit
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Early in stream: be more conservative, prefer opening bins to build diversity
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive when few bins or late stream with poor fits
        let new_bin_bias = 30.0 - progress * 40.0 - (open_bins_count as f64) * 2.0;
        score += new_bin_bias;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can also chain
        }
    }

    // Slight preference for fuller bins as stream progresses
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize large waste relative to item size: dead space is worse for small items.
    score += (post_residual as f64) * (1.0 + item_size as f64 / bin_capacity as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving residual that the next item just barely misses.
            let miss = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            if miss < 10.0 {
                score += 4.0 * (10.0 - miss) / 10.0;
            }
        }
    }

    // Prefer bins whose residual is below the mean (consolidate fullness).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward when open bins are fragmented.
        score += 30.0 - 20.0 * progress;
        score += open_bins_count as f64 * 2.0;
        // If no open bin fits well, allow new bin.
        if post_residual as f64 > bin_capacity as f64 * 0.5 && progress > 0.3 {
            score += 10.0;
        }
    }

    // Slight penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 12.0 * pr_norm * pr_norm * (1.0 + progress)
        - 8.0 * pr_norm * progress * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 10.0 * (nx - pr) * (0.5 + progress);
        } else {
            score -= 4.0 * (pr - nx).min(30.0) as f64 / 30.0;
        }
    } else {
        score += 6.0 * pr_norm; // last item: prefer fuller bins
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild preference for bins tighter than the mean residual
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: keep neutral-ish baseline, slightly discourage early on
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 5.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness preference: smaller post_residual is better.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are multiples of common small sizes (multiples of 10) are
    // more likely to be filled by future items -> reward them.
    let post_mod = post_residual % 10;
    let post_mod_pen = if post_mod == 0 {
        -6.0
    } else if post_mod <= 2 {
        -1.5
    } else if post_mod >= 8 {
        3.0
    } else {
        post_mod as f64 * 0.6
    };
    score += post_mod_pen;

    // Dead-space penalty: residuals below the minimum item size (1) can't occur,
    // but small unusable residuals relative to typical item sizes are bad.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0; // nearly dead space
    }

    // Integer-division threshold on post_residual: classify into capacity quarters.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    let quarter_adj = match quarter {
        0 => -4.0,                       // very tight fit, great
        1 => 0.0,                        // residual 25-50
        2 => 2.0,                        // residual 50-75, wasteful
        _ => 5.0,                        // residual 75+, very wasteful placement
    };
    score += quarter_adj;

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can go here too -> reward chain placements.
            let slack = post_residual - next_item_size;
            score -= 4.0 + (slack as f64).min(20.0) * 0.1;
        } else {
            // Next item won't fit here; penalize more if the leftover is awkward.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 3.0; // near-miss, likely dead space
            } else {
                score += 1.0;
            }
        }
        // Harmonic class of next item: if next item is a multiple of 10 and
        // post_residual is a multiple of 10, strong chain bonus.
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // less attractive than a decent fit but attractive over terrible fits.
    if bin_residual == bin_capacity {
        // Neutral anchor: empty bin scores as its post_residual (capacity),
        // plus a mild openness bonus that decays as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
        // If many bins are open already, prefer packing into them.
        score += (open_bins_count as f64).min(20.0) * 0.4;
    }

    // Mean residual coupling: if this bin is far below the mean residual,
    // it's a "well-used" bin; favor finishing tight bins.
    if post < mean_residual - 10.0 {
        score -= 2.0;
    } else if post > mean_residual + 10.0 {
        score += 2.0;
    }

    // Small reward proportional to item size fraction of capacity (big items
    // placed well are valuable).
    score -= (item / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose leftover can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 5.0; // dead space for the known next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but allow opening a new bin when this would be the last chance
    // and the fit is poor.
    score += (open_bins_count as f64) * 0.35;
    if fitting_bins_count == 1 && post_residual >= 20 {
        score -= 10.0; // last-chance bin with acceptable fit
    }

    // Slight preference toward bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Mild stream-position term: as stream progresses, prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.15;

    // New-bin candidate: only attractive when item is large relative to
    // capacity and no good fit exists (post_residual here = capacity - item).
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a strong nonlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - leftover_after_next / bin_capacity as f64);
        // Extra reward for a near-perfect two-item chain.
        if leftover_after_next < 5.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize post_residual that is dead space relative to the upcoming item.
        score += 10.0 + 0.15 * post_residual as f64;
    }

    // Penalize deviation from mean residual (avoid fragmenting the bin pool).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // but relax the penalty late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 20.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / cap;
    score += 8.0 * (fit_ratio * fit_ratio) - 12.0 * fit_ratio;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is justified when the item
    // is large relative to mean residual capacity of open bins, or when open
    // bins would be left with awkward residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over the stream.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 8.0 * t;

        // Prefer new bin if item is large (hard to place later).
        score -= (item_size as f64 / cap) * 10.0;

        // If open bins are crowded (low mean residual), new bin is natural.
        score -= (cap - mean_residual).max(0.0) / cap * 6.0;

        // Lookahead: if next item is large, avoid filling current bins too much.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt > mean_residual {
                score -= 6.0;
            }
            // Keeping a bin with residual close to next item size is valuable;
            // opening a new bin preserves flexibility.
            if (bin_residual as f64 - nxt).abs() < 5.0 {
                score += 8.0;
            }
        }
    } else {
        // Placing into an open bin: penalize if it destroys capacity needed by next item.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64
            && (bin_residual as f64) >= next_item_size as f64 {
            score += 10.0;
        }
        // Reward using bins that would otherwise stay idle when many are open.
        if open_bins_count > 4 {
            score -= 2.0;
        }
        // Mild reward for keeping post-residual aligned with mean residual (balance).
        score -= 3.0 * (-((post_residual as f64 - mean_residual).abs() / cap)).exp();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: quadratic penalty on post residual (dead space), smoothly damped by progress.
    let norm_post = post / cap;
    let mut score = norm_post * norm_post * cap * (1.0 + 0.8 * progress);

    // Perfect-fit reward: smooth exponential coupling of post residual with progress.
    score -= (1.0 - norm_post).exp() * (10.0 + 15.0 * progress);

    // Interaction: post residual vs mean residual — avoid making bin worse than average.
    score += 0.15 * (post - mean_residual) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward leaving space that still fits the next item.
    if next_item_size > 0 && !is_new_bin {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 8.0 * (1.0 - ((post - nx) / cap).powf(2.0)) * (0.5 + 0.5 * progress);
        } else {
            score += 5.0 * (nx - post) / cap;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when alternatives exist; relax when current bins are fragmented.
    if is_new_bin {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 + 25.0 * progress - 20.0 * fragmentation
            + 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes are preferred (tight packing), large leftovers penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Integer-division thresholds on post_residual: leftover buckets.
    let bucket = post_residual / 10; // 0..10 harmonic class
    let bucket_penalty = match bucket {
        0 => -40.0,               // near-perfect fit
        1 => -25.0,
        2 => -12.0,
        3 => -5.0,
        4 => 0.0,
        5 => 8.0,
        6 => 15.0,
        7 => 22.0,
        8 => 30.0,
        9 => 38.0,
        _ => 45.0,                // empty bin bucket (100/10)
    };
    score += bucket_penalty;

    // Modulo arithmetic: leftover congruent to small residues pairs well with
    // common item sizes; penalize leftovers that no plausible item (1..=100)
    // can fill tightly.
    let mod_class = post_residual % 10;
    if mod_class != 0 && post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver is dead space
    }
    if post_residual >= 10 && post_residual <= 20 {
        score -= 5.0; // usable mid-small gap
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit, mild penalty for opening chain.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post {
            let gap = (post - n).abs();
            score -= 18.0 * (1.0 - gap / cap);
            if (post - n).abs() < 1.0 {
                score -= 20.0; // perfect chained fit
            }
        } else {
            score += 4.0;
        }
    } else {
        // Last item: reward consuming as much as possible.
        score -= 15.0 * (1.0 - post / cap);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when it enables a
    // great future fit or existing fits are awful.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 35.0; // fresh bin accommodates lookahead well
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: must open
        }
    }

    // Progress-aware tightening: late in the stream, prefer tighter fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post / cap);

    // Spread pressure: when many bins are open with high mean residual,
    // discourage adding yet another loose bin.
    if open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit a minimum item
    // (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps (10..20) are hard to fill; escalating penalty.
        score += 25.0;
    } else if post_residual <= 30 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness ratio: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: discourage proliferation of bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual coupling: prefer bins whose residual deviates from mean
    // toward tighter packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the known next item: dead space risk.
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // Opening a new bin while others fit: penalize, scaled by pressure.
            score += 35.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near-perfect match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 30.0 - slack as f64 * 2.0;
        }
    }
    // Next item does NOT fit here after placement: penalize leaving a gap
    // that is too small for the lookahead item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Tight fit reward: small post_residual generally good (classic best-fit),
    // but avoid tiny unusable slivers (< 10, since min item size is 1 keep mild).
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Last chance: only this bin can fit the item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual below mean residual (denser bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large or no good tight fit exists; make empty bin moderately costly
    // so tight fits in open bins win, but bad fits lose to it.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Large items relative to capacity favor a fresh bin slightly.
        score -= item_size as f64 * 0.1;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin also accommodates lookahead
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins harder.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space nonlinearly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: small residuals are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // If next item fits better here than in a fresh bin, encourage keeping it.
        if next_item_size <= post_residual && (bin_capacity - next_item_size) > post_residual - next_item_size {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: make empty bins slightly unattractive
    // unless open bins would create big waste.
    if bin_residual == bin_capacity {
        // Prefer new bin when the item is large relative to mean residual
        // (poor fits everywhere) or late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_forced = (mean_residual - item_size as f64).max(0.0);
        score += 30.0;
        score -= waste_if_forced * 1.5;
        score -= progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to mean (balance) early, diverge later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    score += 18.0 * norm_pr * norm_pr * (0.5 + p2);
    score -= 12.0 * norm_item * (1.0 - progress) * (1.0 - norm_pr);

    // reward tight fits more strongly later in the stream
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * p2);

    // lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * norm_next * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        score += 8.0 * norm_next * p2;
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * p2);
    }

    // penalize divergence from mean residual (fragmentation pressure)
    score += 6.0 * ((pr - mean_residual) / cap).abs() * (0.5 + p2);

    // mild bias against opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt() * (0.5 + p2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer-division thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries at 1/4, 1/2, 3/4 of capacity.
    let q1 = bin_capacity / 4;
    let q2 = bin_capacity / 2;
    let q3 = (3 * bin_capacity) / 4;

    // Dead-space penalty grows superlinearly for small, hard-to-fill residuals.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 25.0; // nearly perfect
    } else if post_residual <= q1 {
        score -= 8.0;
    } else if post_residual <= q2 {
        score += 4.0;
    } else if post_residual <= q3 {
        score += 12.0;
    } else {
        score += 20.0;
    }

    // Modulo-arithmetic coupling: residuals congruent to common item sizes
    // (mod 10 grid) are more likely reusable later.
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0; // round residual aligns with item grid
    } else if m <= 3 {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score -= 18.0; // chains two near-perfect fits
            } else {
                score -= (leftover as f64).ln() * 3.0;
            }
        } else {
            score += 6.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit,
    // avoiding a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are all poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64).min(10.0) * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item: fresh bin is attractive
        }
    }

    // Prefer tighter bins overall: compare against mean residual.
    score += (pr - mean_residual) * 0.15;

    // Late in the stream, favor closing bins tightly (small residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized,
    // but an exact fit (post_residual == 0) is rewarded strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 12 {
        score += (13 - post_residual) as f64 * 6.0;
    }

    // Reward leaving gaps that can still host a typical future item.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits into the resulting gap, this is a great placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap is stranded relative to the known next item.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin (bin_residual == bin_capacity) unless no decent fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Slight relief late in the stream when many bins are open anyway.
        score -= (open_bins_count as f64).sqrt() * 1.5;
    }

    // Mild open-bin pressure: spreading load reduces future fragmentation.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is close to the item (tight fits).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (low post residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Penalize dead space that can never be reused by typical items (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap
    }

    // Aggressive 2-step lookahead: reward bins whose post residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual as f64 == next_item_size as f64 {
            score -= 500.0; // perfect chain: next item exactly fills this bin
        } else if next_item_size as u32 <= post_residual {
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 2.0 * (mean_residual - resid_f);
    } else {
        score += 1.0 * (resid_f - mean_residual);
    }

    // Last-chance logic: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; offset slightly if many items remain
        score += 250.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_f = item_size as f64;
        // opening a fresh bin is attractive for large items early (keeps big residual flexible)
        score -= 100.0 * progress;
        if item_f > 0.5 * bin_capacity as f64 {
            score -= 50.0;
        }
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 30.0; // fresh bin can also chain with next item
        }
    }

    // Mild preference for filling existing bins as stream progresses.
    score -= 0.01 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize dead space: residuals too small to be useful later.
    if post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    } else if post_residual > 80 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: check whether next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chain placement possible
        } else {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // New-bin candidate handling: prefer new bin when open bins are crowded.
    if bin_residual == bin_capacity {
        let avg_fit_gap = mean_residual - item_size as f64;
        if avg_fit_gap < 5.0 && fitting_bins_count > 0 {
            score -= 20.0 * progress; // open fresh bin late in stream
        } else {
            score += 15.0; // default penalty to avoid bin explosion
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty when this bin deviates strongly from mean residual
    // (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space super-linearly as stream progresses
    score += 25.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with a smooth decay term
    score -= 30.0 * (-norm_pr * 6.0).exp() * (1.0 - 0.5 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so open bins are preferred unless fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * norm_pr * progress;
        // Opening a new bin is attractive if next item would fit the fresh residual
        if (next_item_size as f64) <= cap * 0.5 {
            score -= 8.0 * progress;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).abs() * (1.0 + progress);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= next_item_size as u64 { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * (1.0 - progress);
    }

    // Slight scaling with open bins to encourage consolidation
    score *= 1.0 + 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (small divisors) are more reusable; penalize prime/large dead space.
    let pr = post_residual;
    if pr > 0 {
        let mut reusability = 0.0f64;
        for &d in &[1u32, 2, 4, 5, 8, 10, 16, 20, 25, 32, 40, 50] {
            if pr % d == 0 {
                reusability += 2.0;
            }
        }
        score -= reusability;

        // Integer-division thresholds: dead space below the smallest item (1)
        // is worthless; below typical mid sizes is near-worthless.
        if pr < 10 {
            score += 40.0; // unusable sliver
        } else if pr < 25 {
            score += 10.0;
        }

        // Fraction of capacity wasted, quadratic penalty on large waste.
        let waste_frac = pr as f64 / cap;
        score += 30.0 * waste_frac * waste_frac;
    } else {
        score -= 25.0; // perfect closure
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Harmonic bonus if post_residual mod next_item_size leaves a small tail
        let tail = post_residual % next_item_size;
        if tail == 0 {
            score -= 12.0;
        } else if tail < 10 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Creating dead space the next item cannot use
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).min(cap));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Prefer the tightest among many candidates (implicit via post_residual),
        // slight penalty to spread preference toward fuller bins.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate logic: an empty bin is only attractive when open bins
    // have poor fit quality; make the empty bin expensive by default.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.5);
        score += 55.0 + 8.0 * pressure;
        // Late in the stream, opening fresh bins is cheaper long-term.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
    }

    // Mild normalization toward mean residual state.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit heavily rewarded
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits: post_residual close to zero relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Penalize opening a new bin when open bins could fit, unless it's the last chance
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / 8.0;
        score += 25.0 + pressure * 10.0;
        if fitting_bins_count <= 1 {
            score -= 45.0; // last chance: new bin is fine
        }
    }

    // Dead space penalty amplified when bin pressure is low (few bins open)
    score += (post_residual as f64) * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0))) * 0.5;

    // Lookahead: prefer bins leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match of next item into post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as u32 <= post_residual {
            // next item fits: reward small remaining slack after it
            score -= (post_residual as f64 - next_item_size as f64) * 1.5;
            score -= 5.0; // bonus for keeping chain going
        } else {
            score += gap * 0.8; // penalize wasted potential
        }
        // near-perfect two-item fill
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // last item: prefer minimal post residual
        score += (post_residual as f64).powi(2) * 0.01;
    }

    // Relative tightness vs mean residual: tighter-than-average bins preferred
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize new-bin opening unless residual is large / poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size <= bin_capacity / 2 {
            score += 15.0; // avoid wasting fresh bins on small items
        }
    }

    // Penalize tiny dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Early stream: be slightly greedy with tight fits to keep options open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    }
    // Penalize leaving a gap just below the next item (awkward dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Last chance: strongly favor the only bin that fits, to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins that are already relatively full (small residual relative to mean).
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let tightness = item_size as f64 / bin_capacity as f64;
        // New bin is attractive only for very large items or late in the stream
        // with many open bins (dispersion strategy).
        let new_bin_bonus = tightness * 60.0 + progress * 10.0
            - open_bins_count as f64 * 1.5;
        score += 30.0 - new_bin_bonus;
        // A new bin perfectly hosts the next item too.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild penalty for very small leftover slivers (< 10, unusable for min item size 1..100 unknown,
    // but tiny gaps waste capacity).
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space matters more as it becomes unusable
    let unusable = (post / cap).powi(3);
    score += 25.0 * unusable;

    // Tight fit reward (smooth): residual consumed fraction
    let fit_frac = item_size as f64 / bin_residual as f64;
    score -= 12.0 * (fit_frac * fit_frac);

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post;
        if next_fits {
            score -= 8.0 + 10.0 * (1.0 - post / cap);
        } else {
            score += 4.0 * (next_item_size as f64 / cap);
        }
    }

    // Prefer bins below mean residual (consolidate waste)
    score += 3.0 * (post - mean_residual) / cap;

    // New-bin candidate: penalize opening a bin unless current bin would be nearly empty
    if bin_residual == bin_capacity {
        let escape_bonus = if fitting_bins_count <= 1 { 0.0 } else { 10.0 };
        score += 15.0 + escape_bonus - 5.0 * progress;
    }

    // Mild preference for existing bins as stream progresses
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space vs reusable space
    let pr = post_residual;
    // Class A: post_residual is 0 -> perfect fit, huge reward
    if pr == 0 {
        score -= 200.0;
    }
    // Class B: post_residual is a "small dead zone" (1..=9) -> penalize
    if pr >= 1 && pr <= 9 {
        score += 15.0;
    }
    // Class C: post_residual divisible by 10 -> clean reusable chunk
    if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    }
    // Class D: post_residual >= 50 -> half-empty, still very usable
    if pr >= 50 {
        score -= 20.0;
    }

    // Lookahead: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here -> reward, scaled by tightness of that fit
            let future_fit = (pr - next_item_size) as f64;
            score -= 30.0 - 0.2 * future_fit;
            // harmonic bonus if next fit is exact or near-exact
            if pr == next_item_size {
                score -= 60.0;
            } else if (pr - next_item_size) <= 5 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            let gap = (next_item_size - pr) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless the fit is bad; but if mean residual is low
    // (open bins nearly full), opening a new bin is attractive.
    if bin_residual == bin_capacity {
        score += 25.0;
        let mean_res_frac = mean_residual / cap;
        if mean_res_frac < 0.25 {
            score -= 30.0; // open bins are nearly full -> open new bin
        }
    }

    // Large items should prefer tight fits: penalize loose residual for big items
    if item_size > 60 {
        score += 0.4 * (post_residual as f64);
    } else if item_size < 25 {
        // small items: prefer filling bins with large residuals
        score -= 0.1 * (bin_residual as f64);
    }

    // Stream progression: early on, be more willing to open bins (spread items);
    // late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty when many bins are open: encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual > 50 {
        // large residual left means item was small relative to bin; mild penalty
        score += 6.0;
    }

    // Reward tight fits (post_residual small but nonzero).
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last chance: only one bin can fit this item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly.
        score += open_bins_count as f64 * 4.0;
        score += 15.0;
        // If lookahead item is large, opening a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
        // Avoid opening new bins early in the stream.
        score -= (step_index as f64 / (total_items as f64).max(1.0)) * 10.0;
    } else {
        score -= open_bins_count as f64 * 1.5;
    }

    // Prefer bins whose residual deviates from the mean (consolidate space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Lookahead coupling: if next item could use this bin's leftover, reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 20 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // Strong reward when post_residual exactly matches the next item size.
    if next_item_size > 0 {
        let diff = (post - nxt).abs();
        score -= 60.0 * (1.0 - diff / cap).max(0.0);
        // Extra bonus for perfect match.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residual just barely too small for the next item (dead space).
        if post < nxt {
            score += 20.0 * (nxt - post) / cap;
        }
    }

    // Relative-to-mean coupling: prefer bins whose resulting residual is near the mean.
    score += (post - mean_residual).abs() * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless it enables
    // a perfect lookahead match or few bins fit the item.
    if bin_residual == bin_capacity {
        score = cap + 10.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 80.0;
        } else if fitting_bins_count == 0 {
            score -= 90.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score -= 20.0; // mild preference to keep existing bin
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for creating very small unusable slivers.
    if post > 0.0 && post < 10.0 {
        score += 15.0 - post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: prefer tight fits (low post-residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Lookahead: penalize residuals that cannot host the next item (dead space),
    // reward residuals that can still host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 4.0 + 0.5 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large or existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
        let _ = poor_fit;
        // Penalize new bins mildly; discount penalty when item is large or
        // mean residual is high (existing bins fragmented).
        let mut new_bin_score = 10.0
            - 6.0 * (item_size as f64 / bin_capacity as f64)
            - 3.0 * ((mean_residual / bin_capacity as f64).clamp(0.0, 1.0))
            - 2.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score += 3.0;
        }
        score = new_bin_score;
    }

    // Slight preference for bins already below mean residual (consolidation).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly * cap;
    // Tight fits are rewarded quadratically
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (item / cap);
    // Penalize dead space relative to mean residual
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }
    // Mild penalty for spreading across many bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * 0.01;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes.
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Penalize residuals that fall into "dead" classes: small unusable slivers.
    if post > 0 && post < 10 {
        score += 60.0; // worst class: nothing can ever fit (items >= 1... still tiny)
    } else if post >= 10 && post < 20 {
        score += 25.0;
    } else if post >= 20 && post < 35 {
        score += 8.0;
    } else if post == 0 {
        score -= 40.0; // perfect packing reward
    } else {
        // Good class: residual large enough to host a typical item
        score -= 10.0;
    }

    // Harmonic alignment: reward residuals that are multiples of common size classes.
    if post % 10 == 0 && post > 0 {
        score -= 12.0;
    } else if post % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // extra reward for exact-ish fit of the lookahead item
            let slack = post_residual - next_item_size;
            if slack < 5 {
                score -= 15.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) - 0.5; // >0 means fragmented open bins
        if fragmentation > 0.15 && post_residual as f64 > mean_residual {
            score -= 45.0; // open fresh bin when existing residuals are poor
        } else {
            score += 35.0; // discourage wasteful new bins
        }
    }

    // Late in the stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    // Mild tie-break: prefer fuller bins (smaller residual before placement).
    score += (bin_residual as f64 - item_size as f64) * 0.05;
    // Prefer bins below mean residual (i.e., tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize unusable dead space quadratically.
        let dead = post_residual as f64;
        score += 0.35 * dead * dead / bin_capacity as f64;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // next item likely forces a new bin
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure on number of open bins: prefer filling existing bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (concentrate packing).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Mild penalty for opening a brand-new bin when other bins could fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if stream is late and bins are crowded, new bin is less bad.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this placement chains two items into one bin — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    }
    // Next item fits into post residual: mild reward proportional to tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 50.0 * (1.0 - tightness);
    }
    // Next item cannot fit: the leftover is likely dead space — penalize
    // small-but-unusable residuals more than large ones.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average
    // (best-fit flavor), penalize bins looser than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Progression: later in the stream, be more conservative about leaving
    // large residuals (fewer chances to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.3;

    // Many open bins: encourage consolidation into existing bins over new bins.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large relative to capacity or no good fit exists; otherwise keep it
    // expensive so existing bins are preferred.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item || next_item_size == 0 {
            score += 150.0; // still slightly worse than a decent fit
        } else {
            score += 250.0; // strongly discourage opening new bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit even the smallest plausible item is worthless.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        score += 8.0; // residual too small for the lookahead item: dead space
    }

    // Lookahead synergy: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins unless current
    // bins would leave large waste or the stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 18.0 + 20.0 * progress;
        // Early stream with few bins: opening bins is cheap, allow exploration.
        if step_index < 20 && open_bins_count < 4 {
            penalty -= 15.0;
        }
        // If mean residual is large, open bins are roomy; discourage new bin.
        penalty += mean_residual * 0.1;
        score += penalty;
    }

    // Prefer bins below mean residual (consolidating emptier space is wasteful;
    // filling tighter bins keeps large residuals available for big items).
    score += (bin_residual as f64 - mean_residual) * -0.05;

    // Mild normalization by post_residual relative to capacity to break ties
    // toward fuller bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post residual value decays with progress
    score *= (1.0 + 0.5 * (1.0 - progress) * norm_pr);

    // Cubic waste penalty for small post residuals (dead space)
    score -= 8.0 * (1.0 - norm_pr).powi(3);

    // Reward tight fits more strongly late in the stream
    score -= progress * (item_size as f64 / cap) * 6.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * progress;
    }

    // Lookahead: prefer bins leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_quality = 1.0 - ((pr - ns) / cap).abs();
            score -= 3.0 * fit_quality * (1.0 - progress);
        } else {
            score += 2.0;
        }
    }

    // Mild dispersion penalty: discourage bins far from mean residual
    score += 0.05 * (pr - mean_residual).abs();

    // Prefer consolidating into fewer bins as stream progresses
    score += 0.3 * (open_bins_count as f64) * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how close is leftover to a "useful" residue class
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction of leftover

    // Reward small post_residual (tight fit) super-linearly
    score -= 40.0 * (1.0 - frac).powi(3);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // next item can't go here: dead space penalty, scaled by how close we were
            score += 25.0 * (1.0 - post / nxt.max(1.0));
        } else {
            // next item fits: reward chaining, stronger when post_residual is a near-exact multiple class
            let k = (post / nxt).floor();
            let waste = post - k * nxt;
            score -= 15.0 * (1.0 - waste / nxt.max(1.0));
        }
    } else {
        // last item: strongly prefer tightest packing
        score -= 60.0 * (1.0 - frac);
    }

    // Integer-division threshold classes on post_residual (harmonic bands)
    let band = post_residual / 10; // which decade band the leftover falls in
    match band {
        0 => score -= 20.0,                 // almost full bin: excellent
        1 => score -= 5.0,                  // good
        2 => score += 3.0,                  // moderate leftover
        3 => score += 8.0,                  // awkward ~30 leftover
        4 => score += 2.0,                  // 40 is a usable class (fits mid items)
        5 => score += 6.0,
        _ => score += 0.0,
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current leftovers are all bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // allow new bin when open bins are fragmented (high mean residual with many bins)
        score -= 10.0 * (mean_residual / cap) * (open_bins_count as f64).sqrt().min(3.0);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Slight phase modulation across the stream (harmonic step coupling)
    let phase = (step_index as f64 / total_items.max(1) as f64) * std::f64::consts::PI;
    score += 2.0 * phase.sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    }

    // Reward near-perfect fits (very small waste) so tight bins get priority
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer filling bins with small residuals relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64).min(30.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer new bin only if fits are bad
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * 8.0;

    // New-bin candidate: neutral-ish baseline; open a new bin only when it beats poor fits
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the next item could use this item's leftover, opening a new bin is fine
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - pressure);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins where the leftover after this
    // placement can exactly (or nearly) host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: post residual exactly consumed by next item.
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Smaller slack after next item's fit is better; penalize residual slack.
            score += slack * 0.35;
            // Reward chains that land in a small dead zone (<= 10 unusable).
            if post_residual <= next_item_size + 10 {
                score -= 15.0;
            }
        } else {
            // Next item cannot follow into this bin; penalize proportionally
            // to how much the next item overshoots the post residual.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.6;
        }
    }

    // Compare post residual against mean residual across open bins:
    // leaving less than average residual concentrates waste (good),
    // leaving far more than average wastes capacity (bad).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize tiny dead spaces that nothing (min size 1, typically >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins
    // (more future items to chain); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= (1.0 - progress) * 25.0 - 12.5;
    } else {
        // Prefer reusing existing bins as the stream matures.
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Reward filling a bin nearly full (post_residual small relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward leaving that residual; otherwise penalize residuals that are too
    // small to be useful for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = (post_residual as f64 - nxt).abs();
            score -= 3.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Residual too small for next item: dead space penalty grows as
            // residual approaches zero.
            score += 4.0 * (1.0 - post_residual as f64 / nxt);
        }
    } else {
        // Last item: prefer perfect closure.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor new bins less,
    // keep residual spread healthy); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fill_ratio;

    // Global state: if many bins are open with high mean residual, encourage
    // consolidation into existing bins; if mean residual is low, opening a new
    // bin is relatively cheaper.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.02 * mean_gap * (open_bins_count as f64).ln().max(1.0);

    // Penalize opening a brand-new bin when decent fits exist, scaled by how
    // full the stream already is.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress;
        // But if nothing fits well (post_residual would be tiny in existing bins),
        // the new-bin penalty is offset by the natural waste penalties above.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 4.0;
        }
    }

    // Small bonus for exact fit.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr_norm * (1.0 + 0.8 * progress * pr_norm)
        + 0.35 * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits, stronger late in the stream
    score -= 0.5 * (1.0 - pr_norm) * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 0.6 * (1.0 - pr / nxt.max(1.0)) * (1.0 + progress);
        } else {
            score -= 0.25 * (pr / cap) * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2;
    }

    // Mild pressure toward consolidating into fewer bins
    score += 0.02 * open_bins_count as f64 * pr_norm;

    // Slight preference for bins already below-average residual (well-packed)
    score -= 0.1 * ((mean_residual - pr) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead space" classes are penalized, "usable" classes rewarded.
    let pr = post_residual;
    let class = match pr {
        0 => 0u32,           // perfect fit
        1..=5 => 1,          // near-perfect, tiny dead space
        6..=15 => 2,         // awkward small gap
        16..=30 => 3,        // medium gap, still usable for mid items
        _ => 4,              // large gap, very reusable
    };
    match class {
        0 => score -= 60.0,
        1 => score -= 35.0,
        2 => score += 25.0,
        3 => score -= 5.0,
        _ => score -= 20.0,
    }

    // Modulo-10 harmony: residual divisible by 10 aligns with typical item
    // granularities, making the leftover reusable.
    if pr > 0 && pr % 10 == 0 {
        score -= 12.0;
    }
    // Half-capacity harmonic: leftover near C/2 or C/4 is highly reusable.
    let half = bin_capacity / 2;
    let quart = bin_capacity / 4;
    if (pr as i32 - half as i32).abs() <= 3 {
        score -= 18.0;
    }
    if (pr as i32 - quart as i32).abs() <= 3 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists among
    // open bins; penalize opening new bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        score += 55.0 + 30.0 * (1.0 - progress) + 4.0 * openness;
        // But if mean residual is small (all bins nearly full), new bin is fine.
        if mean_residual < 15.0 {
            score -= 70.0;
        }
    }

    // Mild preference for tighter bins (smaller residual before placement).
    score += bin_residual as f64 * 0.05;

    // Late-stream consolidation: prefer reusing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && pr > 0 {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    } else {
        // Larger residual is mildly penalized as wasted space, but scaled by
        // whether the gap could plausibly hold future items (>= 10).
        score += 0.15 * post_residual as f64;
    }

    // Reward bins whose residual after placement still fits the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that cannot host the next item: mild penalty.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 40.0 + 6.0 * open_bins_count as f64;
        // Opening a new bin is acceptable if the item is huge and would leave
        // a dead gap in any existing bin.
        if item_size >= 80 && post_residual < 10 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    } else {
        // Prefer filling bins that are already relatively empty (balance residuals).
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * diff;
    }

    // Slight preference for tighter current fits.
    score -= 0.2 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // next item will close this bin exactly
        } else if post_residual > next_item_size {
            score -= 8.0; // next item still fits after placement
            // tighter coupling: closer next item is to post_residual, better
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit: penalize wasted residual
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize small unusable residuals (dead space)
    if post_residual < 10 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than average residual (good fits)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Penalize opening a new bin when open bins exist and fit reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual > 20 {
        score += 30.0;
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && progress > 0.7 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits: normalized fill ratio
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize leaving dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: favor bins whose post-residual can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 8.0;
        }
    } else {
        // last item: strongly prefer perfect fits
        score -= 20.0 * fill;
    }

    // Last-chance bin: strongly prefer using it before opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: early stream, be conservative (favor new bins less);
    // late stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> consolidate
    let mean_res_norm = mean_residual / bin_capacity as f64;
    if bin_residual as f64 > mean_residual {
        score += 5.0 * mean_res_norm;
    } else {
        score -= 5.0 * (1.0 - mean_res_norm);
    }

    // New-bin candidate: penalize opening a bin when good fits exist elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // early stream: opening bins is cheaper (builds diversity)
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for many competing fitting bins (prefer scarcity)
    score += (fitting_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let poly = 0.5 + 0.9 * progress - 1.3 * p2 + 0.7 * p3;

    // Base: penalize large post_residual, scaled by progress-dependent factor.
    let mut score = pr * poly;

    // Smooth interaction: normalized post-residual coupled with item size.
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (item / cap) * (1.0 + progress);

    // Reward tight fits with smooth decay term.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness * (1.0 + 0.5 * progress);

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = pr - nxt;
        if fit_gap >= 0.0 {
            score -= 6.0 * (1.0 - fit_gap / cap) * (0.4 + 0.6 * progress);
        } else {
            let gap = -fit_gap;
            score += 4.0 * (gap / cap) * (gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: smooth urgency bonus via sigmoid-like term.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 / (1.0 + (-3.0 * (progress - 0.5)).exp()));
    }

    // Penalize opening new bins when many bins exist and residual is large.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Mild coupling with mean residual to discourage fragmenting when mean is high.
    score += 0.03 * (mean_residual - pr).abs() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 bands.
    let band = (post_residual * 10 / bin_capacity) as f64;
    score += band * 2.0;

    // Reward near-perfect fills (post_residual in tiny classes).
    if post_residual <= 2 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space class: residuals that few future items can use (modulo classes).
    let small_class = (post_residual % 10) as f64;
    score -= small_class * 0.3; // residuals just below a decade are more reusable

    // Penalize residual in the "hard" zone 51..=70 (hard to pair later).
    if post_residual >= 51 && post_residual <= 70 {
        score += 8.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here regardless; slight penalty for tight bins
            score += (next_item_size - post_residual).min(20) as f64 * 0.1;
        }
        // Harmonic class of next item: large next item -> keep bins flexible
        let next_class = next_item_size / 20;
        score += next_class as f64 * 1.5;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when item is large
    // or all open bins are very full (mean residual small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = 30.0 + item_frac * 40.0 - mean_residual * 0.3 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big items coming, fresh bin useful
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead space" -> heavy penalty.
    // Treat residuals < 10 as fully wasted (worst possible outcome).
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: penalize heavily on top of the small raw value.
        score += 25.0 * (10.0 - post_residual as f64);
    } else {
        // Usable residual: mild reward for larger usable leftover,
        // but only up to a point (very large leftovers are also wasteful).
        let r = post_residual as f64;
        // reward usable leftovers that can host a lookahead item
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > 0 {
            // lookahead does not fit: this residual risks becoming dead space
            score += 6.0;
        }
        // gently prefer moderate residuals over huge ones
        score += 0.05 * (r - mean_residual).abs();
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin should only win if it enables a perfect fit
        // while no open bin can do so.
        if post_residual == 0 && fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            score += 15.0 + 3.0 * open_bins_count as f64;
        }
    } else {
        // Reward using existing bins, especially when choices are scarce.
        if fitting_bins_count == 1 {
            // Last chance before opening a new bin: strong bonus.
            score -= 20.0;
        } else {
            score -= 2.0;
        }
    }

    // Mild stream-progression coupling: later in the stream, waste matters
    // slightly more since fewer items remain to fill gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (tight fit signal).
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // 2-step lookahead: perfect match where next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain completion: bin becomes exactly full
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how much it consumes
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * frac * frac;
        } else {
            // next item does NOT fit the post-residual: penalize wasted residual
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins with residual below mean
    // (consolidate space), penalize bins already tighter than average when
    // post-residual would become tiny/unusable.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless the
    // current item is large or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // penalize opening a new bin, but less when the item is big
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - size_frac);
        if next_item_size > 0 && post_residual == 0 {
            score -= 40.0; // item exactly fills a fresh bin
        }
    }

    // Late-stream pressure: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Small residual (<10) is dead space for future items (min size 1..100, but
    // typical small items still benefit) - mild penalty scaled by waste.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post residuals relative to capacity
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 200.0 * (1.0 - tightness * tightness);
    }

    // Penalize dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny slivers are wasted
    }

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 30.0;
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins are poor fits or we're late in the stream with few bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // new bin is attractive when mean residual is large (fragmented state)
        score += 120.0 - 180.0 * pressure + 50.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // room for a follow-up item in a fresh bin
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (tight fits preferred).
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress.
    // Late in the stream, dead space matters more; early, flexibility matters.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) - norm_pr * (1.0 - t);
    score += 30.0 * poly;

    // Reward last-chance bins (fitting_bins_count == 1) smoothly.
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 15.0 * fit_quality * (0.5 + 0.5 * t);
    }

    // Penalize bins deviating from mean residual (keep balance).
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate: mildly penalize so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: dead space below 10 is essentially waste-free.
    if post_residual < 10 {
        score -= 25.0;
    }

    // Harmonic class of the leftover: multiples of 10 pair well with common sizes.
    let pr = post_residual as i64;
    let class = pr % 10;
    if class == 0 && pr > 0 {
        score -= 6.0; // clean decade leftover, reusable
    } else if class >= 7 {
        score += 4.0; // awkward sliver (7-9 units) is near-dead space
    }

    // Lookahead coupling: strongly reward bins where the next item also fits.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 18.0;
            if (slack_after_next as i64 % 10) == 0 && slack_after_next < 10 {
                score -= 8.0; // perfect two-item chain
            }
        } else {
            // Next item won't fit here; penalize proportionally to how much
            // of the leftover would be stranded.
            let stranded = (post_residual as f64) / (bin_capacity as f64);
            score += 10.0 + 15.0 * stranded;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (residual == capacity): make it lose against any decent fit,
    // but win when existing bins are all poor. Base penalty:
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream or with many open bins, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            // some open bin can hold it; new bin should rarely win
            score += 8.0;
        }
        // If next item is huge and nothing else fits, a fresh bin is actually good.
        if next_item_size > 60 {
            score -= 14.0;
        }
    }

    // Mild pressure to fill bins deeper when many bins are open.
    if open_bins_count > 4 {
        score -= (post_residual as f64) * 0.05 * ((open_bins_count as f64).ln() + 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable" zone
    // (small gaps that few items can fill) is heavily penalized.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect or near-perfect fills are strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward tight fits relative to the bin's remaining space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 10.0;

    // Pressure from number of open bins: discourage spreading across too
    // many bins, but allow opening a new bin when existing residuals are
    // poor fits (mean residual much larger than item).
    score += open_bins_count as f64 * 0.8;

    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well.
        if fitting_bins_count > 0 && (mean_residual - item_size as f64).abs() < 15.0 {
            score += 40.0;
        } else if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item would fit the post-residual nicely,
    // reward this placement (chaining good fits).
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
        score -= 8.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 4.0; // dead space the next item cannot use
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // close to the current item (leaves balanced space).
    score += (mean_residual - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fit (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits again: penalize leaving a gap that wastes capacity
            // proportional to how much space would remain after the next item.
            let second_residual = post_residual - next_item_size;
            score += second_residual as f64 * 1.5;
            if second_residual <= 10 {
                score -= 40.0; // still a tight chain, mildly good
            }
        } else {
            // Next item cannot reuse the residual: dead space penalty scaled
            // by how badly it misses (unusability of the gap).
            let gap_miss = (next_item_size - post_residual) as f64;
            score += gap_miss * 0.8;
        }
    }

    // Penalize bins whose residual deviates strongly above mean residual
    // (relatively empty bins should be filled by larger items instead).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin unless the item truly fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 50.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 30.0; // fresh bin less attractive if lookahead can't chain perfectly
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // pairing bonus: item + next nearly fill the bin
        if item_size + next_item_size >= bin_residual.saturating_sub(0) && post_residual <= 10 {
            score -= 60.0;
        }
    } else {
        // last item: just fill tightest
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // more open bins with slack => less eager to open new one
        score += open_bins_count as f64 * 2.0;
        if mean_residual > (item_size as f64) {
            score += 30.0;
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
    }

    // Favor bins whose residual is below the mean (tighter bins first)
    score += ((mean_residual - bin_residual as f64) * 0.3).clamp(-40.0, 40.0);

    // Mild penalty for very large leftovers that few items can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + progress) + pr_norm * (1.0 - progress) * 0.3;
    score += coupling * 20.0;

    // Penalize near-full residuals late in the stream (dead space)
    let tight = ((bin_capacity as f64 - pr) / bin_capacity as f64).powi(3);
    score -= tight * 15.0 * (0.5 + progress);

    // Reward tight fits strongly as stream progresses
    if post_residual < item_size / 2 + 2 {
        score -= 10.0 + 20.0 * progress;
    }

    // Last-chance bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: prefer bins whose post_residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Penalize spreading across too many open bins
    score += open_bins_count as f64 * 0.05;

    // Bias toward fuller bins relative to mean residual
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    // New-bin candidate: mildly discouraged unless residual would be very poor elsewhere
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: 4 classes by capacity fraction thresholds
    let item_class = (item_size * 4) / bin_capacity; // 0..3
    let next_class = (next_item_size * 4) / bin_capacity;

    // Reward tight fits: small post_residual is good, but dead space
    // below the smallest item class is worthless.
    if post_residual < 10 {
        score -= 25.0; // perfect/near-perfect fit
    } else if post_residual < 20 {
        score -= 12.0;
    } else {
        // penalize post-residuals that no future item can use well
        let unusable = if post_residual > 80 { 0.0 } else { 3.0 };
        score += unusable;
    }

    // Complementarity: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= (gap.min(40)) as f64 * 0.15;
        }
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: penalize mildly unless bin nearly full
        score += 4.0;
        if next_class >= 2 && post_residual > 30 {
            score += 5.0;
        }
    }

    // Class pairing logic: large items pair with small leftovers
    match (item_class, next_class) {
        (3, 0) | (3, 1) => score -= 6.0,  // big item then small follower: good
        (0, 3) => score += 6.0,           // small item before big one: risky
        _ => {}
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // open bins are crowded or the fit here is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score = cap * 0.55 + pressure * 2.0;
        if item_size > bin_capacity / 2 {
            score -= 8.0; // big items like a fresh bin
        }
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Slight preference for filling bins with larger mean residual (cleanup)
    score -= (mean_residual / cap).min(1.0) * 2.0;

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual.min(50) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the minimum plausible item size,
    // scaled by stream position (later in the stream, gaps matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_gap = 10.0 + 10.0 * progress;
    if post_residual > 0 && (post_residual as f64) < min_gap {
        score += (min_gap - post_residual as f64) * 3.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Moderate residual that could still accept typical items is mildly rewarded.
    if post_residual >= 40 {
        score -= 5.0;
    } else if post_residual >= 20 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item does NOT fit post residual, penalize slightly (dead end).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Open-bin pressure: discourage spreading across too many bins,
    // but relax pressure when this is the last fitting bin (avoid new bin).
    let pressure = (open_bins_count as f64).ln() * 2.0;
    if fitting_bins_count == 1 {
        score -= pressure * 0.5 + 6.0;
    } else {
        score += pressure;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins get filled first, keeping looser bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no good fit exists (large items are hard to place later).
    if bin_residual == bin_capacity {
        let large_item = item_size > 60;
        let poor_fit = fitting_bins_count <= 1;
        if !(large_item && poor_fit) {
            score += 30.0 + 20.0 * (1.0 - progress);
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.35 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space penalty scaled by how "wasted" the leftover is
        score += 0.15 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize post_residual relative to mean residual (prefer tight fits vs. average)
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // small unusable sliver penalty
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big item followed by bigger one: fresh bin may help
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Tightness: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Global state: penalize opening new bins when mean residual across open
    // bins is already large relative to item size.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 5.0 + 0.1 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
    } else {
        score -= 3.0;
    }

    // Time horizon: early in the stream, be more exploratory (favor new bins
    // slightly); late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score -= (1.0 - progress) * 8.0;
    } else {
        score += progress * 4.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post_norm * (1.0 + 0.8 * progress) - 0.9 * post_norm * post_norm * (1.0 + progress);

    // Reward tight fits (small post_residual), more strongly later in the stream
    let mut score = post + 30.0 * poly * cap * 0.01;

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (post - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Mild penalty on opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify leftover into modulo buckets.
    // Leftovers divisible by 10 (common size quantum) are "reusable" classes.
    let class = post_residual % 10;
    if class == 0 {
        score -= 25.0; // residual lies on the size grid -> likely reusable
    } else if class <= 3 {
        score += 18.0; // tiny dead space class -> penalize
    } else if class >= 7 {
        score += 8.0;  // awkward large-but-not-quite class
    }

    // Integer division thresholds: residual >= 40 is a "big room" class.
    if post_residual / 40 >= 1 {
        score -= 12.0;
    } else if post_residual / 20 >= 1 {
        score -= 4.0;
    } else {
        score += 10.0; // residual < 20 -> nearly dead space
    }

    // Lookahead: does next_item_size fit in post_residual? (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or well here -> reward
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 60.0; // perfect two-step packing
            } else {
                score -= 10.0 + (slack as f64).min(20.0);
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = next_item_size - post_residual;
            score += (over as f64) * 0.5;
            // but if post_residual too small anyway, this bin is nearly closed
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: only one bin can fit this item -> strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity elsewhere.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins fit poorly and mean residual is low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let penalty = 40.0 + mean_residual * 0.8 - poor_fits * 60.0 - progress * 10.0;
        score += penalty;
    } else {
        // Mild preference to reuse existing bins when they are below mean residual
        // (balances residual spread across bins).
        if (post_residual as f64) < mean_residual {
            score -= 6.0;
        }
        // Congestion: many open bins -> prefer consolidating into fuller ones.
        if open_bins_count > 4 {
            score += (post_residual as f64) * 0.1;
        }
    }

    // Fractional capacity coupling: item relative to capacity.
    let item_frac = item_size as f64 / bin_capacity as f64;
    if item_frac > 0.7 {
        // large items: place them where they leave least wreckage
        score += (post_residual as f64) * 0.3;
    } else if item_frac < 0.25 {
        // tiny items: keep them for filling small residuals
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current bin creates bad dead space
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Pressure from many open bins: prefer filling existing bins
    score += 0.3 * open_bins_count as f64;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good fill
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear dead-space penalty.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 0.5);
    } else {
        score -= 40.0; // perfect fit reward
    }

    // 2-step lookahead coupling: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain-perfect placement
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64) * 0.35;
        } else {
            // next item won't fit in this bin's leftover: penalize proportionally
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.6;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are more "committed";
    // filling them further is good (consolidate fragmented space).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.25;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Late-stream consolidation: as stream progresses, avoid spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + (post_residual as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit even the smallest plausible item (size 1) is pure waste.
    if post_residual == 0 {
        score -= 30.0; // perfect fit: strong reward
    } else if post_residual < 5 {
        score -= 15.0;
    }

    // Penalize large post_residual more when many bins are open (fragmentation).
    let frag = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += frag * 40.0 * (1.0 + open_bins_count as f64 / 10.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // If next item nearly fits (miss by small margin), mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Global balance: prefer bins whose residual is close to the mean residual
    // (keeps the pool homogeneous), unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, prefer tighter packing (bigger rewards
    // for small post_residual) since fewer chances remain to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (20.0 - post_residual as f64).max(0.0) * 0.5;

    // New-bin candidate handling: an empty bin is a costly escape hatch.
    // Prefer it only when it genuinely beats using an open bin, i.e. when
    // item is large relative to residual and no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual > 0 && post_residual < item_size / 2);
        if large_item || poor_fit {
            score -= 10.0; // opening a fresh bin is reasonable
        } else {
            score += 25.0; // discourage wasteful new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (low post residual), non-linearly.
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling: residual waste weighted by stream progress.
    score += 18.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize large residuals more as the stream matures (dead space matters later).
    score += 25.0 * progress * norm_pr * norm_pr * norm_pr;

    // Reward near-perfect fills with a smooth bump around small residuals.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * tightness * tightness;

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * norm_item;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr as u32).abs_diff(next_item_size) as f64;
        let fit_next = (next_item_size as f64 <= pr) as i32 as f64;
        score -= 8.0 * fit_next * (1.0 - gap / cap);
        score += 4.0 * (1.0 - fit_next) * (next_item_size as f64 / cap);
    }

    // New-bin candidate: penalize opening a bin unless open bins are crowded or fit is poor.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 30.0 * (1.0 - crowd) + 20.0 * progress;
        // But if mean residual across open bins can't help, soften the penalty.
        let mean_useful = (mean_residual >= norm_item * cap) as i32 as f64;
        score -= 25.0 * mean_useful;
    }

    // Mild penalty for bin proliferation.
    score += 0.8 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    // Bands: [0], (0,10], (10,25], (25,50], (50,75], (75,100)
    let band = if post_residual == 0 { 0u32 }
        else if post_residual <= bin_capacity / 10 { 1 }
        else if post_residual <= bin_capacity / 4 { 2 }
        else if post_residual <= bin_capacity / 2 { 3 }
        else if post_residual <= 3 * bin_capacity / 4 { 4 }
        else { 5 };

    // Reward filling a bin completely (waste-free placement)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize leaving dead space in the tiny bands (unusable for most items, min size 1..10)
    if band == 1 {
        score += 8.0 * (bin_capacity as f64 / post_residual as f64);
    } else if band == 2 {
        score += 3.0;
    }

    // Reward keeping large residuals (band 5) — bins stay flexible
    if band == 5 {
        score -= 5.0;
    }

    // Harmonic coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item fills this bin exactly
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                score -= 12.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted chain opportunity
            score += 6.0 * (post_residual as f64 / next_item_size as f64);
        }
        // Modulo harmony: residual divisible into next item sizes
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 10.0;
        }
    } else {
        // Last item: strongly reward emptying the bin
        score -= 200.0;
    }

    // Last-chance bin: this is the only bin that fits; opening a new bin is costly
    if fitting_bins_count == 1 && post_residual != bin_residual {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor, normalized)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate: prefer existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 10.0 + 40.0 * progress;
    }

    // Integer division threshold: if post_residual < half capacity, mild extra penalty
    // unless next item fits (already rewarded above)
    if post_residual < bin_capacity / 2 && next_item_size > post_residual {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Perfectly dead gap: worst outcome, huge penalty.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (small post_residual relative to residual).
    let tightness = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; cheap early, expensive late.
        score = 40.0 + 15.0 * pressure + 30.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        score -= 5.0 * pressure;
    }

    // Lookahead: if next item fits exactly in this post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Prefer bins whose residual is below the mean (larger gaps elsewhere
    // should absorb future items); mildly favor near-mean bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    }

    // Penalize post-residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Favor bins with residual below mean (tight bins absorb items, keep loose bins flexible).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Last-chance bin: strongly prefer filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for keeping new-bin option open early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post-residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: reward leaving space for the next item, penalize dead space otherwise
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // next item can chain here
        } else {
            // penalize leftover space that's too small to be useful
            let waste = post_residual as f64;
            score += 0.05 * waste;
        }
    } else {
        // last item: minimize leftover
        score += 0.1 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Many open bins: prefer filling existing ones over opening new ones
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 2.0 * crowding;

    // Time horizon: early in stream, be more conservative (prefer tight fits);
    // late in stream, just close bins out
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New empty bin candidate: penalize unless current bin fit would be very wasteful
    if bin_residual == bin_capacity {
        let waste_if_placed = (bin_capacity - item_size) as f64;
        let threshold = 0.6 * bin_capacity as f64;
        if waste_if_placed < threshold {
            score += 500.0; // existing bins handle it fine
        } else {
            score -= 10.0; // wasteful fit elsewhere; fresh bin is competitive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: reward tight fits via quadratic penalty on post_residual
    let mut score = pr * (1.0 + 0.9 * fit_norm * fit_norm);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (less time to fill it)
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 18.0 * late * fit_norm * fit_norm;

    // Penalize bins far from mean residual (fragmentation avoidance)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Slight penalty when many bins are open (discourage sprawl)
    score += 0.4 * open_bins_count as f64 * fit_norm;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * late;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear emphasis.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Harmonic class of post_residual: residuals in "dead zones" are penalized.
    // Residuals that are multiples of common item-size classes (10..=20) are reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut reusable = false;
        for k in 10..=20u32 {
            if pr % k == 0 && pr >= k {
                reusable = true;
                break;
            }
        }
        if reusable {
            score -= 6.0;
        } else if pr < 10 {
            // Unusable dead space (below minimum item size).
            score += 25.0;
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 60.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64).powi(2) * 0.05;
        } else {
            // Next item cannot fit here; slight penalty for stranding.
            score += 4.0;
        }
        // Harmonic match: post_residual divisible by next_item_size.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Spread penalty when many bins fit: prefer the tightest (handled by base term).
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so that only
    // genuinely bad fits in open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = 30.0
            + post_residual as f64 * 0.5
            - (if next_item_size > 0 && next_item_size <= bin_capacity { 5.0 } else { 0.0 });
        // Late in the stream, opening new bins is less useful; make it costlier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; penalize.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Mild preference for consolidating into few bins early on.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a meaningful item are heavily penalized (super-linear).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 20.0 {
            // unusable sliver: quadratic penalty
            score += (20.0 - gap) * (20.0 - gap) * 0.8;
        } else if gap < 40.0 {
            // moderately awkward gap
            score += (40.0 - gap) * 0.35;
        }
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to residual (waste ratio view).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it is only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If lookahead item is small, a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) < 0.35 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward leaving a gap that fits the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Open-bin pressure: when many bins are open, favor consolidation into them
    // over opening yet another bin.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Late in the stream, be more conservative about opening new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward closing the bin.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward when the leftover space exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Leftover can host the next item; scale reward by how snug the fit is.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 200.0 * snug;
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize residuals that are too small to be useful for typical items (waste).
    if post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }

    // Compare against mean residual across open bins: prefer bins that are
    // tighter than average (draining nearly-full bins first).
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score += 0.3 * (post_residual as f64 - mean_r);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild penalty for opening a brand-new bin when other bins could fit the item,
    // unless the item is large relative to residual (poor fit elsewhere).
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 80.0 * (1.0 - fit_ratio);
        } else {
            score -= 20.0;
        }
    }

    // Early in the stream, allow more bins to hedge against future variety.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

