    }

    // Time horizon: early in the stream, prefer keeping residuals large (flexibility);
    // later, prefer consolidation into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Prefer bins whose residual is close to the mean residual (balanced usage),
    // weighted more heavily as the stream progresses.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.5 + 1.5 * progress);

    // Late in the stream, penalize opening new bins / low-fill bins.
    if progress > 0.7 && bin_residual == bin_capacity {
        score += 60.0 * progress;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.2 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with larger residual when item is small.
    score -= 0.05 * bin_residual as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    let progress_coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += progress_coupling;

    // Reward tight fits via smooth cubic in normalized item size
    let tightness = (1.0 - norm_item) * (1.0 - norm_item) * (1.0 - norm_item);
    score -= tightness * 15.0 * (1.0 - progress);

    // Lookahead: smooth quadratic reward if next item fits post residual
    if next_item_size > 0 {
        let gap = (pr - norm_next * cap) / cap;
        let fit_reward = (-gap * gap * 4.0).exp();
        score -= 10.0 * fit_reward * (norm_next * cap / cap.max(1.0));
    }

    // Last-chance bonus: smooth sigmoid on fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 20.0 * last_chance;

    // Penalize bins far from mean residual (fragmentation), smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 25.0;

    // Mild penalty for many open bins to encourage consolidation early
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 10.0);
    score += open_norm * 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "nice" modular
    // classes (multiples of 10, or >= 10) remain usable for future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else if pr < 10 {
        score += 45.0; // dead space below minimum item size
    } else {
        // Reward residuals in round harmonic classes (multiples of 10)
        let class = pr % 10;
        score -= (10 - class) as f64 * 1.5; // closer to a multiple of 10 -> better
        // Reward larger usable residual, with diminishing returns
        score -= (pr as f64).sqrt() * 3.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= pr {
            // Next item fits here: reward, especially if it nearly fills the bin
            let combo = item_size as f64 + nxt;
            let fill = combo / cap;
            score -= fill * 40.0;
            if (pr as u32) == next_item_size {
                score -= 35.0; // next item exactly consumes residual
            }
        } else {
            // Next item cannot follow into this bin; penalize proportionally
            score += (nxt - pr as f64).min(40.0) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // A new bin is attractive only for large items (tight fits) or when
        // the stream is early and many bins will be needed anyway.
        score += 30.0 - tightness * 55.0;
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity - item_size {
            score -= 12.0; // pairing potential in fresh bin
        }
        if (post_residual as f64) < 10.0 {
            score -= 25.0; // near-perfect single placement in fresh bin
        }
    }

    // Mild pressure toward consolidating many open bins
    score += open_bins_count as f64 * 0.05;

    // Stream progression: later in the stream, prefer tighter packing (favor
    // filling existing bins over opening new ones).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    let waste_frac = post_residual as f64 / bin_residual.max(1) as f64;
    score += 15.0 * waste_frac;

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when all existing fits would create dead space.
    let open_pressure = open_bins_count as f64 * 0.8;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin candidate (empty bin): base cost plus open-bin pressure,
    // discounted late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        score += 12.0 + open_pressure * (1.0 - 0.5 * progress);
        // If this is the only bin that can fit, opening is nearly free.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    } else {
        // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Reward using bins whose residual deviates below the mean (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it;
    // if the next item is slightly larger than post residual, penalize blocking it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item can't follow here: penalize dead space proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Compare against mean residual: prefer tighter-than-average bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: strong bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins could fit, more so early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 25.0 * (1.0 - progress);
        // New bin is acceptable if item is huge and nothing fits well.
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate aggressively into existing bins.
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.8 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly favored.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead waste).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 15.0 * (nxt - post_residual as f64) / 100.0;
        } else {
            // Reward leaving exactly enough room for the next item.
            let slack = post_residual as f64 - nxt;
            score -= 8.0 * (1.0 - slack / 100.0).max(0.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 10.0; // near-perfect fill on a last-chance bin
        }
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            1.0 / fitting_bins_count as f64
        } else {
            1.0
        };
        score += 25.0 * pressure;
        // Early in the stream, allow more exploration of new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Global fragmentation pressure: if mean residual is low, prefer bins
    // that keep residuals near the next item size.
    let mr = mean_residual;
    if mr > 0.0 {
        let closeness = 1.0 - ((post_residual as f64 - mr) / bin_capacity as f64).abs();
        score -= 5.0 * closeness;
    }

    // Late-stream consolidation: favor filling bins down to tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && post_residual < 15 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty for very large residuals left behind (unusable space).
    if post_residual > 60 {
        score += 0.15 * (post_residual as f64 - 60.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: quadratic penalty on large post_residual,
    // modulated by progress (late in stream, dead space is more costly).
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small relative to item size
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize bins that can't fit the lookahead item (smooth via ratio)
    if next_item_size > 0 {
        let next_fits = (post_residual as f64) >= (next_item_size as f64);
        if !next_fits {
            score += 6.0 * (1.0 - progress);
        } else {
            score -= 3.0 * ((next_item_size as f64) / (post_residual.max(1) as f64));
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64).sqrt();
    }

    // Mild pull toward bins with residual below the mean (consolidate slack)
    score += 0.05 * ((mean_residual - pr).abs()) * (1.0 - progress);

    // New-bin candidate: penalize slightly so we prefer filling open bins unless they fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
        // But encourage opening a new bin early when mean residual is large (fragmentation)
        score += 0.02 * mean_residual * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small" classes (<= 10) are nearly perfect, reward them strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Modulo arithmetic on post_residual: leftovers in multiples of common small
    // item sizes (10, 20, 25, 50) are reusable; reward divisibility.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
        if post_residual < 10 { score += 8.0; } // tiny dead space penalty
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // harmonic class match: next item leaves a small class again
            let pr2 = post_residual - next_item_size;
            if pr2 <= 10 { score -= 8.0; }
            if pr2 % 10 == 0 && pr2 > 0 { score -= 3.0; }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += (next_item_size - post_residual).min(30) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we prefer
    // reusing open bins unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // late in the stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // penalize bins far from the mean residual (outlier fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Integer-division threshold: bins whose residual can host a "half-capacity"
    // class item (>= 50) keep flexibility; bins that cannot are less valuable.
    if bin_residual < 50 && post_residual > 0 && item_size <= 50 {
        score += 3.0;
    }

    // Slight preference for tighter existing bins when many bins are open.
    score += (open_bins_count as f64) * 0.02 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small for typical future
    // items (1..=100, but practically >=10 in classic regime) are wasted.
    // Penalize "unusable" gaps sharply with a non-linear bump.
    let dead_threshold = 12u32.min(bin_capacity / 8).max(1);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Progressive reward for small (usable) residuals.
        score -= 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);
    }

    // Perfect fit detection: item exactly fills the bin.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Mild reward if the next item can still fit afterwards.
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual cannot host next item: penalize small stranded gaps.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // compact choice exists; scale with fraction of stream completed.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (smaller residual = tighter bin = better candidate).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin (avoid waste).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it moderately attractive only when the item is large relative
    // to capacity or no tight option exists; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins readily; small items should not.
        score += 20.0 * (1.0 - fill_ratio);
        // But late in the stream, opening fresh bins is less attractive.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with slight nonlinearity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly-ish
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let slack = post_residual as f64 - next;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize unusable remainder
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Relative to mean residual: bins below mean residual are "tight" -> prefer filling them
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage fragmentation, prefer consolidation
    score += 0.05 * open_bins_count as f64;

    // Late in stream: be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * tightness;

    // New-bin candidate: only attractive when item is large and no good fit exists
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 20.0 * large;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual) — classic best-fit core.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that cannot plausibly hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin becomes useless for the upcoming item.
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        } else {
            // Reward bins that can still accommodate the lookahead item.
            score -= 8.0 * next_item_size as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: any placement is fine; slight preference to close out bins.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global waste.
        score += 25.0;
        // If mean residual is large, open bins are wasteful — opening fresh is fine.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Many open bins: discourage spreading further.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild global pressure: when many bins are open, favor filling existing ones.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Slight preference for bins with residuals near item_size (perfect consumption).
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += gap * 0.05;

    // Small tie-breaker toward bins that are already partially filled.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly coupled with stream progress.
    let mut score = pr;

    // Smooth polynomial coupling: waste matters more as stream progresses.
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += waste_weight * norm_pr * norm_pr * cap * 0.5;

    // Tight fit reward (small post residual) — quadratic bonus, stronger late.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward if next item fits the post residual smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_ratio = (next_item_size as f64) / pr.max(1.0);
        score -= 8.0 * fit_ratio * (1.0 - fit_ratio) * 4.0 * (0.3 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item cannot use.
        score += 4.0 * (1.0 - (pr / (next_item_size as f64)).min(1.0)) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    let mean_norm = mean_residual / cap;
    score += 2.0 * open_bins_count as f64 * mean_norm * mean_norm * 0.1;

    // New-bin candidate: penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * mean_norm + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality by residue mod 10
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,           // perfectly rounded residual, highly reusable
        1 | 2 | 3 => score += 6.0,    // awkward sliver, likely dead space
        4 | 5 | 6 => score += 0.0,    // neutral mid class
        7 | 8 | 9 => score -= 4.0,    // large-ish residual, still usable
        _ => {}
    }

    // Integer-division threshold bands on post_residual
    if post_residual <= 5 {
        score -= 20.0; // near-perfect packing, best outcome
    } else if post_residual <= 15 {
        score += 8.0;  // dead zone: too small for most items (min size 1..100)
    } else if post_residual <= 30 {
        score += 3.0;  // fits only small items
    } else if post_residual <= 60 {
        score -= 6.0;  // sweet spot: fits half the items
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chain placement possible
            // harmonic bonus if next item divides residual evenly
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // penalty scaled by how badly the next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += (miss / 20.0).min(8.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer it only when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // default slight penalty so we prefer filling existing bins on good fits
        score += 4.0;
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 10.0; // existing bins nearly full -> open fresh bin
        }
        if fragmentation > 40.0 {
            score += 5.0;
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / 10.0);

    // Prefer bins tighter than the mean (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harshly (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);
    score += pressure;

    // New-bin candidate: make it moderately attractive only when residuals elsewhere are poor
    if bin_residual == bin_capacity {
        score = score.max(0.0) * 0.5 + 25.0 - mean_residual * 0.3;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // big item coming; fresh bin may be better
        }
    } else {
        // Favor bins whose residual also accommodates the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mild preference for bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (post_residual small relative to item)
    let fit_ratio = post_residual as f64 / cap;
    score -= 60.0 * (1.0 - 2.0 * fit_ratio).powi(2) * (1.0 - fit_ratio);

    // Aggressive 2-step lookahead: if next item fits into post_residual, big bonus
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = (post_residual - next_item_size) as f64 / cap;
        score -= 45.0 * (1.0 - chain_tightness);
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving medium dead space
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 20.0 * (1.0 - dead / cap) * (next_item_size as f64 / cap);
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong penalty if we waste it on a poor fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if fit_ratio > 0.25 {
            score += 30.0;
        } else {
            score -= 15.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
        score += 25.0 + 8.0 * pressure;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 20.0; // fresh bin can chain with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fills (low post_residual already does this; amplify slightly)
    score -= 0.15 * (bin_capacity as f64 - post_residual as f64);

    // Penalize the brand-new bin option: opening a bin is expensive,
    // more so when other bins could fit the item.
    if is_new_bin {
        score += 18.0 + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            // Strong penalty if any open bin could take the item
            score += 10.0 + 0.3 * post_residual as f64;
        }
        // Late in the stream, prefer consolidating into open bins
        score += 5.0 * progress;
    } else {
        // Last-chance bin: strongly favor using it before opening a new one
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Mild preference when many bins compete (keeps bin count low)
        score -= 0.05 * fitting_bins_count as f64;
    }

    // Lookahead (k=2): reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 1.5;
        }
    }

    // Global-state coupling: prefer bins close to the mean residual
    // (keeps residual distribution balanced, avoids stranded outliers)
    score += 0.08 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * (1.0 - progress);

    // Penalize dead space more sharply as the stream matures (smooth cubic in progress).
    let dead = (pr_norm.powi(3)) * (0.5 + 2.5 * progress * progress);

    // Reward tight fits: low post residual gets a smooth bonus.
    let tight_bonus = -8.0 * (1.0 - pr_norm).powi(4);

    // Last-chance bin: strongly favor using it (smooth exponential urgency).
    let last_chance = if fitting_bins_count <= 1 { -6.0 } else { 0.0 };

    // Lookahead: reward bins whose post residual still fits the next item.
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -2.0 * (1.0 - pr / cap)
    } else if next_item_size > 0 {
        1.5
    } else {
        0.0
    };

    // Mild preference for bins below mean residual (balances load smoothly).
    let balance = 0.5 * ((mean_residual - pr) / cap);

    // Slight penalty for many open bins to discourage fragmentation late.
    let frag = (open_bins_count as f64).ln() * pr_norm * 0.2;

    base * 10.0 + dead * 10.0 + tight_bonus + last_chance + lookahead + balance + frag
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: best-fit waste measure.
    let mut score = post;

    // Perfect fit: zero waste, huge reward.
    if post_residual == 0 {
        score -= cap;
    }

    // Harmonic dead-zone: leftover below capacity/8 (integer-division threshold)
    // is fragile dead space that few future items can use.
    if post_residual > 0 && post_residual * 8 < bin_capacity {
        score += post;
    }

    // Modulo tiling: a leftover that exactly divides the next item's size
    // can be tiled perfectly by future copies of that size.
    if next_item_size > 0 && post_residual > 0 && next_item_size % post_residual == 0 {
        score -= 0.25 * post;
    }

    // Lookahead coupling (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post - next;
            // Chain bonus: stronger when the next item lands tightly behind this one.
            score -= 0.6 * next + 0.4 * next * (1.0 - slack / cap);
        } else {
            // Next item cannot use this leftover: proportional dead-space penalty.
            score += 0.5 * (next - post);
        }
    }

    if !is_new_bin {
        // Prefer bins tighter than the fleet average (consolidate fragmentation).
        let tight = mean_residual - bin_residual as f64;
        if tight > 0.0 {
            score -= 0.10 * tight;
        }
        // Last chance: this is the sole open bin that fits — avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 0.25 * cap;
        }
    } else {
        // New-bin candidate: pay an opening cost, discounted for large items
        // (a fresh bin preserves open residuals for small items) and scaled
        // by how many bins are already open and how far the stream has progressed.
        let mut cost = 0.30 * cap * (1.0 - 0.5 * item / cap)
            + 0.40 * open_bins_count as f64;
        cost *= 1.0 + progress;
        if item > 0.5 * cap {
            cost -= 0.15 * cap;
        }
        score += cost;
        // Fresh bin hosting both the current and the next item is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 0.5 * next;
        }
        // Forced opening when no open bin can fit the item.
        if fitting_bins_count == 0 {
            score -= 2.0 * cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // awkward gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when open bins are very fragmented
    // (high mean residual spread) or nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        if fitting_bins_count > 0 {
            score += 35.0; // extra penalty when some open bin can take the item
        }
    }

    // Lookahead: prefer bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Late in the stream, prefer closing bins out rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small dead space).
    score -= 40.0 * (1.0 - (post_residual as f64) / bin_capacity as f64).powi(3);

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this is a perfect chain placement -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves slack; reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a residual that is
            // small and unusable (dead space), worse if next item is large.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(60.0);
        }
    }

    // Compare against mean residual: bins with residual below mean are
    // "nearly full" -> prefer filling them to close them out.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 2.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists,
    // i.e. when residuals are all far from the item size.
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual - item_size as f64).abs() > 15.0 && fitting_bins_count <= 2;
        if poor_fit {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // Early in the stream, be more willing to consolidate (fewer bins now
    // pays off later); late in the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Penalize opening extra bins when many are already open.
    if bin_residual == bin_capacity {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Penalize dead space that cannot fit a typical item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // Bonus if post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer the best fit, mild penalty for wasteful use
        score += 4.0 * (fitting_bins_count as f64).ln();
    }

    // Global fragmentation pressure: when mean residual is low, conserve space
    let frag = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 15.0 * frag * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, prefer opening new bins for large items;
    // late in stream, squeeze into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or for large items, penalized late
        let new_bin_penalty = 35.0 * progress + 0.25 * item_size as f64;
        score += new_bin_penalty;
        // Opening a new bin is good if item is large and few bins fit it
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 40.0 * (1.0 - progress);
        }
    } else {
        // Existing bin: late stream bonus
        score -= 10.0 * progress;
    }

    // Prefer filling fuller bins (lower residual) when many bins are open
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress - 0.3 * progress * progress);

    // Non-linear penalty for small dead space (waste), smoothed via ratio
    let dead = pr / cap;
    score += 12.0 * (1.0 - dead) * (1.0 - dead) * (1.0 - dead);

    // Reward tight fits relative to current bin state
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit * fit;

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead coupling: favor bins whose post_residual still fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (nxt / cap);
        } else {
            score += 3.0 * ((nxt - pr) / cap) * ((nxt - pr) / cap);
        }
    }

    // Mild pressure against proliferating bins late in the stream
    score += 0.15 * (open_bins_count as f64) * progress;

    // New-bin candidate: penalize mildly unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 2.0 - 3.0 * (1.0 - dead) * (1.0 - dead);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space.
    let post = post_residual;
    let class = post / 10; // integer division threshold classes: 0..10

    // Reward small post residuals (tight fits) with a nonlinear bonus.
    let tight_bonus = match class {
        0 => 30.0,               // perfect/near-perfect fit
        1 => 18.0,               // 1..9 leftover
        2 => 10.0,               // 10..19
        3 => 4.0,
        4 => 1.0,
        _ => 0.0,
    };
    score -= tight_bonus;

    // Penalize dead space that no plausible future item can use.
    // Items are 1..100; residuals in awkward bands are waste.
    let dead_penalty = if post > 0 && post < 10 {
        8.0
    } else if post >= 10 && post < 25 {
        3.0
    } else if post >= 75 {
        -2.0 // large residual is reusable, mild reward
    } else {
        0.0
    };
    score += dead_penalty;

    // Modulo coupling: does the leftover pair well with the lookahead item?
    if next_item_size > 0 {
        if post >= next_item_size {
            // Lookahead fits here: reward harmonic complementarity.
            let slack = (post - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
            // Exact two-item closure bonus (modulo-style divisibility)
            if post == next_item_size {
                score -= 12.0;
            } else if (post % next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            // Lookahead cannot use this bin's leftover: penalize proportionally.
            score += 4.0 * (next_item_size as f64 - post as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but allow it when
    // current bins have poor fits and mean residual is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is better when existing residuals are fragmented.
        let fragmentation = mean_residual / cap;
        score = 25.0 + 40.0 * fragmentation - 20.0 * (1.0 - progress);
        // Don't open a new bin if the item fits snugly somewhere already.
        if post == 0 {
            score += 50.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual > 0 {
        // Assume items >= 1, but tiny gaps (< ~10) are near-unusable; penalize heavily.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates below mean (consolidate emptier space usage).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here anyway; small gap left behind is worse.
        score += 5.0;
    }

    // New-bin candidate: neutral baseline, only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0;
    } else if post_residual <= 20 {
        score -= 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer chains where next item also leaves small remainder.
            score -= 200.0 - slack * 0.5;
            if slack < 10.0 {
                score -= 100.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.6;

    // Penalize leaving large dead space relative to smallest possible item (1..100 range).
    if post_residual > 0 && post_residual < item_size && post_residual < 30 {
        score += 50.0;
    }

    // Mild preference for consolidating when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    // Late in stream, be greedier about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large unusable dead space (post residual too small for typical future items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits into the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // extra reward if next item fills bin almost exactly
        let chain_waste = post_residual - next_item_size;
        score -= 8.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot chain here; mild penalty proportional to leftover
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it attractive only when fits are poor
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline; penalize slightly so decent fits win,
        // but reward when current bins would leave big dead space
        score += 5.0;
        if post_residual as f64 > mean_residual {
            score -= 6.0;
        }
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (large post_residual);
    // late in stream, prefer filling bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.10 * post_residual as f64;
    score -= progress * 0.05 * item_size as f64;

    // Global state: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: small post_residuals are strongly favored, scaled by stream progress.
    let norm_pr = pr / cap;
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize large dead space quadratically.
    score += 0.05 * pr * pr / cap;

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize new-bin candidate more as stream progresses; mild early allowance.
    if bin_residual == bin_capacity {
        score += 15.0 * (0.3 + 0.7 * progress) + 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average residual.
    score -= 3.0 * ((mean_residual - pr) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls
    // into a "useless" residue class that few item sizes can fill.
    // Classes via integer division thresholds and modulo arithmetic.
    let cap_f = bin_capacity as f64;

    // Small dead space is good (tight fit) — reward quadratically.
    if post_residual <= 10 {
        score -= 24.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score -= 3.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 are "harmonious"
    // (many item sizes 1..100 align on multiples of 10) — reward them.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Penalize mid-range dead space (25..60) that is hard to fill:
    // integer-division class post_residual / 20 in {1,2} is the danger zone.
    let div_class = post_residual / 20;
    if div_class == 1 || div_class == 2 {
        score += 8.0;
    }

    // Next-item lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residue — mild reward scaled
            // by how harmonious the resulting residue class is.
            let nxt_res = post_residual - next_item_size;
            score -= 6.0 - (nxt_res % 10) as f64 * 0.3;
        } else {
            // next item cannot use this bin's residue: penalize large residues
            // that block the next item, scaled by stream progression.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 5.0 + 8.0 * progress;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual <= 15 {
            score -= 10.0;
        }
    }

    // New-bin candidate: residual == capacity. Prefer it only when mean
    // residual across open bins is already tight (open bins are nearly full)
    // or many bins are open (fragmentation risk).
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap_f; // fraction of capacity still free on average
        if tight < 0.25 || open_bins_count > 12 {
            score -= 12.0;
        } else {
            score += 6.0 + 10.0 * tight;
        }
    }

    // Mild pressure to reuse existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 2.0 * progress;
    }

    // Waste fraction term: large post_residual relative to capacity penalized.
    score += (post_residual as f64 / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit anything
    // (items are >= 1, but small gaps < 10 are nearly unusable) are heavily penalized.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (1.0 - 0.5 * progress);

    // New-bin candidate (empty bin): make it attractive only when this bin's
    // post residual is bad dead space and open-bin pressure is low.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in the stream.
        score += 25.0 - 10.0 * progress;
        // If the current bin would leave a large awkward gap, opening fresh is fine.
        if post_residual < 10 || post_residual > 60 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins with residual far below mean (tighter bins),
    // i.e. placing into a looser-than-average bin is penalized slightly.
    if (bin_residual as f64) > mean_residual {
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item fits; reward tight coupling
            let slack = post_residual - next_item_size;
            score -= 400.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit here -> penalize leaving a gap it can't use
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Compare post_residual relative to mean residual: prefer tight packing
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.35 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fits exist, especially early/mid stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let urgency = (fitting_bins_count == 0) as i32 as f64;
        let waste = bin_residual as f64 - item_size as f64;
        score += 180.0 - urgency * 400.0 - 0.5 * progress * 100.0 + 0.3 * waste;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 2.5 * tight * tight * cap;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Bonus if the next item fits exactly in the post residual.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Early in the stream: prefer opening new bins to build diverse residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when all open bins fit poorly.
        let new_bin_bonus = 30.0 * (1.0 - progress) + 10.0 * (1.0 - (post_residual as f64 / cap));
        score -= new_bin_bonus;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin leaves room for a similar/larger next item
        }
    } else {
        // Late in the stream: consolidate into existing bins.
        score += 15.0 * progress;
        // Penalize placing into bins whose residual is near mean (no advantage).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.5 * dev / cap;
    }

    // Many open bins: discourage fragmentation, favor filling existing bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with small residual overall (best-fit flavor) modulated by progress.
    score += (bin_residual as f64 / cap) * (2.0 + 6.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly scaled by stream progress.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);

    // Penalty for dead space that cannot fit the average next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr < n {
            score += (n - pr) / cap * (1.0 + progress);
        } else {
            score -= (pr - n) / cap * 0.5 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - 0.5 * progress);
    } else if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Penalize bins that deviate from the mean residual (keep residuals balanced),
    // with coupling that relaxes late in the stream.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * (1.0 + progress) * 0.8;

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 1.5 + 0.002 * open_bins_count as f64 * (1.0 + progress);
    }

    // Small reward for filling bins completely (post_residual near zero),
    // smooth cubic term.
    score -= (1.0 - norm_pr).powi(3) * 0.6;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, reward near-perfect packing.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead space quality.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 25.0; // near-closed, small dead space
    } else {
        // Modulo-10 classes: residuals divisible by 5 or 10 are more reusable
        // for items in 1..=100 with common sizes.
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Integer-division thresholds: small residual buckets are hard to fill.
        let bucket = pr / 10; // 0..=9
        score += bucket as f64 * 3.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match: next item's class aligns with residual.
            let slack = pr - next_item_size;
            score -= 10.0 + 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack % 10 == 0 { score -= 3.0; }
        } else {
            // Next item won't fit here: penalize wasting a good bin on this item
            // if the residual would have been large enough for the next item alone.
            score += 5.0;
        }
    } else {
        // Last item: drive residuals to zero aggressively.
        score -= 15.0 * (1.0 - pr as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer tighter fits among candidates.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when
    // current open bins are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        let item_class = item_size / 10; // harmonic size class 1..=8
        let urgency = (item_class as f64 / 8.0) * 0.6 + progress * 0.4;
        // Penalize new bin unless existing bins are quite full.
        score += 35.0 - 45.0 * urgency - 10.0 * crowded.min(1.5);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0; // fresh bin can host a pair
        }
    }

    // Mild preference to consolidate: fewer open bins is better.
    score += (open_bins_count as f64) * 0.5;

    // Mean-residual context: if this bin is much emptier than average,
    // it's a good target; if much fuller, avoid fragmenting it.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
