    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            // next item cannot use this dead space -> extra penalty
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if current bins are very fragmented (high mean residual spread
        // with many bins), opening fresh is less bad.
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // If the item is large relative to capacity, a fresh bin is safer.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Slight preference for bins whose residual is close to the item size
    // (minimize wasted capacity globally).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += waste * 0.1;

    // Late in the stream, consolidate aggressively to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits here afterwards: mild bonus proportional to how well it fills
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_fill;
        } else {
            // next item won't fit in leftover: penalize large unusable leftovers
            let waste = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.15 * waste;
        }
    }

    // Compare against mean residual: bins below mean residual are more "committed";
    // prefer packing into tighter-than-average bins to keep large residuals free.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to open-bin residuals or there are no alternatives.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for very small leftovers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual superlinearly (dead space is quadratic bad).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * frac * frac;

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item exactly fits the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills the remainder
            let nxt_fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nxt_fill;
        } else {
            // next item won't fit here: if post residual is too small for typical items,
            // penalize creating stranded capacity.
            if post_residual < 20 {
                score += 20.0;
            }
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual <= 15 {
            score -= 18.0;
        }
    }

    // New-bin candidate handling: opening a new bin is attractive early in the stream
    // or when many bins are open with fragmented residual space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; becomes cheaper later when open bins are fragmented.
        score = bin_capacity as f64 * 0.55;
        score -= 30.0 * (1.0 - progress);
        // If existing bins are highly fragmented (low mean residual), prefer a new bin.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 0.0;
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 20.0;
        }
        // If the item is large relative to typical residual, a fresh bin fits it well.
        if item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Placing in an existing bin: reward bins whose residual deviates from the mean
        // in a useful way (prefer using bins with below-average residual to consolidate).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Mild load-balancing: many open bins encourage closing them out (filling small residuals).
        if open_bins_count > 6 && post_residual < 30 {
            score -= 8.0;
        }
    }

    // Early stream: keep bins tidy for future flexibility; late stream: just pack tightly.
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on leftover space (dead space is doubly bad late in stream)
    let mut score = norm_pr * norm_pr * cap;

    // Smooth non-linear coupling of post_residual with stream progress
    score += norm_pr * (1.0 + progress * 2.0) * 10.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * (0.5 + progress);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 + 10.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host next item, scaled by wasted amount
        score += (pr - (pr % next_item_size.max(1) as f64)) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.5 * norm_pr;

    // Prefer bins with residual below mean (fill laggards), smooth coupling
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // New-bin candidate: neutral-ish score; only chosen if all fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 30.0 * (1.0 - progress) - if fitting_bins_count == 0 { 1000.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: prefer residues that are "hard to fill"
    // residues divisible by 10 are reusable; odd/tiny residues are dead space
    let residue_class = post_residual % 10;
    if post_residual > 0 && residue_class != 0 {
        score += 8.0; // awkward residue penalty
    }
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // near-dead space
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit reward, stronger for tighter chains
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 + 20.0 * chain_tightness;
        } else {
            // next item won't fit here: penalize leaving medium dead space
            if post_residual >= next_item_size.saturating_sub(5) {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if the item is large relative to capacity, opening fresh is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
        // fewer open bins -> opening new is cheaper
        score -= 2.0 * open_bins_count as f64;
    }

    // Tight fit bonus: item consumes most of the bin
    let fill_frac = item_size as f64 / bin_residual as f64;
    if fill_frac > 0.8 {
        score -= 20.0;
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - waste_frac);

    // Prefer bins below mean residual (more filled bins get priority)
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A gap is "unusable" if it's smaller than the smallest plausible item.
        // Treat gaps < ~10 (or below next item size) as dead space.
        let dead_threshold = 10u32.min(bin_capacity);
        if post_residual < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual) as f64;
        }
        // Non-linear penalty: gaps that cannot fit the lookahead item are risky.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
            // Extra penalty for tiny useless leftovers after failing lookahead.
            if post_residual < 5 {
                score += 25.0;
            }
        }
        // Reward near-perfect fits (small but usable gaps are fine).
        if post_residual <= 5 {
            score -= 15.0;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Mild preference for bins tighter than average (waste consolidation).
    score += 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Default mild penalty; lifted implicitly when all open bins score high.
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size > post_residual {
            // Opening fresh bin preserves room for the next item.
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0; // chain fit: two items perfectly fill the bin
        } else if post_residual >= next_item_size {
            // reward proportional to how little slack remains after the lookahead item
            let after_next = post_residual - next_item_size;
            score -= 200.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // lookahead item cannot fit here: penalize leaving dead space that blocks it
            let dead = post_residual as f64;
            score += 0.5 * dead;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Penalize creating very small unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 250.0;
        // if lookahead chains perfectly with a fresh bin, soften penalty
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 350.0;
        }
        // early in stream, more willing to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
    }

    // Mild preference to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1..~10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // awkward sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score -= 4.0; // still reusable zone
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / (bin_capacity as f64));
        } else {
            // next item won't fit here: mildly prefer leaving larger residuals elsewhere
            score += 3.0;
        }
    } else {
        // last item: just minimize waste
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is low (bins nearly full).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * (1.0 - progress); // prefer below-average-residual bins early on
    } else {
        score += 2.0 * progress; // late in stream, prefer fuller bins
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // If open bins have little usable space, opening new bin is fine; otherwise penalize.
        score += 35.0 - 12.0 * crowded;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    }

    // Mild penalty for opening bins when few items remain relative to open bins.
    if open_bins_count > 0 && bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        if remaining < (open_bins_count as f64) * 1.5 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, non-linearly (quadratic dead-space penalty).
    let mut score = norm_post * norm_post * cap;

    // Smooth coupling: residual quality matters more as the stream progresses.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (1.0 + 3.0 * progress) * 10.0;

    // Perfect-ish fit bonus (smooth via normalized term).
    score -= (1.0 - norm_post).powi(3) * 25.0;

    // Last-chance bin: reward strongly, scaled by how well it fits.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * tightness;
    }

    // Lookahead: if next item fits the post-residual, reward; else penalize dead space.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            let slack = (post - next) / cap;
            score -= (1.0 - slack) * 8.0;
        } else {
            score += 6.0 * (next - post) / cap * 10.0;
        }
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness) * 2.0;

    // Mean residual context: penalize bins far from mean residual (outliers).
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Small bias against opening a new bin early in the stream.
    score += (1.0 - progress) * (if bin_residual == bin_capacity { 12.0 } else { 0.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // Harmonic class logic: partition post_residual into harmonic buckets
    // (dead-space classes). Residuals that are perfect divisors of capacity
    // or near-harmonic complements of common item sizes are more usable.
    let pr = post_residual;
    if pr > 0 {
        // Harmonic bonus: capacity % pr == 0 means residual can be exactly
        // tiled by a whole fraction of the capacity -> very usable.
        if bin_capacity % pr == 0 {
            score -= 8.0;
        }
        // Modulo classes: residuals in low-dead-space bands
        if pr <= 10 {
            score += 6.0; // tiny sliver, nearly dead space
        } else if pr <= 25 {
            score += 2.0;
        } else if pr <= 40 {
            score -= 1.5;
        } else if pr <= 60 {
            score -= 3.0;
        }
        // Integer-division threshold: residual divisible into chunks of 10
        if pr % 10 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: does this bin's post-residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic match: post_residual % next_item_size == 0 is ideal
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 7.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to waste
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into tight fits rather than opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it moderately attractive only when current
    // bins would leave bad residuals, otherwise discourage.
    if bin_residual == bin_capacity {
        score -= 4.0 + 6.0 * progress;
        if item_size >= 50 {
            score -= 5.0; // large items start fresh bins well
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 3.0; // room for a paired follow-up
        }
    }

    // Late-stream tightening: favor perfect/near-perfect fits as stream ends
    if progress > 0.8 {
        score -= 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are nearly useless.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize opening new bins when existing bins fit, scaled by open-bin pressure.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mild preference for tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post residual exactly matches the next item size (perfect 2-step fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item still fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize residual that is too small to ever be useful again (dead space).
    if post_residual < 10 {
        score += 15.0;
    }

    // Compare post_residual against mean residual: prefer bins that leave residual near the mean
    // (keeps open bins homogeneous), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild bonus for tight fits (low post residual relative to item size).
    if item_size > 0 {
        score -= 10.0 * (item_size as f64 / bin_residual as f64);
    }

    // Early in the stream, slightly discourage opening many bins; late, allow flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always great
    } else {
        let pr = post_residual as f64;
        score += (pr / 20.0).powi(2); // penalize dead space quadratically
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.25; // leftover after next item penalized mildly
        } else {
            // next item cannot follow into this bin; slight penalty
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the fit is poor
    // or few bins fit the item and residuals are large on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.6;
        let poor_options = mean_residual < item_size as f64 + 10.0;
        if tight_fit || (poor_options && fitting_bins_count <= 2) {
            score -= 12.0 + 15.0 * progress;
        } else {
            score += 40.0; // discourage wasting a fresh bin
        }
    }

    // Mild preference for fuller bins among open bins.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 8.0;

    // Penalize bins with residuals far above the mean (fragmentation spreading).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pn = pr / bin_capacity as f64;
    let t = progress;
    let coupling = pn * pn * (1.0 + t) * 40.0 + pn * (1.0 - t) * 15.0;
    score += coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pn;
    score -= tightness * tightness * (20.0 + 30.0 * t);

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + t);
        } else {
            score -= 5.0 + 10.0 * t;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * t;
    }

    // Mild preference for bins below mean residual early, above later
    score += (mean_residual - bin_residual as f64) * (0.3 - 0.4 * t);

    // New-bin candidate: penalize opening new bins unless residuals are large
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - t);
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by residue classes
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Class A: post_residual in {0} -> great (handled above)
    // Class B: small residue (1..=5): nearly perfect, mild bonus
    if pr >= 1 && pr <= 5 {
        score -= 20.0 - pr as f64;
    }
    // Class C: mid residue (6..=15): dead space zone, penalize via modulo structure
    else if pr >= 6 && pr <= 15 {
        score += 8.0 + (pr % 5) as f64 * 2.0;
    }
    // Class D: residue divisible by 10 (nice round leftovers other items may match)
    else if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    }
    // Class E: prime-ish residues are hard to fill later
    else if pr > 15 {
        let m = pr % 7;
        if m == 1 || m == 3 {
            score += 5.0;
        } else if m == 0 {
            score -= 5.0;
        }
    }

    // Integer-division thresholds: how many "typical" items could still fit
    let slots = pr / 20; // assume typical item ~20
    score -= slots as f64 * 6.0;

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chained perfect fit
        } else if next_item_size < post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize leaving large unusable gap
            let gap = post_residual as f64;
            if gap > 40.0 {
                score += 10.0;
            }
        }
        // next item fits current residual but not post residual -> prefer keeping room
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should lose unless open bins are crowded
    if bin_residual == bin_capacity {
        // base penalty so new bins are only opened when justified
        score += 25.0;
        // more open bins with small mean residual -> opening new bin less attractive
        score += open_bins_count as f64 * 2.0;
        if mean_residual < 30.0 {
            score += 15.0;
        }
        // early stream: be liberal with bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Prefer tighter bins generally (residual close to item size)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Mean residual divergence: placing into bins far from mean balances the pool
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gaps too small for the smallest plausible item (1..10) are pure waste.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
        // Perfect fit reward.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Dead space relative to next item: if the leftover can't fit the lookahead item,
    // this bin's remaining capacity is likely wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Bonus if post_residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current residuals
    // are already tight (mean residual low) and no other bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
    }

    // Slight stream progression coupling: later in the stream, be more conservative
    // about creating unusable gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Prefer tighter fits overall: reward large item relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item can chain into this bin: strong reward scaled by tightness
            let chain_tightness = nxt / (post_residual as f64);
            score -= 60.0 + 40.0 * chain_tightness;
        } else {
            // dead space relative to next item: penalize small unusable leftovers
            let waste = nxt - post_residual as f64;
            if waste > 0.0 && waste < 20.0 {
                score += 25.0 * (1.0 - waste / 20.0);
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // Last-chance bin bonus: only bin that fits item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening new bins when good fits exist among open bins
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * open_bins_count as f64;
        // allow new bin more readily early in stream
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer leaving moderately usable residuals (avoid tiny slivers)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small leftover relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize creating dead space below the minimum item size (assume small items can appear)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer bins with residuals below mean (consolidate waste into few bins)
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 30.0 * dev;

    // Many open bins: encourage filling existing ones rather than opening more
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 25.0 * pressure;

    // Time horizon: early in stream, be conservative (favor new bins for large items);
    // late in stream, squeeze into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: neutral baseline with slight penalty so it is only chosen on genuinely bad fits
    if bin_residual == bin_capacity {
        score += 120.0 - 80.0 * (item_size as f64 / bin_capacity as f64);
        // open a new bin early for large items
        score -= 60.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Quadratic coupling: penalize small post_residuals more as stream progresses.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / (bin_capacity as f64) * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual) especially when this is the last fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr / bin_capacity as f64);
    } else {
        score -= 4.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        score += 3.0 * progress;
    }

    // Cubic progress term: bias toward compacting bins as stream advances.
    score -= 5.0 * progress * progress * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize deviating far from mean residual (smooth coupling).
    score += 0.15 * (mean_residual - pr).abs();

    // Mild penalty for too many open bins.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: slightly discourage unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 4.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo classes on post_residual
    let post = post_residual;
    if post > 0 {
        let class = post % 10;
        // Leftovers in "awkward" classes (1,2,3) are nearly dead space -> penalize
        match class {
            1 | 2 | 3 => score += 12.0,
            4 | 5 | 6 => score += 4.0,
            _ => score -= 3.0, // classes 7,8,9,0 can host medium items
        }
        // Perfectly reusable leftovers (exact halves/quarters of capacity)
        if post == bin_capacity / 2 || post == bin_capacity / 4 {
            score -= 8.0;
        }
        // Integer-division threshold: leftover >= next item's class bucket
        if next_item_size > 0 {
            let next_class = (next_item_size / 10).max(1);
            if post >= next_class * 10 {
                score -= 5.0;
            } else {
                score += 6.0;
            }
            // Chain fit: item + next exactly fill bin
            if item_size + next_item_size == bin_residual {
                score -= 15.0;
            }
        }
    } else {
        // Perfect fill is ideal
        score -= 20.0;
    }

    // Tight fit reward relative to capacity fractions
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 25.0 * waste;
        // Early in stream, fresh bins are cheap; late, prefer consolidation
        score -= 8.0 * (1.0 - progress);
        if post_residual >= 10 && post_residual <= 30 {
            score += 10.0; // fresh bin would create known-dead space pattern
        }
    }

    // Prefer bins far below mean residual (keeps residuals balanced)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Many open bins -> discourage fragmenting further
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space: penalize small unusable gaps (0 < post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward residual that can still fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins slightly,
    // but encourage using existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor filling the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: mild penalty so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Late-stream consolidation: tighten preference for exact fits near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual == 0) as i32 as f64 * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near match: next item still fits after this placement.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Next item does NOT fit: penalize proportionally to wasted lookahead opportunity.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0 * (next_item_size - post_residual) as f64 / 20.0;
    }

    // Tight fits are good: reward small post_residual relative to mean residual.
    let mean_r = mean_residual.max(0.0);
    if (post_residual as f64) < mean_r {
        score -= (mean_r - post_residual as f64) * 0.15;
    } else {
        score += (post_residual as f64 - mean_r) * 0.10;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early in the stream
    // or the item would leave a very tight fit elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 15.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild pressure against accumulating many open bins with dead space.
    if open_bins_count > 4 && post_residual > 40 {
        score += (post_residual - 40) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize tiny dead space only when it is truly unusable relative to typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly/nicely into post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual likely dead space for the next item: penalize.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: empty bin should only win when fits are poor or scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let poor_fit = 1.0 - fill_ratio; // large when current fit is loose
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.5);
        // Reward new bin when: no/many alternatives, current fit is loose, late in stream.
        score -= 55.0 * scarcity * poor_fit * (0.5 + progress) / pressure;
        // But add a base cost so a new bin never wins on tight fits.
        score += 20.0 * (1.0 - poor_fit);
    }

    // Global residual context: prefer bins below mean residual (consolidate emptier space usage).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Slight time-horizon adaptation: early on, be conservative (favor tight packing);
    // later, allow more spread to keep flexibility for remaining items.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * t * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic dead-space penalty grows with stream progress
    score += progress * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr).powi(3) * (10.0 + 20.0 * progress);

    // Lookahead coupling: bonus if next item fits smoothly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack_after = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack_after * slack_after);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference for bins below mean residual (balancing open bins)
    score += 0.1 * (pr - mean_residual);

    // Slight openness pressure: fewer open bins preferred early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it partitions into capacity fractions
    let post = post_residual as f64;
    let frac = post / cap_f; // capacity fraction remaining

    // Penalize dead space: residuals that are too small to fit typical items
    if post_residual > 0 {
        // class of post_residual modulo common item sizes
        let mod10 = post_residual % 10;
        let mod20 = post_residual % 20;
        score += (mod10 as f64) * 0.15 + (mod20 as f64) * 0.05;
    }

    // Reward tight fits: post_residual small relative to capacity
    score -= (1.0 - frac) * 8.0;

    // Harmonic thresholds on post_residual via integer division
    let q = post_residual / 10; // which "decade class" the leftover falls into
    match q {
        0 => score -= 6.0,                 // near-perfect fill (0..10 left)
        1 => score -= 3.0,                 // good fill
        2 => score += 1.0,                 // moderate
        3 => score += 2.5,                 // leaves half-ish bin
        _ => {}                            // large residual: neutral
    }

    // Lookahead: does the next item fit into the post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (next_item_size as f64) * 0.05;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to wasted potential
        score += (next_item_size as f64 - post as f64).max(0.0) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this item would leave a large awkward residual in every existing bin,
    // or when the stream is early and bins are scarce.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        let new_bin_cost = 55.0 - 20.0 * progress;
        score = new_bin_cost;
        // If next item is large and no bin fits well, new bin is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty for proliferating open bins with large mean residual (fragmentation)
    if open_bins_count > 3 && mean_residual > cap_f * 0.5 && bin_residual != bin_capacity {
        score += 1.5;
    }

    // Slight preference for bins whose residual is closest below capacity fraction classes
    score += (frac - mean_residual / cap_f).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item nearly fits (small miss), slight penalty for creating blocking gap.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: more open bins -> prefer packing into existing ones.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // New-bin candidate: make it moderately attractive only when existing bins would
    // waste space badly; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: opening a new bin is necessary
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 0.4 * dead;
        }
    }

    // Penalize residuals far below the mean residual (creating unusable small pockets)
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.1 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight preference to fill older bins as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Mild penalty for opening a new bin when many bins are open and item is small
    if bin_residual == bin_capacity {
        score += 12.0 + 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tight * tight;

    // Penalize dead space that cannot fit a plausible future item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room for the lookahead item.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty to preserve choice among many fitting bins.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with low residual relative to mean (compact bins fill first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, be conservative: avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins pile up.
        score += 15.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin for a big item followed by another big item is fine.
            score -= 5.0;
        }
    } else if post_residual == 0 {
        // Perfect fill: big reward.
        score -= 30.0;
    }

    // Slight preference to place larger items early in stream.
    score -= 0.05 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let mut score = pr * pr / cap; // quadratic dead-space penalty

    // Smooth coupling: dead space matters more late in the stream.
    score *= 1.0 + 1.5 * progress * progress;

    // Reward using bins that are already substantially filled (smooth saturation).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 8.0 * fill * fill * (1.0 - fill);

    // Last-chance bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Lookahead: reward post-residual that still fits the next item smoothly.
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        score -= 3.0 * (1.0 - gap / cap).max(0.0) * (pr / cap);
    }

    // Mild pressure toward consolidating open bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: penalize slightly so it's only chosen for large items
    // that would leave big dead space in existing bins.
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (1.0 - it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets of capacity/4
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);

    // Reward tight fits (low class) more than linearly
    match class {
        0 => score -= 25.0,                      // post_residual < 25: excellent
        1 => score -= 10.0,                      // 25..50: decent
        2 => score -= 3.0,                       // 50..75: mediocre
        _ => {}                                  // 75+: mostly empty bin
    }

    // Penalize dead space that no typical item can use:
    // post_residual in (0, 10) is nearly unusable for min-size items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < quarter {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; residual becomes dead space weighted by size
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current bin fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open new bin when many bins are open and fragmented
        score -= 0.5 * open_bins_count as f64;
        // if mean residual is large, prefer reusing existing bins
        score += 0.4 * mean_residual;
        // if this is the last item, opening a bin is pure waste
        if next_item_size == 0 {
            score += 200.0;
        }
    }

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Modulo tiebreaker: prefer post_residual divisible by common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items are "dead space" — penalize them heavily.
    let dead_threshold = 10.0f64.min(mean_residual * 0.5);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 2.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // Penalize if next item won't fit here (wasted potential).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Pressure from many open bins: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild aversion to leaving residuals near the awkward mid-range.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 20.0 {
        score += (20.0 - pr) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover after that
            let post2 = post_residual - next_item_size;
            score -= 300.0 - (post2 as f64) * 2.0;
        } else {
            // next item won't fit here; penalize large dead space slightly
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless current bins are all poor fits
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.2;
    }

    // Late-stream tightening: fewer open bins is better near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight nonlinearity.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for typical future items.
    if post_residual > 0 && post_residual < item_size.min(40) {
        score += 12.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Two-item lookahead synergy: leftover fits next item with room to spare.
        if post_residual >= next_item_size + 10 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it when open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 25.0 * crowding;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0; // open bins can't host next item; fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Time horizon: early in stream, be picky (favor tight fits more);
    // late in stream, just close bins out.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - t);
    score -= 5.0 * t * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, prefer bins with small post_residual (tight packing);
    // later, tolerate larger residuals slightly less harshly but reward tightness more.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let mut score = post + 0.35 * post * post / cap;

    // Reward tight fits (small post_residual) with a progress-amplified bonus.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * (0.5 + progress_poly);

    // Penalize dead space that is too small to be useful later.
    if post > 0.0 {
        let dead = (post / cap) * (1.0 - post / cap);
        score -= 6.0 * dead; // reward mid-range residual usefulness
    }
    if post > 0.0 && post < 10.0 {
        score += 8.0 * (1.0 - post / 10.0); // tiny unusable slivers penalized
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: discourage unless current bin would leave large waste
    // or few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let waste_if_here = post; // equals item_size for new bin
        let waste_threshold = 0.5 * cap * (1.0 - progress_poly);
        if waste_if_here < waste_threshold {
            score += 25.0 + 10.0 * (1.0 - progress_poly);
        } else {
            score -= 3.0 * progress_poly;
        }
    }

    // Mild context coupling with mean residual and open bin count.
    score += 0.02 * (mean_residual - post).abs();
    score += 0.05 * open_bins_count as f64 * progress_poly;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let post = post_residual;
    let class = post % 10;
    // Penalize awkward residual classes (1,2,3 leave dead space; 0 is perfect)
    let class_penalty: f64 = match class {
        0 => -12.0,
        1 | 2 => 8.0,
        3 | 4 => 3.0,
        5 | 6 | 7 => -2.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer division thresholds: post_residual / 20 tier
    let tier = post / 20;
    score -= (tier as f64) * 2.5;

    // Perfect fit reward
    if post == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 6.0;
            // Harmonic pairing: (post + next) mod capacity fraction
            let combined = post + next_item_size;
            if combined % 25 == 0 { score -= 5.0; }
            if combined == bin_capacity { score -= 15.0; }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer it only when open bins are badly fragmented
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // New bin default penalty; reduced when mean residual is large (waste) or few fitting bins
        let mut new_pen = 14.0;
        if mean_residual > 45.0 { new_pen -= 8.0; }
        if fitting_bins_count == 0 { new_pen -= 20.0; }
        if item_size > 60 && mean_residual < item_size as f64 { new_pen -= 10.0; }
        score += new_pen * (0.5 + 0.5 * progress) + fragmentation * 0.05;
    }

    // Mild preference for tighter bins relative to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps much more strongly than large ones.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // dead space: nothing can ever fit here
        } else if post_residual <= 20 {
            score += 15.0; // barely usable for the smallest items
        } else {
            score -= 5.0; // generous residual is fine
        }
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: when many bins are open,
    // avoid opening new ones (penalize the new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (open_bins_count as f64).sqrt() + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocks the next item
    }

    // Mild preference for bins with below-average residual (fill emptier bins less).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size closely (chained placements).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + lookahead_gap);
        // Exact chain: next item fills bin completely.
        if post_residual == next_item_size {
            score -= 250.0;
        }
        // Penalize leaving residual too small for the next item (dead space trap)
        // unless residual is 0 (clean close).
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: strongly prefer zero post residual.
        score += post_residual as f64 * 0.5;
    }

    // Penalize bins far below mean residual (wasteful use of a roomy bin)
    // when other options exist; mildly reward bins near mean residual.
    if fitting_bins_count > 1 {
        let dev = post_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 {
        score -= 60.0;
        if post_residual > bin_capacity / 2 {
            score += (post_residual as f64 - bin_capacity as f64 / 2.0) * 1.5;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when the item is large relative to capacity and no
    // tight fit exists elsewhere; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 80.0 * tightness;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress;
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 90.0; // room for the chained pair
        }
    }

    // Small global pressure: with many open bins, consolidate.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 }
                   else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Lookahead bonus: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 2.0;
        }
    }

    // Scarcity: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residual already below the mean (consolidate fragmented space).
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // later, prefer filling open bins to avoid many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 4.0 + 8.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0 * progress;
        }
    } else {
        // Existing bin: reward more as stream progresses.
        score -= 3.0 * progress;
    }

    // Mild penalty for opening many bins early.
    if bin_residual == bin_capacity {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let post_norm = post / cap;
    // Tighter packing favored more as stream advances
    score += (post_norm * post_norm) * cap * (0.5 + 1.5 * p * p);
    // Cubic interaction term: penalize mid-range slack late in stream
    score += 20.0 * post_norm * (1.0 - post_norm) * (1.0 - post_norm) * p;

    // Reward near-perfect fits (small post_residual) with smooth exponential-like polynomial
    let fit_bonus = (1.0 - post_norm).powi(6);
    score -= 15.0 * fit_bonus * (1.0 + p);

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm * post_norm);
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score -= 10.0 * (1.0 - gap * gap);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - post_norm) * 2.0;

    // Deviation from mean residual: prefer bins near/below mean residual to balance
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that cannot fit typical small items are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class bonus: residuals divisible by common item sizes (5,10,20,25) are reusable
    let harmonics: [u32; 6] = [5, 10, 20, 25, 50, 100];
    for (i, &h) in harmonics.iter().enumerate() {
        if post_residual % h == 0 && post_residual > 0 {
            score -= (6.0 - i as f64) * 4.0;
            break;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // fresh bin: base score is full capacity; adjust by stream position
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
        // favor new bin if item is large and mean residual across bins is small
        if item_size as f64 > 0.6 * cap && mean_residual < 0.25 * cap {
            score -= 55.0;
        }
    } else {
        // penalize wasting a mostly-empty existing bin on a tiny item
        if item_size <= 15 && bin_residual > (bin_capacity as u32 * 3) / 4 {
            score += 25.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty scaled by mismatch class
            let mismatch = (next_item_size - post_residual) % 10;
            score += 5.0 + mismatch as f64;
        }
    }

    // Prefer filling bins that are already relatively full (tight packing)
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Tie-break toward fewer open bins when residuals are similar
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are unusable.
    let min_gap = 10.0; // smallest plausible item footprint
    if post_residual > 0 && (post_residual as f64) < min_gap {
        score += 25.0 + (min_gap - post_residual as f64) * 2.0;
    }

    // Lookahead (k=2): reward gaps the next item can actually use,
    // penalize gaps it cannot (they risk becoming permanent dead space).
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 8.0;
        } else {
            score += 3.0;
        }
    }

    // Perfect fit: zero residual is ideal, reward strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only open bin that fits, use it
    // rather than opening a new bin (never applies to the new-bin candidate).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure and stream progression: mild uniform terms that
    // tilt marginal decisions toward consolidating into existing bins
    // as the stream advances.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.05
           + mean_residual * 0.02
           - progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit in the leftover: penalize dead space
        score += 150.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 200.0 + 0.5 * item_size as f64;
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 400.0;
        }
    }

    // Early in stream: be slightly more conservative about tight fits
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless
    // the current fit is poor or the item is large and would leave a useful residual
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // Large items leaving large residuals are fine in a fresh bin
        if post_residual >= 20 && post_residual <= 50 {
            score -= 12.0;
        }
        // Discourage opening new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            let best_possible = post_residual as f64;
            if best_possible < 15.0 {
                score += 35.0; // item fits nearly perfectly somewhere else
            }
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead coupling: if next item could use this bin's post_residual, reward
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // perfect pair: this item + next item fill the bin
        } else if post_residual > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 10.0;
        }
        // Penalize if post_residual is just barely below next item (wasted slot)
        if post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
            score += 8.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual near mean (keeps distribution balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // When many bins are open, mildly prefer filling existing bins over new ones
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to item size (minimal waste)
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * waste_ratio * waste_ratio;

    // Early stream: slightly favor larger residual bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 3.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: quadratic dead-space penalty
    let mut score = r + 12.0 * r * rn;

    // Smooth progress coupling: later in stream, penalize residual more strongly
    let prog_coupling = 1.0 + 2.5 * progress * progress;
    score *= prog_coupling;

    // Cubic interaction between normalized residual and progress
    score += 30.0 * rn * rn * rn * progress;

    // Reward tight fits: small post residual relative to item size
    let item = item_size as f64;
    let tightness = 1.0 - (r / item.max(1.0)).min(1.0);
    score -= 8.0 * tightness * tightness;

    // Lookahead: bonus if next item fits into post residual
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0 * (next_item_size as f64) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize scattering across many open bins slightly, smoothed by mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: near-perfect fit (post_residual tiny) -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 20 {
        score -= 400.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 150.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 40.0;
    }

    // Modulo-10 harmonic bands: residuals that are multiples of 10 are reusable
    // by typical item sizes; penalize odd/awkward residuals.
    let band = post_residual % 10;
    if band == 0 {
        score -= 30.0;
    } else if band == 5 {
        score -= 10.0;
    } else {
        score += band as f64 * 1.5;
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size as f64) / cap;
            score -= 80.0 * (1.0 - slack);
        } else {
            // Dead space relative to the next item.
            score += (next_item_size as f64 - post) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening new bins when open bins are underutilized.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when mean residual is low.
        score += 60.0 + mean_residual * 2.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Prefer fuller bins (lower residual) among open bins.
        score += (bin_residual as f64 / cap) * 20.0;
    }

    // Progress scaling: tighten packing toward the end of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Crowding: with many open bins, prefer consolidating.
    score -= open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving gaps that cannot host the lookahead item but could otherwise be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward if post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer filling existing bins unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish, penalized slightly by open bin count pressure,
        // but rewarded when mean residual across open bins is too small to be useful.
        score -= 5.0;
        if mean_residual < item_size as f64 * 1.1 {
            score -= 15.0;
        }
        if post_residual < 10 {
            score += 60.0; // opening a bin that immediately creates dead space is bad
        }
    } else {
        // Existing bin: mild penalty proportional to wasted relative space.
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= 2.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Aggressive 2-step lookahead: perfect chaining bonus when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item chain: bin closes completely
        } else if next_item_size <= post_residual {
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin; penalize dead space proportionally
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer fullest packing
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins with residuals below mean when fit is good,
    // avoid draining bins that are already tight unless the fit is excellent
    if post_residual as f64 <= mean_residual {
        score -= 5.0;
    } else {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 20.0;
        // but if the item is large relative to capacity, opening fresh is fine
        score -= 0.1 * item_size as f64;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // many open bins with large mean residual: reuse instead of opening
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Slight preference for bins with smaller absolute residual among comparable fits
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space smaller than the minimum plausible item.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // If the next item exactly fills the leftover, strongly favor.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }
    // Many alternatives: mild penalty to encourage spreading.
    if fitting_bins_count > 3 {
        score += 3.0;
    }

    // Prefer bins with residual below mean residual (denser bins).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Time horizon: early in stream, be pickier about waste; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // Mild preference for keeping open-bin count low late in the stream.
    score += open_bins_count as f64 * 0.05 * progress;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (mean_residual / 2.0 > item_size as f64);
        if good_fit_exists {
            score += 60.0;
        } else {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap; // fill ratio of bin after placement

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr + 12.0 * pr * pr / (cap * cap);

    // Stream-progress coupling: later in stream, value tight packing more strongly
    let progress_weight = 0.5 + 2.0 * t * t;
    score -= progress_weight * fill * fill * cap * 0.15;

    // Penalize large dead space that nothing else fits: non-linear in pr
    let dead = pr / cap;
    score += 25.0 * dead * dead * dead;

    // Lookahead: reward leaving room for the next item (smooth coupling)
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        let closeness = 1.0 / (1.0 + (gap / cap).abs() * 8.0);
        score -= 6.0 * closeness * (1.0 - t * 0.5);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * t;
    }

    // New-bin candidate: penalize mildly early, more when open bins are loose
    if bin_residual == bin_capacity {
        let looseness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 18.0 + 40.0 * looseness * (1.0 - t);
    }

    // Mean residual alignment: prefer bins near the mean (smooth quadratic)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Slight congestion effect: many open bins -> prefer consolidation
    score += (open_bins_count as f64).ln().max(0.0) * fill * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fit classes are golden.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Modulo-10 harmonic classes: leftovers in {0,10,20,...} pair well with
    // typical item sizes; odd/prime residues are dead space.
    let r = post_residual % 10;
    if r == 0 {
        score -= 8.0;
    } else if r >= 7 {
        score += 6.0; // awkward residue class
    }

    // Integer-division thresholds: can the next item also land here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
            // tight chain: next item nearly fills the remainder
            if post_residual - next_item_size <= 5 {
                score -= 10.0;
            }
        } else {
            score += 4.0;
            // penalize leftovers that no common class can use
            if post_residual < 20 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when this bin would be left with unusable crumbs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let crumb_penalty = if post_residual > 0 && post_residual < 15 { 20.0 } else { 0.0 };
        score += 25.0 - 20.0 * progress + crumb_penalty
            + 0.05 * open_bins_count as f64;
    }

    // Waste relative to mean residual: placing into a below-average bin
    // balances residual distribution.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Fractional capacity coupling: reward filling past half capacity.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill >= 0.5 {
        score -= 6.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste — penalize them heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead gap, essentially unusable
        } else if post_residual < 20 {
            score += 18.0; // marginal gap, only fits very small items
        } else {
            // larger gaps decay in usefulness as they shrink
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    } else {
        // Perfect fit: completely eliminates dead space — reward strongly.
        score -= 60.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64 + 1.0);
    score -= 25.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit here would be terrible. Otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 30.0 - 45.0 * pressure;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 8.0;
        }
    }

    // Open-bins pressure: many open bins with scattered residuals -> prefer
    // consolidating into existing bins.
    score += 3.0 * open_bins_count as f64 * (1.0 - tightness);

    // Prefer bins whose residual is close to what we're consuming
    // (best-fit style) — penalize bins far larger than needed.
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.15 * waste;

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chains well).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual too small for the upcoming item — penalize mildly
        score += 10.0;
    }

    // Mean-residual coupling: if this bin's residual is below average,
    // using it up helps concentrate large gaps elsewhere.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Early in the stream, be slightly more open to new bins to build a
    // diverse pool; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (waste minimization).
    let post = post_residual as f64;
    if post <= 3.0 {
        score -= 40.0 * (4.0 - post);
    }

    // 2-step lookahead: reward leaving residual that exactly fits next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can chain into this bin: reward closeness of exact match.
            score -= 25.0 * (1.0 - gap / 100.0);
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += 10.0 + gap * 0.15;
        }
    }

    // Penalize residual far below mean (fragmented bin) mildly; reward large residuals kept tidy.
    score += 0.1 * (mean_residual - post).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * (1.0 - early);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin pairs well with a big follow-up
        }
    }

    // Prefer filling bins that are already mostly used (low residual relative to capacity).
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64) * 20.0;

    // Slight preference to spread load when many bins open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but don't waste a whole bin on a tiny item.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Lookahead: if the next item fits exactly into the post-residual, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves slack: partial reward proportional to how snug
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 30.0 * snug;
        } else {
            // next item won't fit here: penalize bins that would strand residual
            let stranded = post_residual as f64;
            score += 0.15 * stranded;
        }
    } else {
        // Last item: just minimize waste directly
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * (post_residual as f64).sqrt();
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    // or the fit in existing bins is bad.
    if bin_residual == bin_capacity {
        let mean_load = bin_capacity as f64 - mean_residual;
        // reward new bin when open bins are congested (low mean residual)
        let congestion = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 20.0 * (1.0 - congestion);
        // early stream: slightly favor consolidating into open bins
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - t);
        // if many open bins already, new bin is fine
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        // tiny items should never open a new bin
        if item_size <= 20 {
            score += 50.0;
        }
    }

    // Global: prefer bins whose residual deviates from the mean in a useful way
    // (placing into below-average-residual bins keeps big holes together elsewhere).
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Nonlinear nudge: smooth preference for residuals that are small multiples
    // of common item sizes (10..80) — squares waste less.
    let r = post_residual;
    if r > 0 && r < 10 {
        score -= 12.0; // near-perfect packing
    } else if r >= 10 && r <= 20 {
        score -= 4.0; // still usable by small items
    } else if r > 60 {
        score += 3.0; // large dead zone risk
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual (0..1)
    let prog = t * (1.0 - t) * 4.0; // peaked mid-stream, smooth
    score += 12.0 * prn * prn * (1.0 - prn) * (1.0 + 2.0 * t);
    score -= 8.0 * prog * prn * (1.0 - prn);

    // Tight fit reward (smooth, non-piecewise)
    let tight = (1.0 - prn).powi(6);
    score -= 15.0 * tight;

    // Lookahead: reward leaving space for the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = (next_item_size as f64 / cap).clamp(0.0, 1.0);
        let diff = prn - nx;
        let fit_next = (1.0 - (diff.abs() * 2.5)).max(0.0);
        score -= 10.0 * fit_next * nx * (1.0 - t * 0.5);
    }

    // Penalize waste relative to mean residual across open bins
    score += 0.05 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Late stream: prefer filling existing bins over opening new ones
    score += 5.0 * t * (prn - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    // Residuals that are "harmonically compatible" with common item sizes are less dead.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 -> very reusable (items 10..80, many multiples of 10).
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: divisible by 5 -> moderately reusable.
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class C: post_residual < 10 -> dead space, heavily penalize.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }
    // Zero residual = perfect fit, big reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Integer division thresholds: post_residual bucketed by quarter capacity.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 4.0; // small residual, low future utility
    } else if post_residual > 2 * quarter {
        score -= 2.0; // large residual, keep flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Harmonic pair: next item leaves a multiple-of-10 remainder again.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            } else if next_post % 5 == 0 {
                score -= 4.0;
            }
            if next_post < 10 && next_post > 0 {
                score += 6.0;
            }
        } else {
            // Next item cannot use this residual: residual may be stranded.
            score += 3.0;
            // Penalize more if residual falls into an awkward class (prime-ish, non-multiple of 5).
            if post_residual % 5 != 0 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: opening a bin is only attractive when current residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score = 30.0 + fragmentation * 0.1;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If many open bins with slack, discourage new bin.
        score += open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    // (place into bins with below-average residual to consolidate fullness).
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
