        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(20.0);
    } else {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 15.0 + pressure * 0.8 + mean_residual * 0.2;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap that only the next item barely fits, blocking others.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size + 10 && post_residual >= next_item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // exact match for the next item -> strong bonus
        if post == nxt {
            score -= 800.0;
        } else if post > nxt {
            // next item fits exactly-ish; reward closeness
            score -= 300.0 * (1.0 - diff / 100.0);
        } else {
            // next item would NOT fit -> penalize wasted residual
            score += 0.5 * (nxt - post);
        }
    }

    // Penalize small dead space that nothing can use (min item size 1, but typical 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * post_residual as f64 * progress;

    // New-bin candidate: only open a new bin if no decent fit exists
    if bin_residual == bin_capacity {
        score += 150.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward strongly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= post_residual as f64 {
            let slack = post_residual as f64 - ni;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Penalize blocking the next item proportionally to overflow.
            score += 6.0 * (ni - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than new ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 4.0 * pressure * (post_residual as f64 / cap);

    // Mean residual coupling: prefer bins near the mean residual (balanced packing).
    score += 0.6 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: late in the stream, be more conservative — keep large residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / cap);

    // New-bin candidate: only attractive when no good fit exists (large item, poor fits).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / cap).max(0.0);
        score += 35.0 - 40.0 * desperation * big_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: tightness of fit weighted by progress
    let tightness = 1.0 - (post_residual as f64 / cap);
    let poly = tightness * tightness * (1.0 + progress * tightness);

    // Reward tight fits (subtract), stronger as stream progresses
    score -= poly * (12.0 + 20.0 * progress);

    // Penalize mid-range residuals (dead space) with a smooth bump
    let r = post_residual as f64 / cap;
    let bump = 4.0 * r * (1.0 - r); // peaks at r=0.5
    score += bump * (6.0 + 8.0 * (1.0 - progress));

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving space for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            let x = gap / cap;
            score -= 10.0 * (1.0 - x * x); // exact fit for next item -> best reward
        } else {
            // penalize blocking the next item, scaled by how close we are
            let miss = (-gap) / cap;
            score += 8.0 * miss * (1.0 + progress);
        }
    }

    // New-bin candidate: make it mildly unattractive unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 * (mean_residual / cap);
        score += 14.0 - 10.0 * (1.0 - (-crowding * 0.5).exp());
        // late in the stream, consolidating is better than opening
        score += 6.0 * progress;
    }

    // Mild preference to fill bins with larger mean residual (waste reduction)
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    // Penalize residuals that fall into awkward harmonic classes (near-quarter dead zones)
    if class == 1 || class == quarter - 1 {
        score += 6.0;
    }

    // Integer-division threshold: post_residual in [1..9] is a tiny dead slot -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use this residual; penalize proportionally to wasted space
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive late in stream or when open bins are crowded
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score -= 8.0 * progress - 2.0 * crowding.min(4.0);
        // But a new bin is bad if some open bin has near-exact fit
        if post_residual == 0 {
            score += 0.0;
        }
    }

    // Prefer bins whose residual is close to item (tight fit) via fraction of capacity
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Mild preference for bins with residual in harmonic half classes
    if post_residual == bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Gaps too small for the NEXT item are also likely dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 15.0;
    }
    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates below the mean (fill the emptier... no,
    // fill the TIGHTER bins first to keep large residuals available).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        score = 55.0 + 30.0 * bad_fit - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // new bin helps the larger lookahead item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        }
        // Penalize residuals that are neither usable nor tight
        if post_residual < next_item_size {
            score += 3.0; // next item can't follow into this bin
        }
    }

    // Tightness reward relative to mean residual
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * (mean_residual / bin_capacity as f64 - tightness);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize large dead space that nothing (>=10) can use
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * mean_residual;
    }

    // Late-stream consolidation: favor filling existing bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits into post residual exactly well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect follow-up fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to overshoot
            score += 3.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() / 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with stream progress and open-bin count.
        score = 100.0 + 40.0 * progress + 15.0 * pressure;
        // But if no existing bin fits well, allow new bin: subtract when fitting bins are scarce.
        if fitting_bins_count == 0 {
            score -= 120.0;
        } else if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Late in stream, avoid new bins even more.
        score += 20.0 * progress;
    } else {
        // Reward filling bins that are already fairly full relative to mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0; // this bin is tighter than average; use its space
        } else {
            score += 2.0;
        }
        // Mild preference for bins whose residual is close to item size.
        let diff = (bin_residual - item_size) as f64;
        score -= 8.0 * (-diff / 20.0).exp();
    }

    // Time-horizon modulation: early on, be more exploratory (flatten differences),
    // later, sharpen preferences.
    let sharp = 0.7 + 1.3 * progress;
    score *= sharp;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: normalize post_residual relative to capacity
    let post_norm = post_residual as f64 / bin_capacity as f64;

    // Polynomial decay: small post_residual is heavily rewarded, especially late in the stream
    let fit_quality = 1.0 - post_norm * post_norm; // in [0,1], high when post_residual small
    score -= fit_quality * (1.0 + 2.0 * progress) * item_size as f64;

    // Penalize post_residual that is too small to fit the (known) next item smoothly
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).max(0.0);
        let usable = gap / bin_capacity as f64;
        // Reward when next item fits exactly-ish (small positive gap), penalize large wasted gap
        score += (1.0 - (1.0 - usable) * (1.0 - usable)) * 10.0;
        if post_residual < next_item_size {
            // Dead space for the lookahead: penalize quadratically with progress
            score += (next_item_size - post_residual) as f64 * (0.5 + progress);
        }
    }

    // Reward using the last-chance bin (avoid opening a new bin needlessly)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many open bins with high mean residual
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Smooth penalty for very tight fits that leave near-zero residual (often wasted)
    let tightness = 1.0 - (post_residual as f64 / (bin_capacity as f64 * 0.2).min(bin_capacity as f64)).min(1.0);
    score += tightness * tightness * 3.0 * progress;

    // Slightly favor opening a new bin early when fit is poor
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;
    let post_f = post as f64;

    // Dead-space penalty grows non-linearly for small unusable residuals.
    if post > 0 && post < eighth {
        score += 3.0 * (eighth - post) as f64;
    } else if post < quarter {
        score += 1.0 * (quarter - post) as f64 * 0.5;
    } else if post > 3 * quarter {
        // Large leftover residual is good (flexible bin).
        score -= 2.0;
    }

    // Modulo arithmetic: reward residuals that are multiples of common item sizes.
    let harmonic = post % 10;
    if harmonic == 0 {
        score -= 1.5;
    } else if harmonic <= 2 || harmonic >= 8 {
        score += 1.0;
    }

    // Lookahead: penalize if next item cannot fit into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 2.0;
            // Extra reward for near-perfect two-item packing.
            if post - next_item_size <= 2 {
                score -= 2.5;
            }
        } else {
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / cap;
        score = cap * 0.55 + 10.0 * (1.0 - crowding);
        if next_item_size > 0 && next_item_size <= bin_capacity && fitting_bins_count == 0 {
            score -= 6.0; // must open a new bin anyway
        }
        if progress > 0.8 && open_bins_count > 0 && mean_residual < item_size as f64 * 1.2 {
            score -= 3.0;
        }
    } else {
        // Slight preference for tighter existing bins relative to mean residual.
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Coupling: prefer filling bins whose residual is close to item size (exact fit).
    let diff = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += diff * 0.05;
    if diff == 0.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "unusable" dead space: residuals that are too small to hold
    // typical future items (below a useful threshold) are worse than large ones.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // the smaller the leftover below the threshold, the more it hurts
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is exactly consumed to a "clean" level,
    // i.e., tight fit relative to what the bin had.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 20.0;

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // rather than spreading out; penalize the new-bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3;

    // New-bin candidate (empty bin): make it costly unless the item is large
    // or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 40.0;
        // large items justify a fresh bin (they leave usable space anyway)
        score -= (item_size as f64) * 0.35;
        // early in the stream, opening bins is cheaper
        score -= (1.0 - progress) * 15.0;
        // if this is the only fitting option, opening a new bin is fine
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward
    // leaving that gap; otherwise penalize gaps that neither help nor fit.
    if next_item_size > 0 {
        if (next_item_size as u32) == post_residual {
            score -= 35.0;
        } else if next_item_size as u32 > post_residual {
            // gap too small for next item: dead space relative to lookahead
            score += (post_residual as f64) * 0.5;
        }
    }

    // Slight preference toward bins with residuals near the mean (balanced play).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
