    }

    // Reward bins whose post_residual stays close to mean_residual (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when open bins already exist; relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * (1.0 - progress);
        if open_bins_count == 0 {
