        }
    }

    // Slight preference for tighter fits overall
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let waste = post_residual as f64;
            let rel = waste / bin_capacity as f64;
            score += 10.0 + 25.0 * rel * rel;
        } else if post_residual >= next_item_size && post_residual > 0 {
            // Reward leaving room for the next item, scaled by how snug it is.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 12.0 * snug;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_penalty = (mean_residual - item_size as f64).max(0.0);
        score += 55.0 - 0.4 * open_bins_count as f64 - 0.15 * avg_fit_penalty;
        // Early in the stream, new bins are cheap; later, discourage them.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can also serve lookahead item
        }
    }

    // Mild preference for fuller bins overall (consolidation pressure).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill;

    // Global residual balance: avoid dumping into bins whose residual deviates
    // strongly from the mean (keeps a portfolio of usable gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nr = next_item_size as f64;

    // Base: post residual, slightly discounted as stream progresses
    let mut score = pr * (1.0 - 0.35 * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let x = pr / cap;
    score += 8.0 * x * x * (1.0 - x) * (0.5 + progress);

    // Lookahead: reward residuals that can fit the next item (smooth coupling)
    if next_item_size > 0 {
        let fit = (nr / cap).min(1.0);
        let usable = (x - nr / cap).max(0.0) / (1.0 - nr / cap).max(0.01);
        score -= 6.0 * (1.0 - usable).powi(2) * fit * (1.0 - progress);
        // penalize near-perfect but next-item-unusable dead space late in stream
        score += 4.0 * progress * (1.0 - fit) * x;
    }

    // Mean residual coupling: prefer bins deviating from mean toward tight fits
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bin moderately attractive only when residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues mod 10 classify dead space quality.
    let r = post_residual % 10;
    // Perfect-fit classes (0) are golden; small residues (1..5) are dead space.
    let class_penalty: f64 = match r {
        0 => -14.0,
        1..=3 => 9.0 + 3.0 * r as f64,
        4..=7 => 3.0 + 0.8 * r as f64,
        _ => -2.0 + 0.5 * (r - 7) as f64,
    };
    score += class_penalty;

    // Integer-division thresholds: how many items of the *lookahead* size fit after placement.
    if next_item_size > 0 {
        let fits_next = post_residual / next_item_size.max(1);
        if fits_next >= 1 {
            // Reward chaining with the next item, scaled by tightness of the chain.
            let chain_tightness = (next_item_size as f64) / (bin_capacity as f64);
            score -= 10.0 * chain_tightness * (fits_next.min(3) as f64);
            // Exact next-item fit is the ideal harmonic partner.
            if post_residual == next_item_size {
                score -= 22.0;
            }
        } else {
            // Placement strands the next item: penalize proportionally to next size.
            score += 4.0 + 0.06 * next_item_size as f64;
        }
    } else {
        // Last item: reward perfect closure.
        if post_residual == 0 { score -= 30.0; }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 16.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are fragmented (high mean residual spread vs item size).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its residual is maximal, so make it unattractive
        // unless current bins are badly fragmented.
        score += 18.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            // All open bins are too tight in spirit; new bin reasonable.
            score -= 12.0 * (1.0 - progress * 0.5);
        }
        if fragmentation > 40.0 {
            score += 5.0;
        }
        // Early in stream, a new bin is cheap insurance.
        if progress < 0.2 {
            score -= 6.0;
        }
    } else {
        // Existing-bin bonus scaled by how full the bin already is (favor dense packing).
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill;
        // Coupling with open-bin pressure: many open bins -> pack tighter.
        score += 0.15 * open_bins_count as f64;
    }

    // Mean-residual coupling: penalize placements that push residual far from the mean
    // (keeps the pool homogeneous and mergeable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small harmonic jitter on capacity fractions to break ties deterministically.
    let frac = (post_residual as f64 / bin_capacity as f64) * 100.0;
    score += 0.01 * ((frac as u32) % 7) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for even the
    // smallest item (size 1) are pure waste; residuals below a usable threshold
    // (e.g. < 20) are unlikely to be filled later -> strong penalty.
    let dead_threshold = 20.0f64;
    if post_residual == 0 {
        // Perfect fit: reward heavily.
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold {
        // Unusable small gap: penalize proportionally to how close it is to zero.
        let severity = (dead_threshold - post_residual as f64) / dead_threshold;
        score += 30.0 * severity;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Lookahead cannot fit here; mild penalty since next item may open a bin.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing ones; when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (1.0 - progress * 0.5);

    // Prefer bins whose residual is already below the mean (tighter bins get filled first),
    // which tends to close out bins and reduce open-bin count.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so as stream progresses.
        score += 10.0 + 20.0 * progress;
        // But if the current item is large, a fresh bin is actually good
        // (large items pair better with small leftovers elsewhere).
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Slight reward for larger fills (higher utilization of this placement).
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving a gap larger than next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare residual against mean residual: favor bins with less residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless this is early in the stream (cheap to open bins)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 500.0;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes wasteful placements more.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: penalize leaving residual that blocks the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt && (post_residual as f64) > 0.0 {
            score += 12.0 * (1.0 - post_residual as f64 / nxt);
        }
        // Reward residual that exactly accommodates the next item (chaining).
        if post_residual as u32 == next_item_size {
            score -= 18.0;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // More open bins -> keep consolidating; fewer open bins -> new bin cheaper.
        score += 3.0 * open_bins_count as f64;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 20.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If mean residual across open bins is large, reuse them instead.
        score += 0.4 * mean_residual;
    }

    // Prefer bins with residual close to item size (best-fit style) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;
    if bin_residual as f64 > mean_residual {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fits), scaled smoothly
    let mut score = pr;

    // Non-linear polynomial coupling: quadratic + cubic terms on normalized residual,
    // weighted by stream progress. Early on, tolerate loose fits; late, punish dead space.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += poly * cap * (0.5 + 2.0 * progress);

    // Reward tight fits more strongly as the stream progresses (smooth coupling)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * cap * (0.3 + 1.2 * progress);

    // Last-chance bonus: strongly favor this bin if it is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: penalize leaving a residual that can't fit the next item,
    // reward residuals that can. Smooth interaction with progress.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr >= nx) as i32 as f64;
        let gap = (pr - nx).abs();
        score += (1.0 - usable) * (10.0 + 20.0 * progress) + usable * (gap / cap) * (5.0 + 10.0 * progress);
    }

    // Slight penalty for bins already very loose relative to mean residual (spread waste)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: mild penalty so we prefer reusing open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "friendly"
    // (divisible into common item sizes) are less penalized.
    let pr = post_residual;
    if pr > 0 {
        let mut friendliness = 0.0f64;
        for d in [10u32, 20, 25, 50, 100] {
            if pr % d == 0 {
                friendliness += 3.0;
            }
        }
        if pr % 5 == 0 { friendliness += 1.0; }
        score -= friendliness;
    }

    // Penalize dead space that can never fit the next item.
    if next_item_size > 0 {
        if pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.6;
        } else {
            // Reward residuals that the next item fits snugly.
            let slack = (pr - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        score += 12.0
            - 6.0 * (step_index as f64 / total_items.max(1) as f64)
            - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 4.0; // big-next-item favors fresh bin
        }
    }

    // Integer-division threshold: residual below 10 is pure waste.
    if pr < 10 && pr > 0 {
        score += 5.0;
    }

    // Coupling with mean residual: prefer bins near the mean (balanced packing).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Progress-based tightening: late in the stream, waste hurts more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing can fit into are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small awkward gaps (10..30) are semi-dead unless the next item fits them.
    if post_residual >= 10 && post_residual < 30 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 25.0;
        } else {
            score -= 15.0;
        }
    }

    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    }
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * fill;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * open_bins_count as f64;
        score -= 10.0 * mean_residual / bin_capacity as f64;
    } else {
        // Mild pressure: with many open bins, prefer consolidating into existing ones.
        score += 0.3 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        score += 8.0;
    }

    // Late in the stream, tighten up: discourage loose fits.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 10.0 * progress * (1.0 - fill);

    // Prefer bins with residuals close to the item (best-fit flavor).
    score += 0.2 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize proportional leftover after the lookahead fill
            let after2 = post_residual - next_item_size;
            score -= 80.0 - after2 as f64 * 0.5;
        } else {
            // next item won't fit here; penalize if post_residual is small dead space
            let dead = post_residual as f64;
            score += dead * dead * 0.01;
        }
    }

    // Compare post_residual against mean residual of open bins.
    // Prefer bins whose residual after placement is close to the mean (keeps pool usable).
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin early in the stream; allow it more later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 120.0 * (1.0 - progress);
    }

    // Slight preference for tighter fits overall.
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that cannot plausibly be used by a future item.
    if post_residual > 0 {
        score += 8.0 * (post_residual as f64 / 100.0).powi(3);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item almost fits, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += 4.0 * ((next_item_size - post_residual) as f64 / 100.0);
        } else {
            score -= 2.0 * (post_residual - next_item_size) as f64 / 100.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: later in the stream, be more conservative with new bins —
    // favor reusing existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_ratio;

    // Compare against mean residual: bins with residual near the mean are
    // "typical"; prefer placing into bins with residual close to item size
    // (small waste) rather than huge or tiny residuals.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 3.0 * residual_gap / 100.0;

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current open bins have poor fit (high mean residual
    // waste) or post_residual would be very small but awkward.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 10.0;
        // If existing bins fit poorly (mean residual high), a fresh bin gains appeal.
        let mean_waste = 1.0 - (mean_residual / bin_capacity as f64);
        if mean_residual < 20.0 {
            score -= 18.0;
        } else if mean_waste > 0.7 {
            score -= 6.0;
        }
        // Late in the stream, avoid opening new bins.
        score += 15.0 * progress;
        // If many bins already open, discourage yet another.
        score += 1.5 * (open_bins_count as f64);
        // If next item is large, a fresh bin is more flexible.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // Small noise-free deterministic tie-breaker based on bin residual ordering.
    score += bin_residual as f64 * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: penalize large residuals less; late stream: penalize waste harder.
    let waste_weight = 1.0 + 2.0 * p2 - 0.5 * p3;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.01;

    // Perfect fit reward (smooth exponential decay of residual).
    if pr == 0 {
        score -= 50.0;
    } else {
        score -= 20.0 * (-(pr / cap) * 4.0).exp();
    }

    // Lookahead coupling: reward residual that fits next item smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_frac = next_item_size as f64 / cap;
        score -= 8.0 * (1.0 - (fit_frac - 0.5) * (fit_frac - 0.5)) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 3.0 * progress * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening bins when open bins fit well.
    if bin_residual == bin_capacity {
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        score += 12.0 + open_bonus * 2.0 - 10.0 * progress;
    }

    // Mean residual deviation: prefer bins close to mean (balanced packing).
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by small
    // capacities are more reusable (harmonic classes of 100: 50, 25, 20, 10).
    let harmonic_bonus = |r: u32| -> f64 {
        let mut h = 0.0;
        if r % 50 == 0 { h += 12.0; }
        else if r % 25 == 0 { h += 8.0; }
        else if r % 20 == 0 { h += 6.0; }
        else if r % 10 == 0 { h += 4.0; }
        if r % 5 == 0 { h += 2.0; }
        h
    };
    score -= harmonic_bonus(post_residual);

    // Dead space: small nonzero residuals are nearly unusable (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 { score -= 20.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway: leftover becomes dead space risk.
        score += (next_item_size - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // fragmented (high mean residual spread) or many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - 20.0 * fragmentation / bin_capacity as f64
                 + 10.0 * progress
                 - 2.0 * open_bins_count as f64;
        // New bin attractive if item is large and next item is small
        // (keeps big-item residue usable for small follow-ups).
        if next_item_size > 0 && next_item_size < item_size / 2 {
            score -= 15.0;
        }
    }

    // Mild tie-break: prefer filling fuller bins (lower residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    if post_residual > 0 {
        score -= 25.0 / post_residual as f64;
    } else {
        score -= 30.0; // perfect fit
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space the next item cannot use
        score += 8.0;
    }

    // New-bin candidate: neutral baseline; only preferred when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins with residual below the mean (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead space elimination).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if post == 0.0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 500.0 - post * 10.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a perfect two-item chain placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 0.5 {
            score -= 700.0;
        } else if nxt <= post {
            // Next item fits: reward proportionally to how well it fills.
            score -= 200.0 * (nxt / post);
        } else {
            // Next item won't fit here: penalize leaving a residual that is
            // neither small nor useful — a likely dead zone.
            let waste = (post - (post % nxt)) / cap;
            score += 80.0 * waste;
        }
    }

    // Compare post residual against mean residual of open bins: prefer bins
    // whose residual lands below average (tightening usage).
    score += 3.0 * (post - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when existing bins would
    // waste a lot; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline minus a bonus if no bin fits well.
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else {
            score += 120.0 + 0.5 * mean_residual;
        }
    }

    // Slight late-stream bias toward consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (post / cap);

    // Mild penalty when many bins are open and this one is nearly empty
    // (encourage spreading load to close bins out).
    if open_bins_count > 1 && post as f64 > 0.7 * cap {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit, dead space is minimal
    }

    // Penalize leaving residuals that no plausible item can use.
    // Items are 1..100, but small residuals (< smallest plausible chunk) are waste.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0; // tiny sliver is dead space
    }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            // next item still fits: mild bonus proportional to leftover-after-next
            let after_next = post_residual - next_item_size;
            score -= 6.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize more when the gap is small
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap.min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive when many bins are already open and
        // mean residual is high (fragmentation risk).
        let frag_pressure = mean_residual / bin_capacity as f64;
        score += 18.0 + 10.0 * frag_pressure + 2.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // But if the item is huge relative to typical residual, new bin is fine.
        if item_size as f64 > mean_residual + 10.0 {
            score -= 20.0;
        }
    }

    // Mild global pressure: when many bins are open with high mean residual,
    // discourage spreading into bins that would leave large residuals.
    if open_bins_count > 3 {
        let waste = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * waste;
    }

    // Time-horizon coupling: early in the stream, keep bins flexible
    // (penalize very small post residuals slightly less critical), late in
    // the stream, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let p = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // non-linear coupling of post_residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + p);
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * p;
    // lookahead: reward residual that fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)).powf(2.0)) * (0.5 + p);
    } else if next_item_size > 0 {
        score += 3.0 * p * (1.0 - norm_pr);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 * (0.3 + 0.7 * p);
    }
    // prefer bins tighter than mean residual (best-fit flavor, smooth)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).clamp(-1.0, 1.0);
    // new-bin candidate: penalize mildly early, allow late when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - p) - 4.0 * p * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // residue classes modulo 10 (item granularity hint) and capacity fractions.
    let post = post_residual as f64;
    let post_class = (post_residual % 10) as f64;

    // Reward residuals that belong to "useful" harmonic classes:
    // residuals divisible by 10 are most reusable for typical item sizes.
    let harmonic_bonus = if post_residual % 10 == 0 {
        6.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize small unusable dead space with nonlinear urgency.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (10.0 - post) * 0.15;
    }

    // Reward tight fits: small post-residual relative to capacity fraction.
    let fill = (item_size as f64) / cap;
    if fill > 0.8 {
        score -= 8.0 * (fill - 0.8) * 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this leftover; dead space penalty grows
        // with the size of the stranded residual.
        score += post * 0.1;
    }

    // Last-chance bin logic: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // open bins are already fairly full or none fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        score = cap * 0.35 + pressure * 40.0 - progress * 5.0;
        if open_bins_count == 0 {
            score -= 20.0;
        }
        // Discourage hoarding open bins when many already exist.
        score += (open_bins_count as f64) * 0.5;
    } else {
        // Mild preference for filling bins that deviate from mean residual
        // toward emptier state (balance load across bins).
        let dev = post - mean_residual;
        score += dev * 0.05;
    }

    // Integer-division threshold coupling on post_residual classes.
    let class_quotient = (post_residual / 20) as f64;
    score += class_quotient * 0.8;

    // Small penalty on residue class magnitude to break ties toward
    // rounder leftover values.
    score += post_class * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // Tiny sliver: nearly unusable dead space.
            score += 40.0 * (10.0 - pr) / 10.0;
        } else if pr < 20.0 {
            // Small gap: likely unusable by most items (min size 10).
            score += 15.0 * (20.0 - pr) / 10.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits relative to item size.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 20.0 * tightness * (item_size as f64) / (bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - gap / (bin_capacity as f64));
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: dead space confirmed.
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when current fit is very poor
    // (large post residual wasted) or bin residual barely fits.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        // Opening fresh is good when the item leaves lots of usable space.
        score -= 5.0;
        if waste >= 20.0 {
            score -= 15.0;
        }
        // But if this is the last chance in an existing bin, avoid new bin.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
