    }

    // New-bin candidate: only attractive when existing bins are nearly full
    // or the fit is very poor.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        score += 45.0 * (1.0 - tightness);
        if next_item_size > 0 && post_residual == next_item_size {
