                score -= 10.0;
            } else {
                score -= 5.0;
            }
            // tight fit lookahead bonus scaled by stream progress
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 8.0 * (1.0 - progress);
        } else {
            // next item won't fit: penalize proportionally to the gap's awkwardness
            let gap = next_item_size - pr;
            score += (gap as f64) * 0.35;
            // if gap lands in a bad harmonic class (prime-ish / non-divisible), extra penalty
            if gap % eighth != 0 && gap % quarter != 0 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 0.9;
        score += 30.0 + crowded;
        // mean residual high => open bins have room, new bin unattractive
        score += mean_residual * 0.5;
        // early in stream, opening fresh bins can be good
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // future needs space too
        }
    }

    // Prefer fuller bins: reward small residual before placement
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Mean-residual coupling: bins below mean residual are "filler" bins, favor them
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Integer-division threshold on post_residual / item ratio
    if item_size > 0 {
        let ratio = pr / item_size;
        if ratio == 0 {
            score -= 5.0; // item consumed more than half the residual: good packing
        } else if ratio >= 2 {
            score += 3.0; // lots left relative to item: questionable fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize small gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: discourage adding to many open bins lightly; encourage closing gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.6 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it beats tight fits (high base cost),
    // discounted when open bins are congested.
    if bin_residual == bin_capacity {
        score += 35.0 - (open_bins_count as f64) * 1.5;
    }

    // Slight preference for bins tighter than average (waste concentration).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect pairing
        } else if post_residual >= next_item_size {
            let next_leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_leftover / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: bins below mean residual are "tighter"
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Penalize creating large dead space relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny leftover is fine (near-perfect fit)
    }

    // New-bin candidate handling: only open a new bin when it's genuinely needed
    if bin_residual == bin_capacity {
        // Opening new bin: baseline cost, reduced late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0 - 10.0 * progress;
        // If existing bins are all poor fits (high mean residual wasted), new bin is okay
        if mean_residual > 40.0 && post_residual < item_size as f64 {
            new_bin_score -= 20.0;
        }
        // If this is the only option, allow it
        if fitting_bins_count == 0 {
            new_bin_score = -100.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: penalize if next item would be stranded by this placement.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Next item can't fit here after placement; if it also can't fit the
            // current residual, this placement doesn't lose opportunity.
            if next_item_size <= bin_residual {
                score += 3.0;
            }
        } else {
            // Next item fits in the post residual: reward keeping that option.
            score -= 4.0;
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score -= 2.0 * (1.0 - consolidation / bin_capacity as f64);
        // Early stream: be pickier about tight fits; late stream: just fill bins.
        score += 4.0 * waste_frac * (1.0 - progress);
    } else {
        // New-bin candidate: penalize relative to mean residual of open bins.
        score += 6.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > (bin_capacity as f64 * 0.5) as u32 {
            score -= 2.0; // big next item: fresh bin is fine
        }
    }

    // Small penalty scaled by item size to prefer placing larger items in tighter bins.
    score -= 0.02 * item_size as f64 * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.6 * progress) - 0.35 * cap * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Reward tight fits: low post_residual relative to item size
    let tightness = 1.0 - pr / (item_size as f64 + pr).max(1.0);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize dead space that next item can't use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / cap) * progress;
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize opening new bins when open bins have slack
    if bin_residual == bin_capacity {
        score += 4.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins below mean residual (larger residuals get lower score)
        score += 0.15 * (mean_residual - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class residuals into buckets of size 10 (capacity fractions).
    let post_class = post_residual / 10;
    match post_class {
        0 => score -= 30.0,              // near-perfect fit (0..9 leftover)
        1 => score -= 18.0,              // small but workable gap
        2 | 3 => score -= 5.0,           // medium gap
        4 | 5 => score -= 10.0,          // half-bin-ish: still reusable
        _ => {}                          // large gap: neutral
    }

    // Modulo-10 dead-space penalty: leftover that no item (>=1) of common
    // small sizes can split nicely is penalized via harmonic residue.
    let harm = (post_residual % 10) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += harm * 0.5;             // tiny slivers are dead space
    }

    // Reward closing the bin tightly when post_residual is 0.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_gap = post_residual - next_item_size;
        if pair_gap == 0 {
            score -= 35.0;
        } else if pair_gap < 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot fit here, mildly penalize (this bin may become stranded).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent harmonic fit. Penalize the fresh bin progressively
    // as the stream matures and open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 55.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;              // must open the first bin
        }
        // If next item is large relative to capacity, a fresh bin is safer.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — placing here consolidates full bins.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.25;
    } else {
        score += (-diff) * 0.15;
    }

    // Integer-division threshold: bins whose residual falls below the smallest
    // plausible item become waste; discourage leaving such bins.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Slight preference for bins that already carry load (avoid bin sprawl).
    if bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strongly reward.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Dead-space avoidance: residuals below the smallest plausible item (1..20)
        // are nearly unusable, so penalize them disproportionately.
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * 8.0; // steep penalty for tiny dead gaps
        } else if pr < 35.0 {
            score += (35.0 - pr) * 2.0; // moderate penalty for small gaps
        }
        // Reward residuals that can still host a typical future item.
        if pr >= next_item_size as f64 && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mild alignment with mean residual: bins tighter than average are more precious.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Progress: later in the stream, waste matters more (fewer chances to recover).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
