pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is strongly preferred.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space proportional to how unusable it is relative to
    // the smallest plausible item (min item size = 1 in the general case).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // reward partial lookahead fit proportional to fill of the gap
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the gap: penalize large leftover gaps
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (large post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 30.0;
        // cheaper to open a bin early in the stream (more future to fill it)
        score -= 25.0 * (1.0 - t);
        // cheaper if the current item is large and would leave big gaps elsewhere
        score -= 0.2 * item_size as f64;
        // more expensive if many bins are already open (consolidation pressure)
        score += 2.0 * open_bins_count as f64;
        // if many bins fit, prefer reusing one of them
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
    }

    // Global residual coupling: prefer placing into bins whose residual is
    // below the mean (tighten the tightest bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for bins with small absolute residual late in stream.
    score += 0.1 * (1.0 - t) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: post residual, with smooth polynomial shrink over stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize large leftover dead space non-linearly (quartic in normalized residual)
    score += 40.0 * pr_norm * pr_norm * pr_norm * pr_norm;

    // Reward tight fits (small post residual) more strongly mid-stream
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_frac = next_item_size as f64 / cap;
        score -= 15.0 * fit_frac * (1.0 - progress);
    } else if next_item_size > 0 {
        // penalize leaving a residual that wastes the next item
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score = pr + 10.0 - 25.0 * (1.0 - fragmentation) * (1.0 - fragmentation);
    }

    // Mild coupling with open bins count: prefer consolidating when many bins open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Mean residual alignment: prefer bins near the mean residual (smooth Gaussian-like)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Dead-space classes: tiny leftovers are good (bin nearly full), mid-range leftovers are bad.
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 15.0;
    } else if pr <= 20 {
        score -= 5.0;
    } else if pr <= 40 {
        score += 8.0; // awkward mid leftover
    } else if pr <= 60 {
        score += 3.0;
    }

    // Modulo-class harmonic: leftover divisible by common item sizes (10/20/25/50) is reusable.
    let pr_u = post_residual;
    if pr_u > 0 {
        let mut harmony = 0.0;
        if pr_u % 10 == 0 { harmony += 4.0; }
        if pr_u % 20 == 0 { harmony += 3.0; }
        if pr_u % 25 == 0 { harmony += 3.0; }
        if pr_u % 50 == 0 { harmony += 4.0; }
        score -= harmony;
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 4.0 * (1.0 - slack / cap); // tight chain fit rewarded
        } else {
            score += 5.0; // leftover unusable for next item
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer it only when all open residuals are poor fits.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        // New bin baseline: slightly worse than a decent existing fit, better than a bad one.
        score = 45.0 - 10.0 * early;
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 8.0; // open bins are nearly full -> fresh bin is fine
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 5.0; // large upcoming item likes a fresh bin
        }
    }

    // Slight preference for fuller bins overall (waste minimization).
    score -= (item_size as f64 / cap) * 4.0;

    // Progress-based tightening: later in stream, be greedier about filling bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - pr) / 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that cannot fit the smallest plausible future item (1..100 unknown).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a new bin is cheap.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = 50.0 + open_bins_count as f64 * 3.0;
        // Cheap to open early in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If existing bins fit poorly, new bin becomes attractive via low score.
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Penalize using bins far from mean residual (imbalance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
        // Mild pressure to consolidate into fewer bins.
        score -= open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly matches post_residual,
    // strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits here afterwards: reward proportionally to leftover slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item would NOT fit after placement: penalize dead space created.
            let mismatch = (next_item_size - post_residual) as f64;
            score += 6.0 * (mismatch / (bin_capacity as f64)) * (mismatch / (bin_capacity as f64));
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving more than average waste is bad.
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - (post_residual as f64)).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins would create big waste
    // or when the stream is early and we can afford spreading load.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_here = (bin_capacity - item_size) as f64;
        score = waste_here - 8.0 * (1.0 - progress);
        if next_item_size > 0 && waste_here <= next_item_size as f64 {
            score -= 10.0; // new bin can also chain the next item
        }
        if fitting_bins_count > 0 && waste_here > 45.0 {
            score += 20.0; // don't open new bins when a decent fit exists
        }
    }

    // Mild pressure to close out bins as the stream progresses.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += 0.6 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // Lookahead: penalize leaving residual just below the next item (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins with below-average residual (keep large residuals for future big items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.2 * diff;
    }

    // New-bin candidate: only attractive when open bins fit poorly or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (fitting_bins_count == 0) as i32;
        let big_gap = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        let penalty = 40.0
            - 20.0 * (1.0 - progress)
            - 15.0 * poor_fits as f64
            - 8.0 * big_gap;
        score += penalty.max(-5.0);
        // Discard tiny items into fresh bins: wasteful.
        if item_size < 20 {
            score += 30.0;
        }
    }

    // Mild preference for consolidating among many open bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, but with diminishing returns (quadratic coupling)
    let mut score = pr * (1.0 + 0.6 * (pr / cap).powi(2));

    // Cubic smooth interaction: large residuals matter more early, less late
    let norm = pr / cap;
    score += 8.0 * norm.powi(3) * (1.0 - progress) - 4.0 * norm * progress;

    // Perfect-fit reward (smooth bump around zero residual)
    let fit = (-pr / cap).exp();
    score -= 12.0 * fit;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack).exp();
        } else {
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Prefer tighter bins relative to the fleet mean residual
    score += 0.3 * (mean_residual - pr);

    // Slight bias against spreading across many bins early
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize post-residuals that fall into "dead zones": too small to be useful
    let dead_zone = post_residual > 0 && post_residual < 10;
    if dead_zone {
        score += 40.0;
    }

    // Reward tight fits (small post_residual) strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= eighth {
        score -= 25.0;
    } else if post_residual <= quarter {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
            // modulo harmonic: post_residual % next_item_size small means chainable
            let m = post_residual % next_item_size;
            if m < 5 {
                score -= 8.0;
            } else if m > next_item_size - 5 && next_item_size > 5 {
                score -= 5.0;
            }
        } else {
            // post-residual too small for next item: penalize proportionally
            let waste_ratio = post_residual as f64 / next_item_size as f64;
            score += 10.0 * waste_ratio;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer filling already-open bins when many bins are open (avoid bin proliferation)
    if bin_residual < bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
        score -= 3.0 * open_pressure.min(5.0);
    }

    // New-bin candidate: empty bin gets a moderate baseline so it only wins when
    // open bins have poor residuals
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if item is large, opening a fresh bin is attractive
        if item_size as f64 > 0.6 * cap {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Coupling with mean residual: bins far below mean residual are good targets
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Progress-aware tuning: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving space that can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0; // gap too small for next item: dead space risk
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins have poor fits or large residuals.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        // Penalize new bins mildly; reward when open bins are crowded (small mean residual).
        score += 25.0 - pressure * 0.8 - (bin_capacity as f64 - mean_r) * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees fit for lookahead
        }
    }

    // Progression: later in stream, prefer packing tighter into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: more open bins -> favor filling existing ones.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step fit
        } else if post_residual as u32 > next_item_size {
            score -= 6.0; // next item still fits: good chain
        }
        // penalize leaving residual that is unusable for next item
        if (post_residual as u32) < next_item_size {
            score += 4.0;
        }
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Relative to mean residual: prefer bins with more residual than average (fill emptier bins first)
    let resid = post_residual as f64;
    score -= (resid - mean_residual) * 0.15;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize tiny unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect closure
    }

    // Early in stream: keep bins balanced / prefer new bins less
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new bin candidate: penalize moderately, less as stream progresses
        score += 20.0 * (1.0 - 0.4 * progress);
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) >= item_size {
            score -= 3.0; // new bin can chain next item too
        }
    }

    // mild preference for bins with larger residual overall
    score -= bin_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Strong reward when this bin is the only one that can fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Dead-space penalty: small post_residual is good; huge leftover bad.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * waste_ratio * 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap = post_residual as f64;
            if gap < next_item_size as f64 && gap > 0.0 {
                score += gap * 0.3;
            }
        }
    }

    // Time horizon: early in the stream, be conservative with bin count;
    // later, prefer closing bins (packing into existing ones).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Global state: many open bins with high mean residual -> prefer filling them.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 2.0;
        score -= (mean_residual / bin_capacity as f64) * 4.0;
    }

    // New-bin candidate: empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + (mean_residual / bin_capacity as f64) * 10.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative, allow new bin
        }
    }

    // Prefer using bins with less residual (best-fit flavor).
    score += (bin_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: quadratic coupling of post_residual with stream progress.
    let pr_norm = post / cap;
    score += 6.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small relative to item size.
    let tightness = 1.0 - pr_norm;
    score -= 4.0 * tightness * tightness;

    // Penalize bins far from the mean residual (smooth divergence term).
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Lookahead coupling: penalize if next item cannot use the post residual smoothly.
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 2.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 2.5 * (-gap / cap) * (-gap / cap);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score -= 0.3 * progress;

    // New-bin candidate: make empty bins mildly unattractive unless residual waste would be large.
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * pr_norm * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes are prized (dead space minimization).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // class A: tiny residues <= 10 are nearly perfect
        if pr <= 10 {
            score -= 45.0;
        }
        // class B: residue matches common item sizes (10,20,..,80) -> reusable
        if pr % 10 == 0 {
            score -= 18.0;
        }
        // class C: residue divisible by 5 (half-class granularity)
        else if pr % 5 == 0 {
            score -= 8.0;
        }
        // class D: residue in awkward middle band 11..=30 -> dead space risk
        if pr > 10 && pr <= 30 {
            score += 12.0;
        }
        // class E: very large leftover is fine (bin stays flexible)
        if pr > 50 {
            score -= 6.0;
        }
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            score += 6.0;
        }
        // modulo harmony: next item shares residue class with post_residual
        if pr > 0 && next_item_size % 10 == pr % 10 && next_item_size <= pr {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if pr > 40 {
            score -= 5.0;
        }
    }

    // New-bin candidate logic: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, scaled by stream progress and open count
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + 25.0 * progress + 3.0 * (open_bins_count as f64).sqrt();
        // if next item is large, having a fresh bin is more valuable
        if next_item_size >= 60 {
            score -= 12.0;
        }
        // if mean residual across open bins is small, open bins are congested
        if mean_residual < 25.0 {
            score -= 10.0;
        }
    } else {
        // slight preference to fill emptier bins when residuals are tight
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 8.0 * fill;
    }

    // tie-break: prefer bins whose residual is close to item size (tight fit)
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64; // tiny gap = heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill, strongly reward
    }

    // Reward good fits: item occupying most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = post_residual - next_item_size;
        if lookahead_gap < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // Penalize if next item cannot use post_residual (dead space ahead)
    if next_item_size > post_residual && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, consolidate; when few, allow spreading
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residuals close to the mean (keeps residual distribution balanced)
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * mean_gap;

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized slightly by default; becomes attractive
        // only if it enables a near-perfect future pairing with next_item_size.
        let mut new_bin_score = 15.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && bin_capacity - next_item_size < 10 {
            new_bin_score -= 25.0;
        }
        if fill_ratio < 0.5 && fitting_bins_count > 0 {
            new_bin_score -= 10.0; // poor fits elsewhere -> new bin ok
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;
    score += tightness * 20.0;

    // 2-step lookahead: strongly reward if the next item fits the post_residual exactly/well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_leftover = post_residual - next_item_size;
            // Perfect chaining bonus: next item consumes all leftover.
            if next_leftover == 0 {
                score -= 60.0;
            } else {
                score += next_leftover as f64 * 0.5;
            }
        } else {
            // Next item cannot use this bin's leftover; penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: just minimize post_residual (already base).
    }

    // Relative-to-mean coupling: prefer bins with residual close to (but >=) what we consume,
    // penalize bins far above the mean residual (they hoard space).
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin unless the item truly fits poorly everywhere.
    if bin_residual == bin_capacity {
        // New bin: base score is full capacity; discount slightly so it competes,
        // but add penalty so existing decent fits win.
        score -= 10.0;
        if fitting_bins_count > 0 && post_residual > 0 {
            // If any open bin could fit, discourage new bin unless item is huge.
            if item_size < bin_capacity / 2 {
                score += 15.0;
            }
        }
    }

    // Small late-stream adjustment: as stream progresses, be slightly more conservative
    // about leftover space (dead space matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the residual space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_zone = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
    score += dead_zone * (0.5 + 0.5 * progress);

    // Lookahead: reward bins whose post-residual exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // post-residual too small for next item: mild penalty scaled by waste
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: strongly prefer fullest packing
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * fit_ratio;
    }

    // New-bin candidate handling: opening a bin is cheap early, expensive late.
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score = 55.0 - 30.0 * openness
            - 10.0 * (mean_residual / bin_capacity as f64)
            + 2.0 * (open_bins_count as f64);
        // If next item is large and current fits are poor, new bin more attractive.
        if next_item_size > 60 && fit_ratio < 0.6 {
            score -= 15.0;
        }
        return score;
    }

    // Prefer spreading load when many bins are open with high mean residual
    // (avoid fragmenting), but consolidate when mean residual is low.
    let mean_norm = mean_residual / bin_capacity as f64;
    if mean_norm > 0.5 {
        score += 5.0 * (mean_norm - 0.5);
    } else {
        score -= 5.0 * (0.5 - mean_norm);
    }

    // Mild reward for near-perfect closure of a bin.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Slight time pressure: late in stream, favor filling existing bins harder.
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = p / cap;
    let fit = fitting_bins_count as f64;
    let open_f = open_bins_count as f64;
    let mean_r = mean_residual / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + t) + pr_norm * t * t;
    score += 20.0 * poly;

    // Reward tight fits, more so late in the stream
    let tight = 1.0 - pr_norm;
    score -= tight * (1.0 + 2.0 * t) * 10.0;

    // Penalize opening/using bins when alternatives exist
    score += (fit - 1.0) * (fit - 1.0) * 0.5;

    // New-bin candidate: prefer it only when stream is early or residuals are large
    if bin_residual == bin_capacity {
        let new_bin_bonus = (1.0 - t) * 15.0 - pr_norm * 5.0 + (mean_r - pr_norm) * 8.0;
        score += new_bin_bonus;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= p {
            score -= (1.0 - (p - nx) / cap) * 6.0 * (1.0 + t);
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for many open bins with low mean residual (fragmentation)
    score += open_f * mean_r * mean_r * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality.
    // Residuals that are exact multiples of small divisors are "usable" classes.
    let pr = post_residual as u32;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit is always great
    } else if pr % 10 == 0 {
        -12.0 // round class: easy to fill with typical items
    } else if pr % 5 == 0 {
        -6.0
    } else if pr < 10 {
        15.0 // tiny sliver: dead space
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division thresholds on post_residual relative to item size classes.
    let slots = pr / item_size.max(1);
    score -= (slots.min(4) as f64) * 3.0;

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chain-friendly placement; reward if next item nearly fills it
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 - (slack / cap) * 10.0;
        } else {
            score += 6.0; // breaks the chain
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        // Prefer new bin if the item would leave a very tight or very wasteful residual
        let waste = post_residual as f64;
        if waste < 5.0 || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 18.0 + crowding * 0.5; // discourage proliferation when fit exists
        }
    }

    // Mean residual coupling: prefer bins far from the mean (balance extremes).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Slight late-stream tightening: keep bins packed as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable by future items (min size 1..100),
    // so penalize small positive residuals hard.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - pr) / 10.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0 * (20.0 - pr) / 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to item size.
    score -= 0.5 * (item_size as f64) * (1.0 - pr / bin_residual.max(1) as f64);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when no open bin offers a good fit
    // (i.e., this bin's residual is large and item leaves a big gap elsewhere).
    if bin_residual == bin_capacity {
        // Slight handicap so existing good fits win, but poor fits (large post_residual
        // on an existing bin) lose to a fresh bin.
        score = (bin_capacity as f64) * 0.5 + 0.6 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        if post_residual >= 0 && item_size <= 20 {
            score += 10.0; // tiny items: prefer squeezing into open bins
        }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: next item exactly fills the post residual
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0) * (1.0 - diff / bin_capacity as f64).max(0.0);
    }

    // Reward tight fits relative to mean residual of open bins
    let mean_r = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    let rel = post_residual as f64 / mean_r;
    score -= 25.0 / (1.0 + rel * rel);

    // Penalize dead space that nothing (size >= 10) could ever use
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize leaving large residual relative to capacity (wasted space)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * frac * frac;

    // Slight bias toward fewer open bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln1p();

    // Encourage matching against lookahead when next item is large
    if next_item_size >= 50 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify near-perfect fits.
    if post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        score -= 25.0; // perfect closure
    }

    // Penalize creating dead space that nothing small can use later.
    let progress = step_index as f64 / total_items as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny useless sliver
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // extra bonus if post_residual is close to next item size (good chain)
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Prefer filling bins that are already relatively full vs. leaving many bins open.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio;

    // When many bins are open, discourage spreading; encourage consolidation.
    score += 2.0 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Compare against mean residual: bins with residual near mean are neutral;
    // bins with much larger residual than mean are worse to leave behind.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 40.0; // default penalty for opening a new bin
        // Early stream: opening bins is cheaper; late stream: consolidation matters.
        score -= 25.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.1 * item_size as f64;
        // If few bins can fit the item and no good chain exists, allow new bin.
        if fitting_bins_count == 1 && (next_item_size == 0 || post_residual < next_item_size) {
            score -= 35.0;
        }
    }

    // Mild time-horizon modulation: late in stream, tighten everything.
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear penalty on wasted residual, growing with stream progress.
    let pr = post_residual as f64;
    let norm = pr / bin_capacity as f64;
    score += 40.0 * norm * norm * (0.5 + progress);

    // Reward tight fits: subtract a smooth bump centered near post_residual == 0.
    let tight = (-pr / 12.0).exp();
    score -= 25.0 * tight * (0.6 + 0.4 * progress);

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (-slack / 20.0).exp();
    } else if next_item_size > post_residual as u32 {
        // Dead space relative to the lookahead item penalized smoothly.
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 * (gap / 40.0).exp() * (1.0 - 0.5 * progress);
    }

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize scattering into many open bins; encourage consolidation early.
    score += (open_bins_count as f64).ln() * 3.0 * (1.0 - progress);

    // Slight preference toward bins below mean residual (filling emptier bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: prefer opening a new bin only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual % (bin_capacity / 4).max(1)) as f64; // 4 harmonic subclasses

    // Reward exact/near-exact fills (post_residual in low harmonic class)
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if class <= 4.0 {
        score -= 12.0; // near-perfect fill
    } else if post_residual < 10 {
        score += 15.0; // dead space: too small for any item (min size 10)
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * (next_item_size as f64);
        } else {
            score += 6.0;
        }
        // harmonic match: next item size congruent with post residual mod 25
        if next_item_size % 25 == post_residual % 25 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins that are already relatively full (low residual fraction)
    let fill_frac = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * fill_frac * fill_frac;

    // Penalize opening a new bin mid-stream when decent options exist,
    // but allow it early or when mean residual is high (fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty so it's only chosen when clearly better
        score += 25.0 - 20.0 * progress;
        if mean_residual < 15.0 {
            score += 10.0; // existing bins are tight; new bin less bad
        }
    } else {
        score -= 5.0; // mild bonus for reusing an open bin
    }

    // Fragmentation guard: penalize leaving residuals in awkward band (10..25)
    if post_residual >= 10 && post_residual < 25 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
