        score += 60.0 - 40.0 * progress;
        // If item is large relative to capacity, new bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
        // If many open bins already, prefer consolidating into them.
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // Global state coupling: bins with residual far from mean residual get slight preference
    // to keep residuals homogeneous (easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild time decay: early on, be more tolerant of imperfect fits (exploration).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in stream: prefer tight fits (minimize post_residual) mildly.
    // Late in stream: dead space matters more, so amplify post_residual penalty.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_post * norm_post * cap * 0.3;

    // Smooth quadratic reward for low post_residual (good fit), stronger as stream advances.
    let fit_term = (1.0 - norm_post);
    score -= (fit_term * fit_term) * (1.0 + progress) * 2.0;

    // Penalize very small residuals that create unusable dead space (smooth cubic gate).
    let dead_gate = (1.0 - norm_post / 0.15).max(0.0).min(1.0);
    score += dead_gate * dead_gate * 3.0 * (0.5 + progress);

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 2.5 * snug * snug;
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (nxt - pr) / cap;
            score += 1.5 * over * over;
        }
    }

    // Prefer bins with below-mean residual (consolidate fullness), smooth coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.2 * dev * dev.abs();

    // Mild penalty for spreading across many open bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
