pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Encourage using bins that are already mostly filled (small residual before placement).
    score += (bin_residual as f64) * 0.15;

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += (open_bins_count as f64) * 1.5;

    // If this bin is the only fitting bin, strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item larger than current: penalize wasting space that could hold it.
        score += 5.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * -0.5;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Slight preference to fill bins with residual close to the mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // next item fits; the smaller leftover after that, the better.
            let after_next = post_residual - next_item_size;
            score -= 20.0 - after_next as f64 * 0.25;
        } else {
            // next item cannot fit: dead space penalty, worse for large leftovers.
            score += (post_residual as f64).min(50.0) * 0.3;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when it wastes capacity, unless it's early stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * progress;
    }

    // Slight penalty for large leftover relative to capacity (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residuals.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 25.0 * (1.0 - tightness * 4.0).max(0.0);

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead (k=2): reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the pair nearly fills the bin.
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * pair_fill;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space too small for the next item.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize bins far below mean residual (fragmentation risk) mildly,
    // and bins far above mean residual (they are precious large-capacity bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress;

    // When many bins are open, encourage consolidation.
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins cheaply; small items should reuse.
        score += 30.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can host both item and next item
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is mandatory anyway
        }
    }

    // Mild preference for filling emptier bins when item is small.
    if item_size <= 25 {
        score += 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: reward tight fits via non-linearly compressed post-residual
    let mut score = (post * post) / cap + post * 0.5;

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more; early, larger residuals are tolerable
    let coupling = norm_post * norm_post * (1.0 - progress) * 30.0
                 - norm_post * progress * 20.0;
    score += coupling;

    // Penalize large residuals relative to mean residual across open bins
    score += (norm_post - mean_residual / cap).abs() * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack_fit * slack_fit);
        } else {
            score += 12.0;
        }
    }

    // Slight penalty for proliferating open bins early
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 2.0;

    // New-bin candidate: discourage opening unless residual would be large waste elsewhere
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction slot does it land in?
    // Classes keyed on integer division of post_residual into 10-wide buckets.
    let post_class = post_residual / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward when post residual class matches the next item's class (perfect future fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_class == next_class {
            score -= 12.0;
        } else if post_residual == next_item_size {
            score -= 25.0;
        }
        // next item fits with small dead space
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // next item cannot follow in this bin: penalize proportionally
        score += 8.0;
    }

    // Penalize dead space that is too small for any realistic item (<10)
    if post_residual < 10 {
        score += 15.0;
    }

    // Harmonic threshold: post_residual exactly at half capacity is a good rest state
    if post_residual * 2 == bin_capacity {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Waste-avoidance: penalize large residuals left with no matching next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Mild pressure to prefer bins with tighter current residual (best-fit core)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host even
    // the smallest plausible item (1..100 unknown distribution) are dead space.
    // Penalize small nonzero post_residuals super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            // Unusable gap: heavy quadratic penalty.
            score += (10.0 - pr) * (10.0 - pr) * 2.0;
        } else if post_residual < 20 {
            // Likely unusable for most items: moderate penalty.
            score += (20.0 - pr) * 1.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if lookahead then fits almost perfectly.
        let gap2 = post_residual - next_item_size;
        if gap2 < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead cannot fit here: mild penalty for creating a trap.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    // Make the empty-bin candidate (bin_residual == bin_capacity) less
    // attractive as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is fine; later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Slight reward for using already-open bins, scaled by pressure.
        score -= (open_bins_count as f64).min(10.0) * 0.8;
    }

    // Prefer bins tighter than average (best-fit flavor relative to mean residual).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for large post_residual being genuinely reusable:
    // if post_residual is large, it's not dead space, soften its cost.
    if post_residual >= 40 {
        score -= (post_residual as f64 - 40.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
