pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Global state coupling: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing residuals are large
        // and few bins are open (early stream).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 40.0 * (1.0 - progress);
        score += 0.3 * (mean_residual - post_residual as f64).abs();
        if open_bins_count > 0 {
            score += 8.0;
        }
    } else {
        // Existing bin: reward filling bins whose residual is near the item.
        let gap = (bin_residual - item_size) as f64;
        score -= 0.2 * gap;
        // Penalize placing into bins with much larger residual than mean
        // (keeps a spread of useful residual sizes).
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Mild time-horizon term: later in the stream, avoid leaving medium holes.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0 * progress; // tiny holes late are fine (near-full bins)
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0 * progress; // medium dead space is bad late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;
    // Penalize waste more sharply later in the stream
    score += (1.0 + 3.0 * progress) * (pr / cap).powi(3) * 20.0;
    // Reward tight fits smoothly
    score -= 25.0 * (1.0 - norm_pr).powi(2) * (0.5 + 0.5 * progress);
    // Last chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }
    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 15.0 * (1.0 - ((pr - ns) / cap)) * (1.0 - progress);
        } else {
            score += 10.0 * (ns - pr) / cap;
        }
    }
    // Mild preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * progress;
    // Deviation from mean residual: prefer bins near mean (balance)
    score += 0.3 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction classes.
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Penalize dead space non-linearly; small residuals (< ~20% capacity) are nearly useless.
    if frac < 0.20 {
        score += (0.20 - frac) * 60.0;
    } else if frac < 0.35 {
        score += 8.0;
    } else {
        // Reward leaving useful mid-range residual space.
        score -= frac * 15.0;
    }

    // Integer-division thresholds: how many items of the NEXT size fit in post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits = post_residual / next_item_size; // integer division threshold
        score -= fits as f64 * 6.0;
        // Exact modulo fit: next item fills bin perfectly -> strong reward.
        if post_residual % next_item_size == 0 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this leftover: leftover is likely dead space.
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Harmonic class of residual via modulo arithmetic on capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    if class < 8 {
        score += 5.0; // near a quarter-boundary: awkward sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when current bins are badly fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post) / cap;
        // New bin baseline: slightly worse than a good fit, better than terrible fits.
        score += 20.0 - fragmentation * 10.0 - progress * 5.0;
    } else {
        // Reward tight fits on existing bins.
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild penalty for proliferation of open bins with large mean residual.
    score += open_bins_count as f64 * 0.3 + mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "dead zone": post_residual too small to fit the smallest plausible item (1..100 stream).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Nonlinear penalty: gaps that can't fit the lookahead item are extra dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.15 * (post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that remain useful for the lookahead item.
        score -= 4.0 + 0.05 * (post_residual as f64);
    }

    // Tight-fit reward: filling most of the bin is excellent (quadratic in fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Penalize leaving mid-range residuals (awkward gaps ~ 20-45) super-linearly.
    if post_residual >= 20 && post_residual <= 45 {
        score += 0.4 * (post_residual as f64 - 20.0);
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins over new ones.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: only attractive when open bins are crowded or mean residual is low.
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 25.0 + pressure * 2.0;
        // Late in the stream, opening fresh bins is more acceptable.
        score -= 15.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Mild reward for keeping bin count from exploding.
        score -= 0.05 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (waste-free placement).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits
    // exactly (or nearly) into the post_residual of this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack; // exact 2-step chain gets the biggest bonus
        if slack == 0.0 {
            score -= 500.0; // perfect 2-item packing chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space, more so when
        // the leftover is small-but-unusable (worst kind of waste).
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 50.0 + 30.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Penalize bins whose residual is far above mean (hoarding space),
    // reward bins already below mean residual (tight bins).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when no open bin is a
    // good fit (post_residual of empty bin == capacity - item_size).
    if bin_residual == bin_capacity {
        // Default: discourage opening a new bin.
        score += 120.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 100.0;
        }
        // If next item is large and won't fit anywhere typical, new bin ok.
        if next_item_size > 0 && next_item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Late in the stream: prefer closing bins tightly (less room for waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Many open bins: favor consolidating into existing bins.
    if open_bins_count > 4 {
        score += 10.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual > 0 {
        // Reward residual that can still hold a plausible next item.
        if (next_item_size > 0 && post_residual >= next_item_size) || next_item_size == 0 {
            score -= 6.0;
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 22.0;
        // More attractive when the item is large (hard to place later) or
        // few bins can fit it, or many bins are already open and fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
        score -= 8.0 * open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        // Late in stream, prefer consolidating into open bins.
        score += 12.0 * progress;
        // If mean residual is large, prefer using existing space.
        score += (mean_residual - (bin_capacity as f64 - item_size as f64)).max(0.0) * 0.4;
    } else {
        // Prefer bins with residuals close to the item (minimize waste).
        let waste = (bin_residual - item_size) as f64;
        score += 0.15 * waste;
        // Slight preference for bins below mean residual (balance fragmentation).
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly damped
    let mut score = pr * (0.9 + 0.2 * progress);

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 - p) + norm_pr * p * (1.0 - norm_pr);
    score += 40.0 * coupling;

    // Penalize large dead space quadratically as stream advances
    score += 25.0 * norm_pr * norm_pr * p;

    // Reward tight fits (small post_residual) especially near the end
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * p);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            score -= 10.0 * (nx / cap);
        } else {
            score += 6.0 * (nx / cap);
        }
    }

    // Encourage balancing residuals toward the mean
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // Mild penalty for opening a new bin when many bins are open and fit exists
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 8.0 + 2.0 * fit_pressure - 5.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: dead space that cannot host
    // typical small items is penalized via integer-division thresholds.
    let small_class = post_residual / 10; // classes 0..10 (capacity 100)
    match small_class {
        0 => score -= 50.0,             // near-perfect fit
        1 => score -= 10.0,             // can host items >= 11
        2 => score -= 3.0,
        3 => score += 2.0,              // awkward zone
        4 => score += 5.0,
        5 => score += 8.0,              // half-full leftover, moderate
        6 => score += 4.0,
        7 => score += 1.0,
        _ => {}                          // large residuals are flexible
    }

    // Lookahead coupling: if next item exactly fits the post residual,
    // strongly favor this bin (chains two perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // residual leftover after a hypothetical next placement
            let chained = post_residual - next_item_size;
            score -= 40.0 * (1.0 - chained as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize tight fits more
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += 15.0 * tightness;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when current bins are nearly full on average
        // or many bins exist with low mean residual (fragmentation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 120.0; // base cost of consuming a fresh bin
        score -= 60.0 * (mean_residual / bin_capacity as f64); // reward when open bins are full
        score -= 30.0 * fragmentation / bin_capacity as f64;
        score -= 20.0 * progress * (open_bins_count as f64).ln().max(0.0);
        // Never open a new bin for a perfect fit elsewhere
        if post_residual == 0 { score += 500.0; }
    }

    // Modulo-10 harmonic penalty on post_residual: residuals that are
    // multiples of 10 align with common item sizes -> easier future packing.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mild preference for tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (sizes 1..100) are wasted. Penalize "unusable"
    // gaps (1..=9) very heavily, and mildly penalize awkward small gaps.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0; // dead space: nothing can ever fit
    } else if post_residual > 0 && post_residual <= 19 {
        score += 25.0; // only tiny items fit: nearly dead
    } else if post_residual > 0 && post_residual <= 34 {
        score += 10.0; // awkward gap
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but allow opening a new bin early when few bins exist.
    score += 2.5 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let lookahead_waste = post_residual - next_item_size;
            if lookahead_waste <= 9 {
                score -= 30.0; // next item fills gap almost perfectly
            } else if lookahead_waste <= 19 {
                score -= 12.0;
            }
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item cannot use this gap: gap likely becomes dead space
            score += 8.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" — finishing it off is valuable.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 6.0 * (mean_residual - bin_res_f) / bin_capacity as f64;
    } else {
        score += 4.0 * (bin_res_f - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate calibration: empty bin has residual == capacity.
    // Give it a mild base penalty so we only open new bins when genuinely better.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let match_gap = (post - nxt).abs();
        // Perfect 2-step fill: post_residual == next_item_size
        if match_gap < 0.5 {
            score -= 60.0;
        } else if nxt <= post {
            // Next item fits exactly into the leftover: scale reward by tightness
            let tightness = 1.0 - (match_gap / bin_capacity as f64);
            score -= 40.0 * tightness * tightness;
        } else {
            // Next item won't fit here: penalize leftover dead space that blocks lookahead
            score += 0.5 * (nxt - post);
        }
    }

    // Compare post_residual against mean residual: prefer bins that end below-average
    // residual (tighter packing than the fleet average)
    let post_f = post_residual as f64;
    score -= (mean_residual - post_f) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // a new bin when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * open_bins_count as f64;
    } else {
        // Slight preference for tighter existing bins (waste-aware best-fit)
        score += 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Early in stream: be slightly more willing to open bins to build a diverse pool
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post-residual waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item can fit in the post-residual, reward;
    // if this placement leaves a gap that fits nothing useful, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 5.0; // dead space too small for min item is acceptable
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 90.0;
        if fitting_bins_count == 0 {
            penalty = -10.0;
        } else if fitting_bins_count == 1 {
            penalty = 30.0;
        }
        // Late in the stream, avoid spawning extra bins with residual slack.
        penalty *= 1.0 + progress;
        score += penalty;
        // If the item is large relative to capacity, a fresh bin is more tolerable.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Prefer filling bins that deviate above the mean residual (balance load):
    // high-residual bins are good targets, low-residual bins are precious.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Slight preference for keeping the number of open bins in check early on.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize large post-residual (wasted space), non-linearly.
    let x = pr / cap;
    let mut score = x * x * 60.0 + x * 20.0;

    // Smooth stream-progress coupling: waste matters more later in the stream.
    score += 30.0 * progress * x * x;

    // Tightness reward: how snugly the item fits (item/residual ratio), smooth.
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tight * tight;

    // Lookahead: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nx = next_item_size as f64 / cap;
        score -= 15.0 * nx * (1.0 - x);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Mild competition pressure: more open bins -> prefer filling existing ones.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: penalize bins deviating from mean residual (balance).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: make empty bin attractive only for large items with poor fits.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 55.0 - 45.0 * fill * fill - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: penalize less when post_residual is small.
    let tightness = 1.0 - (post / cap);
    score -= 60.0 * tightness * tightness;

    // Harmonic classes: bucket post_residual into capacity fractions (1/8 buckets).
    let bucket = (post_residual * 8 / bin_capacity.max(1)) as f64;
    // Dead-space classes: residuals that are awkward (small but nonzero) are penalized.
    if post_residual > 0 && post_residual < item_size.min(bin_capacity / 4) {
        score += 25.0; // unusable sliver relative to typical items
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 120.0;
    }
    // Residual exactly matches next item: excellent lookahead fit
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 90.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // next item cannot fit here; mild penalty scaled by how much is wasted
        score += 10.0 + 20.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer filling bins with high residual relative to mean (consolidation).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Early in stream: slightly prefer opening/using fresh structure; late: pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * (1.0 - progress) * tightness;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // discourage opening new bins when alternatives exist
            score += 70.0 + 5.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (<= 10) are pure waste; penalize quadratically as they approach zero.
    if post_residual < 10 {
        score += (10 - post_residual as i32).abs() as f64 * 8.0;
    }
    // "Awkward gap" zone: residual that likely fits nothing useful later
    // (small but not zero). Penalize extra hard in the 1..=15 band.
    if post_residual >= 1 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 20 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent; if next item cannot fit but residual is
    // small, it's acceptable dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here: dead space penalty scaled by gap size
            score += (post_residual as f64) * 0.8;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; favor packing
    // into existing bins when many are already open.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has large post_residual by
    // definition; make it attractive only when the current item is large or
    // no good fit exists. Penalize the fresh bin mildly by default.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Large items (>60) are hard to place later, so a new bin is fine.
        if item_size > 60 {
            score -= 18.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Deviation from mean residual: bins far below mean residual are the
    // "tight" ones; packing them fully is good, so reward low-residual bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize wasted space relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly or nearly matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // Next item can chain into this bin: strong reward, tighter is better.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 15.0; // perfect chain bonus
            }
        } else {
            // Next item cannot fit in the leftover: penalize dead space,
            // scaled by how big the unusable remainder is.
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Coupling with mean residual: bins deviating from the mean
    // residual are less attractive unless the fit is very tight.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly
    // favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, be more willing to open new bins
    // (long horizon amortizes); late in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    // Penalize leaving very small unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when
    // existing fits are poor. Nudge it up slightly so consolidation wins ties.
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the wasted fraction, the bigger the bonus.
    let waste_frac = post_residual as f64 / cap;
    score -= 8.0 * (1.0 - waste_frac) * (1.0 - waste_frac);

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a fresh bin opening (never for the brand-new-bin candidate).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead (k=2): reward when the next item fits the post residual,
    // with an extra bonus for near-exact chain fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - chain_slack / cap);
        } else {
            // Post residual becomes dead space relative to the next item.
            score += 4.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Brand-new-bin candidate: penalize proportionally to how much room
    // is still available across open bins (fragmented small mean residual
    // makes opening a new bin relatively more attractive).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.4 * mean_residual;
        // Early in the stream, opening bins is cheap and builds flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
    }

    // Mild global pressure: with many open bins, prefer consolidating
    // into existing ones rather than spreading items thin.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_coupling = norm_pr * (1.0 + progress * (norm_pr - 0.5) * 2.0);
    score += progress_coupling * 20.0;

    // Penalize small post-residuals more strongly as stream advances (dead space matters late)
    let dead = (1.0 - norm_pr).powi(2);
    score -= dead * 15.0 * (0.5 + progress);

    // Reward tight fits smoothly
    score -= fit_ratio * fit_ratio * 10.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 5.0 * progress;
    }

    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Deter crowding many open bins
    score += open_bins_count as f64 * 0.15;

    // Mean residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0;

    // New-bin candidate: prefer it only when it beats tight fits
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless -> heavy penalty.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 25.0; // only fits very small items
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Reward using bins with small residual relative to mean (consolidation).
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual is a dead sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 10 || post_residual == 0 {
            score -= 45.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Baseline: opening a new bin is moderately costly.
        score = 55.0 + open_bins_count as f64 * 0.5;
        // If the only alternative creates dead space, new bin becomes better.
        if fitting_bins_count <= 1 && post_residual <= 10 && item_size < bin_capacity {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            score -= 60.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
            score += 0.3 * chain_waste as f64;
        } else {
            // next item cannot chain here: penalize proportionally to leftover mismatch
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer minimal post_residual strongly
        score += 1.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer tighter-than-average bins when fit is good
    let prog = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 * (0.5 + 0.5 * prog);
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 250.0 + 50.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 100.0; // opening new bin for a big item wastes space for the next
        }
    }

    // Slight preference for filling fuller bins
    score += 0.2 * (bin_capacity - bin_residual) as f64 * -0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted residual nonlinearly.
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64).powf(2.0) * bin_capacity as f64;

    // Perfect or near-perfect fit bonus.
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 12 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Dead space that the next item cannot use.
            score += (next_item_size as f64) * 0.15;
        }
    } else {
        // Last item: minimize residual as hard as possible.
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state: prefer filling bins when many bins are open and mean residual is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= mean_residual * 0.05 * (0.5 + progress);
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate logic: an empty bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        // Base penalty for opening a new bin, reduced when this is the last chance
        // or the item is large relative to capacity.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 14.0 * scarcity - 10.0 * item_frac;
        // Late in the stream, opening bins is less costly than fragmenting.
        score -= 6.0 * progress;
    }

    // Fragmentation penalty for mid-range residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear penalty on residual: small residuals are dead space, large residuals are wasteful
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (1.0 - norm_pr) * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize when the leftover cannot fit the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 8.0 * gap * gap * cap * 0.1;
        // Reward leaving room exactly for the next item
        let fit_gap = (pr - next_item_size as f64).abs() / cap;
        score -= 6.0 * (1.0 - fit_gap.min(1.0)) * (1.0 - fit_gap.min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild preference for consolidating when many bins are open
    score += 0.3 * (open_bins_count as f64).sqrt() * norm_pr;

    // Align residual with mean residual: prefer bins near the mean (smooth balancing)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * 0.1;

    // New-bin candidate: penalize opening a new bin unless residual savings justify it
    if bin_residual == bin_capacity {
        score += 6.0 + 14.0 * progress - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into
    // capacity-fraction bands (0, (0,25], (25,50], (50,75], (75,100))
    // and reward/penalize per class.
    let quarter = bin_capacity / 4;
    let class = (post_residual + quarter - 1) / quarter; // 0..=4
    match class {
        0 => score -= 30.0,                       // perfect fit
        1 => score -= 12.0,                       // near-tight, good dead space
        2 => score += 4.0,                        // half-full residual, mediocre
        3 => score += 10.0,                       // wasteful
        _ => score += 18.0,                       // barely used bin
    }

    // Modulo harmonic: post_residual divisible by common item sizes (10/20/25/50)
    // is more reusable by future items.
    if post_residual > 0 {
        if post_residual % 50 == 0 { score -= 10.0; }
        else if post_residual % 25 == 0 { score -= 6.0; }
        else if post_residual % 20 == 0 { score -= 5.0; }
        else if post_residual % 10 == 0 { score -= 3.0; }
    }

    // Lookahead harmony: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain fit: perfect follow-up
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 8.0 - (gap as f64).min(8.0); // better the tighter the follow-up
            if gap % 10 == 0 { score -= 3.0; }
        } else {
            score += 2.0; // next item cannot use this residual anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0; // default penalty: prefer reusing open bins
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits -> new bin is correct
        } else if mean_residual < item_size as f64 * 0.9 {
            score -= 20.0; // open bins are too full to be useful
        }
    }

    // Mean-residual coupling: penalize bins far from the fleet mean to keep
    // residuals homogeneous and harvestable.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let dead_threshold = 25.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward exact fit for the lookahead item (reserve-aware packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // residual can't fit next item: mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Bonus when residual can still hold next item
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: strongly prefer filling an existing bin
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, penalize it
    // proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 6.0 * open_bins_count as f64;
    } else {
        // Prefer tighter bins (smaller residual) slightly
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Early in stream: be more willing to open bins (less pressure);
    // late in stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits, but penalize leftover dead space after it.
            let chain_residual = post_residual - next_item_size;
            score += chain_residual as f64 * 0.3;
            // Bonus for chaining toward a perfect two-item fill.
            if chain_residual == 0 {
                score -= 250.0;
            }
        } else {
            // Next item cannot use this bin's leftover: dead-space penalty.
            score += post_residual as f64 * 0.5;
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last chance bin: prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Slight preference to keep new bins as a fallback early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already partially loaded (compactness).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, amplify non-linearly.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tight * tight;

    // Penalize exact-fit waste avoidance: perfect fit gets strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: only attractive when the fit into existing
    // bins would leave large dead space, or when lookahead pairs well with
    // the fresh residual.
    if bin_residual == bin_capacity {
        // Mild penalty so we don't open bins frivolously.
        score += 15.0;
        // But if next item would fit the residual left after placing here,
        // a fresh bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    // Lookahead: penalize placements that leave residual just below the next
    // item size (unusable wedge for the upcoming item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.1 * (next_item_size - post_residual) as f64;
    }
    // Reward residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Global state coupling: many open bins with high mean residual means
    // fragmentation; push toward filling the emptiest-feeling bins.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.15 * mean_gap;

    // Prefer bins with larger residual when item is large (avoid splitting
    // big items across awkward small leftovers).
    if item_size > 50 {
        score -= 0.05 * bin_residual as f64;
    }

    // Mild noise-free tiebreak by bin residual to keep determinism.
    score += (bin_residual as f64) * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (1.0 - progress) * (1.0 - progress);

    let mut score = pr + 12.0 * poly;

    // Penalize dead space more as stream progresses
    score += 30.0 * progress * norm_pr * norm_pr;

    // Reward tight fits
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly unless post_residual is large
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward bins whose post_residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    // Mean residual coupling
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..10 decile classes

    // Reward near-perfect fits (low class = tiny leftover)
    score -= 60.0 * (1.0 - frac) * (1.0 - frac); // quadratic reward for filling

    // Dead-space penalty: leftover that no future item (min size 1) can use is fine,
    // but leftover in "awkward" classes (just above typical small sizes) is bad.
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0; // tiny leftover is excellent
    } else if post_residual >= 6 && post_residual <= 12 {
        score += 15.0; // awkward dead zone
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of common sizes
    // (10, 20, 25, 50) are reusable — reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover anyway
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in stream
    // and when many open bins exist with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        }
        // Opening a new bin is attractive if current bin's post-fit is awful
        // and next item is large (better to start fresh for it).
        if next_item_size > 0 && next_item_size >= bin_residual - item_size && item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Slight preference for bins already below mean residual (consolidating fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 6.0;
    }

    // Harmonic coupling: item-to-residual ratio classes via integer division
    let ratio_class = if bin_residual > 0 { item_size / bin_residual.max(1) } else { 0 };
    match ratio_class {
        0 => score -= 10.0, // item small relative to bin: keep big bins for big items
        1 => score -= 18.0, // item fills most of bin: great
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
