        let t = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * t;
    }

    // Global coupling: prefer bins whose residual deviates from the mean
    // in the direction of tighter packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer using already-open bins when many are open (avoid bin sprawl).
    score += 0.3 * open_bins_count as f64;

    // Small dynamic nudge: reward tighter fits as the stream progresses.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor small post_residual (non-linearly).
    let tightness = 1.0 - (post / cap);
    score -= 45.0 * tightness * tightness * tightness;

    // Dead-space penalty grows with stream progress (late-stage waste is costlier).
    let waste = post / cap;
    score += 30.0 * waste * waste * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count <= 1 {
        score -= 25.0;
    }

    // Prefer bins whose residual is below the mean (consolidate large gaps).
    score -= 8.0 * ((mean_residual - bin_residual as f64) / cap);

    // Lookahead coupling: reward if next item fits into the resulting post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - ((post - nxt) / cap));
        } else if post > 0 && post < nxt * 3 {
            // penalize leaving slivers that nothing can use
            score += 10.0 * (1.0 - post / (3.0 * nxt));
        }
    }

    // New-bin candidate: mildly discourage opening new bins early, allow it late
    // or when the fit would be terrible.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 10.0 * progress;
        if post > cap * 0.6 {
            score -= 15.0; // item is small; fresh bin wastes capacity
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
