        }
        // modulo classes: residues divisible by common item sizes are reusable
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        }
        // integer-division thresholds: can another item of typical size fit?
        let slots = pr / 10; // how many 10-sized items fit
        score -= (slots as f64) * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize bins that strand the lookahead
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only open a new bin when the current item is large
    // and open bins are crowded (mean residual small).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (item_size as f64 + 15.0);
        if crowded && fitting_bins_count > 0 {
