        // If item is large relative to capacity, opening fresh is safer.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter existing bins as stream progresses.
    score -= 0.05 * (step_index as f64 / total_items.max(1) as f64) * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // since item sizes are >= 10 in the canonical stream (and small gaps waste
    // capacity). Penalize any nonzero but tiny gap heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 25.0;
    }

    // Dead-space pressure relative to capacity: quadratic penalty grows as the
    // leftover fraction becomes "awkward" (small but nonzero).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    if post_frac > 0.0 && post_frac < 0.15 {
        score += 40.0 * (0.15 - post_frac) / 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, opening new bins is cheaper.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate.
        // Attractive early or when few bins are open; penalized when many bins
        // are open unless the fit into existing bins is terrible.
        score += 10.0 + 1.5 * open_pressure;
        // If the next item is large and this item leaves a good gap for it,
        // a fresh bin can still be reasonable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    } else {
        // Existing bin: mild reward scaled by how many bins are open.
        score -= 0.4 * open_pressure;
        // Lookahead synergy: reward if the post_residual exactly accommodates
        // the next item (chains two tight fits).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Penalize bins whose residual is far above the mean (hoarding space).
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += 0.05 * dev;
        }
    }

    // Late in the stream, closing bins tightly matters more: amplify fit quality.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next <= 10 {
                score -= 150.0; // near-perfect chain
            } else {
                score -= 40.0 / (after_next as f64).sqrt(); // mild chain reward
            }
        } else {
            // next item cannot fit here: penalize dead space proportional to gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small unusable dead space (< 10 is worst since min item is 1..100 unknown, but keep small-slot penalty)
    if post_residual > 0 && post_residual < 15 {
        score += 30.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 120.0 + 200.0 * (1.0 - progress);
        // but allow new bin if lookahead chain is perfect
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: post_residual that is too small to ever be useful
    // (assume min item size ~1..100 unknown; treat residuals below 10 as likely dead).
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if the next item exactly fills the remaining space.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a residual that the next item cannot use.
        score += 8.0;
    }

    // Global state coupling: prefer filling bins when many bins are open
    // (consolidation pressure), but allow new bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * (2.0 + 4.0 * progress);

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin; filling it down toward the mean is good.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let gap = residual_f - mean_residual;
        score += 0.05 * gap;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize it mildly, scaled by how much residual
    // would be wasted relative to the item.
    if bin_residual == bin_capacity {
        let waste_ratio = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 10.0 + 30.0 * waste_ratio;
        // Late in the stream, opening new bins is expensive.
        score += 20.0 * progress;
    }

    // Prefer bins that are already partially filled (low residual) to reduce fragmentation.
    score += 0.1 * residual_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large post_residual more aggressively as stream progresses
    score += (pr * pr) / cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with a smooth cubic term
    score -= (1.0 - norm_pr).powi(3) * (8.0 + 6.0 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 5.0 * (nxt - pr) / cap * (0.5 + progress);
        } else {
            score -= 4.0 * (1.0 - (nxt - pr).abs() / cap);
        }
    }

    // Mean residual alignment: prefer bins close to the mean residual state
    score += 0.05 * (pr - mean_residual).abs() * (1.0 - progress);

    // Mild penalty for spreading across many bins early on
    score += open_bins_count as f64 * (1.0 - progress) * 0.2;

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: tiny slivers are dead space.
    let class = post_residual % 10;
    if post_residual > 0 {
        // Penalize dead space more sharply for small classes (1..9 slivers).
        score += match class {
            0 => -6.0,                       // perfect fill segment
            1..=4 => 14.0 - 2.0 * class as f64, // worst slivers
            5..=9 => 4.0 - 0.4 * class as f64,
            _ => 0.0,
        };
    } else {
        score -= 10.0; // exact fit is excellent
    }

    // Integer-division thresholds: post_residual in (0,10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chain fits, scaled by how snugly next item nests.
            let snug = (next_item_size as f64) / (post_residual as f64);
            score -= 8.0 + 6.0 * snug;
        } else {
            // Penalize leaving space the next item cannot use.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening fresh bins is only attractive
    // when the current bin would leave a bad harmonic class.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early (amortization) and when item is large.
        score -= 4.0 + 10.0 * (1.0 - progress) + 0.05 * item_size as f64;
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    // Mild preference to consolidate when many bins are open.
    score -= 0.15 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: placing into a bin below mean residual is good.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items are effectively wasted capacity. Penalize gaps in the
    // "unusable" band (0 < post_residual < ~10) very harshly, and penalize
    // moderately small gaps progressively.
    if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin completely.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver of dead space.
        score += 45.0;
    } else {
        // Progressive penalty for leaving small-but-not-tiny gaps;
        // larger usable gaps are naturally favored by the base term.
        let gap = post_residual as f64;
        score += (10.0 - (gap - 10.0) / 20.0).max(0.0);
    }

    // Reward bins whose residual can still accommodate the lookahead item
    // after this placement (keeps future flexibility).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys the only gap that could hold the next item.
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening yet
    // another one; the new-bin candidate has full residual, so add a term
    // proportional to residual to make full bins relatively cheaper.
    let openness = (open_bins_count as f64).ln().max(1.0);
    score += (bin_residual as f64 / bin_capacity as f64) * openness * 8.0;

    // Mean-residual coupling: if this bin is far below average residual
    // (i.e., nearly full), it is a good target; if far above average,
    // placing here wastes the "dense" bin.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Slight late-stream tightening: near the end, prefer tight fits even
    // more to avoid trailing dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits (post residual close to 0)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // smaller gap after next placement is better
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot fit: post_residual becomes dead space
            let dead = post_residual as f64;
            score += 10.0 + 0.3 * dead;
        }
    }

    // Penalize dead space relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a bin; reduced late in the stream or with many open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 - 10.0 * progress;
        // if item is large, a fresh bin is often good
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild preference for bins with tight residual (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less waste relative to capacity
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing (min size 1..100) can use well:
    // very small post_residual is good only if next item can use it
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward chaining
            score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize stranded residual
            score += 6.0 * (post_residual as f64 / 100.0).min(1.0);
        }
    } else {
        // last item: minimize residual directly
        score += 12.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are not opened casually
        score += 30.0;
        // but if existing fit is very loose (much waste), opening a new bin is fine
        if fit_ratio < 0.5 {
            score -= 22.0 * (1.0 - fit_ratio);
        }
        // early stream: allow more bins to spread load
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // many open bins with high mean residual: reuse is better, penalize new bin
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Global pressure: many open bins -> favor filling existing ones
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild bonus for moderate residual targets (~ perfect packing partners)
    let ideal = (bin_capacity as f64 - item_size as f64) * 0.5;
    score -= 4.0 * (-((post_residual as f64 - ideal) / 25.0).powi(2)).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild preference for tight fits (quadratic reward).
    // Late (progress ~ 1): stronger reward for filling bins completely.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * norm_pr * norm_pr * progress;
    score += poly * cap * 0.5;

    // Reward near-exact fits, smoothly scaled by progress.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.3 + 0.4 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 2.0;
    }

    // Lookahead: penalize leaving residual too small for the next item,
    // reward residuals that exactly accommodate it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = pr - nx;
            score -= (1.0 - gap / cap) * 10.0;
        } else {
            score += (nx - pr) * 0.5;
        }
    }

    // Mild penalty for opening new bins when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += (1.0 + openness * 0.1) * cap * (0.2 + 0.3 * progress);
        score += (mean_residual / cap).max(0.0) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10) are rewarded; awkward leftovers penalized.
    let cls = (post_residual % 10) as f64;
    score += cls * 0.8; // non-multiple-of-10 leftover is dead space

    // Deep dead-space penalty: tiny post_residual wastes the bin.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit
    }

    // Reward filling large fraction of the bin (integer-division thresholds).
    let fill_quartile = post_residual / (bin_capacity / 4); // 0..=3
    score -= (3 - fill_quartile.min(3)) as f64 * 6.0;

    // Lookahead coupling: if next item fits the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item can't use this leftover
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if mean residual across open bins is too small to be useful,
        // make new bin attractive.
        if mean_residual < (item_size as f64) * 0.6 {
            score -= 30.0;
        }
    }

    // Prefer tighter bins early in the stream (progress-scaled tightness bonus).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * (10.0 * (1.0 - progress));

    // Mild dispersion penalty: avoid creating extreme imbalance among open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are worthless; penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Gaps of 10..19 are only usable by small items; mild penalty scaled
        // by how much of the gap is "wasted" relative to the smallest item.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits (tight packing bonus).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 15.0;

    // Penalize bins whose residual is far above the mean (large leftover
    // space being destroyed); prefer bins already fragmented.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Open-bin pressure: with many open bins, discourage spreading to
    // fresh large-residual bins; prefer filling existing ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else. Make the empty-bin baseline
    // moderately high so it wins only on genuinely bad fits.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with stream progression.
        score += 55.0 + 25.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if the next item is large and this item is small, a fresh bin
        // preserves space for the big one.
        if next_item_size > item_size && next_item_size >= 60 {
            score -= 30.0;
        }
    } else {
        // Using an existing bin that also leaves room for the lookahead item
        // is very desirable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Placing here would strand the lookahead item: penalize.
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
            score += 8.0;
        }
    }

    // Slight preference to place into the bin with the smallest residual
    // (best-fit core), scaled by how close the fit is.
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item fits exactly into the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if post >= next {
            // Next item fits: reward tightness of that follow-up fit.
            score -= 40.0 * (1.0 - gap / 100.0);
            if gap == 0.0 {
                score -= 60.0; // perfect 2-item packing: residual fully consumed
            }
        } else {
            // Next item does NOT fit here: penalize leaving large unusable gap.
            score += 15.0 * gap / 100.0;
        }
    }

    // Tight fit reward for current item.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Penalize dead space relative to mean residual across open bins.
    let post_f = post_residual as f64;
    if post_f > mean_residual {
        score += 0.3 * (post_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_f);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when post residual would be small or item is large.
    if bin_residual == bin_capacity {
        let small_item = (item_size as f64) < 0.35 * bin_capacity as f64;
        if small_item && fitting_bins_count > 1 {
            // Don't waste a fresh bin on a small item that fits elsewhere.
            score += 80.0;
        } else {
            // Fresh bin is reasonable: base cost plus mild lookahead benefit.
            score += 20.0;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 25.0;
            }
        }
    }

    // Late in the stream: prefer closing out bins tightly (small residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_f / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect closure is ideal
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64); // penalize large dead space quadratically
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses leftover
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * use_ratio;
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            let waste = next_item_size - post_residual;
            score += 0.15 * waste as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        // base reluctance to open new bins
        score += 25.0;
        // more open bins with small mean residual => opening new bin less attractive
        score += 0.5 * open_bins_count as f64;
        // if mean residual across open bins is large, opening a new bin is wasteful
        score += 0.4 * mean_residual;
        // early in stream, be more willing to open bins (build a portfolio of partial bins)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // if no open bin fits, the new-bin call is the only option: make it win
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // favor filling already-open bins, especially those below mean residual (smaller residuals first)
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
        // reward using bins that are already partially filled
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Late-stream consolidation: near the end, prefer closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.85 {
        score -= 10.0 * (progress - 0.85) * (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr_norm.powf(1.0 + 2.0 * progress);

    // Smooth coupling: dead-space penalty grows quadratically with progress
    score += 0.8 * progress * pr_norm * pr_norm;

    // Reward tight fits smoothly (small post_residual relative to item)
    let tightness = 1.0 - pr_norm;
    score -= 0.5 * tightness * tightness * (1.0 - progress);

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2 * (1.0 - pr_norm);
    }

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let fit_ratio = nxt / (pr + 1.0);
            score -= 0.6 * fit_ratio * (1.0 - fit_ratio) * (1.0 - progress);
        } else {
            score += 0.3 * progress * (nxt / cap) * pr_norm;
        }
    }

    // Mean-residual coupling: penalize bins far from mean residual
    let mr = mean_residual / cap;
    let dev = pr_norm - mr;
    score += 0.4 * dev * dev;

    // New-bin candidate: smooth baseline that decreases with progress
    if bin_residual == bin_capacity {
        score = 0.9 + 0.5 * (1.0 - progress) - 0.3 * pr_norm;
    }

    // Mild open-bins pressure
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "nice" classes
    // (multiples of 10, or small dead space) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo-based harmonic classes on post_residual
    let mod10 = post_residual % 10;
    let mod5 = post_residual % 5;
    if mod10 == 0 {
        score -= 6.0; // perfectly aligned residual class
    } else if mod5 == 0 {
        score -= 3.0;
    } else {
        score += mod10 as f64 * 0.4; // ragged residual penalized
    }

    // Integer-division thresholds: residual buckets
    let bucket = post_residual / 10; // 0..10
    score += bucket as f64 * 0.3;

    // Reward tight fits (small post_residual) super-linearly
    score += (pr / cap).powi(3) * 20.0;

    // Dead-space penalty: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does post_residual fit next item harmonically?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 5.0;
            }
            score -= (gap as f64).min(10.0) * 0.5;
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score += 30.0 - progress * 10.0 - crowding * 0.5;
        if item_size as f64 / cap > 0.7 {
            score -= 10.0; // big items deserve fresh bins
        }
    }

    // Mild preference for bins below mean residual (balance load)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range means
    // anything < ~10 is nearly dead) are heavily penalized; large leftover gaps are mild waste.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr) / 10.0; // unusable sliver => strong penalty
        } else if post_residual < 25 {
            score += 12.0 * (25.0 - pr) / 25.0; // risky small gap
        }
    } else {
        score -= 25.0; // perfect fill is the best outcome
    }

    // Tightness reward: the smaller the post_residual relative to capacity, the better.
    score -= 20.0 * (1.0 - pr / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0); // mild pressure when alternatives exist
    }

    // Open-bin pressure: penalize bins proportionally to how many bins are already open,
    // discouraging scattering across many bins; but relax late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Mean-residual coupling: if this bin is far above mean residual, it's a "dirty" bin;
    // prefer bins already below the mean (they are closer to closing).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // New-bin candidate handling: an empty bin gets a baseline score equal to its leftover
    // plus a fixed opening cost, so it only wins when all open bins score worse.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // If the next item would fit nicely in this fresh bin's future residual, soften cost.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Lookahead: penalize placements whose leftover can't host the next item when the
    // leftover is otherwise decent-sized.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < bin_capacity {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // leftover that blocks the known next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: residual after placement exactly matches next item.
            let exact = (post_residual == next_item_size) as f64;
            score -= 18.0 * exact + 9.0 * (next_item_size as f64 / 100.0);
            // Slight penalty if residual is much larger than next item (wasteful slack).
            let slack = post_residual as f64 - next_item_size as f64;
            score += 0.08 * slack;
        } else {
            // Cannot host next item: penalize proportionally to how close we came
            // (near-miss residuals are the most frustrating dead space).
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.10 * miss;
        }
    } else {
        // Last item: pure tightness objective.
        score -= 6.0;
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.35 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or the stream is early (room to grow chains).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins for small items and late in the stream.
        score += 25.0 + 30.0 * progress - 20.0 * item_frac;
        // But if no open bin can chain with next item, new bin is less bad.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Mild bonus for many open bins being consolidated (avoid bin proliferation).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (waste), modulated by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress + 1.2 * progress * progress);

    // Non-linear coupling: residual^2 normalized, scaled by mean residual context.
    score += 6.0 * norm_pr * norm_pr * (mean_residual / cap).max(0.0);

    // Reward tight fits: subtract when post_residual is small relative to item size.
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (item_size as f64 / cap);

    // Penalize very large dead space that likely becomes unusable.
    score += 4.0 * norm_pr * norm_pr * norm_pr * cap;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward bins whose post residual could host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 5.0 * (1.0 - gap * gap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Crowding: when many bins are open, prefer consolidation (lower residual bins).
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual classes (harmonic residue classes)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 10 {
        score -= 20.0;
    } else if pr <= 20 {
        score -= 8.0;
    } else if pr <= 30 {
        score -= 2.0;
    } else {
        // large dead space: penalize extra for big leftovers
        score += (pr as f64 - 30.0) * 0.35;
    }

    // Modulo-class coupling: leftovers that pair with common small item sizes are useful
    let pair_bonus = |r: u32| -> f64 {
        match r {
            0 => 15.0,
            1..=10 => 10.0,
            11..=20 => 6.0,
            21..=30 => 3.0,
            _ => 0.0,
        }
    };
    score -= pair_bonus(pr);

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > pr {
            // next item won't fit here: leftover is dead for next step
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer fresh bin when all open bins fit poorly
    if bin_residual == bin_capacity {
        // baseline new-bin score slightly above a decent fit
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits: must open new bin
        } else if fitting_bins_count == 1 {
            // existing last-chance bin likely better
            score += 20.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for fuller bins relative to mean residual
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to close bins when many are open
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linear "dead zone").
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 15.0;

    // Penalize opening new bins when existing bins can fit the item,
    // scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 30.0 * progress;
        // If this bin is the last chance, opening a new bin is even worse.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, favor filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item would fit exactly in the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Slight bonus for bins below mean residual (balancing).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain a perfect second placement
        } else if post_residual >= next_item_size {
            score -= 60.0; // next item still fits here
        } else {
            score += 40.0; // dead space for next item
        }
        // Coupling: small leftover that also fails lookahead is worst
        if post_residual < next_item_size && post_residual < 10 {
            score += 80.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize creating tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 300.0 + 200.0 * progress; // new-bin candidate penalty
    }

    // Slight preference for bins with more residual to absorb variety
    score += 0.1 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional dead-space penalty: waste is worse when it can never be refilled.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: penalize placements that leave a residual poorly matched
    // to the next item; reward residuals that can host the next item too.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // alternatives are scarce or the current stream is early (long horizon ahead).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 45.0 - 30.0 * scarcity - 25.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        // An empty bin is naturally good for large items needing room.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Global-state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing slack rather than fragmenting further.
    let slack_pressure = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * slack_pressure * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    } else {
        score += 12.0 * slack_pressure * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Time-horizon effect: late in the stream, tighter packing matters more.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * horizon;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, small residuals become dead space, so penalize them more.
    let prn = pr / cap;
    let w = 0.5 + 1.5 * progress * progress;
    score += w * (prn * prn) * cap * 0.5;

    // Reward near-perfect fits smoothly (cubic decay around zero post-residual)
    score -= 12.0 * (-prn * 6.0).exp();

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 - pr).abs() / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // fraction of capacity left after placement

    // Class boundaries via integer division thresholds on post_residual.
    // Classes: [0..=9] perfect-ish, (10..=24] good, (25..=49] mediocre, (50..=99] wasteful.
    let class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else if post_residual <= 50 {
        3
    } else {
        4
    };
    score += match class {
        0 => -25.0,
        1 => -12.0,
        2 => 0.0,
        3 => 8.0,
        _ => 20.0,
    };

    // Exact-fit modulo harmony: post_residual divisible by small harmonics is fine.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainable: strongly reward.
            let chain_ratio = post_f / (next_item_size as f64).max(1.0);
            score -= 10.0 + 6.0 * (1.0 - (chain_ratio - 1.0).min(3.0) / 3.0);
            // Harmonic bonus if next item exactly consumes residual or a harmonic chunk.
            if post_residual == next_item_size || post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            // Dead space relative to the known next item.
            let waste = post_f - next_item_size as f64;
            score += (waste / cap) * 30.0;
        }
    } else {
        // Last item: prefer filling tightly.
        score -= 5.0 * (1.0 - frac);
    }

    // Last-chance bin: if this is the only bin that fits, opening a new bin is costly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
        // But if it would strand a huge residual AND next item is big, soften.
        if next_item_size > post_residual && post_residual > 40 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: empty bin starts at full residual.
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin: neutral-ish, slightly worse than a perfect fit.
        score = 55.0;
        // Prefer opening a new bin when open bins are fragmented (high mean residual).
        score -= (mean_residual / cap) * 20.0;
        // Late in the stream, opening new bins wastes capacity; prefer existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins already fit the item, a new bin is rarely needed.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // Small items: new bin can host many future items early on.
        if item_size <= 25 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Tie-break toward fuller bins (small bin_residual before placement).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Mid-range awkward gaps (10..=20) get a moderate penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item,
    // reward residuals that exactly or closely accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 10.0; // near-perfect lookahead fit
            }
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += open_bins_count as f64 * 3.0 + 10.0 * progress;
    } else {
        // Existing bin: slight bonus to consolidate when bins are plentiful.
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins with residual above the mean (keep balanced bins available).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match with next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step fill (post_residual == next_item_size) is highly rewarded.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits exactly-ish: reward small gaps.
            score -= 25.0 * (1.0 - lookahead_gap / (bin_capacity as f64));
        } else {
            // Next item would not fit: penalize proportionally to wasted lookahead.
            score += 10.0 + lookahead_gap * 0.15;
        }
    }

    // Penalize leaving large unusable dead space (below min item size 1..~10).
    if post_residual < 10 {
        score -= 15.0; // tight fit is great
    } else if post_residual > bin_capacity as f64 / 2.0 {
        score += 8.0; // wasteful placement
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + mean_residual * 0.1;
    }

    // Early stream: be slightly conservative, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that cannot fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Next item would need another bin anyway; mild penalty for wasting residual.
            score += 3.0;
        }
    }

    // New-bin candidate handling: discourage opening a new bin unless current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when open-bin fits are bad.
        score += 30.0;
        // More attractive when few bins fit the item or open bins are crowded.
        score -= 8.0 * (fitting_bins_count as f64).recip().min(1.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Later in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer filling bins whose residual deviates below the mean (compact bins first).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 2.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Mild preference for bins with larger residual when item is large (avoid fragmentation).
    if item_size > bin_capacity / 2 {
        score -= 0.05 * residual_f;
    }

    // Encourage closing out nearly-full bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual <= 5 {
        score -= 15.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let fit = fitting_bins_count as f64;
    let next = next_item_size as f64;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    // Early on, prefer filling bins tightly (low post_residual); later, keep
    // some slack because future small items may use it.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * (1.0 - progress)) * cap;

    // Smooth cubic coupling of item size with residual tightness.
    let tightness = 1.0 - norm_pr;
    score -= item * tightness * tightness * 0.5;

    // Reward near-perfect fills smoothly (gaussian-like on normalized residual).
    score -= 30.0 * (-(norm_pr * 8.0) * (norm_pr * 8.0)).exp();

    // Last-chance bonus: strongly favor using this bin when it is the only fit.
    let last_chance = (fit <= 1.5) as i32 as f64;
    score -= last_chance * 25.0 * (0.5 + 0.5 * progress);

    // Lookahead: penalize if next item can't use the post residual smoothly.
    if next > 0.0 {
        let usable = (pr - next).max(0.0);
        let waste = 1.0 - (usable / cap).min(1.0);
        score += waste * waste * 10.0 * (1.0 - progress);
        // Bonus if next item fits exactly into post residual.
        if pr >= next && (pr - next) < 10.0 {
            score -= 15.0;
        }
    }

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with slight progress-aware bias.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into integer-division buckets.
    // Leftovers that are "clean fractions" of capacity (0, small, or large) are usable;
    // mid-range dead zones (roughly 30..49) are the worst.
    let pr = post_residual;
    let dead_zone = pr >= 30 && pr <= 49;
    if dead_zone {
        score += 12.0;
    }
    // Perfect fit reward: harmonic class 0 (pr % 10 == 0)
    if pr % 10 == 0 {
        score -= 6.0;
    }
    // Post-residual exactly fits next item: excellent lookahead harmony
    if next_item_size > 0 && pr >= next_item_size {
        let next_class = (pr / next_item_size.max(1)) as f64;
        score -= 3.0 * next_class.min(3.0);
        if pr == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to how much it misses
        let miss = (next_item_size - pr) as f64;
        score += 4.0 * (miss / cap).min(1.0);
    }

    // Tightness coupling: prefer filling bins tightly, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 8.0 * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: empty bin gets a mild default penalty unless
    // no open bin fits well (large item relative to all residuals)
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > 60 || fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mean residual deviation: prefer bins whose residual is below mean (fuller bins)
    score += 2.0 * ((bin_residual as f64) - mean_residual).max(0.0) / cap;

    // Modulo harmony on item size: items in "coarse" classes (multiples of 10) pack well
    if item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 2.5;
    }

    // Penalize very small unusable leftovers slightly more as bins accumulate
    if post_residual < 10 && post_residual > 0 {
        score += 3.0 + 0.5 * open_bins_count.min(10) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Gaps that can only fit tiny items are half-dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer consolidation when many bins open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins below mean residual (keep residuals balanced / avoid stranding).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate: make it moderately attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 40.0; // perfect two-item fill
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space.
        score += 15.0 + 0.3 * (post_residual as f64);
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Prefer bins with residuals below mean (consolidating waste).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Late in the stream, avoid opening new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits perfectly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 2.0;
        }
    }

    // Time horizon: early in stream, prefer opening new bins (keep options open);
    // late in stream, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = (1.0 - progress) * 10.0;
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
    } else {
        score += (1.0 - progress) * 3.0;
    }

    // Crowding: many open bins -> favor consolidating into existing bins.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps balance) but reward below-mean residuals (denser bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Prefer bins that are already fairly full.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize dead space more strongly later in the stream (quadratic coupling)
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: small post_residual gets a smooth cubic bonus
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post residual can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (nxt / cap);
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "large residue" classes (still reusable) are better than tiny dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward next item fitting into the post-residual (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic bonus: stronger when the leftover after the chain is near zero
        let chain_left = (post_residual - next_item_size) as f64;
        score -= 12.0 + 10.0 * (1.0 - chain_left / cap);
    }

    // Penalize dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Integer-division thresholds: leftover divisible into common item classes
    // (10,20,25,50) is reusable; odd leftovers are worse.
    let leftover_class = post_residual / 10;
    let divisible = post_residual % 10 == 0;
    if divisible && post_residual > 0 {
        score -= 3.0 + leftover_class as f64;
    } else if post_residual > 0 {
        score += (post_residual % 10) as f64 * 0.4;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // near-perfectly (perfect fit class) or nothing else fits.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 30.0;
        if waste == 0 {
            score -= 100.0; // perfect fit in fresh bin: excellent
        } else if waste <= 5 {
            score -= 25.0;
        }
        // Mild discount late in the stream when many bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Prefer tighter bins relative to the mean residual (best-fit flavor).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Harmonic modulo coupling between item and residual capacities
    if (bin_residual % item_size.max(1)) == 0 && item_size > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 0.0; // exact fit, ideal
    } else if post_residual <= 10 {
        // tiny dead space below the smallest plausible item: heavily penalized
        score += (11 - post_residual) as f64 * 6.0;
    } else if post_residual < 30 {
        // moderate dead space: moderate penalty
        score += (30 - post_residual) as f64 * 1.5;
    } else {
        // large residuals remain usable: mild reward
        score -= (post_residual as f64 - 30.0) * 0.3;
    }

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residual that still fits the lookahead item (k=2 lookahead)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= next_item_size as f64 * 0.5;
        } else {
            // bin becomes useless for the next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // brand-new bin candidate: base cost plus pressure from open bins
        score += 40.0 + open_bins_count as f64 * 8.0 * (0.5 + 0.5 * progress);
    } else {
        // using an existing bin relieves open-bin pressure slightly
        score -= open_bins_count as f64 * 0.4;
    }

    // Mean-residual coupling: if mean residual across bins is high, prefer
    // consolidating into this bin to reduce fragmentation
    score -= mean_residual * 0.15;

    // Slight late-stream tightening: prefer tighter fits as stream progresses
    score += (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead match (small leftover after next item).
    else if next_item_size > 0 && post_residual > next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - leftover / bin_capacity as f64);
        score += leftover * 0.8;
    }
    // Next item cannot fit here: penalize proportionally to wasted lookahead.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Penalize large dead space beyond what the mean residual justifies.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.3;

    // Slight time-decay pressure: later in the stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already captured), but
    // amplify reward for near-perfect fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 30.0 * (fit_ratio - 0.9);
    }

    // Penalize large dead space relative to capacity, especially when the
    // leftover can't plausibly hold the next item.
    let dead = post_residual as f64 / bin_capacity as f64;
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += 8.0 + 0.1 * (next_item_size as f64 - post_residual as f64);
        } else {
            score -= 5.0; // leftover usable by lookahead: bonus
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // With many fitting bins, prefer the fullest one; post_residual already
        // encodes that, add mild tie-break toward low mean residual divergence.
        score += 0.05 * fitting_bins_count as f64;
    }

    // Prefer bins whose residual deviates from the mean (consolidate waste).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs().sqrt();

    // Time horizon: early in the stream, be frugal with open bins; late,
    // consolidate to close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_open = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual > item_size as f64 * 1.2;
        if decent_open {
            score += 25.0; // discourage opening when decent fits exist
        } else {
            score -= 10.0; // encourage fresh bin for large items
        }
    }

    // Mild penalty for very small post_residual that is still unusable.
    if post_residual > 0 && post_residual < 5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth polynomial shaping
    let x = post / cap;
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like, penalizes mid residuals

    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // later in stream => care more about tight fits (low post_residual)
    let coupling = poly * (0.5 + 2.5 * progress * progress);
    score += 40.0 * coupling;

    // Reward using a bin whose residual closely matches the item (smooth quadratic)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 30.0 * (1.0 - fit_gap * fit_gap) * (0.3 + progress);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            let shortfall = (nx - post) / cap;
            score += 25.0 * shortfall * shortfall;
        } else {
            // smooth reward for leaving room for the lookahead item
            let room = post - nx;
            score -= 8.0 * (room / cap) * (1.0 - room / cap);
        }
    }

    // Last-chance bin bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Mildly discourage opening new bins when many bins exist with room
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 12.0 * (1.0 - progress) + 10.0 * pressure * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Prefer bins below mean residual (consolidating space)
        score += 6.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes via integer division thresholds.
    // Small dead space is bad (wasted capacity); large residual is good (future flexibility).
    let post_class = post_residual / 10; // classes 0..=10
    // Penalize tiny leftover classes heavily (dead space), reward larger ones mildly.
    let class_penalty: [f64; 11] = [60.0, 45.0, 30.0, 18.0, 10.0, 5.0, 2.0, 0.0, -2.0, -4.0, -6.0];
    score += class_penalty[post_class as usize];

    // Modulo coupling: if next item exactly fits post_residual, strong reward (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // reward small second-order leftover, penalize awkward leftovers
            let np = next_post as f64;
            score += (np / 10.0).powi(2) * 0.8;
            // harmonic class of the second-order residual
            if next_post % 10 == 0 {
                score -= 3.0; // clean class boundary residual is reusable
            }
        } else {
            // next item cannot fit here; mild penalty proportional to overshoot
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    // for the item (item much smaller than mean residual gap implies fragmentation).
    if bin_residual == bin_capacity {
        // baseline for fresh bin: keep it competitive but not dominant
        score = (bin_capacity - item_size) as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early in stream, opening bins is cheaper; later, prefer filling existing bins
        score += progress * 20.0;
        score += open_bins_count as f64 * 1.5;
        // if next item is large, a fresh bin is valuable
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0;
        }
        // if mean residual is large, existing bins are roomy; discourage new bin
        score += mean_residual * 0.3;
    }

    // Global pressure: many open bins with high mean residual -> tighten packing,
    // prefer bins whose residual is below mean (consolidating small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder than large residual (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 15.0 * (1.0 - tightness.min(1.0));

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).sqrt() * 2.0 * (0.5 + progress);

    // New-bin candidate: make empty bins less attractive unless the item fits perfectly.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size == bin_capacity {
            score -= 100.0; // perfect fill of a fresh bin
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // dead space that blocks the next item
    }

    // Prefer bins below mean residual (keeps residuals balanced, avoids many half-empty bins).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: small post_residual is good.
    let fit_tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fit_tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 25.0 * next_fit;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to next item: penalize proportionally.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Relative to mean residual: bins with less residual than average are
    // "more filled" — prefer using them up to avoid fragmenting many bins.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Slight preference for existing bins over opening a new empty bin,
    // unless the new bin offers a much better long-run structure.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Opening a new bin is more attractive early in the stream
        // or when many bins are open (diversity of residual sizes helps).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize bins whose residual would become tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item is large and nearly equals post residual, extra reward (perfect chaining).
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 && post_residual > 0 {
        score -= 10.0;
    }

    // Time horizon: early in the stream, be more conservative (prefer compacting
    // existing bins); late in the stream, opening fresh bins is less costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 15.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bias;
    }

    // Global state: many open bins with high mean residual -> prefer compacting
    // into existing bins rather than opening another.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        if bin_residual < bin_capacity {
            score -= 8.0;
        } else {
            score += 10.0;
        }
    }

    // Mild preference for bins that are already fairly full before placement.
    let fill_before = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_before * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: waste after placement (primary driver)
    let mut score = post;

    // Tight-fit reward: quadratic coupling of fill ratio with post_residual
    let fill = item / cap;
    score -= 30.0 * fill * (1.0 - post / cap);

    // Smooth non-linear interaction: waste penalized more as stream progresses
    score += 20.0 * (post / cap) * (post / cap) * (0.5 + progress);

    // Lookahead coupling: reward residual that fits next item, penalize near-miss dead space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            let gap = (nxt - post) / cap;
            score += 25.0 * gap * gap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - post / cap);
    }

    // New-bin candidate: penalize opening a bin unless current waste is severe
    if bin_residual == bin_capacity {
        let severity = (post / cap - 0.15).max(0.0);
        score += 15.0 + 60.0 * (1.0 - severity.min(1.0)) * (0.3 + 0.7 * (1.0 - progress));
    }

    // Mild dispersion pressure: prefer bins deviating from mean residual (consolidation)
    score += 0.05 * (res - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 4 classes.
    let quarter = bin_capacity / 4;
    let leftover_class = post_residual / quarter; // 0..4

    // Reward tight fits strongly (small post_residual => low score).
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 2.0;

    // Harmonic class penalty: leftovers in awkward middle classes are dead space.
    match leftover_class {
        0 => score -= 12.0,                       // near-perfect fit
        1 => score += 2.0,                        // 25-50% residual, ok
        2 => score += 9.0,                        // 50-75% residual, wasteful for big items
        _ => score += 4.0,                        // >75% residual
    }

    // Modulo coupling: leftover divisible by common item-size classes is reusable.
    let reusable = |r: u32| -> bool {
        r == 0 || r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0
    };
    if reusable(post_residual) && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain the next item here.
            let slack = post_residual - next_item_size;
            score -= 10.0 + slack as f64 * 0.08;
            // Harmonic bonus if next item leaves a class-0 leftover again.
            if (post_residual - next_item_size) / quarter == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's remainder.
            score += 8.0;
            // Penalize more if the remainder is tiny (dead space) — modulo classes.
            if post_residual < quarter / 2 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing bins are crowded or item is large.
        let new_bin_bonus = 14.0
            + item_size as f64 * 0.15
            + pressure * 10.0
            + progress * 5.0
            - open_bins_count as f64 * 0.5;
        score = new_bin_bonus;
        // A new bin is bad if a fitting bin exists and the item is small.
        if fitting_bins_count > 0 && item_size <= bin_capacity / 4 {
            score += 25.0;
        }
    }

    // Small global tie-breaker toward bins with residual close to item size.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest future item are waste.
    // Assume minimum plausible item size ~10 (fallback 1). Dead zone: 1..10 unusable gap.
    let min_item = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_item {
        // Fully unusable sliver: strong penalty proportional to wasted fraction.
        score += 40.0 + (min_item - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward: subtract to strongly prefer exact fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit reward: post_residual small but usable (0 < post_residual <= 15).
    if post_residual > 0 && post_residual <= 15 {
        score -= 12.0;
    }

    // Coupling with mean residual: penalize bins far tighter than average (fragmented),
    // reward bins with residual near/above mean (keeps a spread of usable gaps).
    let pr = post_residual as f64;
    let diff = pr - mean_residual;
    score += 0.15 * diff;

    // Dead-space interaction: if post_residual is a dead gap AND below mean, extra penalty.
    if post_residual > 0 && post_residual < min_item && pr < mean_residual {
        score += 20.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing bins (penalize new bin).
    // New-bin candidate has bin_residual == bin_capacity; discourage unless few bins open
    // or the fit into existing bins is bad (handled by dead-space penalties above).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 8.0 + 2.5 * pressure;
    } else {
        // Existing bin: mild reward that grows with open_bins_count (consolidation pressure).
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // (otherwise we open a new bin and strand this residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap <= 15 {
            score -= 10.0;
        }
    }
    // If next item would be blocked by post_residual (dead space for it), penalize mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < min_item {
        score += 10.0;
    }

    // Stream progression: late in stream, consolidate harder (favor existing bins).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= 10.0 * progress;
        } else {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with a non-linear penalty
    let pr = post_residual as f64;
    score += pr * pr / (bin_capacity as f64 * 2.0);

    // Aggressive 2-step lookahead: reward if the next item fits exactly into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        // Perfect lookahead match: strong reward
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Reward closeness, scaled by how much of next item's size is covered
            score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        }
        // Penalize if next item cannot fit into post residual (dead space risk)
        if pr < nxt {
            score += 15.0 * (nxt - pr) / bin_capacity as f64;
        }
        // Extra reward if next item exactly fills the bin after this placement
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: simply prefer minimal waste
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are wasteful targets
    score += (pr - mean_residual).max(0.0) * 0.5;
    score -= (mean_residual - pr).max(0.0) * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well anywhere
    if bin_residual == bin_capacity {
        // Opening a new bin wastes (capacity - item_size); penalize unless current item is large
        score += 30.0 - 0.3 * item_size as f64;
        // If next item is large too, a fresh bin may be good for pairing
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Slight preference for filling nearly-full bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - pr) * 0.05;

    // Prefer bins among many open bins that are closest to closure
    if open_bins_count > 1 {
        let closure = 1.0 - pr / bin_capacity as f64;
        score -= closure * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize leaving dead space that few future items could use.
    let dead_zone = (post_residual as f64) / (bin_capacity as f64);
    if dead_zone > 0.0 && dead_zone < 0.10 {
        score += 10.0 * (0.10 - dead_zone) / 0.10; // tiny unusable slivers are bad
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when the
    // item fits poorly everywhere else or residuals are already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        // Reward new bin when item is large or open bins are highly fragmented.
        score -= 6.0 * (item_size as f64) / 100.0;
        score -= 10.0 * fragmentation;
        // Penalize new bin if item would leave a large hole in a fresh bin
        // while good fits exist elsewhere.
        score += 14.0 * poor_fit * poor_fit;
        // Early in the stream, having few bins, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly
    // or well; penalize if next item cannot fit anywhere afterwards.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect chain
        } else if post_residual >= next_item_size {
            let fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 6.0 * fit_quality;
        } else {
            // Next item won't fit here anyway; slight bonus for closing bin tightly.
            score -= 2.0;
        }
    }

    // Prefer filling bins with larger mean residual (reduce fragmentation globally)
    if bin_residual != bin_capacity {
        let above_mean = (bin_residual as f64) - mean_residual;
        score -= 0.05 * above_mean;
    }

    // Mild preference for fewer open bins overall.
    score += 0.3 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as it gets small
    score += 18.0 * norm_post * (1.0 - norm_post) * (norm_post - 0.5) * cap * (0.5 + progress);

    // Tight fits rewarded, quadratically
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Stream progress coupling: prefer tight packing later in stream
    score += 8.0 * norm_post * norm_post * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Mean-residual coupling: penalize bins far from mean residual
    score += 3.0 * ((post - mean_residual) / cap).abs();

    // Open-bin pressure: with many open bins, favor filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_post);

    // New-bin candidate: penalize opening a new bin unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 14.0 + 20.0 * (1.0 - progress) - 6.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.06;
