pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10 assumed min item,
    // but sizes go down to 1, so weight gaps that are very small relative to capacity).
    if post_residual > 0 {
        let gap = post_residual as f64;
        let gap_ratio = gap / bin_capacity as f64;
        // Small gaps are the worst: quadratic penalty that spikes as gap -> 0
        let dead_penalty = (1.0 - gap_ratio) * (1.0 - gap_ratio) * 40.0;
        score += dead_penalty;
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Next-item lookahead: reward leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap cannot serve next item: extra penalty
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: prefer already-open bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (2.0 + 3.0 * progress);
    score -= pressure;

    // New-bin candidate (empty bin): add a fixed opening cost so it only wins
    // when all open bins score poorly (bad fits / dead space).
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.3;
    } else {
        // Mild preference for bins tighter than the average residual
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
        // Penalize leaving a residual just below the next item size (dead space trap).
        if post_residual > 0 && post_residual < next_item_size {
            score += 80.0;
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when good fitting bins exist, more so late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 200.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 300.0; // item can't fit anyway, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base; add smoothness.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: late in the stream, prefer consolidating into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Many open bins: encourage filling existing ones rather than opening new.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 3.0;

    // Deviation from mean residual: prefer bins whose residual is near/below mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate (empty bin): make it moderately attractive only when
    // item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 15.0 - 20.0 * large;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fits), with non-linear shaping.
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth quadratic coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize small residuals more),
    // later, reward tight packing.
    let phase = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 8.0 * phase * norm_post;
    score -= 6.0 * progress * progress * (cap - post) / cap;

    // Dead-space penalty: residuals too small to ever hold a typical item.
    let dead = (1.0 - norm_post).max(0.0);
    score += 4.0 * dead * dead * dead;

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 5.0 * (gap / cap);
        } else {
            score += 0.5 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 3.0 * open_norm * norm_post * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-capacity classes (0,25,50,75) are reusable.
    let q = post_residual / 25;
    let rem = post_residual % 25;
    // Reward post-residuals that fall on harmonic quarter classes (reusable by many sizes).
    if rem == 0 {
        score -= 12.0 + q as f64 * 4.0;
    } else if rem <= 5 {
        score -= 4.0;
    } else if rem >= 20 {
        score += 3.0;
    }

    // Penalize dead space: post_residual too small for the minimum item (1..100 range, min item 1).
    if post_residual < 10 {
        score += 15.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Coupling with next item: reward residuals that exactly fit next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 8.0;
        } else if post_residual < next_item_size {
            score += 6.0;
        }
        // Integer-division threshold: next item divides residual evenly.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets moderate score unless residuals are fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it must beat only bad fits.
        score = 55.0 + post_residual as f64 * 0.4;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 10.0; // existing bins are all too tight in aggregate
        }
    }

    // Tight fit reward: small post_residual relative to item size.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Stream progression: early on, prefer compacting; late, tolerate new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fills (waste <= 5) strongly.
    if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // if next item is large and would not fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            score += 8.0;
        }
    }

