    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score -= 10.0;
        // Prefer new bin if all existing fits leave tiny dead space.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
        // Discourage opening new bins early in the stream.
        score += progress * 15.0;
    }

    // Mild alignment with mean residual: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

