    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Aggressive 2-step lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain match
        } else if next_item_size <= post_residual {
            // partial match: closer to exact is better
            let gap = post - next;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            // next item cannot use this residual; penalize proportional to waste
            score += 8.0 * (next - post) / cap;
        }
    } else {
        // last item: just minimize post residual
        score -= 5.0;
    }

    // Compare against mean residual: bins with residual far from mean are either
    // outliers (good to close them out with tight fits) or already dead space.
    let dev = post - mean_residual;
    score += 0.3 * dev;

    // Penalize tiny unusable residuals (dead space) unless next item uses them.
    if post > 0.0 && (next_item_size == 0 || next > post) && post < 10.0 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish default; only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 5.0;
        // early in stream, allow opening bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Slight preference to fill fuller bins (lower residual before placement).
    score += 0.1 * (bin_residual as f64 - item_size as f64 - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item would fit in post_residual, reward; if it would
    // leave the bin useless, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual == next_item_size {
                score -= 10.0; // perfect pair packing
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // Compare against mean residual: bins with residual far from item fit quality.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // when consolidation matters less.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 18.0 - 6.0 * progress;
        // If the item leaves a big hole in an existing bin, opening a new bin
        // becomes relatively better.
        if post_residual > bin_capacity / 2 {
            new_bin_cost -= 4.0;
        }
        // If this is the only fitting bin, opening new is expensive.
        if fitting_bins_count == 1 {
            new_bin_cost += 30.0;
        }
        score += new_bin_cost;
    }

    // Mild time-horizon modulation: later in stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;

    // Base: penalize leftover space, but non-linearly (dead space hurts more)
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late in the stream, aggressively minimize post_residual.
    let progress_weight = 0.4 + 1.6 * progress * progress;
    score += progress_weight * norm_pr * norm_pr;

    // Smooth interaction: item size relative to residual (tight fit reward)
    let tightness = 1.0 - norm_pr; // fraction of bin filled by this item
    score -= 0.8 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: reward residual that can still fit the next item,
    // smoothly scaled by how much of the residual the next item would consume.
    if next_item_size > 0 {
        let ni = next_item_size as f64 / cap;
        let fits_next = if pr >= ni { 1.0 } else { 0.0 } * (1.0 - (pr - ni).abs() / cap).max(0.0);
        let smooth_fit = 1.0 / (1.0 + (-(pr - ni) * 4.0 / cap).exp());
        score -= 0.6 * smooth_fit * fits_next.max(smooth_fit);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this placement wastes space
    let open_norm = (open_bins_count as f64 / (1.0 + open_bins_count as f64)) - 0.5;
    score += 0.3 * open_norm * norm_pr;

    // Divergence from mean residual: prefer bins whose residual deviates smoothly
    let mean_norm = mean_residual / cap;
    let dev = norm_pr - mean_norm;
    score += 0.25 * dev * dev - 0.15 * dev;

    // New-bin candidate handling: neutral baseline so it only wins when open bins score poorly
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Harmonic class of the item: coarse capacity-fraction classes (1..=100 -> mod 10).
    let item_class = item_size % 10;
    let next_class = if next_item_size > 0 { next_item_size % 10 } else { 0 };

    // Reward when post_residual lies in the same harmonic class as the next item
    // (next item may exactly fill the gap).
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % 10 == next_item_size % 10 {
            score -= 8.0;
        }
        // Exact complement: next item fills bin perfectly.
        if next_item_size == post_residual {
            score -= 25.0;
        }
        // Integer-division threshold: post_residual / next_item_size >= 2 means
        // the gap could hold the next item twice -> still flexible.
        if post_residual >= 2 * next_item_size {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this gap: penalize dead space proportionally.
        score += 6.0 * fit_ratio;
    }

    // Penalize gaps in "awkward" classes: small odd post_residuals (1..9) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 - post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.1 * (bin_residual as f64 - post_residual as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well. Penalize fresh bins mildly when decent fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).min(4.0)
        } else {
            0.0
        };
        score += 20.0 + 8.0 * pressure;
        // Late in the stream, opening bins is fine for large items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 50 && progress > 0.5 {
            score -= 10.0 * progress;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, it's
    // a "leftover" bin; using it consolidates waste.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.05 * diff;
    } else {
        score += 0.05 * (-diff);
    }

    // Modulo coupling: item + post_residual class alignment (harmonic packing).
    if (item_size + post_residual) % 25 == 0 {
        score -= 5.0;
    }
    if (item_size + post_residual) % 50 == 0 {
        score -= 5.0;
    }

    // Slight preference to fill bins with more residual (keeps few open bins tight).
    score -= 0.02 * bin_residual as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (<= 1) are worthless; residuals that cannot
    // fit the lookahead item are partially wasted.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable micro-gap: penalize heavily.
        score += 200.0 + (10 - post_residual) as f64 * 20.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item.
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual can still host the next item: mild reward.
        score -= 15.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only allow opening a new bin when the item
    // is large relative to typical residuals or all fits are terrible.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 {
            (post_residual.saturating_sub(next_item_size)) as f64
        } else {
            post_residual as f64
        };
        // Base cost of a fresh bin, discounted when open bins are crowded.
        score += 150.0 - (open_bins_count as f64).min(50.0) * 2.0;
        // A fresh bin keeps large residual; acceptable if mean residual is low.
        score -= (mean_residual / bin_capacity as f64) * 50.0;
        let _ = desperation;
    }

    // Slight preference for bins whose residual is close to mean (balance).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize less when post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward when next item matches post_residual exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (1.0 - diff / (bin_capacity as f64)).max(0.0);
        score -= 18.0 * match_bonus * match_bonus;
        // Penalize post_residual that is unusably small relative to next item.
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    } else {
        // Last item: pure tight-fit behavior.
        score += 4.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    score += 0.35 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins offer terrible fits or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_penalty = if next_item_size > 0 {
            (post_residual as f64).abs() // = capacity residual
        } else { 0.0 };
        score += 20.0 + 15.0 * progress - 0.2 * item_size as f64 + 0.05 * poor_fit_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: quadratic penalty on wasted space
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Good: chain placement possible
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead space for the known next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += crowding * 4.0;

    // Mean residual coupling: if this bin is far below mean residual, it's a good filler
    let dev = mean_residual - post_residual as f64;
    score -= 0.10 * dev;

    // Time horizon: late in the stream, avoid opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 30.0 + 70.0 * progress;
        // Allow new bin early or when it enables near-perfect future packing
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) >= item_size as f64 && progress < 0.3 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item / (bin_residual as f64).max(1.0);
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize creating small, hard-to-use dead space (non-linear bump).
    let dead = post / cap;
    score += 30.0 * dead * (1.0 - dead) * (1.0 - dead) * 4.0;

    // Smooth interaction: as stream progresses, prefer minimizing post_residual more aggressively.
    score += progress * 0.35 * post;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate: make it attractive only when current bin residuals are large and item is small.
    if bin_residual == bin_capacity {
        let rel_mean = mean_residual / cap;
        score += 6.0 * rel_mean * rel_mean - 4.0 * (item / cap);
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 5.0; // fresh bin can also host the lookahead item
        }
    }

    // Lookahead synergy: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Mild pressure against bin proliferation early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let post = post_residual;
    let class3 = post % 3;
    let class5 = post % 5;
    let class10 = post % 10;

    // Reward residuals that form "harmonic" classes (divisible, friendly slots).
    if post == 0 {
        score -= 40.0; // perfect fit
    } else {
        if post % 10 == 0 { score -= 12.0; }
        if post % 5 == 0 && post % 10 != 0 { score -= 6.0; }
        if post % 25 == 0 { score -= 8.0; }
        if class3 == 0 { score -= 2.0; }
        // Penalize awkward dead space in low classes.
        if post < 10 { score += 25.0; }
        else if post < 20 { score += 8.0; }
        if class10 == 1 || class10 == 9 { score += 3.0; }
        if class5 == 1 || class5 == 4 { score += 2.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            let gap = post - next_item_size;
            score -= 10.0 - (gap as f64).min(10.0);
            if gap % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use leftover: mild penalty proportional to leftover waste
            score += (post as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 10.0;

    // Slight preference for existing bins vs opening new ones early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless remaining spread is large.
        score += 18.0 - 10.0 * progress;
        if post_residual as f64 > mean_residual { score -= 4.0; }
    } else {
        score -= 4.0;
        if (bin_residual as f64 - mean_residual).abs() < 5.0 { score -= 1.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that is too small to ever
    // hold a minimum item (size 1) is pure waste; gaps below a practical
    // threshold are heavily penalized since they become unusable dead space.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-zone penalty ramps up as the gap shrinks below the smallest
        // useful size, and is worst for tiny slivers (1..=5).
        if gap <= 5.0 {
            score += 40.0 + (5.0 - gap) * 8.0;
        } else if gap <= 12.0 {
            score += 20.0 + (12.0 - gap) * 2.0;
        }
        // Smooth dead-space curvature: quadratic waste term on small gaps.
        if gap < 25.0 {
            score += (25.0 - gap) * (25.0 - gap) / 25.0;
        }
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Prefer bins whose residual was tight before placement (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 10.0;

    // Open-bin pressure: discourage scattering across many bins; encourage
    // consolidating into existing bins when many are already open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, softened for large items and when
        // the mean residual across open bins is already high (fragmented).
        score += 30.0 - big_item * 20.0 + mean_residual * 0.15 - progress * 3.0;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Lookahead: if this placement leaves room exactly (or nearly) for the
    // next item, reward it.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        } else {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            if diff <= 5.0 {
                score -= (5.0 - diff) * 2.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
