    }

    // Reward bins tighter than the mean residual (good packing direction).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer using existing bins over opening new ones, more so as stream fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * progress;
    }

    // Slight preference for bins with larger residual among equals (first-fit-ish tie-break).
    score -= 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space, especially small unusable gaps (< next item size).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight * tight;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible;
    // later, prefer filling bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.10 * post_residual as f64;
    score -= progress * 0.15 * post_residual as f64;

    // Global state coupling: many open bins with high mean residual
    // suggests we should consolidate into existing bins.
    let spread = mean_residual - post_residual as f64;
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64).ln() * spread.max(-20.0);
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 4.0;
    }

    // Mild penalty for opening a new bin when other fitting bins exist.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 8.0 + 0.5 * item_size as f64 * (1.0 - progress);
    }

    // Reward using a nearly-full bin completely.
    if post_residual <= 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * x + 0.4 * x * x);

    // Penalize dead space that cannot fit the lookahead item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 + progress);
    }

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - x) * (1.0 + progress);
    }

    // Mild penalty for opening a new bin when many bins are open and fit exists
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 8.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Slight preference for bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: modulo-16 buckets penalize awkward leftovers.
    let cls = post_residual % 16;
    let cls_penalty = match cls {
        0 => -15.0,
        1..=5 => 18.0,
        6..=10 => 6.0,
        11..=15 => 12.0,
        _ => 0.0,
    };
    score += cls_penalty;

    // Dead-space threshold: leftovers too small for the smallest plausible item are waste.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual - next_item_size < 10 {
                score -= 8.0; // near-perfect two-item packing
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // pair next item with this one in a fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward post_residual that can still host a typical future item.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 25.0;
    }
    // Penalize if post_residual is just barely too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive for large items leaving usable residual.
        score += 20.0 + 3.0 * open_bins_count as f64;
        if item_size >= 50 && post_residual >= 20 {
            score -= 30.0;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Late-stream consolidation: prefer filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize dead space
            score += 15.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Reward tight fits
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize relative to mean residual (avoid wasting well-packed bins)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are large
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation: mild penalty proportional to leftover
            score += 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: slight bonus for conserving residual space elsewhere
            score -= 5.0;
        }
    }

    // Prefer filling bins that are already relatively empty when many bins are open.
    let residual_gap = (bin_residual as f64 - mean_residual).max(0.0);
    score += 0.2 * residual_gap * (open_bins_count as f64).sqrt();

    // Time horizon: early in the stream, be more conservative (penalize low post residual less),
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate handling: make opening a new bin unattractive unless current fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted when the stream is young or item is huge.
        let item_frac = item_size as f64 / cap;
        let mut new_bin_cost = 35.0 + 10.0 * (open_bins_count as f64).sqrt();
        new_bin_cost -= 30.0 * item_frac * item_frac; // huge items justify a new bin
        if progress > 0.8 {
            new_bin_cost += 15.0; // near the end, avoid spawning bins
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic) penalty on waste
    let mut score = pr * (1.0 + norm_post * norm_post);

    // Smooth polynomial coupling of waste with stream progress:
    // early on, waste matters more (bins stay open longer); relax slightly later
    let progress_coupling = 1.0 - 0.35 * progress * (2.0 - progress);
    score *= progress_coupling;

    // Dead-space penalty: residuals too small for typical items are quadratic losses
    let dead_threshold = 0.12 * cap;
    if pr < dead_threshold {
        let d = (dead_threshold - pr) / cap;
        score += 60.0 * d * d;
    }

    // Lookahead: reward residuals that can host the next item (smooth cubic-ish term)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 25.0 * (1.0 - slack * slack);
        } else {
            let miss = (ni - pr) / cap;
            score += 30.0 * miss * (1.0 + miss);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * (open_bins_count as f64).sqrt() * norm_post * 10.0;

    // Mean-residual deviation: prefer bins close to mean (balanced packing), smooth term
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: encourage opening a fresh bin only when waste is low or stream is early
    if bin_residual == bin_capacity {
        score = cap - 0.5 * (1.0 - progress) * cap + item_size as f64 * 0.3;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes
    // Perfect fill (0) is best; small residuals (1..10) are near-dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += (11 - post_residual) as f64 * 25.0; // penalize near-dead wedges
    } else if post_residual >= 30 {
        score -= (post_residual - 29) as f64 * 1.5; // reward large usable leftovers
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with
    // the integer item grid and are more likely to be filled later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= (post_residual as f64) * 0.3 - (slack as f64) * 0.4;
        } else {
            // next item cannot use this bin's leftover; leftover riskier
            score += (next_item_size as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.8;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // New-bin candidate: neutral-ish baseline; only open new bins when it
    // preserves large residual and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 60.0 + fragmentation * 40.0 - progress * 10.0;
        if next_item_size >= 40 && item_size >= 40 {
            score -= 20.0; // pairing large items in a fresh bin
        }
        if fitting_bins_count <= 1 {
            score += 200.0; // don't open new bin when a real option exists
        }
    }

    // Mild open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that is too small for the smallest possible item (1),
    // but especially gaps below the typical minimum item size.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 8.0;
    }

    // Lookahead: reward bins whose post residual can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
