        }
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer tighter packing (lower post residual).
    let ob = open_bins_count as f64;
    score += ob * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current residuals are mostly unusable.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If open bins have large residuals, discourage new bin.
        score += mean_residual * 0.2;
    }

    // Slight progression bias: late in stream, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
