pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: reward tight fits non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0; // dead space below minimum item size is unusable
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.15 * chain_fit.min(50.0);
        } else {
            // Penalize leaving a residual that wastes the next item's options.
            score += 8.0;
        }
        // If next item fits perfectly after this placement, big reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize unless
    // current bins are too full or too fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_bin_penalty = 45.0;
        // As stream progresses, opening new bins becomes more acceptable if
        // existing bins are heavily filled.
        new_bin_penalty -= 30.0 * avg_fill;
        new_bin_penalty += 10.0 * fragmentation / bin_capacity as f64;
        if open_bins_count == 0 {
            new_bin_penalty = -1000.0; // must open a bin
        }
        // Late in the stream, avoid hoarding empty capacity.
        new_bin_penalty -= 10.0 * progress;
        score += new_bin_penalty;
    }

    // Mild preference for filling bins with larger residual when many bins open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - post_residual as f64).signum();

    // Prefer bins whose residual deviates least from the mean (balance load).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
