    // Base: post residual (tighter fit -> lower score)
    let mut score = pr;

    // Normalized post-residual, polynomial coupling with stream progress
    let u = pr / cap; // 0..1
    let p1 = u * u;
    let p2 = p1 * u;
    // Early in stream: mild penalty for large residual; late: strong penalty (dead space matters more)
    score += (0.5 + 2.0 * progress) * (p1 + 0.8 * p2) * cap * 0.1;

    // Reward near-perfect fits quadratically
    let tightness = 1.0 - u;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize
    if next > 0.0 {
        if next <= pr {
            score -= 5.0 * (1.0 - (pr - next) / cap);
        } else {
            score += 3.0 * ((next - pr) / cap);
        }
    }

    // New-bin candidate: penalize slightly unless existing fit would leave bad residual
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        // If item is large relative to capacity, new bin is fine
        score -= 6.0 * (item / cap);
    }

    // Slight preference for bins with more residual used among many open bins
    score -= 0.5 * (mean_residual - pr) / cap;

    // Smooth open-bin pressure: many open bins -> prefer filling existing ones
    score += 0.3 * (open_bins_count as f64).ln() * u;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< next item size) are wasted.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0 + (next_item_size - post_residual) as f64;
    }

    // Reward very tight fits (low post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - tightness * tightness);

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidation).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Early in stream, be slightly more willing to open bins for future flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 40.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 15.0 * fit_ratio;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 30.0 - 2.0 * gap;
            } else {
                score += 0.3 * gap;
            }
        }
        // Penalize leaving a residual that is awkwardly larger than next item.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
            score += 10.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: default penalty, waived when current bin fit is bad
    // and next item can't chain here.
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.5 && post_residual < 20;
        let no_chain = next_item_size > 0 && next_item_size > post_residual && post_residual < 15;
        if bad_fit || no_chain {
            score -= 20.0;
        } else {
            score += 35.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Slight early-stream conservatism: keep bins flexible early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: less leftover relative to capacity.
    score -= (cap - post) / cap * 12.0;

    // Penalize dead space that is too small to be useful later (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly or well into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; slight penalty if we leave a large unusable gap for it.
            score += (next_item_size as f64 - post) * 0.05;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins whose residual is below average (pack fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: give it a moderate baseline so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity && item_size > 0 {
        score += cap * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Reward tight fits: non-linear coupling of fill ratio with progress
    let fill = 1.0 - post / cap;
    score -= fill * fill * (30.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the next item (smooth quadratic coupling)
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - post) / cap;
        score += 60.0 * gap * gap;
    } else if next_item_size > 0 {
        // mild reward when next item still fits this bin's residual
        let slack = (post - next_item_size as f64) / cap;
        score -= 8.0 * slack * (1.0 - slack);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize opening bins when open bins fit well
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { 1.0 / (1.0 + open_bins_count as f64) } else { 1.0 };
        score += 70.0 * pressure * (1.0 - progress) + 20.0;
        // allow opening a new bin late in stream when residuals are fragmented
        let frag = (mean_residual - post).abs() / cap;
        score -= 40.0 * frag * frag * progress;
    }

    // Penalize leaving residuals that match no typical item (mid-range dead zones)
    let zone = (post / cap - 0.5).abs();
    score += 10.0 * zone * zone * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 20.0;

    // Harmonic class of post_residual: dead space value depends on which
    // residue class it falls in relative to typical small item sizes.
    let pr = post_residual;
    if pr > 0 {
        // Residuals divisible by common small sizes are more reusable.
        let reusability = if pr % 10 == 0 { 1.0 }
            else if pr % 5 == 0 { 0.7 }
            else if pr % 3 == 0 { 0.5 }
            else { 0.0 };
        score -= reusability * 8.0;

        // Integer-division thresholds: classify dead space magnitude.
        let class = pr / 10; // 0..10 harmonic classes
        score += match class {
            0 => -6.0,  // pr < 10: nearly perfect fit, great
            1 => 0.0,   // pr 10-19: still usable by small items
            2 => 2.0,   // pr 20-29: moderate
            3 => 4.0,
            4 => 5.0,
            _ => 6.0,   // large leftover: wasteful
        };
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 15.0 - slack * 0.05;
    } else if next_item_size > pr && pr > 0 {
        // Next item won't fit here; penalize proportionally to how much
        // we'd strand if this bin is never revisited.
        score += (next_item_size as f64 - pr as f64) * 0.10;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current bin fits are all poor (high post_residual).
    if bin_residual == bin_capacity {
        // Neutral baseline: cost of a fresh bin ~ half capacity wasted on average.
        score = 55.0;
        // Early in stream, opening bins is cheap (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
        // If many open bins already, discourage proliferation.
        score += open_bins_count as f64 * 1.5;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 6.0;
        }
    }

    // Mean residual context: if this bin's residual is far below mean,
    // it's already well-packed; using it further is good.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - bin_res_f) * 0.05;
    }

    // Mild normalization of raw post_residual dominance.
    score -= (post_residual as f64).sqrt() * 1.5;

    // Modulo harmony bonus: item + post_residual forms a "clean" class.
    if (item_size + pr) % 100 == 0 {
        score -= 10.0;
    } else if (item_size + pr) % 50 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space avoidance: penalize small unusable gaps super-linearly.
    // A gap is "unusable" if it is smaller than the next item (or smaller than
    // the smallest plausible item when no lookahead exists).
    let min_item = if next_item_size > 0 { next_item_size } else { 10 };
    if (post_residual as f64) < min_item as f64 {
        // Wasted space: penalize proportionally to how much of the gap is dead.
        let deadness = 1.0 - (post_residual as f64 / min_item as f64);
        score += 40.0 + 120.0 * deadness * deadness;
    } else {
        // Usable gap: mild reward for keeping residual close to next item size
        // (tight but usable fit leaves room for the lookahead item).
        let tightness = 1.0 - ((post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64);
        score -= 10.0 * tightness;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 20.0 * progress;
    }

    // Open-bin pressure: mildly prefer consolidating into existing bins
    // when many bins are open.
    if !is_new_bin {
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // New-bin candidate handling: default penalty so a new bin is opened only
    // when every existing fit would create significant dead space.
    if is_new_bin {
        score += 60.0 - 30.0 * progress;
        // If lookahead item is large, a fresh bin is more valuable.
        score -= next_item_size as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            let mismatch = pr - next;
            // Reward proportional to how close post_residual is to next item.
            score -= (100.0 / (1.0 + mismatch)) * 0.6;
        } else {
            // Post-residual too small for next item: penalize dead space,
            // more strongly if it's small but unusable.
            score += (next - pr) * 0.4;
        }
    } else {
        // Last item: just minimize post residual strongly.
        score += post_residual as f64 * 0.2;
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving less than average residual is good (tight packing).
    let pr = post_residual as f64;
    score -= (mean_residual - pr) * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when no open
    // bin fits well. Penalize the fresh bin mildly so open bins win on
    // decent fits, but keep it competitive for bad fits.
    if bin_residual == bin_capacity {
        score += 5.0;
        // If nothing else fits (fitting_bins_count == 0 among open bins,
        // only this candidate), the lookahead bonus still applies.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 3.0;
        }
    }

    // Mild late-stream tightening: as stream progresses, prefer filling
    // existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.1 * progress;

    // Prefer bins with residual far below mean (already tight) when many
    // bins are open.
    if open_bins_count > 3 && pr < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins with small post residual.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - frac).powi(3);

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 6.0 * (waste / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // open-bin residuals are all poor fits (high mean residual mismatch).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0
            - 25.0 * fill_ratio
            - 20.0 * pressure
            - 5.0 * progress;
        // Too many open bins: discourage fragmentation.
        score += (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Slight preference for bins already below mean residual (balance).
        score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).clamp(-1.0, 1.0);
    }

    // Perfect fit gets a decisive discount.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic dead-space penalty, normalized by capacity, amplified late in stream
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth cubic term
    score -= 8.0 * (1.0 - norm_pr).powi(3);

    // Coupling with mean residual: prefer bins whose residual is below mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 3.0 * dev;

    // Lookahead: penalize leaving residual that neither fits next item nor is tiny
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = pr - ni;
        let awkward = if gap >= 0.0 { gap / cap } else { 0.0 };
        score += 5.0 * awkward * awkward;
        // reward if post residual exactly accommodates next item
        if gap.abs() < 0.5 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild competition pressure: prefer fuller bins among many candidates
        score += 3.0 * (1.0 - item_size as f64 / cap);
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let crowded = mean_residual / cap;
        score += 25.0 - 20.0 * crowded.min(1.0) - 2.0 * crowd.sqrt();
        // late in stream, new bins are cheaper than fragmentation
        score -= 8.0 * progress;
    }

    // Smooth progress-based exploration term
    score += 2.0 * (progress - 0.5).powi(2) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for small post_residual (tight fit), with harmonic class tiers.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Harmonic-class penalty: residual divisible into common small classes is reusable.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 25 == 0) {
        score -= 3.0;
    }
    if r > 0 && r < 10 {
        score += 6.0; // dead space below the minimum item size
    }

    // Lookahead: reward if the next item fits exactly or well in the post residual.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 20.0;
        } else if next_item_size < r {
            let slack = (r - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot fit here; mild penalty proportional to overflow
            score += ((next_item_size - r) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let poor_fit = post_residual < 10;
        let crowded = open_bins_count == 0 || (fitting_bins_count <= 1);
        let mean_tight = mean_residual < item_size as f64 * 1.2;
        if poor_fit || (crowded && mean_tight) {
            score -= 12.0;
        } else {
            score += 40.0; // keep filling existing bins when fits are reasonable
        }
    }

    // Slight bias toward balancing residuals late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - post_residual as f64).abs() * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 20.0;
    }

    // Non-linear dead-space penalty: gaps that nothing can fill well.
    // Items are 1..100, but small gaps (< ~25) rarely get filled; penalize superlinearly.
    if post_residual > 0 && post_residual <= 25 {
        score += (25.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits relative to residual before placement
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward proportional to how well it packs
        score -= 50.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this gap: penalize leaving a gap the lookahead can't fill
        score += 40.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize the new-bin candidate (bin_residual == bin_capacity).
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure; only attractive if no good fit exists.
        score += 120.0 + 200.0 * open_pressure;
        // If many fitting bins exist, make new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Mean residual coupling: if mean residual across open bins is high, prefer
    // filling bins with large residuals (spread usage), else prefer tight fits.
    if mean_residual > bin_capacity as f64 * 0.5 && bin_residual >= item_size {
        score -= 20.0;
    } else if mean_residual < bin_capacity as f64 * 0.3 {
        score += 10.0;
    }

    // Stream progression: early in the stream, be more willing to open bins
    // (flexibility); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 80.0 * (1.0 - progress);
    } else {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelmingly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small dead space strongly favored (quadratic penalty on waste).
    score += 0.01 * (post_residual as f64) * (post_residual as f64);

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        }
        // Reward if the next item can still fit after placement (chain packing).
        if post_residual >= next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual that is dangerously small: dead space that fits nothing typical.
        if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Prefer bins below mean residual (tighter bins get used first, keeping roomy bins flexible).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize opening a new bin,
    // unless the item is large and would leave a very fragmented existing bin.
    if bin_residual == bin_capacity {
        let fragmentation = if bin_residual > item_size {
            (bin_residual - item_size) as f64
        } else {
            0.0
        };
        // Opening a new bin is only attractive when it yields a near-perfect future chain.
        let mut new_bin_score = 200.0 - 0.5 * fragmentation;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 <= fragmentation * 0.5 {
            new_bin_score -= 120.0;
        }
        score += new_bin_score;
    }

    // Late in the stream, consolidate: favor closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * (post_residual as f64);

    // Many open bins: encourage tighter packing to reduce bin count.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward low post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // Next item won't fit here; leftover becomes dead space.
            score += 6.0 + 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless it's genuinely needed
    // (poor fit into existing bins, or many bins already open).
    if bin_residual == bin_capacity {
        let avg_fit_quality = (mean_residual - item_size as f64).max(0.0);
        let desperation = if fitting_bins_count == 0 { 1.0 } else { (avg_fit_quality / 40.0).min(1.0) };
        score += 30.0 - 25.0 * desperation + (open_bins_count as f64) * 0.5;
    } else {
        // Slight preference for fuller bins among open ones.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Late in the stream, consolidate harder (fewer new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is near the mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic dead-space penalty, sharpened as stream progresses
    let mut score = post * post / cap;

    // Smooth polynomial coupling of post_residual with progress:
    // late in the stream, tight fits matter more
    let tightness = 1.0 + 2.5 * progress * progress;
    score *= tightness;

    // Reward filling bins well (item large relative to residual)
    score -= norm_item * norm_item * cap * 0.5;

    // Penalize bins whose residual is much larger than the mean (hoarding space)
    score += ((post - mean_residual) / cap).max(-1.0).abs() * 8.0 * (post - mean_residual).signum().max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let new_bin_penalty = 25.0 + 40.0 * (1.0 - progress);
        // Worse if the next item could use this item's leftover space elsewhere
        let lookahead_waste = if next_item_size > post_residual { 1.0 } else { 0.0 };
        score = cap * 2.0 + new_bin_penalty * (0.5 + 0.5 * lookahead_waste) - norm_item * cap;
    } else {
        // If next item fits exactly in post_residual, reward this placement
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0 * (1.0 - (next_item_size as f64) / post.max(1.0));
        }
        // Mild penalty for leaving awkward small residuals (not zero, not large)
        if post > 0.0 && post < 10.0 {
            score += 10.0 * (10.0 - post);
        }
    }

    // Slight preference for fewer open bins early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: post_residual too small for any plausible item (assume min size 1,
    // but treat tiny residuals as near-perfect fills).
    if post_residual > 0 && post_residual < 4 {
        score -= 200.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 300.0; // chain fit: perfect two-item packing
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted capacity.
            score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Harmonic class logic: bucket post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    // Penalize residuals in awkward classes (just above common item sizes)
    // i.e. residuals in (0, 10], (10, 20] etc. get graded penalties.
    let class = (post_residual / 10).min(10);
    score += match class {
        0 => -50.0,
        1 => 10.0,
        2 => 5.0,
        3 => 15.0,
        4 => 8.0,
        5 => 20.0,
        6 => 12.0,
        7 => 25.0,
        8 => 18.0,
        9 => 30.0,
        _ => 5.0,
    } * (1.0 - frac.min(1.0));

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin if current bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: slightly worse than a good fit,
        // better than a bad fit.
        score = cap * 0.55 + open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 * progress;
    } else {
        // Prefer bins with lower residual relative to mean (tighter bins first).
        score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;
    }

    // Slight preference to fill older/more bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= ~15) are pure waste.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }
    // Medium dead space (15..=30) is risky: penalize proportionally.
    if post_residual >= 15 && post_residual <= 30 {
        score += 0.6 * (30 - post_residual) as f64;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    // (high open_bins_count, low mean residual) or item won't fit well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 + pressure + fragmentation * 0.5;
        if post_residual as f64 >= mean_residual {
            score += 10.0; // fresh bin worse than average residual -> avoid
        }
        if fitting_bins_count == 1 {
            score += 60.0; // never open a bin when only one bin fits
        }
        // If next item can use the fresh bin's residual well, slight relief.
        if next_item_size > 0 && (bin_capacity - next_item_size) <= post_residual {
            score -= 8.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0; // next item won't fit here anyway
    }

    // Mild open-bin pressure late in the stream.
    score += 0.15 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: item leaves exactly room for next item.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Penalize dead space that neither the next item nor small items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Reward tight fits overall: small post_residual is good (already base score).
    // But penalize wasting a large residual on a small item when mean residual is high.
    if (post_residual as f64) > mean_residual * 1.5 && item_size < 30 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive if no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they fit poorly.
        score += 45.0;
        // If the next item is large relative to post-fit space of typical bins,
        // a fresh bin preserves flexibility.
        if next_item_size >= 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference early in stream to keep bins open for future flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual), with superlinear decay.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize if the next item no longer fits this bin but would
    // fit if we had kept more residual; reward if next item still fits after.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if bin_residual >= next_item_size {
            score += 15.0;
        }
        // Chain fit bonus: both this and next item pack here.
        if item_size + next_item_size <= bin_residual {
            score -= 8.0;
        }
    }

    // Penalize opening a new bin when plenty of open bins have room.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (mean_residual + 1.0);
        score += 20.0 + 25.0 * (1.0 - pressure.min(1.0));
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Early in stream: be conservative, keep bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (consolidate emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Strong non-linear reward for tight fits (small post residual).
    let tightness = 1.0 - (pr / cap);
    score -= 28.0 * tightness.powi(3);

    // Quadratic penalty on dead space that can never fit a typical next item.
    score += 0.35 * (pr * pr) / cap;

    // Lookahead coupling: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 14.0 * fits_next * (1.0 - ((pr - nx) / cap).abs()).powi(2);
        score += 6.0 * (1.0 - fits_next) * (nx / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0 + 10.0 * progress;
    }

    // Progress-dependent pressure: late in the stream, prefer consolidating
    // into existing bins rather than opening new ones.
    score += (0.5 + 3.0 * progress) * (open_bins_count as f64).sqrt();

    // New-bin candidate: penalize opening a bin unless residual waste is large.
    if bin_residual == bin_capacity {
        score += 30.0 - 12.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: opening is correct
        }
    }

    // Mild attraction toward bins whose residual is near the mean (balance).
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // residue 0 (perfect fit into a future item) -> strong reward
        if class == 0 {
            score -= 25.0;
        } else if class <= 2 {
            score -= 8.0;
        } else if class >= 8 {
            score -= 3.0;
        } else {
            score += 6.0; // awkward middle residues are dead space
        }
        // harmonic depth: how many "harmonics" (divisors) the residual has
        let mut divisors = 0u32;
        let p = pr;
        let mut d = 2u32;
        while d * d <= p {
            if p % d == 0 { divisors += 2; }
            d += 1;
        }
        score -= divisors as f64 * 1.5;
    } else {
        score -= 40.0; // perfect closure
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize wasting this bin's future
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Tightness of current fit
    let fill = item_size as f64 / cap;
    score -= fill * 15.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral baseline with mild exploration bonus
    if bin_residual == bin_capacity {
        score = cap - 10.0 + (open_bins_count as f64).sqrt() * 3.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Prefer bins below mean residual (using up the emptier bins first keeps tight ones flexible)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host another item
    // (or only the tiniest ones) are pure waste; penalize them hard.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual < 25 {
        score += 25.0; // barely usable gap
    } else if post_residual >= next_item_size as f64 && next_item_size > 0 {
        score -= 15.0; // residual can host the lookahead item
    }

    // Reward tight fits (large fraction of bin consumed)
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Open-bin pressure: discourage spreading across many bins unless fit is great
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is costly when open bins exist,
    // but attractive if all open bins would leave terrible dead space.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // big item now, another big one coming: fresh bin ok
        }
    }

    // Prefer placing into bins with below-average residual (consolidate fullness)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, close out bins aggressively (perfect fits matter more)
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 20.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly or nearly matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post - nxt) as f64;
            // perfect chain match -> strong reward
            score -= 25.0 * (1.0 - gap / cap).max(0.0);
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // next item cannot chain here: mild penalty scaled by wasted space
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Relative to mean residual: bins tighter than average are precious;
    // dumping into them wastes scarce space.
    if post < mean_residual {
        score += 0.6 * (mean_residual - post);
    } else {
        score -= 0.3 * (post - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // late in the stream or when many bins are open and current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = fit_ratio < 0.5;
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        if bad_fit && (progress > 0.6 || open_bins_count > 8) && next_item_size > post_residual {
            score -= 10.0 + 5.0 * progress;
        } else {
            // discourage spreading items across fresh bins
            score += 15.0 + 0.1 * pressure;
        }
    }

    // Dead-space penalty: residual that is too small to hold the smallest
    // plausible future item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild noise-free tiebreak by bin index proxy (fewer open bins preferred).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a nonlinear term.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize dead space: residuals too small for any plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (post_residual as f64 / next_item_size as f64).min(4.0);
        } else {
            score += 2.0;
        }
    } else {
        // Last item: just minimize residual, prefer any bin.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Compare against mean residual: bins already tighter than average are better targets.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when all open bins would leave large waste.
    if bin_residual == bin_capacity {
        let min_waste_elsewhere = if fitting_bins_count > 0 {
            (bin_capacity as f64 - item_size as f64) * 0.5
        } else {
            0.0
        };
        // Base penalty for opening a new bin, discounted late in the stream.
        score += 25.0 - 10.0 * progress - min_waste_elsewhere * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
        if post_residual as f64 >= next_item_size as f64 && next_item_size > 0 {
            score -= 4.0; // fresh bin can host the next item too
        }
    }

    // Mild noise-free deterministic tie-break on residual evenness.
    score += 0.01 * ((bin_residual as f64).powf(1.1) - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Normalized post-residual (dead space fraction)
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: dead space penalty grows super-linearly
    // with stream progress (late dead space is more costly since fewer items remain
    // to fill it). Use smooth cubic/quartic terms.
    let dead_penalty = pr_norm * pr_norm * (1.0 + 3.0 * progress) + pr_norm * pr_norm * pr_norm * 4.0 * progress;
    score += 10.0 * dead_penalty;

    // Reward tight fits: item filling most of the residual is desirable
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Smooth interaction between mean residual and post residual: prefer bins
    // whose post-residual stays near the mean (keeps residuals usable later).
    let mean_diff = post_residual as f64 - mean_residual;
    let mean_diff_norm = mean_diff / bin_capacity as f64;
    score += 4.0 * mean_diff_norm * mean_diff_norm;

    // Lookahead coupling: if next item fits exactly in post-residual, reward strongly
    if next_item_size > 0 {
        let next_fit = next_item_size as f64 / bin_capacity as f64;
        let gap = (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
        // smooth reward decaying with gap
        score -= 12.0 * next_fit * (-gap * 6.0).exp();
        // penalize wasting residual slightly larger than next item (near-miss dead space)
        score += 3.0 * gap * gap * progress;
    } else {
        // Last item: any residual is fine, mild reward for tightness
        score -= 5.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Scarcity pressure: with many open bins, prefer consolidating into existing ones
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 5.0 * open_norm * pr_norm;

    // New-bin candidate handling: empty bin has zero fill ratio (fill_ratio ~ 0),
    // gets no tight-fit reward; add a mild exploration bonus early, penalty late.
    if bin_residual == bin_capacity {
        score += 2.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "usable" residue class (multiples of small common sizes) are preferred.
    let cap = bin_capacity as f64;
    let fill = (bin_residual as f64) / cap; // fill fraction before placement
    let post_frac = (post_residual as f64) / cap;

    // Class A: post_residual is a multiple of 10 -> clean slot for future items.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Integer-division thresholds on post_residual: dead-space bands.
    let band = post_residual / 20; // 0..=5 bands
    match band {
        0 => score -= 8.0,            // near-perfect fit
        1 => score -= 3.0,            // small leftover, still usable
        2 => score += 0.0,            // neutral
        3 => score += 2.0,            // awkward gap (40-59)
        4 => score += 1.0,            // half-bin-ish, recoverable
        _ => score -= 1.5,            // mostly empty, fine to keep building
    }

    // Coupling with lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item leaves another classifiable remainder.
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 {
                score -= 5.0;
            } else if rem <= 10 {
                score -= 3.0;
            } else {
                score -= 1.0;
            }
        } else {
            // Next item won't fit here; penalize more if this was the only fit.
            score += 2.0 + 0.02 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are badly fragmented (mean residual high but unusable).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; escalate late in the stream.
        score += 10.0 + 15.0 * progress;
        // But if no existing bin can fit at all, new bin must win.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If mean residual across open bins is tiny, opening fresh is fine.
        if mean_residual < 5.0 {
            score -= 8.0;
        }
    }

    // Fragmentation pressure: when many bins are open, prefer tightening fills.
    score += 0.15 * open_bins_count as f64 * (1.0 - fill);

    // Slight preference for balancing residuals toward the mean.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Capacity-fraction bonus for filling past half the bin.
    if fill >= 0.5 && post_frac < 0.5 {
        score -= 4.0;
    }
    if fill >= 0.75 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small, hard-to-fill gap)
    // is penalized super-linearly. Dead zone: gaps of 1..=20 that can't hold typical items.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= tightness * -10.0; // effectively subtracts when tightness small
        score += tightness * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin is costly; penalize it unless the current
    // placement would create severe dead space or the bin is nearly full anyway.
    if bin_residual == bin_capacity {
        score = 100.0 + open_bins_count as f64;
        // Allow opening a new bin when current best fit would waste a lot.
        if post_residual < 20 && item_size >= bin_capacity {
            score -= 150.0;
        }
        // Late in the stream, prefer closing out bins tightly rather than spreading.
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 + 20.0 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Favor bins below mean residual (fill the emptier ones first keeps balance).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead coupling: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves further waste; penalize leftover proportionally
            let next_left = post_residual - next_item_size;
            score += next_left as f64 * 0.5;
            // small bonus that next item fits at all
            score -= 20.0;
        } else {
            // next item won't fit here; penalize small dead space more
            score += 30.0;
        }
    }

    // Penalize creating dead space below the minimum item size (assume >=1, use 10 as conservative)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin when it wastes residual elsewhere
    if bin_residual == bin_capacity {
        // base cost of new bin; lower if few bins open or stream near end
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 - 50.0 * (1.0 - progress) - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can host next item too, mild bonus
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space: residuals too small to fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= item_size + next_item_size {
            // item + next both fit now: slight penalty to prefer bins where chaining works
            score += 4.0;
        }
        // Penalize leaving a residual that just barely misses the next item
        if post_residual < next_item_size && post_residual >= next_item_size.saturating_sub(5) && post_residual > 0 {
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with lower residuals when many bins are open (consolidation)
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, favor closing out bins (use bins with small residuals)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= fit_ratio * progress * 10.0;

    // Mild preference for filling existing bins when many are open
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling: opening a new bin should only win when
    // the item fits poorly everywhere; make empty bin moderately expensive
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if next item is large and nothing else helps, new bin is okay
        if next_item_size >= 60 && item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap; // normalized fill fraction of bin after placement

    // Base: prefer small post_residual (tight fit), with non-linear sharpening.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth non-linear coupling: as the stream progresses, reward high fill more strongly.
    let fill_reward = fill * fill * (1.0 + 2.0 * progress * fill);
    score -= 25.0 * fill_reward;

    // Penalize dead space that is too small to be useful later, smoothly via cubic term.
    let useless = (cap - pr) / cap; // 1 when pr==0
    let dead = (pr / cap).powi(3) * (1.0 - useless);
    score += 15.0 * dead * (0.5 + progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            let smooth = 1.0 - (diff / cap).min(1.0);
            score -= 18.0 * smooth * smooth;
        } else {
            // post_residual can't hold next item: mild penalty scaled by wasted potential
            score += 4.0 * (pr / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: score it relative to average residual; open new bins when
    // existing residuals are fragmented (high mean residual spread vs this bin).
    if bin_residual == bin_capacity {
        score = cap * 0.9 - 10.0 * (mean_residual / cap) * (1.0 - progress);
        // early in stream, opening bins is cheap; later, prefer consolidation
        score += 12.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty grows superlinearly for tiny unusable residuals
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward exact-fill / near-fill classes (residuals divisible by common item sizes)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Harmonic pairing: if the next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.2;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; penalize proportionally to wasted fraction
        score += frac * 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tiny
    if bin_residual == bin_capacity {
        let tight = mean_residual < 15.0 && open_bins_count > 0;
        if !tight {
            score += 25.0 + mean_residual * 0.3;
        } else {
            score += 5.0;
        }
    }

    // Prefer filling bins with larger residual when many bins open (consolidation)
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 0.05;
        score += (mean_residual - bin_residual as f64).abs() * 0.05;
    }

    // Progress scaling: early stream, be more conservative with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item
    // (items >= 1, but practically small gaps are wasted) are heavily penalized.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.2);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Zero residual is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Open bins pressure: discourage spreading when many bins are open,
    // but encourage using nearly-full bins.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or item would leave a big gap in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0 + open_bins_count as f64 * 0.5;
        // But if current placement would waste most of an existing bin's
        // residual (item much smaller than residual), new bin becomes viable.
        let waste = bin_residual.saturating_sub(item_size) as f64;
        if waste > bin_capacity as f64 * 0.6 {
            score -= waste * 0.25;
        }
        // Lookahead: if next item is large, a fresh bin is useful.
        if next_item_size > bin_capacity / 2 {
            score -= next_item_size as f64 * 0.1;
        }
    }

    // Lookahead coupling: prefer leaving room for the next item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Mean residual context: bins far below mean residual are less urgent.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Slight late-stream tightening: consolidate toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 35.0;
        } else {
            score += diff as f64 * 0.6;
        }
        // Penalize leftovers that are too small to ever hold typical items (dead space).
        if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 20.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins),
    // but avoid creating extreme fragmentation relative to the fleet.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 8.0;
        } else if rel > 1.5 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current
    // leftovers are fragmented or there are no other fitting bins.
    if bin_residual == bin_capacity {
        score += 45.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0; // fresh bin perfectly accommodates the next item
        }
    }

    // Late in the stream, prefer closing out bins tightly (less room for regret).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that can only hold tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted space
            score += 0.15 * (next_item_size as f64).min(post_residual as f64 + 1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid pushing us to open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when this item would leave a lot of waste
    // in every open bin, or late in the stream with few bins open.
    if bin_residual == bin_capacity {
        let waste_elsewhere = (bin_residual - item_size) as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Prefer new bin when item is large relative to mean residual (poor fits everywhere)
        let poor_fit_pressure = (item_size as f64 - mean_residual).max(0.0);
        score = 45.0 + waste_elsewhere - 1.5 * poor_fit_pressure - 10.0 * progress
                + 0.5 * open_bins_count as f64;
    }

    // Mild global pressure: many open bins with high mean residual -> consolidate.
    score -= 0.05 * mean_residual / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: post residual (larger residual = better fit, lower score)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (quadratic penalty on large residuals),
    // later, prefer flexibility (quadratic bonus on large residuals).
    let early = (1.0 - progress).powi(2);
    let late = progress.powi(2);
    score += 60.0 * early * norm_pr * norm_pr;
    score -= 40.0 * late * norm_pr * (1.0 - norm_pr);

    // Cubic coupling: penalize medium dead-space zones non-linearly
    score += 25.0 * norm_pr * (1.0 - norm_pr) * (norm_pr - 0.5).abs();

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Next item lookahead: if post_residual fits next item, reward; else mild penalty
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - pr / (pr + nx));
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Crowding: many open bins with low mean residual -> favor filling existing bins
    let crowd = (open_bins_count as f64).ln() / (1.0 + (mean_residual / cap).max(0.0));
    score += 8.0 * crowd * norm_pr;

    // New-bin candidate: empty bin should only win when it's genuinely better
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 4 equal classes
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4
    // Reward tight fits: class 0 (near-full) heavily rewarded
    score -= (4 - class.min(4)) as f64 * 6.0;

    // Perfect-fill harmonic: post_residual is exact divisor-friendly residue
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Dead-space penalty: small unusable residue (1..10) is wasted
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; slight penalty if we leave a large gap anyway
        score += (post_residual as f64) * 0.05;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets neutral base, penalize mildly
    // so we only open new bins when open bins score very poorly
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        // many open bins: discourage another new bin
        score += open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: placing into a bin far below mean residual is good
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // Integer division threshold: post_residual in (10, 25] is awkward — mild penalty
    if post_residual > 10 && post_residual <= 25 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are wasted forever.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score += 60.0; // tiny unusable gap -> strong penalty
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (post residual close to 0 relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates a gap blocking the known next item
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * 0.8 * (1.0 - progress);

    // Prefer bins whose residual is already below average (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Opening fresh is penalized mildly, but beats bins leaving tiny dead gaps.
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term.

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chaining), penalize near-misses
    // that strand dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // Next item can chain into this bin: reward exact match strongly,
            // reward "fits but loose" mildly.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            score -= 10.0; // chainability bonus
        } else {
            // Next item cannot fit here: penalize stranded residual,
            // worse when post_residual is small (dead space).
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Mild penalty if lookahead item is large and this bin would be the
        // only fitting bin for the current item (last-chance pressure).
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer bins below mean residual (filling emptier bins keeps tight bins
    // available for future tight fits), but only when there are alternatives.
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins attractive only when the item is
    // large relative to capacity or the fit elsewhere would be very loose.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Opening fresh is good for big items (they'd wreck any bin anyway),
        // bad for small items (waste of a fresh bin).
        score -= 20.0 * tightness - 10.0;
        // If next item is also large, a fresh bin pairs well with it.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Slight early-stream preference to open bins (build a portfolio),
    // slight late-stream preference to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 4.0 * (1.0 - progress);
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: squash small residuals aggressively.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        score -= 40.0 * (-pr / 12.0).exp();
    }

    // Penalize dead space proportional to how unusable it is relative to
    // the smallest conceivable future item (min size ~1, but typical chunk).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead) / 10.0; // tiny slivers are pure waste
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this bin; if it fits at all, mild reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = (post_residual as f64 - nxt).abs();
            score -= 18.0 * (-gap / 10.0).exp();
        } else {
            // Next item won't fit here: leftover space likely wasted.
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0 + 0.15 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: an empty bin has huge residual, so add a
    // moderate opening penalty; waive it late in the stream or when open
    // bins are nearly saturated (mean residual low => few good fits).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 30.0 + 3.0 * open_bins_count as f64;
        // If mean residual across open bins is small, new bin is attractive.
        open_penalty -= (mean_residual - 20.0).clamp(-40.0, 40.0) * 0.5;
        // Early stream: slightly prefer consolidating into open bins.
        open_penalty += 10.0 * (1.0 - progress);
        score += open_penalty.max(0.0);
    } else {
        // Existing-bin bonus scaled by waste-avoidance vs mean residual.
        score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Global packing pressure: many open bins with fat residuals -> prefer
    // filling those bins rather than spreading.
    score += 0.05 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual

    // Smooth non-linear polynomial coupling: dead-space penalty grows quadratically
    // with residual size and with stream progress (late waste matters more).
    let dead = x * x * (1.0 + 1.5 * progress);
    score += 60.0 * dead;

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_next = 1.0 - diff / cap;
        score -= 30.0 * fit_next * fit_next * fit_next;
    } else {
        // Last item: penalize any leftover residual strongly
        score += 40.0 * x;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: keep it neutral-ish, mildly penalized early, penalized
    // less late when open bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 15.0 - 30.0 * progress * fragmentation;
    } else {
        // Slight preference for bins with residual close to mean (balanced use)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev * dev;
    }

    // Mild penalty for proliferating open bins early in the stream
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: quantize post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let q = post / cap; // fraction of capacity left after placement

    // Class index by eighths of capacity: 0 = full, 7 = near empty.
    let class = (q * 8.0).floor().min(7.0) as u32;
    let class_bonus: [f64; 8] = [6.0, 4.5, 3.5, 2.5, 1.5, 0.5, -1.0, -3.0];
    score -= class_bonus[class as usize];

    // Modulo arithmetic on post_residual: residues that pair well with
    // common item sizes (multiples of 10..20) are favored.
    let pr = post_residual;
    let m10 = (pr % 10) as f64;
    let m20 = (pr % 20) as f64;
    score -= 0.8 * (1.0 - m10 / 5.0).abs();   // reward near-multiples of 10
    score -= 0.5 * (1.0 - m20 / 10.0).abs();  // reward near-multiples of 20

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
        // Extra reward if next item's size class complements the residue.
        let nm = (post_residual % next_item_size.max(1)) as f64;
        score -= 0.4 * (1.0 - nm / (next_item_size as f64 / 2.0)).abs();
    } else if next_item_size > post_residual {
        // Dead space risk: leftover can't host the next item.
        score += 2.0 * q;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score = 12.0 + 10.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 15.0; // no alternative
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 2.0; // fresh bin helps the big next item
        }
    }

    // Tight-fit reward: near-exact fills are excellent.
    if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Mild stream-progression damping: early on, keep bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Fragmentation penalty relative to mean residual of open bins.
    score += 0.3 * (post - mean_residual).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fill is heavily rewarded.
        score -= 40.0;
    }

    // Reward tight fits (item consuming most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; allow opening when few bins exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    score += if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, but cheaper when no good fit exists.
        15.0 + open_pressure * 0.5
    } else {
        -open_pressure * 0.3
    };

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward this placement (creates a perfect slot for the next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 15.0; // would create dead space for the next item
        }
        // Prefer bins whose post-residual stays large enough to be reusable.
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: only exact fills matter.
        score = if post_residual == 0 { -100.0 } else { post_residual as f64 };
    }

    // Slight preference for bins with below-mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where item leaves minimal waste.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // 2-step lookahead: reward when post_residual exactly matches next item size,
    // penalize when next item would leave a large unusable gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // chain: next item fills this bin perfectly
        } else if post_residual > next_item_size {
            let next_post = post_residual - next_item_size;
            // penalize leftover after hypothetical next placement
            score += (next_post as f64) * 0.6;
        } else {
            // next item cannot fit here; post_residual is dead space
            score += (post_residual as f64) * 0.9;
        }
    } else {
        // last item: minimize final residual
        score += (post_residual as f64) * 0.5;
    }

    // Reward tight fit relative to current residual (avoid fragmenting large residuals badly)
    let fill_fraction = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_fraction * 20.0;

    // Mean residual coupling: prefer bins whose residual deviates usefully from mean.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong penalty for skipping it when it's the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize moderately so we only open when
    // existing bins fit poorly; allow it when residual waste would be high.
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if lookahead suggests a fresh bin chains well, ease the penalty
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0;
        }
    }

    // Early stream: be slightly more willing to open bins (keeps residuals diverse)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small unusable dead space (post_residual too small for any future item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins early; relax later in the stream.
        score += 30.0 * (1.0 - progress);
        // Penalize more when many bins are already open and have room.
        score += 0.05 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // If no open bin fits well (large post_residual elsewhere), new bin is fine.
        if post_residual == bin_capacity && item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Slight preference for fuller bins to consolidate space.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 6.0 * fill;
        // Prefer bins below mean residual (less crowded bins keep flexibility).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr;

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (superlinear)
    let dead_penalty = norm_pr * norm_pr * (1.0 + 3.0 * progress) * cap * 0.5;
    score += dead_penalty;

    // Reward near-perfect fills (post_residual small) more strongly as stream progresses
    let tight_bonus = (1.0 - norm_pr).powi(3) * cap * (0.3 + 0.5 * progress);
    score -= tight_bonus;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // smooth reward proportional to how well next item fills the remainder
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 25.0 * fill * (1.0 - norm_pr);
        } else {
            // post_residual too small for next item: penalize proportionally to wasted potential
            let waste = (next_item_size as f64 - pr) / cap;
            score += 20.0 * waste * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    let spread = (open_bins_count as f64).ln() * (mean_residual / cap).max(0.0);
    score += 5.0 * spread * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): penalize opening new bins unless residual would be very poor
    if bin_residual == bin_capacity {
        let threshold = 0.25 + 0.35 * progress;
        score += 30.0 - 40.0 * threshold;
        // If the current item leaves a big hole anyway, opening a new bin is attractive
        if norm_pr > threshold {
            score -= 45.0 * (norm_pr - threshold) / threshold.max(0.01);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are "harmonic" and reusable; odd fragments are dead space.
    let class: f64 = if post_residual == 0 {
        -60.0 // perfect fit: strongest reward
    } else if post_residual % 50 == 0 {
        -12.0
    } else if post_residual % 25 == 0 {
        -8.0
    } else if post_residual % 20 == 0 {
        -7.0
    } else if post_residual % 10 == 0 {
        -5.0
    } else if post_residual % 5 == 0 {
        -2.0
    } else {
        4.0 // non-harmonic fragment: penalize
    };
    score += class;

    // Lookahead: reward if the next item fits exactly or harmonically into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if post_residual % next_item_size == 0 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here: leftover becomes dead space until later.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current
    // bins are nearly full / fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 25.0 + 10.0 * (1.0 - progress) - fragmentation.min(20.0);
    }

    // Prefer tighter bins: relative fill tightness.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Small penalty scaling with number of open bins to discourage bin sprawl.
    score += (open_bins_count as f64).ln().max(0.0);

    // Dead-space quadratic term for tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harshly (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: penalize leaving a gap that barely misses the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins tighter than average (good fits).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.3;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.5;
        }
    }

    // Compare post_residual against mean residual: avoid creating bins that are
    // far emptier than average (wasteful) unless it's a tight fit.
    let pr = post_residual as f64;
    if pr > mean_residual + 20.0 {
        score += (pr - mean_residual - 20.0) * 0.6;
    } else if pr < mean_residual - 20.0 {
        score -= (mean_residual - 20.0 - pr).min(15.0) * 0.4;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize the brand-new empty bin candidate, unless current bins fit poorly
    // (item much larger than smallest fitting residual) or few bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 55.0 - poor_fit * 70.0 - (open_bins_count as f64).min(3.0) * 5.0;
        // If lookahead suggests the item pairs poorly with existing residuals, new bin is fine.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 15.0;
        }
    }

    // Late in the stream, consolidate harder: discourage opening new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (wasted-space penalty is super-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Penalize residual that the next item cannot use but is close to it.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(30.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (a fresh bin preserves space for the bulk) or open bins are very full on average.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let crowded = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin, discounted for large items, crowding, and late stream.
        let new_bin_cost = 55.0 - 25.0 * large_item - 20.0 * crowded - 10.0 * progress;
        score += new_bin_cost.max(-5.0) / pressure.sqrt();
    } else {
        // Mild preference for fuller bins among open candidates (best-fit consolidation).
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 6.0 * fullness;
        // Slight penalty for spreading across many bins.
        score += 0.3 * (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate large residual waste; late, penalize it quadratically.
    let progress_waste = norm_post * (1.0 + 2.5 * progress + 4.0 * progress * progress) * cap * 0.25;
    score += progress_waste;

    // Smooth reward for tight fits (post residual small relative to item), cubic coupling.
    let tightness = 1.0 - norm_post;
    score -= 30.0 * tightness * tightness * tightness * norm_item;

    // Penalize residual that cannot hold the lookahead item (smooth sigmoid-like coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - post) / cap;
        let unusable = gap.max(0.0);
        score += 20.0 * unusable * unusable;
        // Reward residuals that can fit the next item, smoothly weighted by fit quality.
        let fit_quality = (1.0 - ((post - nxt) / cap).abs()).max(0.0);
        score -= 10.0 * fit_quality * fit_quality;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post * 0.5);
    }

    // Mild penalty for spreading across too many open bins, coupled with mean residual.
    let open_norm = open_bins_count as f64;
    score += 0.4 * open_norm * (1.0 - (mean_residual / cap).abs().min(1.0));

    // New-bin candidate: neutral-ish score so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) - 5.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
