pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize unusable dead space: gaps too small for the smallest plausible item.
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 200.0;
        }
        // Dead space in the classic "small gap" band (1..=10) is nearly unusable.
        if post_residual <= 10 {
            score += 120.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual <= 20 {
            score += 30.0;
        }
