        } else if next_item_size < post_residual && (post_residual - next_item_size) <= 10 {
            score += 40.0; // leaves another dead gap -> penalize
        } else if next_item_size <= post_residual {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 180.0;
    }

    // Pressure from number of open bins: discourage proliferation of bins.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: an empty bin has high raw residual; make it
    // attractive only when no open bin offers a good fit (high mean residual
    // fragmentation or many open bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = bin_capacity as f64 * 0.6 + open_bins_count as f64 * 8.0;
        // If existing bins are fragmented (mean residual small relative to item),
        // opening a new bin becomes more attractive.
        if mean_residual < item_size as f64 * 1.5 {
            new_bin_score -= 120.0;
        }
        // If this is the only fitting bin besides the new bin, prefer the open bin.
        if fitting_bins_count >= 1 {
            new_bin_score += 150.0;
        }
        score = score.min(new_bin_score) * 0.0 + if new_bin_score < score { new_bin_score } else { score };
    }

    // Mild progression term: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
