    // Penalize dead space: post_residual too small to ever be useful (below min item size 1 is
    // impossible, but small leftovers relative to typical items waste capacity).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving a large unusable gap.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 70.0;
        // Cheaper to open a new bin late in the stream or when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If open bins are fragmented (high mean residual but poor fit), new bin less costly.
        score -= 0.15 * mean_residual;
        // If many bins already fit the item, opening a new bin is unattractive.
        score += 12.0 * fitting_bins_count as f64;
    } else {
        // Existing-bin preference grows with stream progress (consolidation late).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
    }

    // Mild penalty when many bins are open: encourage closing them out by filling.
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Reward using bins whose residual is close to capacity-relative mean (balance avoidance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
