    let next = next_item_size as f64;

    // Base: strong preference for small post_residual, non-linearly amplified.
    let mut score = post * (1.0 + 2.0 * post / cap) + 0.35 * (post / cap).powi(2) * cap;

    // Tightness reward: near-exact fits get a large bonus (subtracted).
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness.powi(3) * (1.0 + progress);

    // Penalize wasting large residuals on small items: coupling of item_size with bin_residual.
    let fill_ratio = size / residual.max(1.0);
    score += 10.0 * (1.0 - fill_ratio).powi(2);

    // Lookahead coupling: bonus if next item fits the post_residual exactly-ish.
    if next > 0.0 && next <= post {
        let gap = (post - next).abs();
        score -= 12.0 * (1.0 - gap / cap).powi(2);
    } else if next > post {
        // If next item cannot fit here, mild penalty for leaving awkward residue.
        score += 4.0 * (next - post) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: empty bin should generally score high (bad),
    // unless open bins' residuals are large and fragmentation is high.
    if residual >= cap - 0.5 {
        score = cap - 8.0 * (mean_residual / cap) - 6.0 * progress - 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Fragmentation pressure: many open bins with high mean residual -> prefer filling existing bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Mean-residual coupling: when mean residual is small, waste matters more.
    score += post * (mean_residual / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead space in "awkward" classes is worse.
    let pr = post_residual as i64;
    if pr > 0 {
        let class = pr % 10;
        let awkward = match class {
            1 | 2 | 3 | 7 | 8 | 9 => 1.0,
            4 | 6 => 0.5,
            _ => 0.0,
        };
        score += 6.0 * awkward * (1.0 - pr as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large residuals a bit
            score += 3.0 * post_residual as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: any bin works, prefer tightest.
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // fit here is poor. Penalize the fresh empty bin by default.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let stream_pos = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * pressure
            - 10.0 * (1.0 - stream_pos)
            + 0.5 * open_bins_count as f64;
        // If the item is huge relative to mean residual, new bin is less bad.
        score -= 8.0 * (item_size as f64 / bin_capacity as f64).powf(2.0);
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Modulo threshold on item size: very small items pack anywhere; prefer
    // dumping them into already-cluttered bins.
    if item_size % 10 == 0 && item_size <= 20 {
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are tiny but nonzero are the worst
    // (they can only absorb very small future items). Reward exact fits hard.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill: always prefer
    } else {
        let pr = post_residual as f64;
        // Non-linear penalty peaking for small unusable-feeling gaps.
        let dead_zone = (30.0 - pr).max(0.0) / 30.0; // 1.0 when gap <= ~0, fades by 30
        score += 60.0 * dead_zone * dead_zone;
        // Mild general reward for tighter fits beyond the dead zone
        score -= (bin_capacity as f64 - pr) * 0.05;
    }

    // Lookahead coupling: if the next item fits exactly into the post gap,
    // strongly favor this bin; if post gap is too small for the next item,
    // penalize slightly (dead space from the stream's perspective).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size > post_residual {
            score += 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits but leaves another gap: mild chain bonus
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; when few bins, spreading is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.05 * pressure;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when this item would create
    // a large dead gap in every existing bin. Baseline new-bin score is its
    // residual (capacity - item), which is naturally high; add a fixed
    // opening cost so we only open when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
    } else {
        // Compare against mean residual: bins far below mean residual are
        // already fragmented; prefer filling the fullest bins.
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // 2-step lookahead: strongly reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect 2-step match: post_residual == next_item_size
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 25.0; // exact two-item closure
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot,
            // but less if post_residual is small (dead space is tiny).
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.3;
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 30.0;
    }

    // Relative to mean residual: bins with residual near/below mean are "normal" fills.
    let resid_f = bin_residual as f64;
    let rel = resid_f - mean_residual;
    score += rel * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many fitting bins means we should reuse one, so penalize new bin).
    if bin_residual == bin_capacity {
        let base = 95.0;
        // Penalize more when many alternatives exist or stream is early.
        let alt_penalty = (fitting_bins_count as f64).min(6.0) * 8.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base + alt_penalty - progress * 10.0
            - if next_item_size > 0 && next_item_size <= bin_capacity {
                12.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64))
            } else { 0.0 };
    }

    // Mild penalty for opening bins when many are already open (fragmentation).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.35 * (dead / 100.0).powf(1.5);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it, else the item opens a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.5 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if the next item would fit better elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size > bin_residual && bin_residual >= item_size {
            // next item cannot fit here anyway; neutral.
        }
    }

    // Time horizon: early in stream, be conservative (prefer new bins for large items);
    // late in stream, consolidate aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins with high mean residual: prefer filling existing bins.
    score += 0.02 * open_bins_count as f64;
    score -= 0.05 * mean_residual;

    // New-bin candidate: make it attractive only when this item leaves a large
    // awkward residual in existing bins and the next item is small.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if awkward && next_item_size <= post_residual {
            score -= 3.0;
        } else {
            score += 8.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= poly * (60.0 + 80.0 * progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let waste = (nxt - pr) / bin_capacity as f64;
            score += waste * waste * (200.0 + 300.0 * progress);
        } else {
            // Reward residual that still accommodates the next item.
            score -= (pr - nxt).min(bin_capacity as f64) / bin_capacity as f64 * 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 60.0 * progress;
    }

    // Penalize opening a new bin when open bins exist, more so late in the stream.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 70.0 + 50.0 * (1.0 - progress) + 5.0 * open_f.sqrt();
        // Discourage new bin if mean residual across open bins is large.
        score += 0.3 * mean_residual;
    }

    // Mild best-fit sharpening via quadratic post-residual term.
    score += pr * pr / bin_capacity as f64 * 0.4;

    // Slight tie-break noise-free coupling with bin count pressure.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: bucket post_residual into capacity-fraction classes.
    // Small dead space classes (< 25% capacity) are penalized quadratically.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        let dead = (quarter - post_residual) as f64;
        score += dead * dead * 0.15;
    }

    // Integer-division thresholds on post_residual: classes of size 10.
    let class = post_residual / 10;
    score += match class {
        0 => -20.0,
        1 => -8.0,
        2 => 0.0,
        3 => 4.0,
        _ => 8.0,
    };

    // Lookahead coupling: if the next item exactly fills the post residual,
    // this is a chain fit — strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills.
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 25.0 * fill;
        } else {
            // Next item cannot use this residual: mild penalty proportional
            // to wasted potential.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Early in the stream, keeping bins consolidated matters more.
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            1.0
        };
        score -= 20.0 * progress;
        // If item leaves a big residual in a fresh bin and next item is small,
        // the new bin is fine; if item is small, prefer existing bins.
        score += (item_size as f64) * 0.2;
        // If no open bin fits at all, new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Many open bins with high mean residual: discourage new bins.
        score += open_bins_count as f64 * 2.0;
        score += mean_residual * 0.3;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more reusable.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 25 == 0) {
        score -= 6.0;
    }

    // Slight penalty when bin residual is much larger than item (loose fit).
    if bin_residual > item_size * 2 {
        score += (bin_residual - item_size * 2) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    if post_residual > 0 {
        let dead_threshold = 10u32.min(bin_capacity / 10).max(1);
        if post_residual < dead_threshold {
            score += 500.0 * (dead_threshold - post_residual) as f64;
        }
        // Penalize gaps that cannot fit the lookahead item if no other bin could absorb it.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Perfect fit gets a strong reward.
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the resulting dead space is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }
    if fitting_bins_count > 1 {
        // Among many candidates, favor tighter fills relative to the pack.
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 40.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if post_residual stays large and usable.
        score += new_bin_penalty - 0.2 * post_residual as f64;
    }

    // Slight preference for filling larger-residual bins to keep mean residual low.
    score += 0.1 * (bin_residual as f64 - post_residual as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted potential.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.6 * miss.min(60.0);
    }

    // Penalize tiny unusable dead space (below minimum item size 1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Compare against mean residual: prefer bins whose residual deviates favorably.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly, more so early in the stream / few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if no existing bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for the next item (wasted gap).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the lookahead item.
            score -= 5.0;
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: empty bin should score high (bad) unless
    // existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0 + 0.4 * open_bins_count as f64;
        // If mean residual across open bins is large, opening a new bin is
        // less costly (existing bins are already fragmented).
        score -= 0.15 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Mild reward for using already-open bins, scaled by how full they are.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 3.0 * fill;
        // Slight penalty if many bins fit the item (less urgency), letting
        // tighter bins win via the tightness term.
        if fitting_bins_count > 1 {
            score += 0.5 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // Global fragmentation pressure: when mean residual is low, conserve bins.
    if mean_residual < 20.0 {
        score += 5.0 * (20.0 - mean_residual) / 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild penalty on wasted space; late stream: strong penalty (dead space hurts more).
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += waste_weight * (norm_post * norm_post) * cap * 0.25;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = 1.0 - (norm_post * std::f64::consts::PI / 2.0).tanh();
    score -= 6.0 * tightness * (1.0 + 0.5 * progress);

    // Lookahead coupling: if the next item fits into the post residual, reward this placement;
    // otherwise penalize proportionally to the leftover gap relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 3.0 * (nxt / cap);
        } else {
            let gap = (nxt - post) / cap;
            score += 4.0 * gap * (1.0 + progress);
        }
    }

    // Penalize opening a new bin when other bins can fit the item (smooth, not piecewise).
    let new_bin = (bin_residual == bin_capacity) as f64;
    let fit_pressure = 1.0 / (fitting_bins_count.max(1) as f64);
    score += new_bin * (8.0 + 10.0 * (1.0 - fit_pressure)) * (1.0 + 0.5 * progress);

    // Mild penalty when this bin is the last fitting bin (avoid wasting last-chance capacity on bad fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 * (1.0 - norm_post);
    }

    // Coupling with mean residual: prefer bins whose residual is near the mean (balanced packing).
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * dev * cap;

    // Encourage consolidating into fewer bins as the stream progresses.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by modulo bands
    let pr = post_residual as f64;
    let frac = pr / cap; // residual fraction of capacity

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals in awkward bands (can't fit small items later)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable dead space
    }

    // Modulo class coupling: residuals that are multiples of common item sizes
    // (10/20/25/50) are reusable; odd residuals are less reusable.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 25.0;
    } else if mod10 == 5 {
        score -= 10.0;
    } else {
        score += 5.0 + 2.0 * mod10 as f64;
    }

    // Integer-division threshold: post_residual in [next_item_size] compatibility
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bin can host the next item too: reward proportional to leftover after next
            let post2 = post_residual - next_item_size;
            score -= 30.0 + (post2 as f64).min(50.0) * 0.3;
            if post2 == 0 {
                score -= 80.0; // perfect two-item packing
            }
        } else {
            // next item won't fit here; penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // choose the tightest fit among many candidates: base score already does this,
        // add mild bonus for tightness
        score -= (1.0 - frac) * 10.0;
    }

    // New-bin candidate handling: only prefer fresh bin when all fits are terrible
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline, penalize early stream waste
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 0.5 * cap + 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 50.0; // next item may need fresh space anyway
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open first bin
        }
    }

    // Mean-residual coupling: when mean residual is high, tolerate loose fits
    score -= (mean_residual - frac * cap).max(0.0) * 0.05;

    // Slight preference to keep number of open bins low mid-stream
    if open_bins_count > 8 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items (<= 9) are essentially unusable -> heavy penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 18.0;
    } else if post_residual <= 40 {
        score += 6.0;
    } else {
        // Large leftover space is valuable: reward it mildly.
        score -= 8.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 25.0;
    } else if fill_ratio < 0.25 {
        // Dumping a small item into a big bin wastes capacity.
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += 4.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin would leave a
    // dead gap AND the next item could use a fresh bin's full capacity.
    if bin_residual == bin_capacity {
        if post_residual <= 9 && next_item_size > 0 {
            // Opening a new bin is only sensible if next item is large.
            if next_item_size >= 50 {
                score -= 30.0;
            } else {
                score += 25.0;
            }
        } else {
            // Default: mildly discourage opening new bins.
            score += 15.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item would not fit but would fit a fresh bin, penalize slightly.
    if next_item_size > post_residual && next_item_size <= bin_capacity && post_residual <= 9 {
        score += 10.0;
    }

    // Late in the stream: prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Alignment with mean residual: bins far below mean residual are
    // already tight; prefer them.
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
