pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward placing larger items (tight fits leave less dead space relative to effort)
    score -= (item_size as f64 / cap) * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins, but relax when many bins
    // are already open (consolidation pressure) and late in the stream
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 40.0 - 10.0 * openness - 10.0 * progress;
    }

    // Lookahead: if the next item also fits here, chain placements are valuable
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }

    // Penalize creating unusually small residual compared to fleet mean (dead space)
    if (post_residual as f64) < mean_residual * 0.3 {
        score += 5.0;
    }

    // Late in the stream, prefer consolidating into existing bins
    score -= progress * 5.0;

    // Slight preference for bins whose residual is close to the item (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = post / cap;

    // Base: tight packing favored, with non-linear (quadratic) reward for small post-residual.
    let mut score = post * (1.0 + 0.8 * (1.0 - fit_norm) * (1.0 - fit_norm));

    // Smooth progress coupling: waste tolerated less as stream advances.
    score -= 12.0 * progress * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Lookahead: reward if next item fits the post-residual smoothly (sigmoid-like).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - post;
        let s = 1.0 / (1.0 + (gap / 10.0) * (gap / 10.0));
        score -= 15.0 * s;
        // Penalize leaving residual just below the next item size (dead space).
        if gap > 0.0 {
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).abs();

    // New-bin candidate: penalize slightly so it wins only for poor fits / large items.
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction bucket does it land in?
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..=4

    // Reward tight fits strongly, with harmonic (modulo) structure.
    match post_class {
        0 => score -= 30.0,                          // near-perfect fit
        1 => score -= 15.0,                          // good fit
        2 => score -= 5.0,                           // moderate
        3 => score += 8.0,                           // wasteful
        _ => score += 20.0,                          // huge dead space
    }

    // Exact modulo bonus: residual divisible into small-item chunks
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra harmonic reward if next item also lands in a good class after
        let next_post = post_residual - next_item_size;
        if next_post / quarter <= 1 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover: penalize dead space proportionally
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual - (post_residual as f64);
        score += 40.0;
        if fragmentation > 40.0 && open_bins_count > 0 {
            score -= 30.0; // opening fresh is fine when open bins are packed tight
        }
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0; // next item won't fit typical open bin anyway
        }
    }

    // Late in the stream, be more conservative about waste
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += score * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps nonlinearly.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Small gaps (< 10) are pure dead space: heavy penalty.
        if pr < 10.0 {
            score += 40.0 * (10.0 - pr) / 10.0;
        }
        // Medium gaps (10..30) are only usable by small items: moderate penalty.
        else if pr < 30.0 {
            score += 8.0 * (30.0 - pr) / 20.0;
        }
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += 0.35 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if lookahead item is large and this bin would be near-empty after, allow it.
        if next_item_size as f64 > 0.5 * bin_capacity as f64 && pr > next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (pr - n).abs() < 1.0 {
            score -= 12.0; // perfect two-item sequence
        } else if pr >= n {
            score -= 4.0;
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Mean residual alignment: prefer bins whose residual is close to the item need.
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // Late-stream consolidation: as stream progresses, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * pr / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: exact match of next item into post_residual is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward leaving room for the next item; penalize large slack beyond it.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            if slack <= 10.0 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.5 * shortfall;
        }
    }

    // Compare residual against mean residual of open bins.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 15.0; // leaving this bin much emptier than average wastes space
    } else if (post_residual as f64 - mean_residual).abs() <= 10.0 {
        score -= 10.0; // keeps residuals balanced
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Early in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Discourage opening a new bin when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity && open_bins_count > 0 && next_item_size > 0 {
        score += 35.0;
        // But allow opening a new bin if the item would leave a huge dead space elsewhere.
        if post_residual >= 40 && bin_residual < bin_capacity {
            score -= 0.0;
        }
    }

    // Slight preference for filling bins with small residuals tightly.
    if bin_residual < bin_capacity {
        score += 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
