pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit).
    let mut score = post;

    // Non-linear tightness reward: quadratic coupling of fit ratio with stream progress.
    let fit_ratio = item / cap;
    score -= 12.0 * fit_ratio * (1.0 + progress);

    // Penalize large dead space non-linearly (cubic in normalized residual).
    let norm_post = post / cap;
    score += 25.0 * norm_post * norm_post * norm_post;

    // Penalize residuals that are too small to be useful later (smooth valley around ~30).
    let useful = ((post - 30.0) / 30.0).powi(2);
    score += 6.0 * useful * (1.0 - progress);

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: open a new bin only when current bin fits poorly.
    if bin_residual == bin_capacity {
        let waste_elsewhere = mean_residual / cap;
        score += 10.0 * (1.0 - fit_ratio) - 8.0 * waste_elsewhere * (1.0 - progress);
    } else {
        // Slight penalty for many open bins to encourage consolidation.
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions (integer division thresholds)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Class penalty: residual buckets via integer division
    let post_class = post_residual / quarter; // 0..4
    let class_penalty = match post_class {
        0 => -18.0, // post_residual < 25: tight fit, excellent packing
        1 => -4.0,  // 25..50: decent
        2 => 6.0,   // 50..75: wasteful
        _ => 16.0,  // >=75: nearly empty bin used poorly
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residue classes mod 10 (dead-space granularity)
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0; // perfectly divisible residual, likely reusable
    } else if m < 5 {
        score += (m as f64) * 0.8; // small awkward slivers
    } else {
        score -= ((10 - m) as f64) * 0.4;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item divides residual nicely
            let ratio = post_residual as f64 / next_item_size as f64;
            if (post_residual % next_item_size) == 0 {
                score -= 12.0; // perfect fill later
            } else if ratio < 2.0 {
                score -= 7.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize if residual becomes dead space
            if post_residual < next_item_size.min(bin_capacity / 4) {
                score += 10.0;
            }
        }
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when placement elsewhere is terrible
    if bin_residual == bin_capacity {
        // opening a new bin: base cost
        score = 55.0;
        if fitting_bins_count == 0 {
            score = -100.0; // must open
        } else if post_residual >= half {
            score -= 10.0; // large item justifies fresh bin
        }
        // late in stream, prefer reusing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Slight preference for many-open-bins consolidation
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest conceivable
    // follow-up item are pure waste; penalize them super-linearly.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 {
        score += 40.0;
    } else if post_residual <= 10 {
        // gap of exactly 10 is reusable only by the smallest item
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Perfect fill: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if (post_residual as f64) > 0.0 {
            // next item cannot use this gap -> gap likely becomes dead space
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual <= 20 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when existing
    // bins would leave large dead space or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin grows with number of open bins
        score += 30.0 + 6.0 * open_bins_count as f64;
        // but if existing best fit would waste a lot, opening is fine
        score -= 0.4 * mean_residual;
        // early in the stream, opening bins is cheaper (future packing freedom)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
    }

    // Mild pressure: prefer filling bins that are already heavily loaded
    // (residual close to item_size means high fill ratio).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    // Prefer bins whose residual is below the mean (consolidate small gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward: exact match leaves a perfectly filled bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: can next item fit into the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item can't use: penalize proportionally.
        score += 8.0 + 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Compare post residual against mean residual of open bins:
    // leaving less than average residual wastes space elsewhere.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins that are already quite full (tight packing).
    let fill_ratio = 1.0 - (post_residual as f64 / cap);
    score -= 5.0 * fill_ratio;

    // Early in stream: slightly favor consolidating into fewer bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 3.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 1.0));
    }

    // New empty bin candidate: baseline penalty so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item fits into the post-residual,
    // penalize if post-residual is a dead zone that can't host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < 10 {
            // small dead space; less harmful if next item is large (needs fresh bin anyway)
            if next_item_size > 60 {
                score -= 10.0;
            } else {
                score += 15.0;
            }
        }
        // If this bin is the only option and next item is big, keeping residual large helps
        if next_item_size > post_residual && post_residual > next_item_size.saturating_sub(0) {
            score += 0.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 30 {
            score -= 200.0;
        } else {
            score -= 50.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, scaled by how well the
    // item would use it and global state.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 120.0;
        // Large items are fine to start a fresh bin with.
        score -= fill_ratio * 90.0;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // If open bins have plenty of residual capacity on average, opening new is wasteful.
        if mean_residual > item_size as f64 + 20.0 {
            score += 40.0;
        }
        // If many bins are open already, prefer reusing.
        score += (open_bins_count as f64).min(20.0) * 2.0;
    }

    // Mild preference for filling fuller bins (lower residual) among equals.
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Penalize leaving residuals in the awkward 10..30 zone (hard to fill later).
    if post_residual >= 10 && post_residual <= 30 {
        let awkward = 1.0 - ((post_residual as f64 - 10.0) / 20.0).abs();
        score += 12.0 * awkward;
    }

    // Reward bins whose residual is much larger than the item (good reuse of space)
    if bin_residual != bin_capacity && post_residual > 40 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post residual), with non-linear sharpening
    let mut score = x * (1.0 + 0.8 * x * x);

    // Polynomial coupling with stream progress: later in the stream, dead space matters more
    let progress_coupling = 0.6 * t * x * (1.0 - x);
    score += progress_coupling;

    // Penalize post residual that cannot fit the lookahead item (smooth gate)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let fit_gap = nx - x;
        if fit_gap > 0.0 {
            score += 0.5 * fit_gap * fit_gap * (1.0 + t);
        } else {
            // reward bins whose residual accommodates the next item
            score -= 0.25 * (-fit_gap) * (1.0 - t);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 * (1.0 - x);
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized early, more attractive late
    if bin_residual == bin_capacity {
        score = 0.9 + 0.8 * t + 0.05 * open_bins_count as f64;
    }

    // Mild penalty for bin residuals far from the mean residual (encourages balance)
    let dev = (mean_residual - pr) / cap;
    score += 0.15 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..10 harmonic band

    // Reward bands that are "perfect" residues (0, 10, 20, 25, 50, 100 style).
    let perfect = matches!(post_residual, 0 | 10 | 20 | 25 | 50 | 100);
    if perfect {
        score -= 30.0;
    }

    // Penalize awkward mid-band residues (hard to fill later).
    match class {
        1 | 2 | 3 => score += 18.0,   // tiny slivers 1..30
        4 | 5 => score += 6.0,        // half-bin-ish, still usable
        6 | 7 => score += 2.0,
        8 | 9 => score -= 4.0,        // nearly full bin, great fit
        _ => {}
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_frac = next_item_size as f64 / bin_capacity as f64;
            // harmonic class of next item vs. remaining space
            let nxt_class = (nxt_frac * 10.0).floor() as i64;
            if nxt_class == class && post_residual > 0 {
                score -= 12.0; // same harmonic band, likely good chaining
            }
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is terrible
    // and many open bins exist (fragmentation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 > bin_capacity as f64 * 0.5
            && (item_size as f64 / bin_capacity as f64) < 0.35;
        if bad_fit && open_bins_count > 2 && progress > 0.05 {
            score -= 20.0; // prefer fresh bin
        } else {
            score += 40.0; // discourage opening new bins by default
        }
    }

    // Mild pressure toward packing into existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post > 0.0 && post < 10.0 {
        score += 40.0 * (10.0 - post) / 10.0; // tiny gaps = wasted capacity
    }

    // Unusable for lookahead item: dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * post;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight fits relative to the bin's original residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when all open bins would leave large,
    // unusable residue or when bin pressure is low. Otherwise make it unattractive.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes nothing now, but costs a fresh bin.
        score += 20.0 + 3.0 * (open_bins_count as f64).sqrt();
        // If item nearly fills a fresh bin, opening is reasonable.
        if item_size as f64 > 0.8 * cap {
            score -= 25.0;
        }
        // With high mean residual across open bins, prefer reusing them.
        score += 0.10 * mean_residual;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Late-stream consolidation: keep closing out existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.89;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= (cap - post).powi(2) / (2.0 * cap);

    // Lookahead: reward if next item fits in post-residual (chaining), penalize waste if not.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - post / cap);
        } else if post > 0.0 {
            // Dead space that next item cannot use: penalize more late in stream.
            let t = step_index as f64 / total_items.max(1) as f64;
            score += 4.0 + 6.0 * t * (post / cap);
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= 10.0 * (1.0 - post / cap);
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 3.0 + 0.05 * (bin_residual as f64 - item_size as f64);
    } else if fitting_bins_count > 1 {
        // Many options: be pickier about tightness.
        score += 0.02 * post;
    }

    // New empty bin candidate: neutral-ish but slightly penalized so it only wins on bad fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 4.0; // opening fresh bin is fine for uniform pairs
        }
    }

    // Global state coupling: spread load when mean residual is high.
    if (bin_residual as f64) > mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual with non-linear polynomial coupling to stream progress.
    // Early on, tight packing matters less; later, small residuals are heavily penalized.
    let norm_pr = pr / cap; // 0..1
    let poly = norm_pr * (1.0 + 2.0 * progress) - 1.5 * norm_pr * norm_pr * (0.5 + progress);
    let mut score = pr + 40.0 * poly;

    // Lookahead: if next item fits exactly in post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack_gap = (pr - nx) / cap;
            score -= 25.0 * (1.0 - slack_gap) * (1.0 - slack_gap);
        }
    }

    // Last-chance bin: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: penalize mildly unless few fitting bins or large mean residual.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_norm = mean_residual / cap;
        score = cap as f64 * (0.5 + 0.5 * progress)
            - 60.0 * pressure
            - 20.0 * mean_norm
            - (if fitting_bins_count > 0 { 0.0 } else { 0.0 });
    }

    // Slight preference for bins tighter than average (fragments consolidation).
    score += 5.0 * ((bin_residual as f64) - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes for typical item sizes (small multiples / divisors).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if pr <= 10 {
        score -= 40.0; // near-perfect: dead space almost negligible
    } else if pr % 10 == 0 {
        score -= 25.0; // harmonic class: residual aligns with common item grid
    } else if pr % 5 == 0 {
        score -= 12.0; // semi-harmonic class
    }

    // Integer-division thresholds: residuals in (10,20] can host a small item;
    // residuals in (20,40] are moderately reusable; larger is worse.
    let class = pr / 10; // 0..=10 integer division class
    score += class as f64 * 4.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (next_item_size - pr).min(30) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): only attractive when fit is poor
    // or no real bin gives a good fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if many bins are open and mean residual is large, opening fresh
        // is less attractive since consolidation is possible
        score += open_bins_count as f64 * 1.5;
        score -= mean_residual * 0.3;
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Slight preference for fuller bins overall (tight packing pressure).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Mild penalty when this bin's residual deviates far from mean residual
    // (keep residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residual below the lookahead item size is likely dead too (mild penalty
    // since a future different item might still fit).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * post_residual as f64;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead synergy: if the next item exactly fits the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Pressure from too many open bins: prefer consolidation.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when the item would leave a
    // large, useful residual and open bins are crowded with small residuals.
    if bin_residual == bin_capacity {
        // Baseline neutral-ish score for a fresh bin.
        score = 45.0 + 0.8 * open_bins_count as f64;
        // Fresh bin is good if existing bins are nearly full on average.
        score -= 0.3 * mean_residual;
        // Fresh bin is bad if it wastes most of a bin on a small item.
        if item_size < 40 {
            score += (40 - item_size) as f64;
        }
        // If no other bin fits well (few fitting bins), opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fill of the residual (perfect packing).
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if the next item exactly fits the leftover space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild bonus proportional to slack left after it.
            score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot fit: penalize dead space, worse when gap is small.
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 + 1.5 * gap;
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful fit).
    if post_residual as f64 > mean_residual {
        score += 0.8 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.4 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New empty bin candidate: only attractive when current fits are poor
    // or item is large relative to all residuals.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when it beats poor fits.
        score += 120.0;
        // Large items or many open bins make a fresh bin more reasonable.
        score -= 0.6 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Slight late-stream conservatism: consolidate into fewer bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward near-zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can fit into the resulting residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack_after_next.min(25.0) * 0.5;
    }
    // Penalize residual too small for the lookahead item (dead space trap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate penalty: opening a bin is costly; only allow when it
    // creates a large, next-item-usable residual or existing fits are awful.
    if bin_residual == bin_capacity {
        score += 70.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 90.0; // fresh bin tailored for the next item
        }
        if fitting_bins_count >= 1 && post_residual < 30 {
            score += 50.0; // new bin with tiny residual is terrible
        }
    }

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 10.0 * (mean_residual / 100.0).min(1.0);
    }

    // Late in the stream, tighten packing: punish wasted residual more.
    score += post_residual as f64 * progress * 0.5;

    // Mild preference for bins with tighter current residual among equals.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new = (bin_residual == bin_capacity) as i32 as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear waste penalty: dead space hurts more when small and late
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward filling a bin nearly completely (smooth quadratic bonus)
    let fill = 1.0 - norm_pr;
    score -= 8.0 * fill * fill * fill;

    // Perfect-fit lookahead: if next item exactly matches post residual
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 {
        // penalize post residuals that are awkward for the next item
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.06 * gap;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 10.0;
    }

    // New-bin candidate handling: smooth polynomial penalty that relaxes
    // when existing bins fit poorly (many bins, high mean residual mismatch)
    let mean_gap = (mean_residual - item_size as f64).abs();
    let openness = (open_bins_count as f64).ln().max(1.0);
    let new_penalty = 18.0 + 20.0 * (1.0 - progress) - 0.8 * mean_gap.min(20.0) - 1.5 * openness;
    score += is_new * new_penalty.max(2.0);

    // Smooth coupling: waste relative to stream position
    score += 6.0 * norm_pr * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (post_residual close to 0) super-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - frac).powi(4);

    // Lookahead (k=2): if the next item fits into the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 7.0;
        // Extra reward if next item exactly fills leftover space.
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only open bin that can fit, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin when existing
    // open bins have plenty of residual capacity to absorb items.
    if bin_residual == bin_capacity {
        score += 8.0
            + 0.35 * mean_residual
            + 0.4 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
    }

    // Harmonic classes: classify post_residual into dead-space classes modulo 20.
    // Residuals that are useless for typical small items get penalized;
    // residuals that are near-zero or exact small-item complements get rewarded.
    let cls = post_residual % 20;
    match cls {
        0 => score -= 4.0,        // perfectly reusable class
        1 | 2 => score -= 2.0,    // near-full, tiny waste
        3..=7 => score += 1.5,    // awkward small gap
        8..=14 => score += 3.0,   // dead space class
        _ => score += 0.5,        // moderately reusable
    }

    // Integer-division threshold: residual >= half capacity is valuable for medium items.
    if post_residual >= bin_capacity / 2 {
        score -= 3.0;
    }

    // Slight preference for bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.05 * tightness * (1.0 - (item_size as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100
    // interface, but keep conservative threshold) are pure waste; penalize small
    // gaps super-linearly so bins leaving tiny unusable slivers are avoided.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.15);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual after placement still fits the lookahead item
    // (keeps future options alive); penalize bins that block the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // over opening new bins (penalize the fresh empty bin candidate).
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        score += 25.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (concentrate filling).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, allow new bins more freely; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: strong reward, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 0.5;
            if post_residual == next_item_size {
                score -= 300.0; // perfect 2-item fill
            }
        } else {
            // Next item cannot use the leftover: penalize dead space, worse when residual is tiny.
            let dead = post_residual as f64;
            score += dead * dead * 0.05;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is above average (bigger holes),
    // penalize dipping far below mean residual.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;
    if dev > 0.0 {
        score += dev * dev * 0.02;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 400.0;
        } else {
            // Opening a new bin is wasteful if decent fits exist; penalize mildly.
            score += 50.0 + 10.0 * fitting_bins_count as f64;
        }
    }

    // Early in the stream, allow more bins; late, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with small residuals overall (tight packing), tie-break deterministically.
    score += (bin_residual as f64) * 0.1;
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for typical future items,
    // scaled by how much of the bin was just consumed.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if post_residual > 0 && (post_residual as f64) < 0.2 * bin_capacity as f64 {
        score += 40.0 * (1.0 - fill_frac);
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item would not fit here; slight penalty proportional to overshoot.
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Scarcity pressure: when few bins can fit the item, prefer the fullest fitting bin.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 20.0 * scarcity * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are quite full on average or the item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin, discounted by how "wasteful" existing bins are.
        let mut new_bin_cost = 150.0
            - 120.0 * avg_fullness
            - 40.0 * item_frac
            - 30.0 * progress;
        // If the only alternative is a terrible fit (huge post residual on best bin),
        // opening a new bin becomes more attractive — approximate via mean residual.
        if mean_residual < 0.5 * bin_capacity as f64 {
            new_bin_cost -= 25.0;
        }
        score += new_bin_cost.max(5.0);
    }

    // Mild global pressure: many open bins -> prefer packing tighter into existing ones.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, keep bins flexible (avoid tiny residuals);
    // late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.1 * post_residual as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, nonlinearly (quadratic dead-space term)
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tighter packing (higher order in norm_pr);
    // later, prefer filling bins more completely.
    let coupling = progress * progress * (1.0 - progress) * (1.0 - progress);
    score -= 30.0 * coupling * (cap - pr) / cap * (cap - pr) / cap * cap;

    // Reward using nearly-full bins, weighted by progress
    score -= progress * (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0;

    // Penalize bins that are too empty relative to mean residual (fragmentation)
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            score += 4.0 * (nxt - pr) / cap * cap * 0.1;
        }
    }

    // Mild penalty for proliferating open bins
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: bucket by integer division on 10
    let class = post_residual / 10;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 200.0;
    } else if class == 0 {
        // tiny dead space (1..9): mild penalty to avoid near-perfect but wasteful fills
        score += 15.0;
    } else if class == 1 || class == 2 {
        // 10..29 residual: usable for typical small items, reward
        score -= 10.0;
    } else if class == 3 || class == 4 {
        // 30..49: neutral-good
        score -= 3.0;
    } else if class >= 7 {
        // 70+: mostly empty bin, low priority unless nothing better
        score += 8.0;
    }

    // Harmonic match: does post_residual align with next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits exactly into leftover: big reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.3 * slack;
            if post_residual == next_item_size {
                score -= 60.0;
            }
        } else {
            // leftover can't host next item: penalty scaled by how close we are to capacity fraction thresholds
            let over = (next_item_size - post_residual) as f64;
            score += 0.4 * over;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New empty bin candidate: keep it moderately attractive only when few bins fit or residual mean is low
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += pressure + 20.0 * (1.0 - progress);
        if item_size > 50 {
            score += 10.0; // big items better into partially filled bins
        }
    }

    // Prefer tighter bins overall: compare residual to mean residual
    score += 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
