    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage fragmentation and
    // prefer filling existing bins; with few bins, opening a new one is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: baseline score so it wins only when all open bins
    // would create significant dead space.
    if bin_residual == bin_capacity {
        score = 45.0 + pressure * 0.5 - 10.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 80.0; // never open new bin when it's the only fitting one
        }
    }

    // Slight nudge toward bins below mean residual (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

