    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual_f / mean_residual;
        score += 5.0 * (rel - 1.0);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize leaving a tiny unusable sliver (<10) that likely becomes dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: empty bin starts with high score so it's only
