    if bin_residual == bin_capacity {
        // Neutral base; gets opened only when it wins outright
        score += 0.0;
        // Slight early-stream preference to open bins (builds a diverse pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
