    // Large items: prefer consuming big residuals aggressively
    if item_size > bin_capacity / 2 {
        score -= 8.0;
    }

    // Mild crowding pressure: with many open bins, favor consolidating into
    // existing bins rather than spreading (keeps mean_residual low).
    score += 0.5 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
