        // Base cost of opening a new bin.
        score += 25.0;
        // Attractive if no bin fits or fits are very loose.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, keeping bins flexible is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - progress);
        // If mean residual of open bins is high, prefer reusing them.
        score += 0.3 * mean_residual;
    } else {
        // Reward using bins with larger residuals when the item is big.
        score -= 0.1 * bin_residual as f64 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear coupling: residual penalized more as stream progresses
    let progress_weight = 0.5 + 2.0 * progress;
    score += progress_weight * pr_norm * pr_norm * cap * 0.3;

    // Reward tight fits with smooth saturation
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Last-chance bonus (smooth, not piecewise)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 6.0 * last_chance * (1.0 - pr_norm);

    // Lookahead: penalize if post_residual cannot serve next item, reward if it can
    if next_item_size > 0 {
        let fits_next = (post_residual as u32 >= next_item_size) as i32 as f64;
        let match_next = 1.0 - ((post_residual as f64 - next_item_size as f64).abs() / cap);
        score += 3.0 * (1.0 - fits_next) * pr_norm;
        score -= 4.0 * fits_next * match_next * match_next;
    }

    // Mean residual deviation coupling
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.1;

    // New-bin candidate: mildly penalize opening new bins when many open
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (2.0 + 0.05 * open_bins_count as f64);

    // Penalize large dead space quadratically, smoothed by progress
    score += 0.02 * pr * pr / cap * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let fifth = cap / 5.0;

    // Penalize residuals that are "wasted" — too small to fit typical items
    // (harmonic classes: (0,10] dead, (10,25] narrow, (25,50] medium, >50 useful).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space class
    } else if pr <= quarter {
        score += 12.0;
    } else if pr <= 2.0 * quarter {
        score += 3.0;
    } else {
        score -= 8.0; // large residual is reusable
    }

    // Modulo arithmetic on post_residual: residuals near multiples of common
    // item sizes (10,20,25,50) are "harmonic" and likely to be filled later.
    let harmonics: [u32; 5] = [10, 20, 25, 40, 50];
    let mut harmonic_bonus = 0.0;
    for h in harmonics.iter() {
        if post_residual >= *h {
            let r = post_residual % h;
            let d = (*h as f64 - r as f64).min(r as f64);
            if d <= 2 {
                harmonic_bonus += 6.0;
            }
        }
    }
    score -= harmonic_bonus;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 2 {
        score -= 60.0;
    }

    // Lookahead: does next_item_size fit exactly in the post_residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // chain a perfect pair
        } else if post_residual > next_item_size {
            score -= 10.0; // next item can follow here
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 5 {
                score += 6.0; // near-miss is frustrating
            } else {
                score += 15.0; // next item forces a new bin anyway
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all
    // open fits are poor. Give the empty bin a baseline near mid-quality.
    if bin_residual == bin_capacity {
        score = 0.35 * cap; // neutral baseline; poor fits in open bins score worse
        // Slightly prefer opening bins early in the stream when many bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 8.0;
        }
        return score;
    }

    // Mild pressure against accumulating too many open bins with sloppy fits.
    if open_bins_count > 8 {
        score += 0.5 * open_bins_count as f64;
    }

    // Tie-break toward bins with residual close to the stream mean (keeps
    // the residual distribution uniform, easier to fill later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A post_residual below the minimum item size is pure waste.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        // "Almost unusable" gaps that only tiny items can fill.
        score += 18.0;
    }

    // Reward tight fits: the smaller post_residual relative to bin capacity,
    // the better the packing density.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // rather than spreading items; penalize placements that keep many bins open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin — finishing it off is valuable (freeing a bin).
    let res_diff = mean_residual - bin_residual as f64;
    if res_diff > 0.0 {
        score -= 0.5 * res_diff;
    } else {
        score += 0.3 * (-res_diff);
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (chained perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap < 10 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving a gap
        // that neither the next item nor typical items can use.
        score += 5.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins offer poor fits. Penalize opening a new bin moderately, scaled by
    // how many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 12.0 * fitting_bins_count as f64;
        // But late in the stream, opening a fresh bin is less costly.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches (or closely fits) the next item's size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain match gets a big discount.
            if slack == 0.0 {
                score -= 45.0;
            } else {
                score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how far off the chain is.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual means we packed tighter than typical.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin when decent fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    // Mild late-stream tightening: as the stream progresses, prefer
    // consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tight) * (1.0 - tight) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that next item can't use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Reward if leftover exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for wasting an empty bin.
        let mut nb = 55.0 + 0.3 * open_bins_count as f64;
        // Late in the stream, prefer consolidation into open bins.
        nb += 25.0 * progress;
        // If mean residual across open bins is large, opening new bin is wasteful.
        nb += mean_residual * 0.4;
        // If item is large relative to capacity, a fresh bin is more acceptable.
        nb -= (item_size as f64 / bin_capacity as f64) * 40.0;
        // If many bins fit the item, definitely use one of them.
        nb += 10.0 * (fitting_bins_count as f64).min(5.0);
        score += nb;
    }

    // Mild preference to balance load across bins when many are open.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Prefer fuller bins (waste-averse tiebreak).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear reward for tight fits (small post_residual relative to capacity)
    let tightness = pr / cap;
    score -= (1.0 - tightness).powi(4) * 12.0;

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is more costly -> amplify residual penalty
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += pr * tightness * progress_coupling * 0.8;

    // Penalize near-mean residuals mildly (fragmentation relative to fleet average)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 4.0 * (1.0 + progress_coupling);

    // Lookahead: reward leaving space that fits the next item smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64 / pr).clamp(0.0, 1.0);
        score -= fit_quality * (1.0 - fit_quality) * 4.0 * 4.0; // peak reward at ~half-fill match
    }
    // Penalize residual too small for the next item (dead space)
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * 0.15 * (1.0 + progress_coupling);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New empty bin candidate: penalize, more so early (bins accumulate for future use)
    if bin_residual == bin_capacity && item_size <= bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let pr = post_residual as u32;
    let class = pr % 10; // fine-grained residual class
    let half = bin_capacity / 2;
    let quart = bin_capacity / 4;

    // Reward residuals that belong to "useful" harmonic classes:
    // multiples of 10 and 25 are more likely to be exactly filled by future items.
    if pr % 25 == 0 && pr > 0 {
        score -= 12.0;
    } else if class == 0 && pr > 0 {
        score -= 6.0;
    } else if class <= 2 {
        score -= 2.0;
    } else if class >= 8 {
        score += 3.0; // awkward near-multiple residual: dead-space risk
    }

    // Penalize very small post residuals slightly less if they are near-zero (good packing)
    if pr <= 2 {
        score -= 8.0;
    }

    // Tight fit reward: item consumes most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            // harmonic compatibility: next item size class matches residual class
            if (next_item_size % 10) == class {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize leaving a large unusable gap
            let gap = pr as f64;
            if gap > (next_item_size as f64) * 0.5 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // open a new bin if mean residual is large (open bins are fragmented)
        score = 60.0 - 40.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // next item is big, fresh bin pairs well
        }
    }

    // Stream progression: later in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fill);

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - fill) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste; penalize them extra hard.
    if post_residual < 10 {
        score += 25.0 + 0.5 * post; // dead space penalty
    } else {
        // Usable gap: reward leaving a gap that can absorb the lookahead item.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        }
        // Smooth fill reward: tighter fit (smaller post_residual) already favored
        // by base term; add mild non-linear bonus for very tight fits.
        score -= 6.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open and mean
    // residual is plentiful; encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base aversion scaled by open bins and slack in system.
        score += 20.0 + 3.0 * open_bins_count as f64 + 0.05 * mean_residual;
        // Late in the stream, be even more reluctant to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // But if no open bin fits well (post_residual would be tiny dead space),
        // a fresh bin is fine: soften the penalty.
        if fitting_bins_count >= 1 {
            let best_gap = post; // post_residual of an open-bin call equals its gap
            if best_gap < 10.0 {
                score -= 30.0;
            }
        }
    } else {
        // Fitting into an existing bin: reward proportional to how much it beats mean residual.
        score -= 0.05 * (mean_residual - post).max(0.0);
        // Mild bonus for keeping bin count stable.
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
