pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Tightness: reward small post_residual relative to capacity
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= 60.0 * tightness * tightness;
    }

    // Dead-space penalty: leftover that likely can't hold the next item
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 0.5 * (post_residual as f64);
        } else {
            // leftover can hold next item: reward
            score -= 10.0;
        }
    }

    // Lookahead coupling: if post_residual fits next item well, favor
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size as u32;
        score -= 20.0 * (slack as f64 / cap);
    }

    // New-bin candidate handling: opening a new bin is expensive
    if bin_residual == bin_capacity {
        // Base cost of opening a bin
        score += 150.0;
        // More acceptable early in the stream or when few fitting bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // forced: no alternative
        } else if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // If existing bins have lots of mean residual, prefer using them
        score += 0.3 * mean_residual;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Reward using bins below mean residual (filling emptier bins)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.2 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize key quantities
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;                 // normalized post-residual [0,1]
    let fill = 1.0 - pr;                                 // bin fill fraction after placement
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let next = (next_item_size as f64 / cap).clamp(0.0, 1.0);

    // Smooth non-linear coupling: reward tight fits with a convex fill term
    // that grows as the stream progresses (late-stage consolidation).
    let tightness = (fill * fill * (1.0 + 2.0 * fill)) * (0.5 + progress);
    score -= 30.0 * tightness;

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward strongly (smooth gaussian-like coupling instead of a hard branch).
    let gap = (pr - next).abs();
    let lookahead_fit = (-12.0 * gap * gap).exp();
    score -= 18.0 * lookahead_fit * (0.4 + 0.6 * progress);

    // Penalize leaving residuals that are too small to be useful later
    // (smooth sigmoid on normalized post-residual).
    let dead = 1.0 / (1.0 + (pr * 12.0 - 1.5).exp());
    score += 25.0 * dead;

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (consolidating small leftovers), with a smooth quadratic term.
    let mr = mean_residual / cap;
    let dev = (pr - mr).abs();
    score += 6.0 * dev * dev * (1.0 + progress);

    // New-bin candidate handling: empty bins start with a mild penalty so that
    // existing bins with decent fits win; the penalty decays smoothly when no
    // other bin fits well (fitting_bins_count small).
    let is_new = (bin_residual == bin_capacity) as f64;
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score += is_new * (8.0 + 20.0 * (1.0 - (scarcity.min(1.0)))) * (0.6 + 0.4 * progress);

    // Slight pressure to keep the number of open bins in check via a soft term
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // Small tie-breaker on exact post-residual to prefer smaller leftovers
    score += 0.01 * pr * pr * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: quantize dead space into capacity fractions ---
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual create harmonic "bins within bins".
    // Residual classes: 0 (perfect), <=10 (great), <=25 (good), <=50 (ok), else bad.
    let class: f64 = if post_residual == 0 {
        -40.0
    } else if post_residual <= 10 {
        -25.0
    } else if post_residual <= 25 {
        -10.0
    } else if post_residual <= 50 {
        0.0
    } else {
        12.0
    };
    score += class;

    // Modulo arithmetic: residuals divisible by common item-size steps (e.g. 10) are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // --- Lookahead coupling: can next_item_size fit into the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chain placements, scaled by how tightly the next item fits.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 + 15.0 * tightness;
        } else {
            // Penalize creating residual that wastes the known next item's class.
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.08 * wasted;
        }
        // Harmonic pairing: item + next item near-capacity combos are golden.
        let pair = item_size + next_item_size;
        if pair == bin_capacity {
            score -= 18.0;
        } else if pair > bin_capacity {
            score += 3.0;
        }
    }

    // --- Fit scarcity: last-chance bin gets strong reward ---
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Mild bonus for competition among many fitting bins based on tight fit.
        let tight = (bin_residual - item_size) as f64;
        score -= tight * 0.05 / (fitting_bins_count as f64).sqrt();
    }

    // --- Mean residual coupling: avoid bins far from the pack's average slack ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // --- Stream progression: early on, keep bins balanced; late, pack greedily ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is worthwhile only if no tight option exists:
        // base penalty so it loses against decent fits, but beats very bad residuals.
        let mut nb = 30.0 + frac * 0.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            nb -= 4.0;
        }
        if open_bins_count == 0 {
            nb = -100.0; // must open when nothing is open
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible item are effectively wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to bin_residual).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score = bin_capacity as f64 * 0.5 + 12.0 * open_bins_count as f64 + 30.0 * progress;
        // Opening a fresh bin is fine if residuals are mostly dead.
        if mean_residual < 8.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (minimize dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host
    // the next item exactly or nearly so.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) == next {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - next;
            if slack <= 10.0 {
                score -= 250.0 - 15.0 * slack;
            } else {
                // still mildly favor chains, decaying with slack
                score -= 100.0 / (1.0 + slack * 0.08);
            }
        } else {
            // next item cannot fit here: penalize proportionally to the gap,
            // signaling wasted lookahead potential.
            let gap = next - post_residual as f64;
            score += 20.0 + 3.0 * gap;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let dev = mean_residual - post_residual as f64;
    score -= 0.5 * dev;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins can still absorb the item,
    // unless the fit is terrible (large post_residual).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let new_bin_penalty = 500.0 + 4.0 * waste;
        let open_alters = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += new_bin_penalty * open_alters;
        // Slight bonus for a fresh bin early in the stream when few bins open.
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mild stream-progression term: later in the stream, be more conservative
    // about leaving large residuals (fewer chances to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Small tie-breaker: prefer bins with larger residual consumed.
    score -= item_size as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to how far off.
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins: slight penalty to encourage spreading / keeping good bins.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state coupling: prefer filling bins when mean residual is low (consolidation phase).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Time horizon: early in stream, slightly discourage opening new bins (keep bins tight);
    // late in stream, allow more freedom.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // New bin candidate: base cost plus scaling; cheaper to open early when few bins,
        // expensive late when many bins could still absorb the item.
        score = 30.0 + 20.0 * progress - 2.0 * open_bins_count as f64;
        // If item is large, new bin is more attractive since it leaves usable space.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        // If no lookahead fits anywhere meaningful, opening is fine.
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Mild preference for bins with larger residual when item is small (save tight bins).
    if item_size <= 30 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fits rewarded: quadratic bonus as post_residual approaches zero
    let tightness = 1.0 - (pr / cap);
    score -= 60.0 * tightness * tightness;

    // Dead-space penalty: residuals too small for typical future items are costly
    let dead = (pr / cap).powi(3);
    score += 25.0 * dead;

    // Lookahead coupling: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 30.0 * (-gap / 40.0).exp();
        // exact lookahead fit is highly desirable
        if pr >= nx {
            score -= 20.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Stream-progress interaction: later in the stream, prefer tighter packing more aggressively
    score -= 35.0 * progress * tightness * tightness;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mean-residual coupling: if this bin's residual deviates favorably from the mean,
    // consolidating space is good; penalize bins already much emptier than average
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev.max(0.0) - 5.0 * (-dev).max(0.0);

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // but allow new bin late in stream if fit would be terrible
        if pr / cap < 0.25 {
            score -= 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are precious
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residuals that are "usable" sizes (multiples of common item classes)
    // Class 1: residual divisible into halves/quarters of capacity
    if bin_capacity % post_residual.max(1) == 0 && post_residual > 0 {
        score -= 20.0; // residual itself is a "harmonic" divisor of capacity
    }

    // Next item lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // harmonic coupling: next item leaves a harmonic residual
            let nr = post_residual - next_item_size;
            if bin_capacity % nr.max(1) == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize modestly
            score += 5.0;
        }
    }

    // Penalize large dead space relative to capacity
    score += (pr / cap) * (pr / cap) * 10.0;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 60.0;
        // cheaper to open new bin late in stream with many open bins having small residuals
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 {
            score -= 40.0 * progress;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // big next item: fresh bin may serve it
        }
    }

    // Prefer bins with residual close to item (tight fit) via modulo-class threshold
    let waste = bin_residual - item_size;
    if waste <= 10 {
        score -= 10.0;
    } else if waste <= 25 {
        score -= 3.0;
    }

    // Modulo arithmetic on post_residual: reward residuals in common size classes
    let cls = post_residual % 20;
    if cls == 0 {
        score -= 5.0;
    } else if cls == 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 40.0; // hard-to-fill small gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this call is the empty-bin call itself, residual == capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced under bin pressure.
        score = 120.0 + 15.0 * open_bins_count as f64;
        // If the next item could use this fresh bin's space, soften the cost.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
    }

    // Open-bin pressure: with many open bins, mildly favor filling existing ones.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins with residual close to the mean (balanced packing).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item fits this bin's post_residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish lookahead match: next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally.
        score += 4.0;
    }

    // Penalize tiny dead space that nothing (min size 1..) can use productively.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Compare post_residual against mean residual: keeping residual near mean
    // preserves flexibility across the open-bin pool.
    score -= 1.5 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is awful.
    if bin_residual == bin_capacity {
        score += 5.0;
        if item_size >= bin_capacity / 2 {
            score -= 4.0; // big items fine in fresh bins
        }
    }

    // Early in the stream, be slightly conservative about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving exactly awkward space relative to next item.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.8 * crowding;

    // Time horizon: late in the stream, be more conservative (avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate: only attractive when existing fits are bad or none exist.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = (1.0 - fit_ratio) * 20.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 45.0 + 5.0 * (fitting_bins_count as f64).ln().max(0.0) };
        score += scarcity + bad_fit_penalty - 5.0 * progress;
        // New bin attractive if mean residual across open bins is very low (all nearly full).
        score -= (mean_residual / bin_capacity as f64) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: penalize large residuals more as stream progresses
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits smoothly (small post_residual), stronger early
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (fragmentation signal), smooth coupling
    score += 0.05 * (mean_residual - pr).max(0.0) * (1.0 + progress);

    // Lookahead: reward leaving space that matches next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.3 };
        score += fit_next * (gap / cap) * 15.0 * (0.5 + progress);
    }

    // Mild penalty on many open bins to encourage consolidation early on
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep it slightly penalized unless residual waste would be huge
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * norm_pr * (0.3 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
