    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + slack * 0.25;
        } else {
            score += 10.0; // this bin dies for the next item
            // harmonic match: next_item_size divides residual classes
            let nclass = next_item_size % 10;
            if nclass == 0 && post_residual >= next_item_size {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize spreading across many open bins when residuals are small
    let prog = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual {
        score += 5.0 * (1.0 - prog);
    } else {
        score -= 3.0 * prog;
    }

    // New-bin candidate handling: empty bin is a fallback, not a favorite
    if bin_residual == bin_capacity {
        // attractive only if no open bin fits or all fits are terrible
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 30.0 + mean_residual * 0.15;
        }
    }

    // Mild tie-breaking on tightness of fit
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Penalize residuals that cannot fit the smallest plausible next item (1..100 range).
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += 25.0;
    }

    // Reward using a bin whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open bins pressure: with many open bins, discourage opening another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but relax if current fit is terrible (large dead space).
        score += pressure * 3.0;
        if post_residual < 10 {
            score -= pressure * 2.5;
        }
    } else {
        // Using an existing bin slightly reduces pressure cost.
        score -= pressure * 0.3;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins),
    // keeping roomier bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect = diff < 0.5;
        if perfect {
            score -= 60.0; // next item fills this bin exactly
        } else {
            // penalize mismatch, scaled by how much the next item misses
            score += diff * 0.45;
            // if next item could still fit here with slack, mild bonus
            if next_item_size <= post_residual {
                score -= 8.0;
            } else {
                // next item won't fit here: dead-space penalty grows with tightness
                score += (post_residual as f64) * 0.25;
            }
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Prefer bins already below mean residual (consolidate waste).
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.35;
    } else {
        score += (resid - mean_residual) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening a new bin when good open bins exist, unless item is large relative to residual.
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral-ish, slightly penalized so open bins are preferred on decent fits
        score += 12.0;
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0; // large items better in a fresh bin
        }
        if post_residual > 0 && post_residual < 10 {
            score += 20.0; // avoid creating tiny useless fresh-bin residue patterns
        }
    }

    // Slight late-stream conservatism: keep bins tight as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: lookahead item exactly fills the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Lookahead item fits into post residual: strong bonus scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tight = (post_residual - next_item_size) as f64;
        score -= 25.0 - tight * 0.3;
    }
    // Lookahead cannot use the residual: penalize leaving large dead space.
    if next_item_size > post_residual && next_item_size > 0 {
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }
    // Many alternatives: mild penalty so we keep the best-fit bins for later.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 3.0;
    }

    // Compare against global mean residual: bins with less residual than mean
    // are "tighter" and better to fill.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Time horizon: early in the stream, be conservative about wasting bins;
    // late in the stream, prefer tight packing regardless of new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 * 0.2);

    // New-bin candidate handling: opening a new bin is expensive early,
    // acceptable late or when the item is huge relative to any residual.
    if bin_residual == bin_capacity {
        let open_cost = 95.0 - progress * 55.0;
        score += open_cost;
        // If item is large, a fresh bin is often the natural home.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If no open bin can fit, new bin is effectively forced (handled by
        // caller, but keep score sane).
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference to fill bins with smaller current residual first.
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild quadratic penalty on wasted space; later: stronger cubic push
    // toward tight fits as the stream matures.
    let poly = pr_norm * pr_norm * (0.5 + 1.5 * progress) + pr_norm * pr_norm * pr_norm * (2.0 * progress);
    score += poly * cap;

    // Smooth interaction: tight fits (small post_residual) are rewarded more
    // as the stream progresses, via a saturating exponential term.
    let tightness = (-pr_norm * 4.0).exp();
    score -= tightness * (1.0 + progress) * 8.0;

    // Penalize bins that leave residual close to the mean residual (redundant space),
    // with smooth gaussian-like coupling.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (4.0 + 4.0 * progress) * cap;

    // Lookahead coupling: reward leaving space compatible with next item,
    // smoothly via a gaussian on the difference.
    if next_item_size > 0 {
        let diff = (pr as f64 - next_item_size as f64) / cap;
        score -= (-diff * diff * 12.0).exp() * (3.0 + 5.0 * progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across too many bins early on.
    score += open_bins_count as f64 * (0.5 - 0.3 * progress);

    // New-bin candidate: penalize opening a new bin unless residual would be
    // large and stream is early; smooth interaction rather than hard rule.
    if bin_residual == bin_capacity {
        score += (2.0 + 20.0 * progress) + pr_norm * (5.0 - 5.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into bands of 10
    let band = post_residual / 10;
    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Quasi-perfect fits (tiny leftovers are dead space)
    if post_residual <= 2 {
        score -= 200.0;
    }

    // Penalize residuals in "awkward" harmonic classes (hard to fill later)
    match band {
        0 => score += 15.0,          // 1..9 dead space
        1 => score -= 5.0,           // 10..19 fits small items
        2 => score -= 10.0,          // 20..29 useful
        3 => score -= 8.0,
        4 => score -= 12.0,          // 40..49 half-bin class
        5 => score -= 6.0,
        6 => score -= 9.0,
        7 => score -= 4.0,
        _ => {}                       // large residual: neutral
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can host the next item too
            let slack = post_residual - next_item_size;
            score -= 30.0 + (slack as f64).min(40.0) * 0.5;
            // Harmonic match: next item divides post residual nicely
            if post_residual % next_item_size.max(1) == 0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; mildly penalize leaving small gap
            score += 10.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits
        score += (fitting_bins_count as f64).ln() * 5.0;
    }

    // New-bin candidate handling: only open a new bin if all fits are bad
    if bin_residual == bin_capacity {
        // Base cost of opening a bin
        score += 60.0;
        // If no open bin fits, the new-bin call is the only option
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
        // Many open bins: discourage opening more
        score += (open_bins_count as f64) * 3.0;
    }

    // Mean residual context: if open bins are already tight, reward using them
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (post_residual < 10)
    // are heavily penalized, since nothing can ever fill them.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else {
        // Reward tight fits: perfect fill gets a big discount.
        if post_residual == 0 {
            score -= 40.0;
        }
        // Smooth reward proportional to fill ratio.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when existing fits are poor (large residual waste)
        // or no bin fits well. Base cost for opening a new bin.
        score += 12.0;
        // If current item is large, a fresh bin is attractive (no fragmentation).
        score -= item_size as f64 * 0.05;
        // If lookahead item is small, a fresh bin preserves flexibility.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 6.0;
        }
    } else {
        // Reward reusing an existing bin (avoids bin proliferation).
        score -= 5.0;
        // Lookahead synergy: if next item fits in the resulting residual, discount.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 7.0;
        } else if next_item_size > 0 && post_residual > 0 {
            // Next item cannot fit: the remaining gap risks becoming dead space.
            score += 4.0;
        }
    }

    // Open-bins pressure: penalize spreading across many bins mildly,
    // but when few bins fit the item, favor this bin strongly (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer the bin whose residual is closest to item
        // (minimal waste) — already captured, but add tie-break via mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 2.0;
        }
    }

    // Late in the stream, consolidate: slightly favor reusing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward if next item still fits after placement
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
    }
    // Penalize residual that cannot host the next item (dead space risk)
    else if next_item_size > 0 {
        score += 5.0;
    }

    // Reward tight fits relative to mean residual of open bins
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (post_residual as f64) <= mean_residual;
        if good_fit_exists || (next_item_size > 0 && post_residual != next_item_size) {
            score += 40.0;
        } else {
            score += 5.0;
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize residual relative to mean residual across open bins:
    // leaving more than average slack wastes shared capacity.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item can use the post-residual exactly
    // or nearly, reward this placement; otherwise penalize hoarding space.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 5.0 {
            score -= 20.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // dead space for next item: penalize proportionally
            score += 0.3 * (post_residual as f64 - nr).abs();
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling
    // existing bins); late in the stream, prioritize perfect packing.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * t * (1.0 - fill);

    // Many open bins: discourage spreading, favor bins already below mean.
    if open_bins_count > 4 && (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when nothing fits well or item is huge.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || item_size as f64 / bin_capacity as f64 > 0.8
            || (mean_residual < item_size as f64 && fitting_bins_count <= 1);
        if desperate {
            score -= 15.0;
        } else {
            score += 40.0;
        }
    }

    // Small bonus for exact-fit style placements.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: penalize large residuals more as stream progresses.
    let norm_pr = pr / cap;
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: penalize leaving a residual that barely fails to fit the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni > pr {
            let gap = (ni - pr) / cap;
            score += 10.0 * gap;
        } else {
            // Reward leaving exactly enough room for the next item.
            let slack = (pr - ni) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only if open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let frag = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score = cap - 30.0 * frag * frag - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score += 40.0; // don't open new bins when a fitting bin is a last chance
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain residue classes.
    // Residuals that cannot hold any plausible small item (<= 10) are pure waste.
    let dead = if post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 45.0;

    // Classify post_residual by integer division into capacity-fraction buckets.
    // Buckets that leave a "harmonically useful" remainder (e.g. 25, 33, 50) are better.
    let bucket = post_residual / 10;
    let bucket_penalty = match bucket {
        0 => 60.0,               // 0..9: dead space
        1 => 12.0,               // 10..19: can fit small item
        2 => 8.0,                // 20..29
        3 => 4.0,                // 30..39
        4 => 2.0,                // 40..49
        5 => 0.0,                // 50..59: half-full, flexible
        6 => 1.0,
        7 => 2.0,
        8 => 3.0,
        _ => 0.0,                // near-empty bin
    };
    score += bucket_penalty;

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize leftover proportionally
            score += 10.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only prefer it if current residual is dead space
    // or item is huge relative to residual.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 55.0 + 30.0 * (1.0 - fill_ratio);
        if post_residual < 10 {
            score -= 70.0; // opening new bin beats leaving dead space
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression pressure: later in stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer bins tighter than average (good fits).
    score += 8.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }

    // Penalize small unusable gaps more aggressively (non-linear).
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        // New bin candidate: only attractive if existing bins fit poorly.
        score += 25.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        score -= open_bins_count as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mean-residual coupling: bins far below mean residual are less filled;
    // prefer bins with residual near/below the mean.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Late-stream consolidation: as the stream progresses, avoid leaving
    // many partially filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), but not zero-waste obsession.
    score = 0.8 * post_residual as f64 + 0.2 * (post_residual as f64 / cap);

    // 2-step lookahead: reward bins whose leftover matches the next item exactly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post_residual as f64 - nx).abs();
        if post_residual as u32 >= next_item_size {
            // Next item fits here afterwards: strong reward scaled by closeness.
            score -= 30.0 * (1.0 - gap / cap);
        } else {
            // Leftover too small for next item: penalize dead space.
            score += 10.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Compare against mean residual of open bins: prefer filling below-average bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong penalty for opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in stream: encourage consolidating into few bins.
    let open_f = open_bins_count as f64;
    score += 0.1 * open_f * (1.0 - progress);

    // Mild bonus for larger item fits (harder to place later).
    score -= 0.05 * item_size as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0 + (5 - post_residual) as f64 * 8.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else {
        // Penalize dead space that no realistic item can fill.
        let dead = (post_residual as f64 - 10.0).max(0.0);
        score += 0.6 * dead * dead / bin_capacity as f64;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.3 * over;
        }
    } else {
        // Last item: reward filling as much as possible.
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > mean_residual * 0.5 && fitting_bins_count > 0;
        let crowded = open_bins_count as f64 > 4.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        if poor_fit || crowded {
            score -= 20.0;
        } else {
            // Prefer reusing existing bins early / with good fits.
            score += 40.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Slight preference for bins with lower residual relative to mean (tighter bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild time decay: later in stream, be more aggressive about consolidating.
    score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer tight fits, non-linearly scaled by stream progress
    let mut score = pr * (1.0 + 0.8 * t * t);

    // Quadratic penalty on large post-residuals (dead space), stronger later in stream
    score += 20.0 * prn * prn * (0.5 + t);

    // Reward exact/near-perfect fills
    if prn < 0.05 {
        score -= 30.0 * (1.0 - prn * 20.0);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space that fits the next item, penalize otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (nx / cap);
        } else {
            score += 6.0 * ((nx - pr) / cap);
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins
    score += 0.5 * (mean_residual - pr);

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * prn;

    // New-bin candidate: penalize slightly unless current fit is terrible
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 15.0 - 10.0 * prn.min(1.0) * (fitting_bins_count as f64).min(3.0) * 0.0;
        score += 15.0;
        // Allow opening a new bin when all fits would be very loose
        score -= 20.0 * prn.max(0.0).min(1.0) * (pr / cap) * 0.0;
        if fitting_bins_count >= 1 && prn > 0.6 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: quantize post_residual into classes.
    // Residuals that are "usable" (small, or large enough for typical items) are favored.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes
    match class {
        0 => score -= 25.0,          // residual < 10: near-perfect dead space, great
        1 => score -= 10.0,          // 10..19: usable for small items
        2 | 3 => score += 5.0,       // 20..39: awkward middle zone
        4 | 5 => score -= 8.0,       // 40..59: good reusable space
        6 | 7 => score += 3.0,       // 60..79: large but wasteful for now
        _ => score += 10.0,          // >= 80: bin mostly empty, poor packing
    }

    // Modulo coupling: residuals congruent to common item sizes are more reusable.
    let m = pr % 20;
    if m == 0 {
        score -= 6.0;
    } else if m <= 10 {
        score -= 2.0 * (10 - m) as f64 / 10.0;
    } else {
        score += 1.5 * (m - 10) as f64 / 10.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let next_fit = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 2.0 * ((next_item_size - pr) as f64 / 20.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless all fits are bad.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let pressure = open_bins_count as f64;
        // Base cost of a fresh bin: high, so we only open when necessary.
        score += 55.0;
        // But if the mean residual across open bins is large (fragmented),
        // a fresh bin becomes more attractive.
        score -= (mean_residual / 10.0).min(20.0);
        // Later in the stream, prefer consolidating (fewer bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins: discourage opening yet another.
        score += 0.5 * pressure.sqrt();
    }

    // Mild preference to fill already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_ratio;

    // Penalize bins far from mean residual (keep residual profile balanced).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: gaps too small for the smallest plausible item are unusable
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Tightness reward: fractional residual relative to capacity
    score -= 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: bonus if post_residual exactly fits the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Pressure against opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
    }

    // Mild preference for fuller bins relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late-stream tightening: prefer closing bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact fits for the next item too.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit (next item exactly fills post_residual)
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward tightness of the chain
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot follow here: penalize proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // general tightness bonus for small lookahead gap
        score -= 20.0 / (1.0 + diff);
    }

    // Penalize leaving dead space that nothing typical can use
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual > 40 {
        score += 5.0;  // large leftover, keep options open elsewhere
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins already tighter than average
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Slight preference to fill older bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // New-bin candidate: make empty bin moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact or near-exact fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Lookahead: penalize leaving a residual that is unusable by the next item,
    // reward residuals that the next item can fill.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // residual too small for next item: dead-space penalty scaled by how close to useless
            let dead = post_residual as f64 / next_item_size as f64;
            score += 10.0 * (1.0 - dead);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize picking a bin among many fitting bins poorly (encourage best-fit discrimination).
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: opening a new bin is attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it slightly worse than a good existing fit.
        score = bin_capacity as f64 - 15.0;
        // If several bins can already fit the item, prefer reusing one.
        if fitting_bins_count > 0 {
            score += 20.0 + 3.0 * fitting_bins_count as f64;
        }
        // If only one fitting bin (last chance), opening a new bin is worse.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // If mean residual across open bins is large, reuse is cheap.
        if mean_residual > item_size as f64 + 15.0 {
            score += 15.0;
        }
        // Early in stream, opening bins is fine (build a pool); late in stream, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    } else {
        // Existing bin: slight penalty if its residual is far below mean (fragmented bin).
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev.abs();
        // Late in the stream, prefer filling bins with small residuals (consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for too many open bins: encourage reuse.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base cost: dead space after placement, mildly convex (waste grows superlinearly).
    let mut score = pr * (1.0 + 0.008 * pr / cap);

    // Smooth polynomial coupling of waste with stream progress:
    // later in the stream, tight fits matter more; early on, waste is more tolerable.
    let tight = 1.0 - pr / cap; // fit quality in [0,1]
    score -= 12.0 * tight * tight * (1.0 + progress);

    // Reward bins whose residual stays useful for the lookahead item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = ((pr - n) / cap).abs();
        score -= 6.0 * (-8.0 * gap * gap).exp();
    }

    // Penalize bins much emptier than average (fragmentation avoidance), smooth in mean_residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bin: strongly favor it unless the fit is terrible (smooth interaction).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let bad_fit = pr / cap;
        score -= 15.0 * (1.0 - bad_fit) * (1.0 - bad_fit);
    }

    // New-bin candidate (pristine bin): penalize so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it divides the capacity
    let pr = post_residual;
    if pr > 0 {
        let class = bin_capacity / pr; // integer division class
        // Residuals that exactly divide capacity (harmonic classes like 50, 33, 25, 20) are reusable
        if bin_capacity % pr == 0 {
            score -= 12.0 + 3.0 * class as f64;
        } else {
            // penalize dead space that cannot be filled by typical items
            let dead = (pr as f64) * (1.0 - (class as f64) / (class as f64 + 1.0));
            score += dead * 0.5;
        }
    } else {
        // perfect fill: huge reward
        score -= 200.0;
    }

    // Tight fit reward: post_residual small relative to item size
    let tightness = (post_residual as f64) / (item_size as f64 + 1.0);
    score += tightness * 10.0;

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            let nxt = next_item_size as f64;
            // harmonic match: does next item divide the post residual?
            if pr % next_item_size == 0 {
                score -= 25.0 + 10.0 * (pr / next_item_size) as f64;
            } else {
                score += (pr as f64 - nxt) * 0.3;
            }
        } else {
            // next item won't fit here: slight penalty for leaving large gap
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make it moderately attractive only when
    // the item would leave a very awkward residual in existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, decreasing late in stream
        score = 55.0 - 20.0 * progress;
        if item_size >= bin_capacity / 2 {
            score -= 30.0; // big items start fresh bins happily
        }
    } else {
        // reward keeping bins balanced: prefer bins with residual near mean
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
        // when many bins are open, prefer consolidating into fuller bins
        score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100
    // interface, assume min item ~10) are pure waste. Penalize small unusable gaps hard.
    let min_item = 10u32;
    if post_residual < min_item {
        // Dead space: the bin is effectively closed. Reward this strongly
        // (we filled it completely) but only if it wasn't wasteful (item fits well).
        score -= 60.0;
    } else if post_residual < min_item * 2 {
        // Semi-dead zone: only tiny items can use this space.
        score += 12.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving a residual that exactly fits nothing likely to come:
    // compare post_residual against next_item_size lookahead (k=2).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect lookahead fit: strongly favor this bin.
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item could still use this bin: mild bonus.
            score -= 8.0;
        } else {
            // Next item cannot fit here: mild penalty for bin closure pressure.
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage proliferating bins when many are open,
    // but only mildly so tight fits still win.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (i.e., this bin is more filled than average) to balance bin loads.
    let resid_diff = mean_residual - post_residual as f64;
    score += 0.3 * resid_diff;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin explosion).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual by definition.
    // Make it unattractive unless no open bin gives a good fit. Approximate:
    // if this is the new bin and the item would leave lots of space while other
    // bins exist, penalize.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 20.0;
        // But if the item is large (most of the bin used), a fresh bin is fine.
        if fill_ratio > 0.7 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit: item leaves exactly the next item's size.
        if diff == 0.0 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward proportional to tightness.
            score -= 20.0 * (1.0 - diff / 100.0);
        } else {
            // Next item won't fit in this bin's residual: mild penalty scaled by gap.
            score += 0.15 * diff;
        }
    }

    // Penalize dead space: residuals too small for the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 5.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 3.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in the stream, allow spreading into new bins to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized when many bins already open.
        score -= 12.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
    } else {
        // Late in the stream, prefer filling existing bins.
        score -= 8.0 * progress;
    }

    // Slight preference for bins with larger residual when item is large.
    score += 0.05 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - residual_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space relative to smallest plausible future item (1..100 interface)
        let dead = post_residual as f64;
        score += 0.3 * dead;
        // If no future item can plausibly fit, dead space is worse
        if (next_item_size as f64) > dead {
            score += 0.4 * dead;
        }
    }

    // Lookahead: reward leaving exactly enough room for the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening new bins is cheap early / when open bins have large residuals
        score = 60.0 + 80.0 * pressure - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many bins when residuals are large
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let tight = 1.0 - norm_pr;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses.
    let tight_poly = tight * tight * (1.0 + 2.0 * progress);
    score -= 6.0 * tight_poly * cap;

    // Penalize mid-range dead space (quadratic hump around half-full residual).
    let dead = norm_pr * (1.0 - norm_pr);
    score += 4.0 * dead * cap * (0.5 + progress);

    // Lookahead: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (norm_pr - nx).abs();
        score -= 3.0 * (1.0 - gap) * (1.0 - gap) * cap * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward to use it.
    if fitting_bins_count == 1 {
        score -= 8.0 * cap * (1.0 + progress);
    }

    // Slight penalty for bin proliferation, scaled by item size.
    score += (open_bins_count as f64).ln() * norm_item * cap * 0.5;

    // Deviation from mean residual: smooth quadratic alignment term.
    score += 0.5 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate: keep its score near baseline, mildly worse over time
    // unless residuals elsewhere are large.
    if bin_residual == bin_capacity {
        score = cap + 2.0 * cap * progress - 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: small dead space classes are good
        let pr = post_residual;
        if pr <= 10 {
            score -= 80.0;
        } else if pr <= 20 {
            score -= 30.0;
        } else if pr <= 40 {
            score -= 10.0;
        } else {
            // large dead space: penalize extra
            score += (pr as f64 - 40.0) * 0.5;
        }

        // Lookahead: reward if next item fits exactly / well into post_residual
        if next_item_size > 0 && next_item_size <= pr {
            let next_post = pr - next_item_size;
            if next_post == 0 {
                score -= 200.0;
            } else if next_post <= 10 {
                score -= 60.0;
            } else {
                score -= next_post as f64 * 0.3;
            }
        } else if next_item_size > 0 {
            // next item cannot use this dead space: penalize proportionally
            score += (next_item_size - pr).min(30) as f64 * 0.4;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: must be beaten only by genuinely good fits
    if bin_residual == bin_capacity {
        score = 250.0 - mean_residual * 0.5 + open_bins_count as f64 * 2.0;
    }

    // Slight preference for filling bins as stream progresses (reduce open-bin sprawl)
    score += open_bins_count as f64 * 0.5;

    // Mild tie-break: prefer bins with residual close to mean (balance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
