pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual bucketed by capacity fractions
    let c = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;

    // Dead space penalty: residuals that are too small to be useful
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Residual classes via integer division thresholds
    if post_residual >= half {
        score -= 15.0; // half-full or less: very reusable
    } else if post_residual >= quarter {
        score -= 5.0;
    } else {
        score += 10.0; // small residual class: penalize
    }

    // Modular arithmetic on post_residual: common item sizes 10..80
    // Residuals divisible by 10 pair well with typical item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Residuals in awkward classes (mod 10 in 1..=3) are near-dead
    let m = post_residual % 10;
    if m >= 1 && m <= 3 {
        score += 12.0;
    }

    // Lookahead coupling: can the next item fit exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // chain a perfect fit
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 30.0;
            } else if gap < 20 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly, more so late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 + 25.0 * progress;
        // but if item is large and mean residual is tight, new bin is fine
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Tie-break with mean residual coupling
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to host the lookahead
    // item are "dead" for the next step -> heavy penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64;
    }

    // Dead-space band: residuals that can hold almost nothing useful
    // (very small leftovers) get an extra nonlinear penalty.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
