    score += (open_bins_count as f64) * 0.8 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a fresh bin only if the best existing
    // fit would leave a dead gap; otherwise make the empty bin unattractive.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9
            - 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        if next_item_size > 0 && post_residual < next_item_size {
