pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: penalize residual, non-linearly (quadratic waste).
    let mut score = pr * (1.0 + 0.5 * pr_norm);

    // Smooth polynomial coupling of post_residual with stream progress.
    let t = progress;
    let coupling = pr_norm * pr_norm * (t * t * (3.0 - 2.0 * t)) + pr_norm * t * (1.0 - t);
    score += 20.0 * coupling;

    // Perfect fit reward (smooth, no piecewise).
    let fit_quality = 1.0 - pr_norm;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Penalize bins that leave residual close to but below typical small item
    // (dead space), smoothly via distance to next_item_size.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 5.0 * (1.0 - (-diff / 10.0).exp());
