        } else if next_item_size <= post_residual {
            // Next item fits: residual after that chain matters.
            let chained = post_residual - next_item_size;
            score -= 5.0 + (chained as f64).min(15.0) * 0.3;
        } else {
            // Next item cannot use this residue: penalize proportionally
            // to how much space would be stranded.
            let stranded = (next_item_size - post_residual) as f64;
            score += stranded.min(30.0) * 0.25;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 8.0;
    }

    // New-bin candidate: empty bin. Prefer using existing bins unless the
    // current fit is very poor (large post_residual) and many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and
        // how badly the item fits elsewhere.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = cap * 0.85 - progress * 10.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 30.0; // nothing fits, must open
        }
        if open_bins_count as f64 > mean_residual.max(1.0) / 10.0 {
            new_bin_score += 5.0; // many open bins with slack: consolidate
        }
        score = score.max(new_bin_score);
        score = new_bin_score + (post_residual / 10) as f64 * 0.5;
    }

    // Slight tie-breaker: prefer bins whose residual is closest to the
    // global mean residual (keeps bin states homogeneous).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Pressure against spreading across many open bins: prefer filling existing bins
    // when the bin is relatively full compared to the mean residual.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 0.5 * fullness * (open_bins_count as f64).sqrt();

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.6
            + 0.3 * (mean_residual - post_residual as f64).max(0.0);
        score += pressure;
        // Opening a new bin preserves a large uniform gap; penalize moderately
        // unless the stream is nearly done.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Slight preference for keeping large residuals intact when many bins are open.
    if open_bins_count > 4 && post_residual > 50 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use
        let waste = post_residual as f64 - (post_residual.min(next_item_size - 1) as f64);
        score += 0.3 * waste;
    }

    // Tight fit reward relative to mean residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Compare against mean residual across open bins
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 55.0 - 0.3 * (item_size as f64);
    }

    // Late-stream preference for compacting into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize "dead space": residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins below the mean residual (consolidating space) when many bins are open.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.3 * (mean_residual - residual_f);
    } else {
        score += 0.2 * (residual_f - mean_residual);
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep options open);
    // late in the stream, fill existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let new_bin_bonus = 12.0 * (1.0 - progress) - 6.0 * progress;
        score += new_bin_bonus;
        // Don't open a new bin if a decent fit exists elsewhere.
        if post_residual as f64 > mean_residual * 0.5 {
            score += 10.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    let mut score = norm_pr * (1.0 + 0.5 * progress * progress);

    // smooth non-linear coupling: quadratic dead-space penalty modulated by progress
    score += 0.8 * norm_pr * norm_pr * (0.5 + progress);

    // reward tight fits via smooth inverse of post-residual
    score -= 0.6 * norm_item * (1.0 - norm_pr) * (1.0 - progress * 0.5);

    // lookahead coupling: penalize residuals that neither fit next item nor stay tiny
    if next > 0.0 {
        let gap = (pr - next_item_size as f64) / cap;
        score += 0.4 * (gap * gap) * (1.0 - progress);
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 0.3 * fits_next * norm_item * (1.0 - progress);
    }

    // last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - norm_pr * norm_pr);
    }

    // new-bin candidate: penalize mildly, less as stream progresses
    if bin_residual == bin_capacity {
        score += 0.5 + 0.3 * (1.0 - progress);
    }

    // mean-residual coupling
    score += 0.2 * (norm_pr - mean_residual / cap).abs();

    // slight preference for bins with more open competition
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: exact-fill classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 12.0; // decile residue: highly reusable
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        score += 3.0; // awkward residue
    }

    // Integer-division thresholds: tiny residuals are dead space.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    if pr >= 10 && pr < 20 {
        score += 8.0;
    }

    // Coupling with lookahead: reward residues that can host next item exactly or in harmonic class.
    if next_item_size > 0 {
        let nx = next_item_size;
        if pr >= nx {
            if pr % nx == 0 {
                score -= 20.0;
            } else if (pr - nx) % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 2.0;
            }
            if pr - nx < 10 {
                score += 15.0; // leaves dead space after next item
            }
        } else {
            score += 6.0; // residue too small for lookahead
        }
    }

    // Tightness: prefer bins where item fills a large fraction of residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor or many bins open.
    if bin_residual == bin_capacity {
        score += 45.0
            - 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0))
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Spread pressure: prefer bins with residual far from mean (balance across bins).
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Harmonic class of item size: items in coarse classes fit better into big-residue bins.
    let item_class = item_size / 20; // 0..4
    let resid_class = pr / 20;
    if item_class == resid_class && pr >= item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful for typical future items are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Unusable sliver: pure dead space.
            score += 60.0 + (10.0 - gap) * 4.0;
        } else if gap < 25.0 {
            // Marginal gap: only fits very small items; partially dead.
            score += 25.0 * (1.0 - (gap - 10.0) / 15.0);
        }
    } else {
        // Perfect fill: strong reward.
        score -= 80.0;
    }

    // Reward tight fits (small post_residual relative to residual).
    if bin_residual > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 30.0 * tightness;
    }

    // If this is the last bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere (large post_residual in existing bins).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; scales mildly with open bins.
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 20.0 + 8.0 * pressure;

        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
        // Late in the stream, avoid spawning bins for tiny leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 30 && progress > 0.8 {
            score += 30.0;
        }
    }

    // Prefer bins whose residual is close to the current item (waste nothing).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.4;

    // Lookahead: if the post_residual would fit the next item exactly, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins with large residuals (consolidate).
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 10.0; // avoid the emptiest outliers when bins are plentiful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual).
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Aggressive 2-step lookahead: perfect match with next item is a jackpot.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // The next item exactly fills this bin afterwards -> excellent.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also go here; mild bonus proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use -> penalize.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    } else {
        // Last item: just minimize post_residual (already baseline).
    }

    // Compare against mean residual across open bins: placing into a bin whose
    // residual is far above the mean tends to leave many fragmented bins.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (res_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin (penalize new-bin option implicitly by bonus here).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: make it unattractive unless the item is huge
    // relative to all open residuals (handled via base score being capacity).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * open_bins_count as f64;
    }

    // Slight late-stream tightening: as the stream progresses, prefer filling
    // existing bins ever more strongly.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual < 10 + item_size {
        // Dead space smaller than the smallest possible next item is unusable.
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the resulting post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += 8.0 * ((next_item_size - post_residual) as f64 / item_size.max(1) as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is wasteful while mean residual across open bins is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 0.15 * mean_residual + 20.0 * (1.0 - progress);
        // But allow new bins when open bins are nearly full on average.
        if mean_residual < 15.0 {
            score -= 40.0;
        }
        // If no open bin can even fit the item, the new bin must be attractive.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    } else {
        // Slight preference for filling existing bins as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // Prefer bins whose residual deviates favorably from the mean (larger residual
        // bins are more flexible; consume them rather than hoarding small residuals).
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with quadratic penalty for waste
    let mut score = pr + 40.0 * fit_norm * fit_norm * cap;

    // Tight fit reward: strongly reward near-full placements, amplified late in stream
    let tightness = 1.0 - fit_norm;
    score -= (1.0 + 3.0 * progress) * 60.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 25.0 * (1.0 - (pr - nx) / cap) * (1.0 + progress);
        } else {
            score += 15.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus if this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0 * (1.0 + progress);
    }

    // Penalize bins whose residual deviates badly from mean residual (fragmentation signal)
    let dev = (pr - mean_residual).abs();
    score += 5.0 * (dev / cap) * (dev / cap) * cap;

    // Mild penalty for spreading across too many open bins; encourage consolidation
    score += 3.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive early or when fit is terrible
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score -= 35.0 * early;
        score += 20.0 * fit_norm.max(0.0) * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo small divisors
    let class3 = post_residual % 3;
    let class5 = post_residual % 5;
    let class10 = post_residual % 10;

    // Reward post_residuals in "usable" harmonic classes (multiples of common item sizes)
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual % 10 == 0 {
        score -= 12.0; // residual aligns with decade-sized items
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        // penalize awkward residuals, worse for small non-aligned dead space
        score += (class3 as f64) * 1.5 + (class10 as f64) * 0.8;
    }

    // Integer division thresholds on post_residual
    if post_residual < 10 {
        score += 18.0; // unusable sliver
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Coupling with next item: reward residuals that can host the lookahead item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let nxt_post = post_residual - next_item_size;
            score -= 4.0 + (nxt_post % 10 == 0) as i32 as f64 * 8.0;
            score += (nxt_post < 10 && nxt_post > 0) as i32 as f64 * 7.0;
        } else {
            score += 5.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when existing fits are poor (high post_residual spread) or mean residual is high
        if post_residual as f64 > 25.0 || mean_residual > 45.0 {
            score -= 15.0 + 10.0 * (1.0 - progress);
        } else {
            score += 10.0;
        }
    }

    // Mild pressure against proliferating bins when many are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item (<= 12) are "dead" and heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - 4.0 * post_residual as f64;
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // If this bin can also fit the next item after placement, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if placing here wastes a gap the next item could have used.
    if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins; few open bins -> allow opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / 10.0).min(3.0) * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier bin worth closing out; if far above, keep it flexible.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // New-bin candidate baseline: an empty bin should only win when existing
    // fits are poor (large post_residual) or no real alternatives exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual, but with diminishing returns on tiny slivers.
    score = (post_residual as f64).powf(0.85);

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chained fit: strong reward.
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves another residual; reward proportional to tightness.
            let next_post = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.2 * next_post;
        } else {
            // Next item will NOT fit here: penalize leaving residual that wastes potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.3 * overflow;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter; prefer them.
    score += 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating dead space that no plausible item (>=1) can use well:
    // tiny post_residuals are fine (near-full), large post_residuals are fine (flexible),
    // mid-range residuals just above typical small items are worst.
    let pr = post_residual as f64;
    let dead_zone = ((pr - 25.0).powi(2)) / 400.0;
    score += dead_zone * 0.4;

    // New-bin candidate handling: empty bin gets a neutral-to-slightly-high baseline.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 55.0;
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += 30.0 * progress;
        // If many open bins already exist, opening another is less harmful early on.
        new_bin_score -= 2.0 * open_bins_count as f64;
        // If the next item is large and won't fit anywhere typical, a fresh bin is safer.
        if next_item_size > 60 {
            new_bin_score -= 12.0;
        }
        // If no open bin fits (only new-bin call), the comparison decides anyway;
        // make it slightly attractive when mean residual is small.
        new_bin_score -= 0.2 * mean_residual;
        return new_bin_score;
    }

    // Mild late-stream tightening: squeeze items into existing bins as stream ends.
    score += 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits superlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight * tight;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead (k=2): strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 18.0 + 20.0 * snug;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that cannot host the next item, scaled by gap size.
        score += 6.0 + 0.08 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is justified when existing residuals
    // are already small (mean_residual low) or few bins fit the item.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64);
        // Early in the stream, prefer consolidation; later, allow spreading.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = 0.5 + 0.5 * t;
        score = 60.0 - 45.0 * pressure - 25.0 * scarcity * openness;
        if fitting_bins_count == 1 {
            score += 50.0; // never open when a last-chance bin exists
        }
    }

    // Mild consolidation bias: prefer bins below mean residual (filling emptier bins
    // balances the portfolio of open bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // Penalize fragmenting many-open-bin regimes slightly to curb bin proliferation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let mean = mean_residual;
    let nxt = next_item_size as f64;

    // Base: quadratic in normalized post-residual (favor tight fits)
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 20.0;

    // Smooth non-linear coupling with stream progress: later in stream,
    // tolerate larger residuals less (dead space becomes costlier)
    let progress_coupling = (norm_pr * norm_pr) * (progress * progress) * 40.0;
    score += progress_coupling;

    // Reward bins whose residual is close to mean residual (harmonization),
    // smooth via squared difference
    score += ((pr - mean) * (pr - mean)) / (cap * cap) * 15.0;

    // Lookahead: if next item fits in post-residual, reward this bin
    if nxt > 0.0 {
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= (1.0 - fits_next) * (1.0 - fits_next) * 10.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * (1.0 - progress);
    } else {
        // Mild penalty for crowding many-bin choices
        score += fit * 0.5;
    }

    // New-bin candidate: penalize gently so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual: reward residuals that are "usable"
    // for common item sizes (multiples of 10 or small complements).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0; // round residual = highly reusable
        }
        if pr >= 10 && pr <= 30 {
            score -= 3.0; // small residual, still placeable by small items
        }
        if pr > 30 && pr < 50 {
            score += 2.0; // awkward middle dead-space zone
        }
        // Integer division thresholds: classify residual into usable tiers
        let tier = pr / 20; // 0..5
        score -= tier as f64 * 2.5;
    } else {
        // zero post residual handled above; nothing more
    }

    // Penalize leaving residual smaller than the minimum plausible item (1..=100 unknown,
    // but be conservative: residual < 10 is nearly dead space).
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0;
        // Extra harmonic reward if next item exactly consumes the residual class
        if pr % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to mismatch.
        let gap = (next_item_size - pr) as f64;
        score += gap * 0.15;
    }

    // Prefer filling bins with large residual when many bins are open (bin consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (1.0 - progress);
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: make it moderately attractive only when it beats bad fits.
    if bin_residual == bin_capacity {
        score += 12.0; // baseline penalty so existing good fits win
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits elsewhere: must open new bin
        }
        if pr == bin_capacity && next_item_size > 0 && next_item_size >= 50 {
            score -= 20.0; // large lookahead item: fresh bin is fine
        }
    }

    // Modulo coupling on item_size vs residual: reward complementary pairs.
    if (bin_residual - item_size.min(bin_residual)) % 5 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful are heavily penalized. Define a "dead zone" threshold.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: small post residual relative to item size
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 20.0;
    }

    // If the next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use this residual: mild penalty scaled by dead-ness
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Open bins pressure: discourage spreading across many bins when fit is loose
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.8 * progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e. fuller bins) to concentrate fill.
    if (bin_residual as f64) < mean_residual {
        score -= 12.0;
    } else {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when
    // no open bin offers a reasonable fit. Penalize opening a new bin,
    // especially early in the stream or when open bins exist.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        score += 40.0 + open_pressure * 15.0;
        // Late in stream, opening new bins is more acceptable
        score -= progress * 20.0;
    }

    // Mild overall preference for fuller bins
    score += (bin_capacity - bin_residual) as f64 * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tightness toward the next item (aggressive lookahead).
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Penalize if next item cannot fit in the post residual (dead space for next step).
        if post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else if post_residual == next_item_size {
            score -= 25.0; // exact chain fit
        }
    } else {
        // Last item: minimize final residual.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize bins whose residual is far above the mean (hoarding space), reward below-mean use.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly so it is chosen only when fits are poor,
    // but reward it when few fitting bins exist and residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        } else if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
            score -= 20.0; // poor chain fits elsewhere -> fresh bin is attractive
        }
    }

    // Small residual left behind is dead space: penalize very small nonzero leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference late in the stream to consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.8 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits the post-residual (chain placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // Penalize leaving a residual too small for typical next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += post_residual as f64 * 1.5;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit is poor and many open bins have small residuals.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 40.0 * scarcity;
        if poor_fit {
            score -= 30.0;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins with residual below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let base = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = pr_norm;
    let poly = p * p * (3.0 - 2.0 * p); // smoothstep-shaped dead-space penalty
    let coupling = poly * (0.5 + progress);

    // Reward tight fits (small post_residual), especially late in stream
    let tightness = (1.0 - pr_norm).powi(3);
    let mut score = base + 20.0 * coupling - 15.0 * tightness * (0.3 + 0.7 * progress);

    // Lookahead: penalize post_residual that cannot host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins below mean residual (more crowded bins absorb waste)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: keep it attractive early, discourage late
    if bin_residual == bin_capacity {
        score += 6.0 * progress - 4.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild penalty for many open bins
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: perfect fills are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else {
        // Modulo classes on residual space (harmonic granularity classes)
        let class = pr % 10;
        match class {
            0 => score -= 12.0,          // clean decade residual, highly reusable
            1 | 9 => score += 6.0,       // awkward off-by-one residuals
            2 | 8 => score += 2.0,
            5 => score -= 3.0,           // half-class residuals pair well
            _ => {}
        }
        // Integer-division thresholds: quarter bins
        let quarter = bin_capacity / 4;
        if pr < quarter {
            score += 10.0; // dead space risk
        } else if pr <= bin_capacity / 2 {
            score -= 4.0;  // sweet spot
        }
    }

    // Lookahead coupling: can next item exactly fill this bin?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 8.0 * (next_item_size as f64 / pr.max(1.0));
        } else {
            score += 5.0; // next item cannot use this residual
        }
        // Harmonic pairing: next item leaves a decade residual
        if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.5 };
        score = cap * 0.55 + 20.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 80.0; // forced open
        }
        if fitting_bins_count == 1 {
            score += 25.0; // keep the last-chance bin viable
        }
    }

    // Stream-phase drift: pack tighter early, consolidate late.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * phase * (mean_residual / cap);

    // Mild tie-break toward fewer open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

