    score += 0.2 * (mean_residual - bin_residual as f64);

    // Mild progression term: later in stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

