}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted space.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than average.
    let resid = post_residual as f64;
    score += 0.3 * (resid - mean_residual).max(-50.0);

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it unattractive unless the fit here is terrible.
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual > 20 {
            score += (post_residual - 20) as f64;
        }
    }

    // Late in the stream, consolidate: prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed — late items should close bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: smaller post_residual is already favored by base score,
    // but reward near-perfect fits much harder.
    let tight_fit = (bin_residual - item_size) as f64;
    score -= 12.0 * (-tight_fit / 15.0).exp();

    // Lookahead: strongly reward bins whose post_residual can host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-slack / 20.0).exp();
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 + 4.0 * (-gap / 25.0).exp();
        }
    }

    // Dead space penalty: residuals too small for the minimum item size are waste.
    if post_residual < 1 {
        score += 50.0;
    } else {
        let min_item = 1.0f64;
        let unusable = (min_item - post_residual as f64).max(0.0);
        score += 5.0 * unusable;
        // Residuals below typical small item sizes are semi-dead; scale with progress.
        if post_residual < 10 {
            score += (1.0 + progress) * (10 - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
        if post_residual < 5 {
            score += 10.0; // still avoid wrecking the bin for crumbs
        }
    }

    // New-bin candidate handling: empty bin should only win when the item is large
    // relative to capacity or open bins are congested / mean residual is poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin.
        score += 20.0 + 10.0 * progress;
        // Large items deserve fresh bins (few good fits exist anyway).
        score -= 30.0 * fill_ratio * fill_ratio;
        // If many bins fit the item, opening new is wasteful.
        score += 3.0 * fitting_bins_count as f64;
        // If existing mean residual barely fits the item, a fresh bin is attractive.
        let mean_margin = mean_residual - item_size as f64;
        if mean_margin < 10.0 {
            score -= 12.0 * (1.0 - mean_margin.max(0.0) / 10.0);
        }
        // Early in the stream, keep bin count low; late, spread freely.
        score -= 5.0 * (1.0 - progress);
    } else {
        // Reusing an open bin: mild reward scaled by how many alternatives exist.
        score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
        // Prefer bins with residual close to mean (keeps bin population balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * dev / (1.0 + dev);
    }

    // Global congestion: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 {
        let consolidation = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
        score += 2.0 * consolidation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fills (low post_residual) with a strong cubic pressure.
    // Later: relax slightly but add curvature that punishes mid-range dead space.
    let poly = norm_post * norm_post * (1.0 - progress) * 90.0
             + norm_post * norm_post * norm_post * (60.0 + 40.0 * progress);
    score += poly;

    // Smooth interaction: dead space becomes costlier as mean residual grows
    // (bins are collectively fragmented), a quadratic coupling.
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    score += norm_post * mean_norm * 25.0 + norm_post * mean_norm * mean_norm * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it
    // rather than opening a new bin, scaled smoothly by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * (1.0 - norm_post) * (1.0 - norm_post);
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily
    // (perfect chaining); if it doesn't fit, mildly penalize leaving awkward gaps.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 35.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 * (nxt / cap) * (1.0 - norm_post);
        }
    }

    // New-bin candidate: opening a fresh bin should only win when all open bins
    // fit poorly. Penalize the empty-bin candidate with a smooth function of
    // how much residual would be wasted elsewhere.
    if bin_residual == bin_capacity {
        let waste_pressure = if fitting_bins_count == 0 {
            -1000.0 // no open bin fits: must open new bin
        } else {
            55.0 + 45.0 * mean_norm + 20.0 * progress
        };
        score += waste_pressure;
    }

    // Mild open-bins pressure: discourage scattering across many bins early.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions.
    let q = post_residual * 4 / bin_capacity; // 0..3 harmonic class
    let class_penalty = match q {
        0 => -60.0, // near-perfect fill
        1 => -10.0, // leaves a quarter — often reusable by mid items
        2 => 5.0,   // half-empty: mediocre
        _ => 15.0,  // mostly empty: wasteful placement
    };
    score += class_penalty;

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space relative to lookahead: penalize modulo mismatch
            let m = post_residual % next_item_size.max(1);
            score += (m as f64) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 40.0
            + (mean_residual - item_size as f64).max(0.0) * 0.5
            - (open_bins_count as f64) * 2.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Progress-scaled tie-break: slight preference for early consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Integer-division threshold: reward leaving residuals in common item bands.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 12.0;
    } else if post_residual > 80 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1, but practically gaps < ~10 are near-dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward filling bins that are already fairly full (tight packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize creating a gap that just barely fails to fit the known next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, mild penalty
    // for leaving large residuals in mostly-empty bins (favor new-bin when fresh).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (1.0 - fill_ratio);
    score -= 10.0 * progress * fill_ratio;

    // Coupling with mean residual: if this bin's residual is far below the mean,
    // it is a good consolidation target.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // New-bin candidate baseline: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its residual equals capacity; make it
        // competitive but not dominant unless open bins would waste space badly.
        score = 55.0 + 0.5 * open_bins_count as f64 - 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but don't over-reward tiny residuals
    score = 0.8 * score;

    // 2-step lookahead: strongly reward exact match of post_residual to next item size
    if next_item_size > 0 {
        let match_val = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - match_val).abs();
        if diff < 0.5 {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if pr >= match_val {
            // next item fits here too -> good chaining
            score -= 12.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize proportional to wasted potential
            score += 6.0 * (diff / bin_capacity as f64);
        }
    }

    // Dead-space penalty: residuals below typical small item size are likely wasted
    if post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 8.0;
        // but if mean residual across open bins is low (all bins tight), opening is fine
        score -= 0.05 * mean_residual;
    }

    // Prefer filling bins with larger residual when many bins are open (bin consolidation)
    if open_bins_count > 3 {
        score += 0.3 * (bin_residual as f64 - mean_residual).abs().signum()
            * (bin_residual as f64 - mean_residual);
    }

    // Slight progression-aware tightening: later in stream, waste hurts more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed residual matters less.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item can still fit in the post residual,
    // keeping that capacity is valuable -> penalize using this bin loosely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score += 0.35 * next_item_size as f64;
        } else {
            // Bin becomes useless for next item; using it now is fine, reward.
            score -= 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: just minimize waste, slight bonus for any fit.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor placing here to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // When many bins fit the item, prefer the one with least residual (already
    // captured), but add mild pressure toward consolidation.
    score += 0.05 * fitting_bins_count as f64;

    // Global state: if mean residual is high, encourage filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.10 * mean_residual * (1.0 - progress);

    // New-bin candidate: make it unattractive unless nothing reasonable fits.
    if bin_residual == bin_capacity {
        score += 60.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        }
    }

    // Mild noise-free tie-break toward later-opened bins (larger residual spread).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: tightness of fit weighted by stream progress.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    let poly = tightness * tightness * (1.0 + 2.0 * progress);
    score -= 25.0 * poly * fill_ratio;

    // Penalize dead space that is too small to be useful later (smooth ramp).
    let dead = post_residual as f64;
    let dead_norm = dead / bin_capacity as f64;
    score += 40.0 * dead_norm * dead_norm * (1.0 - dead_norm);

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - slack) * (0.5 + progress);
    } else if next_item_size > 0 {
        // Penalize wasting space the next item could have used.
        score += 10.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early on
    // and when many bins are already open but mean residual is high.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        let mean_waste = mean_residual / bin_capacity as f64;
        score += 55.0 + 10.0 * open_pressure + 30.0 * mean_waste * (1.0 - progress);
    }

    // Slight preference for bins with residuals near the item size (smooth term).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // classes (multiples of small divisors) are more valuable to keep tidy.
    let pr = post_residual;
    let class_score: f64 = if pr == 0 {
        0.0
    } else if pr % 10 == 0 {
        -5.0 // clean class, likely reusable by future items
    } else if pr % 5 == 0 {
        -2.0
    } else if pr % 2 == 0 {
        1.0
    } else {
        3.0 // odd residue: awkward dead space
    };
    score += class_score;

    // Lookahead coupling: reward when leftover can host the next item exactly
    // or nearly (harmonic match between post_residual and next_item_size).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 15.0;
            } else if slack <= 10 {
                score -= 8.0;
            } else {
                score += slack as f64 * 0.1;
            }
        } else {
            // next item cannot fit here; leftover becomes stranded -> penalize
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin if existing fit leaves very fragmented residue
        if pr > 0 && pr < 5 && bin_residual == bin_capacity {
            score -= 45.0;
        }
    }

    // Prefer filling bins with low residual relative to fleet mean
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in stream, tighten packing (less tolerance for waste)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item are pure waste; penalize them heavily and
    // non-linearly.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Dead-space curve: reward small residuals, but with a cliff — residuals
    // below ~10 are nearly worthless, residuals near 0 are perfect fits.
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 200.0; // exact fill: best possible outcome
    } else if pr <= 10.0 {
        score += 60.0 * (1.0 - pr / 10.0); // unusable sliver penalty
    } else {
        // Usable residual: mild reward for larger usable leftover space,
        // since it can host future items.
        score -= 0.15 * pr;
    }

    // Reward tight fits relative to bin_residual (small waste fraction).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Base penalty grows with open bins
    // (pressure to consolidate), reduced when the item fits the fresh bin
    // very well and lookahead item would also fit.
    if bin_residual == bin_capacity {
        score += 40.0 + 6.0 * open_bins_count as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score -= 50.0 * fit_quality;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // fresh bin can also host the next item
        }
        if fitting_bins_count == 1 {
            score -= 60.0; // no real alternative anyway
        }
    }

    // Lookahead synergy: if the next item exactly fits the post_residual,
    // this placement is excellent; if the next item cannot fit anywhere
    // else afterwards, keep space flexible.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 5.0; // bin closes; fine if post_residual was small
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.05 * open_bins_count as f64;

    // Progress-based tightening: late in the stream, prefer consolidating
    // into few bins (wasted space costs more when few items remain).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr * 0.2;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean to keep the pool homogeneous and mergeable.
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: post_residual exactly fits the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, penalize leftover slack after the hypothetical second placement.
            let second_leftover = post_residual - next_item_size;
            score -= 25.0 * (1.0 - second_leftover as f64 / bin_capacity as f64);
            // Penalize large slack that would remain wasted.
            score += 0.25 * second_leftover as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to the shortfall.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: just minimize post_residual.
        score += 0.1 * post_residual as f64;
    }

    // Relative to mean residual: placing into a bin with residual far below mean
    // consolidates fullness (good); bins with residual well above mean are better
    // saved for future large items.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; stronger when many bins are open or
        // post_residual (== capacity) leaves lots of usable space.
        score += 55.0 + 3.0 * open_bins_count as f64;
        // If the next item is large, a fresh bin is somewhat more attractive.
        if next_item_size >= 70 {
            score -= 20.0;
        }
    }

    // Early in the stream, be slightly more willing to spread items (future flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: tight fits heavily rewarded.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize post-residuals that are dead space: too small for typical future items
    // (items in 1..100 unknown distribution, so treat residual < 10 as nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item cannot use this residual; penalize proportionally to wasted space
            score += 3.0 * post_residual as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: prefer zero residual absolutely.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty so we prefer filling existing bins.
        score += 30.0;
        // But if this bin is the only fitting bin (i.e., no open bin fits), opening is fine.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Late in the stream, opening fresh bins is less costly than scattering.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // Many open bins with large mean residual: discourage another bin.
        score += 0.5 * open_bins_count as f64;
        score += 0.2 * mean_residual;
    } else {
        // Prefer bins whose residual is below mean (tighter bins first).
        score += 0.3 * (mean_residual - bin_residual as f64);
        // Mild preference for fewer open bins overall.
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = 1.0 - pr / cap;

    // Base: prefer tight fits, with smooth non-linear shaping of post_residual
    let mut score = pr * (1.0 + 0.6 * fill_ratio * fill_ratio);

    // Stream-progress coupling: later in the stream, penalize larger residuals more strongly
    let progress_coupling = pr * pr / cap * progress;
    score += 0.8 * progress_coupling;

    // Reward bins whose post-residual could still serve a future item (smooth lookahead term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr - nxt).max(0.0);
        let match_quality = usable / cap;
        score -= 6.0 * (1.0 - match_quality) * (1.0 - match_quality) * (pr / cap);
        // Penalize if next item exactly fills nothing (dead space risk)
        if pr < nxt {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * fill_ratio;
    } else if fitting_bins_count > 1 {
        // Mild competition scaling: more fitting bins -> less urgency, penalize waste slightly
        score += 0.5 * (fitting_bins_count as f64).ln() * (pr / cap);
    }

    // Mean-residual coupling: when open bins are generally full (low mean residual),
    // avoid wasting this bin's remaining space; when mean residual is high, prefer consolidation
    let mean_norm = mean_residual / cap;
    score += 2.0 * (1.0 - mean_norm) * (pr / cap) * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a smooth opening penalty that grows
    // with the number of open bins and stream progress
    if bin_residual == bin_capacity {
        score += 4.0 + 1.5 * (open_bins_count as f64) + 6.0 * progress;
        // But if item is large relative to capacity, opening fresh is less bad
        score -= 3.0 * (item_size as f64 / cap);
    }

    // Small smooth tie-breaker against very small residuals (nearly full bins are great)
    score -= 4.0 * (1.0 - pr / cap).powi(4);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Class A: post_residual in [0, eighth) -> near-perfect packing, strong reward.
    if post_residual < eighth {
        score -= 18.0 + (eighth - post_residual) as f64;
    }
    // Class B: post_residual in [eighth, quarter) -> good, moderate reward.
    else if post_residual < quarter {
        score -= 6.0;
    }
    // Class C: post_residual in [quarter, half) -> mediocre; penalize slightly.
    else if post_residual < bin_capacity / 2 {
        score += 4.0;
    }
    // Class D: post_residual >= half -> wasteful dead space.
    else {
        score += 10.0 + post * 0.05;
    }

    // Harmonic residue classes: dead space that is a multiple of common item
    // sizes (10, 20, 25, 50) is reusable; odd/prime-like residues are not.
    let residue_reusable = post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0;
    if residue_reusable {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < eighth as u32 {
                score -= 8.0;
            }
        } else {
            // Next item cannot follow here; penalize more if we created big dead space.
            score += (next_item_size as f64 - post) * 0.1;
        }
    }

    // New-bin candidate logic: opening a new bin is attractive when the item
    // fits poorly everywhere else or open bins are very full on average.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let tightness = 1.0 - mean_residual / cap; // how full open bins are
        let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Reward new bin when existing bins are tight; penalize when bins are loose.
        score -= tightness * 22.0 + pressure * 0.5 + progress * 5.0;
        // If this bin is the only fitting option, opening new is wasteful.
        if fitting_bins_count <= 1 {
            score += 15.0;
        }
    } else {
        // Mild preference for reusing fuller bins (smaller residual).
        score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;
    }

    // Slight preference to keep number of open bins bounded early on.
    if open_bins_count > 4 && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (1..=100 range)
    // are pure waste. Penalize sharply when post_residual is small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        if next_fit < 10.0 {
            score -= 30.0 - 3.0 * next_fit;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin so we only
    // do it when open bins have bad fits, but relieve the penalty when many
    // bins are already open (fragmentation pressure) or mean residual is large.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 - 4.0 * pressure - 0.05 * mean_residual;
        // If next item is huge and this bin is fresh, opening is attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Open-bins pressure: mildly discourage scattering across many bins early.
    score += 0.3 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Stream progression: later in the stream, be more conservative about
    // leaving awkward gaps (dead space matters more as stream ends approach).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: after placing this item, the next item fits exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a new residual — reward tight leftover.
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * chain_left;
        } else {
            // Next item cannot use the leftover: penalize proportional dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.4 * dead;
        }
    } else {
        // Last item: minimize leftover directly (score = post_residual already does).
        score += 0.1 * post_residual as f64;
    }

    // Reward tight fits relative to the current item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalize residuals far below the mean (fragmented bin).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, prefer closing bins tightly (waste minimization).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 10.0 };
        score += 45.0 + poor_fit + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward saving this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; prefer bins whose post-residual stays flexible
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Prefer bins with below-average residual (consolidate fullness).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more willing to open new bins (score new bin better);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted early.
        score = bin_capacity as f64 * (1.0 - 0.5 * (1.0 - progress));
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    } else {
        score -= 10.0 * progress;
    }

    // Slight preference for fewer open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr_norm = pr / cap;
    let fit_frac = it / cap;

    // Core: quadratic waste penalty on post-residual, amplified by stream progress
    let mut score = pr_norm * pr_norm * (1.0 + 2.0 * progress);

    // Smooth interaction: prefer tight fits (low post_residual) more as stream advances
    score += (pr_norm - fit_frac).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    } else {
        // Slight preference for bins in a larger pool of candidates with tighter fit
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0) * pr_norm;
    }

    // New-bin candidate: bin_residual == bin_capacity. Penalize opening new bins,
    // more so early in the stream and when many bins are already open but sparse.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let open_f = open_bins_count as f64;
        let sparsity = (mean_residual / cap).max(0.0);
        score += 2.5 + 3.0 * (1.0 - progress) + 0.5 * open_f.sqrt() + 1.5 * sparsity;
        // Exception: if item nearly fills a fresh bin, allow it
        score -= 4.0 * fit_frac * fit_frac;
    }

    // Lookahead coupling: penalize leaving residuals that neither fit the next item
    // nor are large enough to be useful; reward residuals close to next_item_size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        if gap < 0.0 && pr > 0.0 {
            // residual too small for next item: dead space penalty, smooth in gap
            score += (-gap) * (1.0 + progress) * 1.2;
        } else {
            // residual just fits next item: reward, strongest when gap is small
            score -= (1.0 - gap.abs()) * 0.8 * (1.0 - progress);
        }
    }

    // Mild global coupling: mean residual vs this bin's post residual
    score += 0.2 * (pr_norm - mean_residual / cap).abs();

    // Small cubic smoothing term for non-linear shaping
    score += 0.4 * pr_norm * pr_norm * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual partitioned by integer division thresholds
    // Dead-space classes of size 10 (classic capacity-fraction buckets).
    let dead_class = post_residual / 10;
    // Reward bins whose post_residual lands in a "usable" class (<= 30 residual
    // can host typical next items; > 30 is increasingly dead space).
    if dead_class <= 3 {
        score -= 12.0 * (4.0 - dead_class as f64);
    } else {
        score += 4.0 * (dead_class as f64 - 3.0);
    }

    // Perfect fits get a huge bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: harmonic match between post_residual and next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward exact-ish matches via modular closeness.
            let diff = post_residual - next_item_size;
            if diff <= 5 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - diff as f64 / cap);
            }
            // Harmonic class: next item divisible into remaining space
            if post_residual % next_item_size == 0 && next_item_size > 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Tight-fit term: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= 10.0 * fill_frac;

    // Mean-residual harmony: prefer bins close to the mean residual (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Progress coupling: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // New-bin candidate: opening a new bin wastes existing residual mass.
    if bin_residual == bin_capacity {
        // Only attractive when existing bins fit poorly (large dead space).
        score += 0.10 * mean_residual + 2.0 * open_bins_count as f64;
        if post_residual == bin_capacity {
            score += 25.0 * (1.0 - fill_frac); // penalize for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, min item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Penalize gaps too small for the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits strongly.
    score -= (bin_residual as f64 - post_residual as f64) * 0.5;

    // Reward perfect closure.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward exact match with the lookahead item (this gap becomes useful again).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Pressure on number of open bins: prefer reusing existing bins when many are open.
    score += open_bins_count as f64 * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when no existing bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a new bin when existing residuals are large and fragmented.
        score -= (mean_residual - (bin_capacity as f64 - item_size as f64)).max(0.0) * 0.3;
        // Prefer new bin early in the stream (plenty of future items to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // Discourage new bin if the next item fits well into the fresh bin's post-residual.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild bonus for bins whose residual is below mean (compact bins).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good, but reward when
    // post_residual matches the next item size (2-step lookahead chaining).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let chain_bonus = 40.0 / (1.0 + diff * 0.15);
        score -= chain_bonus;

        // Perfect chain: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize post_residual that is too small for the next item
        // (dead space that nothing can use soon).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: pure tight fit preferred.
        score -= 20.0 / (1.0 + post_residual as f64);
    }

    // Relative to mean residual: placing into a tighter-than-average bin
    // preserves loose bins for awkward future items.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Late in the stream, prefer tight fits even more (consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.5 * progress);

    // Penalize leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Mild penalty for opening a new bin when decent fits exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize leaving small unusable dead space (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // Next item can't follow here: mild penalty proportional to wasted chain potential.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        } else {
            // Next item fits: bonus scaled by how much slack remains after it.
            let chain_left = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: strong incentive to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many fitting bins: slight penalty to encourage spreading across bins / diversity.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residual below mean residual (denser bins) when many bins open.
    let res_diff = bin_residual as f64 - mean_residual;
    score += 0.05 * res_diff * (1.0 + open_bins_count as f64 * 0.05);

    // Time horizon: early in stream, be more willing to open new bins (exploration);
    // late in stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: only attractive early or when item barely fits anywhere.
    if bin_residual == bin_capacity {
        let new_bin_bonus = if progress < 0.3 {
            8.0
        } else {
            -15.0 * (1.0 - progress)
        };
        score += 12.0 - new_bin_bonus;
        // If item is large and would leave tiny post_residual in a fresh bin, discourage.
        if item_size > 90 {
            score += 30.0;
        }
    } else {
        // Late stream: reward consolidation into existing bins more aggressively.
        score -= 10.0 * progress;
    }

    // Mild penalty on opening many bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    let poly = (norm_pr * norm_pr) * (1.0 + progress) - (norm_pr * progress * progress);
    score += poly * cap * 0.5;
    // penalize dead space more as stream progresses
    score += progress * (norm_pr * norm_pr) * cap * 0.3;
    // lookahead: reward residual that fits next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = next_item_size as f64 / cap;
        score -= cap * fit_frac * (0.5 + 0.5 * (1.0 - progress));
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // slight preference for filling bins close to mean residual
    score -= (mean_residual - pr).abs() / cap * 5.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity classes
    let quarter = bin_capacity / 4;
    let item_class = item_size / quarter;
    let resid_class = post_residual / (quarter / 2);

    // Reward near-perfect fits: post_residual in a small harmonic band
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible item can fill:
    // unusable gap = post_residual < min item size (1..100 range -> use 10 as soft floor)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo-style coupling: if post_residual exactly matches a common item class
    // (e.g. equals next_item_size or a quarter multiple), reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // lookahead pairs perfectly
        } else if post_residual >= next_item_size {
            score -= 10.0; // can still host next item
        } else {
            score += 15.0; // next item won't fit here
        }
        // integer-division threshold: residual divisible into halves of next item
        if next_item_size > 0 && post_residual % (next_item_size.max(1)) == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the ONLY fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        let lonely = fitting_bins_count <= 1;
        if bad_fit || lonely {
            score -= 70.0; // open new bin when fit is poor or it's last-chance tension
        } else {
            score += 150.0; // otherwise prefer existing bins
        }
    }

    // Prefer filling bins with larger existing residual (consolidation)
    score += mean_residual * 0.15;

    // Slight preference for bins whose residual class matches item class
    if resid_class == item_class && post_residual > 0 {
        score -= 6.0;
    }

    // Mild stream-progression damping: early on, be more liberal opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (1)
    // are pure waste, but tiny gaps (< 10) are especially unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Bonus if the leftover gap can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score += 55.0; // undo: bad dead space beats opening a bin anyway? no—keep penalty
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else. Make the empty bin moderately costly
    // by default so it wins only against heavily penalized poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening fresh bins is fine (no need to keep many open).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
    }

    // Mild preference for bins below mean residual (consolidate space).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: prefer bins that leave small post_residual.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powf(2.0) * 100.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual -> dead space penalty grows
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste.min(80.0);
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable.
    let mean_r = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    score += 1.5 * (bin_residual as f64 - mean_r);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening new bins when a reasonable fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * progress;
        // Only open a new bin if no open bin fits well (post_residual large waste).
        if fitting_bins_count > 0 && post_residual <= 15 {
            score += 200.0; // existing bin fits nearly perfectly; never open new
        }
        // Encourage reserving space: if next item is large and won't fit elsewhere,
        // opening a fresh bin now can be smart.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
            score -= 30.0;
        }
    }

    // Late in stream, consolidate: discourage spreading across many bins.
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of fit: reward placements that fill the bin well.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Reward near-perfect closure.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many options exist, encouraging consolidation.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would exactly fill the bin after this placement, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, slight penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Time horizon: early in the stream, prefer opening new bins to preserve flexibility;
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> favor this bin
    // to consolidate and avoid bin proliferation.
    if open_bins_count > 3 {
        score -= 3.0 * (open_bins_count as f64).ln();
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    }

    // Prefer bins with residual closest to item size among comparable fits.
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    // New-bin candidate: make it attractive only when item is large or late stream.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 8.0 * fill_ratio - 4.0 * (1.0 - progress);
        score -= new_bin_bonus;
        // Discourage new bins when existing bins fit well (many fitting bins).
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: prefer small post residuals more strongly as stream progresses.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 20.0 * coupling;

    // Penalize residuals that are slightly positive but too small to be useful (dead space),
    // penalized smoothly via sin of normalized residual.
    score += 8.0 * (norm_pr * std::f64::consts::PI).sin().abs() * (1.0 - norm_pr) * (0.5 + progress);

    // Lookahead: reward leaving room for the next item (subtract if next item fits exactly-ish).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let tightness = 1.0 - ((pr - nxt) / cap).abs();
            score -= 6.0 * tightness * tightness * (0.5 + progress);
        } else {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Last chance bin: strong reward if this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild reward for consolidating when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Discourage opening new bins when mean residual is large.
    score += (mean_residual / cap) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: strongly favor small post_residual
    score -= 60.0 * (1.0 - post / cap);

    // Harmonic class of post_residual: residues divisible by common item
    // sizes (10/20/25/50) are more reusable -> reward those classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 8.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 6.0; }
        if pr % 50 == 0 { bonus += 10.0; }
        score -= bonus;

        // Penalize dead space: post_residual too small for typical items
        if pr < 10 {
            score += 25.0; // unusable sliver
        } else if pr < 20 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            let rem2 = post_residual - next_item_size;
            // reward chain fits, scaled by how clean the second remainder is
            if rem2 == 0 { score -= 35.0; }
            else if rem2 < 10 { score += 8.0; } // creates sliver after chain
            else { score -= 12.0 * (1.0 - (rem2 as f64) / cap); }
        } else {
            // next item cannot use this bin's remainder anyway
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins would waste a lot. New bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; offset if few bins open or stream is early
        score += 35.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 { score -= 40.0; }
    }

    // Prefer filling bins below mean residual (i.e., tighter than average)
    score -= 0.5 * (mean_residual - post).max(0.0);

    // Mild preference to keep number of open bins low
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead gap = wasted space
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, no dead space at all
    } else {
        // Moderate residuals that can still host typical items are mildly favored.
        score -= 0.3 * post_residual as f64;
    }

    // Dead space relative to the lookahead item: if next item cannot use the gap,
    // this gap is likely to become permanent waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Open-bins pressure: discourage spreading across many bins early on.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // Opening a new bin is a fallback; make it slightly unattractive so
            // decent existing fits win, but not terrible for hopeless fits.
            score += 15.0 + mean_residual * 0.2;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit signal).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.4 * tightness;

    // Stream progression: later in the stream, waste matters more (fewer future
    // opportunities to compensate), so penalize residual slightly harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Reward bins that are already well-filled (low residual before placement).
    score += 0.2 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 4.0;
        } else {
            // next item cannot fit here; penalize small dead space left behind
            let waste = post_residual as f64;
            score += waste * 0.5;
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins)
    let residual_f = bin_residual as f64;
    score -= (mean_residual - residual_f) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 150.0 - fill_ratio * 120.0;
        }
        // large items are fine to start fresh
        if item_size >= 60 {
            score -= 80.0;
        }
    }

    // Late in stream: be more conservative with new bins, favor packing tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 60.0;
    } else {
        score -= progress * 30.0;
    }

    // Mild penalty proportional to wasted fraction of capacity
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no typical item could fill
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small slivers are fine-ish
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0; // awkward zone
    }

    // Lookahead: reward bins whose residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            let leftover_after_next = post_residual - next_item_size;
            score += (leftover_after_next as f64 / bin_capacity as f64) * 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when many bins are open,
        // but costly when few bins fit and residual capacity is abundant.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let base = 55.0 - 25.0 * progress;
        score += base;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        } else if fitting_bins_count <= 2 {
            score += 20.0; // discourage wasting existing near-fitting bins
        }
        if open_bins_count > 8 {
            score -= 10.0; // many open bins: spreading load is okay
        }
    }

    // Global residual pressure: if mean residual is high, prefer filling
    // existing bins rather than fragmenting further.
    if bin_residual < bin_capacity {
        score += (mean_residual - post_residual as f64) * 0.35;
    }

    // Mild preference for bins that are already quite full
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early in the stream, prefer tight fits less aggressively; later, tighten.
    let tightness = 1.0 + 2.0 * progress * progress;
    score += tightness * (pr / cap) * pr * 0.05;

    // Penalize dead space that cannot fit the lookahead item (smooth quadratic gate).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 12.0 * gap * gap * cap;
    }

    // Reward last-chance bins (few fitting bins) with a smooth discount.
    let fit_factor = 1.0 / (fitting_bins_count.max(1) as f64);
    score -= 6.0 * fit_factor * (item_size as f64 / cap);

    // Mild preference toward consolidating into bins near the mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight penalty for spreading across many open bins as stream progresses.
    score += progress * (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    // Residuals divisible by large chunks (e.g. multiples of 25, 20, 10) are
    // more likely to be filled by future items -> reward them.
    let r = post_residual;
    if r > 0 {
        if r % 25 == 0 { score -= 18.0; }
        else if r % 20 == 0 { score -= 12.0; }
        else if r % 10 == 0 { score -= 8.0; }
        else if r % 5 == 0 { score -= 4.0; }
        // Dead space: tiny residuals that no item (min size 1) reliably fills.
        if r < 5 { score += 30.0 * (6 - r) as f64; }
    } else {
        // Perfect closure is ideal.
        score -= 60.0;
    }

    // Integer-division threshold on post_residual: classify usable leftover.
    let usable_class = r / 10; // 0..10
    score -= usable_class as f64 * 2.0; // larger usable leftover slightly better than mid dead zone

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = r - next_item_size;
            score -= 25.0 - (slack as f64).min(25.0);
            if slack == 0 { score -= 20.0; }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += (next_item_size - r).min(20) as f64 * 1.5;
        }
    } else {
        // Last item: any residual is waste; strongly prefer tight fit / closure.
        score += 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well
    // (residual would be huge waste otherwise) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = bin_capacity as f64 - item_size as f64;
        score = waste + 55.0 * (1.0 - progress);
        if fitting_bins_count == 0 { score -= 80.0; }
        // If mean residual across open bins is small, reusing is bad -> new bin ok.
        if mean_residual < item_size as f64 { score -= 25.0; }
    }

    // Mild pressure against proliferating bins when mean residual is high.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this leftover gap
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin is a fallback; prefer it only when
    // no open bin offers a good fit (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 25.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let match_quality = 1.0 - (post_residual as f64 - next) / bin_capacity as f64;
            score -= 50.0 * match_quality;
        } else {
            // Post-residual too small for next item: penalize dead space
            score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize residual far below mean residual (wasteful bin usage)
    let dev = post_residual as f64 - mean_residual;
    score += 0.1 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize mildly so it is only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 60.0;
        // Prefer new bin if no open bin gives a good lookahead match
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() > 30.0 {
            score -= 30.0;
        }
    }

    // Late in stream: tighten packing, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual, non-zero)
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let pr = post_residual as f64;
        score += 40.0 / pr; // small residuals get big discount; large ones mild penalty
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize dead space
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(50.0);
        }
    }

    // New-bin candidate logic: empty bin
    if bin_residual == bin_capacity {
        // Prefer new bin when current item is large relative to capacity or
        // post_residual of placing here would be tiny but next item is large
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 20.0 * tightness;
        if fitting_bins_count == 1 {
            // no other option; opening new bin is fine
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // pair fits perfectly in fresh bin
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.1 * consolidation;
        score -= 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mild time decay: later in stream, tolerate imperfect fits less
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, mildly convex in post_residual
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Reward tight fits: item filling a large fraction of the bin
    score -= 0.6 * (it / cap) * (it / cap) * cap;

    // Smooth stream-progress coupling: as stream advances, prefer tighter packing
    score -= progress * 0.5 * (cap - pr); // later: reward fuller bins more
    score += progress * 0.3 * pr * pr / cap; // later: penalize leftover waste more

    // Coupling with next item: bonus if post_residual can host the lookahead item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 8.0 * snug;
    } else if next_item_size > 0 {
        score += 3.0; // cannot host lookahead: mild penalty
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Discard spreading items thinly when many bins already open
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Mean-residual interaction: if this bin is much emptier than average, deprioritize
    score += 0.2 * (mean_residual - pr).max(0.0);

    // New-bin candidate handling: neutral baseline; only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 0.4 * pr + 0.05 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 20.0; // discourage abandoning the sole fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into 10-wide buckets.
    let class = post_residual / 10;
    // Small classes (near-perfect fill) are heavily rewarded.
    score -= match class {
        0 => 60.0,
        1 => 45.0,
        2 => 30.0,
        3 => 18.0,
        4 => 10.0,
        _ => 0.0,
    };

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Harmonic lookahead: does the next item fit exactly or well into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = post_residual - next_item_size;
        if next_fit == 0 {
            score -= 50.0;
        } else if next_fit <= 10 {
            score -= 30.0;
        } else if next_fit <= 20 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the dead space: penalize proportional dead space.
        score += post_residual as f64 * 0.25;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals of open bins are tight.
    if bin_residual == bin_capacity {
        score += 70.0;
        if mean_residual < 25.0 {
            score -= 55.0; // open bins are nearly full, new bin justified
        }
        if post_residual >= 50 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can host the next item too
        }
    }

    // Penalize leaving residuals that no typical item (1..=100) can ever pair into well
    // if it falls in the awkward 51..=60 band only fillable by small items.
    if post_residual > 50 && post_residual < 60 {
        score += 8.0;
    }

    // Mild preference to keep number of open bins low late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item are pure waste; penalize them super-linearly.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to bin size).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for stranding space.
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose post residual stays near the
    // mean (predictable packing landscape).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in the stream, consolidate: penalize opening new capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // New-bin candidate baseline: opening a new bin should only win when the
    // fit into existing bins is poor (large post_residual or dead space).
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize stranding space the next item cannot use
        score += 8.0;
    }

    // Penalize dead space relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly prefer filling it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tighter fits overall (relative waste term)
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (bin_residual as f64);

    // Early stream: be slightly greedy toward reusing open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // New-bin candidate should be penalized mildly so it wins only on bad fits
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that is hard to reuse (post_residual in awkward band).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item nests
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * nest;
        } else {
            // next item won't fit here; slight penalty for wasting residual below next size
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: prefer opening a new bin when current fit is poor
    // and many open bins exist; penalize new bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.55;
        if poor_fit && open_bins_count > 3 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 12.0 + 20.0 * (1.0 - progress);
        }
    }

    // Global state: if mean residual is high, prefer filling bins with large residuals less
    // tightly? Actually prefer balancing: penalize bins far from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Reward tight fits more aggressively as the stream progresses:
    // subtract a smooth polynomial "tightness bonus" scaled by progress.
    let tightness = (1.0 - x) * (1.0 - x); // 0 at empty, 1 at perfect fit
    score -= tightness * (1.0 + 30.0 * progress + 40.0 * p2 + 30.0 * p3);

    // Penalize large dead space with a cubic term that grows over time.
    let dead = x * x * x;
    score += dead * (20.0 + 60.0 * progress);

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - fit_slack / cap) * (1.0 + 2.0 * progress);
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Prefer bins with residuals near the mean (balanced packing), smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for too many open bins, growing with progress.
    score += open_bins_count as f64 * (0.5 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "unusable" classes (tiny slivers that nothing can ever fill) are penalized.
    // Items are >= 1, so post_residual == 0 is perfect; 1..=9 is a dead sliver
    // under the original 10..80 regime but still usable for tiny items —
    // treat 1..=3 as near-dead regardless.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: strong reward
    } else if post_residual <= 3 {
        score += 25.0; // near-dead sliver: heavy penalty
    }

    // Modulo-10 harmonic classes: leftovers that are multiples of 10 align
    // with the classic size grid and are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd / prime-ish residues are harder to pair: mild penalty.
    if post_residual % 2 == 1 && post_residual > 3 {
        score += 3.0;
    }

    // Lookahead coupling: reward if the next item fits exactly or well
    // into the post_residual; penalize if next item cannot use it at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot enter this bin's leftover: the leftover's
            // value drops, especially if it is small (dead space).
            let unusable = (post_residual as f64).min(next_item_size as f64);
            score += 0.3 * unusable;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item is large relative to capacity or when current leftovers are poor.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin costs ~ (capacity - item) of fresh residual;
        // discourage it when existing bins give a decent fit.
        score += 20.0;
        score -= 30.0 * frac; // large items justify fresh bins
        if post_residual % 25 == 0 {
            score -= 5.0; // clean 25/50/75/100 residual classes
        }
        // If many open bins already exist with low mean residual, opening
        // fresh space is relatively cheaper.
        if mean_residual < 20.0 && open_bins_count > 2 {
            score -= 10.0;
        }
    }

    // Small preference for balancing residual mass across bins late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (post_residual as f64 - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the bin (low post_residual fraction).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness;

    // Lookahead coupling: if the next item fits the post residual, reward;
    // if it nearly fits (small miss), penalize the tease.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if next_item_size <= bin_residual {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 15.0 * (1.0 - miss / 10.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh space; with few open bins, mildly encourage filling.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 5.0 * pressure * tightness;

    // New-bin candidate handling: an empty bin has high residual; only
    // make it attractive when existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base cost of opening a new bin, reduced if open bins are fragmented.
        let mut new_bin_score = 55.0 + 3.0 * pressure;
        if fragmentation > 30.0 {
            new_bin_score -= (fragmentation - 30.0).min(35.0);
        }
        // If next item is large and this item leaves a bad gap, new bin helps.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            new_bin_score -= 20.0;
        }
        score = new_bin_score;
    }

    // Mild stream-progression term: late in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: if the next item fits the post residual exactly, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0; // chainability reward
        } else {
            // post residual cannot host next item: penalize dead space scaled by gap
            let gap = nxt - post_residual as f64;
            score += gap * 0.8;
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin before opening a new bin: reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge relative to residual
    // and no good fit exists (handled implicitly by penalties above).
    if bin_residual == bin_capacity {
        score += 30.0;
        // But allow new bin for very large items that would fragment open bins badly.
        let fill_frac = item_size as f64 / cap;
        if fill_frac > 0.8 {
            score -= 55.0;
        }
    }

    // Slight early-stream preference to spread items, late-stream preference to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.1;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64) * 0.6;

    // Penalize wasted residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overflow gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many fitting bins: prefer the one with residual closest to item (best fit).
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins below mean residual (consolidate emptier space usage).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // later, allow tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: penalize opening a new bin unless current item is small
    // relative to capacity (large items pack well anywhere) or few bins fit it.
    if bin_residual == bin_capacity {
        let base = 60.0;
        let size_factor = 0.8 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64);
        let scarcity = if fitting_bins_count == 0 { 50.0 } else { 0.0 };
        score += base - size_factor - scarcity;
        // Late in stream, opening new bins is more acceptable.
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: minimize wasted residual, with non-linear polynomial shaping.
    let mut score = pr * pr / cap;

    // Smooth coupling: as stream progresses, tolerate residual waste less.
    score += pr * (0.5 + progress * progress);

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= (1.0 - pr / cap).powi(3) * 20.0;

    // Penalize bins whose residual is much larger than the mean (bad fit).
    score += ((bin_residual as f64 - mean_residual) / cap).powi(2) * 15.0;

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + (next_item_size as f64 / cap) * 10.0;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by gap.
        score += ((next_item_size as f64 - pr) / cap) * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Slight preference for consolidating into fewer bins early on.
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // New-bin candidate: must not look attractive unless everything else is bad.
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod capacity fractions.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f;

    // Class A: tiny dead space (<= 10) — excellent, reward strongly
    if post_residual <= 10 && post_residual > 0 {
        score -= 60.0;
    }
    // Class B: unusable band (11..=20) — penalize (dead space nothing small fits well)
    else if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    }
    // Class C: mid band (21..=50) — moderately reusable
    else if post_residual > 20 && post_residual <= 50 {
        score -= 15.0;
    }

    // Modulo-harmonic bonus: post_residual divisible into useful chunk sizes
    if post_residual > 0 && (post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0) {
        score -= 20.0;
    }
    // Awkward residues (prime-ish offsets) get slight penalty
    if post_residual > 0 && post_residual % 10 != 0 && post_residual % 25 != 0 {
        score += 8.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here — strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - 0.3 * slack;
        } else {
            // Next item won't fit — mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid proliferation
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }
    // Many fitting bins: prefer tightest fit implicitly via post_residual; slight penalty for spreading
    if fitting_bins_count > 3 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (all residuals would leave large waste).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin
        score += 40.0;
        // If item is large, new bin is relatively attractive (little waste anywhere)
        if item_size >= 70 {
            score -= 45.0;
        }
        // If mean residual is small (open bins nearly full), new bin is fine
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        // Late in the stream, avoid opening bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the only fitting bin is this new one, it must be chosen
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild pressure against many open bins with high mean residual
    score += 0.05 * open_bins_count as f64;
    score += 0.1 * (mean_residual - frac * 50.0).abs().min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (1..100 interface => min size 1, but small gaps under
    // ~15 are statistically near-dead) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // If the next item fits exactly into the post-residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item won't fit here; mild penalty
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // (fixed overhead dominates), encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count,
        // relax late in the stream when consolidation matters less.
        score += 30.0 + 5.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer placing into bins with above-average residual (balance residuals).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 25.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(0.0);
        // Perfect chain bonus: next item fits exactly after this placement
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving a dead residual the next item cannot use
        if next_item_size > post_residual && post_residual < 10 {
            score += 35.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize wasting a nearly-empty bin's potential on a small item
    if item_size < bin_residual / 3 && bin_residual > bin_capacity / 2 {
        score += 15.0;
    }

    // New-bin candidate: prefer using open bins early, but allow new bin
    // when all open fits would be poor (large post_residual dead space)
    if bin_residual == bin_capacity {
        // Baseline handicap vs. good fits
        score = 45.0 + 0.1 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Opening a fresh bin is attractive if the next item pairs well
            // with a full bin after this one (item + next <= capacity)
            if item_size + next_item_size <= bin_capacity {
                score -= 12.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    // Progression: as stream advances, tighten packing (favor tight fits more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // Mild penalty for proliferating bins
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dynamic time horizon: how far through the stream we are.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Brand-new empty bin candidate: make it a deliberate fallback.
        // Base cost grows with the number of already-open bins (consolidation pressure)
        // and with stream progress (late leftovers are less likely to be filled).
        score += 30.0 + 3.0 * (open_bins_count as f64).sqrt() + 20.0 * progress;

        // Large items sit more naturally in a fresh bin; soften the penalty.
        score -= 0.10 * item_size as f64;

        // If no open bin can fit the item, the new bin is effectively forced.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Tight-fit reward: near-closed bins are highly valuable.
        if post_residual <= 5 {
            score -= 12.0;
        }

        // Last-chance bin: the only open bin that can host this item.
        // Strongly reward using it, especially late in the stream when
        // leaving it unused wastes residual permanently.
        if fitting_bins_count == 1 {
            score -= 18.0 + 15.0 * progress;
        }

        // Lookahead coupling (k=2): reward residuals the next item can chain into.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if next_item_size as u32 <= post_residual {
                let chain_gap = post - nxt;
                // Reward a usable chain; cap the gap-based bonus so loose chains
                // don't dominate tight single placements.
                score -= 6.0 + 0.5 * chain_gap.max(0.0).min(20.0);
                // Perfect two-item closure: item + next item exactly fill the bin.
                if chain_gap == 0.0 {
                    score -= 8.0;
                }
            } else {
                // Next item cannot use this residual: it risks becoming dead space.
                // Penalize proportionally, more so late in the stream when fewer
                // future items remain to fill small gaps.
                score += 0.25 * post * (0.5 + progress);
            }
        }

        // Gentle global coupling: nudge selection toward bins whose residual is
        // below the open-bin mean, consolidating small leftovers and preserving
        // large-residual bins for larger future items.
        score += 0.12 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual (waste), with smooth polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits: quadratic bonus when post_residual is small.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space relative to mean residual across open bins.
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: strongly reward using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly, less so early in the stream
    // or when the next item is large and this bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if nx > pr + item_size as f64 {
                score -= 3.0; // next item won't fit here anyway; new bin may help
            }
        }
    }

    // Lookahead: reward leaving residual that still fits the next item,
    // penalize residuals that are just barely too small for it.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 4.0 * (1.0 - pr / cap);
        } else if nx <= pr + 20.0 {
            score += 3.0 * (nx - pr) / 20.0;
        }
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: prefer small post_residual.
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: reward residuals that are "perfect" fits
    // (0) heavily, and reward residuals in classes matching the lookahead item.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual, this is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Penalize leaving awkward gaps relative to lookahead.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 60.0; // small sliver, still usable-ish
            } else if gap > 40 {
                score += 40.0; // large dead space likely
            }
        } else {
            // Next item cannot fit here regardless; residual is final dead space.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Modulo classes on post_residual w.r.t. capacity fractions (harmonic sizes).
    let c = bin_capacity;
    for h in [2u32, 3, 4, 5] {
        let q = c / h;
        if post_residual == c % h + q * (h - 1) || post_residual == q {
            score -= 25.0; // residuals aligned to harmonic fractions are reusable
        }
    }

    // Integer-division threshold classes: bucket post_residual into deciles,
    // prefer buckets where residual is small but not zero-wasteful.
    let decile = post_residual / 10;
    score += decile as f64 * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins: encourage consolidation (prefer filling existing bins
    // over opening new ones) unless fit is terrible.
    if open_bins_count > 1 {
        let tightness = 1.0 - (post_residual as f64 / c as f64);
        score -= tightness * 30.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity) should only
    // win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a decent existing fit beats opening a new bin.
        score += 200.0;
        // But if current item leaves a huge unusable gap in any open bin,
        // opening fresh is fine: scale penalty down with item "blockiness".
        if item_size >= c / 2 {
            score -= 80.0;
        }
        // Late in stream, prefer closing out bins rather than opening new.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 120.0;
        // If mean residual across open bins is small, they are nearly full;
        // opening a new bin is reasonable.
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual was already small (tight packing pressure).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // Mild noise-free deterministic tiebreak on step parity (harmonic flavor).
    if (step_index + post_residual as usize) % 3 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot serve typical small
    // items (>= 10) are wasted. Penalize unusable small gaps quadratically.
    if post_residual < 10 {
        score += 120.0 + (10.0 - post_residual as f64) * 40.0;
    } else if post_residual < 20 {
        score += 45.0 - (post_residual as f64 - 10.0) * 2.0;
    }

    // Reward tight fits: the smaller the post_residual relative to the bin,
    // the better (exactly-full bins are heavily rewarded).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure,
        // unless existing bins have large mean residuals (poor fits there).
        score += 55.0 + pressure * 3.0 - (mean_residual - post_residual as f64).max(0.0) * 0.3;
    } else {
        // Favor bins with residual above the mean (avoid fragmenting the
        // most usable bins when alternatives exist).
        if (bin_residual as f64) < mean_residual {
            score += 6.0;
        } else {
            score -= 3.0;
        }
    }

    // Lookahead (k=2): if the next item could exactly fill this bin's
    // post_residual, keep the bin attractive; if next item cannot fit in the
    // post_residual but this bin could otherwise be a good home, slight
    // penalty for creating a gap the next item cannot use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 12.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual
    score += 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.3 * slack; // penalize leftover after chaining
        } else {
            // next item cannot fit here; penalize proportionally to wasted capacity
            score += 0.15 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= 0.4 * (mean_residual - post_residual as f64);
    // Penalize bins that are much emptier than average (keep them flexible)
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin would leave large unusable fragment
    if bin_residual == bin_capacity {
        let fragment = post_residual as f64;
        if next_item_size > 0 && fragment < next_item_size as f64 && fragment < 15.0 {
            score -= 10.0; // opening fresh bin is fine when old bin nearly exhausted
        } else {
            score += 30.0; // discourage opening new bin when fits exist
        }
    }

    // Late in stream: prefer filling bins completely
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1, typical mid) can use.
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 0.35 * (post_residual as f64);
    }

    // Lookahead coupling: if next item fits the post residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - next_fit / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty for leaving a tempting gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer filling existing bins fully.
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer bins where item leaves least waste (already via post_residual),
        // mild penalty to spread preference toward fuller bins.
        score += 0.05 * (fitting_bins_count as f64);
    }

    // Global state: many open bins with high mean residual -> encourage consolidating
    // into bins below mean residual (fuller bins).
    if open_bins_count > 1 {
        let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 4.0 * rel;
    }

    // Time horizon: early in stream, be more liberal opening bins (penalize new-bin
    // crowding less); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins exist.
        score += 6.0 + 20.0 * progress + 0.5 * (open_bins_count as f64);
        // But if no open bin fits well (large waste), allow new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Late stream: extra reward for using existing bins.
        score -= 8.0 * progress;
    }

    // Mild preference for bins whose residual is a multiple-friendly chunk
    // (avoid odd gaps like 1-9 that rarely get filled).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear coupling: post_residual normalized, penalize large residuals with polynomial growth
    let post_norm = post / cap;
    score += 40.0 * post_norm * post_norm * post_norm;

    // Reward tight fits (small post_residual) with smooth exponential bonus
    score -= 25.0 * (-post_norm * 8.0).exp();

    // Perfect-fill reward: quadratic coupling with item size
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Stream progress interaction: later in stream, prefer tighter packing more strongly
    score *= 1.0 + 0.5 * progress * post_norm;

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 18.0 * (1.0 - post / (post + next)) * (1.0 - progress);
        } else {
            // penalize leaving residual that cannot serve next item, scaled by gap
            score += 6.0 * ((next - post) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a bin unless existing fits are poor
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 45.0 + 3.0 * open;
        if post_norm > 0.2 {
            score -= 20.0 * post_norm; // allow new bin if item is small relative to capacity
        }
    }

    // Mean residual divergence: prefer bins whose residual deviates favorably from mean
    score += 0.15 * (post - mean_residual).abs() * (1.0 - progress);

    // Slight preference for reusing bins over opening many
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-10 bands (capacity fractions)
    let post_class = post_residual % 10;
    score += post_class as f64 * 0.5;

    // Integer division thresholds on post_residual: dead-space penalties
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // hard to refill zone
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic bonus if next item exactly consumes a mod class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use the leftover: penalize by leftover size
            score += post_residual as f64 * 0.15;
        }
        // If next item fits better in another class band, mild nudge
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual is small (bins nearly full)
        score = 60.0 - 30.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin guarantees room for next item
            score -= next_item_size as f64 * 0.2;
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * progress;

    // Mean residual drift: penalize bins far below mean residual (fragmented)
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item (<= 10)
    // or cannot hold the lookahead item.
    if post > 0.0 && post < 10.0 {
        score += 60.0 * (1.0 - post / 10.0); // tiny slivers are worst
    }
    if next_item_size > 0 && (post as u32) < next_item_size && post > 0.0 {
        // gap too small for the next item: penalize proportionally to how close
        // the next item is to fitting (near-miss waste is painful)
        let miss = (next_item_size as f64 - post) / (next_item_size as f64).max(1.0);
        score += 25.0 * (1.0 - miss);
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 30.0 * (1.0 - post / cap);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow opening new bins for large residual mismatches.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (bin_residual as f64 - item) / cap;

    // New-bin candidate: baseline slightly above a decent fit so we only open
    // a new bin when existing bins are genuinely poor.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 8.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 20.0; // still prefer it over nothing? no: keep new bin unattractive if a fitting bin exists
        }
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post-residuals that are too small for any
    // plausible item (min size 1, but tiny slivers are wasteful) are bad.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: strongly reward a perfect chain fit (next item exactly
    // fills post_residual), moderately reward next item fitting.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain: best possible outcome
        } else if next_item_size <= post_residual {
            // reward proportional tightness of the follow-up fit
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * tight;
        } else {
            // next item cannot follow: penalize leftover dead space
            let dead = (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
            score += 0.5 * dead;
        }
    }

    // Tightness of the current fit relative to mean residual across open bins.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Penalize bins whose residual is far below the mean (fragmented bins),
    // unless this is a last-chance placement.
    if (post_residual as f64) < mean_residual {
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    // Last chance: only one bin fits -> strong reward to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor. Penalize it mildly, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * (1.0 - progress);
        // but if no open bin could fit, opening is fine
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Late in the stream, consolidate aggressively: prefer filling existing bins.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: favor residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Penalize leaving residuals that are too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Global state: when many bins are open with large mean residual,
    // prefer consolidating into existing bins over opening new ones.
    if bin_residual < bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        score -= 4.0 * pressure;
    } else {
        // New-bin candidate: penalize slightly unless existing fits are bad.
        score += 5.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Time horizon: late in the stream, be more conservative (prefer tight packing).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;

    // Non-linear tight-fit reward: quadratic decay of post_residual, stronger late in stream.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 2.5 * tight * tight * (0.5 + progress);

    // Exact fit bonus (smooth, non-piecewise).
    if post_residual == 0 {
        score -= 20.0 * (0.5 + progress);
    }

    // Penalize wasted space relative to mean residual across open bins.
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual (smooth interaction).
    if next_item_size > 0 {
        let next_fits = (post_residual as f64 - next_item_size as f64).max(0.0);
        let next_util = 1.0 - (next_fits / cap);
        score -= 1.2 * next_util * (1.0 - progress);
        // Penalize if post residual is too small for the next item (dead space trap).
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 0.4 * (next_item_size - post_residual) as f64 * (1.0 - progress);
        }
    }

    // New-bin candidate: penalize opening a bin when decent fits exist, less so early.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: prefer residuals that are "usable"
    // for future items. Classify via modulo arithmetic on small moduli.
    let r = post_residual;
    let m4 = (r % 4) as f64;
    let m8 = (r % 8) as f64;
    let m16 = (r % 16) as f64;

    // Penalize residuals that are awkward fractions of capacity.
    // A residual divisible by 8/16 is more likely reusable.
    score -= ((16 - m16) / 16.0) * 6.0;
    score -= ((8 - m8) / 8.0) * 3.0;
    score -= ((4 - m4) / 4.0) * 1.5;

    // Dead-space penalty: very small residuals are nearly worthless.
    if r < 10 {
        score += 40.0 + (10 - r) as f64 * 8.0;
    } else if r < 20 {
        score += 12.0 + (20 - r) as f64 * 1.2;
    }

    // Reward residuals that could host the lookahead item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 25.0 - gap as f64;
            }
        }
        // If next item cannot fit here anyway, slight penalty vs a bin where it can.
        if next_item_size > post_residual {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins. Make new bins attractive only when the current
    // fit is terrible (huge leftover) or when few bins are open.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual * open_bins_count as f64;
        score = 55.0 + waste * 0.15 - progress * 10.0;
        // If the item would leave a small residual in some existing bin,
        // opening fresh is bad; if item is large relative to capacity,
        // fresh bin is fine.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 20.0;
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit baseline sharpening).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (post_residual in 1..=9) are the worst outcome:
    // that space can never be reclaimed by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Open-bins pressure ---
    // Discourage spreading across many bins; reward compacting into fewer.
    score += open_bins_count as f64 * 0.8;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 15.0;
    }
    if fitting_bins_count > 1 {
        // Mild reward for choosing among several options (keeps flexibility).
        score -= 1.5;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well,
        // i.e. the best existing post_residual would be tiny/dead.
        // Base cost of a new bin:
        score += 30.0 + open_bins_count as f64 * 1.0;
        // If the item would leave a large usable residual in a fresh bin
        // and the next item is small, a new bin may be preferable.
        let fresh_residual = bin_capacity - item_size;
        if next_item_size > 0 && fresh_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize opening bins early in the stream (prefer consolidation first).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward.
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Residual too small for next item: mild dead-space penalty.
            score += 3.0;
        }
    }

    // --- Mean residual context ---
    // Prefer bins whose residual is below average (tighter bins get filled first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linear emphasis.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins where the next item fits the post residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            // Perfect chaining: post_residual exactly matches next item => strong reward.
            let slack = (post_residual - next_item_size) as f64;
            let match_bonus = if slack == 0.0 {
                18.0
            } else {
                10.0 * (1.0 - slack / bin_capacity as f64)
            };
            score -= match_bonus;
        } else {
            // Next item cannot fit here: penalize proportionally to wasted potential.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.08 * miss;
        }
        // Coupling: if next item is large, prefer leaving exactly-sized space.
        if n >= 0.5 * bin_capacity as f64 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Relative to mean residual: bins with residuals far below mean are "tight" -> good targets.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count <= 1 { 0.0 } else { (post_residual as f64) };
        // Opening a new bin wastes (capacity - item_size); penalize unless item is large.
        let waste = (bin_capacity - item_size) as f64;
        score += 0.9 * waste - 0.5 * poor_fit;
        // Late in stream, avoid opening bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose post residual aligns with common small-item sizes (dead-space shaping).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers are dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else {
        // Dead space penalty grows super-linearly for small leftovers.
        score += (post_residual as f64).powf(1.4) * 0.05;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_efficiency = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * pair_efficiency;
        if post_residual == next_item_size {
            score -= 10.0; // perfect pair packing
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover too small for next item: penalize proportionally to waste.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, especially when alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 30.0 + 20.0 * progress;
        if fitting_bins_count > 1 {
            new_bin_penalty += 15.0;
        }
        // If open bins are mostly empty, discourage new bins further.
        if mean_residual > bin_capacity as f64 * 0.6 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for filling fuller bins (smaller residual) first.
    score += (bin_residual as f64) * 0.03;

    // Slight bonus for bins already below average residual (consolidating usage).
    score -= (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    // Encourage bin consolidation when many bins are open.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 18.0 * norm_pr * norm_pr * (0.5 + prog2);
    score -= 12.0 * norm_pr * (1.0 - progress) * (1.0 - prog3);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.6 + prog2);

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            score += 0.08 * gap * (1.0 + progress);
        } else {
            score -= 0.05 * gap.abs() * (1.0 - prog2);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild pressure from many open bins relative to mean residual
    let bins_term = open_bins_count as f64;
    score += 0.02 * bins_term * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate penalty: prefer reusing open bins unless residual is tiny
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    // Class 0: perfect fit (post_residual == 0) -> huge reward.
    // Class 1: tiny leftover (<= 10) -> nearly perfect, strong reward.
    // Class 2: leftover that a small item (<= 20) could still fill.
    // Class 3: awkward mid-range leftover (21..50) -> dead-space risk, penalize.
    // Class 4: large leftover (> 50) -> bin still flexible, mild reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 500.0;
    } else if post_residual <= 20 {
        score -= 150.0;
    } else if post_residual <= 50 {
        score += 40.0; // awkward zone penalty
    } else {
        score -= 20.0;
    }

    // Integer-division harmonic classes: leftover divisible into known item sizes is valuable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 30.0; // aligns with typical item granularity
        } else if post_residual % 5 == 0 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 120.0;
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 200.0; // perfect 2-chain
        } else if slack <= 10 {
            score -= 60.0;
        }
    }
    // Penalize if next item almost fits but not quite (tempting near miss).
    if next_item_size > post_residual && next_item_size <= post_residual + 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to capacity or no good residual remains.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 60.0; // large item in fresh bin is efficient
        } else {
            score += 90.0 + 40.0 * (1.0 - fill_ratio); // discourage wasteful fresh-bin use
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer bins whose residual is far below the mean (compact them), keeping
    // large-residual bins free for bigger future items.
    score += 0.5 * ((bin_residual as f64 - mean_residual) * 0.05);

    // Mild preference for fewer open bins overall.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly favor tight fits (low post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Dead space avoidance: residuals too small for the smallest plausible item are wasted.
    // Treat gaps < ~12 (below min item size) as dead weight; penalize quadratically.
    if post_residual < 12 && post_residual > 0 {
        score += 40.0 + (12 - post_residual) as f64 * 5.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else if gap < 12 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item does NOT fit in the residual, mildly penalize hoarding space here
    // unless this is the only fitting bin.
    if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the sole bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // fits are poor (high mean residual spread) or many bins are already open.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: its post_residual is large, so base score is
        // already high; add open-bin pressure so we consolidate when possible.
        score += (open_bins_count as f64) * 2.5;
        // If mean residual of open bins is small (they are nearly full), opening new is fine.
        if mean_residual < 15.0 {
            score -= 30.0;
        }
        // If no open bin can fit at all, opening is mandatory (fitting_bins_count==1
        // refers only to this new bin).
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    } else {
        // Existing bin: slight bonus to keep consolidating as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
        // Prefer bins whose residual is close to what we consume (best-fit sharpening).
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= tightness * 10.0;
    }

    // Mild open-bin pressure overall: fewer open bins is better when fits are decent.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better (already base score).
    // Strong bonus for perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this is an ideal chaining placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetical next placement, scaled
            score += leftover * 0.8;
            if leftover <= 5.0 {
                score -= 60.0;
            }
        } else {
            // next item won't fit here after placement; mild penalty for wasted chain
            score += 15.0;
        }
    }

    // Compare against mean residual: placing in a bin with residual far below mean
    // concentrates waste; placing in a large-residual bin preserves tight bins.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.5;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 40.0 && next_item_size != post_residual;
        if poor_fit && open_bins_count > 0 {
            score += 120.0;
        } else {
            score += 30.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 5.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize exact-fit waste asymmetry: small post_residual is great, but
    // post_residual in a "dead zone" (too small for typical items) is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 8.0; // still usable for small items
    }

    // Lookahead coupling: if the next item fits into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual as f64 - next_item_size as f64;
        score -= 18.0 + 0.3 * chain;
    } else if next_item_size > 0 {
        // Next item won't chain here; penalize proportionally to how close it is.
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.15 * gap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged unless the
    // current bin fit is poor or lookahead suggests a better future pairing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base reluctance to open new bins grows with number of open bins.
        score += 12.0 + 1.5 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        score += 10.0 * progress;
        // If item is large, a fresh bin is actually attractive (large items
        // pair well together later).
        if item_size >= 50 {
            score -= 20.0;
        }
        // If no bin can fit except a new one... (fitting_bins_count == 0 case
        // would not reach here since new bin always fits, but guard anyway).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier future packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Prefer filling bins that are already mostly empty relative to capacity
    // (avoid leaving many half-empty bins).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Mild time-dependent exploration bonus: early on, be slightly more willing
    // to spread items (build diverse residual profiles to learn from).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0 * ((post_residual % 17) as f64 / 17.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, quadratic in post_residual.
    let mut score = pr * pr / cap;

    // Smooth coupling: tight fits matter more as the stream progresses.
    score += norm_pr * norm_pr * (1.0 + progress) * 40.0;

    // Reward bins whose residual is close to the item (smooth closeness term).
    let closeness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= closeness * closeness * 8.0;

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        let slack = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score -= fits_next * (1.0 - slack) * 10.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, more when many bins are open and late in stream.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (open_bins_count as f64).ln() + 15.0 * progress;
    }

    // Slight preference for bins below mean residual (consolidate emptier space).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional capacity utilization reward: tighter fit wins.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_frac * fit_frac;

    // Harmonic classes: bucket post_residual by capacity/8 classes.
    let class = (post_residual * 8) / bin_capacity.max(1);
    let class_penalty = match class {
        0 => -30.0,              // perfect fill
        1 => -10.0,              // small residue, likely dead
        2 => 2.0,
        3 => 6.0,
        4 => 10.0,               // half-full residue: flexible
        5 => 6.0,
        6 => 2.0,
        _ => -4.0,               // near-empty bin: very reusable
    };
    score += class_penalty;

    // Dead-space penalty if residue can't fit any plausible small item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits residue exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize opening new bins normally, less when bins are full/many.
        score += 55.0 - 20.0 * tightness - 1.5 * pressure.min(20.0);
        // Large items relative to capacity favor fresh bins.
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_frac;

    // Small tie-break via modular arithmetic on residual.
    score += (post_residual % 3) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score += 15.0; // nearly-dead space
    }

    // Reward bins whose residual can still fit the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0; // lookahead won't fit here afterwards
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: penalize adding to bins when many are open,
    // encouraging consolidation; but mild so tight fits still win.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins below mean residual (fill emptier bins first keeps tighter bins flexible).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: default neutral-ish; make it attractive only when
    // no good fit exists (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 - score;
        if fitting_bins_count == 0 || item_size > 60 {
            score = base - 20.0; // open a fresh bin for big items / no alternatives
        } else {
            score = base + 15.0; // prefer existing bins when they fit reasonably
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect (tight) fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post residuals non-linearly.
        let pr = post_residual as f64;
        score -= 60.0 * (1.0 - pr / bin_capacity as f64).powi(3);

        // 2-step lookahead: if next item exactly fills the leftover, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Next item fits in the leftover: mild reward scaled by how well it fills.
            let fill = next_item_size as f64 / pr;
            score -= 150.0 * fill * fill;
        } else if next_item_size > 0 {
            // Next item would NOT fit in the leftover: penalize wasted space.
            score += 40.0 * (next_item_size as f64 - pr);
        }
    }

    // Reward when this bin is the last chance (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize bins whose residual deviates favorably from the mean (keep diverse residuals).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive if the item is large relative to capacity
    // (poor fit anywhere else) and many bins are already open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 350.0 - 300.0 * tightness * tightness;
        // More open bins -> slightly cheaper to open another.
        new_bin_score -= 5.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating.
        new_bin_score += 50.0 * (step_index as f64 / total_items.max(1) as f64);
        // If next item is huge, a fresh bin may serve it better.
        if next_item_size > 60 {
            new_bin_score -= 60.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving residuals that no typical item can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // dead space: nothing (min size 1... but small items rare)
    }
    // Penalize residuals just above common small sizes poorly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting space
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad current fits are.
        let mean_waste = (mean_residual - item_size as f64).max(0.0);
        let fit_quality = post_residual as f64; // = capacity - item_size for new bin
        let mut new_bin_score = fit_quality + 35.0;
        // If existing bins have large residuals, opening new bin is less costly.
        new_bin_score -= mean_waste * 0.6;
        // Early in stream, more willing to open bins; late, consolidate.
        new_bin_score -= (1.0 - progress) * 15.0;
        // Many open bins: discourage opening more.
        new_bin_score += open_bins_count as f64 * 2.0;
        // If no open bin fits (fitting_bins_count == 0 effectively new bin needed),
        // the caller only compares against fitting bins, but keep sane value.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score = new_bin_score;
    } else {
        // Prefer fuller bins over emptier ones among open bins.
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    // Mild global pressure: as stream progresses, prefer using existing space.
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    // Smooth interaction: tight fits rewarded more as stream progresses.
    let tight = (1.0 - prn) * (1.0 - prn); // quadratic tightness
    score -= tight * (20.0 + 40.0 * t * t);

    // Penalize residuals that are awkward: neither small nor large.
    let awkward = 4.0 * prn * (1.0 - prn); // peaks at prn=0.5
    score += awkward * (8.0 + 12.0 * t);

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_gap = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - fit_gap) * (1.0 + t);
    } else if next_item_size > 0 {
        // next item won't fit: mildly penalize wasted potential
        score += 4.0 * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowd effect: when many bins are open, prefer consolidating (small post residual).
    let crowd = (open_bins_count as f64).ln1p();
    score += crowd * prn * 3.0;

    // Mean residual context: bins far from mean residual get slight penalty.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * 5.0;

    // New-bin candidate: make it moderately expensive unless residuals are all tight.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the item: quarter-band (1..25, 26..50, 51..75, 76..100)
    let item_class = ((item_size as f64 - 1.0) / 25.0) as u32;
    let post_class = ((post_residual as f64) / 25.0) as u32;

    // Reward residual classes that pair well with common item classes:
    // post_residual in 10..25 or 50..75 is highly reusable; 76..100 is very reusable.
    let class_bonus = match post_class {
        0 => 6.0,   // tiny dead space, nearly unusable -> penalize
        1 => -8.0,  // 25..50 residual: fits most mid items
        2 => -10.0, // 50..75 residual: excellent
        3 => -14.0, // 75..100 residual: near-fresh bin
        _ => 0.0,
    };
    score += class_bonus as f64;

    // Exact harmonic match: can next item fill this bin perfectly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect lookahead fit
        } else if next_item_size <= post_residual {
            // lookahead fits: reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 4.0 + 8.0 * tight;
        } else {
            // lookahead cannot use this bin: slight penalty scaled by dead class
            score += 2.0;
        }
    }

    // Modulo-10 alignment: residuals divisible by 10 tend to host integer items better
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins below mean residual (fill the emptiest-fitting bins first)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: keep it neutral-ish, only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score -= 1.0 + open_bins_count as f64 * 0.05;
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    // Late in the stream: pack tighter, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual is "dead" if it's too small for the smallest plausible item
    // (sizes 1..100, so any gap < next_item_size is dead for the lookahead item).
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap cannot hold the lookahead item: dead space penalty, worse the
            // closer post_residual is to being useful.
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
        // Absolute dead-space: gap below the minimum item size is pure waste.
        if post_residual < 8 {
            score += 25.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize it moderately so tight fits in open
    // bins win, but reward it when open bins are crowded (high mean fill).
    if bin_residual == bin_capacity {
        score += 20.0;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin becomes attractive.
        score -= 0.4 * (bin_capacity as f64 - mean_residual).max(0.0);
        // Early in the stream, fewer bins needed: slightly favor new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual is close to the item (tight fit again).
        let slack = (bin_residual - item_size) as f64;
        score += 0.05 * slack;
        // Favor bins with residual close to mean residual (balance residuals).
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    // Lookahead coupling: if this bin's post_residual exactly fits the next
    // item, big reward for chaining placements.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leave room for the next item: reward proportional to how well the
        // next item would fit in the leftover.
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 5.0 * next_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect (or near-perfect) fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this is an ideal placement.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = pr - nr;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leaving a residual the next item can't use at all.
            if next_item_size > post_residual {
                score += 80.0;
            }
        } else {
            // Next item doesn't fit in leftover: dead space risk.
            score += 60.0 + 0.5 * (nr - pr);
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than the mean concentrates waste well.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it moderately attractive only when current
    // bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        score = 70.0 + pr - 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item: if post_residual
    // is smaller than the lookahead item (or a mid-range item), it's wasted space.
    let eff_lookahead = if next_item_size == 0 { 30 } else { next_item_size };
    if (post_residual as u64) < eff_lookahead as u64 && post_residual > 0 {
        score += 0.5 * (eff_lookahead as f64 - post_residual as f64);
    }

    // Bonus if the lookahead item fits exactly in the post residual (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: this is the only bin that fits the item; strongly favor
    // using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when other bins fit, unless residual capacity
    // across open bins is very fragmented (mean residual low) or many bins open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / (bin_capacity as f64);
        let mut new_bin_penalty = 60.0;
        // Later in the stream or many open bins => avoid spawning more bins.
        new_bin_penalty += 30.0 * progress + 2.0 * (open_bins_count as f64);
        // If open bins are nearly full (low mean residual), a new bin is more acceptable.
        new_bin_penalty -= 50.0 * (1.0 - fragmentation);
        // If item is large, a fresh bin wastes little; soften penalty.
        new_bin_penalty -= 0.3 * (item_size as f64);
        // If only one bin fits and it's this new bin, allow it more readily.
        if fitting_bins_count == 1 {
            new_bin_penalty -= 45.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild penalty for leaving residuals in the awkward 1..10 "sliver" zone.
    if post_residual >= 1 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference for bins whose residual is close to mean residual
    // (keeps bin states homogeneous, easier future packing).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer minimal post-residual, with smooth non-linear coupling to progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Dead-space penalty grows non-linearly when residual is small but nonzero.
    if pr > 0.0 {
        score += (norm_pr).powf(2.0 + 2.0 * progress) * cap * 0.3;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless post_residual of the chosen bin would be
    // worse than the fresh bin's capacity minus next item usage.
    if bin_residual == bin_capacity {
        let next_need = next_item_size as f64;
        let waste_estimate = (mean_residual - next_need).max(0.0);
        score = cap - 0.5 * waste_estimate.min(cap) + 5.0 * progress;
        // Encourage new bin when existing fit would leave a large awkward residual.
        if pr > 0.0 && pr < next_item_size as u32 {
            score -= 10.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mild penalty for scattering across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions (20% bands)
    let band = post_residual / (bin_capacity / 5).max(1);
    score += match band {
        0 => -30.0,                       // near-perfect fit, big reward
        1 => -8.0,                        // small residual, still good
        2 => 0.0,
        3 => 6.0,
        _ => 12.0,                        // large residual left, penalize
    };

    // Dead space: residual too small to hold any plausible item (min size 1)
    if post_residual < 10 {
        score -= 20.0; // fully consumed bin is excellent
    } else if post_residual < 25 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual (chained packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // penalize creating residual that next item cannot use
            score += 4.0;
        }
        // Harmonic class of next item: big next item favors tight packing now
        if next_item_size > 60 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Modulo logic on post_residual: prefer residuals divisible by common item classes
    let m = post_residual % 10;
    if m == 0 {
        score -= 3.0;
    } else if m >= 7 {
        score += 2.0;
    }

    // Prefer filling bins with smaller residual (best-fit core)
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // New-bin candidate: discourage opening a new bin unless residuals are all large
    if bin_residual == bin_capacity {
        let avg_fill = bin_capacity as f64 - mean_residual;
        let pressure = (open_bins_count as f64) * 3.0 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        score = 40.0 + 60.0 - pressure - avg_fill * 0.3;
        if fitting_bins_count == 0 {
            score = -100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (<= 1)
    // are pure waste; penalize heavily with a nonlinear blow-up near zero.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0).powi(2);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Tight fit bonus: reward small post_residual relative to capacity.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // If this bin is the last chance (only fitting bin), discourage opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless open-bin pressure is high and residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count as f64 > 2.0 + mean_residual / 10.0 {
            score -= 25.0;
        }
        // If next item is large and this bin would be its only home later, mild discount.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Open bins: reward keeping mean residual low (consolidation).
        if (post_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving awkward gap.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Early stream: be more permissive opening bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize proportional to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 8.0 * (overshoot / 100.0).min(1.0);
        }
    }

    // Relative to mean residual: prefer bins with residual near/below mean (consolidating)
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.15 * dev;
    if dev < 0.0 {
        score += 0.25 * dev; // extra reward for below-mean residual
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 60.0 - 0.3 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin pairs well with next item
        }
        if fitting_bins_count >= 2 {
            score += 20.0; // alternatives exist, avoid spreading
        }
    }

    // Late in stream: consolidate harder, avoid leaving many small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (res / bin_capacity as f64);

    // Mild penalty when many bins are open (encourage closing bins out)
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 {
        let dead = (post_residual as f64) / cap;
        score += 20.0 * dead * dead * dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // or open bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fullness = 1.0 - (mean_r / cap).clamp(0.0, 1.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - item_size as f64
            + 25.0 * (1.0 - scarcity)
            - 20.0 * fullness * fullness
            + 10.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins when residuals are large.
    if open_bins_count > 2 && bin_residual != bin_capacity {
        let spread = (mean_residual / cap).clamp(0.0, 1.0);
        score += 4.0 * spread;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: penalize wasted space, quadratically (dead space is super-bad).
    let mut score = post + 0.018 * post * post / cap;

    // Reward tight fits (fill ratio), smooth polynomial coupling with progress.
    score -= 22.0 * fit_ratio * fit_ratio * (1.0 + 0.6 * progress);

    // Perfect fits strongly rewarded.
    if post == 0 { score -= 30.0; }

    // Lookahead: penalize leaving a residual that cannot host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 8.0 + 0.08 * (nx - post);
        } else {
            // reward leaving exactly usable space for next item
            let gap = post - nx;
            score -= 10.0 * (1.0 - gap / cap).abs() * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening bins when decent fits exist,
    // but allow it late in the stream or when mean residual is fragmented.
    if bin_residual == bin_capacity {
        score += 40.0 - 12.0 * progress - 0.05 * mean_residual;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    // Mild penalty for many open bins with large mean residual (fragmentation).
    score += 0.002 * open_bins_count as f64 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement (harmonic class on capacity fractions)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 40.0;

    // Strong reward for near-perfect fits (post_residual small but nonzero)
    if post_residual <= 5 {
        score -= 30.0;
    }
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual that no item of size 10..80 could ever use
    // (harmonic class via integer division thresholds)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits into the post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // extra reward if next item nearly fills the remainder too
        if post_residual - next_item_size <= 5 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportional leftover
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Prefer bins below mean residual (keeps bins balanced, avoids many half-empty bins)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Modulo / integer-division harmonic classes on post_residual
    let cls = match post_residual {
        0 => 0.0,
        1..=9 => 1.0,
        10..=19 => 2.0,
        20..=34 => 3.0,
        35..=49 => 4.0,
        _ => 5.0,
    };
    score += cls * 3.0;

    // New-bin candidate: residual == capacity. Give it a mid-range score so it
    // wins only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 55.0
            + (open_bins_count as f64) * 1.5
            - (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: small unusable gaps (post_residual) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver: unusable for any item
    } else if post_residual < 20 {
        score += 15.0; // very hard to reuse
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * item_size as f64;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into them
    // rather than spawning more (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
        // But if the item would leave a huge residual in an existing bin anyway,
        // opening fresh is fine; soften when mean residual is large.
        if mean_residual > 40.0 {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item can exactly use this bin's post_residual,
    // reward leaving that gap; if next item cannot fit post_residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0; // gap likely dead for the next item
        }
    }

    // Mild preference for bins with below-average residual (pack fuller bins first).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Exact fit is extremely desirable
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // next item fits: good, but worse the more dead space remains after both
            let double_res = post_residual - next_item_size;
            score -= 12.0 - 0.15 * double_res as f64;
        } else {
            // next item does not fit: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.10 * over;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin candidate mildly unless residuals are all poor
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - (bin_capacity as f64 - mean_residual);
        let threshold = 45.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        if avg_waste < threshold {
            score += 25.0;
        } else {
            score -= 5.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize leaving residuals that are hard to fill (small awkward gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // Strong bonus if next item exactly fills the post-residual.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Many fitting bins: mild penalty to concentrate packing into fewer bins.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate logic: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (post_residual as f64 - mean_residual).abs();
        score = 40.0
            + mean_residual * 0.3
            + (fitting_bins_count as f64) * 3.0
            - progress * 10.0
            - poor_fits * 0.5;
        // If next item is large, opening fresh is more attractive.
        score -= next_item_size as f64 * 0.1;
    }

    // Prefer bins with residual close to the mean (balanced usage) mildly.
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Slight time-horizon modulation: early on, be conservative (favor filling
    // existing bins); late in the stream, tighten fit preference further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fit_ratio;

    // Prefer bins with smaller residual overall (fill fullest first).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty on wasted residual (quartic-ish growth for tiny leftovers)
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Smooth coupling with stream progress: waste hurts more later
    score += 25.0 * progress * norm_pr * norm_pr;

    // Lookahead: reward if next item fits into post_residual (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (pr - nxt).abs();
        let tightness = 1.0 / (1.0 + fit * fit / (10.0 * cap));
        score -= 30.0 * tightness * (nxt / cap);
    }

    // Penalize opening a new bin when open bins fit decently
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        let avg_waste = (mean_residual - pr).max(0.0);
        score += 15.0 + 0.5 * open_bins_count as f64 + avg_waste * 0.3;
        if fitting_bins_count == 1 {
            score += 60.0; // last-chance bin: strongly avoid new bin
        }
    } else if fitting_bins_count == 1 {
        // last chance: reward using this bin
        score -= 20.0;
    }

    // Mild reward for tight fits overall
    score -= 10.0 * (1.0 - norm_pr) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // ---- Harmonic classes of post_residual (dead-space taxonomy) ----
    if pr == 0 {
        // Perfect closure: bin exactly filled.
        score -= 60.0;
    } else if pr < 10 {
        // Tiny unusable crumb: nearly perfect, harmless.
        score -= 25.0;
    } else if pr <= 30 {
        // Awkward dead zone: too small for most items (items >= 10 but
        // mid-range leftovers rarely reused) -> strong penalty.
        score += 20.0;
    } else if pr <= 60 {
        // Moderately reusable residual.
        score += 5.0;
    } else {
        // Large residual: still very usable, mild penalty only.
        score += 0.0;
    }

    // ---- Last-chance bin: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible. ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        // Extra reward if the placement closes the bin nearly perfectly.
        if pr < 10 {
            score -= 15.0;
        }
    }

    // ---- Lookahead coupling (k=2) with exact-match harmonic class ----
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let prf = pr as f64;
        if (prf - n).abs() < 1.0 {
            // Next item fills this bin exactly: reserve it.
            score -= 50.0;
        } else if n > prf {
            // Next item cannot use this residual anyway -> wasting it is cheap.
            score -= 15.0;
        } else {
            // Next item fits with slack left: residual still contested.
            score += 10.0;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: the space it will leave after this item.
        score = cap - item_size as f64;
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is mandatory.
            score -= 100.0;
        } else if item_size > 50 {
            // Large item into a fresh bin is reasonable; still discourage
            // when existing bins could host it.
            score += 15.0;
        } else {
            // Small item into a fresh bin wastes capacity: discourage.
            score += 45.0;
        }
    }

    // ---- Mild stream-progression coupling: late in the stream, prefer
    // consolidating into fewer bins. ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * progress * open_bins_count as f64;

    // ---- Tie-break against mean residual state: bins far below mean
    // residual are "fresher"; slightly prefer filling drier bins. ----
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold future items (below the minimum plausible item size) are pure waste.
    let min_useful = 1.0f64;
    if (post_residual as f64) < min_useful + 0.0 {
        score += 1000.0;
    }

    // Non-linear dead-space penalty: gaps that can only fit very small items
    // (<= 10) are nearly useless; penalize them quadratically.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits (small but usable residual is fine if tight).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead cannot fit here: mild penalty, stronger if gap is dead.
        score += 8.0;
        if (post_residual as f64) < next_item_size as f64 * 0.5 {
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded
        // or mean residual is too small to be useful.
        score = 150.0 + pressure * 5.0 - mean_residual * 1.5;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    } else {
        score += pressure * 0.8;
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Prefer bins whose residual is close to the item (tightness).
    score += (bin_residual - item_size) as f64 * 0.3;

    // Penalize leaving residual far from mean (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core dead-space penalty: quadratic in leftover space (waste grows superlinearly).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect chaining: this placement sets up the next item exactly.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: scale reward by how tight the fit is.
            let tightness = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 25.0 * tightness.max(0.0);
        } else {
            // Next item cannot follow: penalize proportionally to the gap.
            score += 8.0 + 0.5 * (nxt - post);
        }

        // Bonus if both current and next item chain tightly (item + next + post == capacity-ish).
        let combined = item_size as f64 + nxt;
        if (combined - (bin_capacity - post_residual) as f64).abs() <= 1.0 {
            score -= 15.0;
        }
    } else {
        // Last item: purely minimize waste.
        score += 0.2 * (post_residual as f64);
    }

    // Relative-to-mean coupling: bins with residual far below mean are "cramped";
    // prefer filling bins already below mean residual (consolidate small leftovers).
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 6.0 * (mean_residual - post_f) / bin_capacity as f64;
    } else {
        score += 4.0 * (post_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current item fits poorly everywhere. Make the empty-bin score default-ish high
    // unless post_residual is large enough to be genuinely useful.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of consuming capacity + mild attractiveness
        // only if the item is large relative to capacity.
        score = 45.0 + 0.5 * (bin_capacity - item_size.min(bin_capacity)) as f64;
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 20.0; // big items deserve fresh bins
        }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= bin_capacity as f64 {
            score -= 10.0; // fresh bin can host the pair
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer tightening
    // existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_f / bin_capacity as f64);

    // Mild penalty proportional to open bins count to discourage sprawl.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that no future item can plausibly use:
    // small post_residual is fine; large post_residual wastes capacity.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste * waste;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit in post_residual, mild penalty for chaining failure.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a bin wastes (capacity - item_size) immediately;
    // only attractive when existing fits are poor (fit_ratio low) or many bins already open.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fit_ratio > 0.5 {
            score += 25.0; // discourage opening when a decent fit exists
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Prefer bins with below-average residual (keep one "junk collector" bin).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Slight preference for bins with larger residual when item is large (avoid fragmentation).
    if item_size > 60 {
        score -= 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty on post_residual: dead space grows quadratically with progress
    let pr_norm = pr / cap;
    score += (pr_norm * pr_norm) * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (2.0 + 6.0 * progress);

    // Coupling with mean residual: penalize bins far from the fleet mean residual
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead: reward leaving room for the next item, smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = pr - ni;
        if diff >= 0.0 {
            score -= 1.5 * (1.0 - (diff / cap).powf(2.0)) * (0.5 + progress);
        } else {
            score += 2.0 * (-diff / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Crowding: mild penalty when many bins are open, encouraging consolidation
    score += 0.02 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: keep it neutral-to-slightly-high unless current fit is bad
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - pr_norm) * 0.0 + 4.0 * (1.0 - progress);
        if pr_norm * cap > 0.0 && item_size as f64 / cap < 0.5 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "useful"
    // multiples (divisible into common item sizes), penalize dead zones.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -15.0
    } else if pr % 5 == 0 {
        -8.0
    } else if pr < 10 {
        25.0 // tiny dead space
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds on post residual: which size classes still fit.
    let fits_small = (pr / 10) as f64;
    let fits_mid = (pr / 25) as f64;
    let fits_big = (pr / 50) as f64;
    score -= 2.0 * fits_small + 3.0 * fits_mid + 5.0 * fits_big;

    // Lookahead: penalize if the next item cannot fit in the post residual.
    if next_item_size > 0 {
        if next_item_size > pr {
            score += 20.0;
        } else {
            // harmonic coupling: how well next item divides into post residual
            let rem_after_next = pr - next_item_size;
            score -= (rem_after_next % 10 == 0) as i32 as f64 * 10.0;
            score += rem_after_next as f64 * 0.1;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded
    // (low mean residual) or this bin would leave a bad fit.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap_f).clamp(0.0, 1.0);
        let bad_fit = if post_residual > 0 && post_residual < 15 { 1.0 } else { 0.0 };
        score = 70.0 - 55.0 * crowding + 30.0 * bad_fit
            + (open_bins_count as f64) * 1.5;
    }

    // Slight time preference to consolidate early, spread late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize medium gaps that only fit tiny items.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward leaving room for the lookahead item if it fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize when lookahead item no longer fits anywhere useful.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mild pull toward bins with residuals close to the item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Slight preference to fill older/emptier bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect fit for the next item: huge bonus
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Item + next item exactly fill the bin
        if item_size + next_item_size == bin_residual {
            score -= 50.0;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space that is too small to be useful (below min item size 1 => anything < ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward placing into bins with residuals below mean (consolidating fragmented space)
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline, penalized slightly so only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item is large and this item leaves a great match, still allow new bin
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer filling nearly-full bins harder as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * fit_ratio;
    }

    // Penalize creating tiny dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if post-residual is stranded relative to the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Global state: with many open bins, discourage opening new ones (favor consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
    score += open_pressure * 0.5 * (1.0 - progress);

    // Prefer bins with above-mean residual (balance residual distribution).
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // New-bin candidate: make empty bins slightly less attractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - fit_ratio);
        if mean_residual < 30.0 {
            score -= 12.0; // residuals are tight, opening a new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: penalize leftover residual, non-linearly (waste grows quadratically)
    let mut score = pr * (1.0 + 0.008 * pr);

    // Smooth coupling of residual with stream progress: early on, tolerate
    // leftover space more (bins may still fill); late, penalize waste harder.
    let progress_coupling = 1.0 + 1.2 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth function of how well item fills the bin
    let tightness = fit_ratio * (1.0 - pr / cap);
    score -= 12.0 * tightness * tightness;

    // Penalize large post-residual that cannot fit the next item (smooth gate)
    let next_fits = (next_item_size as f64 <= pr) as f64;
    let next_gap = if next_item_size > 0 { (pr - next_item_size as f64).abs() } else { 0.0 };
    score += (1.0 - next_fits) * 8.0 * (1.0 + 0.05 * next_item_size as f64);
    score -= next_fits * 0.15 * next_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    let last_chance = (fitting_bins_count == 1) as f64;
    score -= last_chance * 25.0 * (1.0 - 0.3 * progress);

    // Mild pressure to consolidate when many bins are open relative to progress
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 2.0 * bin_pressure * (pr / cap);

    // Deviation from mean residual: prefer bins whose residual is near typical
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: brand-new empty bin gets a moderate default score so it
    // only wins when all open bins have high residual (poor fits).
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover: classify post_residual by integer division.
    // Small leftovers (class 0-2) are near-dead space unless a tiny item follows.
    let class = post_residual / 10; // harmonic class of the gap
    match class {
        0 => score -= 60.0,          // gap < 10: almost surely unusable -> but small, acceptable
        1 => score -= 20.0,          // gap 10-19: usable by small items
        2 => score -= 35.0,          // gap 20-29: moderate
        3 => score -= 15.0,          // gap 30-39
        4 => score -= 25.0,          // gap 40-49
        _ => score -= 5.0,           // large gaps: bin still very flexible
    }

    // If the next item fits exactly into the post-residual gap, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_mod = post_residual % next_item_size.max(1);
        if gap_mod == 0 {
            score -= 80.0; // next item tiles the gap perfectly
        } else if gap_mod < 10 {
            score -= 40.0; // near-perfect tiling
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // Dead space: next item can't use the tiny gap.
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin is only attractive early in the
    // stream or when few bins are open; otherwise penalize it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 40.0 + 200.0 * progress + 5.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // But if current bin leaves a tiny unusable gap and next item is large,
        // opening fresh may be better: soften penalty.
        if post_residual == bin_capacity as u32 - item_size && post_residual < 10 && next_item_size > post_residual {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balance load) mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Coupling: item size fraction of capacity — big items prefer tight bins.
    let frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * frac * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (sizes >= 1, but practically small gaps < ~12 are near-useless) are
    // heavily penalized; exact or near-exact fills are heavily rewarded.
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else if post_residual < 12 {
        score += 200.0; // unusable dead space created
    } else if post_residual < 25 {
        score += 40.0; // marginal gap
    }

    // Reward tight fits relative to residual (fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 80.0 + 10.0 * open_bins_count as f64;
        // But allow new bin if all open bins would leave terrible gaps.
        if fitting_bins_count >= 1 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap < 12.0 {
                score -= 100.0;
            }
        }
    } else {
        // Mild pressure to prefer bins whose residual is close to item size.
        score += 0.15 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_gap = post_residual - next_item_size;
            if next_gap == 0 {
                score -= 120.0;
            } else if next_gap < 12 {
                score += 30.0;
            }
        } else if post_residual > 0 {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // Stream progression: early on, be slightly more tolerant of new bins
    // (future packing freedom); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress);
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            // Reward chains that leave a small, still-usable remainder.
            score -= 60.0 * (nxt / cap) - 0.5 * slack;
            if slack <= 10.0 {
                score -= 40.0;
            }
        } else {
            // Penalize residuals that strand the next item.
            score += 30.0 + 0.3 * (nxt - post_residual as f64);
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    let tightness = mean_residual - post_residual as f64;
    score -= 0.4 * tightness;

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it attractive only when open bins would waste space badly.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 25.0
            + 0.5 * mean_residual
            - if next_item_size > 0 { 20.0 } else { 0.0 };
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mildly discourage fragmenting when many bins are already open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: penalize leftover space (tighter fit => lower score).
    let mut score = post;

    // Non-linear waste penalty: dead space that can never be reused is worse.
    // Space below the minimum plausible item size (~cap/10) is nearly dead.
    let dead_threshold = cap * 0.1;
    if post < dead_threshold {
        score += (dead_threshold - post) * 1.5;
    }

    // Perfect-fit bonus: strong reward for nearly filling the bin.
    if post == 0.0 {
        score -= cap * 0.5;
    } else if post <= 2.0 {
        score -= cap * 0.3;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward heavily; if next item barely misses, penalize slightly.
    if next > 0.0 {
        if next <= post {
            let slack = post - next;
            if slack <= 2.0 {
                score -= cap * 0.4; // chain fit: excellent
            } else {
                score -= (post - slack.max(cap * 0.1)) * 0.2;
            }
        } else {
            score += (next - post) * 0.15; // next item won't chain here
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid forcing
    // an awkward placement unless the fit is actually good.
    if fitting_bins_count == 1 && post > 0.0 {
        score += post * 0.3;
    }

    // Global pressure: many open bins with high mean residual => prefer
    // consolidating into existing bins (penalize opening new ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / cap - 0.5).max(0.0);
    score += consolidation * cap * 0.2 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only for large items or when
        // existing bins are fragmented; otherwise keep it slightly worse
        // than a decent fit.
        let fill_ratio = item / cap;
        if fill_ratio > 0.7 {
            score -= cap * 0.25; // large item: fresh bin is fine
        } else {
            score += cap * 0.15 * (1.0 - fill_ratio);
        }
        // Late in stream, prefer closing out existing bins instead.
        score += progress * cap * 0.1;
    }

    // Mild time-horizon modulation: early on, be more exploratory
    // (tolerate imperfect fits to keep flexibility), late on, be greedy.
    score *= 1.0 + 0.1 * (1.0 - progress) - 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let base = pr / cap;

    // Core: non-linear polynomial in normalized post-residual, tightened as stream progresses
    let mut score = base * base * (1.0 + 2.0 * progress) + base * (1.0 - progress);

    // Smooth coupling: interaction of post_residual with mean residual across open bins
    let mean_norm = mean_residual / cap;
    score += 0.5 * base * mean_norm * (1.0 + progress);

    // Lookahead: reward residual that can still host the next item (smooth ramp)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0) / cap;
        score -= 0.6 * (fit_next * (2.0 - fit_next)) * (0.5 + progress);
        // exact match lookahead bonus (smooth via squared gap)
        let gap = (pr - nxt) as f64;
        score -= 0.4 * (-gap * gap / (cap * cap * 0.05)).exp();
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    } else {
        // mild penalty for spreading across many bins when alternatives exist
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a new bin, more so early and when bins exist
    if bin_residual == bin_capacity {
        score += 2.5 + 1.5 * (1.0 - progress) + 0.1 * open_bins_count as f64;
        // but soften if item is large relative to capacity (hard to place later)
        score -= 1.5 * (item_size as f64 / cap);
    }

    // Reward near-perfect fits smoothly
    score -= 1.2 * (-(pr as f64).powi(2) / 50.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight by item size class.
    let size_class = item_size / 10; // harmonic class 1..10
    score *= 1.0 + 0.05 * (size_class as f64);

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Harmonic residue classes on post_residual: residuals divisible
    // by common small item sizes (5, 10, 20, 25) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Dead space penalty: residuals below the smallest plausible item (10)
    // are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; residual value drops,
            // especially if residual is small.
            if post_residual < next_item_size.min(30) {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open
    // bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Cheaper to open bins early in the stream when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, discourage proliferation.
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with residual below mean (fill laggards),
    // keeps bin set compact.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Waste-proportional quadratic term for medium residuals.
    if post_residual > 15 && post_residual < 50 {
        score += 0.05 * (post_residual as f64 - 15.0) * (post_residual as f64 - 15.0) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero leftovers are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits are poor or nonexistent.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_mean = if mean_residual > 0.0 && mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score = 45.0 - 50.0 * (poor_fits + bad_mean);
    }

    // Late in the stream, tighten packing further (less slack tolerated).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: strongly reward post_residual == next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead match: next item still fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * tightness;
    }

    // Penalize post_residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward bins tighter than the mean residual (better fill candidates).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 10.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If the item fits tightly in an existing bin, opening a new bin is worse.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Late in the stream, prefer minimizing bin count more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness;

    // Reward exact fill.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space too small for next item: penalize proportionally.
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere (large item, small residual) or few bins fit it.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 60.0;
        // If current bin residual is small (item barely fits), new bin is fine.
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fit_ratio > 0.9 {
            score -= 70.0;
        }
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 25.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
        // Late in the stream, avoid leaving many nearly-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 4 && progress > 0.7 {
            score += 20.0;
        }
    }

    // Global waste pressure: if mean residual is high, prefer filling bins with
    // large residual (spreading waste) rather than creating fragmented small ones.
    if !is_new_bin {
        let dev = (mean_residual - bin_residual as f64).abs();
        score += 0.15 * dev;
    }

    // Prefer bins whose residual is close to item size (minimal leftover).
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.05 * slack.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual: fraction of capacity wasted after placement.
    let post_norm = post / cap;

    // Smooth non-linear waste term: quadratic in normalized post-residual,
    // amplified as the stream progresses (later placements should be tighter).
    let mut score = post * (1.0 + 2.0 * progress) + 40.0 * post_norm * post_norm * (0.5 + progress);

    // Smooth coupling with mean residual: penalize bins whose post-residual
    // deviates from the mean (encourages balanced residual profiles).
    let dev = (post - mean_residual).abs() / cap;
    score += 25.0 * dev * dev * (1.0 + progress);

    // New-bin candidate: opening a new bin is only attractive when residuals
    // across open bins are already large; smooth sigmoid-like gate.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_norm = mean_residual / cap;
        let gate = 1.0 / (1.0 + (-6.0 * (mean_norm - 0.45)).exp());
        score += cap * (0.6 + 1.4 * gate) * (1.0 + progress);
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 0.35 * cap * (1.0 - post_norm) * (0.5 + progress);
    }

    // Lookahead: reward leaving a gap that still fits the next item,
    // penalize when post-residual barely misses it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (0.4 + 0.6 * progress);
        } else {
            let miss = (nxt - post) / cap;
            score += 18.0 * miss * miss * (0.5 + progress);
        }
    }

    // Mild penalty for proliferating bins early on.
    score += (open_bins_count as f64).ln() * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "quality tiers".
    let residue_class = post_residual % 10;
    score -= match residue_class {
        0 => 25.0,                    // perfect harmonic slot
        5 => 12.0,                    // half-slot
        1 | 9 => 6.0,                 // near-boundary
        2 | 8 => 3.0,
        3 | 7 => 0.0,
        _ => -2.0,                    // 4 | 6: mildly awkward
    };

    // Integer-division thresholds: how many size-10 units remain usable.
    let units = post_residual / 10;
    score -= (units as f64).sqrt() * 4.0;

    // Lookahead coupling: reward exact fit for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let nxt_res = post_residual - next_item_size;
            score -= 10.0 - (nxt_res % 10) as f64 * 0.5;
        } else {
            // next item cannot use this residue; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: any residual is dead space
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize wasting a nearly-full bin when many alternatives exist.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 2 {
        score += 8.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly above good fits,
    // but beats badly fragmented open bins.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.05 - (open_bins_count as f64).ln() * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - 5 {
            score -= 15.0; // big next item: fresh bin is fine
        }
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the only fitting bin
        }
    }

    // Mild stream-progression damping of lookahead bonuses early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 10.0;

    // Penalize bins that could have fit the next item but this placement kills it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving room exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to prefer consolidating into fullest bins.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if new_bin {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap; later it is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Prefer bins with below-mean residual (fuller bins) to consolidate.
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space super-linearly (waste matters most when tiny).
        let pr = post_residual as f64;
        score += 8.0 * (10.0 / pr.min(10.0)).powi(2);
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fill_ratio;
        } else {
            // Next item cannot fit here: mild penalty scaled by the overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    }

    // Compare post_residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 1.0 {
            score -= 40.0 * (1.0 - ratio);
        } else {
            score += 20.0 * (ratio - 1.0).min(3.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    // or the stream is early and building a diverse stock of bins may help.
    if bin_residual == bin_capacity {
        let base_penalty = 150.0;
        let early_bonus = if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.15 {
            60.0
        } else {
            0.0
        };
        // If many bins already fit the item, opening a new one is clearly bad.
        let crowd = 15.0 * fitting_bins_count as f64;
        score += base_penalty + early_bonus + crowd;
    }

    // Slight preference for bins with less residual overall (tighter packing).
    score += 0.1 * bin_residual as f64;

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, with a slight superlinear penalty
    // on medium dead space but a discount for very small post residuals.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powf(1.6) * bin_capacity as f64;

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.12 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize leaving a residual too small for the next item (dead space).
        score += 4.0 * (1.0 - pr / (next_item_size as f64 + pr + 1.0));
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidation.
    let pressure = mean_residual / bin_capacity as f64 * (open_bins_count as f64).sqrt();
    score -= pressure * 2.5;

    // Time horizon: late in the stream, be more conservative (favor tight fits,
    // avoid opening bins that will be underused).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * pr / bin_capacity as f64;

    // New-bin candidate handling: opening a new bin is attractive only when the
    // item is large or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 18.0 * large_item - 30.0 * scarcity - 8.0 * progress;
        if next_item_size > 0 && bin_capacity >= next_item_size + item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Quadratic penalty for mid-range wasted space (dead space valley)
    score += 8.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.1;

    // Perfect fit reward: smooth exponential-like via polynomial
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: reward if next item fits post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / (pr + nxt)) * (1.0 + progress);
        } else {
            score += 4.0 * (nxt - pr) / cap * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins near the mean (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference to fill bins when many are open
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod 10 classify dead-space quality
    let residue = post_residual % 10;
    let class = post_residual / 10; // "harmonic class" 0..=9

    // Penalize awkward residues (waste that rarely matches typical item tails)
    let residue_penalty: f64 = match residue {
        0 => -3.0,   // round residual, reusable
        5 => -1.5,   // half-class
        2 | 8 => 2.0,
        1 | 9 => 4.0,
        3 | 7 => 3.0,
        _ => 2.5,    // 4 | 6
    };
    score += residue_penalty * (1.0 + class as f64 / 10.0);

    // Lookahead coupling: reward if next item fits in post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 0.15 * (post_residual as f64 - (next_item_size - post_residual) as f64).abs();
        }
    }

    // Last chance: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make empty-bin attractive only when item is small relative
    // to capacity or open bins are already fragmented
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score = 50.0 + 40.0 * frac;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // discourage opening new bin when reasonable fits exist
            score += 25.0 * (1.0 - frac);
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 80.0; // pair fits perfectly in a fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Progress-aware tuning
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Penalize small unusable gaps more than proportionally (convex penalty).
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Prefer bins whose residual is close to the mean residual (keeps bin profile uniform).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can use the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item cannot use the leftover, penalize leaving a mid-sized dead gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive only
    // when no open bin offers a decent fit (post_residual large => weak fit here).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are already open
        // or when this bin would be a genuinely better home for the item.
        score = bin_capacity as f64 * 0.9
            - if fitting_bins_count == 0 { 400.0 } else { 0.0 }
            + open_bins_count as f64 * 0.5;
        // Allow new bin to win when existing fits are terrible (large post_residual gap).
        if post_residual >= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect-fit reward: minimize post residual aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly favor bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // Next item fits exactly or near-exactly after this placement.
            score -= 12.0 * (1.0 - gap / capacity) * (1.0 + nxt / capacity);
            if gap == 0.0 {
                score -= 250.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward leftover.
            score += 0.35 * gap;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    let mean_gap = post - mean_residual;
    score += 0.5 * mean_gap;

    // Penalize large dead space relative to smallest useful item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good fit (post_residual large means poor fit).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Default penalty so we prefer reusing open bins with decent fits.
        score += 40.0 * pressure;
        // If lookahead says the next item is huge, a fresh bin may be worth it
        // when current fit leaves lots of fragmented space.
        if next_item_size > 0 && post_residual > next_item_size + 20 {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Slight bonus for using fuller bins (keeps many partially-filled bins flexible).
    score -= 0.1 * (capacity - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward near-perfect packing
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize bins whose residual becomes small-but-awkward (dead space)
    if post_residual > 0 && post_residual < 20 && (next_item_size as f64) > post_residual as f64 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large gaps
            score += 5.0 * fit_ratio;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in stream, be picky (tight fits matter); late, pack aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // Global state: many open bins with high mean residual -> prefer consolidating into fuller bins
    if open_bins_count > 2 {
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 6.0 * fullness * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: make it moderately unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 18.0;
        // If current bins are very fragmented, opening fresh is less bad
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted post residual, with non-linear (quadratic/cubic) shaping.
    let mut score = norm_pr + 1.5 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, keep bins flexible; late, tolerate tight fits more.
    let coupling = norm_pr * (0.5 + 2.0 * progress * progress);
    score += coupling;

    // Reward tight fits smoothly: subtract a saturating function of item/binary fit ratio.
    let tightness = 1.0 - (post_residual as f64 / cap).powi(3);
    score -= 2.0 * tightness * (1.0 - 0.5 * progress);

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = 1.0 - (next_item_size as f64 / cap);
        score -= 1.2 * next_fit * (1.0 - progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty growing with progress.
        score += 0.3 * (next_item_size as f64 / cap) * (0.5 + progress);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else if fitting_bins_count > 0 {
        // Slight penalty for abundance of options: prefer the best fit only.
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual context: if this bin is far from the mean, small smooth penalty.
    let dev = (pr - mean_residual) / cap;
    score += 0.2 * dev * dev;

    // New-bin candidate handling: empty bin should only win when open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Penalize new bin mildly; reduced when many open bins are highly fragmented.
        let fragmentation = (mean_residual / cap).powi(2);
        score = 2.0 + 2.5 * (1.0 - fragmentation) + 1.0 * progress;
        if fitting_bins_count == 1 {
            score += 5.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

