        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }
    } else {
        // Perfect closure: strongly reward filling a bin exactly.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is a chain; reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: leftover must survive longer, penalize
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tight fits: reward small post residual relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.2;

    // New-bin candidate handling: an empty bin has large post_residual, which
    // naturally scores high; add extra penalty scaled by how many open bins
    // already exist, but relax it late in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_weight = (open_bins_count as f64).sqrt() * 6.0;
        score += 30.0 + open_weight * (1.0 - 0.5 * progress);
    }

    // Mild tie-break by mean residual: prefer bins below the mean (tighter bins),
    // spreading work toward bins with more slack.
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Early stream: slightly prefer filling existing bins to keep bin count low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
