    let fit_tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * (fit_tightness - 0.5).abs();

    // Reward using a bin whose residual is above mean (drain large bins first)
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
