            // Reward if next item fits in post residual at all.
            if nxt <= post {
                score -= 40.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless there are no fitting bins
    // or the current fit is very poor.
    if bin_residual == bin_capacity {
        score += 250.0;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 50.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    // Penalize leaving residual that is hard to reuse (small odd gaps).
    let pr = post_residual;
    if pr > 0 && pr < item_size.min(50) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: penalize large dead space, especially small dead space that is unusable
    let dead = post_residual as f64;
    if dead > 0.0 {
        // small residuals (<10) are unusable for future items -> strong penalty
        if dead < 10.0 {
            score += 50.0 * (10.0 - dead) / 10.0;
        }
        // large residual is good (reusable), scale reward
        score -= 0.5 * dead;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 100.0;
        } else {
            // next item won't fit here; slight penalty for wasting space now
            score += 20.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Best-fit style: prefer bin whose residual is close to item size
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 200.0 * tightness;

    // Prefer fuller bins (small residual) generally
    score += 0.3 * bin_residual as f64;

    // New-bin candidate handling: only attractive when no good existing option
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 400.0;
        // cheaper to open new bin early in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 150.0 * (1.0 - progress);
        // if many bins open and mean residual is high, prefer reusing
        score += 0.5 * mean_residual;
        score += 2.0 * open_bins_count as f64;
        // if item is large relative to capacity, opening fresh bin is safer
        score -= 1.0 * item_size as f64;
        // if next item is huge, a fresh bin gives flexibility
        if next_item_size >= 60 {
            score -= 100.0;
        }
        // if this is the only chance... new bin has no fitting count relevance; keep neutral
    }

    // Global congestion: when many bins open with low mean residual, encourage consolidation
    if bin_residual != bin_capacity {
        score += 0.1 * mean_residual;
        score -= 1.0 * open_bins_count as f64;
    }

    // Time horizon: late in stream, avoid creating new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 200.0 * progress;
    } else {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a smooth quadratic reward for low post-residual
    let mut score = pr * (1.0 + 0.5 * norm_pr);

    // Non-linear coupling with stream progress: later in the stream, dead space matters more
    let progress_weight = 1.0 + progress * progress;
    score += norm_pr * norm_pr * cap * 0.3 * progress_weight;

    // Reward placing into bins whose residual deviates favorably from the mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev * (1.0 - progress);

    // Lookahead: penalize leaving a residual that neither fits nor excludes the next item awkwardly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // good: next item can follow; reward proportional to how well it fits
            let slack = (pr - ni) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            // dead space for the next item: penalize smoothly
            score += 5.0 * (1.0 - pr / ni) * (1.0 + progress);
        }
    } else {
        // last item: strongly prefer minimal post-residual
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate calibration: empty bin gets a moderate default so real fits usually win
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - progress) + 0.3 * item_size as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize small unusable slivers (post_residual in [1..15]) strongly.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (1.0 - frac);
    }

    // Reward perfect or near-perfect fits (harmonic completion).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Modulo-class coupling: post_residual divisible by common item classes
    // (items 10..80 often multiples of 5/10) leaves reusable residue.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize wasting this bin's space.
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins below mean residual (balance toward tighter bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild pressure to close bins early in the stream; late stream favors reuse.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * frac;

    // New-bin candidate: only attractive when no good fit exists
    // (a fresh bin has max flexibility but costs one bin).
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * frac; // net +5 for empty bin baseline
        if fitting_bins_count <= 2 {
            score -= 18.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    }

    // Integer-division threshold: residual in upper quarter is flexible space.
    if post_residual >= bin_capacity / 4 && post_residual < bin_capacity / 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    let min_useful = 10u32; // smallest plausible future item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0; // unusable sliver => strong penalty
    } else if post_residual >= min_useful && post_residual <= 25 {
        score += 12.0; // awkward small gap
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill: reward closing the bin
    } else {
        // Larger gaps are useful; mildly reward leaving room for medium items.
        score -= 0.15 * post_residual as f64;
    }

    // Reward bins that can also host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 15.0; // lookahead exactly fills the remainder
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // remainder blocks the next item
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins => prefer consolidating into existing bins,
    // and make the empty new-bin candidate expensive unless it is genuinely needed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += 0.05 * bin_pressure;

    if bin_residual == bin_capacity {
        // New bin: baseline cost plus penalty scaled by how many bins could fit the item.
        score += 45.0 + 8.0 * fitting_bins_count as f64;
        // A new bin is acceptable if existing residuals are nearly exhausted on average.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 50.0;
        }
    } else {
        // Existing bin slightly below mean residual is a good consolidation target.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Prefer tight fits: small waste relative to item size.
    score += 0.3 * (post_residual as f64 / item_size.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residual too small for any future item (min size 1, but typical items larger).
    // Penalize residuals that are small but nonzero — they are likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect 2-step lookahead match: this bin's post residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Next item fits comfortably in post residual: good chaining.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }
    // Next item does NOT fit the leftover: leftover is dead space for the immediate future.
    else if next_item_size > 0 {
        score += 6.0 + 0.25 * (post_residual as f64);
    }

    // Prefer tight fits: reward small post_residual relative to item size.
    score -= 4.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // and no open bin offers a good fit. Scale with stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 - 8.0 * progress;
        // Opening a new bin is more attractive for large items with poor existing fits.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    // (below-mean residual), discouraging scattering across many half-empty bins.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Slight preference for bins with low post residual overall as stream progresses.
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // Penalize large dead space after placement (hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // small leftover is nearly perfect packing
    } else if post_residual >= 10 && post_residual < 30 {
        score += 1.5 * (post_residual as f64 / 30.0);
    } else {
        score += 3.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead coupling: reward leaving a residual that still fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // If next item can't fit here, a near-exact current fill is even better.
            if post_residual < 10 { score -= 2.0; }
            else { score += 1.0; }
        }
    }

    // New-bin candidate logic: opening a new bin is attractive when the item is large
    // relative to mean residual (poor fits everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_fits = (item_size as f64) > mean_residual * 0.85;
        let mut penalty = 4.0; // default: prefer existing bins
        if poor_fits { penalty -= 6.0; }
        if open_bins_count < 3 { penalty -= 2.0; }
        if large_item > 0.7 { penalty -= 3.0; }
        if next_item_size > 0 && next_item_size >= item_size && post_residual == 0 {
            penalty -= 2.0; // big item then equally big next: fresh bin pairs well
        }
        score += penalty;
    }

    // Time horizon: early in the stream, be conservative with dead space;
    // late in the stream, exploit remaining residuals aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Mild dispersion pressure: when many bins are open with high mean residual,
    // encourage consolidating into tighter bins.
    score += 0.02 * mean_residual * (open_bins_count as f64).ln().max(1.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);

    // Base: post residual, scaled non-linearly (dead space quadratic penalty)
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 40.0 * (1.0 - pr / cap) * (0.5 + progress);

    // Smooth interaction: item size vs residual — favor large items into large residuals
    let fill_ratio = it / cap;
    score -= 20.0 * fill_ratio * (bin_residual as f64 / cap);

    // Penalize leaving residual that is awkwardly small but nonzero (dead space)
    if pr > 0.0 {
        score += 12.0 * (1.0 - pr / cap).powi(6);
    }

    // Lookahead coupling: if next item fits exactly in post residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Mean residual deviation: prefer bins below mean residual (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening new bins, more so late in the stream,
    // but allow it when post_residual of this empty bin is large (it always is)
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - 0.4 * progress) + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, i.e. divisible by the smallest item
    // quantum) are more valuable than awkward leftovers.
    let quantum: u32 = 10;
    let residue = post_residual % quantum;
    let class_div = (post_residual / quantum) as f64;

    // Penalize leftovers that are not aligned to the quantum grid (dead space).
    score += (quantum - residue) as f64 * 0.35;

    // Reward large aligned leftover blocks (integer-division thresholds).
    if class_div >= 5.0 {
        score -= 4.0 + class_div * 0.6;
    } else if class_div >= 3.0 {
        score -= 1.5;
    } else if post_residual > 0 {
        score += 3.0; // tiny unusable sliver
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual exactly host the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt_res = post_residual - next_item_size;
            // Harmonic check on the doubly-post residual.
            if nxt_res % quantum == 0 {
                score -= 6.0;
            }
            score -= (next_item_size as f64) * 0.05;
        } else {
            // Next item cannot follow here: mildly penalize tight fits that
            // strand the lookahead.
            score += 2.0;
        }
    } else {
        // Last item: any bin that fits is equally fine; prefer exact fill.
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 15.0;
        // If many bins already fit the item elsewhere, new bin is bad.
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
        // Late in the stream, opening new bins is less costly (no future waste).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 12.0;
        // Large items (>= half capacity) justify fresh bins.
        if item_size * 2 >= bin_capacity {
            score -= 8.0;
        }
    }

    // Congestion pressure: when many open bins exist, prefer compacting into
    // bins with below-average residual (tighter bins).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.08;
    }

    // Small global tie-breaker by step to stabilize selection.
    score += (step_index as f64 % 7.0) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible item (1..=100)
    // are pure waste; the smaller the unusable gap, the harsher the penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap 1 -> +56, gap 9 -> +24
    }

    // Reward exact / near-exact fits aggressively.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving a gap that the lookahead item could have used instead
    // (wasting the opportunity for a two-for-one chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // good: this bin can also host the next item
    } else if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 6.0; // bad: we destroyed a slot usable by the next item
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins
    // rather than opening new ones; make the new-bin candidate less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; give it a mild
    // baseline so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.15;
    } else {
        // Favor bins whose residual is close to the item (tight fit) relative to mean.
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.15;
        // Slightly prefer bins below the mean residual (already partially used well).
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: prefer bins whose post-fit residual tightly matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * gap;
        // Perfect lookahead match: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Residual large enough for next item but wastefully larger: mild penalty.
        if post_residual > next_item_size {
            score += 0.15 * (post_residual as f64 - next_item_size as f64);
        }
    } else {
        // Last item: purely minimize leftover.
        score += 0.0;
    }

    // Penalize very small dead space (unusable fragments), non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Pull toward bins with residuals below the mean (consolidate space).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, be more willing to spread items (keep flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * (1.0 - progress);

    // Slight penalty for opening a brand-new bin when many bins are already open
    // and the item fits elsewhere reasonably.
    if bin_residual == bin_capacity && open_bins_count > 0 && next_item_size > 0 {
        score += 5.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness * tightness;

    // Penalize small unusable dead space (post_residual that nothing can use)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            score -= 12.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
            if leftover == 0 { score -= 10.0; }
        } else {
            // next item can't follow here; mild penalty
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full/crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowded = (open_bins_count as f64) / (mean_residual / bin_capacity as f64).max(0.1);
        score += 20.0 - 15.0 * progress - (crowded.ln().max(0.0)) * 3.0;
        // opening a bin is bad if current bin would leave large useful residual
        if post_residual >= next_item_size && next_item_size > 0 {
            score += 15.0;
        }
    }

    // Prefer filling bins below mean residual (balance toward consolidation)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight preference for bins with larger residual early on, tighter bins later
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 0.03 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let curve = pr * pr / cap;              // quadratic dead-space penalty
    score += 0.9 * curve * (0.5 + prog);

    // Tight fits rewarded via smooth sigmoid-like term on fill ratio
    let fill = (item_size as f64) / cap;
    score -= 12.0 * fill * fill * (1.0 - (pr / cap)) * (1.0 - prog * 0.5);

    // Penalize small post_residual that can't hold a typical next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 6.0 * gap * gap;
        // reward residual that exactly accommodates next item (smooth)
        let match_term = 1.0 - (pr - nxt).abs() / cap;
        score -= 4.0 * match_term.max(0.0) * match_term.max(0.0);
    } else {
        // last item: minimize waste aggressively
        score += 2.0 * pr;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + prog);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    // Deviation from mean residual: prefer bins near mean (smooth balance)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * cap;

    // New-bin candidate: penalize slightly so it wins only on genuinely poor fits
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * prog;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small residues are "dead space"
    // classes; reward residues that fall into reusable bands.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes of capacity: residues that are exact fractions
    // (C/4, C/3, C/2) are highly reusable.
    for (frac, bonus) in [(0.25, 18.0), (0.5, 14.0), (0.75, 10.0), (1.0/3.0, 9.0), (2.0/3.0, 7.0)] {
        let target = frac * cap_f;
        if (post - target).abs() < 1.0 {
            score -= bonus;
        }
    }

    // Integer-division threshold on post_residual: classify into buckets
    let bucket = post_residual / 10; // 0..10
    match bucket {
        0 => score += 12.0,        // 0..9: dead space risk (unless 0, handled above)
        1 => score += 4.0,         // 10..19
        2 => score -= 2.0,
        3 => score -= 5.0,         // 30..39: sweet spot
        4 => score -= 4.0,
        5 => score -= 6.0,         // 50..59: half-bin reusable
        6 => score -= 3.0,
        _ => {}
    }

    // Modulo coupling: residues congruent to 0 mod 10 pair well with
    // typical item sizes; residues mod 10 near 1..3 are awkward.
    let rmod = post_residual % 10;
    if rmod == 0 {
        score -= 6.0;
    } else if rmod <= 3 && post_residual > 0 {
        score += 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight lookahead fits
            score -= 15.0 * (1.0 - slack / cap_f).max(0.0);
        } else {
            // next item cannot fit here: slight penalty for blocking
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave terrible residue.
    if bin_residual == bin_capacity {
        // Base preference for new bin is mild; post_residual == capacity
        // already gives a large score, add a controlled offset.
        score += 30.0;
        // But if the stream is early and few bins open, opening is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Spread-awareness: prefer bins whose residual deviates from the mean
    // in a useful way (consolidate small residues together).
    let dev = post - mean_residual;
    if dev < 0.0 {
        score += 0.05 * (-dev);
    } else {
        score -= 0.03 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fills are heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0 - (post_residual as f64) * 3.0;
    }

    // Strict dead-space avoidance: small leftover gaps (< next item, < min item size 10)
    // are unusable dead space -> penalize proportionally to their uselessness.
    let threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < threshold.min(10).max(1) {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nothing in [1,100] range can be smaller than 10... but guard anyway
    }
    if post_residual > 0 && post_residual < 20 && (next_item_size as u32) > post_residual {
        score += 15.0; // gap too small for the lookahead item
    }

    // Reward bins whose residual can still host the next item (keeps chains alive).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0 + next_item_size as f64 * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: penalize so it is only chosen when all fits are terrible.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.3;
    } else {
        // Prefer bins tighter than average (best-fit style).
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: mild reward proportional to closeness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit: penalize dead space, worse when dead space is small & unusable.
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 8.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Penalize large leftover relative to mean residual (creating outliers of dead space).
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else {
        let fit_ratio = post_residual as f64 / bin_capacity as f64;
        score += fit_ratio * fit_ratio * 20.0; // dead-space penalty grows quadratically
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0; // chain of perfect fits
        } else {
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // If next item cannot use the post residual, mildly penalize large leftovers.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // New-bin candidate handling: opening a new bin is normally worse than fitting
    // an existing bin, but attractive when few bins fit and residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 25.0;
        if fitting_bins_count == 0 {
            new_bin_cost = -100.0; // no open bin fits: must open
        } else if fitting_bins_count == 1 {
            new_bin_cost = 5.0; // last-chance bin exists, still lean toward it
        }
        // Early in the stream, keeping bins tight matters less; late, avoid sprawl.
        new_bin_cost += progress * 15.0;
        // If mean residual across open bins is small (bins nearly full), a new bin is fine.
        if mean_residual < item_size as f64 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Global pressure: with many open bins, prefer consolidating into fuller bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fullness * (open_bins_count as f64).ln().max(1.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening over time
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Smooth polynomial coupling: penalize mid-range residuals (dead space zone)
    let mid = norm_pr - 0.35;
    score += 40.0 * progress * mid * mid * (1.0 - norm_pr);

    // Reward tight fits (small post_residual) more strongly late in stream
    score -= 30.0 * progress * (-norm_pr * 6.0).exp();

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let waste = (mean_residual - item_size as f64).abs();
        score += 15.0 + 30.0 * (1.0 - (waste / cap).min(1.0));
    } else {
        // Favor bins with residual close to item size (good fill)
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 10.0 * fit_gap * fit_gap;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).abs()) * (0.5 + 0.5 * progress);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Mild dispersion penalty: prefer bins deviating from mean residual in useful way
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "nice" fractions
    // of capacity (0, 25, 50, 75, 100) are more reusable; penalize odd dead zones.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;
    let harmonic_bonus = if post_residual == 0 {
        -30.0 // perfect fill
    } else {
        match (post_residual * 4) / bin_capacity {
            0 => 8.0,   // < 25% left: small but potentially dead space
            1 => -6.0,  // ~25% residual: very reusable
            2 => -4.0,  // ~50% residual: reusable
            3 => -2.0,  // ~75% residual
            _ => 0.0,
        }
    };
    score += harmonic_bonus;

    // Penalize residuals that cannot accommodate the lookahead item (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            score -= 3.0; // lookahead fits: strong reward
        }
        // Harmonic pairing: if post residual exactly equals next item, reward heavily.
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Modulo-class match: residual in same mod-10 class as next item is easier to fill later.
        if post_residual >= next_item_size && (post_residual % 10) == (next_item_size % 10) {
            score -= 2.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should rarely win unless the item
    // fits nowhere else or the fit in open bins is terrible.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        } else if post_residual > bin_capacity / 2 {
            score += 6.0; // item is large; fresh bin may be fine
        }
    }

    // Prefer bins whose residual is below average (denser bins first), keeping
    // large residuals available for large future items.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev;

    // Early in the stream, be slightly more willing to consolidate (fewer bins);
    // late in the stream, prioritize tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Integer-division threshold: reward placing items that leave residual in a
    // reusable band [10, 30] (covers the common small-item range).
    if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0;
    }
    // Penalize tiny slivers of dead space (1..9) that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item.max(next_item_size.min(100)) {
            // gap too small even for the next item -> likely dead space
            score += 25.0 + 0.5 * post_residual as f64;
        }
        // non-linear dead-space curve: gaps below half capacity hurt more
        let half = bin_capacity as f64 / 2.0;
        if (post_residual as f64) < half {
            score += (half - post_residual as f64) * 0.8;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Fit that leaves room exactly for the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 + 15.0 * open_bins_count as f64 * (0.5 + progress));

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 20.0 + 10.0 * progress;
    }

    // Prefer bins tighter than the mean residual (good packing candidates)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item can't fit here; penalize proportionally to how much dead space remains
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect chain: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins below mean residual (already tighter)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin unless it enables a great future fit
    if bin_residual == bin_capacity {
        // new bin: post_residual = capacity - item_size
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 20.0 + slack; // new bin must beat tight existing fits
        } else {
            score += 60.0;
        }
    }

    // Mild penalty for leaving very small unusable residuals (< 10)
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space), with diminishing returns.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving awkward residuals that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward;
    // if next item cannot fit in post residual but could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or residuals are large relative to the item.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual - item_size as f64) / bin_capacity as f64;
        score += 15.0; // base cost of opening a new bin
        if pressure > 0.15 {
            score -= 20.0 * pressure.min(1.0);
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0; // big next item: fresh bin is valuable
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 6.0 * progress * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Prefer bins whose residual deviates favorably from the mean (use the fullest bins).
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty on tiny residuals (dead space), smoothly scaled
    let prn = pr / cap;
    score += 12.0 * (1.0 - prn) * prn * prn * cap * 0.1;

    // Reward tight fits with smooth polynomial coupling to stream progress
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (1.0 + 3.0 * progress) * 8.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            score += (gap / cap) * (gap / cap) * 20.0 * (1.0 - progress);
        } else {
            score -= 5.0 * (1.0 + progress);
        }
    }

    // Mild preference for larger residual bins early, tighter bins late
    score += (bin_residual as f64 / cap - 0.5) * (2.0 - 4.0 * progress) * 4.0;

    // Deviation from mean residual: smooth quadratic repulsion
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 6.0 * (1.0 - progress);

    // Encourage consolidation when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues near 0 are ideal.
    // Classify residual by its "harmonic" (integer division) bucket.
    let cap_f = bin_capacity as f64;
    let res_f = post_residual as f64;

    // Fraction of capacity wasted; small residuals are great.
    let frac = res_f / cap_f;

    // Reward tight fits strongly (post residual small relative to capacity)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Harmonic (modulo) logic: residuals that are multiples of common small
    // sizes (10, 20, 25, 50) are more reusable by future items.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 4.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 50 == 0 { score -= 3.0; }

    // Dead-space penalty: residual in (0,10) is unusable for items >=10 in
    // classic streams, but with sizes 1..100 tiny residues are still dead
    // unless next item is tiny. Penalize dead zones.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // next item fits exactly in the dead zone
        }
    }

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability: reward proportional to how well next item fills remainder
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 - chain_waste.min(12.0);
        } else {
            // next item cannot follow: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a base handicap so we prefer
    // reusing open bins, but handicap shrinks when fits are poor or many bins
    // are open with high mean residual (fragmentation pressure).
    if bin_residual == bin_capacity {
        let mut handicap = 30.0;
        // If current item is large relative to typical residuals, opening a
        // fresh bin is attractive.
        let big_item = (item_size as f64) > 0.6 * cap_f;
        if big_item { handicap -= 12.0; }
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is fine.
        if mean_residual < 0.25 * cap_f { handicap -= 10.0; }
        // If many bins are open, discourage adding more unless necessary.
        handicap += open_bins_count as f64 * 0.5;
        // If no other bin fits (fitting_bins_count counts open bins only;
        // the empty-bin call still reports the fitting count), reduce handicap
        // so the new bin wins when it's genuinely needed.
        if fitting_bins_count == 0 { handicap -= 40.0; }
        // Late in the stream, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        handicap += progress * 8.0;
        score += handicap;
    }

    // Mild preference toward fuller bins (lower residual before placement)
    score += (bin_residual as f64) * 0.05;

    // Global waste pressure: penalize leaving residual far from any harmonic
    // multiple of 10 (non-reusable residue).
    let rem = post_residual % 10;
    if rem != 0 {
        let dist = rem.min(10 - rem) as f64;
        score += dist * 0.8;
    }

    // Small tie-breaker noise-free coupling with step progression
    score += (step_index as f64) * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10, min item size) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small usable gaps are risky: hard for future items to use.
    if post_residual > 0 && post_residual <= 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: prefer compacting into existing bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when residuals are tight elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5;
    }

    // Prefer bins already tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but reward it nonlinearly.
    if post_residual > 0 {
        score -= 12.0 / (post_residual as f64).sqrt();
    } else {
        // Perfect fill is excellent.
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post_residual,
    // this placement is ideal (bin becomes perfectly full after next item).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover dead space after it.
            let after_next = post_residual - next_item_size;
            score += 0.35 * after_next as f64;
            if after_next == 0 {
                score -= 20.0;
            }
        } else {
            // Next item will NOT fit here: post_residual becomes a dead slot.
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: bins with residual far below mean absorb
    // small items well; placing into them keeps the "big" bins flexible.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual {
            score -= 0.3 * (mean_residual - res);
        } else {
            score += 0.45 * (res - mean_residual);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize wasting space in a nearly-full bin when many bins are open
    // (keep flexibility), but reward consolidation when few bins are open.
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64);
    }

    // Early in the stream, be slightly more willing to open fresh bins
    // (leave tight bins for later small items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a new bin.
        score += 20.0;
        // Prefer a new bin early, or when next item is large and would
        // strand the leftover of an existing bin.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
        if progress < 0.3 {
            score -= 8.0 * (0.3 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / bin_capacity as f64;

    // Reward tight fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 20.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 5.0 * (1.0 - (nxt / (pr + 1.0)));
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 0.05 * (nxt - pr).max(0.0);
        }
    } else {
        // last item: strongly prefer exact fill
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins with residual below the mean (consolidate small residuals)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, be more conservative about new bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more early, less late
        score += 10.0 * (1.0 - t) + 0.1 * open_bins_count as f64;
        if post_residual > 50 {
            score += 5.0; // opening a bin that stays half-empty is bad
        }
    } else {
        // reward using existing bins more as stream progresses
        score -= 3.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: reward small post-residual, with quadratic sharpening
    let mut score = norm_pr * norm_pr * cap;

    // Smooth coupling: post-residual worth less as stream progresses (dead space penalty grows)
    score += norm_pr * (1.0 + 6.0 * progress) * 10.0;

    // Interaction: polynomial coupling of post_residual with item fill ratio
    let fill = item_size as f64 / cap;
    score -= fill * fill * 20.0 * (1.0 - norm_pr);

    // Lookahead bonus: if next item fits into post-residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 15.0 * snug * snug;
        } else {
            // penalize leaving space that next item cannot use
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild diversity pressure: penalize bins far from mean residual (smooth cubic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * dev * 5.0;

    // New-bin candidate: penalize opening new bins, more so early in stream
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: dead space quality.
    // Residuals that can still host common item classes (multiples of 10 bands)
    // are more valuable than awkward leftovers.
    let class = post_residual / 10; // 0..10 harmonic class
    match class {
        0 => score += 40.0,                       // unusable sliver
        1 => score += 22.0,                       // dead space
        2 => score += 12.0,
        3 => score += 6.0,
        4 => score -= 2.0,                        // hosts small items
        5 => score -= 4.0,                        // half-bin, very reusable
        6 => score -= 3.0,
        7 => score -= 1.0,
        _ => {}                                   // large residual, neutral
    }

    // Exact or near-exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= (10.0 - (slack / 10) as f64).max(0.0);
        } else {
            // next item cannot use this residual: mild penalty proportional to waste
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: baseline penalty so it is chosen only when open bins
    // would leave worse dead space. Scales with how much of the fresh bin the
    // item would consume (big items justify new bins more).
    if bin_residual == bin_capacity {
        score += 25.0 - (item_size as f64) * 0.2;
    }

    // Prefer filling bins below the mean residual (tighter bins first),
    // keeping some diversity in residual classes.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 25.0; // near-perfect fit reward
    } else if (post_residual as f64) <= 0.5 * bin_capacity as f64 {
        // moderate gap: mild penalty scaled by how small the gap is
        score += 0.05 * (post_residual as f64);
    } else {
        // large gap: this bin is wasteful for a small item
        score += 0.10 * (post_residual as f64);
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.3 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 4.0; // stranded residual that next item can't use
    }

    // New-bin candidate: penalize opening a new bin unless open bins are congested.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // allow new bin late in stream if mean residual is small
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Progress coupling: early on, be conservative about bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact/near match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if diff <= 5.0 {
            score -= 30.0 - diff * 4.0;
        } else if post_residual as f64 > next_item_size as f64 {
            score -= 8.0 / (1.0 + diff / 20.0); // mild reward for feasible follow-up
        } else {
            score += diff * 0.5; // next item cannot fit here: dead space risk
        }
    }

    // Penalize residual far below mean (bin is unusually full -> good use, reward it)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize very small unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless they fit poorly;
    // discount slightly more late in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 20.0 * (1.0 - progress);
    }

    // Prefer bins with tight residual relative to item (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // Slight preference for fewer open bins being filled
    score -= 1.0 / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small for typical future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this bin could have hosted next item, but now can't: mild penalty
            score += 4.0;
        }
        // Exact pairing bonus: item + next item fill the bin well
        if item_size + next_item_size == bin_capacity {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: discourage opening new bins when open bins
    // have plenty of room and few bins are open; encourage when bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_r = mean_residual;
        let crowd = open_bins_count as f64;
        // penalize new bin when existing residual space suffices on average
        score += 15.0 + crowd * 2.0 - mean_r * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Prefer bins with residual close to item size (best-fit flavor).
        let gap = (bin_residual - item_size) as f64;
        score += gap * 0.1;
        // Slight preference for fuller bins (larger item_size relative to residual).
        score -= (item_size as f64 / bin_residual as f64) * 5.0;
    }

    // Global balance: when many bins are open, consolidate; when few, allow spread.
    if open_bins_count > 4 && !is_new_bin {
        score -= mean_residual * 0.05;
    }

    // Time horizon: late in stream, avoid leaving tiny residuals.
    if progress > 0.8 && post_residual > 0 && post_residual < 20 {
        score += 15.0 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Base: prefer tight fits (low post residual), with non-linear polynomial shaping
    let mut score = post;

    // Smooth polynomial coupling: penalize mid-range dead space more as stream progresses
    let x2 = x * x;
    let x3 = x2 * x;
    score += (x2 - x3) * (10.0 + 40.0 * progress);

    // Reward near-perfect fits strongly, smoothly
    score -= (1.0 - x).powi(3) * 15.0;

    // Last-chance bonus: only fitting bin -> encourage using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, reward; if it barely misses, penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tight = 1.0 - ((post - nxt) / cap).abs();
            score -= 6.0 * tight * tight;
        } else {
            score += (nxt - post).min(cap) * 0.3;
        }
    }

    // Prefer bins with residuals near the mean (keeps distribution balanced), smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * dev.abs() * 10.0;

    // Mild preference for consolidating into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - x);

    // New-bin candidate: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = x; // post == capacity means nothing placed? treat as new-bin signal
        score += 5.0 + 25.0 * (1.0 - poor_fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "usable"
    // classes (small or large), penalize mid-range dead space via modulo bands.
    let pr = post_residual as i64;
    let band = 10;
    let class = (pr % (2 * band)) as i64; // 0..19 sawtooth
    let class_reward = if class < band { class as f64 } else { (2 * band - class) as f64 };
    score -= 0.8 * class_reward;

    // Integer-division threshold: residual that can still hold the next item is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Exact pairing: post_residual + next_item fills bin perfectly
            if post_residual == next_item_size {
                score -= 25.0;
            }
            // Harmonic match: next item leaves another "good" class residual
            let nr = (post_residual - next_item_size) as i64;
            if nr % band == 0 {
                score -= 6.0;
            }
        } else {
            // Dead space that next item cannot use
            score += 8.0;
            if pr > 0 && (next_item_size as i64) % pr == 0 {
                score += 4.0; // divisible mismatch penalty
            }
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Fractional fill of the bin by this placement
    let fill_frac = item_size as f64 / cap_f;
    score -= 10.0 * fill_frac;

    // Last-chance bin: strongly favor using it rather than opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let mean_tightness = 1.0 - (mean_residual / cap_f);
        score += 15.0 - 10.0 * mean_tightness + 2.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 5.0;
        }
    }

    // Mild stream-phase coupling: early on, prefer consolidating into fewer bins
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - phase) * (mean_residual / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small for any
    // future item (min item size 1, but practically < ~10) are wasted.
    let dead = if post_residual == 0 {
        -50.0 // perfect fit: strong reward
    } else if post_residual < 10 {
        40.0 // unusable sliver: heavy penalty
    } else if post_residual < 20 {
        12.0
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits proportionally to how much of the bin is consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via its full residual,
    // and add extra penalty to opening bins under load).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream.
        score += 8.0 + 0.05 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 0.03 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if post residual is smaller than next item but nonzero, mild penalty.
    if next_item_size > 0 {
        if post_residual > 0 {
            if next_item_size == post_residual {
                score -= 18.0;
            } else if next_item_size > post_residual {
                score += 6.0;
            }
        }
        // Bonus for keeping room compatible with mean residual structure.
        if (post_residual as f64 - mean_residual).abs() < 5.0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: non-linear decay of post-residual.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tight * 60.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in post-residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // next item fits current residual but not post-residual: keep more space
            score += 8.0;
        }
        // dead-space penalty: post-residual too small for any plausible item
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    }

    // Time horizon: early in stream, prefer opening new bins (spread load);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Global state coupling: many open bins with high mean residual -> discourage new bins.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when open bins are plentiful and roomy
        score += (open_bins_count as f64) * 2.0 + mean_residual * 0.3;
        score -= progress * 15.0;
        if fitting_bins_count > 0 {
            score += 10.0; // opening new bin while others fit is wasteful
        }
    } else {
        // favor filling bins that are already below mean residual (reducing spread)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild penalty for very large items in nearly-empty bins (save space for them).
    if item_size >= 60 && bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Reward tight fits: quadratic decay of penalty with post_residual
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Non-linear coupling: tight fits matter more late in the stream
    score -= 20.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space below smallest plausible item (unusable residual)
    if next_item_size > 0 && pr < next_item_size as f64 {
        score += 8.0 * (1.0 - pr / next_item_size.max(1) as f64);
    }

    // Reward bins whose residual can host the lookahead item exactly-ish
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 6.0 * (norm_next / (norm_pr + 0.01)).min(1.0);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins; grows non-linearly
    score += 0.3 * (open_bins_count as f64).powf(1.3) * norm_pr;

    // Pull toward mean residual state (smooth regularization)
    score += 0.5 * (pr - mean_residual) / cap * (1.0 - progress);

    // Smooth endgame term: waste less as stream nears completion
    score += 5.0 * progress * norm_pr * norm_pr;

    // Prefer filling fuller bins with larger items (non-linear coupling)
    score -= 10.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common size classes
    // (e.g. multiples of 10, 25, 50) are more reusable; penalize odd/dead residues.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fill is ideal
    } else {
        if r % 10 == 0 { score -= 8.0; }
        if r % 25 == 0 { score -= 6.0; }
        if r % 50 == 0 { score -= 5.0; }
        if r % 2 == 1 { score += 3.0; } // odd residue harder to pair
        // Dead-space cliff: small unusable leftovers
        if r < 10 && r > 0 { score += 25.0; }
        // Sweet spots: residual that likely fits typical items
        if r >= 10 && r <= 40 { score -= 5.0; }
    }

    // Tightness reward: fraction of bin consumed by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0; // next item nearly fills remainder
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else if fitting_bins_count == 1 {
            score += 15.0; // prefer using the single fitting bin
        } else {
            score += 10.0 + mean_residual * 0.15; // many bins open: prefer packing
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual
    if open_bins_count > 3 && mean_residual > 50.0 && post_residual as f64 > mean_residual {
        score -= 4.0;
    }

    // Late-stream conservatism: near the end, avoid leaving large residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap large enough for typical items.
    if post_residual >= 10 && post_residual < 30 {
        score -= 8.0;
    }

    // Open-bins pressure: penalize adding to bins when many bins are open.
    score += open_bins_count as f64 * 0.7;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 20.0;
    }
    // Penalize if next item cannot fit in the post residual but could fit
    // elsewhere, encouraging gaps that are useful for the next item.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Mild preference for tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (post residual close to zero)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 800.0; // chain fit: next item seals this bin perfectly
        } else if gap <= 5.0 {
            score -= 150.0;
        } else if gap <= 15.0 {
            score -= 40.0;
        } else {
            // penalize leaving a large unusable gap relative to next item
            score += gap * 0.5;
        }
        // if next item cannot fit in post_residual, mild penalty for tight packing
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize wasting a very full bin on a tiny item when other bins exist
    if bin_residual >= bin_capacity {
        // brand-new bin candidate: penalize unless item is large and stream is early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 60.0 * progress - (item_size as f64) * 0.5;
        if item_size >= 50 && open_bins_count == 0 {
            score -= 200.0; // no open bin alternatives, must open
        }
    }

    // Prefer bins with residual below mean (tighter bins get packed first)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild penalty per open bin to discourage bin proliferation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 20.0;

    // Reward perfectly filling the bin.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and the next item is large (so a fresh bin is more useful).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        if next_item_size > 0 {
            // A fresh bin is more attractive when the next item is big and
            // this placement would leave a useless sliver.
            if next_item_size > post_residual && post_residual < 15 {
                new_bin_penalty -= 25.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score += next_waste * 0.5;
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 5.0;
        }
    }

    // Global state: prefer bins below the mean residual (consolidate emptier bins),
    // keeping fuller bins available for small items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Many open bins: encourage closing them out by filling tight.
    if open_bins_count > 4 {
        score += (bin_residual as f64 - post_residual as f64) * -0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 6.0 * poly * cap * 0.01;

    // Reward tight fits (small post_residual), more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 + progress) * 4.0;

    // Penalize dead space below the minimum plausible item size
    if pr < item_size as f64 && pr > 0.0 {
        score += (item_size as f64 - pr) * (1.5 + progress);
    }

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Prefer bins already below mean residual (consolidation)
    score += (pr - mean_residual) * 0.05;

    // Lookahead: reward leaving space usable by the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 2.0 * (1.0 - ((pr - nx) / cap).abs()) * (1.0 + progress);
        } else {
            score += 1.5 * progress;
        }
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: very small post_residual is excellent (near-perfect fit).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Harmonic class penalty: residuals that are awkward for typical item sizes
    // (not multiples of 10, falling in "dead zones" like 11..19, 21..29) get punished.
    let r_mod10 = post_residual % 10;
    if post_residual > 0 && r_mod10 >= 1 && r_mod10 <= 4 {
        score += 12.0; // small unusable sliver
    } else if r_mod10 >= 5 && r_mod10 <= 9 {
        score += 4.0; // moderate waste
    }

    // Integer-division thresholds: classify residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 15.0; // bin still half-full: good to keep filling
    } else if frac < 0.1 {
        score += 8.0; // nearly full bin, but we already reward small residuals
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chains items nicely).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: slight penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 90.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit into
    // existing bins is poor. Penalize the fresh bin mildly, scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 25.0 * progress;
        // But if the item is large, a fresh bin is actually attractive.
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    }

    // Many open bins: discourage spreading; prefer tighter bins via mean residual pull.
    if open_bins_count > 4 {
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward residual sizes that remain broadly reusable (>= 10).
        if post_residual >= 10 {
            score -= 12.0;
        }
        // Penalize residuals that no plausible item (1..=100) can reuse well.
        if post_residual > 80 {
            score += 8.0;
        }
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (small miss), slight penalty for creating a near-miss gap.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // mildly encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.35 * (1.0 - progress);

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.25;

    // Mean-residual coupling: placing into a bin below-average residual (tighter bin)
    // is slightly favored to keep large residuals available.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual as f64 - item_size as f64) < 10.0);
        if poor_alternatives {
            score -= 20.0;
        } else {
            score += 30.0 + (open_bins_count as f64) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement chains two perfect fits — heavily reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits in post_residual, mild reward (keeps bin useful).
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item cannot use the leftover space, penalize proportional dead space.
    else if next_item_size > post_residual {
        let dead = post_residual as f64;
        score += 0.3 * dead;
        // Extra penalty if the dead space is small and unusable (fragmentation).
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins whose post_residual
    // stays near the mean residual (balanced packing).
    let pr = post_residual as f64;
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large (poor fit in partial residual) — penalize premature bin opening.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 10.0 + 0.4 * waste;
        // If item is large relative to capacity, new bin is more reasonable.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream with many open bins, avoid opening more.
        if open_bins_count > 5 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0; // usable leftover zone
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; mild penalty scaled by wasted amount
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: this is the only bin that can fit the item; strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins is cheaper early; more costly as stream progresses.
        score += 18.0 + 14.0 * progress;
        // If the current bin fit is bad (large post_residual waste), reduce the penalty.
        if fit_ratio < 0.6 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            // new bin can host the next item well
            score -= 8.0;
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean residual
    // (consolidate waste into fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Slight preference for filling bins among many open bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post residual, but with non-linear polynomial shaping vs progress
    let mut score = r;

    // Smooth polynomial coupling: early on, prefer tight fits (low residual);
    // late in stream, residual matters more strongly (quadratic growth).
    let tight_bonus = -(1.0 - rn) * (1.0 - rn) * (1.0 - progress) * 12.0;
    score += tight_bonus;

    // Cubic penalty for very small residuals that become dead space,
    // modulated by progress so late-stream waste is punished harder.
    let dead = (1.0 - rn).powi(3) * progress * 20.0;
    score += dead;

    // Lookahead coupling: reward if next item fits the post residual (smooth gaussian-like term)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= r {
            let fit_quality = 1.0 - ((r - ns) / cap);
            score -= 10.0 * fit_quality * (1.0 - progress);
        } else {
            // penalize if next item won't fit
            score += 5.0 * (ns - r) / cap;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - rn) * 2.0;

    // Alignment with mean residual: prefer bins near the mean (smooth quadratic)
    score += ((r - mean_residual) / cap).powi(2) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose residual falls into
    // "useful" residue classes modulo common item sizes are more valuable.
    let pr = post_residual;
    let cap = bin_capacity;

    // Reward tiny residuals (near-perfect fit) with a strong subtraction.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    }

    // Penalize residuals that are "dead": too small for the smallest plausible item (1..100).
    // Residuals below 10 can only be filled by very small items; keep a graded penalty.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }

    // Modulo coupling: if the residual can be exactly divided by the next item size,
    // future packing is harmonic — reward it.
    if next_item_size > 0 && pr > 0 {
        if pr % next_item_size == 0 {
            score -= 12.0;
        } else if pr >= next_item_size {
            // Partial harmonic: reward closeness of residual to a multiple of next item.
            let rem = pr % next_item_size;
            let alt = next_item_size - rem;
            score -= (next_item_size as f64).min(rem as f64).min(alt as f64) * 0.5;
        }
    }

    // Integer-division thresholds on post_residual: classify residual into
    // capacity fractions (1/4, 1/2, 3/4 of bin) and reward mid-size leftovers
    // that remain reusable, penalize awkward quarter-slivers.
    let quarter = cap / 4;
    let half = cap / 2;
    if pr >= half {
        score -= 8.0; // residual still large: bin remains flexible
    } else if pr >= quarter {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 15.0;
    }

    // Many open bins with high mean residual: prefer tightening existing bins
    // rather than leaving many loose bins around.
    if open_bins_count > 0 {
        score -= (mean_residual / cap as f64) * 4.0;
    }

    // Early in the stream, keep bins open and flexible; later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (post_residual as f64 / cap as f64);

    // If next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size are pure waste; penalize them quadratically.
    let min_size = 1.0f64;
    if (post_residual as f64) < min_size {
        score += 1000.0; // should not happen, safety
    }
    // "Dead zone": gaps that no future item can plausibly use.
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        // small-but-usable gaps: mild penalty so tight fits still win
        score += 5.0;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Tightness coupling: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Prefer bins whose residual was already small (compact the fullest bins).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Open-bin pressure: when many bins are open, avoid spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += 2.0 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item is large and post_residual is tiny, slight penalty.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let slack = post_residual as f64 - nx;
            if slack == 0.0 {
                score -= 60.0;
            } else if slack < 10.0 {
                score -= 15.0;
            }
        } else {
            score += 0.05 * (nx - post_residual as f64).min(50.0);
        }
    }

    // New-bin candidate calibration: an empty bin has full residual; make it
    // attractive only when current fits are poor (large post_residual or
    // dead-space creation) and mean residual across open bins is high.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64).max(0.0);
        let mean_frac = mean_residual / bin_capacity as f64;
        // base cost of a fresh bin, discounted when open bins are already full-ish
        score = 45.0 + 0.9 * post_residual as f64 - 30.0 * mean_frac;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if poor_fit < 0.05 {
            score += 50.0; // would-be near-perfect fit elsewhere: keep open bins
        }
        let _ = poor_fit;
    }

    // Mild noise-free stabilization across stream progress: later in the
    // stream, consolidation matters more.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if next item fits exactly-ish in the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space that the next item cannot use
    if next_item_size > 0 && next_item_size > post_residual {
        score += (post_residual as f64) * 0.5;
    }

    // Compare against mean residual: bins tighter than mean are better targets
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize wasting a large residual on a small item (bad packing)
    let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Slight preference for filling bins when many bins are open
    score += open_bins_count as f64 * 0.05;

    // Late in the stream: be greedier, prefer tight fits even more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - waste);

    // New-bin candidate: keep it mildly unattractive unless it beats poor fits
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that is too small for typical items (unusable sliver),
    // scaled by how much of the capacity it wastes.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving post_residual that can host the next item,
    // penalize post_residual that cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // New-bin candidate handling: it starts with a large default score (post_residual = capacity),
    // but adjust so it wins only when open bins are fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins (fragmentation).
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If no existing bin fits well (post_residual large relative to item), make new bin attractive.
        let poor_fit_elsewhere = post_residual as f64 / bin_capacity as f64;
        // post_residual here equals capacity for the new bin; use mean_residual as proxy for open-bin slack.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0; // open bins are too full -> open a fresh one
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        let _ = poor_fit_elsewhere;
    } else {
        // Mild preference for filling fuller bins first (best-fit core).
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
        // Spread items across bins when many are open with slack, to enable future pairings.
        if bin_residual as f64 > mean_residual + 20.0 {
            score -= 3.0;
        }
    }

    // Global pressure: when many bins are open, discourage waste more aggressively.
    score += 0.01 * open_bins_count as f64 * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = (pr / cap).clamp(0.0, 1.0);

    // Base: prefer tight fits, with non-linear shrinkage of large residuals.
    let mut score = pr - 18.0 * fit * (1.0 - fit);

    // Polynomial coupling of residual waste with stream progress:
    // late in the stream, dead space becomes increasingly costly.
    let waste_penalty = (pr * pr) / (cap * cap) * (0.5 + 9.0 * progress * progress);
    score += waste_penalty;

    // Smooth interaction: exact-ish fits are rewarded more as stream advances.
    let tightness = 1.0 - fit;
    score -= 14.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward residual that can host the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let margin = (pr - nx) / cap;
            score -= 10.0 * (1.0 - margin * margin);
        } else {
            let shortfall = (nx - pr) / cap;
            score += 12.0 * shortfall * shortfall;
        }
    }

    // Mild pressure to consolidate: more open bins relative to progress favors reuse.
    score += 0.35 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: penalize slightly so reuse wins unless fit is very poor;
    // penalty fades as mean residual across bins shrinks (bins nearly full).
    if bin_residual == bin_capacity {
        score += 6.0 + 14.0 * progress - 0.05 * mean_residual;
    }

    // Small tie-breaker toward bins below mean residual (consolidation).
    score += 0.08 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small remainders are gold.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Zero residual: perfect closure, strong reward.
    if post_residual == 0 {
        score -= 250.0;
    }

    // Dead-space penalty grows superlinearly for unusable slivers (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Modulo-class logic: residuals in multiples of common item sizes are reusable.
    // Check divisibility by small harmonic bases (10, 20, 25, 50).
    for base in [10u32, 20, 25, 50] {
        if post_residual % base == 0 && post_residual > 0 {
            score -= 15.0 + base as f64 * 0.4;
        }
    }

    // Integer-division threshold: post_residual bucket via pr/10.
    let bucket = (post_residual / 10) as f64;
    score -= bucket * 2.0; // prefer larger usable remainders slightly

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        if next_item_size == post_residual {
            score -= 60.0;
        }
        // Harmonic match: next item divides post_residual evenly.
        if post_residual % next_item_size == 0 {
            score -= 25.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving awkward space.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: only attractive when no good open option.
    if bin_residual == bin_capacity {
        score = cap * 0.9; // baseline high score for opening a new bin
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open
        }
        // Late in stream, prefer closing out open bins over spawning new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If mean residual across open bins is large, discourage new bin.
        if mean_residual > item_size as f64 {
            score += 30.0;
        }
    }

    // Tie-break: prefer bins with residuals close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 10.0;

    // Mild preference to fill bins when many are open (bin-count pressure).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any realistic
    // item (min size 1..100 unknown, but gaps < ~15 are rarely reusable)
    // are dead space -> heavy penalty proportional to how "wasted" they are.
    let dead_threshold = 14.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits: fraction of residual consumed by the item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual == 1 {
        score -= 35.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // New-bin candidate handling: an empty bin is attractive when the item
    // is large or the next item could pair with the leftover space.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; reward when remaining space after
        // placement matches the lookahead item (good pairing potential).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0 + 0.3 * (post_residual - next_item_size) as f64;
        }
        // Penalize opening a new bin when existing bins fit well (tight fits).
        if tightness > 0.0 {
            score += tightness * 8.0;
        }
        // Fewer open bins -> new bin slightly more acceptable.
        score -= pressure * 2.0;
    } else {
        // Lookahead pairing bonus for existing bins: leftover space that can
        // host the next item is valuable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize leftover space slightly larger than the next item
        // (awkward gap that will become dead space).
        if next_item_size > 0 && post_residual > next_item_size {
            let awkward = post_residual - next_item_size;
            if (awkward as f64) < dead_threshold {
                score += (dead_threshold - awkward as f64) * 2.0;
            }
        }
    }

    // Mean-residual coupling: if this bin is far below the mean residual,
    // it is a "junk" bin -> prefer filling it; if above mean, mild penalty.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.15;

    // Early in the stream, allow new bins more freely; late in the stream,
    // consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling (k=2): reward residuals that chain with the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pairing: next item exactly fills this bin
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 + 4.0 * (1.0 - slack); // tighter chain = bigger reward
        } else {
            score += 3.0; // next item cannot use this residual -> likely dead space
        }
    }

    // Perfect fill bonus for open bins.
    if !is_new_bin && post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: mild structural penalty, stronger when many bins
    // are already open or open bins clearly have room (mean_residual high).
    if is_new_bin {
        score += 4.0 + 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 2.0;
        }
    }

    // Late-stream consolidation: prefer bins whose residual is below the
    // global mean residual (drain the emptier-looking bins first).
    let gap = mean_residual - post_residual as f64;
    if gap > 0.0 {
        score -= 2.0 * t * gap / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling between post_residual and stream progress:
    // early on, tolerate leftovers; late in the stream, squeeze residuals hard.
    let coupling = norm_pr * (1.0 - progress) * (1.0 - norm_pr) * 4.0;
    score += coupling * pr * 0.5;

    // Lookahead: reward bins whose residual fits the next item (subtract), penalize near-misses.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= (pr - ni).min(20.0) * 0.6;
        } else {
            score += (ni - pr) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 8.0 * progress;
    }

    // Penalize bins deviating from mean residual (keep pool balanced, smooth term).
    score += (pr - mean_residual).abs() * 0.15;

    // Mild penalty for many open bins to discourage sprawl.
    score += open_bins_count as f64 * 0.05;

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor(); // 0..10 harmonic band

    // Reward near-perfect fits (small post_residual bands).
    score -= 40.0 / (1.0 + class);

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead fits: reward leaving exactly a usable slot.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: unusable for next item — heavy penalty scaled by band.
            score += 25.0 + 10.0 * class;
        }
    }

    // Integer-division thresholds on post_residual (harmonic classes).
    let div = post_residual / 25; // quarters of capacity
    match div {
        0 => score -= 30.0,          // [0,25): excellent fit
        1 => score -= 10.0,          // [25,50): decent
        2 => score += 5.0,           // [50,75): mediocre
        _ => score += 15.0,          // [75,100): wasteful
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // (large post_residual) or item is huge and would strand a big bin.
    if bin_residual == bin_capacity {
        let strand_risk = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += 60.0 - strand_risk - 0.5 * mean_residual;
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size >= item_size {
            // Pairing lookahead with fresh bin can be good.
            score -= 20.0;
        }
    }

    // Slight preference to fill bins that are already heavily loaded.
    let load = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * load;

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // Mean residual coupling: penalize deviating far from fleet average
    // to keep residuals balanced unless it's a tight fit.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - 1.0 / (1.0 + class));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0;
    } else if post_residual < 25 {
        // small gaps are less flexible than medium ones
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual) non-linearly.
    if post_residual > 0 {
        score -= (bin_capacity as f64 / post_residual as f64).sqrt() * 4.0;
    } else {
        // perfect fit is ideal
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.8;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, this placement
    // chains nicely; reward it. If next item would leave the gap dead, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 20 {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // and would create dead space; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let poor_fit = mean_residual < item_size as f64 * 1.2;
        if poor_fit && open_bins_count > 0 {
            score -= 8.0;
        } else {
            score += 15.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Slight preference for bins with residuals close to the mean (balance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect match: post residual exactly fits next item -> strongly reward.
        if post_residual as f64 == nxt {
            score -= 60.0 + 20.0 * progress;
        }
        // Next item fits into post residual: chain placement possible -> reward
        // proportionally to how snug the chain is.
        if post_residual as u32 >= next_item_size {
            let snug = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 15.0 + 25.0 * snug;
        } else {
            // Next item will NOT fit here: dead space risk -> penalize,
            // scaled by how much space is wasted relative to next item.
            let waste = post_residual as f64 / nxt.max(1.0);
            score += 10.0 * waste.min(3.0);
        }
        // Two-item chain: post residual fits next and next's residual is tiny.
        let after_next = post_residual as f64 - nxt;
        if after_next >= 0.0 && after_next <= 5.0 {
            score -= 20.0; // near-perfect 2-item chain completion
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // ---- Relative-to-mean-residual term ----
    // Prefer bins whose residual deviates favorably from the mean:
    // a bin much tighter than the mean is precious; using it for a good fit is good.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // Post residual below mean: we consumed a lot of slack -> reward mildly.
        score -= 0.5 * (-dev).min(50.0);
    } else {
        // Post residual above mean: leaving oversized slack -> penalize.
        score += 0.3 * dev.min(50.0);
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // If this is the only fitting bin, avoid opening a new bin unless the
        // fit is terrible. Reward scaled by tightness of the fit.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: only attractive when current item leaves huge
        // unusable residue elsewhere or nothing sensible fits.
        let bad_fit = (bin_capacity as f64 - item_size as f64) < 0.25 * bin_capacity as f64;
        if bad_fit {
            score -= 40.0; // big item, fresh bin is natural
        } else {
            // Discourage premature opening when open bins exist and could fit.
            if open_bins_count > 0 && fitting_bins_count > 1 {
                score += 50.0;
            } else if open_bins_count > 0 {
                score += 10.0;
            }
        }
        // Early in the stream, slightly prefer consolidating into open bins.
        score += 20.0 * (1.0 - progress);
    }

    // ---- Mild tightness preference overall ----
    score += 0.1 * (bin_capacity as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual is already favored by base score).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual values that are too small
    // for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if this bin becomes near-full junk
            score += 3.0;
        }
    }

    // Last chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately unattractive unless current fit is bad
    // or the bin landscape is crowded with large residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bins early (exploration) and when the item fits poorly anywhere.
        let new_bin_bonus = 30.0
            - 20.0 * progress
            - 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If item is large relative to capacity, opening fresh bin is attractive.
        score = 20.0 + new_bin_bonus - 0.3 * item_size as f64;
    }

    // Mild pressure to consolidate: fewer open bins -> favor placing in existing bins.
    score += 0.5 * mean_residual / (open_bins_count as f64 + 1.0);

    // Slight time-based preference for filling bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = item_size as f64 / cap;

    // Base: reward tight fits via non-linear decay of post_residual
    let mut score = pr * (1.0 + 0.6 * fit_norm * fit_norm);

    // Smooth progress coupling: later in stream, penalize leftover space more strongly
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= progress_coupling;

    // Dead-space penalty: post residual too small to be useful relative to mean residual
    let dead = (pr - mean_residual * 0.5).max(0.0);
    score += dead * dead / (cap * cap) * 20.0;

    // Lookahead: bonus if next item fits in post_residual (subtract to favor)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 10.0 + 15.0 * snug * snug;
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize hoarding space
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: keep it available but not preferred unless residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) * (mean_residual / cap);
        score = 60.0 + 20.0 * fragmentation - 30.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class 0: dead space (< 10, unusable by any item) -> heavy penalty
    // Class 1..: usable slots; finer classes reward "recyclable" residuals
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if post_residual < 10 {
        score += 40.0; // dead space: cannot ever be filled
    } else {
        // Harmonic bucketing: which standard item sizes (10..80) fit?
        let fits_next = (next_item_size > 0 && next_item_size <= post_residual) as f64;
        let fits_typical = (post_residual >= 10) as f64;

        // Modulo-arithmetic class: residual in [10,19], [20,29], ... [90,99]
        let decade = post_residual / 10;
        // Smaller decade = tighter fit; reward proportionally
        score -= fits_next * 25.0;
        score -= fits_typical * 5.0;

        // Penalize residuals that only huge items can fill (rare classes)
        if post_residual > 80 {
            score += 12.0; // only tiny items fit; likely waste
        } else if post_residual >= 50 && post_residual <= 60 {
            score -= 6.0; // half-bin residual is highly reusable
        }

        // Harmonic coupling: if next item fits exactly (perfect pair), big reward
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 45.0;
        }
        // If next item leaves a fresh dead space after pairing, mild penalty
        if next_item_size > 0 && next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post < 10 && next_post > 0 {
                score += 8.0;
            }
        }

        // Modulo threshold: residuals divisible by 10 align with item grid
        if post_residual % 10 == 0 {
            score -= 4.0;
        }

        // Last-chance bonus: only this bin fits the item
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost. Only attractive when current bins
        // would create dead space or mean residual is already fragmented.
        score = bin_capacity as f64 * 0.55; // 55.0 baseline
        if post_residual < 10 {
            score -= 35.0; // prefer new bin over creating dead space
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0; // open bins nearly full; fresh bin is fine
        }
        // Late in the stream, avoid hoarding new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
        // If next item is large, having a fresh bin helps
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Global pressure: many open bins -> discourage spreading, favor consolidation
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 0.7;
    }

    // Mean residual alignment: placing into a bin far from mean residual
    // fragments the fleet; pull score toward mean-friendly placements
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Zero residual is perfect (bin exactly closed).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // If the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is large and would leave this bin stranded, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 10.0;
    }

    // Relative residual vs mean: prefer placing into below-average-residual bins
    // (keeps large-residual bins available for large future items).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: small post_residual rewarded.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly or nearly accommodate the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also fit here afterwards: strong reward,
            // especially for an exact chain match.
            score -= 30.0 + 50.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            score += 10.0 + 20.0 * (diff / bin_capacity as f64);
        }
    }

    // Compare residual against mean residual: bins far below mean are
    // already tight; using them wastes less overall capacity.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score += 80.0;
        // If next item is large and current item is large, fresh bin
        // pairing may be good: soften the penalty.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 70.0;
        }
        // Early in the stream, opening bins is cheaper.
        score -= 40.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference to fill bins among many open ones (reduce sprawl).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalized super-linearly.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste_ratio * waste_ratio;

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small dead space that no future item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves more fragmentation: mild penalty proportional to leftover
        score += 0.3 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight reward for using this bin's space now
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_f = open_bins_count as f64;
    score -= 1.5 * open_f;

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (minimal overfill of large-residual bins when others are tight).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Time horizon: early in stream, opening new bins is cheap (long future to fill them);
    // late in stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bonus = 30.0 * (1.0 - progress); // subtracted for empty-bin candidate later
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus discount early in the stream.
        score += 55.0 - new_bin_bonus;
    } else {
        // Late in the stream, reward using existing bins more aggressively.
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nx = next_item_size as f64;

    // Base: quadratic penalty on post residual (dead space), smoothed by progress
    let mut score = pr * (1.0 + 0.9 * pr / cap) * (0.5 + 0.5 * progress);

    // Reward tight fits: subtract when post_residual is small relative to capacity
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Non-linear coupling: item size with progress — bigger items late should prefer tight bins
    score -= 6.0 * (it / cap) * tightness * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits into post residual, reward this placement
    if nx > 0.0 && nx <= pr {
        let fill_next = nx / pr.max(1.0);
        score -= 8.0 * fill_next * (1.0 - progress * 0.5);
    } else if nx > 0.0 {
        // penalize leaving residual that cannot host the next item
        score += 3.0 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - progress) - 2.0 * dev;

    // New-bin candidate: penalize mildly, relax late in the stream or when many bins open
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress - 0.3 * open_bins_count as f64;
        if nx > 0.0 && nx >= 0.5 * cap {
            score -= 4.0; // big next item: fresh bin may be wise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item granularity classes are more reusable than "odd" dead space.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: heavily reward
    } else if pr <= 10 {
        -8.0 // small residue is usually still fillable
    } else if pr % 10 == 0 {
        -12.0 // round residual aligns with typical item sizes
    } else if pr % 5 == 0 {
        -6.0
    } else {
        4.0 // odd dead space penalty
    };
    score += class_bonus;

    // Lookahead coupling: strongly reward residuals that can host next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0 + 0.05 * (pr - next_item_size) as f64;
        } else {
            // residual cannot host next item -> dead space risk
            score += 8.0 + 0.10 * (next_item_size - pr) as f64;
        }
        // exact match with next item is ideal
        if pr == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when existing
    // bins are truly bad (their scores will exceed this unless very wasteful).
    if bin_residual == bin_capacity {
        score += 45.0 + 0.25 * open_bins_count as f64;
    } else {
        // Mild reward for packing into already-open bins, scaled by stream
        // progression (pack tighter toward the end).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 + 5.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting
    // outliers); mean-residual deviation penalty.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Integer-division threshold: bins where item fills >= half of residual
    // are good placements.
    if item_size * 2 >= bin_residual && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0; // dead space of 1..9 is nearly worthless
        } else if pr < 20.0 {
            score += 25.0 * (20.0 - pr) / 10.0; // small gap, hard to reuse
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 50.0;
        }
    } else {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but slightly favor tighter-than-mean bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs() + 0.05 * dev;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let left = post_residual - next_item_size;
            if left < 10 {
                score += 15.0; // would create new dead space
            } else {
                score -= 10.0 * (left as f64 / post_residual as f64);
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // New-bin candidate: keep it attractive only when current bins are tight.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.2;
        if tight {
            score -= 20.0;
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space quadratically
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain fit: this bin will be perfectly filled next step
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item will NOT fit here: penalize leaving residual that only a new bin handles
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless post_residual is huge usable space
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow opening new bin if current item is small and lookahead is large
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Slight preference to fill bins with many open bins (reduce spread)
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // small unusable slivers are wasted capacity
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With several options, prefer bins whose residual is closest to item size.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for hogging space it needs.
            score += 6.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer filling bins
    // with large residuals (reduce fragmentation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.35 * residual_gap;

    // Time horizon: late in the stream, avoid opening new bins; favor existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins open.
        score += 25.0 + 45.0 * progress + 1.5 * open_bins_count as f64;
        // But allow opening a new bin early when current bins would leave big dead space.
        if post_residual < 20 && progress < 0.4 {
            score -= 30.0;
        }
    } else {
        score -= 8.0 * progress;
    }

    // Slight preference for bins with larger residual overall (keep small-residual
    // bins for small items later).
    score += 0.10 * bin_residual as f64;

    // Cap penalty when item barely fits (post_residual near 0 is ideal).
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear waste penalty: dead space hurts more as it becomes unusable
    let unusability = (post / cap).powi(3);
    score += 18.0 * unusability * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual) with a quadratic bonus
    score -= 25.0 * (1.0 - post / cap).powi(2);

    // Lookahead: penalize if post_residual can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 + 12.0 * (nxt - post) / cap;
        } else {
            score -= 4.0 * (post - nxt) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild pressure to prefer bins with below-mean residual (balance spread)
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Encourage consolidation into fewer bins early, more openness later
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New empty bin candidate: prefer it only when post_residual would be very small
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * (1.0 - post / cap).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic-like discount for very small dead space.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always best
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic class of post_residual: residues divisible by common small
    // item sizes (10, 20, 25) are more reusable -> reward them.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0;
    }
    if pr % 20 == 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 {
        score -= 3.0;
    }
    // Penalize "awkward" residues in (0,10) that no realistic item can use.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }
    // Integer-division dead-zone: pr in [60, 69] wastes more than half a bin.
    if pr >= 60 {
        score += (pr - 60) as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 60.0;
        } else if next_item_size > pr {
            // Next item won't fit here anyway; slight penalty if we leave
            // a large stranded residual.
            if pr >= 20 && pr < 40 {
                score += 8.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits the item,
    // using it avoids opening a new bin -> reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline score.
    // Prefer opening a new bin only when all open-bin fits are sloppy.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // (late in the stream, fewer future items -> cheaper to reuse).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 70.0 + 30.0 * (1.0 - progress);
        // If many bins are already open, reusing them is cheaper.
        new_bin_score += open_bins_count as f64 * 2.0;
        // If mean residual is high, open bins have plenty of room -> reuse.
        new_bin_score += mean_residual * 0.4;
        // If the next item is huge, a fresh bin preserves flexibility.
        if next_item_size >= 70 {
            new_bin_score -= 25.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (1..10) are wasted space. Penalize them heavily, with a smooth
    // ramp that peaks when the gap becomes truly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual as i32) as f64;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else {
        // Usable leftover: mild reward proportional to how well the item
        // fills the bin (prefer tight fits over loose ones).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio;
    }

    // Last chance: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one
    // and encourage consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open with slack.
        score += 10.0 + 2.0 * pressure;
        // But if the next item could combine with this one in a fresh bin,
        // slightly soften the penalty.
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score -= 5.0;
        }
    } else {
        // Reward placing into already-open bins, scaled by open-bin pressure.
        score -= 3.0 + pressure.min(15.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (creates a perfect follow-up slot).
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // Next item still fits here: mild reward.
        score -= 5.0;
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a good pool of partial bins; late in the stream, consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    } else {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but penalize dead space
    // that is too small to ever be useful (below minimum item size 1... use
    // a soft threshold around 10-15% of capacity).
    let dead_threshold = bin_capacity as f64 * 0.12;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Unusable sliver: heavily penalize.
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly or
    // closely matches the next item size (chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            // Perfect chain: next item exactly fills this bin.
            score -= 60.0;
        } else if post_residual >= next_item_size && diff <= 10.0 {
            // Next item nearly fills this bin: strong reward scaled by closeness.
            score -= 40.0 * (1.0 - diff / 10.0);
        } else if post_residual < next_item_size {
            // Next item cannot fit here: mild penalty proportional to gap,
            // but only if post_residual is still usable for others.
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: purely minimize waste.
        score = post_residual as f64;
    }

    // Compare against mean residual: placing into a bin whose residual is
    // far below average preserves larger residuals for future items.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: the empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the item is large relative to capacity
    // and few bins are open, or when post_residual would be a large awkward gap.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: its post_residual is large.
        // Penalize opening new bins when many bins are already open and
        // the item fits reasonably elsewhere.
        score += 15.0 * (open_bins_count as f64).ln().max(0.0);
        // Reward opening a new bin early in the stream (more future items
        // benefit from a fresh bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If the item is large (>= 60% of capacity), a fresh bin is natural.
        if item_size * 10 >= bin_capacity * 6 {
            score -= 15.0;
        }
        // If lookahead item is large too, fresh bin keeps flexibility.
        if next_item_size * 10 >= bin_capacity * 6 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fills (no dead space).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: strongly prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= next_item_size as f64 * 0.35;
        } else {
            // leftover too small for the next item -> penalize proportional to wasted potential
            score += next_item_size as f64 * 0.25;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: mildly penalized by default, and more so when
    // existing bins still carry plenty of residual capacity.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.4 * open_bins_count as f64 + 0.06 * mean_residual;
        // Opening a fresh bin is more attractive early in the stream (room to consolidate later).
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (1.0 - t);
    }

    // Global pressure: when many open bins exist with high mean residual,
    // push harder toward filling existing bins tightly (amplify residual cost).
    let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    score *= 1.0 + 0.25 * pressure;

    // Time horizon: later in the stream, dead space becomes costlier.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * t * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let mut score = r;

    // Non-linear polynomial coupling of post-residual with stream progress
    score += 30.0 * rn * rn * (1.0 + progress);
    score -= 20.0 * (rn * (1.0 - rn)) * (1.0 - progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (r - mean_residual) / cap;
    score += 15.0 * dead * dead * cap;

    // Reward tight fits when this is the last fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - rn) * (1.0 - rn);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = (r - nx).abs() / cap;
        score += 12.0 * compat * compat * cap - 8.0 * (1.0 - compat);
    }

    // Mild penalty for bin proliferation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals in [1,10] are prime dead-space territory; multiples of 10 are ideal.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0; // clean class, likely reusable
    } else if pr < 10 {
        score += 25.0; // dead space
    } else if pr % 10 <= 3 {
        score += 8.0;  // awkward small class
    } else if pr % 10 >= 7 {
        score -= 4.0;  // near next decade class, decent
    }

    // Lookahead coupling: if next item fits the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let fit_quality = (next_item_size as f64 / pr as f64).min(1.0);
            score -= 20.0 + 25.0 * fit_quality;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 6.0 + 0.15 * (next_item_size as f64 - pr as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin is crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).ln().max(0.0);
        score += 45.0 - 10.0 * pressure;
        if item_size >= 50 {
            score -= 15.0; // big items start fresh bins happily
        }
    }

    // Prefer tighter fits overall: reward small post_residual relative to capacity.
    score -= 10.0 * (1.0 - pr as f64 / bin_capacity as f64);

    // Mild preference to fill bins with high residual when many bins are open.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early stream: be slightly conservative (keep flexibility), late stream: pack tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (pr as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps below ~10 are worthless)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (waste minimization)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if next item nearly fits but leaves a dead gap
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when current bins are very full / fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual < 25.0 {
            score -= 15.0; // open bins nearly full -> new bin is good
        } else {
            score += 20.0 + fragmentation * 0.1; // discourage opening when space exists
        }
    }

    // Late in stream: be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: prefer small post_residual.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Perfect-fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead matching: reward when the leftover space exactly
    // matches the next item, or when it leaves a still-usable gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // chain fill: next item closes this bin perfectly
        } else if post_residual >= next_item_size {
            // leftover can host next item: mild bonus proportional to tightness
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space relative to next size
            let waste = post_residual as f64 / (next_item_size as f64 + 1.0);
            score += 60.0 * waste.min(3.0);
        }
    }

    // Compare against mean residual: placing into a bin already tighter than
    // average is good (concentrating waste), loose bins get a penalty.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 15.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 80.0;
        // More open bins => prefer reusing them, penalize opening another.
        score += open_bins_count as f64 * 5.0;
        // If many bins fit the item, opening a new bin is clearly worse.
        if fitting_bins_count > 1 {
            score += 120.0;
        }
        // If next item is large and this item is small, a fresh bin may be
        // worth it (reserve space): slight discount.
        if next_item_size > item_size * 2 {
            score -= 30.0;
        }
    }

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few items could still use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: reward if the next item fits into the post-residual (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward if next item also fills it tightly
            let chain_tight = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * chain_tight * chain_tight;
        } else if next_item_size <= post_residual + 10 {
            score += 3.0; // near-miss chain: mild penalty for blocking good chains
        }
        // If next item cannot fit anywhere in this bin, slightly deprioritize
        // bins that would leave a large awkward residual.
        if next_item_size > post_residual && post_residual > 0 {
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing
    // existing capacity over opening new bins.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 6.0 * pressure;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early in
    // the stream or when the current item is huge and would leave a bad residual
    // in any existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = (bin_residual - item_size) as f64;
        // Prefer new bin when item is large relative to capacity (would fragment
        // existing bins badly) or late in stream when open bins are fragmented.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 20.0;
        let late_bonus = progress * 5.0;
        let fragment_penalty = if post_residual > 0 && post_residual < 15 { 10.0 } else { 0.0 };
        score -= large_item_bonus + late_bonus - fragment_penalty;
        // If many open bins exist with small residuals, discourage hoarding new bins.
        score += 0.15 * open_bins_count as f64 * (1.0 - pressure);
        // Perfect-fit item in a fresh bin is fine (waste_elsewhere == 0 handled naturally).
        let _ = waste_elsewhere;
    }

    // Mild preference for bins with below-mean residual (consolidate fuller bins,
    // keep emptier bins flexible for future items).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 4.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, but its value depends on stream progress.
    // Early on, large residuals are fine (bins stay flexible); later, waste is costly.
    let mut score = pr * (0.5 + 0.9 * progress * progress);

    // Non-linear coupling: penalize residuals near awkward mid-range sizes
    // (dead space that future items likely can't use), reward near-zero waste.
    let mid = 0.35 + 0.15 * progress;
    score += 8.0 * (pr_norm - mid) * (pr_norm - mid) * (1.0 - progress * 0.5);

    // Tight fit reward: smooth polynomial in item_norm * pr_norm complement.
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * (1.0 - tightness);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.3);
    }

    // New-bin candidate handling: empty bin gets a moderate baseline score;
    // it should win only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 60.0 + 20.0 * progress - 2.0 * item_norm * 10.0;
        // If this item is huge, opening fresh is relatively attractive.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 10.0 * (1.0 - gap / cap) * (1.0 - progress * 0.4);
        } else {
            // Next item won't fit here: penalize slightly more as stream advances.
            score += 4.0 * progress;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * (pr / cap);

    // Deviation from mean residual: prefer bins that are either much fuller
    // or keep the ensemble balanced, with smooth weighting by progress.
    score += 2.5 * (pr - mean_residual) / cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: fraction of capacity wasted after placement.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // Harmonic classes: bucket post_residual into residue classes mod 10.
    // Residuals that are "dead" (small but nonzero, hard to fill later) get penalized.
    let class = post_residual % 10;
    let dead_penalty: f64 = match class {
        1..=9 => {
            // dead space severity grows as residual shrinks below typical small item (~10-30)
            if post_residual < 30 { 8.0 + (30 - post_residual) as f64 * 0.6 } else { 1.0 }
        }
        _ => 0.0,
    };
    score += dead_penalty;

    // Perfect fill reward (integer division threshold on post_residual)
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // prefer bins that are relatively emptier among many candidates
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score += 0.15 * next_waste;
        } else {
            // next item won't fit here: slight penalty for creating awkward residual
            score += 2.0;
        }
    }

    // New-bin candidate handling: only attractive when no open bin is decent.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline: slightly worse than a perfect fit, better than large waste
        score = 35.0;
        // as stream progresses, discourage accumulating too many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // if other bins can fit, opening new bin should lose unless they waste a lot
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Mild density reward for filling large chunks of the bin
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // only usable by the smallest items
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with few open bins, prefer consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 8.0 * open_pressure;
    }

    // Prefer bins that are already tighter than average (best-fit flavor).
    let res_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * res_gap;

    // Lookahead: if next item fits into post_residual, bonus for chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item won't chain here
    }

    // New empty bin candidate: make it attractive only when it's genuinely better
    // than a poor fit; otherwise penalize mildly to prefer existing bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream when
        // future capacity is more valuable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 - 20.0 * progress;
        // If the item is large and no existing bin fits well, new bin is fine.
        if fill_ratio > 0.7 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: if the next item fits the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 25.0;
        if leftover <= 5 {
            score -= 20.0; // perfect two-item packing
        }
    } else if next_item_size > 0 {
        // Next item won't fit after this placement: penalize small dead space
        // that is too small to be useful (wasted capacity).
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual as f64 > mean_residual + 10.0 {
            score += 10.0;
        }
        // If next item could pair with the remainder, new bin is more acceptable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Late in stream: tighter packing matters more (fewer chances to fix).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Strongly reward perfect or near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item cannot use leftover space; penalize large dead space.
            score += (post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when item is large
    // (open bins would fragment badly) or many bins are already open.
    if bin_residual == bin_capacity {
        let large_item_bonus = fill_ratio * 70.0;
        let congestion = (open_bins_count as f64).ln().max(0.0) * 6.0;
        score += 55.0 - large_item_bonus - congestion;
        // Opening a bin late in the stream is cheaper (fewer future items to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Prefer bins with residual close to the item (best-fit flavor),
    // scaled against the global mean residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;
    score -= (mean_residual - bin_residual as f64).abs() * 0.05;

    // Mild preference for fuller bins among equals.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a convex penalty
    // that grows super-linearly for large wasted space.
    let norm_post = post / cap;
    let mut score = norm_post + 1.5 * norm_post * norm_post;

    // Smooth interaction: wasted space is more tolerable early in the stream,
    // increasingly costly as progress approaches 1.
    score -= 0.8 * norm_post * (1.0 - progress) * (1.0 - progress);

    // Penalize bins whose post-residual is close to but below the next item size
    // (dead space the lookahead item cannot use), smoothly via a squared gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt {
            let gap = (nxt - post) / cap;
            score += 2.0 * gap * (1.0 - progress);
        } else if post >= nxt {
            // Reward leaving room for the lookahead item (smooth bonus).
            let room = (post - nxt) / cap;
            score -= 0.5 * room * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 1.2 * scarcity * (1.0 - norm_post);
    }

    // Mild penalty for very fragmented state (many open bins with high mean residual)
    // to discourage spreading across too many bins late in the stream.
    let frag = (mean_residual / cap - norm_post).abs();
    score += 0.3 * frag * progress;

    // Slight preference for opening a new bin when item is huge relative to
    // residual (poor fit) — smooth in item/residual ratio.
    let ratio = item_size as f64 / (bin_residual as f64).max(1.0);
    score += 0.2 * ratio * ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * post_frac * post_frac;

    // Harmonic classes: reward when post_residual belongs to a "useful" residue class
    // (divisible into chunks that typical items 1..=100 can fill).
    let pr = post_residual as i64;
    if pr > 0 {
        // Small residuals (< 10) are dead space; strong penalty.
        if pr < 10 {
            score += 60.0;
        } else {
            // Reward residuals that are multiples of common item granularities.
            let mut harmony = 0.0;
            for m in [5i64, 10, 20, 25, 50] {
                if pr % m == 0 {
                    harmony += 8.0;
                }
            }
            score -= harmony;
            // Integer-division threshold: residuals expressible as sums of medium items
            let div = pr / 34;
            score -= 3.0 * div as f64;
        }
    } else if pr == 0 {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n <= pr {
            if n == pr {
                score -= 80.0;
            } else {
                // next item fits but leaves another residual; scale by resulting waste
                let next_post = pr - n;
                score -= 25.0 - (next_post as f64 / bin_capacity as f64) * 20.0;
                if next_post < 10 {
                    score += 15.0; // creates new dead space
                }
            }
        } else {
            // next item won't fit here: mild penalty if we'd strand this bin
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current fits are poor.
        // Base cost of a new bin, discounted by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 70.0 - 30.0 * progress;
        // If item is large relative to capacity, a fresh bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
    } else {
        // Prefer fuller bins (best-fit flavor): lower residual => lower score.
        score -= 20.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Spread load when many bins are open and mean residual is high:
    // encourage using bins with residual above mean.
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Slight preference for keeping open_bins_count low late in the stream.
    score += 0.5 * open_bins_count as f64 * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10) can
    // use are wasted. Penalize tiny unusable gaps heavily.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Last chance: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer compacting into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly into the post_residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving an awkward gap.
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when no reasonable fit exists among open bins; make the
    // empty bin score high unless the current bin would leave dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is costly; penalize more as stream progresses.
        score += 40.0 + 20.0 * progress;
        // But if placing here would create dead space anyway, soften.
        if (post_residual as f64) < dead_threshold && post_residual > 0 {
            score -= 25.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it is
    // already tight; prefer it slightly.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a perfect second fill.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let l2 = post_residual - next_item_size;
            if l2 <= 10 {
                score -= 250.0 - (l2 as f64) * 15.0;
            } else {
                // Next item leaves more dead space; penalize proportionally.
                score += (l2 as f64) * 0.8;
            }
        } else {
            // Next item cannot use the remaining space at all.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins whose residual is already below average (consolidate small leftovers).
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.6;
    } else {
        score += (resid_f - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // fits well (large dead space would be created elsewhere).
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins with decent fits win.
        score += 40.0;
        // But if the item is large relative to capacity, opening a fresh bin
        // is often better than fragmenting a partially filled one.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            score -= 120.0 * (fill_ratio - 0.6);
        }
        // Late in the stream, avoid spawning bins with tiny leftovers unused.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 30.0;
        }
    }

    // Mild pressure to keep the number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1)
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Detect the brand-new empty bin candidate
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is generally wasteful: penalize it.
        // The penalty shrinks late in the stream when closing out is fine,
        // and grows when many bins are already open (fragmentation risk).
        let mut penalty = 12.0 + 0.15 * open_bins_count as f64;
        // Late in the stream, slightly more willing to open a bin
        penalty *= (1.0 - 0.5 * progress);
        // If the next item is large, a fresh bin preserves flexibility:
        // reward (subtract) a bit when next_item_size is big.
        let flexibility = next_item_size as f64 / bin_capacity as f64;
        penalty -= 4.0 * flexibility * (1.0 - progress);
        // If this bin is the only fitting option elsewhere is unknown here,
        // but if many bins fit, opening new is clearly worse.
        penalty += 0.5 * fitting_bins_count as f64;
        score += penalty;
    } else {
        // Reward tight fits: post_residual already captures leftover space.
        // Extra reward for near-perfect packing (post_residual small).
        if post_residual == 0 {
            score -= 6.0; // perfect fill is excellent
        } else if post_residual < 10 {
            score -= 3.0; // very tight fit
        }

        // Penalize creating dead space that likely can't fit future items.
        // If post_residual is smaller than the smallest plausible item (1),
        // it's dead space; scale penalty by how "orphaned" the residual is.
        if post_residual > 0 {
            let orphan = (post_residual as f64 / bin_capacity as f64).powf(2.0);
            score += 2.0 * orphan;
        }

        // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer it
        // over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        } else if fitting_bins_count == 2 {
            score -= 3.0;
        }

        // Lookahead coupling: if the next item fits exactly in post_residual,
        // this placement sets up a perfect follow-up — reward it.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 5.0;
            } else if post_residual >= next_item_size {
                score -= 1.5;
            } else {
                // Next item won't fit here afterward; mild penalty for
                // stranding the bin unless the residual is tiny.
                if post_residual >= 10 {
                    score += 1.0;
                }
            }
        }

        // Global state: prefer filling bins whose residual is below the mean
        // (consolidate small leftovers), especially early/mid stream.
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;

        // Slight preference for bins with larger residuals early on
        // (best-fit behavior already dominates via post_residual).
        score -= 0.02 * bin_residual as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    let mut score = x * (2.0 - progress) * cap;

    // Smooth non-linear coupling: large post residuals are more tolerable early,
    // small residuals (tight fits) are rewarded more strongly late.
    score -= (1.0 - x) * (1.0 - x) * 30.0 * (0.5 + progress);

    // Dead-space term: cubic in normalized residual, penalizes mid-range waste.
    score += x * x * (1.0 - x) * 12.0 * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress) + 10.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack) * (0.4 + 0.6 * progress);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidation.
    let crowd = open_bins_count as f64;
    score += (mean_residual / cap) * (crowd / (crowd + 5.0)) * 8.0;

    // New-bin candidate: mild penalty so we only open when truly better.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress - 8.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class: small dead space thresholds (mod arithmetic on post_residual)
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // unusable sliver
    } else if pr == 10 || pr == 20 || pr == 25 || pr == 50 {
        score -= 40.0; // reusable harmonic class residual
    }

    // Fraction-of-capacity classes for post residual
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 {
        score += 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual - next_item_size == 0 {
            score -= 120.0;
        } else if (post_residual - next_item_size) % 10 == 0 {
            score -= 50.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // next item cannot use this residual -> dead space penalty scaled by class
        let class = post_residual % 10;
        score += 20.0 + class as f64 * 2.0;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New bin candidate handling: penalize opening a new bin unless residual is tiny
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0;
        }
    }

    // Prefer fuller bins (tight packing) via integer division thresholds
    let fill_class = (bin_capacity - bin_residual) / 25; // 0..4
    score -= fill_class as f64 * 8.0;

    // Stream progression: early on, be pickier about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mild penalty for too many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 6.0;
    }
    // Mid-range gaps slightly penalized too (hard to fill later).
    if post_residual >= 15 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // If the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item can't fit in post-residual but post-residual is small, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage proliferation of bins,
    // but only when this is an existing bin (not the new-bin candidate).
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Opening a new bin: penalize mildly when few bins open, more when many.
        score += 3.0 + 0.15 * open_bins_count as f64;
        // If many bins can already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins with below-average residual (concentrate waste in few bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual closely
    // matches the next item's size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Exact match for the next item is highly desirable.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize leftover dead space.
        score += 10.0;
    }

    // Prefer bins with residual below the mean (tighter, more filled bins),
    // penalize bins that are unusually empty relative to the mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (waste fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: only attractive when the item leaves a large,
    // reusable residual and existing bins are poor fits; otherwise keep
    // score high so open bins are preferred.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing can fill (item sizes >= 1).
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 15.0; // near-perfect fill, very desirable
        } else {
            score += (post_residual as f64).sqrt() * 2.0;
        }
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize wasting space on a big hole.
        score += 8.0;
    }

    // Global state: with many open bins, prefer consolidating into existing ones.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    score += open_pressure * 20.0;

    // Prefer bins whose residual is below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin, more so early on and
    // when other bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 45.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 25.0 * fitting_bins_count as f64;
        }
        // Late in stream, opening bins is more acceptable (less future waste risk).
        new_bin_penalty *= (1.0 - 0.5 * progress);
        score += new_bin_penalty;
    }

    // Slight preference for bins with larger residual when item is small
    // (save tight bins for big items).
    if item_size < 30 && bin_residual != bin_capacity {
        score += (100 - bin_residual.min(100)) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_n = pr / cap;

    // Base: prefer small post-residual (tight fit), non-linearly
    let mut score = pr * (1.0 + 0.8 * pr_n * pr_n);

    // Smooth stream-progress coupling: early on, tolerate slack; later, punish it
    let prog_term = 1.0 + 1.5 * progress * progress;
    score *= prog_term;

    // Reward bins whose residual aligns with the next item (lookahead)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= 20.0 * (-diff * diff * 40.0).exp();
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Penalize deviating far from mean residual (keeps bins balanced)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // capacity fraction

    // Penalize dead space in low harmonic classes (small residuals that nothing fits)
    if post_residual > 0 {
        let class = post_residual % 10; // decade harmonic class
        if class != 0 {
            score += (10 - class) as f64 * 0.6; // uneven residuals are less reusable
        }
        if post_residual < 10 {
            score += 40.0; // unusable dead space
        }
    } else {
        score -= 25.0; // perfect fit: harmonic zero
    }

    // Integer division thresholds on post_residual
    let half = bin_capacity / 2;
    if post_residual > half {
        score -= 12.0; // still roomy bin, good
    } else if post_residual <= half && post_residual > bin_capacity / 4 {
        score += 4.0;
    }

    // Coupling with lookahead: reward residual that harmonizes with next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish: reward closeness to zero gap
            let gap = post_residual - next_item_size;
            score -= 18.0 * (1.0 - gap as f64 / cap_f);
            // harmonic alignment: gap in small modulo class is great
            if gap % 5 == 0 { score -= 6.0; }
        } else {
            score += 8.0; // next item won't fit here regardless
        }
    }

    // Last-chance bin: strong reward to use it, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_tightness = mean_residual / cap_f;
        // open new bin only if mean residual is small (bins nearly full)
        score += 30.0 * (1.0 - avg_tightness) + 10.0 * (1.0 - progress);
        // avoid hoarding many open bins
        score += open_bins_count as f64 * 1.5;
        // but if item is large and would leave tiny residual in any bin, new bin is fine
        if item_size > bin_capacity * 7 / 10 {
            score -= 15.0;
        }
    }

    // Prefer fuller bins: residual fraction penalty (best-fit bias with harmonic twist)
    score += frac * 15.0;

    // Modulo coupling: if item_size divides capacity harmonically, prefer exact fills
    if bin_capacity % item_size == 0 && post_residual % item_size == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is too small for even the smallest plausible item.
    let min_useful = 12u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 90.0 * (min_useful - post_residual) as f64;
    }
    // Mid-range gaps that cannot fit the lookahead item are also dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // a brand-new empty bin candidate gets a baseline penalty that grows with open count.
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * open_bins_count as f64;
    } else {
        // Slight preference to fill already-open bins, stronger when many are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Early in the stream, allow more liberal bin usage; later, be conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is near the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // If lookahead fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post_residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can still follow into this bin: mild reward scaled
            // by how snugly the follow-up fits.
            let snug = 1.0 - gap / (bin_capacity as f64);
            score -= 15.0 * snug;
        } else {
            // Next item cannot follow: penalize proportionally to wasted
            // potential relative to mean residual.
            score += 10.0 * (post_residual as f64 / mean_residual.max(1.0)).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving residuals that are small but unusable (dead space
    // below the typical minimum item footprint).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer filling bins that are already below-average residual
    // (consolidation): keeps many high-residual bins available.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Early in the stream, be slightly more willing to spread out
    // (open bins) to build a good pool of residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless nothing else fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 55.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual likely dead space if next item can't use it.
        score += 6.0;
    }

    // Perfect fit gets a decisive bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the
    // item is large and residuals are small (better to start fresh).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let fresh_benefit = (item_size as f64 / bin_capacity as f64) * (1.0 - mean_r / bin_capacity as f64);
        let open_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
        score += 45.0 - 40.0 * fresh_benefit + open_pressure;
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (larger-than-mean residual bins are more reusable targets for
        // medium items; smaller residuals should be filled by big items).
        let dev = bin_residual as f64 - mean_residual;
        if item_size >= 50 {
            score -= 0.15 * dev;
        } else {
            score += 0.15 * dev;
        }
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, pack greedily into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) shaping
    let mut score = pr + 20.0 * pr_norm * pr_norm;

    // Smooth interaction: as stream progresses, penalize residual more (dead space matters later)
    score += 15.0 * pr_norm * pr_norm * progress;

    // Reward tight fits (small post residual relative to item size)
    let tightness = 1.0 - (pr / (item_size as f64 + 1.0));
    score -= 10.0 * tightness.max(0.0) * (1.0 - progress);

    // Penalize bins whose residual deviates strongly from mean residual (imbalance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalize leaving residual that can't host next item, scaled by dead-space size
        score += 6.0 * pr_norm * (1.0 - progress);
    }

    // New-bin candidate: make it attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        score = cap - fit_ratio * 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are hard to fill later get penalized.
    let pr = post_residual;
    let class = if pr == 0 { 0 } else if pr <= 10 { 1 } else if pr <= 25 { 2 } else if pr <= 50 { 3 } else { 4 };
    score += match class {
        0 => -30.0,                      // perfect fit, strongly favored
        1 => 25.0,                       // tiny dead space, very bad
        2 => 5.0,                        // moderate waste
        3 => -5.0,                       // half-ish residual, still usable
        _ => 0.0,
    };

    // Integer-division thresholds: residual divisible into likely chunks is good.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
    }

    // Pairing with lookahead item: reward residuals that next item can nearly fill.
    if next_item_size > 0 && pr >= next_item_size {
        let nxt = next_item_size as f64;
        let tight = (pr as f64 - nxt) / cap; // 0 = perfect pairing
        score -= 18.0 * (1.0 - tight).min(1.0);
    }
    // Penalize leaving residual that is smaller than next item but nonzero.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // baseline cost of a fresh bin: capacity minus item
        score = cap - item_size as f64 + 15.0;
        // if many bins fit the item, opening new bin is wasteful
        score += fitting_bins_count as f64 * 6.0;
        // early in stream, prefer opening bins to build diversity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if item leaves large residual in any open bin anyway, new bin is fine
        if post_residual >= 50 { score -= 6.0; }
    } else {
        // Prefer bins whose residual deviates favorably from mean residual
        // (use tighter bins first to consolidate).
        score -= 0.15 * (mean_residual - bin_residual as f64);
        // Mild pressure to reduce number of open bins.
        score += open_bins_count as f64 * 0.05;
    }

    // Small jitter-free tie-break: prefer larger items placed into fuller bins.
    score -= 0.01 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..=item_min) are unusable if they can't
    // hold the smallest plausible future item. Penalize them heavily.
    let dead_threshold: f64 = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize wasting a large residual on a small item when post_residual
    // remains large but awkwardly split (fragmentation risk).
    if pr > 40.0 {
        score -= 5.0; // large leftover is still flexible, mild reward
    } else if pr >= dead_threshold {
        // medium gap: usable only for small items, slight penalty
        score += 3.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large or current bins would leave heavy dead space.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - pr;
        if mean_gap > 20.0 && open_bins_count > 0 {
            score += 20.0; // existing bins fit poorly -> discourage new bin? no:
            // actually if mean residual is large, existing bins have room, so
            // opening new bin is wasteful.
        }
        if open_bins_count == 0 {
            score -= 10.0;
        }
        // Prefer new bin for large items that would leave tiny dead space anyway.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 15.0;
        }
    }

    // Progress-based mild tightening: later in the stream, be greedier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 0.5 * bin_capacity as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits: penalize leftover waste after the hypothetical next placement.
            let waste_after_next = (post_residual - next_item_size) as f64;
            score += waste_after_next * 0.15;
        } else {
            // Next item won't fit: penalize leaving a large unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Penalize deviations from the mean residual (prefer balanced bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins early in the stream; allow it later when bins fragment.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin.
        score = bin_capacity as f64 * 0.8 - progress * 20.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0; // definitely need a new bin
        }
        if fitting_bins_count > 2 {
            score += 10.0; // plenty of alternatives, new bin less costly
        }
    }

    // Slight preference for bins with larger residuals when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
