    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 4.0;

    // Penalize bins far below mean residual (fragmented bins) slightly.
    let res_f = bin_residual as f64;
    if res_f > mean_residual + 1.0 {
        score += 0.05 * (res_f - mean_residual);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity && bin_residual > 0 && item_size < bin_capacity {
        // base cost of a new bin; reduced late in the stream when open bins are fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64).min(1.0);
        score += 35.0 - 12.0 * fragmentation - 6.0 * progress;
    }

    // Slight time-dependent exploration noise-free bias: favor tight fits more as stream ends.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: small post-residuals are good, but tiny residuals
    // that can never fit future items (min size 1) are dead space; reward tight fits.
    let pr_norm = pr / cap;
    score += 4.0 * pr_norm * pr_norm * cap * 0.1;

    // Smooth stream-progress coupling: later in the stream, tighten packing more
    // aggressively (favor low post_residual) since fewer chances remain to consolidate.
    score -= (1.0 - progress) * 2.0 * pr_norm * cap * 0.05;
    score += progress * 3.0 * pr_norm * pr_norm * cap * 0.05;

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_slack = (post_residual - next_item_size) as f64;
        score -= 6.0 + 4.0 * (1.0 - fit_slack / cap);
    } else if next_item_size > 0 {
        // Penalize residuals that strand the next item.
        score += 3.0 + 5.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the empty-bin candidate smoothly by how much
    // residual would be wasted relative to current mean residual across open bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * mean_residual + 2.0 * (open_bins_count as f64);
        // Allow opening a new bin late in the stream or when mean residual is tiny
        // (existing bins are nearly full anyway).
        score -= progress * 8.0 + (cap - mean_residual).max(0.0) * 0.05;
    }

    // Mild preference for reusing bins with residual close to mean (balance open bins).
    let dev = (pr - mean_residual).abs();
    score += 0.02 * dev;

    // Slight bonus for filling a large fraction of the bin with this item.
    score -= 5.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity/10 (i.e., mod 10).
    let r10 = post_residual % 10;
    // Dead space penalty: residuals not divisible by 10 are "harmonically off"
    // and harder to fill with typical items; penalize by class.
    let harm_pen = match r10 {
        0 => 0.0,
        5 => 1.5,
        1 | 9 => 4.0,
        2 | 8 => 6.0,
        3 | 7 => 8.0,
        _ => 10.0,
    };
    score += harm_pen * (1.0 + post_residual as f64 / bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item exactly fills the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Prefer leaving a residual in a "good" harmonic class for the next item.
            let nxt = post_residual - next_item_size;
            if nxt % 10 == 0 {
                score -= 12.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot fit here; penalize tight residuals slightly.
            score += 5.0;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is small relative
    // to capacity and open bins are already crowded with small residuals.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = mean_residual / bin_capacity as f64;
        score = 100.0 - 20.0 * frac - 30.0 * pressure;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small to hold any plausible future item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        // Perfect fit is excellent: subtract a bonus.
        score -= 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderately usable gap: mild penalty proportional to waste.
        score += (20.0 - post_residual as f64) * 0.5;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when this item leaves a large residual everywhere else.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced early in the stream
        // and when mean residual across open bins is large (poor fits there).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 35.0 + open_bins_count as f64 * 1.5;
        new_bin_score -= mean_residual * 0.25;
        new_bin_score -= (1.0 - progress) * 5.0;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            new_bin_score -= 10.0;
        }
        if new_bin_score < 0.0 {
            new_bin_score = 0.0;
        }
        score = new_bin_score;
    }

    // Lookahead coupling: prefer leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fit (post_residual == 0 is perfect).
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement is part of a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves slack: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative residual vs. mean residual: prefer bins that are tighter than average
    // (packing into fuller bins keeps loose bins available for larger future items).
    score += 4.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If many bins are open, opening yet another one fragments capacity further.
        score += 0.5 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper; late in the stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= item_size {
            score -= 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize dead space that is too small to be useful for future items
    // (typical item sizes 1..100; residual < 10 is nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: if this bin's residual deviates far
    // below mean, it's a "small hole" — prefer using it up.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Time horizon: late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: make it moderately attractive only when current
    // fit is poor (large post_residual) and many bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score -= 8.0 * poor_fit * poor_fit;
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.9 * (pr / cap) * (pr / cap));

    // Smooth stream-progress coupling: tighten preference as stream advances
    score *= 1.0 + 0.5 * progress * (pr / cap);

    // Reward if the lookahead item fits into the post residual (smooth sigmoid-like gate)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (1.0 - (pr - nxt) / cap).clamp(0.0, 1.0);
        let bonus = if nxt <= pr { 12.0 + 8.0 * (1.0 - (pr - nxt) / cap) } else { -6.0 * fits };
        score -= bonus;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr / cap);
    } else if fitting_bins_count > 1 {
        // mild competition bonus, stronger when many alternatives exist
        score += 2.0 * ((fitting_bins_count as f64).ln());
    }

    // Penalize opening a brand-new bin when decent fits exist
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        let penalty = 18.0
            + 10.0 * (1.0 - (mean_gap / cap).clamp(0.0, 1.0))
            + 8.0 * (1.0 - progress);
        score += penalty;
        if next_item_size as f64 > pr {
            score += 6.0;
        }
    }

    // Slight preference for bins with residuals near the mean (balanced packing)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quarters / eighths classes: residual in a "dead zone" (small but unusable) is penalized.
    let eighth = cap / 8.0;
    let quarter = cap / 4.0;
    let half = cap / 2.0;

    if pr > 0.0 && pr < eighth {
        // Tiny unusable sliver: excellent packing (no future item fits anyway).
        score -= 30.0;
    } else if pr >= eighth && pr < quarter {
        // Medium-small residual: only very small next items can use it.
        score -= 10.0;
    } else if pr >= quarter && pr < half {
        // Mid residual: partially reusable.
        score += 5.0;
    } else if pr >= half && pr < cap {
        // Large residual: wasteful placement, penalize.
        score += 25.0;
    }

    // Integer-division harmonic classes on post_residual (buckets of 12).
    let bucket = post_residual / 12;
    score += (bucket % 4) as f64 * 3.0;

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item could use this residual: mildly penalize consuming it now
            // unless this placement is near-perfect.
            let waste_ratio = pr / cap;
            score += 12.0 * (1.0 - waste_ratio);
        } else {
            // Next item cannot use leftover: residual is dead weight; reward tight fits.
            score -= 8.0;
        }
        // Harmonic mod-5 class of next item size relative to residual.
        let ncls = next_item_size % 5;
        if ncls == 0 && next_item_size > post_residual {
            score -= 4.0; // round next item won't fit here anyway; free to fill now
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how many bins already fit.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        score = cap as f64 * 0.9 + 15.0 * open_pressure * (0.5 + 0.5 * progress);
        if fitting_bins_count == 0 {
            // No existing bin fits: new bin is mandatory, make it cheap.
            score -= cap as f64;
        }
        if fitting_bins_count == 1 {
            // Existing last-chance bin exists; keep new bin expensive.
            score += 10.0;
        }
    }

    // Slight preference for bins whose residual deviates from mean (concentrate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild load-balancing pressure via open bin count.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1) are pure waste.
    // Penalize "unusable" gaps hard — anything below the smallest plausible future item.
    let dead_threshold = 3u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 40.0 * (dead_threshold as f64 - post_residual as f64 + 1.0);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize leaving a gap that barely misses the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 10.0 {
            score += 8.0 * (10.0 - gap) / 10.0; // near-miss penalty
        }
    }
    // Reward a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins whose residual is already below average (they are "nearly full").
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins would waste a lot
    // (large post_residual in an open bin is fine, but a fresh bin is a clean slate).
    if bin_residual == bin_capacity {
        // Mild penalty so a decent existing fit wins; scale down as stream progresses
        // and consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 300.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);
    }

    // 2-step lookahead: if next item fits perfectly into the post residual,
    // this placement chains into a perfect fill.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - chain_slack / bin_capacity as f64).powi(4);
        } else {
            // Next item cannot use this residual; penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 40.0 * (waste / bin_capacity as f64);
        }
    }

    // Compare post residual to the mean residual across open bins:
    // prefer bins that end below-average (tight packing), penalize above-average.
    score += 1.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Mild penalty for opening a new bin when plenty of bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    // Early in the stream, be slightly more willing to open bins (future flexibility).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize small unusable residuals (< 10 or < next item size) — dead space.
    let dead_threshold = 10.0f64.min(next_item_size as f64);
    if (post_residual as f64) < dead_threshold {
        score += 18.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual, mildly if it fits at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted space.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last chance: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual below the mean residual (fill emptier-of-space bins first).
    score += 0.10 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for proliferating open bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate handling: an empty bin is only attractive when the fit is bad
    // (large post_residual) or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * (open_bins_count as f64);
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate slack; later, punish dead space quadratically.
    let p = 1.0 + 2.0 * progress;
    score += 60.0 * norm_post.powf(p) * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual) increasingly as stream advances.
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Penalize deviation from mean residual across open bins (balance load).
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual as f64 >= ns {
            let slack_after_next = post - ns;
            score -= 20.0 * (1.0 - slack_after_next / cap) * (1.0 + progress);
        } else {
            score += 12.0 * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * norm_post;

    // New-bin candidate calibration: an empty bin has moderate appeal early,
    // worse late (prefer filling existing bins).
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: residues that are "reusable" sizes
        // (multiples of common item sizes 10..=80 grid, i.e. multiples of 5)
        // are more likely to be filled by a future item.
        let r = post_residual;
        let harmonic_bonus = if r % 10 == 0 {
            6.0
        } else if r % 5 == 0 {
            3.0
        } else if r % 20 == 0 {
            8.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Dead space: post_residual smaller than the minimum item size (1) is fine,
        // but small nonzero residuals that no plausible item can use are waste.
        // Penalize residuals in the "awkward" band (1..=9) more strongly.
        if r < 10 && r > 0 {
            score += 12.0;
        }

        // If lookahead item fits exactly into post_residual, big reward.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Lookahead fits: reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill;
        } else if next_item_size > post_residual {
            // Lookahead cannot use this residual: mild penalty scaled by waste.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }

        // Fractional capacity coupling: reward placements that leave residual
        // near common capacity fractions (25, 50, 75) which are flexible.
        if r == 25 || r == 50 || r == 75 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current fit is poor or no real bins fit well.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64; // post_residual for new bin
        let pressure = if fitting_bins_count == 0 {
            200.0
        } else {
            (mean_residual - item_size as f64).max(0.0) * 2.0
        };
        // Opening a new bin costs ~one bin; make it competitive but not dominant.
        score = 95.0 + fit_quality * 0.3 - pressure + open_bins_count as f64 * 0.5;
    }

    // Slight preference for fuller bins as stream progresses (best-fit flavor).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps nonlinearly.
    // A post_residual that is too small to hold even the smallest plausible item (1)
    // is actually perfect packing; but gaps that fit nothing useful later are waste.
    if post_residual > 0 {
        // Dead-space penalty grows superlinearly as the gap shrinks into "junk" range.
        let junk_threshold = 12.0;
        if (post_residual as f64) < junk_threshold {
            score += (junk_threshold - post_residual as f64) * 3.0;
        }
        // Reward large remaining residuals mildly (keeps bins flexible).
        score -= (post_residual as f64).sqrt() * 1.5;
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 3 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for next item: potential dead space, penalize.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Open bins pressure: with many open bins, discourage opening/keeping more
    // fragmentation; favor filling existing bins.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if fitting_bins_count == 1 {
        // Last chance bin: strong reward to use it instead of opening a new bin.
        score -= 15.0 * pressure;
    } else {
        score += pressure * 1.2;
    }

    // New-bin candidate: opening a new bin should be costly unless current bins
    // would leave terrible dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 4.0;
    }

    // Mean residual context: if this bin's residual is far below mean (tight bin),
    // filling it is good.
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= tightness * 0.5;
    } else {
        score += (-tightness) * 0.3;
    }

    // Slight stream-progression bias: later in the stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual).
    let perfect_fit = (post_residual as f64 / bin_capacity as f64).powi(4);
    score -= 40.0 * (1.0 - perfect_fit);

    // Aggressive 2-step lookahead: if the next item can exactly fill the post
    // residual, this is an ideal chaining placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills remainder
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer post_residual slightly larger than next item; penalize big slack
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit in the leftover: dead space unless residual is small
            let waste = (next_item_size - post_residual) as f64;
            score += 10.0 * (waste / bin_capacity as f64);
            // But if post_residual is tiny, it's still a good squeeze
            if post_residual <= 10 {
                score -= 15.0;
            }
        }
    }

    // Compare against mean residual: bins already tighter than average are
    // good candidates to keep compacting.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 60 {
            score -= 25.0; // large items are fine to start fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits, must open
        }
        // Late in the stream, prefer closing out with tight packing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins with the smallest residual overall
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual in (0, 10) is nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement; if it almost fits, mildly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 15.0 * (1.0 - gap / 10.0);
            }
        } else {
            // Next item cannot use this residual: slight penalty proportional
            // to how much residual is stranded relative to next item.
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln1p() * (mean_residual / cap);
    score += pressure * 6.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins clean); late in the stream, squeeze everything in.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let base = 18.0 + 30.0 * (1.0 - progress) - 20.0 * crowding.min(1.0);
        score += base.max(2.0);
    }

    // Mild preference for bins whose residual is close to the item (best fit).
    let waste = (bin_residual - item_size) as f64;
    score += 0.05 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic penalty on post-residual (waste), modulated by stream progress.
    let mut score = x * (1.0 + 0.8 * progress) + 0.6 * x * x;

    // Reward tight fits more strongly as the stream progresses (bins get scarcer).
    let tightness = 1.0 - x;
    score -= 0.5 * tightness * tightness * (0.5 + progress);

    // Penalize residual far from mean residual (dead-space dispersion).
    let dev = (pr - mean_residual).abs() / cap;
    score += 0.3 * dev * dev;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else {
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            let slack = (pr as f64 - nx) / cap;
            score -= 0.4 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Residual cannot host next item: mild penalty scaled by progress.
            score += 0.3 * (0.5 + progress);
        }
    }

    // Prefer fewer open bins early (keep stream compact).
    score += 0.01 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with progress-scaled reluctance.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.6 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual % 10 == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space that cannot plausibly be filled later:
        // residual classes below the minimum item size are pure waste.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }
    }

    // Modulo-class coupling: does the leftover combine with the next item?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits exactly or leaves another small class residual.
        let nxt_post = post_residual - next_item_size;
        if nxt_post == 0 {
            score -= 70.0;
        } else if nxt_post <= 5 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item will not fit here: this residual is likely terminal.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowd penalty: with many open bins, tighten packing (prefer tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = (open_bins_count as f64).ln().max(1.0);
    score += crowd * (post_residual as f64 / cap) * (20.0 + 30.0 * progress);

    // Relative tightness vs mean residual: bins tighter than average are preferred.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New empty-bin candidate: only attractive when no reasonable fit exists.
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        // Base cost of opening a bin, discounted when current fit is poor.
        score += 120.0 - 150.0 * bad_fit + 40.0 * progress;
        // Opening is worse if the next item could have shared this bin later.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Integer-division threshold: residual buckets of capacity/2 get mild bonus.
    if post_residual >= bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    } else if post_residual <= 20 {
        // Small but potentially reusable gap: moderate penalty.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits proportionally (waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 15.0;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good; encourage closing bins out.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward
    // leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (fill the emptier-feeling bins with tight fits first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are terrible. Make the empty-bin score moderately high
    // but not prohibitive.
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
