        // Exact match for next item is excellent
        if post_residual == next_item_size {
            score -= 400.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that can't fit the next item
        score += 30.0;
    }

    // Penalize small unusable residuals (dead space) relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer tighter fits among open bins: penalize large residuals
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New bin candidate: make it attractive only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 50.0;
        if poor_fit {
            score -= 200.0;
        } else {
            score += 150.0;
        }
    }

    // Mild penalty for proliferating open bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (post_residual small relative to item size)
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score -= 12.0 / (1.0 + tightness);

    // Strong reward for exact fill
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if leftover pairs perfectly with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // leftover can still host next item: mild reward proportional to leftover usability
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
