    if bin_residual == bin_capacity {
        score += 55.0 + 0.35 * open_bins_count as f64 + 0.15 * mean_residual;
        // but if no existing bin fits well, relax the penalty
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Penalize bins whose residual deviates from mean residual (prefer balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time-dependent pressure: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Small penalty for very fragmented leftovers that nothing small can use
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
