    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates from mean residual (consolidation)
    score += 0.5 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: neutral-to-slightly-high score unless residuals are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress * (1.0 - progress) * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: bins whose residual is divisible by
    // common small item sizes (or their complements) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 5.0; }
        else { score += 4.0; }
        if pr < 10 { score += 25.0; } // unusable dead space under min size
    }

    // Lookahead coupling: reward residuals that exactly fit the next item's class
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 80.0;
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 { score -= 30.0; }
        } else {
            score += 8.0; // next item cannot use this residual
        }
        // modulo-class match between next item and residual
        if next_item_size % 10 == 0 && pr % 10 == 0 && pr >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score += 55.0 - 30.0 * crowding - 15.0 * progress;
        if open_bins_count == 0 { score -= 200.0; }
    }

    // Mild preference for fuller bins relative to mean residual
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: bins with residual in [item, item+9] are tight fits
    if bin_residual >= item_size && (bin_residual - item_size) / 10 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residuals too small to be useful for future items.
    // Threshold scales with lookahead: if next item could use the gap, it's not dead.
    let dead_threshold = if next_item_size > 0 && next_item_size <= post_residual {
        0 // gap usable by next item; no dead-space penalty
    } else if post_residual < 10 {
        1
    } else {
        0
    };

    if dead_threshold == 1 {
        // Unusable tiny gap: heavy penalty proportional to how much we "wasted".
        score += 60.0 + 2.0 * (post_residual as f64);
    }

    // Medium gaps (10..30) are risky: mildly penalize unless the next item fits.
    if post_residual >= 10 && post_residual < 30 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 8.0 + 0.3 * (30.0 - post_residual as f64);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing an existing bin unless it would create bad dead space.
        // Penalize opening a new bin moderately, scaled by how many bins already fit the item.
        score += 15.0 + 4.0 * (fitting_bins_count as f64).min(6.0);

        // If only one fitting bin exists and its residual is tight, opening a new
        // bin may be fine: reduce the penalty when the stream is early.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: too many open bins -> favor consolidating into existing bins.
    score += 0.5 * (open_bins_count as f64).min(20.0);

    // Prefer bins whose residual is close to what we consume (tight fit).
    score += 0.2 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    // Slight tie-break toward bins with lower residual (fill fullest bins first).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: small post_residual relative to bin capacity is good.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 50.0;

        // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size <= post_residual {
                // Next item fits: reward proportional to how snugly.
                let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
                score -= 100.0 + snug * 150.0;
            } else {
                // Next item does not fit here: penalize wasted residual that next item can't use,
                // scaled by how badly it misses.
                let miss = (next_item_size - post_residual) as f64;
                score += miss * 2.0;
            }
        }

        // Compare post_residual against mean residual across open bins:
        // leaving less than the mean is good (we consolidated space).
        score += (post_residual as f64 - mean_residual) * 0.5;

        // Last-chance bin: if this is the only bin that can fit, strongly favor using it.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 250.0;
        }

        // Penalize creating large dead space that few future items can use
        // (residuals below the minimum item size are pure waste).
        if post_residual < 10 && post_residual > 0 {
            score += 80.0;
        }

        // Late in the stream, prefer closing bins tightly (waste matters more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += tightness * 50.0 * progress;

        // With many open bins, prefer placements that reduce fragmentation.
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate: neutral-ish baseline; only prefer opening a new bin
    // when no open bin offers a decent fit (handled by the penalties above).
    if bin_residual == bin_capacity {
        score = 150.0 + (post_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items
    // (items are >= 1, but small slivers below a typical item are wasted).
    if post_residual > 0 {
        let sliver = (post_residual as f64 / bin_capacity as f64).powf(2.5);
        score += 25.0 * sliver;
    }

    // Perfect or near-perfect fill gets strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 35.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * pair_quality;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover can't host the next item: mild penalty scaled by wasted fraction.
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: this is the only bin that fits — strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; slightly cheaper when many bins are already open
        // (fragmentation control) or early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 20.0 + 15.0 * (1.0 - progress);
        // If many open bins with high mean residual, discourage adding another.
        new_bin_cost += 3.0 * (open_bins_count as f64).sqrt();
        if mean_residual > 30.0 {
            new_bin_cost += (mean_residual - 30.0) * 0.4;
        }
        score += new_bin_cost;
    }

    // Global fragmentation pressure: when mean residual is small, squeezing items
    // into existing bins is valuable.
    score -= (mean_residual / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: tight fits favored (small post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (dead space penalized quadratically);
    // later, dead space is more acceptable so coupling softens.
    let coupling = 1.0 + 2.0 * (1.0 - progress).powi(2);
    score += coupling * 40.0 * pr_norm * pr_norm;

    // Reward using an existing bin over opening a new one (new-bin candidate has
    // bin_residual == bin_capacity, so post_residual is large; the quadratic term
    // above already penalizes it, add explicit bonus for open bins).
    score -= 8.0;

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits perfectly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let diff = (pr as u32 as i64 - next_item_size as i64).abs() as f64;
        let fit_quality = 1.0 - (diff / cap).min(1.0);
        score -= 12.0 * fit_quality * fit_quality;
    }

    // Slight penalty for leaving residual far from mean residual (fragmentation shaping).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + 0.5 * progress);

    // Small reward for large items consuming big chunks (fit_ratio coupling).
    score -= 6.0 * fit_ratio * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post_residual non-linearly.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    }

    // Harmonic class of post_residual: multiples of common item sizes (10..=80
    // stream, but interface allows 1..=100) leave re-usable gaps.
    let pr = post_residual;
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0; // round residual is likely reusable by future items
    } else if pr < 10 {
        score += (10 - pr) as f64 * 1.5; // tiny dead space: nearly unusable
    }

    // Lookahead coupling: does the next item fit the post residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 0.15; // next item fits here
        } else {
            // next item cannot use this residual: dead-space penalty grows
            let gap = next_item_size - pr;
            score += gap as f64 * 0.25;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all too fragmented (mean residual small relative to item).
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual >= item_size as f64 {
            score += 20.0; // an existing bin should have handled it
        }
        // Early in the stream, be more willing to open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Spread load when many bins are open with large mean residual.
    if open_bins_count > 0 {
        let tightness = (mean_residual - post_residual as f64).abs();
        score += tightness * 0.05;
    }

    // Modulo harmony: item/bin_capacity fraction classes.
    let frac = (item_size * 100 / bin_capacity) as f64 / 100.0;
    if (frac * 4.0).round() as u32 * 25 == item_size {
        score -= 2.0; // item is a clean quarter-fraction of capacity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that could still fit a typical small item.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if post-residual is a dead gap that cannot hold the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 10.0 + open_bins_count as f64 * 3.0;
    } else {
        score -= open_bins_count.min(20) as f64 * 0.5;
    }

    // Prefer bins with residual below the mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, allow more flexibility; later, be stricter about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // 2-step lookahead: reward if the next item exactly fills the post_residual,
    // or nearly fills it (small leftover after next item too).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: bin closed by next item
        } else if next_item_size < post_residual {
            let two_step_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
            if two_step_left < 10 {
                score -= 15.0; // near-perfect two-step chain
            }
        } else {
            // next item won't fit here: post_residual likely dead space
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste;
        }
    }

    // Penalize creating small unusable slivers that no plausible item (>=1) fits well
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead-space sliver
    }

    // Compare against mean residual: placing into a bin with residual far below
    // mean means we're using the fullest useful bin - good (best-fit flavor).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): discourage unless current fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin costs a fresh bin; only attractive if item is large
        // relative to what open bins can absorb, or many bins already open.
        score += 55.0;
        score -= 0.5 * item_size as f64; // large items start fresh bins more readily
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // room for the next item in a fresh bin: pairing potential
            score -= 20.0 * (1.0 - (item_size + next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Early in the stream: be slightly more willing to consolidate (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if next_item_size <= post_residual + 10 {
            score += 4.0; // near-miss: mild penalty
        }
        // If next item would exactly fill this bin later, slight bonus.
        if post_residual > 0 && next_item_size == post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> discourage
    // opening new bins / spreading waste; encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score -= 3.0 * pressure * (0.5 + progress);

    // New-bin candidate handling: empty bin has post_residual == capacity - item.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless existing fit is bad or item is large.
        let bad_fit = post_residual as f64 > 0.55 * bin_capacity as f64
            && fitting_bins_count > 1;
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if bad_fit || big_item {
            score -= 8.0 + 6.0 * progress;
        } else {
            score += 14.0 + 10.0 * (1.0 - progress);
        }
    }

    // Time-horizon modulation: early stream favors consolidation,
    // late stream favors simply closing gaps.
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Small residual bonus: bins nearly full are good targets.
    if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: reward tight fits via strongly non-linear penalty on wasted space.
    let mut score = pr_norm.powf(1.7) * 10.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer leaving flexible space; late, pack tightly.
    let flex = pr_norm * (1.0 - progress) * (1.0 - progress);
    let tight = pr_norm * pr_norm * progress;
    score += 6.0 * flex - 4.0 * tight;

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic mismatch).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 8.0 * gap * gap;
        // Reward residuals that exactly-ish fit the next item (smooth bell).
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap).powi(2);
        score -= 3.0 * fit_quality.max(0.0) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins (smooth in count).
    score += 0.15 * (open_bins_count as f64).powf(1.3);

    // Align with mean residual state: bins far from mean residual are
    // mildly penalized (smooth quadratic), encouraging uniform packing.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: make it attractive only when current fits are bad.
    if bin_residual == bin_capacity {
        score = 12.0 + 20.0 * (1.0 - progress) - 2.0 * (fitting_bins_count as f64);
        if next_item_size > 0 {
            score -= 0.02 * next_item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "usable" vs "dead" classes.
    let r = post_residual % 10;
    let residue_penalty = match r {
        0 => -6.0,                 // perfectly reusable class
        1 | 9 => -3.0,
        2 | 8 => -1.5,
        5 => 0.5,
        3 | 7 => 1.0,
        _ => 2.5,                  // 4|6: awkward class
    };
    score += residue_penalty;

    // Integer-division thresholds: tiny unusable post-residual is dead space.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling with lookahead: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward, scaled by how tight the fit is
            let slack = post_residual - next_item_size;
            score -= 8.0 + (slack as f64).min(20.0) * 0.15;
            // harmonic bonus if post_residual is a near-multiple of next_item_size
            if post_residual % next_item_size.max(1) <= 3 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize slightly more for larger next item
            score += 2.0 + (next_item_size as f64) * 0.05;
        }
    } else {
        // last item: prefer exact/tight fill
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the item is huge relative to capacity and mean residuals are small,
        // opening fresh is less bad
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        if mean_residual < (item_size as f64) * 0.5 && fitting_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Progression: early in stream, be conservative with open bins; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;
    score += open_bins_count as f64 * 0.3;

    // Deviation from mean residual: bins far below mean are "almost full", prefer them.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to host the smallest
    // plausible future item are "dead" — penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 70.0;
        } else {
            score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't host the lookahead item: penalize proportionally.
        score += 15.0 * (next_item_size - post_residual) as f64 / 100.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 30.0 + pressure * 10.0;
        // If no open bin can fit, opening is necessary — soften the penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Mild reward for consolidating into bins with larger residual.
        score -= 5.0 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0) / 20.0;
    }

    // Late in the stream, prefer packing tighter (less chance to fix waste later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fits (post_residual small relative to item).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = (post_residual as f64) - next;
            // Perfect chain (next item exactly fills remainder) is excellent.
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Post-residual cannot host next item: penalize proportionally to wasted chain potential.
            score += 4.0 * (next - post_residual as f64) / 100.0;
        }
    }

    // Penalize residuals far below mean_residual (fragmentation vs. fleet).
    score += 1.5 * (mean_residual - post_residual as f64).max(0.0) / 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it slightly unattractive unless residual is huge
    // (i.e., current bins would leave very fragmented space).
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if the next item is large and current post_residual is awkward, new bin gains appeal.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 12.0;

    // Lookahead: reward if next item fits into post_residual (good chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward for near-perfect two-item packing.
        if post_residual - next_item_size <= 5 {
            score -= 10.0;
        }
    }
    // Penalize if next item would waste this bin's leftover.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or mean residual is too small for the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 40.0;
        // Discourage opening bins when existing mean residual can absorb the item.
        if mean_residual >= item_size as f64 {
            new_bin_score += 30.0;
        }
        // Encourage fresh bins late in the stream less (less time to fill them).
        new_bin_score += progress * 20.0;
        // If many bins open, opening more fragments capacity.
        new_bin_score += (open_bins_count as f64) * 1.5;
        // If no open bin fits (fitting_bins_count==0 means only new bin), allow it.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score += new_bin_score;
    }

    // Mild preference for filling bins that are already partly used.
    if bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let residual_norm = post / cap;

    // Base: prefer filling bins tightly (low post_residual).
    let mut score = post;

    // Non-linear polynomial coupling with stream progress:
    // late in the stream, dead space matters more; early, waste is cheaper.
    let dead_space_weight = 1.0 + 2.0 * progress * progress;
    score += dead_space_weight * (residual_norm * residual_norm) * cap * 0.5;

    // Penalize unusable slivers (post_residual too small for any realistic item 1..100).
    let sliver = (1.0 - residual_norm * 2.0).max(0.0);
    score += 30.0 * sliver * sliver * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead coupling: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 25.0 * (-gap / 20.0) * (1.0 - progress);
        // Penalize leaving space that neither fits next item nor is small.
        if post < next_item_size as f64 && post > 0.0 {
            score += 10.0 * (1.0 - post / cap);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (many bins, high mean residual spread).
    if bin_residual == bin_capacity {
        let poor_alternatives = (open_bins_count as f64) * (mean_residual / cap);
        let new_bin_bonus = 40.0 + 60.0 * progress - 0.5 * poor_alternatives;
        score += new_bin_bonus;
        // If no open bin fits, new bin must win outright.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // Mild penalty for spreading across many bins when mean residual is low.
        score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 / 25 create "dead zone" classes.
    let pr = post_residual;
    let res_class = pr % 10;
    // Penalize small nonzero residuals (unusable dead space), especially residues 1..=5
    if pr > 0 {
        if res_class >= 1 && res_class <= 5 {
            score += (6 - res_class) as f64 * 4.0;
        } else {
            score -= res_class as f64 * 0.5;
        }
    } else {
        score -= 30.0; // perfect fit reward
    }

    // Integer-division thresholds on post_residual
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr == 0 { score -= 20.0; }
    else if pr <= quarter { score += 5.0; }
    else if pr <= half { score -= 3.0; }

    // Lookahead: reward leaving room for next item exactly
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0; // next item fills this bin perfectly
        } else if pr > next_item_size && pr - next_item_size <= 5 {
            score -= 15.0; // near-perfect chain
        } else if pr > next_item_size {
            let rem = pr - next_item_size;
            let rc = rem % 10;
            if rc >= 1 && rc <= 5 { score += (6 - rc) as f64 * 2.0; }
        } else {
            score += 10.0; // next item can't use leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0;
        if open_bins_count == 0 { score -= 50.0; }
        // if mean residual across open bins is too small to be useful, allow new bin
        if mean_residual < item_size as f64 * 0.5 { score -= 15.0; }
    } else {
        // Tighter fits (small post_residual fraction) get harmonic discount
        let frac = post_residual as f64 / cap;
        score -= (1.0 - frac) * 10.0;
    }

    // Stream progression: early on, be conservative about fragmenting bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && pr > half {
        score += 4.0; // late stream: avoid leaving large residuals scattered
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - post_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold the
    // smallest plausible item are pure waste — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero or exactly reusable).
    if post_residual == 0 {
        score -= 80.0; // perfect fill
    } else if post_residual >= 10 {
        // usable leftover: mild reward proportional to how standard it is
        score -= 10.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading,
    // prefer filling existing bins over opening new ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open pressure so it only wins
        // when all existing bins are bad fits (their dead-space penalties dominate).
        score += open_pressure + 40.0;
    } else {
        score -= open_pressure * 0.25;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward heavily; if next item cannot fit in post_residual but the residual
    // is small, mild penalty for stranding.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is below average
    // (smaller gaps get filled first, keeping large gaps flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Late-stream consolidation: as the stream progresses, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core waste measure
    score = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward residuals that will be filled by next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // next item perfectly consumes remainder
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-slack / 20.0).exp(); // decaying lookahead bonus
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap; // residual too small for next item -> dead space risk
        }
    }

    // Penalize residuals that are unusable for typical items (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver is dead space
    }

    // Tightness bonus relative to mean residual
    let tightness = mean_residual - post_residual as f64;
    score += 0.3 * tightness; // prefer bins with less residual than average

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 }
            else if post_residual as f64 > mean_residual { 0.5 } else { 0.0 };
        score = bin_capacity as f64 - 30.0 * poor_fit + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large item stream: fresh bin useful
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
