pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: quadratic waste penalty (dead space grows quadratically worse)
    let mut score = norm_post * norm_post * cap;

    // Smooth coupling: waste matters more later in the stream
    score *= 1.0 + 1.5 * progress;

    // Reward tight fits: small post_residual relative to bin residual
    let tightness = if resid > 0.0 { 1.0 - post / resid } else { 0.0 };
    score -= 12.0 * tightness * tightness;

    // Penalize bins whose remaining residual deviates from mean (fragmentation)
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // smooth penalty if next item barely doesn't fit
        let gap = (next_item_size as f64 - post) / cap;
        score += 10.0 * gap * gap * cap;
    }

    // New-bin candidate: neutral score, slightly penalized early, acceptable when
    // open bins would leave huge waste
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 5.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let class = post_residual % 25; // residual classes: 0,10,15,20,... structure
    match class {
        0 => score -= 12.0,            // perfectly harmonized residual (25/50/75)
        10 => score -= 8.0,
        15 => score -= 6.0,
        20 => score -= 4.0,
        5 => score += 10.0,            // awkward sliver class
        _ => {}
    }

    // Integer-division thresholds: reward residuals that could fit common size bands
    let q = post_residual / 10;
    if q >= 1 && q <= 8 {
        score -= q as f64 * 0.5;
    }

    // Lookahead coupling: if next item fits the post residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.05;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that blocks the next item: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64) * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow opening when item is large and no bin fits well
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 40.0;
        }
        if post_residual < 20 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild preference for tight fits overall
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Progress-aware damping of open-bin count pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.02;

    // Nudge toward bins near mean residual (balance load)
    score += (bin_residual as f64 - mean_residual).abs() * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    let min_item = 1.0f64;
    let dead = if post_residual > 0 && (post_residual as f64) < min_item {
        1000.0
    } else {
        0.0
    };
    score += dead;

    // Penalize small unusable gaps super-linearly: residuals in (0, 10) are near-wasted,
    // residuals in [10, 30) are partially wasted.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 4.0;
    } else if pr >= 10.0 && pr < 30.0 {
        score += (30.0 - pr) * 0.6;
    }

    // Reward perfect or near-perfect fills.
    if pr == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual closely matches the next item (lookahead chaining).
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Slight preference for bins with residuals near mean (keeps bin population homogeneous).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    // New-bin candidate: make it moderately attractive only when the item fits poorly everywhere
    // (large post_residual in existing bins) or too many tight squeezes would be created.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral-ish, scaled by open bins pressure.
        score = item_size as f64 * 0.5 + pressure * 0.4;
        // Opening a new bin is good if this item would leave a large dead gap in any existing bin.
        if pr > 0.0 && pr < item_size as f64 * 0.25 {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheap.
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // If the next item cannot fit in the leftover space, penalize dead space
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
    }

    // If the next item fits comfortably, mildly reward leaving room
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 0.15 * slack;
    }

    // Penalize bins that are far below mean residual (poor consolidation)
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Reward filling bins tightly (small post_residual relative to capacity)
    score += 0.2 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for consolidating into fewer bins when many are open
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    // New-bin candidate: make it moderately unattractive so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to how much of the bin is used.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * bin_capacity as f64 * 0.6;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Dead space penalty: small post_residual that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits in the post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            // post_residual too small for next item; penalize proportionally
            let gap = next_item_size - post_residual as u32;
            score += (gap as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make opening a new bin unattractive unless current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If item fits poorly anywhere (large post_residual elsewhere), new bin is fine.
        // Scale with how many open bins already exist (encourage consolidation early).
        score += (open_bins_count as f64).min(20.0) * 0.5;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Global residual pressure: if mean residual is low, conserve space by tight fits.
    if mean_residual > 0.0 {
        let tightness = item_size as f64 / mean_residual;
        score -= tightness * 5.0;
    }

    // Mild time-horizon modulation: early stream, be more exploratory with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 {
        score -= 3.0; // slight exploration bonus early
    }

    // Small deterministic tie-breaker favoring bins with larger residual (more flexible leftovers).
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let sz = item_size as f64;

    // Base: quadratic penalty on post_residual (waste), scaled by stream progress
    let mut score = pr * (1.0 + 0.9 * progress) + 0.004 * pr * pr;

    // Reward tight fits: smooth coupling of post_residual with item size
    let fit_ratio = sz / cap;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - pr / cap);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a bin, more so early and
    // when open bins exist; relax when the item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = (pr as f64 / cap).max(0.0); // for new bin, pr = cap
        let _ = poor_fit;
        score += 30.0 * (1.0 - 0.5 * progress) + 2.0 * (open_bins_count as f64);
        // If next item is large relative to this one, a fresh bin is more useful
        let nx = next_item_size as f64;
        if nx > 0.0 {
            score -= 10.0 * (nx / cap) * (1.0 - fit_ratio);
        }
        // Late in stream, prefer consolidating; early, fresh bins OK
        score -= 15.0 * progress * (1.0 - fit_ratio);
    } else {
        // Reward using an existing bin, especially when it leaves room for next item
        let nx = next_item_size as f64;
        if nx > 0.0 && pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).abs());
        } else if nx > 0.0 {
            // placing here blocks the next item less than leaving a bad residual
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mild smoothing interaction: progress-weighted residual curvature
    score += 2.0 * progress * (pr / cap) * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Harmonic class of post_residual: dead space in (0,10] is worst
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is excellent
    } else if pr < 10 {
        score += 25.0; // tiny unusable sliver
    } else if pr % 10 == 0 {
        score -= 8.0; // round residual, likely reusable
    } else if pr % 5 == 0 {
        score -= 4.0;
    }

    // Harmonic class of item size relative to capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if item_size > half {
        // big item: better in a fresh-ish bin
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    } else if item_size <= quarter {
        score += 3.0; // small items should fill leftovers
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let nxt_fit = (next_item_size as f64 / pr as f64).min(1.0);
            score -= 12.0 * nxt_fit;
        } else {
            // next item won't fit here; penalize wasting a fitting slot
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer using existing bins over opening new ones
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless it enables a much better future fit
        score += 15.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for pairing with next item
        }
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Early stream: slightly favor consolidation into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward gap" zone: residual that fits almost nothing else.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward small post_residual proportionally to item size (dense packing).
        score -= (item_size as f64) * (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 1.5;
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // strongly favor this placement (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64) * 0.4;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Next item won't fit anywhere anyway; tightness matters less.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer reusing.
    score += (open_bins_count as f64) * 0.8;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is the "dirtiest" bin — prefer filling it to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    }

    // New-bin candidate handling: only open a new bin when it is genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progression
        // (late in the stream, opening bins is riskier) and open-bin count.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + 30.0 * progress + (open_bins_count as f64) * 2.0;
        // A new bin is attractive if the item is huge and no tight fit exists elsewhere.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // 2-step lookahead: reward if next item exactly fits the post residual
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 500.0;
            } else if post_residual >= next_item_size {
                // next item fits after this placement: mild reward proportional to tightness
                let slack = (post_residual - next_item_size) as f64;
                score -= 200.0 - slack * 0.5;
            } else {
                // dead space relative to next item: penalize small unusable leftovers
                let waste = (next_item_size - post_residual) as f64;
                score += waste * 0.8;
            }
        }
        // Penalize tiny unusable residuals that no small item could use
        if post_residual < 10 {
            score += 150.0;
        }
    }

    // Tightness of current fit relative to mean residual
    let tightness = mean_residual - post_residual as f64;
    score -= tightness * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when
    // open bins have poor fits; discourage early in the stream or with few bins
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 50.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: must open new bin
        }
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 100.0; // an open bin could take it decently
        }
        // late in stream, prefer reusing bins to avoid many nearly-empty bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild penalty for proliferating bins
    score += open_bins_count as f64 * 0.5;

    score
}
